\section{Bayesian Least Squares Estimation}
\label{app:bls}
Assume \((x, y) \sim P(x, y)\), and let \(g(x)\) be a target function. To estimate \(g(x)\) from observations \(y\), we consider minimizing the mean squared error:
\[
\mathcal{L}(f) = \mathbb{E}_{P(x, y)} \left[ (f(y) - g(x))^2 \right].
\]
The minimizer of this loss is the Bayes least squares estimator:
\[
f^*(y) = \mathbb{E}_{P(x \mid y)} [g(x)].
\]
This follows from the decomposition:
\[
\begin{aligned}
\mathcal{L}(f)
&= \mathbb{E}_{P(y)} \left[ \mathbb{E}_{P(x \mid y)} \left[ (f(y) - g(x))^2 \right] \right] \\
&= \mathbb{E}_{P(y)} \left[ \left(f(y) - \mathbb{E}_{P(x \mid y)}[g(x)] \right)^2 + \operatorname{Var}_{P(x \mid y)}[g(x)] \right],
\end{aligned}
\]
where \(\operatorname{Var}_{P(x \mid y)}[g(x)] = \mathbb{E}_{P(x \mid y)}\left[(g(x) - \mathbb{E}_{P(x \mid y)}[g(x)])^2\right]\) is independent of \(f\). Thus, the optimal estimator matches the conditional mean.


\section{Error Analysis for Indecomposable Models with Additive Noise}
\label{app:add_nosie}
When a natural latent variable is unavailable, we introduce an auxiliary variable \(\tilde{\theta}\) and define a latent model \(P(\theta \mid \tilde{\theta})\). In this case, our method estimates the Fisher score of the extended model, \(\nabla_{\tilde{\theta}} \log P(x \mid \tilde{\theta})\), rather than the original model.

Assume an additive noise model:
\[
\theta = \tilde{\theta} + w, \quad \text{where } w \sim p(w).
\]
Then the marginal likelihood under the extended model is:
\[
P(x \mid \tilde{\theta}) = \int P(x \mid \theta) \, p(\theta \mid \tilde{\theta}) \, d\theta = \int P(x \mid \tilde{\theta} + w) \, p(w) \, dw.
\]
Taking the gradient with respect to \(\tilde{\theta}\), we have:
\[
\begin{aligned}
\nabla_{\tilde{\theta}} P(x \mid \tilde{\theta}) 
&= \int \nabla_{\tilde{\theta}} P(x \mid \tilde{\theta} + w) \, p(w) \, dw \\
&= \int \nabla_{\tilde{\theta}} \log P(x \mid \tilde{\theta} + w) \, P(x \mid \tilde{\theta} + w) \, p(w) \, dw.
\end{aligned}
\]
Using the definition of the Fisher score, we obtain:
\[
\nabla_{\tilde{\theta}} \log P(x \mid \tilde{\theta}) 
= \frac{\nabla_{\tilde{\theta}} P(x \mid \tilde{\theta})}{P(x \mid \tilde{\theta})}
= \int \nabla_{\tilde{\theta}} \log P(x \mid \tilde{\theta} + w) \, \frac{P(x \mid \tilde{\theta} + w) \, p(w)}{P(x \mid \tilde{\theta})} \, dw.
\]
Substituting \(\theta = \tilde{\theta} + w\), and applying Bayes' theorem, we rewrite the integrand as 
\[
\nabla_{\tilde{\theta}} \log P(x \mid \tilde{\theta}) 
= \int \nabla_{\theta} \log P(x \mid \theta) \, P(\theta \mid \tilde{\theta}, x) \, d\theta.
\]

This result shows that the estimated score is a smoothed version of the true score \(\nabla_{\theta} \log P(x \mid \theta)\). The accuracy of this approximation depends on the sharpness of \(P(\theta \mid \tilde{\theta})\), which bounds the sharpness of $P(\theta \mid \tilde{\theta}, x) $. When it is highly concentrated (e.g., close to a delta function), the smoothed score approaches the true Fisher score.

\section{Fisher Score Matching Algorithms}
\label{app:alg}
\noindent
\begin{minipage}[t]{0.48\linewidth}
\begin{algorithm}[H]
   \caption{FSM for Decomposable Model}
   \label{alg:decomposable}
\begin{algorithmic}
   \STATE {\bfseries Input:} Simulator $x \mid \theta \sim \int p(x \mid \theta^*)p(\theta^* \mid \theta)d\theta^*$, model $s(x, \theta)$, proposal $p(\theta)$
   \WHILE{not converged}
       \STATE Sample batch: $(\theta, \theta^*, x) \sim p(\theta)p(\theta^* \mid \theta)p(x \mid \theta^*)$
       \STATE Compute target: $\nabla_{\theta} \log p(\theta^* \mid \theta)$
       \STATE Predict score: $\hat{s} = s(x, \theta)$
       \STATE Compute loss: $L = \|\hat{s} - \text{target}\|^2$
       \STATE Update model parameters using $\nabla L$
   \ENDWHILE
   \STATE {\bfseries Output:} Trained estimator $s(x, \theta)\approx \nabla_{\theta} \log p(x \mid \theta)$
\end{algorithmic}
\end{algorithm}
\end{minipage}
\hfill
\begin{minipage}[t]{0.48\linewidth}
\begin{algorithm}[H]
   \caption{FSM for Indecomposable Model}
   \label{alg:indecomposable}
\begin{algorithmic}
   \STATE {\bfseries Input:} Simulator $x \mid \theta \sim p(x \mid \theta)$, model $s(x, \tilde{\theta})$, proposal $p(\tilde{\theta})$, conditional $p(\theta \mid \tilde{\theta})$
   \WHILE{not converged}
       \STATE Sample batch: $(\tilde{\theta}, \theta, x) \sim p(\tilde{\theta})p(\theta \mid \tilde{\theta})p(x \mid \theta)$
       \STATE Compute target: $\nabla_{\tilde{\theta}} \log p(\theta \mid \tilde{\theta})$
       \STATE Predict score: $\hat{s} = s(x, \tilde{\theta})$
       \STATE Compute loss: $L = \|\hat{s} - \text{target}\|^2$
       \STATE Update model parameters using $\nabla L$
   \ENDWHILE
   \STATE {\bfseries Output:} Trained estimator $s(x, \tilde{\theta})\approx \nabla_{\theta} \log p(x \mid \tilde{\theta})$
\end{algorithmic}
\end{algorithm}
\end{minipage}





\section{Network Details}
\label{app:network}
For the Gaussian model, we use a multilayer perceptron (MLP) with two hidden layers of 64 units each, followed by ELU activation. The network is trained with a learning rate of 1e-2 for 1000 epochs. For the Weak Lensing example, we use an MLP with hidden layers of sizes 64, 128, and 128, also followed by ELU activation. The network is trained with a learning rate of 1e-3 for 10,000 epochs.

