\begin{remark}{}{}
  For simplicity, we use the notation $r_{i_1\dots i_k}$ to denote $r_{i_1}+\dots+r_{i_k}$. 
  Under this notation, the weak triangle inequality can be rewritten as follows:
  Let $r_1>0, r_2>0$, $r_3>0$. 
  If $d_{r_{12}}(x, y)<r_3$ and $d_{r_{123}}(y, z)<r_2$, then 
  $d_{r_1}(x, z)\leq d_{r_{12}}(x, y)+d_{r_{123}}(y, z)$.
\end{remark}

\begin{defi} \label{definition neighborhoods of topology}
  Let $(X, \{d_r\}_{r>0})$ satisfy the axioms in \defref{definition axioms of dr}.
  For a given $x\in X$, $r>0$, $\varepsilon>0$, we define the neighborhood
  \[
      \nhddr{r}{\varepsilon}{x}=\{y\in X\mid d_r(x, y)<\varepsilon\}.
  \]
\end{defi}

% Here, notice that $\{d_r\}_{r>0}$ may not be symmetric. By this reason, the order of the variants in the definition of these neighborhoods is important. 
It is important to note that $d_r$ is not necessarily symmetric. Consequently, the order of the arguments in this definition must be carefully considered.
% Also, note that we always have $x\in\nhddr{r}{\varepsilon}{x}$. 
Moreover, observe that $x\in\nhddr{r}{\varepsilon}{x}$ always holds. 

The following proposition and its proof are identical to those given in \metricemb.

\begin{prop}[\metricemb, Lemma 4.3] \label{proposition basis of topology}
    Let $(X, \{d_r\}_{r>0})$ satisfy the axioms in \defref{definition axioms of dr}. Suppose $x\in X$, and let $r>0$ and $\varepsilon>0$. 
    % Let $X$ be a set equipped with the family of Let $x\in X$ be an element. 
    If $y\in \nhddr{r}{\varepsilon}{x}$, then there exist $r'>0$ and $\varepsilon'>0$ such that 
    \[
        \nhddr{r'}{\varepsilon'}{y}\subset \nhddr{r}{\varepsilon}{x}. 
    \]
    In particular, the collection of sets $\nhddr{r}{\varepsilon}{x}$ forms a basis for a topology on X. 
    % In particular, if $y\in \nhddr{r}{\varepsilon}{x}$, then there exists $r'>0$ and $\varepsilon'>0$ such that 
    % \[
    %     \nhddr{r'}{\varepsilon'}{y}\subset \nhddr{r}{\varepsilon}{x}. 
    % \]
\end{prop}

\begin{proof}
% It is enough to show that if $y\in \nhddr{r}{\varepsilon}{x}$, then there exists $r'>0$ and $\varepsilon'>0$ such that 
% \[
%     \nhddr{r'}{\varepsilon'}{y}\subset \nhddr{r}{\varepsilon}{x}. 
% \]
By the axioms of $\{d_r\}_{r>0}$, there exist $\delta>0$ and $\varepsilon_1>0$ such that $d_{r+\delta}(x, y)<\varepsilon-\varepsilon_1$. 
With these values of $\delta$ and $\varepsilon_1$, if we set $\varepsilon'=\min\{\delta, \varepsilon_1\}$ and $r'=r+\delta+\varepsilon-\varepsilon_1$, then the inclusion above holds. 
To prove the inclusion, let $z\in\nhddr{r'}{\varepsilon'}{y}$ be any element. Since $d_{r+\delta}(x,y)<\varepsilon-\varepsilon_1$ and $d_{r'}(y, z)<\varepsilon'\leq \delta$, we have
\[
    d_r(x, z)\leq d_{r+\delta}(x,y)+d_{r'}(y, z)\leq \varepsilon-\varepsilon_1+\varepsilon'\leq \varepsilon
\]
by the weak triangle inequality. Thus, $z\in \nhddr{r}{\varepsilon}{x}$. 
\end{proof}

\begin{cor} \label{corollary upper semiconti}
    Let $(X, \{d_r\}_{r>0})$ satisfy the axioms in \defref{definition axioms of dr}. 
    For any $x\in X$ and $r>0$, the function
    \[
        d_r(x, \cdot)\colon X\to \mathbb{R};y\mapsto d_r(x, y)
    \]
    %  $d_r(x, \cdot)\colon X\to \mathbb{R};y\mapsto d_r(x, y)$ 
     is upper semi-continuous. 
\end{cor}

\begin{proof}
% Let $U\subset \mathbb{R}$ be any open interval of the form $(-\infty, b)$, and let $y\in d_r(x, \cdot)^{-1}(U)$ be any element. 
% Since $d_r(x,y)<b$, there exists $\varepsilon>0$ such that $d_r(x,y)+\varepsilon<b$. 
% By the Upper semi-continuity axiom of $\{d_r\}_{r>0}$, there exists $\delta>0$ such that $d_{r+\delta}(x,y)<b-\varepsilon$. 
% We define $\varepsilon'=\min\{\varepsilon,\delta\}$. Then we have $\nhddr{r}{\varepsilon'}{y}\subset d_r(x,\cdot)^{-1}(U)$. 
