% Then, by the weak triangle inequality axiom, we have
% \[
%     d_r(x,z)\leq d_r
% \]
Let $U\subset \mathbb{R}$ be any open interval of the form $(-\infty, b)$, and let $y\in d_r(x, \cdot)^{-1}(U)=\nhddr{r}{b}{x}$ be any element. 
By the \proref{proposition basis of topology}, there exist $r'>0$ and $\varepsilon>0$ such that 
\[
    \nhddr{r'}{\varepsilon}{y}\subset \nhddr{r}{b}{x}. 
\]
% This implies the upper semi-continuity of $d_r(x, \cdot)\colon X\to \mathbb{R}$. 
This implies that $d_r(x, \cdot)\colon X \to \mathbb{R}$ is upper semi-continuous.

\end{proof}

We now present some examples of spaces defined by $\{d_r\}_{r>0}$. 
In the first example, the family $\{d_r\}_{r>0}$ satisfies not only the weak triangle inequality but also the standard triangle inequality. Thus, this example may not be particularly surprising. 
However, it illustrates that spaces defined by $\{d_r\}_{r>0}$ can be viewed as generalizations of the compact-open topology.

\begin{ex} \label{example mapping space}
%   Let $T$ and $S$ be two metric spaces, and let $X=\mappingsp{T}{S}$. Take a point $t_0$ of $T$ and we write $\closedball{r}=\{t\in T\mid d_T(t_0, t)\leq r\}$ for each $r>0$. 
Let $(T, d_T)$ be a proper metric space, i.e., a metric space where every closed ball is compact. Let $(S, d_S)$ be another metric space, 
