\begin{proof}
Let $K\subset T$ be an arbitrary compact subset, and let $U\subset S$ be an arbitrary open subset. Consider an element $f\in \cptopen{K}{U}=\{g\colon T\to S\mid g(K)\subset U\}$. 
Since $K$ is compact, we can choose $r>0$ such that $K\subset \closedball{r}$. 
For each $x\in K$, there exists $\varepsilon_x>0$ such that $\openball{\varepsilon_x}{f(x)}\subset U$. 
By compactness of $K$, we can choose a finite set $\{x_1,\dots, x_n\}\subset K$ such that
\[
    K\subset \bigcup_{i=1}^n f^{-1}(\openball{\varepsilon_{x_i}/2}{f(x_i)}).
\]
Define $\varepsilon=\min\{\varepsilon_{x_i}/2\mid i=1,\dots, n\}$. Then, $\nhddr{r}{\varepsilon}{f}\subset \cptopen{K}{U}$. 

% To prove the inclusion, let $g\in \nhddr{r}{\varepsilon}{f}$ and take any $x\in K$. 
To prove the inclusion, let $g\in \nhddr{r}{\varepsilon}{f}$ and $x\in K$ be arbitrary. 
% Then, there exists $i$ such that $x\in f^{-1}(\openball{\varepsilon_{x_i}/2}{f(x_i)})$, which implies $d_S(f(x_i),f(x))<\varepsilon_{x_i}/2$. 
Since $x$ belongs to one of the preimages $f^{-1}(\openball{\varepsilon_{x_i}/2}{f(x_i)})$, we have
\[
  d_S(f(x_i),f(x))<\varepsilon_{x_i}/2. 
\]
Moreover, since $g\in \nhddr{r}{\varepsilon}{f}$, it follows that 
\[
    d_S(f(x), g(x))<\varepsilon\leq \varepsilon_{x_i}/2. 
\]
Thus, we conclude 
\[
    d_S(g(x), f(x_i))<\varepsilon_{x_i},
\]
which implies, $g(x)\in \openball{\varepsilon_{x_i}}{f(x_i)}\subset U$. 
Therefore, $\nhddr{r}{\varepsilon}{f}\subset \cptopen{K}{U}$. 

For the reverse inclusion, 
let $r>0$ and $\varepsilon>0$ be arbitrary, and consider $f\in \mappingsp{T}{S}$. 
For each $x\in \closedball{r}$, there exists $r_x>0$ such that $\openball{2r_x}{x}\subset f^{-1}(\openball{\varepsilon/2}{f(x)})$. 
% Since $T$ is proper, $\closedball{r}$ is compact. 
Since $\closedball{r}$ is compact (by the assumption that $T$ is proper), there exists a finite set $\{x_1,\dots, x_n\}\subset \closedball{r}$ such that 
% Thus, there exists a family of finite elements $x_1,\dots, x_n$ of $\closedball{r}$ such that
\[
    \closedball{r}\subset \bigcup_{i=1}^n \openball{r_{x_i}}{x_i}.
\]
For each $i=1,\dots, n$, define $W_i=\cptopen{\overline{\openball{r_{x_i}}{x_i}}}{\openball{\varepsilon/2}{f(x_i)}}$. Then, 
\[
    f\in \bigcap_{i=1}^n W_i\subset \nhddr{r}{\varepsilon}{f}.
\]
To prove the inclusion, let $g\in \bigcap_{i=1}^n W_i$ and $x\in \closedball{r}$. 
% Since there exists $i$ such that $x\in \openball{r_{x_i}}{x_i}$, which implies $g(x)\in \openball{\varepsilon/2}{f(x_i)}$. 
Since $x$ is contained in some $\openball{r_{x_i}}{x_i}$, we have $g(x)\in \openball{\varepsilon/2}{f(x_i)}$.
Moreover, since $\openball{r_{x_i}}{x_i}\subset f^{-1}(\openball{\varepsilon/2}{f(x_i)})$, we obtain $f(x)\in \openball{\varepsilon/2}{f(x_i)}$.
Thus, 
\[
    d_S(f(x), g(x))<\varepsilon
\]
for each $x\in \closedball{r}$. 
It follows that 
\[
    d_r(f,g)=\sup_{x\in \closedball{r}}d_S(f(x),g(x))=\max_{x\in \closedball{r}}d_S(f(x),g(x))<\varepsilon, 
\]
which shows that $g\in \nhddr{r}{\varepsilon}{f}$.
\end{proof}

