\section{Tiling spaces and \texorpdfstring{$d_r$}{dr}}
% \subsection{Tiling spaces and \texorpdfstring{$d_r$}{dr}}

% In this section, we see the definition of the tiling spaces and the relationship between the tiling spaces and the family $\{d_r\}_{r>0}$.
% In this section, we introduce the definition of tiling spaces and explore the relationship between tiling spaces and the family $\{d_r\}_{r>0}$. 
In this section, we recall the definition of tiling spaces and discuss the relationship between the tiling spaces and the family $\{d_r\}_{r>0}$. 
% To begin, we outline the general definition of a tiling space. 
For a more detailed treatment of tiling spaces, we refer the reader to the textbook \tilingtextbook~and the paper \tilinginvertlimit~by Anderson-Putnam. 

\begin{defi}[\tilingtextbook, \tilinginvertlimit, \tilingdflg] \label{definition tiling}
  Let $d\in \mathbb{Z}_{>0}$ be a positive integer. 
  A \textit{tiling} of $\mathbb{R}^d$ is a collection $T\subset \powerset{\mathbb{R}^d}$ that satisfies the following conditions:
  \begin{itemize}
    \item Each $t\in T$ is a translated copy of one of the \textit{prototiles}, where prototiles form a finite set $\prototile=\{\tau_1,\dots,\tau_n\}$ of subsets of $\mathbb{R}^d$. 
    % Each $t\in T$ is a translated copy of a finite set $\prototile=\{\tau_1,\dots,\tau_n\}\subset \powerset{\mathbb{R}^d}$, called prototiles. 
    \item Each $t\in T$ is homeomorphic to a closed $d$-disk.
    \item $\bigcup_{t\in T} t =\mathbb{R}^d$.
    \item For each $t_1, t_2\in T$ such that $t_1\neq t_2$, $\Int{t_1}\cap\Int{t_2}\neq \emptyset$. 
  \end{itemize}
  Let $T$ be a tiling of $\mathbb{R}^d$. For a subset $A\subset\mathbb{R}^d$, we define 
  \[
    T\cap A=\{t\in T\mid t\cap A\neq \emptyset\}.
  \]
\end{defi}


\begin{defi}[\tilingtextbook, \tilinginvertlimit, \tilingdflg] \label{definition tiling space}
  Let $T$ be a tiling of $\mathbb{R}^d$. For each $x\in \mathbb{R}^d$, we define the translated tiling as 
  \[
    T+x=\{t+x\mid t\in T\}. 
  \]
  We then define the orbit of $T$ under the translation action of $\mathbb{R}^d$ as
  \[
    \orbit{T}=\{T+x\mid x\in \mathbb{R}^d\}.
  \]
  For any two tilings $T, T'$, we define $d(T, T')$ as follows:
  \[
    % d(T,T')=\inf\{\varepsilon>0\mid \mbox{There exist $u, v\in \mathbb{R}^d$ such that $|u|<\varepsilon$, $|v|<\varepsilon$}\}
    d(T,T')=\inf\left(\left\{\varepsilon>0 \;\middle|
    \begin{array}{l}
        \mbox{There exist $u, v\in \mathbb{R}^d$ such that $|u|<\varepsilon$, $|v|<\varepsilon$,} \\
        \mbox{and $(T+u)\cap \openball{1/\varepsilon}{0}=(T'+v)\cap \openball{1/\varepsilon}{0}$}
    \end{array}
    \right\}\cup \{1/\sqrt{2}\}\right).
  \]
  This $d$ is easily verified to be a metric on $\orbit{T}$. 
  We define the \textit{tiling space} $\tilingsp{T}$ of $T$ as the metric completion of $\orbit{T}$ with respect to $d$.
\end{defi}

\begin{remark}{}{} \label{remark prototiles of tiling space}
   If $T$ is tiling with $\prototile=\{\tau_1,\dots,\tau_n\}$ as its set of prototiles, then any $T' \in \tilingsp{T}$ can be regarded as a tiling whose set of prototiles is a subset of $\prototile$.
%    This is because $T'$ is locally indistinguishable from $T$, meaning that every patch of $T'$ can still be found in $T$. Here, a patch refers to a finite and connected union of tiles. 
   This is because any limit of a Cauchy sequence in $\orbit{T}$ corresponds to a tiling in which every \textit{patch} appearing in $T'$ can also be found in $T$. 
   Here, a patch refers to a finite and connected union of tiles.
\end{remark}

\begin{prop} \label{proposition definition tiling dr}
    Let $T$ be a tiling of $\mathbb{R}^d$, and let $T_1$ and $T_2$ be two elements of $\tilingsp{T}$. 
    For each $r>0$, we define 
    \[
        % d_r(T_1, T_2)=\inf\{\varepsilon>0\mid \}
        d_r(T,T')=\inf\left\{\varepsilon>0 \;\middle|
        \begin{array}{l}
            \mbox{There exists $u\in \mathbb{R}^d$ such that $|u|<\varepsilon$,} \\
            \mbox{and $(T+u)\cap \closedball{r}=T'\cap \closedball{r}$}
        \end{array}
        \right\}.
    \]
    If there is no $u\in\mathbb{R}^d$ such that $(T_1+u)\cap \closedball{r}=T_2\cap \closedball{r}$, this number is understood to be $\infty$. 
    Then, this family $\{d_r\}_{r>0}$ satisfies the axioms in \defref{definition axioms of dr}. 
\end{prop}

\begin{proof}
    The self-distance axiom is easy. 

    We prove upper semi-continuity. 
    Since $r_1\leq r_2$ implies $d_{r_1}(T_1, T_2)\leq d_{r_2}(T_1, T_2)$ straightforwardly, we proceed to prove the second condition. 

    % Take any $r>0$, $T_1, T_2\in \tilingsp{T}$, and $\varepsilon>0$ such that $d_r(T_1, T_2)<\varepsilon$. 
    Let $r > 0$, $T_1, T_2 \in \tilingsp{T}$, and $\varepsilon > 0$ be arbitrary satisfying $d_r(T_1, T_2) < \varepsilon$. 
    Then, there exists $u\in \mathbb{R}^d$ such that $|u|<\varepsilon$, and $(T_1+u)\cap \closedball{r}=T_2\cap \closedball{r}$. 
    Since the set 
    \[
        % ((T_1+u)\cap (\closedball{r})^c)\cup (T_2\cap (\closedball{r})^c)
        \bigcup\{t\in (T_1+u)\cup T_2\mid t\cap \closedball{r}\neq \emptyset\}
    \]
    is closed, we can separate it from $\closedball{r}$ using the normality of $\mathbb{R}^d$. 
    Therefore, there exists $\delta>0$ such that $(T_1+u)\cap \closedball{(r+\delta)}=T_2\cap \closedball{(r+\delta)}$. 
    This implies $d_{r+\delta}(T_1, T_2)<\varepsilon$. 

    Finally, we prove the weak triangle inequality. 
    % Take any $T_1, T_2, T_3\in\tilingsp{T}$, and let $r_1, r_2, r_3 > 0$ satisfy 
    Let $T_1, T_2, T_3\in\tilingsp{T}$, and $r_1, r_2, r_3 > 0$ be arbitrary satisfying  
    $d_{r_{12}}(T_1, T_2) < r_3$, $d_{r_{123}}(T_2, T_3) < r_2$. 
    % Also, take any $d_1, d_2 > 0$ such that 
    Also, let $d_1, d_2 > 0$ be arbitrary satisfying 
    \[
        d_{r_{12}}(T_1, T_2)<d_1<r_3, \quad d_{r_{123}}(T_2, T_3)<d_2<r_2. 
    \] 
    It suffices to prove that $d_{r_1}(T_1, T_3)\leq d_1+d_2$. 
    First, there exist $u, v\in \mathbb{R}^d$ such that $|u|<d_1$, $|v|<d_2$, and 
    $(T_1+u)\cap \closedball{r_{12}}=T_2\cap \closedball{r_{12}}$, $(T_2+v)\cap \closedball{r_{123}}=T_2\cap \closedball{r_{123}}$. 
    % To prove $d_{r_1}(T_1, T_3)\leq d_1+d_2$, we first verify the following identity:
    Using these $u$ and $v$, we now verify the following identity to prove $d_{r_1}(T_1, T_3)\leq d_1+d_2$:
    \[
        (T_1+u+v)\cap \closedball{r_1}=T_3\cap \closedball{r_1}.
    \]
    Let $t_1+u+v\in (T_1+u+v)\cap \closedball{r_1}$ be a tile. Since $(t_1+u+v)\cap\closedball{r_1}\neq \emptyset$ and $|v|<d_2<r_2$, it follows that $(t_1+u)\cap \closedball{r_{12}}\neq \emptyset$. 
    Thus, there exists $t_2\in T_2\cap \closedball{r_{12}}$ such that $t_1+u=t_2$.
    Since $t_2+v=t_1+u+v\in (T_1+u+v)\cap \closedball{r_1}$, it follows that $(t_2+v)\cap \closedball{r_1}\neq \emptyset$, which in turn implies $(t_2+v)\cap \closedball{r_{123}}\neq \emptyset$. 
    Therefore, there exists $t_3\in T_3\cap \closedball{r_{123}}$ such that $t_2+v=t_3$. 
    Using this $t_3$, we obtain 
    \[
        t_1+u+v=t_3\in T_3\cap\closedball{r_1}, 
    \]
    which implies $(T_1+u+v)\cap \closedball{r_1}\subset T_3\cap \closedball{r_1}$. 

    Conversely, let $t_3\in T_3\cap \closedball{r_1}$ be a tile. 
    Since $(T_2+v)\cap\closedball{r_{123}}=T_3\cap \closedball{r_{123}}$, there exists $t_2\in T_2$ such that $t_2+v=t_3$. 
    From $t_2=t_3-v$, $|v|<d_2<r_2$, and $t_3\cap\closedball{r_1}\neq \emptyset$, it follows that $t_2\cap\closedball{r_{12}}\neq \emptyset$. 
    Therefore, there exists $t_1\in T_1$ such that $t_1+u=t_2$. 
    Using this $t_1$, we have 
    \[
        t_3=t_1+u+v\in (T_1+u+v)\cap\closedball{r_1}, 
    \]
    which implies $T_3\cap \closedball{r_1}\subset (T_1+u+v)\cap \closedball{r_1}$. 
    Thus, we conclude that $(T_1+u+v)\cap \closedball{r_1}=T_3\cap \closedball{r_1}$. 

    From this identity and the fact that $|u+v|<d_1+d_2$, it follows that $d_{r_1}(T_1, T_3)<d_1+d_2$. 
    Since $d_1$ and $d_2$ are arbitrary values satisfying $d_{r_{12}}(T_1, T_2)<d_1<r_3$ and $d_{r_{123}}(T_2, T_3)<d_2<r_2$, we conclude that $d_{r_1}(T_1, T_3)\leq d_{r_{12}}(T_1, T_2)+d_{r_{123}}(T_2, T_3)$.
\end{proof}

