Before proceeding, we provide a brief introduction to quasi-uniform spaces, which generalize uniform spaces by not necessarily requiring symmetry. 
For a more detailed treatment of uniform spaces, see \broubakione, Chapter II by Bourbaki, and for quasi-uniform spaces, see \quasiuniform~by Fletcher-Lindgren.


\begin{defi}[\broubakione, Chapter II, \quasiuniform, Chapter 1] \label{definition uniform space}
    Let $X$ be a set. A \textit{uniformity} on $X$ is a collection $\mathcal{U}$ of subsets of $X\times X$ (called \textit{entourages}) satisfying the following five axioms:
    \begin{itemize}
        \item If $U\in \mathcal{U}$ and $U\subset V\subset X\times X$, then $V\in \mathcal{U}$. 
        \item If $U, V\in \mathcal{U}$, then $U\cap V\in \mathcal{U}$. 
        \item If $U\in \mathcal{U}$, then $\Delta\subset U$, where $\Delta=\{(x,x)\in X\times X\mid x\in X\}$ is the diagonal. 
        \item If $U\in \mathcal{U}$, then there exists $V\in \mathcal{U}$ such that $V\circ V\subset U$, where for any two subsets $U, V\subset X\times X$, we define 
        \[
        U\circ V=\{(x,z)\mid \text{there exists $y\in X$ such that $(x,y)\in U$ and $(y,z)\in V$.}\}.
        \]
        \item If $U\in\mathcal{U}$, then $U^{-1}\in \mathcal{U}$, where $U^{-1}=\{(y,x)\in X\times X\mid (x,y)\in U\}\in \mathcal{U}$ for $U\subset X\times X$. 
        \end{itemize}
    A \textit{uniform space} is a set equipped with a uniformity. If the last condition is omitted, $\mathcal{U}$ is called a \textit{quasi-uniformity}, and a set equipped with a quasi-uniformity is called a \textit{quasi-uniform space}. 
\end{defi}

\begin{prop}[\broubakione, Chapter II, \S 1.2, Proposition 1] \label{proposition nhd system uniform space}
  Let $(X,\mathcal{U})$ be a quasi-uniform space. For each $U\in \mathcal{U}$ and $x\in X$, define 
  \[
    U[x]=\{y\in X\mid (x,y)\in U\}, 
  \]
  and let $\mathcal{B}(x)=\{U[x]\mid U\in \mathcal{U}\}$. Then, $\mathcal{B}(x)$ forms a neighborhood system for some topology on $X$, i.e., it satisfies the following conditions:
    \begin{itemize}
      \item For each $x\in X$ and each $U, V\subset X$ satisfying $V\in \mathcal{B}(x)$ and $V\subset U$, we have $U\in \mathcal{B}(x)$. 
      \item For each $x\in X$ and $U_1, U_2\in\mathcal{B}(x)$, we have $U_1\cap U_2\in \mathcal{B}(x)$. 
      \item For each $x\in X$ and $U\in \mathcal{B}(x)$, we have $x\in U$. 
      \item For each $x\in X$ and $U\in \mathcal{B}(x)$, there exists $V\in \mathcal{B}(x)$ such that $U\in\mathcal{B}(y)$ for all $y\in V$. 
    \end{itemize}
%   Then, the collection $\{U[x]\}_{x\in X, U\in \mathcal{U}}$ forms a fundamental system of neighbourhoods for some topology on $X$, i.e., it satisfies the following conditions: 
%   \begin{itemize}
%     \item For each $x\in X$, $\{U[x]\}_{U\in \mathcal{U}}\neq \emptyset$. 
%     \item For each $x\in X$ and $U\in \mathcal{U}$, we have $x\in U[x]$. 
%     \item For each $x\in X$ and $U_1, U_2\in\mathcal{U}$, there exists $V\in \mathcal{U}$ such that $V[x]\subset U_1[x]\cap U_2[x]$. 
%     \item For each $x\in X$ and $U\in \mathcal{U}$, there exists $V\in \mathcal{U}$ such that for any $y\in V[x]$, there exists $W\in \mathcal{U}$ with $W[y]\subset U[x]$. 
%   \end{itemize}
\end{prop}

\begin{proof}
    See \broubakione, Chapter II, \S 1.2, Proposition 1. 
\end{proof}

\begin{remark}
    Although \broubakione~states this proposition for uniform spaces, the proof does not rely 
    on the symmetry of the entourages. Thus, the statement also holds for quasi-uniform spaces.
\end{remark}

