We next introduce a still weaker form of the triangle inequality, which generalizes the weak triangle inequality of \defref{definition axioms of dr}.

\begin{defi} \label{definition weaker triangle inequality}
    Let $\{d_r\}_{r>0}$ be a family satisfying the axioms of \defref{definition axioms of dr}.
    Instead of the weak triangle inequality in \defref{definition axioms of dr}, we assume the following weaker triangle inequality:

    \begin{description}
        \item[Weaker triangle inequality]\leavevmode\\
        Let $r_1, r_2, r_3 > 0$. If $d_{r_1+r_2+r_3}(x, y)<r_3$ and $d_{r_1+r_2+r_3}(y, z)<r_2$, then 
        \[
            d_{r_1}(x, z)\leq d_{r_1+r_2+r_3}(x, y)+d_{r_1+r_2+r_3}(y, z).
        \]
    \end{description}
    A set $(X, \{d_r\}_{r>0})$ is said to satisfy the weaker $\{d_r\}$-axioms if it satisfies the axioms in \defref{definition axioms of dr}, 
    except that the weak triangle inequality is replaced by the weaker triangle inequality. 
\end{defi}

\begin{remark}
    % The weaker triangle inequality follows from the weak triangle inequality in Definition~\ref{definition axioms of dr} because it requires a less restrictive assumption.
    % In the weak triangle inequality, we assume an upper bound on $d_{r_1+r_2}(x, y)$, whereas in the weaker triangle inequality, it suffices to have an upper bound on $d_{r_1+r_2+r_3}(x, y)$, which is necessarily greater than or equal to $d_{r_1+r_2}(x, y)$. 
    % This relaxation of the hypothesis ensures that the weaker triangle inequality holds whenever the weak triangle inequality does.
    The key difference is that in the weak triangle inequality, the term $d_{r_1+r_2}(x, y)$ appears, whereas in the weaker triangle inequality, this is replaced by $d_{r_1+r_2+r_3}(x, y)$.
    The weaker triangle inequality follows from the weak triangle inequality since $d_{r_1+r_2}(x, y) \leq d_{r_1+r_2+r_3}(x, y)$. 

    % A natural example of a family $\{d_r\}_{r>0}$ satisfying the weaker triangle inequality arises in the space of graph embeddings $\embgraph{\mathbb{R}^N}$ (see \graphemb).
    % While the weak triangle inequality may also hold in this space, we are unable to verify it directly.
    In \exref{example graphemb}, we will define a family $\{d_r\}_{r>0}$ on the space of graph embeddings $\embgraph{\mathbb{R}^N}$ that satisfies the weaker triangle inequality.
    While the weak triangle inequality may also hold in this space, we are unable to verify it directly.
\end{remark}

The following definition provides the quasi-uniformity induced by the family $\{d_r\}_{r>0}$. 

\begin{prop} \label{proposition definition uniformity of dr space}
    Let $(X, \{d_r\}_{r>0})$ satisfy the weaker $\{d_r\}$-axioms in \defref{definition weaker triangle inequality}.
    We define
    \[
    \entourage{r}{\varepsilon}=\{(x,y)\in X\times X\mid d_r(x,y)<\varepsilon\}. 
    \]
    A subset $U\subset X\times X$ is called an entourage if there exist $r>0$ and $\varepsilon>0$ such that $\entourage{r}{\varepsilon}\subset U$. 

    Then, the collection $\mathcal{U}$ of all such entourages forms a quasi-uniformity on $X$.
    Moreover, if the family $\{d_r\}_{r>0}$ satisfies the symmetry condition, i.e., 
    \[
        d_r(x,y)=d_r(y,x)
    \]
    for all $x, y\in X$ and $r>0$, then in this case, $\mathcal{U}$ forms a uniformity. 
\end{prop}

