\begin{defi} \label{definition non-symmetric pseudo-metric}
  Let $X$ be a set. A \textit{quasi-pseudo-metric} on $X$ is a function $d\colon X\times X\to \mathbb{R}_{\geq 0}$ satisfying the following:
  \begin{description}
    \item[Self-distance Axiom] $d(x,x)=0$ for all $x\in X$. 
    \item[Triangle inequality] $d(x, z)\leq d(x, y)+d(y, z)$ for all $x, y, z\in X$.  
  \end{description}
  If the following condition is also satisfied, then we call $d$ a \textit{quasi-metric}: 
  \begin{description}
    \item[Non-degeneracy] $d(x, y)=0$ implies $x=y$.  
  \end{description}

%   Given a quasi-pseudo-metric $d$ on a set $X$, we can define a quasi-uniformity on $X$ by saying that a subset $U\subset X\times X$ is an entourage if it contains a set of the form 
%   \[
%     U_{\varepsilon}:=\{(x,y)\in X\times X\mid d(x, y)< \varepsilon\}
%   \]
%   for some $\varepsilon>0$. 
  Given a quasi-pseudo-metric $d$ on a set $X$, we define
  \[
    V_{\varepsilon}=\{(x,y)\in X\times X\mid d(x, y)< \varepsilon\}
  \]
  for each $\varepsilon>0$. A subset $U\subset X\times X$ is called an entourage if there exists $\varepsilon>0$ such that $V_{\varepsilon}\subset U$. 
  Then, the collection $\mathcal{U}$ of all such entourages forms a quasi-uniformity on $X$. 
\end{defi}

\begin{thm} \label{theorem pseudo-metric of dr space}
    Let $(X, \{d_r\}_{r>0})$ satisfy the weaker $\{d_r\}$-axioms in \defref{definition weaker triangle inequality}. 
    Then there exists a quasi-pseudo-metric $d$ on $X$ that induces the quasi-uniformity defined in \proref{proposition definition uniformity of dr space}. 
    Moreover, if the family $\{d_r\}_{r>0}$ is non-degenerate, i.e., 
    \[
        d_r(x, y)=0 \text{ for all } r>0\implies x=y, 
    \]
    then $d$ can be chosen to be a quasi-metric on $X$. 
\end{thm}

\begin{proof}
    The following argument is based on Proposition 2 in Chapter IX, Section 1.4 of \broubakitwo~by Bourbaki. 

    We define $W_n=\entourage{3^{2n}}{3^{-n}}=\{(x,y)\in X\times X\mid d_{3^{2n}}(x,y)<3^{-n}\}$ for each $n\in \mathbb{Z}_{\geq 0}$. 
    We now show that the following inclusion holds for each $n\in \mathbb{Z}_{\geq 0}$: 
    \[
        W_{n+1}\circ W_{n+1}\circ W_{n+1}\subset W_n. 
    \]
    Let $(x, w)\in W_{n+1}\circ W_{n+1}\circ W_{n+1}$ be arbitrary. 
    Then, there exist $y, z\in X$ such that $(x, y)$, $(y, z)$, and $(z, w)$ are all in $W_{n+1}$. 
    % Then, there exists $z\in X$ such that $(x, z)\in W_{n+1}\circ W_{n+1}$ and $(z, w)\in W_{n+1}$. 
    % Also, since $(x,z)\in W_{n+1}\circ W_{n+1}$, there exists $y\in X$ such that $(x, y)\in W_{n+1}$ and $(y,z)\in W_{n+1}$. 
    By applying the weaker triangle inequality repeatedly, we obtain
    \[
    \begin{aligned}
        &d_{3^{2n}}(x, w)\leq d_{3^{2n+1}}(x, y) + d_{3^{2n+1}}(y, w)\leq d_{3^{2n+2}}(x, y) + d_{3^{2n+1}}(y, w)\\
        &\leq d_{3^{2n+2}}(x, y) + d_{3^{2n+2}}(y, z) + d_{3^{2n+2}}(z, w)\leq 3^{-n-1}+3^{-n-1}+3^{-n-1}=3^{-n}. 
    \end{aligned}
    \]
    Using these $\{W_n\}_{n\in \mathbb{Z}_{\geq 0}}$, we define a function $g\colon X\times X\to \mathbb{R}_{\geq 0}$ by
    \[
        g(x, y) = 
        \begin{cases}
            0 & \text{if } (x, y) \in W_n \text{ for all } n \geq 1, \\
            2^{-k} & \text{if } (x, y) \in W_n \text{ for } 1 \leq n \leq k \text{ and } (x, y) \notin W_{k+1}, \\
            1 & \text{if } (x, y) \notin W_1.
        \end{cases}
    \]
    for $(x, y)\in X\times X$. Also, we define a function $d\colon X\times X\to \mathbb{R}_{\geq 0}$ by 
    \[
        d(x, y)=\inf \sum_{i=0}^{p-1} g(z_i, z_{i+1}), 
    \]
    where the infimum is taken over all finite sequences $\{z_i\}_{0\leq i\leq p}$ such that $z_0=x$ and $z_p=y$. 
    We shall show that $d$ is a quasi-pseudo-metric on $X$ which satisfies the following inequalities:
    \[
        \dfrac{1}{2}\,g(x, y)\leq d(x, y)\leq g(x, y).
    \]
    % It is straightforward to verify that $d$ is a quasi-pseudo-metric on $X$.  
    % Since the inequality $d(x, y) \leq g(x, y)$ is immediate from the definition, we focus on proving the other direction.
    % Since the inequality $d(x, y) \leq g(x, y)$ follows directly from the definition, it remains to prove the other inequality.
    % To establish the inequality $\frac{1}{2} g(x, y)\leq d(x, y)$, we prove the following proposition by induction on $p \in \mathbb{Z}_{>0}$:

    % \textbf{Claim} $(\mathcal{A}_p)$:  

    % For any $x, y\in X$ and any finite sequence $\{z_i\}_{0 \leq i \leq p}$ in $X$ with $z_0 = x$ and $z_p = y$, we have  
    % \[
    %     \dfrac{1}{2}\,g(x, y)\leq \sum_{i=0}^{p-1} g(z_i, z_{i+1}).
    % \]     
    % We prove $(\mathcal{A}_p)$ by induction on $p$. The case $p = 1$ is immediate. 
    % Now assume that $(\mathcal{A}_{p'})$ holds for every $1 \leq p' < p$.
    % We prove $(\mathcal{A}_p)$ under this assumption.    
    It is straightforward to verify that $d$ is a quasi-pseudo-metric on $X$.  
    Since the inequality $d(x, y) \leq g(x, y)$ follows directly from the definition, we only need to prove the inequality $\frac{1}{2} g(x, y)\leq d(x, y)$.  
    To this end, we prove the following by induction on $p \in \mathbb{Z}_{>0}$:

    For any $x, y\in X$ and any finite sequence $\{z_i\}_{0 \leq i \leq p}$ in $X$ with $z_0 = x$ and $z_p = y$, we have  
    \[
        \dfrac{1}{2}\,g(x, y)\leq \sum_{i=0}^{p-1} g(z_i, z_{i+1}).
    \] 
    % We prove this by induction on $p$. The case $p = 1$ is immediate. Suppose that the statement holds for every $p' < p$, we prove this statement on $p$. 
    Suppose that the statement holds for every $p' < p$. We now prove the case $p$.
    We define $a=\sum_{i=0}^{p-1} g(z_i, z_{i+1})$. If $a\geq 1/2$, then the desired inequality holds trivially. 
    If $a<1/2$, let $h$ be the largest integer $q\in \mathbb{Z}_{\geq 1}$ such that 
    \[
        \sum_{i=1}^{q-1} g(z_i, z_{i+1}) \leq \dfrac{a}{2}. 
    \]
    By the definition of $h$, we have 
    \[
        \sum_{i=0}^{h-1}g(z_i, z_{i+1})\leq\dfrac{a}{2}\quad \text{and} \quad \sum_{i=0}^h g(z_i, z_{i+1})>\dfrac{a}{2}. 
    \]
    It follows from the second inequality that $\sum_{i=h+1}^{p-1} g(z_i, z_{i+1})\leq a/2$. 
    By the inductive hypothesis, we have $g(x, z_h)\leq a$ and $g(z_{h+1}, y)\leq a$. It is also clear that $g(z_h, z_{h+1})\leq a$. 
    Let $k\in\mathbb{Z}_{\geq 1}$ be the smallest integer such that $2^{-k}\leq a$. 
    % Moreover, since $g(x, z_h)$, $g(z_h, z_{h+1})$, and $g(z_{h+1}, y)$ are all of the form $2^{-n}$ and are less than or equal to $a$, we have $(x, z_h),\ (z_h, z_{h+1}),\ (z_{h+1}, y)\in W_k$. 
    Since $g(x, z_h)$, $g(z_h, z_{h+1})$, and $g(z_{h+1}, y)$ are each of the form $2^{-n}$ and less than or equal to $a$, it follows that $(x, z_h),\ (z_h, z_{h+1})$, and $(z_{h+1}, y)$ all belong to $W_k$.
    Therefore, we obtain $(x, y)\in W_k\circ W_k\circ W_k\subset W_{k-1}$, which implies that $g(x, y)\leq 2^{1-k}\leq 2a$. This completes the proof of $\frac{1}{2}\,g(x, y)\leq d(x, y)$. 

    % Using these inequalities, we prove that the quasi-uniformity induced by $d$ is the same to the one induced by the family $\{d_r\}_{r>0}$. 
    Using these inequalities, we now show that the quasi-uniformity $\mathcal{U}$ induced by the family $\{d_r\}_{r>0}$ coincides with the quasi-uniformity $\mathcal{U}'$ induced by $d$. 
    Let $U\in \mathcal{U}$ be an arbitrary entourage. 
    Then there exist $r>0$ and $\varepsilon>0$ such that $\entourage{r}{\varepsilon}\subset U$. 
    For these $r$ and $\varepsilon$, choose $k\in\mathbb{Z}_{\geq 0}$ such that $3^{2k}>r$, $3^{-k}<\varepsilon$. 
    Since $g(x, y)\leq 2d(x, y)$ for any $x, y\in X$, we have 
    \[
        V_{2^{-k-1}}\subset W_k\subset \entourage{r}{\varepsilon}\subset U. 
    \]
    Indeed, for any $(x, y)\in V_{2^{-k-1}}$, we have $g(x, y)\leq 2d(x, y)< 2^{-k}$, which implies $(x, y)\in W_k$. 
    Therefore, $U$ is also in $\mathcal{U}'$. 

    Conversely, let $U\in \mathcal{U}'$ be an arbitrary entourage. 
    Then there exists $\varepsilon>0$ such that $V_{\varepsilon}\subset U$. Choose $k\in\mathbb{Z}_{\geq 0}$ such that $2^{-k}< \varepsilon$. 
    Since $d(x, y)\leq g(x, y)$ for any $x, y\in X$, we have
    \[
        \entourage{3^{2k}}{3^{-k}}=W_k\subset V_{\varepsilon}.
    \]
    Indeed, for any $(x, y)\in W_k$, we have $d(x, y)\leq g(x, y)\leq 2^{-k}<\varepsilon$. Therefore, $U$ is also in $\mathcal{U}$. 

    % Finally, we prove that $d$ is actually non-degenerate, i.e., $d(x, y)=0$ implies $x=y$, when the family $\{d_r\}_{r>0}$ is non-degenerate. 
    % Finally, we show that $d$ is actually non-degenerate; that is, $d(x, y) = 0$ implies $x = y$, provided that the family ${d_r}_{r>0}$ is non-degenerate.
    Finally, we prove that $d(x, y) = 0$ implies $x = y$ under the assumption that the family $\{d_r\}_{r>0}$ is non-degenerate. 
    Let $x, y\in X$ be arbitrary with $d(x, y)=0$, and let $r>0$ and $\varepsilon>0$ be arbitrary. Choose $k\in \mathbb{Z}_{\geq 1}$ such that $W_k\subset \entourage{r}{\varepsilon}$. 
    Since $g(x, y)\leq 2d(x, y)=0$, we obtain $(x, y)\in W_n$ for all $n\in\mathbb{Z}_{\geq 1}$, and in particular $(x, y)\in W_k$.  
    % Therefore, we obtain $(x, y)\in W_k\subset \entourage{r}{\varepsilon}$, which implies $d_r(x, y)< \varepsilon$. 
    Hence, $(x, y)\in \entourage{r}{\varepsilon}$, it follows that $d_r(x, y)< \varepsilon$. 
    Since $r$ and $\varepsilon$ were arbitrary, this means $d_r(x, y)=0$ for all $r>0$. 
    By the non-degeneracy of $\{d_r\}_{r > 0}$, we conclude that $x = y$.
\end{proof}

\begin{remark}{}{} \label{remark symmetric metric}
    If each $d_r$ is symmetric, then the family $\{d_r\}_{r>0}$ induces a genuine uniformity rather than just a quasi-uniformity.
    In this case, Proposition 2 in Chapter IX, Section 1.4 of \broubakitwo~applies directly and ensures the existence of a pseudo-metric $d$ that induces the original uniformity.
    Moreover, if each $d_r$ is symmetric, then the topology induced by the family $\{d_r\}_{r>0}$ satisfies the $T_1$ separation axiom. In fact, it is even regular (\metricemb, Lemma 4.3).
    As a consequence, the pseudo-metric $d$ constructed in the proof must actually be a metric. 
\end{remark}

\begin{ex} \label{example submanifold metrizable}
  The family $\{d_r\}_{r>0}$ on the space of submanifolds $\embmfd{d}{N}$ in \exref{example submanifold} is symmetric. 
  Therefore, by \thref{theorem pseudo-metric of dr space} and \remref{remark symmetric metric}, there exists a metric on $\embmfd{d}{N}$ which induces both the uniformity and the topology on $\embmfd{d}{N}$. 
  This provides a simpler way to recover the result of \metricemb, Theorem 4.4.
\end{ex}

\section{Diffeology defined by \texorpdfstring{$d_r$}{dr}}

In this section, we introduce a diffeology defined by the family $\{d_r\}_{r>0}$. 
We begin by defining \textit{diffeological spaces} and see their basic properties. 
All definitions and properties presented here are based on \IZ~by Iglesias-Zemmour, the standard textbook of diffeology. 
% For the proofs of the propositions mentioned in this section, please refer to \IZ for further details.
For more details on diffeological spaces, see \IZ. 

\begin{defi}[\IZ, 1.5] \label{definition diffeology}
  Let $X$ be a set. A \textit{parametrization} of $X$ is a map $U\to X$ where $U$ is an open set of $\mathbb{R}^n$ for some $n\in\mathbb{Z}_{\geq 0}$.
  A \textit{diffeology} on $X$ is a set $\mathscr{D}_X$ of parametrizations (whose elements are called \textit{plots}) satisfying the following three axioms:
  % A diffeology on $X$ is any set $\mathscr{D}_X$ of maps $U\to X$ (called plots) for every open set $U$ in $\mathbb{R}^n$ and for each $n\in \mathbb{Z}_{\geq 0}$, such that the three following axioms are satisfied:
  \begin{description}
    \item[Covering] Every constant parametrization $U\to X$ is a plot.
    \item[Locality] Let $p\colon U\to X$ be a parametrization. If there exists an open covering $\{U_{\alpha}\}$ of $U$ such that ${p|}_{U_{\alpha}}\in \mathscr{D}_X$ for all $\alpha$, then $p$ itself is a plot.  
    \item[Smooth compatibility] For every plot $p\colon U\to X$, every open set $V$ in $\mathbb{R}^m$ and $f\colon V\to U$ that is smooth as a map between Euclidean spaces, $p\circ f\colon V\to X$ is also a plot.
  \end{description}
  A \textit{diffeological space} is a set equipped with a diffeology.
  We usually write the underlying set $X$ to represent a diffeological space $(X,\mathscr{D}_X)$.
\end{defi}

% Throughout this paper, we call an open set of $\mathbb{R}^n$ for some $n$ an \textit{Euclidean open set}, and we denote the domain set of a plot $p$ of a diffeological space by $\plotdom{p}$.
Throughout this paper, we refer to any open subset of $\mathbb{R}^n$ (for some $n$) as a \textit{Euclidean open set}.  
% Also, we call a plot $p$ an \textit{$n$-plot} if its domain $\plotdom{p}$ is an open set of $\mathbb{R}^n$. 
We also denote the domain of a plot $p$ by $U_p$ and call $p$ an \textit{$n$-plot} if its domain $U_p$ is an open subset of $\mathbb{R}^n$.

\begin{defi}[\IZ, 1.14] \label{definition smooth map}
  Let $X$ and $Y$ be diffeological spaces. 
  A map $f\colon X\to Y$ is said to be \textit{smooth} if for every plot $p\colon \plotdom{p}\to X$, the composition $f\circ p\colon \plotdom{p}\to Y$ is a plot of $Y$.
  The set of smooth maps from $X$ to $Y$ is denoted by $\smoothmap{X}{Y}$. 
  If $X$ is a Euclidean open set, then $C^\infty(X,Y)$ coincides with the set of all plots $X\to Y$ (\IZ, 1.16).
\end{defi}

Diffeological spaces and smooth maps between them form a category denoted by $\dflg$.
% We call an isomorphism of this category a \textit{diffeomorphism}. 
An isomorphism in this category is called a \textit{diffeomorphism}.  
The category $\dflg$ contains the category $\mfd$ of smooth manifolds and smooth maps as a full subcategory. 
In particular, $\dflg$ also contains the category $\encl$ of Euclidean open sets and smooth maps as a full subcategory. This follows from the next example. 

\begin{ex} \label{example definition manifold diffeology}
  Let $M$ be a smooth manifold, and let $\mathscr{D}_M$ be the set of all smooth maps from some Euclidean open set $U$ to $M$ (in the sense of smooth maps between manifolds).
  Then $\mathscr{D}_M$ forms a diffeology on $M$. 
\end{ex}

\begin{defi}[\IZ, 2.8] \label{definition D-topology}
  Let $X$ be a diffeological space. The largest topology on $X$ that makes all plots continuous is called the \textit{$D$-topology} on $X$. 
  With this construction, we define the functor $D$ from the category $\dflg$ to the category of topological spaces $\topsp$.
\end{defi}

It is known that the functor $D$ has the right adjoint $\conti$ (Shimakawa-Yoshida-Haraguchi \SH, Proposition 2.1).
For a manifold $M$ equipped with the standard diffeology (\exref{example definition manifold diffeology}), the $D$-topology of $M$ coincides with the standard topology of the manifold $M$. 

\begin{defi}[\IZ, 1.66] \label{definition generating family}
    Let $X$ be a set, and let $\mathscr{F}$ be a family of parametrizations of $X$. Then, there exists the smallest diffeology $\mathscr{D}$ on $X$ that contains all parametrizations of $\mathscr{F}$ as plots. 
    We call this diffeology $\mathscr{D}$ the \textit{diffeology generated by} $\mathscr{F}$. 
    A parametrization $p\colon \plotdom{p}\to X$ is a plot of $\mathscr{D}$ if and only if it satisfies the following condition:
    there exists an open covering $\{U_{\alpha}\}$ of $\plotdom{p}$ such that for each $\alpha$, either ${p|}_{U_{\alpha}}$ is a constant parametrization 
    or ${p|}_{U_{\alpha}}=q\circ f$ for some $q\in\mathscr{F}$ and some smooth map $f\colon U_{\alpha} \to \plotdom{q}$ (\IZ, 1.68).

    If the family $\mathscr{F}$ satisfies $\bigcup_{q\in \mathscr{F}} q(\plotdom{q})=X$, then $\mathscr{F}$ is called a \textit{covering generating family}. 
    In this case, a parametrization $p\colon \plotdom{p}\to X$ is a plot of $\mathscr{D}$ if and only if it satisfies the following property:
    there exists an open covering $\{U_{\alpha}\}$ of $\plotdom{p}$ such that for each $\alpha$, ${p|}_{U_{\alpha}}=q\circ f$ for some $q\in\mathscr{F}$ and some smooth map $f\colon U_{\alpha} \to \plotdom{q}$.
\end{defi}

We now proceed to define a diffeology on the space with the family $\{d_r\}_{r>0}$. 

\begin{prop} \label{proposition definition diffeology on dr space}
    % Let $(X, \{d_r\}_{r>0})$ satisfy the axioms in \defref{definition axioms of dr}. 
    Let $(X, \{d_r\}_{r>0})$ satisfy the weaker $\{d_r\}$-axioms in \defref{definition weaker triangle inequality}.
    A parametrization $p\colon\plotdom{p}\to X$ is \textit{smooth at} $t_0\in \plotdom{p}$ if there exists $\delta>0$ satisfying the following conditions: 
    \begin{itemize}
        \item The map $\openball{\delta}{t_0}\to \mathbb{R}; t\mapsto d_r(p(t_0),p(t))$ is continuous for each $r>0$. 
        \item For any $t_1\in \openball{\delta}{t_0}\setminus p^{-1}(p(t_0))$, the map $\openball{\delta}{t_0}\to \mathbb{R}; t\mapsto d_r(p(t_1),p(t))$ is smooth at $t_0$ for each $r>0$. 
    \end{itemize}
    A parametrization $p\colon\plotdom{p}\to X$ is said to be a \textit{plot} if it is smooth at every point $t_0\in \plotdom{p}$. 
    Then, the set of all plots of $X$ forms a diffeology on $X$. 
\end{prop}

\begin{proof}
Since the covering and locality axioms follow directly from the definitions, we proceed to prove the smooth compatibility axiom. 
Let $p\colon\plotdom{p}\to X$ be a plot of $X$, and let $f\colon V\to \plotdom{p}$ be a smooth map from a Euclidean open set. 
% Take any $t_0\in V$. 
Let $t_0\in V$ be arbitrary. 
Since $p$ is smooth at $f(t_0)$, there exists $\delta>0$ such that the following conditions hold: 
\begin{itemize}
    \item The map $\openball{\delta}{f(t_0)}\to \mathbb{R}; t\mapsto d_r(p\circ f(t_0),p(t))$ is continuous for each $r>0$. 
    \item For any $t_1\in \openball{\delta}{f(t_0)}\setminus p^{-1}(p\circ f(t_0))$, the map $\openball{\delta}{f(t_0)}\to \mathbb{R}; t\mapsto d_r(p\circ f(t_1),p(t))$ is smooth at $f(t_0)$ for each $r>0$. 
\end{itemize} 
By the continuity of $f$, there exists $\delta'>0$ such that $\openball{\delta'}{t_0}\subset f^{-1}(\openball{\delta}{f(t_0)})$. 
Using the identity 
\[
    [t\mapsto d_r(p\circ f(s),p\circ f(t))]=[t\mapsto d_r(p\circ f(s),p(t))]\circ f
\]
for any $s\in \openball{\delta'}{s}$, we obtain:
\begin{itemize}
    \item The map $\openball{\delta'}{t_0}\to \mathbb{R}; t\mapsto d_r(p\circ f(t_0),p\circ f(t))$ is continuous. 
    \item For any $t_1\in \openball{\delta'}{t_0}\setminus (p\circ f)^{-1}(p\circ f(t_0))$, the map $\openball{\delta'}{t_0}\to \mathbb{R}; t\mapsto d_r(p\circ f(t_1),p\circ f(t))$ is smooth at $t_0$ for each $r>0$. 
\end{itemize}
These conditions imply that $p\circ f$ is smooth at $t_0$, and therefore, $p\circ f$ is a plot of $X$. 
\end{proof}

In \tilingdflg, a diffeology is introduced on the tiling space. 
We aim to show that this diffeology coincides with the one defined using the family $\{d_r\}_{r>0}$ (\proref{proposition definition diffeology on dr space}). 
First, we review the diffeology on the tiling space defined in \tilingdflg. 

\begin{defi}[\tilingdflg, Definition 12] \label{definition tiling diffeology}
    Let $T$ be a tiling of $\mathbb{R}^d$. For each $T_1\in\tilingsp{T}$, we define the map 
    \[
        F_{T_1}\colon \mathbb{R}^d\to \tilingsp{T};x\mapsto T_1+x.
    \]
    The diffeology on $\tilingsp{T}$ defined in \tilingdflg~is the diffeology generated by the family $\{F_{T_1}\mid T_1\in \tilingsp{T}\}$. 
\end{defi}

We now prove that this diffeology coincides with the one defined using the family $\{d_r\}_{r>0}$ on $\tilingsp{T}$ (\proref{proposition definition diffeology on dr space}). 

\begin{thm} \label{theorem tiling diffeology is dr diffeology}
    Let $T$ be a tiling of $\mathbb{R}^d$, and let $\{d_r\}_{r>0}$ be the family introduced in \proref{proposition definition tiling dr}. 
    The diffeology on $\tilingsp{T}$, defined in \defref{definition tiling diffeology}, coincides with the one induced by the family $\{d_r\}_{r>0}$ (see \proref{proposition definition diffeology on dr space}).
\end{thm}

% \begin{prop} \label{proposition tiling diffeology is dr diffeology}
%     Let $T$ be a tiling of $\mathbb{R}^d$, and let $\{d_r\}_{r>0}$ be the family introduced in \proref{proposition definition tiling dr}. 
%     The diffeology on $\tilingsp{T}$, defined in \defref{definition tiling diffeology}, coincides with the one induced by the family $\{d_r\}_{r>0}$ (see \proref{proposition definition diffeology on dr space}).
% \end{prop}

\begin{proof}
First, we prove that $F_{T_1}$ is a plot of the diffeology induced by $\{d_r\}_{r>0}$ for each $T_1\in\tilingsp{T}$. 
Let $\prototile$ be the set of prototiles of $T$, and let $T_1\in \tilingsp{T}$ a tiling. 
% Take any $t_0\in \mathbb{R}^d$, and define $\delta=\min_{\tau\in \prototile}(\diam{\tau})
Let $t_0\in \mathbb{R}^d$ be arbitrary, and define $\delta=\min_{\tau\in \prototile}(\diam{\tau})
% \min\{\diam{\tau}\mid \tau\in \prototile\}
$. Then, for each $t\in \openball{\delta}{t_0}$, we have 
\[
    d_r(F_{T_1}(t_0), F_{T_1}(t))=d_r(T_1+t_0, T_1+t)=|t_0-t|.
\]
This holds because $d_r(T_1+t_0, T_1+t)$ cannot be smaller than $\delta=\min_{\tau\in \prototile}(\diam{\tau})$. 
Thus, $F_{T_1}$ satisfies the conditions specified in \proref{proposition definition diffeology on dr space} for each $T_1\in\tilingsp{T}$. 

Next, we prove the other inclusion. 
Let $p\colon\plotdom{p}\to \tilingsp{T}$ be a plot in the sense of \proref{proposition definition diffeology on dr space}, and let $t_0\in \plotdom{p}$. 
Then, there exists $\delta>0$ such that the map 
\[
    \openball{\delta}{t_0}\to \mathbb{R}; t\mapsto d_r(p(t_0),p(t))
\]
is continuous for each $r>0$. 
Define $\varepsilon>0$ such that $0<\varepsilon<1/2\min_{\tau\in \prototile}(\diam{\tau})$. 
Let $r>0$ be arbitrary. By the continuity of the map $t\mapsto d_r(p(t_0),p(t))$, we can choose $\delta>0$ such that $d_r(p(t_0),p(t))<\varepsilon$ for all $t\in \openball{\delta}{t_0}$. 
In fact, this $\delta$ satisfies $d_{r'}(p(t_0),p(t))<\varepsilon$ for all $r'>0$ and all $t\in \openball{\delta}{t_0}$. 
To prove the above statement, it suffices to show that the set 
\[
    A_{r'}=\{t\in\openball{\delta}{t_0}\mid d_{r'}(p(t_0), p(t))<\varepsilon\}\,(\neq \emptyset) 
\]
is connected in $\openball{\delta}{t_0}$ for all $r'>0$. 
% We only need to show when $r'>r$ holds, since if $r'\geq r$, then we have $A_{r'}\supset A_r=\openball{\delta}{t_0}$. 
% We only need to consider the case where $r'>r$, since if $r'\leq r$, it follows that $A_{r'}\supset A_r=\openball{\delta}{t_0}$. 
We only need to consider the case where $r'>r$, as $r'\leq r$ implies $A_{r'}\supset A_r=\openball{\delta}{t_0}$. 
Since the map $d_{r'}(p(t_0), \cdot)\colon X\to \mathbb{R}$ is upper semi-continuous 
(\corref{corollary upper semiconti}), 
% (this will be proved in \lemref{lemma upper semiconti}), 
$A_{r'}\subset \openball{\delta}{t_0}$ is open. 
Therefore, it suffices to show that $A_{r'}$ is closed in $\openball{\delta}{t_0}$. 
% To prove this, we assume that $\overline{A}\setminus A\neq \emptyset$, and take $t\in \overline{A}\setminus A$. 
To prove this, suppose there exists $t\in \overline{A_{r'}}\setminus A_{r'}$. 
Since $t\notin A_{r'}$, we have $d_{r'}(p(t_0), p(t))\geq \varepsilon$. 
% On the other hand, we have $d_{r}(p(t_0),p(t))<\varepsilon$ because $t\in \openball{\delta}{t_0}$. 
On the other hand, since $t\in \openball{\delta}{t_0}$, there exists $v\in \mathbb{R}^d$ such that $|v|<\varepsilon$ and 
\[
    (p(t_0)+v)\cap \closedball{r}=p(t)\cap \closedball{r}. 
\]
% ここまで
By the inequality $d_{r'}(p(t_0), p(t))\geq \varepsilon$, it follows that 
\[
    (p(t_0)+v)\cap \closedball{r'}\neq p(t)\cap \closedball{r'} 
\]
for the same $v$. Therefore, we obtain 
\[
    d_{r'}(p(t_0),p(t))\geq \min_{\tau\in \prototile}(\diam{\tau})-\varepsilon>\varepsilon. 
\]
On the other hand, since $t\in \overline{A}_{r'}$, there exists a sequence $\{s_n\}_{n\in \mathbb{Z}_{\geq 0}}$ converging to $t$ such that 
\[
    d_{r'}(p(t_0),p(s_n))<\varepsilon.
\]
This contradicts the continuity of the map $d_{r'}(p(t_0), p(\cdot))\colon X\to \mathbb{R}$ at the point $t$. 
Thus, we have $\overline{A_{r'}}\setminus A_{r'}\neq \emptyset$, which implies that $A_{r'}$ is closed in $\openball{\delta}{t_0}$. Therefore, we obtain $A_{r'}=\openball{\delta}{t_0}$. 

By the above argument, for each $t\in \openball{\delta}{t_0}$, there exists a unique $u_t\in\mathbb{R}^d$ such that $|u_t|<\varepsilon$ and 
\[
    (p(t_0)+u_t)\cap \closedball{r'}=p(t)\cap \closedball{r'}
\]
for each $r'>0$. This $u_t$ satisfies 
\[
    p(t_0)+u_t=p(t)
\]
for each $t\in\openball{\delta}{t_0}$. 
Therefore, we have a unique map $u\colon \openball{\delta}{t_0}\to \mathbb{R}^d;t\mapsto u_t$ such that $p(t_0)+u(t)=p(t)$ for each $t\in\openball{\delta}{t_0}$. 
We now show that this map $u$ is smooth. 

First, we prove the continuity of $u$ at the point $t_0\in\openball{\delta}{t_0}$. 
It has already been proved that the map $d_r(p(t_0), p(\cdot))\colon\openball{\delta}{t_0}\to \mathbb{R}$ is continuous. 
Since $d_r(p(t_0),p(t))<\varepsilon$ for each $t\in\openball{\delta}{t_0}$, it follows that 
\[
    d_r(p(t_0), p(t))=|u(t_0)-u(t)|. 
\]
Therefore, for any $\varepsilon'>0$, there exists $\delta'>0$ such that for each $t\in\openball{\delta'}{t_0}$, 
\[
    |u(t_0)-u(t)|=|u(t_0)-u(t)|-|u(t_0)-u(t_0)|<\varepsilon', 
\]
which implies that $u$ is continuous at $t_0$. 

Next, we prove the smoothness of $u$ at the point $t_0\in\openball{\delta}{t_0}$. 
If $p(t)=p(t_0)$ holds for all $t\in\openball{\delta}{t_0}$, then $u$ is constant on $\openball{\delta}{t_0}$, and in particular, smooth on $\openball{\delta}{t_0}$. 
Otherwise, there exists $t_1\in\openball{\delta}{t_0}\setminus p^{-1}(p(t_0))$. 
By repeating this process, we can find a finite sequence $t_1, \dots, t_n\in \openball{\delta}{t_0}$ such that 
\[
    \{u(t)\mid t\in\openball{\delta}{t_0}\}\subset \Span\{\overrightarrow{u(t_0)u(t_i)}\mid i=1,\dots,n\}
\]
and the set of vectors $\left\{\overrightarrow{u(t_0)u(t_i)}\right\}_{i=1}^n$ is linearly independent. 
Thus, we can restrict the codomain of $u$ to $\Span\left\{\overrightarrow{u(t_0)u(t_i)}\mid i=1,\dots,n\right\}\cong \mathbb{R}^n$. 
We define the map 
\[
    f\colon \openball{\delta}{t_0}\times \mathbb{R}^n\to \mathbb{R}^n;(t,x)\mapsto (|x-u(t_i)|^2-d_r(p(t_i), p(t))^2)_{i=1}^n.
\]
Since the map $d_r(p(t_i), p(\cdot))$ is smooth at $t_0$ for each $t_i$, the map $f$ is smooth around $(t_0, u(t_0))$. 
By the linear independence of $\left\{\overrightarrow{u(t_0)u(t_i)}\right\}_{i=1}^n$, we have
\[
    \left.\det\left({\frac{\partial f}{\partial x}}(t_0, u(t_0))\right)=\det{\begin{pmatrix}
        2x-2u(t_1) \\ \vdots \\ 2x-2u(t_n) 
       \end{pmatrix}}\right|_{t=t_0, x=u(t_0)}\neq 0.
\]
Thus, by the implicit function theorem, there exist open sets $U\subset \openball{\delta}{t_0}$ and $V\subset \mathbb{R}^n$ with $t_0\in U$ and $u(t_0)\in V$, and a smooth map $g\colon U\to V$ such that
% Therefore, by the implicit function theorem, there exist open sets $U$ and $V$ such that $t_0\in U\subset \openball{\delta}{t_0}$ and $u(t_0)\in V\subset \mathbb{R}^n$, and a smooth map $g\colon U\to V$ such that 
for all $(t,x)\in U\times V$, 
\[
    f(t,x)=0\iff x=g(t). 
\]
This map $g$ is precisely the restriction ${u|}_{U}$, which implies that $u$ is smooth at $t_0$. 
\end{proof}

\section{Relating topologies and diffeologies}

We have seen that the topology and diffeology of the tiling space can be connected through the structure of the family $\{d_r\}_{r>0}$. 


% The preceding results suggest a natural question about the relationship between the topology and diffeology induced by $\{d_r\}_{r>0}$ in specific spaces.
% The preceding results suggest a natural question of whether the topology and the $D$-topology actually coincide in certain spaces.


% In particular, for the tiling space, we have shown that the topology and diffeology are compatible via the structure of the family $\{d_r\}_{r>0}$.  
% Moreover, in the case of the tiling space, both the topology and the diffeology can be recovered from the structure of the family $\{d_r\}_{r>0}$.
It is natural to ask whether a similar relationship holds for the space of submanifolds $\embmfd{d}{N}$, equipped with the family introduced in \exref{example submanifold}.

In \mfdembdflg, a diffeology on $\embmfd{d}{N}$ is defined as follows:  
a parametrization $p\colon\plotdom{p}\to \embmfd{d}{N}$ is a plot if  
\[
\Gamma_p = \{(t,x)\in \plotdom{p}\times \mathbb{R}^N \mid x \in p(t)\}
\]
is a closed submanifold of $\mathbb{R}^N$, and the projection  
\[
\hat{p} \colon \Gamma_p \to \plotdom{p}, \quad (t,x) \mapsto t
\]
is a submersion.

% A natural question is how this diffeology relates to the one induced by $\{d_r\}_{r>0}$ (see \proref{proposition definition diffeology on dr space}). 
It is natural to ask how this diffeology relates to the one induced by by $\{d_r\}_{r>0}$ (see \proref{proposition definition diffeology on dr space}). 
At least, the following fact holds in general. 

\begin{lemma} \label{lem smooth plot is continuous}
    Let $(X, \{d_r\}_{r>0})$ satisfy the weaker $\{d_r\}$-axioms in \defref{definition weaker triangle inequality}. 
    If a map $p\colon\plotdom{p}\to X$ is a plot of $X$ as defined in \proref{proposition definition diffeology on dr space}, then $p$ is also continuous. 
\end{lemma}

\begin{proof}
Let $t_0\in \plotdom{p}$, $r>0$, and $\varepsilon>0$ be arbitrary. 
Since $p$ is a plot of $X$, there exists $\delta>0$ such that $d_r(p(t_0), p(t))<\varepsilon$ for all $t\in\openball{\delta}{t_0}$. 
This implies that $\openball{\delta}{t_0}\subset p^{-1}(\entourage{r}{\varepsilon}[p(t_0)])$. 
\end{proof}

\begin{prop} \label{proposition D-topology is finer than topology}
    Let $(X, \{d_r\}_{r>0})$ satisfy the weaker $\{d_r\}$-axioms in \defref{definition weaker triangle inequality}. 
    The $D$-topology of the diffeology on $X$ induced by the family $\{d_r\}_{r>0}$ (see \proref{proposition definition diffeology on dr space}) is finer than 
    the topology on $X$ induced by the same family (see \proref{proposition definition uniformity of dr space}).
\end{prop}

\begin{proof}
Let $x\in X$, $r>0$, and $\varepsilon>0$ be arbitrary. For each plot $p\colon \plotdom{p}\to X$ of $X$, 
the preimage $p^{-1}(\nhddr{r}{\varepsilon}{x})$ is open in $\plotdom{p}$ because $p$ is continuous (\lemref{lem smooth plot is continuous}). 
Therefore, $\nhddr{r}{\varepsilon}{x}$ is $D$-open. 
\end{proof}

