\subsection{Construction for $\exists \phi, \forall \phi, \forall\exists \phi$, and $\exists\forall \phi$}
\label{ssec:constructions}

Next we describe the GFM automata constructions of the formulas $\exists \phi, \forall \phi, \forall\exists \phi$ and $\exists\forall \phi$, which we call \emph{leaf} formulas.


\paragraph{$\exists \phi$.} We first present the construction for $\exists \phi$ below.
\begin{enumerate}\itemsep=0pt
    \item First, let $\D = (\alphabet, Q, \iota, \trans, \acc)$ be $\dfaBuild(\phi)$ such that $\finlang{\D} = [\phi]$.
    \item Second, make all final states in $\acc$ sink final states, i.e., $\trans(s, a) = s$ for each $s \in \acc$ and $a \in \alphabet$, obtaining the automaton $\C = (Q, \iota', \trans', \acc')$.
     $\C$ remains deterministic.
    \item Finally, read it as DBA $\B = ( Q, \iota', \trans', \acc')$.
\end{enumerate}

\begin{theorem}\label{lem:exists-lang}
    $\lang{\B} = \flang{\exists\phi}$.
\end{theorem}
By making final states sink, every word accepted in $\B$ must have a prefix belonging to $[\phi]$.
Hence, the theorem follows.

\paragraph{$\forall \phi$.} Now we introduce the construction for $\forall\phi$.


\begin{figure}[t]
    \centering
    \includegraphics[width=1\linewidth]{example-construction.pdf}
    \caption{The corresponding \buchiaut automata constructed by our algorithm for $\exists\phi, \forall 
    \phi$ and $\forall \exists \phi$ where $\phi$ is as defined in Figure~\ref{fig:dfa-example}.}
    \label{fig:ba-construction}
\end{figure}


\begin{enumerate}\itemsep=0pt
\item First, let $\C =  (\states, \iota, \trans, \acc)$ be $\dfaBuild(\neg\phi)$ such that $\finlang{\C} = [\neg\phi]$.
\item Then, make all final states in $\C$ as sink final states, remove unreachable states and obtain the DFA $\C' = (Q', \iota, \trans', \acc')$
\item Finally, reverse the set of final states and read it as B\"uchi automaton $\B = (\states', \iota, \trans', \states'\setminus\acc')$.
\end{enumerate}


\begin{theorem}\label{lem:uni-lang}
    $\lang{\B} = \flang{\forall \phi}$.
\end{theorem}
By making final states of $\C$ sink states, every accepting run over a word $w$ in $\B$ does not visit those sink final states in $\C$, which then entails that no prefixes of $w$ belong to $[\neg\phi]$.
That is, all prefixes of $w$ belong to $\phi$. Then the theorem follows.
Our construction for $\forall\phi$ is quite similar to the one %described
in~\cite{DBLP:conf/atva/BansalLTVW23}.


\paragraph{$\forall\exists \phi$.}
The construction for $\forall\exists\phi$ is simple and given below.
\begin{enumerate}
    \item First, let $\D = (Q, \iota, \trans, \acc)$ be the DFA $\dfaBuild(\phi)$.
%    \item 
    \item Then, read $\D$ as B\"uchi automaton $\B = (Q, \iota, \trans, \acc)$.
\end{enumerate}

\begin{theorem}\label{lem:uni-exist-phi}
    $\lang{\B} = \flang{\forall \exists \phi}$.
\end{theorem}
Theorem~\ref{lem:uni-exist-phi} clearly holds since every accepting run in $\B$ has a finite prefix run that is an accepting run in $\D$.
Figure~\ref{fig:ba-construction} shows the \buchiaut automata constructed for $\exists\phi, \forall 
    \phi$ and $\forall \exists \phi$.
% The DBA $\B$ is not a weak DBA, as witnessed in Figure~\ref{fig:ba-construction};


