\section{Trace Formula Set-up}
\label{Sec: Setup}

\subsection{Set-up}
Fix a square-free positive integer $N$. 
Set $H^{\new}(N)$ to denote a basis of the space $S^{\new}(N)$ of weight $2$ Hecke cusp newforms for $\Gamma_0(N)$, and let $a_f(P) = \lambda_f(P)\sqrt{P}$ denote the eigenvalue under the $P$-th Hecke operator $T_p$ of $f \in H^{\new}(N)$.
Let $\epsilon(f)$ denote the root number of $f$ and recall that $-\epsilon(f)$ is equal to the eigenvalue of $f$ under the Atkin--Lehner involution $W_N$.

In contrast to previous considerations of murmuration behaviour we are interested in the Fourier-coefficient $\lambda_f(P^2)$.
When $P\nmid N$, we know that %Coefficients_of_symmetric_square_L-functions.pdf
\[
 \lambda_f(P^2) = \lambda_f(P)^2 -1.
\]

Consider the operator $(-1)T_{P^2}\circ W_N$ on $S^{\new}(N)$; its trace is 
\[
\sum_{f\in H^{\new}(N)} a_f(P^2)\epsilon(f) = \sum_{f\in H^{\new}(N)} P \lambda_f(P^2)\epsilon(f). 
\]
More generally, if we consider $P^k$ Fourier coefficients, we apply the operator $(-1)T_{P^k} \circ W_N$ on $S^{\new}(N)$ and its trace is
\[
\sum_{f\in H^{\new}(N)} a_f(P^k)\epsilon(f) = \sum_{f\in H^{\new}(N)} P^{\frac{k}{2}} \lambda_f(P^k)\epsilon(f). 
\]
On the other hand, when $P\mid N$, %for $\epsilon_f(P) = \operatorname{sgn}(a_f(P)) = \pm 1$ 
we have the equality 
\[
\lambda_f(P^\nu) = \left(\frac{a_f(P)}{\sqrt{P}}\right)^\nu \text{ for all } \nu\geq 0.
\]
Recall that $a_f(P)=\pm1$ so, for $\nu$ even  we have 
\[
\lambda_f(P^{2\nu'}) = P^{-\nu'} \text{ for all } \nu'\geq 0.
\]
In particular, when $\nu'=1$, we have $\lambda_f(P^2) = \frac{1}{P}$.
%Coefficients_of_symmetric_square_L-functions.pdf




\subsection{Trace Formula}
We record a result of Skoruppa--Zagier \cite[Section~2]{skoruppa1987jacobi} that will be useful for us.
The following result is a special case of the formula in equation (7) of \emph{op.~cit.}
The result there is more general but since we restrict ourselves to $N$ square-free, the expression simplifies in our setting to the following

\begin{theorem}
\label{Skoruppa-Zagier}
With notation introduced above, in the case that $P\nmid N$
for $P$-power coefficients
\[
\sum_{f\in H^{\new}(N)} a_f(P^k)\epsilon(f) = \sum_{f\in H^{\new}(N)} P^{\frac{k}{2}} \lambda_f(P^k)\epsilon(f) = \frac{H_1(-4P^kN)} {2} + \sum_{0<r\leq 2 \frac{P^{\frac{k}{2}}}{\sqrt{N}}} H_1(r^2N^2 - 4P^{k}N) - \left(\sum_{i=0}^k P^i\right).     
\]
In particular, when $k=2$
\[
\sum_{f\in H^{\new}(N)} a_f(P^2)\epsilon(f) = \sum_{f\in H^{\new}(N)} P \lambda_f(P^2)\epsilon(f) = \frac{H_1(-4P^2N)} {2} + \sum_{0<r\leq 2P/\sqrt{N}} H_1(r^2N^2 - 4P^2N) - (1+P+P^2).     
\]

\end{theorem}

\begin{remark}
In the notation of \cite{skoruppa1987jacobi}, the quantity $n_1$ takes the value $N$ and $n_2 =1$.
A priori, the second term should have a coefficient $U_0(r\sqrt{N}/2P^{k/2})$ but we note that $U_0(x)=1$.
The final term in the expression is $\sigma_1(P^{k}) = \sum_{d\mid P^{k}} d = 1 + P + P^2 + \ldots + P^k$.

In the above formula, the Hurwitz class number $H_1(-d)$ is the number of equivalence classes with respect to $\SL_2(\Z)$ of positive-definite binary quadratic forms of discriminant $-d$ weighed by the number of automorphisms (i.e., with forms corresponding to multiples of $x^2 +y^2$ and $x^2 +xy+y^2$ counted with multiplicities $\frac{1}{2}$ and $\frac{1}{3}$, accordingly).
In other words, $H_1$ can be expressed in terms of the Gauss class number $h$ via: 
\[
H_1(-d) = \sum_{f\in \Z^{>0}, f^2\mid d} h(-d/f^2) +O(1),
\]
with the error term disappearing if $d$ is not of the form 3 or 4 times a square.
\end{remark}

Using the relationship between the Hurwitz class number $H_1(\cdot)$ and Gauss class number $h(\cdot)$ explained above, we see that
\[
H_1(-4P^kN) = \begin{cases}
\displaystyle{\sum_{j=0}^{k/2} h(-4P^{2(\frac{k}{2} - j)}N) + \sum_{j=0}^{k/2} h(-P^{2(\frac{k}{2} - j)}N)} + O(1) & \textrm{ when }k=\textrm{ even}\\
\displaystyle{\sum_{j=0}^{(k-1)/2} h(-4P^{2(\frac{k-1}{2} - j)}PN) + \sum_{j=0}^{(k-1)/2} h(-P^{2(\frac{k-1}{2} - j)}PN)} + O(1) & \textrm{ when }k=\textrm{ odd}.\end{cases}
\]
Throughout this article we assume that $P\neq 2$.
Since we assume that $\gcd(P,N)=1$ and that $N$ is square-free, the square factors of $4P^{k}N$ are $1, 4, P^2, 4P^2, \ldots, P^{\lfloor k/2 \rfloor}, 4P^{\lfloor k/2 \rfloor}$. 
The above expression simplifies to the following formula when $k=2$ (which is what is required for our main result)
\[
H_1(-4P^2N) = h(-4P^2N) + h(-P^2N) + h(-4N) + h(-N) + O(1).
\]
If $q$ is any prime and $r\geq 1$, we note that $q^2\mid N(r^2 N -4P^{k})$ is satisfied if $q^2\mid (r^2 N -4P^{k})$ or if $q\mid N$ and $q\mid 4P^{k}$.
The latter condition is satisfied precisely when $q=2$ (i.e., $N$ is even).
Writing $N=2N'$ (where $N'$ must now be odd), if $4d^2 \mid (r^2 N^2 -4P^{k}N)$, we can note that
\[
\frac{r^2 N^2 -4P^{k}N}{4d^2} = \frac{r^2 N'^2 -2P^{k}N'}{d^2}
\]
is not a square modulo 4 and the corresponding class number vanishes.
Indeed, we remind the reader that by Dirchlet's class number formula, for $d>4$, the Gauss class number $h(-d)=0$ whenever $-d \equiv 2 \text{ or }3\pmod{4}$.
%not a square because the top guy can not be a square.
It will therefore be enough to consider those square-divisors which satisfy $d^2\mid (r^2N - 4P^{k})$.  
In the general case, the trace formula becomes 
\begin{align*}
\sum_{f\in H^{\new}(N)} P \lambda_f(P^k)\epsilon(f) & =  \displaystyle{\sum_{j=0}^{\lfloor k/2 \rfloor} h(-4P^{2(\frac{k}{2} - j)}N) + \sum_{j=0}^{\lfloor k/2 \rfloor} h(-P^{2(\frac{k}{2} - j)}N)}{2} - \left(\sum_{i=1}^k P^i\right) \\
& \hspace{1cm} + \sum_{0<r\leq 2\sqrt{\frac{P^k}{N}}} \sum_{d^2\mid r^2N - 4P^{k}} h(N(r^2N - 4P^{k})/d^2) + O(1).
\end{align*}
When $k=2$ the trace formula further simplifies to
\begin{align*}
\sum_{f\in H^{\new}(N)} P \lambda_f(P^2)\epsilon(f) & =  \frac{h(-4P^2N) + h(-P^2N) + h(-4N) + h(-N)} {2} - (P+P^2) \\
& \hspace{1cm} + \sum_{0<r\leq 2P/\sqrt{N}} \sum_{d^2\mid r^2N - 4P^{2}} h(N(r^2N - 4P^{2})/d^2) + O(1).
\end{align*}


\section{Main Term Calculation via Averages of Gauss Class Numbers I}
\label{Section: Main Term Calculation 1}

The goal of this section is to estimate the Hurwitz class number $H_1(-4P^2N)$ which (as we have noted above) can be written as a sum of four Gauss class numbers.

Recall that if $-d\equiv 0 \text{ or }1\pmod{4}$ then the Gauss class number can be written in terms of a special value of an $L$-function.
More precisely,
\[
h(-d) = \frac{\sqrt{d}}{\pi} L(1, \chi_d)
\]
where $\chi_d$ is the quadratic Dirichlet character of modulus $d$ or $4d$ which can be calculated explicitly via the Kronecker symbol and $L(1, \chi_d)$ is the value at 1 of the Dirichlet series for the Kronecker symbol $\left( \frac{d}{\cdot}\right)$.
The calculation in this section will be separated into two cases, first when $-d\equiv 1\pmod{4}$ and second when $-d\equiv 0\pmod{4}$. 
The first calculation will allow us to estimate averages of  $h(-P^2N)$ and $h(-N)$ and the second will allow us to estimate averages of $h(-4P^2N)$ and $h(-4N)$.

When $\chi$ is a non-principal Dirichlet character of modulus $d$, for a truncation parameter $T$ we know %\DK{[add some appropriate reference and words]}
\[
L(1,\chi) = \sum_{n=1}^T \frac{\chi(n)}{n} + O\left(\frac{\sqrt{d} \log d}{T}\right).
\]

The main result we want to prove in this section is an analogue of \cite[Proposition~3.1]{Zub23}.

\begin{proposition}
\label{our version of Nina P3.1}
Let $P\neq 2$ be a prime and let $[X,X+Y]$ be an interval of length $Y=o(X)$.
Then as $X\rightarrow \infty$,
{\allowdisplaybreaks\begin{align*}
\frac{\zeta(2) \pi}{XY}\sum_{\substack{N\in [X,X+Y] \\ P\nmid N \\ N \text{ sq-free}}} \frac{h(-P^2 N)}{2} &+ \frac{h(- N)}{2} + \frac{h(-4P^2 N)}{2} + \frac{h(- 4N)}{2} \\
& = \frac{AP}{\sqrt{X}}+ O_\epsilon\left(\left(\frac{1}{\sqrt{X}}+\frac{P^{\frac{7}{6}}X^{\frac{1}{12} }}{Y^{\frac{5}{6}}}+\frac{PY}{X^{\frac32}}\right) (PXY)^\epsilon\right).
\end{align*}}
Here the error term $\rightarrow 0$ as $P,X\rightarrow\infty$ and $Y=o\left(\frac{X}{\log P^2 X}\right)$.
\end{proposition}

\begin{proof}
We prove that for a cut-off parameter $T$
\begin{align*}
\frac{\zeta(2) \pi}{XY}\sum_{\substack{N\in [X,X+Y] \\ P\nmid N \\ N \text{ sq-free}}} \frac{h(-P^2 N)}{2} &+ \frac{h(- N)}{2} + \frac{h(-4P^2 N)}{2} + \frac{h(- 4N)}{2} = \eqref{3-1-1 main equation cutoff} + \eqref{3-1-2 main equation cut off} + \eqref{3-2-1 main equation cut off} + \eqref{3-2-2 main equation cutoff}\\
& = \frac{AP}{\sqrt{X}} + O_{\epsilon}\left(\frac{1}{\sqrt{X}} +  \frac{P}{\sqrt{TX}} + \frac{PT^{\frac{1}{5}+\epsilon}X^{\frac{1}{10}+\epsilon}}{Y} + \frac{P Y\log T}{X^{\frac{3}{2}}} + \frac{P^2\log(P^2 X)}{T}\right).
\end{align*}
Choosing $T = \frac{(YP)^{\frac{5}{6} - \epsilon}}{X^{\frac{1}{12}}}$, the right side of the above expression becomes
\[
\frac{AP}{\sqrt{X}} +  O_\epsilon\left(\frac{1}{\sqrt{X}}+\frac{P^{\frac{7}{12}}}{Y^{\frac{5}{12}}X^{\frac{11}{24}}}+ \frac{(PY)^{1+\epsilon}}{X^{\frac32 -\epsilon }} + \frac{P^{\frac{7}{6}+\epsilon}X^{\frac{1}{12} + \epsilon}}{Y^{\frac{5}{6}-\epsilon}}\right).
\]
and the result follows.
\end{proof}


\subsection{When \texorpdfstring{$-d \equiv 1\pmod{4}$}{}}

Throughout this section $P\neq 2$ and $[X, X+Y]$ is an interval of length $Y=o(X)$.
We provide the following estimate for the first two terms in Proposition~\ref{our version of Nina P3.1}.

\begin{equation*}
\frac{\zeta(2)\pi}{YX}\sum_{\substack{N\in [X, X+Y] \\ P\nmid N\\ N \text{ 
sq-free}}} \frac{h(-P^2N)}{2} + \frac{h(-N)}{2} %& = \eqref{3-1-1 main equation} + \eqref{3-1-2 main equation}\\
= \frac{2A}{11} \frac{P}{\sqrt{X}} + O_\epsilon\left(\frac{1}{\sqrt{X}}+\frac{P^{\frac{7}{12}}}{Y^{\frac{5}{12}}X^{\frac{11}{24}}}+\frac{P^{\frac{7}{6} + \epsilon}}{Y^{\frac{5}{6}- \epsilon}X^{\frac{1}{12}- \epsilon}}+\frac{P^{\frac{7}{6}+\epsilon}X^{\frac{1}{12} + \epsilon}}{Y^{\frac{5}{6}-\epsilon}}\right). 
\end{equation*}

Here, the main term contribution is from the estimates in Lemma~\ref{3-1-1 main equation}.
The leading term of the expression in Lemma~\ref{3-1-2 main equation} contributes $\frac{1}{\sqrt{X}}$ to the error term of this summation and subsumes the error term $\frac{1}{P\sqrt{X}}$ arising in Lemma~\ref{3-1-1 main equation}.


\subsubsection{Averages of \texorpdfstring{$h(-P^2N)$}{}}
\label{sec 3-1-1}

\begin{lemma}
\label{3-1-1 main equation}
With notation as introduced above,
{\allowdisplaybreaks
\begin{equation*}
\frac{\zeta(2)\pi}{YX}\sum_{\substack{N\in [X, X+Y] \\ P\nmid N \\ N \text{ 
sq-free}}} \frac{h(-P^2N)}{2} = \frac{2AP}{11\sqrt{X}} + O_\epsilon\left(\frac{1}{P\sqrt{X}}+\frac{P^{\frac{7}{12}}}{Y^{\frac{5}{12}}X^{\frac{11}{24}}}+\frac{(PY)^{1+\epsilon}}{X^{\frac32 -\epsilon }} + \frac{P^{\frac{7}{6}+\epsilon}X^{\frac{1}{12} + \epsilon}}{Y^{\frac{5}{6}-\epsilon}}\right).
\end{equation*}
}
\end{lemma}

The first step is to obtain an expression for $\frac{\zeta(2)\pi}{YX}\sum h(-P^2N)$ in terms of a cut-off parameter $T$ where the sum runs over square-free $N \in [X, X+Y]$ such that  $P\nmid N$.
To ensure that the error-term is smaller than the main term, we choose the cut-off parameter appropriately.
The proof of the lemma occupies the remainder of this section.

\begin{proof}
We calculate the averages in intervals using the Gauss class number formula, i.e.,
{\allowdisplaybreaks
\begin{align*}
\frac{1}{P\sqrt{X}} \sum_{\substack{N\in [X, X+Y] \\ P\nmid N \\ N \text{ 
sq-free}}} h(-P^2N) &= \frac{1}{\pi} \sum_{\substack{N\in [X, X+Y]\\ P\nmid N \\ N \text{ sq-free} \\ N \equiv 3\pmod{4}}} \sqrt{\frac{N}{X}} L(1, \chi_{-P^2N})\\
&= \frac{1}{\pi}\sum_{\substack{N\in [X, X+Y]\\ P\nmid N \\ N \text{ sq-free} \\ N \equiv 3\pmod{4}}} \sqrt{\frac{N}{X}} \sum_{n=1}^T \frac{\left( \frac{-P^2N}{n}\right)}{n} + O\left(\frac{YP\sqrt{X}\log(P^2 X)}{T}\right)\\
&= \frac{1}{\pi} \sum_{\substack{N\in [X, X+Y]\\ P\nmid N \\ N \text{ sq-free} \\ N \equiv 3\pmod{4}}} \sum_{m=1}^{\sqrt{T}}   \frac{\sqrt{\frac{N}{X}}\left( \frac{-P^2N}{m^2}\right)}{m^2} + \frac{1}{\pi} \sum_{\substack{N\in [X, X+Y]\\ P\nmid N \\ N \text{ sq-free} \\ N \equiv 3\pmod{4}}} \sum_{\substack{n=1 \\ n\neq \square}}^T   \frac{\sqrt{\frac{N}{X}} \left( \frac{-P^2N}{n}\right)}{n} \\ 
\quad & \quad + O\left(\frac{YP\sqrt{X}\log(P^2 X)}{T}\right).
\end{align*}}

\noindent where to show the second equality we use the fact that $\chi_{-P^2N}$ is always a non-principal character when $N$ is square-free and $P\nmid N$.
%\KM{This is correct, I think we can just ignore the $P^2$ at least when $n$ is coprime to $P^2N$. }

Next, we calculate the two (double) sums appearing in the above expression separately.
Note that the first sum contains principal characters.

{
\allowdisplaybreaks
\begin{align*}
\Sq &= \frac{1}{\pi}\sum_{\substack{N\in [X, X+Y]\\ P\nmid N \\ N \text{ sq-free} \\ N \equiv 3\pmod{4}}} \sum_{m=1}^{\sqrt{T}}   \frac{\sqrt{\frac{N}{X}}\left( \frac{-P^2N}{m^2}\right)}{m^2} \\
& =\frac{1}{\pi}\sum_{m=1}^{\sqrt{T}} \frac{1}{m^2}\sum_{\substack{N\in [X, X+Y]\\ P\nmid N \\ N \equiv 3\pmod{4}}}    \mu^2(N)\left( \frac{-P^2N}{m^2}\right)\left(1 + \left(\sqrt{1 + \frac{N-X}{X}} - 1\right) \right) \\
%&= \frac{1}{\pi}\sum_{m=1}^{\sqrt{T}} \frac{1}{m^2}\sum_{\substack{N\in [X, X+Y]\\ P\nmid N \\ N \equiv 3\pmod{4}}}    \mu^2(N)\left( \frac{-P^2N}{m^2}\right) + O\left(Y \left(\sqrt{1 + \frac{Y}{X}} - 1\right)\right)\\
&= \frac{1}{\pi}\sum_{m=1}^{\sqrt{T}} \frac{1}{m^2} \sum_{\substack{N\in [X, X+Y]\\ P\nmid N \\ N \equiv 3\pmod{4}}} \mu^2(N)\left( \frac{P^2}{m^2}\right)\left( \frac{N}{m^2}\right) + O\left(Y \left(\sqrt{1 + \frac{Y}{X}} - 1\right)\right)\\
&= \frac{1}{\pi}\sum_{\substack{m=1\\ \gcd(P,m)=1}}^{\sqrt{T}} \frac{1}{m^2} \sum_{\substack{N\in [X, X+Y]\\ P\nmid N \\ N \equiv 3\pmod{4}}} \mu^2(N)\left( \frac{N}{m^2}\right) + O\left(Y \left(\sqrt{1 + \frac{Y}{X}} - 1\right)\right)\\
&= \frac{1}{\pi} \sum_{\substack{m=1\\ \gcd(P,m)=1}}^{\sqrt{T}} \frac{1}{m^2} \left(\sum_{N\in [X, X+Y]}    \mu^2(N)\left( \frac{N}{m^2}\right)\frac{\chi_1(N) - \chi_2(N)}{2}\right) + O\left(\frac{Y^2}{X}\right)\\
&= \frac{1}{\pi}\sum_{\substack{m=1\\ \gcd(P,m)=1}}^{\sqrt{T}} \frac{Y}{\zeta(2)} \frac{\eta(2m)}{2m^2} + O_{\epsilon}\left( m^{\frac{1}{5}+\epsilon}X^{\frac{3}{5}+\epsilon}\frac{1}{m^2}\right) + O\left(\frac{Y^2}{X}\right) \\
&= \frac{4YA}{11\pi\zeta(2)} + O_{\epsilon}\left( \frac{Y}{P^2} + \frac{Y}{\sqrt{T}} + X^{\frac{3}{5}+\epsilon} +\frac{Y^2}{X}\right) \text{ by Lemma~\ref{eta} where } A:= \prod_{p}\left(1 + \frac{p}{(p+1)^2 (p-1)} \right).
\end{align*}}
Here, $\chi_1$ and $\chi_2$ are characters modulo 4, and $\chi_1$ is principal.
The character $\left(\frac{N}{m^2}\right)\chi_1(N)$ is principal modulo $2m$ whereas, $\left(\frac{N}{m^2}\right)\chi_2(N)$ is always non-principal modulo $4m$.
Note that for the second last equality we use \cite[Lemma~6.7]{Zub23}.
Next we calculate the non-square term in a manner identical to the one above.

{
\allowdisplaybreaks
\begin{align*}
    \NSq &= \frac{1}{\pi} \sum_{\substack{N\in [X, X+Y]\\ P\nmid N \\ N \text{ sq-free} \\ N \equiv 3\pmod{4}}} \sum_{\substack{n=1 \\ n\neq \square}}^T \frac{\sqrt{\frac{N}{X}} \left( \frac{-P^2N}{n}\right)}{n}\\
    & = \frac{1}{\pi} \sum_{\substack{N\in [X, X+Y]\\ P\nmid N \\ N \text{ sq-free} \\ N \equiv 3\pmod{4}}} \sum_{\substack{n=1 \\ n\neq \square}}^{T} \frac{1}{n}  \left( \frac{-P^2N}{n}\right)\left(1 + \left(\sqrt{1 + \frac{N-X}{X}} - 1\right) \right) \\
    &=\frac{1}{\pi} \sum_{\substack{N\in [X, X+Y]\\ P\nmid N \\ N \text{ sq-free} \\ N \equiv 3\pmod{4}}} \sum_{\substack{n=1 \\ n\neq \square}}^{T} \frac{\left( \frac{-P^2N}{n}\right)}{n} + O\left(\frac{Y^2\sum_{n\leq T} \frac{1}{n}}{X} \right) \\
    &=\frac{1}{\pi} \sum_{\substack{N\in [X, X+Y]\\ P\nmid N \\ N \text{ sq-free} \\ N \equiv 3\pmod{4}}}  \sum_{\substack{n=1 \\ n\neq \square \\ \gcd(P,n)=1}}^{T} \frac{\left( \frac{-N}{n}\right)}{n} + O\left(\frac{Y^2\log T}{X} \right)  \\
    &\leq \frac{1}{\pi} \sum_{\substack{n=1 \\ n\neq \square}}^{T} \sum_{\substack{N\in [X, X+Y]\\ N \equiv 3\pmod{4} \\ N \text{ sq-free}}}   \frac{\left( \frac{-N}{n}\right)}{n} + O\left(\frac{Y^2\log T}{X} \right)  \\
    &=\frac{1}{\pi} \sum_{\substack{n=1 \\ n\neq \square}}^{T}\frac{\left( \frac{-1}{n}\right)}{n} \left( \sum_{\substack{N\in [X, X+Y] \\ N \text{ sq-free}}}   \left(\frac{N}{n}\right)   \frac{\chi_{1}(N)-\chi_2(N)}{2}\right) + O\left(\frac{Y^2\log T}{X} \right) \\
    &=\frac{1}{\pi} \sum_{\substack{n=1 \\ n\neq \square}}^{T} \frac{1}{n} O_{\epsilon}\left(n^{\frac{1}{5}+\epsilon}X^{\frac{3}{5}+\epsilon}\right) + O\left(\frac{Y^2\log T}{X} \right) \\
    &\ll_{\epsilon} T^{\frac{1}{5}+\epsilon}X^{\frac{3}{5}+\epsilon} + \frac{Y^2\log T}{X}.
\end{align*}}

Since $N$ is not a square, note that $\left(\frac{N}{n}\right)$ is non-principal.
Since $\left(\frac{N}{2}\right)$ is primitive modulo 8, the characters $\left(\frac{N}{n}\right)\chi_1(N)$ and $\left(\frac{N}{n}\right)\chi_2(N)$ are non-principal.
For the last equality, we use \cite[Lemma~6.7]{Zub23}.

In conclusion we obtain that for a truncation parameter $T$,

{\allowdisplaybreaks
\begin{equation}
\label{3-1-1 main equation cutoff}
\begin{split}
\frac{\zeta(2)\pi}{YX}\sum_{\substack{N\in [X, X+Y] \\ P\nmid N \\ N \text{ 
sq-free}}} \frac{h(-P^2N)}{2} & = \frac{2AP}{11\sqrt{X}} \\ 
& + O_\epsilon\left( \frac{1}{P \sqrt{X}} + \frac{P}{\sqrt{TX}} + \frac{PT^{\frac{1}{5}+\epsilon}X^{\frac{1}{10}+\epsilon}}{Y} + \frac{P Y\log T}{X^\frac{3}{2}} + \frac{P^2\log(P^2 X)}{T}\right).
\end{split}
\end{equation}
}

Choosing $T = \frac{(PY)^{\frac{5}{6}}}{X^{\frac{1}{12}}}$, completes the proof of the lemma.
\end{proof}



\subsubsection{Averages of \texorpdfstring{$h(-N)$}{}}

\begin{lemma}
\label{3-1-2 main equation} 
With notation as before
\begin{equation*}
\frac{\zeta(2)\pi}{YX}\sum_{\substack{N\in [X, X+Y] \\ P\nmid N \\ N \text{ 
sq-free}}} \frac{h(-N)}{2}  = \frac{2A}{11\sqrt{X}} + O_\epsilon\left(\frac{1}{(PY)^{\frac{5}{12}}X^{\frac{11}{24}}} + \frac{P^{\frac{1}{6}  + \epsilon}X^{\frac{1}{12} + \epsilon}}{Y^{\frac{5}{6} - \epsilon}%X^{\frac{1}{12} - \epsilon}
}+\frac{Y^{1+\epsilon}P^\epsilon}{X^{3/2-\epsilon}}+\frac{X^{\frac{1}{12}+\epsilon}}{Y^{\frac{5}{6}-\epsilon}P^{\frac{5}{6}-\epsilon}}%\frac{P^{\frac{7}{6}}X^{\frac{1}{12}}}{Y^{\frac{5}{6}}}
\right).
\end{equation*}
\end{lemma}


\begin{proof}
We begin by calculating the average
{\allowdisplaybreaks
\begin{align*}
