\vspace{0.3cm}

Regarding $\tau=0.1$, using that the next eigenvalue has absolute value at least $2.7$, we have using the spectral density bounds in (\ref{spectralparameterbound}) that
\begin{align*}
\left|\sum_{i\neq0}(\sinc^7)'(s_i(0.1))\right|&\leq\sum_{k\geq 0}\max_{t\in[2.7+k,2.7+k+1]}|(\sinc^7)'(t)|\cdot \#\left\{|s_i(0.1)|\in[2.7+k,2.7+k+1]\right\}\\
&\leq 0.0017
\end{align*}
so that the conclusion follows.

\begin{remark}\label{numericalapprox}
At the practical level, for simplicity we bound the infinite sum by evaluating its first forty terms. This does not introduce a significant error because we have$$(\sinc^7)'(t)=O(t^{-7}),$$while the spectral density bounds are $O(t^2)$. This tail can be bounded explicitly using bounding (using $|\cos(x)|\leq1)$ the sum of $H_{6,\nu}$ over the closed geodesics with
\begin{equation*}
S_Y=\sum \frac{\ell(\gamma_0)}{|1-e^{\mathbb{C}\ell(\gamma)}||1-e^{-\mathbb{C}\ell(\gamma)}|}H_{6,0}(\ell(\gamma))
\end{equation*}
which is readily computable, see also Remark \ref{mainasymptotic}.
\end{remark}
At $\tau=0.2$, we have that the next eigenvalue has absolute value at least $2.4$ and obtain correspondingly that
\begin{equation*}
\left|\sum_{i\neq0}(\sinc^7)'(s_i(0.2))\right|\leq 0.0104,
\end{equation*}
and conclude again.





\vspace{0.3cm}


\subsection{Proving uniqueness and transversality.}
We are left to show that for the small eigenvalue
\begin{equation*}
s_0'(\tau)\neq 0\text{ for }\tau\in [0.1537,0.1556].
\end{equation*}
In order to do this, we will study the derivative of the trace formula (\ref{derivativetraceodd}) for the odd test function $K_7$ in (\ref{xconv7}). We have  

\begin{equation*}
-i\widehat{K_7}'(t)=(\sinc^7)''(t)
\end{equation*}
where explicitly the second derivative is
\begin{equation*}
(\sinc^7)''(t)=-\frac{7\sin^5(t)\cdot\left(\sin(t)\cdot((t^2-2)\sin(t)+2t\cdot\cos(t))-6(\sin(t)-t\cos(t))^2\right)}{t^9}
\end{equation*}
for $t\neq0$, with value $-7/3$ at zero; see Figure \ref{sinc7secondder} for the plot.

\begin{figure}
\centering
  \includegraphics[width=.5\linewidth]{secondderivativesinc7.png}
  \label{fig:sub1}
  \caption{The plot of the second derivative of $\sinc^7$ for $t\geq0$. This function is very small for $t \gtrsim 2.5$.}
  \label{sinc7secondder}
\end{figure}

\vspace{0.3cm}

For our purposes, we will rewrite the trace formula (\ref{derivativetraceodd}) as
\begin{equation*}
-i\widehat{K_7}'(s_0(\tau))s'_0(\tau)=2\cdot\widetilde{\Gamma}_{K_7}(\tau)+i \sum_{j\neq0} \widehat{K_7}'(s_j(\tau))s'_j(\tau)
\end{equation*}
where $\widetilde{\Gamma}_{K_7}(t)$ denotes the geometric side and we think of the infinite sum on the right hand side as an error term; in particular our goal will be to show that the inequality
\begin{equation}\label{desiredbound}
\left|\sum_{j\neq 0}\widehat{K_7}'(s_j(\tau))s'_j(\tau)\right|< 2|\widetilde{\Gamma}_{K_7}(\tau)|
\end{equation}
holds for $\tau\in [0.1537,0.1556]$, which implies $s_0'(\tau)\neq0$ in the interval.
\\
\par
Looking for example at the midpoint of the interval $\tau_0=0.15465$, we have
\begin{equation*}
\widetilde{\Gamma}_{K_7}(\tau_0)\approx-14.4905;
\end{equation*}
in fact, we have
\begin{equation*}
\widetilde{\Gamma}_{K_7}(\tau)\in[-14.4906,-14.4832]\text{ for all }\tau\in [0.1537,0.1556].
\end{equation*}
Using that the next eigenvalue of $D_{B_\tau}$ has absolute value at least $2.5$ throughout the interval (which is readily checked by evaluating $J_{2.5}(\tau)$), we see as in the previous subsection that
\begin{align*}
\left|\sum_{i\neq0}\widehat{K_7}'(s_i(\tau))\right|&\leq\sum_{k\geq 0}\max_{t\in[2.5+k,2.5+k+1]}|(\sinc^7)''(t)|\cdot \#\{|s_i(\tau)|\in[2.5+k,2.5+k+1]\}\\
&\leq 0.0470
\end{align*}
for all parameters $\tau$ in the interval. Again, we estimate the sum as in Remark \ref{numericalapprox}. As explained in Appendix \ref{C0bounds}, we have $C_Y\leq 3.5151$ for \#357,  so that by Lemma \ref{eigenbound} the we have the bound
\begin{equation*}
|s_i'(\tau)|\leq 2\pi C_Y\leq 22.0861\text{ for all }\tau\in[0,1],
\end{equation*}
so that inequality (\ref{desiredbound}) holds as
\begin{equation*}
0.0470\times 22.0861\leq 1.0381.
\end{equation*}
This concludes the proof of Theorem \ref{thm1} for the self-conjugate spin$^c$ structure on \#357.





