\begin{remark}
In the opposite direction, there are two natural ways to provide \textit{lower} bounds on $C_Y$ in terms of the geometry and topology of $Y$. First, if $\gamma$ is a closed geodesic, denoting $[\gamma]\in H_1(Y;\mathbb{Z})/\mathrm{tors}=\mathbb{Z})$ we have
\begin{equation*}
|[\gamma]|=\left|\int_{\gamma}\alpha\right|\leq C_Y\cdot \ell(\gamma)
\end{equation*}
so that
\begin{equation*}
C_Y\geq\sup\frac{[\gamma]}{{\ell(\gamma)}},
\end{equation*}
the supremum being taken over all closed geodesics. Similarly, taking a circle-valued primitive $f:Y\rightarrow \mathbb{R}/\mathbb{Z}$ of $\alpha$, the coarea formula implies that
\begin{equation*}
 \int_{\mathbb{R}/\mathbb{Z}}\mathrm{Area}(f^{-1}(t))dt\leq \int_Y|\alpha|\leq C_Y\cdot\vol(Y).
\end{equation*}
With some care about the singularities of $f$, the fact that in for a class in $H_2(Y;\mathbb{Z})$ the least area norm is at least $\pi$ times the Thurston norm \cite{BD} implies then that
\begin{equation*}
C_Y\geq \frac{\pi\cdot\mathrm{Th}(Y)}{\vol(Y)},
\end{equation*}
where we denote by $\mathrm{Th}(Y)$ the Thurston norm of the generator of $H_2(Y;\mathbb{Z})$.
\end{remark}
In fact, our method will work more in general for $b_1>0$ and any class $a\in H^1(Y;\mathbb{Z})$. We take as input a Dirichlet domain $\mathsf{D}\subset\mathbb{H}^3$ for $Y$ together with the face-pairing maps $\{g_i\}_{i\in I}$, which are elements in $\mathrm{Isom}^+(\mathbb{H}^3)$ (as computed for example by SnapPy). First of all, we interpret the class $a$ as a homomorphism
\begin{equation*}
\varphi_a: \pi_1(Y)\rightarrow \mathbb{Z}.
\end{equation*}
Our concrete goal is then to describe an explicit function
\begin{equation}\label{aclass}
F:\mathsf{D}\rightarrow \mathbb{R}
\end{equation}
with the property that
\begin{equation}\label{equivariant}
F(g_i\cdot x)=F(x)+\varphi_a(g_i)\text{ for all }x\in\partial\mathsf{D}\text{ and } i\in I,
\end{equation}
so that the closed $1$-form $dF$ represents $a$.
\par
In order to do this, we first we will fix a triangulation $\mathcal{T}=\{T_i\}$ of $\mathsf{D}$ in simplices with geodesic boundary, and consider functions obtained by assigning values at the vertices of the triangulation, and extended in a canonical `linear' fashion.
\\
\par
In what follows, we first discuss the geometry of such linear extensions, and then discuss the specific details of our implementation. An important simplifying assumption we will make is that all the tetrahedra in our triangulation admit a \textit{circumcenter}, i.e. the four vertices are equidistant from some point in $\mathbb{H}^3$; unlike the euclidean case, this is a non-trivial condition.





\vspace{0.5cm}
\textbf{Geometry of linear extensions in hyperbolic space.} A geodesic tetrahedron $T$ in hyperbolic space comes with a natural parametrization
\begin{equation*}
\eta:\Delta\rightarrow T
\end{equation*}
from the standard $3$-simplex
\begin{equation*}
\Delta=\left\{(t_0,t_1,t_2,t_3)\lvert t_i\geq 0 \text{ and }\sum t_i\leq 1\right\}\subset\mathbb{R}^4
\end{equation*}
given by convex combinations, the definition of which we now recall (see for example \cite{Mar}). We consider the hyperboloid model $\mathsf{I}$ for hyperbolic space. To set notation, we consider the standard Minkowski space given by $\mathbb{R}^4$ with coordinates $x=(x_0,x_1,x_2,x_3)$ and Lorentzian inner product
\begin{equation*}
\langle x,y\rangle=-x_0y_0+\sum_{i=1}^3x_iy_i.
\end{equation*}
Then $\mathsf{I}$ is the upper half of the two-sheeted hyperboloid
\begin{equation*}
\mathsf{I}=\left\{x\lvert \langle x,x\rangle=-1, x_0>0\right\}
\end{equation*}
equipped with restriction of the Lorentzian inner product, which is a Riemannian metric of constant curvature $-1$. In this model, the geodesics are given exactly by the intersection of $\mathsf{I}$ with planes $\mathbb{R}^4$, and the distance between points $x,y\in \mathsf{I}$ is given by
\begin{equation*}
d(x,y)=\cosh^{-1}(-\langle x, y\rangle).
\end{equation*}
Denoting
\begin{equation*}
\|x\|=\sqrt{-\langle x,x\rangle},
\end{equation*}
we have the hyperbolic analogue of the radial projection map
\begin{align*}
P: \{x\lvert  \langle x,x\rangle<0,x_0>0\}&\rightarrow \mathsf{I}\\
x&\mapsto \frac{x}{\|x\|}.
\end{align*}
Given two distinct points $x,y\in \mathsf{I}$, the geodesic segment in $\mathsf{I}$ between them is parametrized (not at constant speed) by
\begin{equation}\label{convex}
P((1-t)x+ty) \text{ for }t\in[0,1].
\end{equation}
In particular, given four points $v_i$ in $\mathsf{I}$ (which are linearly independent in $\mathbb{R}^4$), the geodesic simplex $T$ in $\mathsf{I}$ they determine is parametrized via the convex combinations
\begin{align*}
\eta: \Delta&\rightarrow T\\
(t_0,t_1,t_2,t_3)&\mapsto P(\sum t_iv_i).
\end{align*}
Of course, this is the composition of the projection $P$ with the linear parametrization of the affine simplex spanned by the $v_i$ in $\mathbb{R}^4$. Notice that this parametrization is equivariant with respect to the action of $\mathrm{Isom}^+(\mathbb{H}^3)=\mathrm{SO}_0(3,1)$. This is because a point $p\in \Delta$ is the projection of a unique point in the convex hull in $\mathbb{R}^4$ of the vertices of $\Delta$, and isometries act via linear maps on such convex hull.
\\
\par
Suppose now we are given a function $f$ on the vertices of the geodesic tetrahedron $T$. This naturally extends to a function
\begin{equation}\label{linext}
F: T\rightarrow \mathbb{R}
\end{equation}
given as the composition
\begin{equation}\label{compositionLip}
T\stackrel{\eta^{-1}}{\longrightarrow}\Delta{\longrightarrow}\mathbb{R}
\end{equation}
where the latter is the unique affine linear function on $\Delta$ agreeing with $f\circ\eta$ on the vertices of $\Delta$; we will refer to $F$ as the linear extension of $f$. The goal of this section is then to estimate from above the norm of $dF$, or equivalently the Lipschitz constant of $F$, in terms of $f$ and $T$, under the simplifying assumption that $T$ admits a circumcenter; this can be achieved with the following steps.
\\
\par
\textit{Step 0: find the circumcenter of $T$. }This is done via linear algebra by noticing that the circumcenter $c$ of $T$ lies at the intersection of the bisectors of pairs of vertices $v_i,v_j$, which are described by the equations
\begin{equation*}
\langle z, v_i\rangle=\langle z,v_j\rangle.
\end{equation*}
Notice that the existence of the circumcenter is equivalent to the fact that the one-dimensional space of solutions to these equations in $\mathbb{R}^4$ intersects the hyperboloid $\mathsf{I}$.
\\
\par
\textit{Step 1: move the circumcenter to the origin $o=(1,0,0,0)$.}
We can apply isometry that maps $c$ to $o$ (e.g. one can just use the reflection at the midpoint of the segment). Under this isometry, the the tetrahedron $T$ is mapped to $\tilde{T}$, a geodesic tetrahedron with circumcenter at the origin $o$. In particular, its vertices $\tilde{v_i}$ lie on the boundary of the ball $B_R\subset\mathsf{I}$ of radius $R$ around $o$; by equivariance, the natural parametrization
\begin{equation*}
\tilde{\eta}: \Delta\rightarrow \tilde{T}
\end{equation*}
is obtained by composing the isometry with $\eta$. Because of this, we can assume from now on that our vertices lie on the boundary of $B_R$.
\\
\par
\textit{Step 2: fixing a Euclidean structure on $\Delta$.} In order to evaluate the Lipschitz constant of (\ref{linext}), we will factor it as in (\ref{compositionLip}) and use the chain rule. To do so, we \textit{identify} $\Delta$ with the affine span of the $\{v_i\}$, equipped with the Riemannian metric induced by the standard Euclidean norm $x_0^2+x_1^2+x_2^2+x_3^2$ on $\mathbb{R}^4$, which we denote as $\Delta_{\mathrm{hor}}$, where the subscript reminds us that $\Delta_{\mathrm{hor}}$ is horizontal (i.e. $x_0$ is constant). We then have to study the Lipschitz constants of the maps 
\begin{equation}\label{compositionLip}
T\stackrel{P^{-1}_{\mathrm{hor}}}{\longrightarrow}\Delta_{\mathrm{hor}}{\longrightarrow}\mathbb{R}
\end{equation}
where to simplify the notation we denote the inverse of $P:\Delta_{\mathrm{hor}}\rightarrow T$ by $P^{-1}_{\mathrm{hor}}$. Of course, the Lipschitz constant of the second map is directly computed in terms of linear algebra, so the remaining non-trivial computations consists of providing an upper bound on the Lipschitz constant of $P^{-1}_{\mathrm{hor}}$.
\\
\par
\textit{Step 3: the Lipschitz constant of $P_{\mathrm{hor}}^{-1}$.}
We show that the Lipschitz constant of $P_{\mathrm{hor}}^{-1}$ is $\cosh(R)$ by considering more in general the map $P_R^{-1}$ from the ball of radius $R$ around $o$ in $\mathsf{I}$ to the horizontal disk with the same boundary (see Figure \ref{PR}) as follows.
\par
Let us introduce coordinates $(z,t,\vartheta)$ on $\mathbb{R}^{4}$ where $z=x_0$ and $(t,\vartheta)$ are polar coordinates in the $\mathbb{R}^{3}$ corresponding to the last $3$ coordinates. Consider the points
\begin{equation*}
(\sqrt{1+a^2}, a,\vartheta)\text{ for }\vartheta\in S^2
\end{equation*}
on $\mathsf{I}$, which form the boundary of the ball $B_R$ of radius
\begin{equation*}
R=\cosh^{-1}(\sqrt{1+a^2})
\end{equation*}
around the origin $o=(1,0,0,0)$. The horizontal ball in this situation is just the disk
\begin{equation*}
(\sqrt{1+a^2},t,\vartheta)\text{ for }t\in[0,a]\text{ and }\vartheta\in S^2,
\end{equation*}
equipped with the standard metric Euclidean
\begin{equation*}
dt^2+t^2 g_{S^{2}}.
\end{equation*}
In these coordinates projection map $P_R$ from the horizontal ball to $B_R$ is given by
\begin{equation*}
(t,\vartheta)\mapsto \left(\frac{\sqrt{1+a^2}}{\sqrt{1+a^2-t^2}}, \frac{t}{\sqrt{1+a^2-t^2}},\vartheta \right).  
\end{equation*}
The exponential map at the origin in hyperbolic space is given by
\begin{equation*}
(s,\vartheta)\mapsto (\sinh(s),\vartheta,\cosh(s));
\end{equation*}
recall that in these coordinates the hyperbolic metric is given by
\begin{equation*}
g_{\mathrm{hyp}}=ds^2+\sinh^2(s)g_{S^{n-1}}.
\end{equation*}
In particular, denoting by $s(t)$ the $s$-coordinate of $P(t,\vartheta)$, we have
\begin{equation*}
s(t)=\mathrm{arcsinh}\left(\frac{t}{\sqrt{1+a^2-t^2}}\right),
\end{equation*}
so that the pullback of the hyperbolic metric to the horizontal disk is given by
\begin{equation*}
P_R^*(g_{\mathrm{hyp}})=\frac{a^2+1}{(1+a^2-t^2)^2}dt^2+\frac{t^2}{1+a^2-t^2}g_{S^{n-1}}.
\end{equation*}
From this we see that the differential of the inverse $P_R^{-1}$ multiplies lengths by
\begin{equation*}
\frac{(1+a^2-t^2)}{\sqrt{a^2+1}}\text{ and }\sqrt{1+a^2-t^2}
\end{equation*}
in the radial and tangential directions respectively, and both of these quantities have maximum $\sqrt{1+a^2}=\cosh(R)$ at the origin.

\begin{figure}
  \centering
\def\svgwidth{0.8\textwidth}
\input{tetrahedra.pdf_tex}
