{\bf Proof of Proposition 2.1.} Based on (2.1)-(2.5), we can obtain that
\begin{equation*}
	\begin{split}
		\xi_{\tau}(\bm{X})&=\bm{X}^{\top}\bm{\beta}_{\tau}=
		\bm{X}^{\top}\int_0^1\bm{\gamma}(\bar{\tau})\text{J}_{\tau}
		(\bar{\tau})d\bar{\tau}=\int_0^1\bm{X}^{\top}\bm{\gamma}(\bar{\tau})
		\text{J}_{\tau}(\bar{\tau})d\bar{\tau}\\
		&=\int_0^1q_{\bar{\tau}}(\bm{X})\text{J}_{\tau}(\bar{\tau})d\bar{\tau}
		=\int_{y\in \mathbb{R}}y\text{J}_{\tau}\{\text{F}(y|\bm{X})\}d\text{F}(y|\bm{X})\\
		&=E[\bm{Y}\text{J}_{\tau}\{\text{F}(\bm{Y}|\bm{X})\}]=E(\bm{Z}_{\bm{X},{\tau}}),
	\end{split}
\end{equation*}
where $\bm{Z}_{\bm{X},{\tau}}$ has cumulative distribution function $\text{F}_{\bm{Z}_{\bm{X},{\tau}}}=\text{H}_{\tau}\{\text{F}(\cdot|\bm{X})\}$.
When $\tau=0.5^{1/r}$ and $r\in \mathbb{N}\backslash \{0\}$, for any $z\in \mathbb{R}$, we have
\begin{equation*}
	\begin{split}
		\text{F}_{\bm{Z}_{\bm{X},{\tau}}}(z)=\text{H}_{\tau}\{\text{F}(z|\bm{X})\}
=\{\text{F}(z|\bm{X})\}^r=P\left(\max(Y_{\bm{X}}^1,\ldots,Y_{\bm{X}}^{r})\leqslant z\right),
	\end{split}
\end{equation*}
so that $\xi_{\tau}(\bm{X})
=E(\bm{Z}_{\bm{X},{\tau}})=E\{\max(Y_{\bm{X}}^1,\ldots,Y_{\bm{X}}^{r})\}$ according to
$\bm{Z}_{\bm{X},{\tau}}=\max(Y_{\bm{X}}^1,\ldots,Y_{\bm{X}}^{r})$. Similarly, we can prove that $\xi_{\tau}(\bm{X})
=E\{\min(Y_{\bm{X}}^1,\ldots,Y_{\bm{X}}^{r})\}$ under $\tau=1-0.5^{1/s}$ and $s\in \mathbb{N}\backslash \{0\}$. Because,
for any $z\in \mathbb{R}$,
\begin{equation*}
	\begin{split} 1-\text{F}_{\bm{Z}_{\bm{X},{\tau}}}(z)=1-\text{H}_{\tau}\{\text{F}(z|\bm{X})\}=\{1-\text{F}(z|\bm{X})\}^s
		=P\left(\min(Y_{\bm{X}}^1,\ldots,Y_{\bm{X}}^{r})> z\right).
	\end{split}
\end{equation*}
\\
\par
{\bf Proof of Theorems 2.1 and 2.2.} The results of Theorems 2.1 and 2.2 can be obtained directly from the following proofs of theorems 3.1 and 3.2 under $N=0$ and $\bm{\alpha}^*=\bm{\alpha}_0$.
\\
\par
{\bf Proof of Theorem 3.1.}
{\bf To establish consistency.}
Denote
\begin{equation*}
	\begin{split}
		\tilde{L}(\bm{\alpha})=\sum_{i=1}^{n}L(Y_i,\bm{X}_i,\bm{\alpha})
		+\sum_{i=n+1}^{n+N}\bm{Z}_i^{\top}\hat{\varphi}(\bm{\alpha}).
	\end{split}
\end{equation*}
Note that $\tilde{L}(\bm{\alpha})$ is the loss function in equation (3.2). We first show that
$\tilde{L}(\bm{\alpha})$ is invariant under affine transformation on $\bm{Z}=(1,\tilde{\bm{Z}}^{\top})^{\top}$, where $\tilde{\bm{Z}}$ is the remainder of $\bm{Z}$ after removing the first element. Assume that $\tilde{\bm{Z}}_i=\bm{M}\tilde{\bm{Q}}_i+\bm{b}$ for any fixed nonsingular $(d-1)\times (d-1)$ matrix $\bm{M}$ and $d-1$ vector $\bm{b}$, where $\tilde{\bm{Z}}_i$ is the $i$-th observation of $\tilde{\bm{Z}}$. Then, we can rewrite $\bm{Z}_i$ as
$$
\bm{Z}_i=\left(
\begin{array}{ll}
	1&{\bf 0}^{\top}_{q-1}\\
	\bm{b}&\bm{M}
\end{array}
\right)
\bm{Q}_i,
$$
where $\bm{Q}_i=(1,\tilde{\bm{Q}}_i^{\top})^{\top}$. Then, for any $\bm{\alpha}$, we can obtain
\begin{equation*}
	\begin{split}
		\tilde{L}(\bm{\alpha})=&
		\sum_{i=1}^{n}L(Y_i,\bm{X}_i,\bm{\alpha})
		+\sum_{i=n+1}^{n+N}\bm{Z}_i^{\top}
		\left(\frac{1}{n}\sum_{i=1}^{n}\bm{Z}_i\bm{Z}_i^{\top}\right)^{-1}
		\frac{1}{n}\sum_{i=1}^{n}\bm{Z}_iL(Y_i,\bm{X}_i,\bm{\alpha})\\
		=&\sum_{i=1}^{n}L(Y_i,\bm{X}_i,\bm{\alpha})
		+\sum_{i=n+1}^{n+N}\bm{Q}_i^{\top}
		\left(\frac{1}{n}\sum_{i=1}^{n}\bm{Q}_i\bm{Q}_i^{\top}\right)^{-1}
		\frac{1}{n}\sum_{i=1}^{n}\bm{Q}_iL(Y_i,\bm{X}_i,\bm{\alpha}).
	\end{split}
\end{equation*}
Therefore, we consider $E(\bm{Z}\bm{Z}^{\top})=\bm{I}_d$ and $E(\bm{Z})=(1,\bm{0}_{d-1}^{\top})^{\top}$ in the following proofs according to the above affine transformation invariant property.
Let
\begin{equation}
	\begin{split}
		\bar{L}(\bm{\alpha})=&\sum_{i=1}^{n}L(Y_i,\bm{X}_i,\bm{\alpha})
		+NE(\bm{Z}^{\top})\{E(\bm{Z}\bm{Z}^{\top})\}^{-1}
		\frac{1}{n}\sum_{i=1}^{n}\bm{Z}_iL(Y_i,\bm{X}_i,\bm{\alpha})\\
		=&\frac{n+N}{n}\sum_{i=1}^{n}L(Y_i,\bm{X}_i,\bm{\alpha}).
	\end{split}
\end{equation}
\par
Next, we proof that $\sup_{\bm{\alpha}\in\Theta}|\tilde{L}(\bm{\alpha})-\bar{L}(\bm{\alpha})|=o_p(1)$. Then, by Lemma 1 in \cite{r48} and conditions {\bf C2} and {\bf C5}, for large enough constants $c_1$ and $c_2$, we have
\begin{equation}
	\begin{split}
		&|\tilde{L}(\bm{\alpha})-\bar{L}(\bm{\alpha})|\\
		=&
		\left|\left[\sum_{i=n+1}^{n+N}\bm{Z}_i^{\top}
		\left(\frac{1}{n}\sum_{i=1}^{n}\bm{Z}_i\bm{Z}_i^{\top}\right)^{-1}
		-NE(\bm{Z}^{\top})\{E(\bm{Z}\bm{Z}^{\top})\}^{-1}\right]
		\frac{1}{n}\sum_{i=1}^{n}\bm{Z}_iL(Y_i,\bm{X}_i,\bm{\alpha})\right|\\
		\leq&\left\|\sum_{i=n+1}^{n+N}\bm{Z}_i^{\top}
		\left(\frac{1}{n}\sum_{i=1}^{n}\bm{Z}_i\bm{Z}_i^{\top}\right)^{-1}
		-NE(\bm{Z}^{\top})\{E(\bm{Z}\bm{Z}^{\top})\}^{-1}\right\|_2
		\left\|\frac{1}{n}\sum_{i=1}^{n}\bm{Z}_iL(Y_i,\bm{X}_i,\bm{\alpha})\right\|_2\\
		\leq&c_1\left\|\left\{\sum_{i=n+1}^{n+N}\bm{Z}_i^{\top}-NE(\bm{Z}^{\top})\right\}
		\left(\sum_{i=1}^{n}\bm{Z}_i\bm{Z}_i^{\top}\right)^{-1}\right\|_2\\
		&+c_1N\left\|E(\bm{Z}^{\top})
		\left[\left(\frac{1}{n}\sum_{i=1}^{n}\bm{Z}_i\bm{Z}_i^{\top}\right)^{-1}
		-E(\bm{Z}^{\top})\{E(\bm{Z}\bm{Z}^{\top})\}^{-1}\right]\right\|_2\\
		\leq&c_2(N^{1/2}+Nn^{-1/2}),
	\end{split}
\end{equation}
where $\|\cdot\|_2$ is $L_2$ norm. Then, by equations (A.1) and (A.2), and $n\rightarrow\infty$, we have
\begin{equation}
	\begin{split}
		&\sup_{\bm{\alpha}\in\Theta}|\tilde{L}(\bm{\alpha})/(n+N)
		-E\{L(\bm{Y},\bm{X},\bm{\alpha})\}|\\
		&\leq \sup_{\bm{\alpha}\in\Theta}|\tilde{L}(\bm{\alpha})-\bar{L}(\bm{\alpha})|/(n+N)
		+\sup_{\bm{\alpha}\in\Theta}|\bar{L}(\bm{\alpha})/(n+N)-E\{L(\bm{Y},\bm{X},\bm{\alpha})\}|
		=o_p(1).
	\end{split}
\end{equation}
(A.3) implies that $\|\text{Vec}(\tilde{\bm{\alpha}}-\bm{\alpha}^*)\|_2=o_p(1)$ according to $\bm{\alpha}^*$ is the unique minimizer of $E\{L(\bm{Y},\bm{X},\bm{\alpha})\}$.  Thus, the consistency is proved.
\\
\par
{\bf To show asymptotic normality.} By equation (3.2) and Taylor's expansion of $\nabla_{\text{Vec}(\bm{\alpha})}\tilde{L}(\bm{\alpha})|_{\bm{\alpha}=\tilde{\bm{\alpha}}}$ at $\bm{\alpha}^*$ as
\begin{equation}
	\begin{split}
		\bm{0}=\nabla_{\text{Vec}(\bm{\alpha})}\tilde{L}(\bm{\alpha})|_{\bm{\alpha}=\tilde{\bm{\alpha}}}
		=\nabla_{\text{Vec}(\bm{\alpha})}\tilde{L}(\bm{\alpha})|_{\bm{\alpha}=\bm{\alpha}^*}+
		\nabla^2_{\text{Vec}(\bm{\alpha})}
		\tilde{L}(\bm{\alpha})|_{\bm{\alpha}=\bar{\bm{\alpha}}}\text{Vec}(\tilde{\bm{\alpha}}
		-\bm{\alpha}^*),
	\end{split}
\end{equation}
where $\bar{\bm{\alpha}}$ is between $\tilde{\bm{\alpha}}$ and $\bm{\alpha}^*$.
We first consider $\nabla_{\text{Vec}(\bm{\alpha})}\tilde{L}(\bm{\alpha})|_{\bm{\alpha}=\bm{\alpha}^*}$.
Denote $\tilde{\bm{Z}}_N=\sum_{i=n+1}^{n+N}\bm{Z}_i/N$, $\tilde{\bm{Z}}_n=\sum_{i=1}^{n}\bm{Z}_i/n$, $\hat{{\bm \Sigma}}_{\bm{Z}}=\sum_{i=1}^{n}\bm{Z}_i\bm{Z}_i^{\top}/n$ and
$\bm{U}_i=S_i(\bm{\alpha}^*)-\bm{A}^{\top}\bm{Z}_i$ with $S_i(\bm{\alpha}^*)=\nabla_{\text{Vec}(\bm{\alpha})}L(Y_i,\bm{X}_i,\bm{\alpha})|_{\bm{\alpha}=\bm{\alpha}^*}$. Thus, we can obtain
\begin{equation}
	\begin{split}
		\nabla_{\text{Vec}(\bm{\alpha})}\tilde{L}(\bm{\alpha})|_{\bm{\alpha}=\bm{\alpha}^*}
		=&nS(\bm{\alpha}^*)+\frac{N}{n}\sum_{i=1}^{n}S_i(\bm{\alpha}^*)\bm{Z}_i^{\top}
		\hat{{\bm \Sigma}}_{\bm{Z}}^{-1}\tilde{\bm{Z}}_N\\
		=&nS(\bm{\alpha}^*)+\frac{N}{n}
		\sum_{i=1}^{n}(\bm{A}^{\top}\bm{Z}_i+\bm{U}_i)\bm{Z}_i^{\top}\hat{{\bm \Sigma}}_{\bm{Z}}^{-1}\tilde{\bm{Z}}_N\\
		=&nS(\bm{\alpha}^*)+N\bm{A}^{\top}\left\{\tilde{\bm{Z}}_N-E(\bm{Z})\right\}
		+N\bm{A}^{\top}E(\bm{Z})\\
		&+\frac{N}{n}\sum_{i=1}^{n}\bm{U}_i\bm{Z}_i^{\top}
		\hat{{\bm \Sigma}}_{\bm{Z}}^{-1}\tilde{\bm{Z}}_n+\frac{N}{n}\sum_{i=1}^{n}\bm{U}_i\bm{Z}_i^{\top}
		\hat{{\bm \Sigma}}_{\bm{Z}}^{-1}
		\left\{\tilde{\bm{Z}}_N-\tilde{\bm{Z}}_n\right\}\\
		=&\left\{nS(\bm{\alpha}^*)+\frac{N}{n}\sum_{i=1}^{n}\bm{U}_i\right\}
		+N\bm{A}^{\top}\left\{\tilde{\bm{Z}}_N-E(\bm{Z})\right\}\\
		&+o_p(n^{-1/2}(n+N))\\
		=&\left\{(n+N)S(\bm{\alpha}^*)-N\bm{A}^{\top}\tilde{\bm{Z}}_n\right\}
		+N\bm{A}^{\top}\left\{\tilde{\bm{Z}}_N-E(\bm{Z})\right\}\\
		&+o_p(n^{-1/2}(n+N)),
	\end{split}
\end{equation}
where
the forth equality holds because of $\bm{A}^{\top}E(\bm{Z})=\bm{0}$ by the definition of $\bm{\alpha}^*$, $
\hat{{\bm \Sigma}}_{\bm{Z}}^{-1}\tilde{\bm{Z}}_n=(1,\bm{0}_{d-1}^{\top})^{\top}$ by Lemma 2 in \cite{r47}, and $$\frac{N}{n}\sum_{i=1}^{n}\bm{U}_i\bm{Z}_i^{\top}
\hat{{\bm \Sigma}}_{\bm{Z}}^{-1}
\left\{\tilde{\bm{Z}}_N-\tilde{\bm{Z}}_n\right\}=o_p(n^{-1/2}(n+N))$$ by proof similar to Theorem 1 in \cite{r47}.
Finally, we consider $\nabla^2_{\text{Vec}(\bm{\alpha})}\tilde{L}(\bm{\alpha})|_{\bm{\alpha}=\bar{\bm{\alpha}}}$ as
\begin{equation}
	\begin{split}
		&\nabla^2_{\text{Vec}(\bm{\alpha})}\tilde{L}(\bm{\alpha})|_{\bm{\alpha}=\bar{\bm{\alpha}}}\\
		=&
		\nabla^2_{\text{Vec}(\bm{\alpha})}\bar{L}(\bm{\alpha})|_{\bm{\alpha}=\bar{\bm{\alpha}}}
		+\left\{\nabla^2_{\text{Vec}(\bm{\alpha})}\tilde{L}(\bm{\alpha})|_{\bm{\alpha}=\bar{\bm{\alpha}}}
		-\nabla^2_{\text{Vec}(\bm{\alpha})}\bar{L}(\bm{\alpha})|_{\bm{\alpha}=\bar{\bm{\alpha}}} \right\}
		\\
		=&(n+N){\bf H}+\left\{\nabla^2_{\text{Vec}(\bm{\alpha})}\bar{L}(\bm{\alpha})|_{\bm{\alpha}
			=\bar{\bm{\alpha}}}-(n+N){\bf H}\right\}
		+O_p(N^{1/2}+Nn^{-1/2})\\
		=&(n+N)\{{\bf H}+o_p(1)\},
	\end{split}
\end{equation}
where the second equation is similar to (A.2) by conditions {\bf C2} and {\bf C4}, and the last equation is according to (A.1). Then, from (A.4)-(A.6), we have
\begin{equation}
	\begin{split}
		\text{Vec}(\tilde{\bm{\alpha}}-\bm{\alpha}^*)
		=-{\bf H}^{-1}\left[\left\{S(\bm{\alpha}^*)-\frac{N}{n+N}\bm{A}^{\top}\tilde{\bm{Z}}_n
		\right\}
		+\frac{N}{n+N}\bm{A}^{\top}\left\{\tilde{\bm{Z}}_N-E(\bm{Z})\right\}
		\right]+o_p(n^{-1/2}).
	\end{split}
\end{equation}
Therefore, we can prove the theorem.
\\
\par
{\bf Proof of Theorem 3.2.} From the $\tilde{\beta}_{\tau}=\tilde{\alpha}\int_0^1\bm{b}(\bar{\tau})\text{J}_{\tau}(\bar{\tau})d\bar{\tau}$ and (A.7), the theorem can be directly proven.


