\section{Proofs}
\label{SecProofs}


In this section, we turn to the proofs of our main claims,
including~\Cref{ThmWildOptBound,ThmRhatError} in
in~\Cref{SecThmWildOptBound,SecThmRhatError}, respectively.

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%


\subsection{Proof of~\Cref{ThmWildOptBound}}
\label{SecThmWildOptBound}


Our proof involves relating the optimism and its wild variant
via the intermediate quantities
\begin{subequations}
\begin{align}
\OptDagger(\fhat) & = \frac{1}{\numobs} \sum_{i=1}^\numobs w_i
\big(\fhat(x_i) - \fproj(x_i) \big), \quad \mbox{and} \\
%
  \ZoptRade(r) & \defn \sup_{f \in \MyBall{\fproj}{r}} \Big[ \FULLSUM
    \rade{i} \noise_i \big(f(x_i) - \fproj(x_i) \big) \Big].
\end{align}
\end{subequations}

\noindent The following lemma shows how they can be used to bound the
optimism:
\begin{lemma}
\label{LemOptBound}
For any $\tpar > 0$, we have
\begin{subequations}  
\begin{align}
\label{EqnOptBound}
\Opt(\fhat) & \leq \OptDagger(\fhat) + \empnorm{\fproj - \fstar} \:
\DevTerm \qquad \mbox{with probability at least $1 - e^{-t^2}$.}
\end{align}
Moreover, for any $r \geq \|\fhat - \fproj\|_\numobs$ and any $t > 0$,
we have
\begin{align}
\label{EqnZoptRadeConc}
\max \big \{ \OptDagger(\fhat), \ZoptRade(r) \big \} & \leq
\ExsRade[\ZoptRade(r)] + r \DevTerm.
\end{align}
\end{subequations}
with probability at least $1 - 2 e^{-t^2}$.
\end{lemma}
\noindent See~\Cref{SecLemOptBound} for the proof of this claim. \\



Based on~\Cref{LemOptBound}, we see that for any $r \geq \|\fhat -
\fproj\|_\numobs$, we have the upper bound
\begin{align}
\label{EqnFizzy}  
  \Opt(\fhat) & \leq \ExsRade[\ZoptRade(r)] + \big \{ r +
  \empnorm{\fproj - \fstar} \big \} \; \DevTerm
\end{align}
\mbox{with probability at least $1 - 3 e^{-t^2}$.}  Our next step is
to relate the expectation $\ExsRade[\ZoptRade(r)]$ to the wild
optimism $\OptWild(\fhat)$.  In order to do so, we make use of the
intermediate family of random variables
\begin{align}
\label{EqnDefnZwildRade}  
  \ZwildRade(r) & \defn \sup_{f \in \MyBall{\fhat}{r}} \Big[ \FULLSUM
    \rade{i} \noise_i \big(f(x_i) - \fhat(x_i) \big) \Big].
\end{align}


\noindent The following auxiliary result relates the expectations of
$\ZoptRade(r)$ and $\ZwildRade(r)$, and involves the estimation error
$\rhat \defn \empnorm{\fhat - \fproj}$.
%
\begin{lemma}
\label{LemZopt2Wild}
We have the deterministic bound
\begin{subequations}
\begin{align}
\label{EqnZopt2Wild}
\ExsRade[\ZoptRade(r)] & \leq \ExsRade[\ZwildRade(r + \rhat)]
\end{align}
along with the bound
\begin{align}
\label{EqnZwildRadeConc}
\ExsRade[\ZwildRade(r)] & \leq \ZwildRade(r) +  r \DevTerm \qquad
\mbox{with probability at least $1 - e^{-t^2}$.}
\end{align}
\end{subequations}
\end{lemma}
\noindent See~\Cref{SecLemZopt2Wild} for the proof of this claim.
\\


The two bounds from~\Cref{LemZopt2Wild} imply that
for any $r \geq \rhat$, we have
\begin{align*}
  \ExsRade[\ZoptRade(2 r)] & \leq \ZwildRade(2 r) + (2 r) \;  \DevTerm
\end{align*}
with probability at least $1 - e^{-t^2}$.
Combined with our earlier inequality~\eqref{EqnFizzy}, we have shown that
\begin{align}
\label{EqnPurpleGlasses}  
  \Opt(\fhat) & \leq \ZwildRade(2 r) + \big \{ 3 r + \empnorm{\fproj -
    \fstar} \big \} \; \DevTerm
\end{align}
with probability at least $1 - 4 e^{-t^2}$.  Our final step is to
relate $\ZwildRade(2 r)$ to the wild optimism $\OptWild(\fwild)$ for a
suitably chosen noise scale $\rho$.

\begin{lemma}
  \label{LemFinal}
For any radius $r$, we have 
\begin{align}
\label{EqnFinal}  
\ZwildRade(2 r) & \leq \OptWild(\fwild) + \AppError,
  \end{align}
where $\fwild$ is the wild solution with $\|\fwild - \fhat\|_\numobs =
2r$.
\end{lemma}
%
\noindent See~\Cref{SecProofLemFinal} for the proof of this claim. \\


Finally, by applying the bound~\eqref{EqnFinal} to our earlier
inequality~\eqref{EqnPurpleGlasses}, we find that
\begin{align*}
  \Opt(\fhat) & \leq \OptWild(\fwild) + \big \{ 3 r + \empnorm{\fproj
    - \fstar} \big \} \; \DevTerm + \AppError,
\end{align*}
with probability at least $1 - 4 e^{-t^2}$, as claimed
in~\Cref{ThmWildOptBound}.


