\subsection{Auxiliary lemmas for~\Cref{ThmWildOptBound}}
\label{SecAuxiliaryLemmas}
In this section, we collect together the proofs of the auxiliary
lemmas used in the proof of~\Cref{ThmWildOptBound}.


%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%


\subsubsection{Proof of~\Cref{LemOptBound}}
\label{SecLemOptBound}

We split our analysis into two parts, corresponding to the
two claims in the lemma.

\paragraph{Proof of the bound~\eqref{EqnOptBound}:}
Beginning with the definition of the optimism~\eqref{EqnDefnOptimism},
we can add and subtract terms involving $\fproj$, thereby obtaining
\begin{align*}
\Opt(\fhat) = \underbrace{\empinner{\wnoise}{\fhat -
    \fproj}}_{\OptDagger(\fhat)} + \underbrace{\empinner{\wnoise}{\fproj -
    \fstar}}_{\Term}.
\end{align*}
It remains to bound the term $\Term$.  Since variable $\wnoise_i$ has
a distribution symmetric around zero, we can write $\wnoise_i =
\rade{i} |\wnoise_i|$, where $\rade{i} \in \{-1, +1 \}$ is a random
sign (Rademacher variable) independent of $|\wnoise_i|$.  Conditioning
on the absolute values, we can represent $\Term$ as a realization of
the linear (and hence convex) function
\begin{align*}
\big( \rade{1}, \ldots, \rade{\numobs} \big) & \mapsto G(\rade{})
\defn \empinner{ \rade{} |\wnoise|}{\fproj - \fstar} \; = \; \Big \{
\frac{1}{\numobs} \sum_{i=1}^\numobs \rade{i} |\wnoise_i|
\big(\fproj(x_i) - \fstar(x_i) \big) \Big \}.
\end{align*}
Letting $\rade{}$ and $\rade{}'$ be two Rademacher sequences,
applying the Cauchy--Schwarz inequality yields
\begin{align*}
  \big| G(\rade{}) - G(\rade{}') \big| \; = \; \FULLSUM (\rade{i} -
  \rade{i}') \, |\wnoise_i| \big(\fproj(x_i) - \fstar(x_i) \big)
  %
  & \leq \frac{1}{\numobs} \big(\sum_{i=1}^\numobs \wnoise_i^2 \big(
  \fproj(x_i) - \fstar(x_i) \big)^2\big)^{1/2} \; \|\rade{} -
  \rade{}'\|_2 \\
  %
 & \leq \tfrac{\|\wnoise\|_\infty}{\sqrt{\numobs}} \empnorm{\fproj -
    \fstar} \, \|\rade{} - \rade{}'\|_2
\end{align*}
showing that the function $G$ is $L$-Lipschitz with $L \defn
\tfrac{\|\wnoise\|_\infty}{\sqrt{\numobs}} \empnorm{\fproj - \fstar}$.
Since $\Exs_{\rade{}} [G(\rade{})] = 0$, standard concentration
results for convex/Lipschitz functions of Rademacher variables
(cf. Theorem 3.24 in the book~\cite{Wai19}) guarantee that
\begin{align*}
G(\rade{}) & \leq \tfrac{2 \|\wnoise\|_\infty \tpar}{\sqrt{\numobs}}
\; \empnorm{\fproj - \fstar} \qquad \mbox{with probability at least $1
  - e^{-\tpar^2}$.}
\end{align*}



\paragraph{Proof of
the bound~\eqref{EqnZoptRadeConc}:} We condition on the vector
$|\wnoise|$ of absolute values throughout this proof.  Letting
$\rade{} \in \{-1, +1 \}^\numobs$ be an i.i.d. vector of Rademacher
variables, we can view the random variable $\ZoptRade(r)$ as a
function
\begin{align*}
  \rade{} \mapsto H(\rade{}) \defn \ZoptRade(r) \defn
  \sup_{f \in
  \MyBall{\fproj}{r}} \Big[ \FULLSUM \rade{i} |\noise_i| \big(f(x_i) -
  \fproj(x_i) \big) \Big].
\end{align*}
As in our previous proof, we can write $\noise_i = \radetil_i
|\noise_i|$, where $\radetil_i \in \{-1, +1 \}$ is a Rademacher
variable independent of $|\noise_i|$.  Thus, we recognize the random
variable $\Zopt(r)$ as a particular realization of the random variable
defined by $H$.  Consequently, bounding the difference $\Zopt(r) -
\ExsRade[\ZoptRade(r)]$ is equivalent to establishing an upper tail
bound for $H(\rade{})$ in terms of its expectation
$\ExsRade[H(\rade{})]$.  In particular, the claim is equivalent to
showing that $H(\rade{}) \leq \ExsRade[H(\rade{})] + r \: (\DevTerm)$
with probability at least $1 - e^{-\tpar^2}$.

In order to establish this claim, we again make use of concentration
bounds for convex and Lipschitz functions of independent bounded
random variables (cf. Theorem 3.24 in the book~\cite{Wai19}).  As a
supremum of linear functions, the function $H$ is convex.  The claimed
bound follows as long as we can establish the Lipschitz bound
\begin{align}
\label{EqnHclaim}  
  |H(\rade{}) - H(\rade{}')| & \leq L \|\rade{} - \rade{}'\|_2 \qquad
  \mbox{for $L = \tfrac{\|\wnoise\|_\infty}{\sqrt{\numobs}} r$,}
\end{align}
valid for any pair of Rademacher vectors $\rade{}, \rade{}' \in \{-1,
+1 \}^\numobs$.

Let $g$ by any function that achieves the supremum defining
$H(\rade{})$.  We can then write
\begin{align*}
  H(\rade{}) - H(\rade{}') & \leq \Big[ \FULLSUM \rade{i} |\noise_i|
    \big(g(x_i) - \fproj(x_i) \big) \Big] - \Big[ \FULLSUM \rade{i}'
    |\noise_i| \big(g(x_i) - \fproj(x_i) \big) \Big] \\
  %
  & = \FULLSUM \big(\rade{i} - \rade{i}' \big) |\noise_i| \big(g(x_i)
  - \fproj(x_i) \big).
\end{align*}
Applying the Cauchy--Schwarz inequality yields
\begin{align*}
  H(\rade{}) - H(\rade{}') \; \leq \; \frac{1}{\numobs} \big \{
  \sum_{i=1}^\numobs \noise_i^2 \big(g(x_i) - \fproj(x_i) \big)^2 \big
  \}^{1/2} \; \big( \|\rade{} - \rade{}'\|_2\big) & \leq
  \frac{\|\wnoise\|_\infty}{\sqrt{\numobs}} \empnorm{g - \fproj}
  \|\rade{} - \rade{}'\|_2 \\ & \stackrel{(\star)}{\leq}
  \frac{\|\wnoise\|_\infty}{\sqrt{\numobs}} \, r \, \|\rade{} -
  \rade{}'\|_2.
\end{align*}
where the final bound $(\star)$ follows since $\empnorm{g - \fproj}
\leq r$.  The same argument applies with the roles of $\rade{}$ and
$\rade{}'$ reversed, from which the claimed Lipschitz
bound~\eqref{EqnHclaim} follows.



%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

\subsubsection{Proof of~\Cref{LemZopt2Wild}}
\label{SecLemZopt2Wild} 

We prove each of the two claims in turn.

\paragraph{Proof of the bound~\eqref{EqnZopt2Wild}:}
Let $g \in \MyBall{\fproj}{r}$ be any function that achieves the
supremum defining $\ZoptRade(r)$.  In terms of this function, we have
the decomposition $\ZoptRade(r) = \FULLSUM \rade{i} \noise_i
\big(g(x_i) - \fproj(x_i) \big) = \Term_1 + \Term_2$, where
\begin{align*}
\Term_1 & \defn \FULLSUM \rade{i} \noise_i \big(g(x_i) - \fhat(x_i)
\big), \quad \mbox{and} \quad \Term_2 \defn \FULLSUM \rade{i} \noise_i
\big(\fhat(x_i) - \fproj(x_i) \big).
\end{align*}
By the triangle inequality, we have
\begin{align*}
\empnorm{g - \fhat} & \leq \empnorm{g - \fproj} + \empnorm{\fproj -
  \fhat} \; \leq \; 2 r.
\end{align*}
where the final step follows since $\fhat$ and $g$ belong the ball
$\MyBall{\fproj}{r}$. Consequently, we have shown that
\begin{align*}
\Term_1 & \leq \sup_{f \in \MyBall{\fhat}{2 r}} \FULLSUM \rade{i}
\noise_i \big(g(x_i) - \fhat(x_i) \big), \quad \mbox{and hence} \quad
\ExsRade[\Term_1] \leq \ExsRade[ \ZwildRade(2 r)].
\end{align*}
As for the second term, we have
\begin{align*}
\ExsRade[\Term_2] & = \ExsRade \Big[ \FULLSUM \rade{i} \noise_i
  \big(\fhat(x_i) - \fproj(x_i) \big) \Big] \; = \; 0,
\end{align*}
using the fact that $\rade{i}$ is a Rademacher variable independent of
the original noise vector $\wnoise_i$, and hence $\fhat$ as well.
Putting together the pieces, we have shown that
\begin{align*}
\ExsRade[\ZoptRade(r)] & \leq \ExsRade[\Term_1] \; = \;
\ExsRade[\ZwildRade(2 r)],
\end{align*}
thus establishing the claim~\eqref{EqnZopt2Wild}
of~\Cref{LemZopt2Wild}.

\paragraph{Proof of the bound~\eqref{EqnZwildRadeConc}:}
The random variable $\ZwildRade(r)$ has a structure analogous to
$\ZoptRade(r)$, so that this claim follows by an argument entirely
analogous to that used to prove the claim~\eqref{EqnZoptRadeConc}
from~\Cref{LemOptBound}.


%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%


\subsubsection{Proof of~\Cref{LemFinal}}
\label{SecProofLemFinal}
By definition of the wild noise $\wtil_i = y_i - \ftil(x_i)$, we have
\begin{align*}
\rade{i} \wnoise_i & = \rade{i} \wtil_i + \rade{i} (\ftil(x_i) -
\fstar(x_i)).
\end{align*}
Consequently, from the definition of  $\ZwildRade$ combined with
the triangle inequality, we can write
\begin{align}
  \ZwildRade(2r) & =
  \sup_{f \in \MyBall{\fhat}{2r}} \Big[ \FULLSUM
    \rade{i} \noise_i \big(f(x_i) - \fhat(x_i) \big) \Big]  \notag \\
  %
  & \leq \sup_{f \in \MyBall{\fhat}{2 r}} \Big[ \FULLSUM \rade{i}
    \wtil_i \big(f(x_i) - \fhat(x_i) \big) \Big] + \sup_{f \in
    \MyBall{\fhat}{2r}} \Big[ \FULLSUM \rade{i} \big (\ftil(x_i) -
    \fstar(x_i) \big) \big(f(x_i) - \fhat(x_i) \big) \Big] \notag \\
  %
\label{EqnRavenBound}  
  & = \Zwild(2 r) + \AppError.
\end{align}
Finally, by~\Cref{LemOpt2Complex}, we have the equivalence $\Zwild(2
r) = \OptWild(\fwild)$ for the wild solution $\fwild$ with noise scale
$\rho$ chosen to ensure that $\|\fwild - \fhat\|_\numobs = 2 \rho$.








