\subsection{Proof of~\Cref{ThmRhatError}}
\label{SecThmRhatError}

We now turn to the proof of~\Cref{ThmRhatError}, which provides upper
bounds on the estimation error $\rhat \defn \|\fhat -
\fproj\|_\numobs$.



%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

\subsubsection{Proof of the bound~\eqref{EqnRhatError}}

Our proof of this claim requires two auxiliary results, which we begin
by stating.

\begin{lemma}
  \label{LemRhatBasic}
Given a procedure $\Meth$ that is firmly non-expansive~\eqref{EqnFirm}
around $\fstar$, the error \mbox{$\rhat \defn \empnorm{\fhat -
    \fproj}$} satisfies the bound
\begin{align}
\label{EqnRhatBasic}
\rhat^2 \leq \Zopt(\rhat).
\end{align}
\end{lemma}
\noindent See~\Cref{SecLemRhatBasic} for the proof. \\


\noindent We also require the following generalization of the
bound~\eqref{EqnZoptRadeConc} from~\Cref{LemOptBound}.  In
particular, it allows us to bound $\Zopt(r)$ for a random radius (such
as $\rhat$).
\begin{lemma}
\label{LemZconcRandom}
For any scalar $s \geq 3$, we have
\begin{align}
\label{EqnColdUpper}  
\Zopt(r) & \leq \ExsRade \big[\ZoptRade \big([\oneplus] \; r \big)
  \big] + \tfrac{4 \|\noise\|_\infty}{s} \: r^2
\end{align}
uniformly for all $r \geq \frac{s^2}{\sqrt{\numobs}}$ with
probability at least $1 - e^{-s^2}$.
\end{lemma}
%
\noindent See~\Cref{SecLemZconcRandom} for the proof. \\

Equipped with these lemmas, let us now complete the proof of the
theorem.  Fix some $s \geq 3$.  We either have $\rhat \leq
s^2/\sqrt{\numobs}$, or we may assume that $\rhat >
s^2/\sqrt{\numobs}$.  The remainder of our proof assumes that the
latter inequality holds.

We have
\begin{align*}
  \rhat^2 & \stackrel{(i)}{\leq} \Zopt(\rhat) \; \stackrel{(ii)}{\leq}
  \; \ExsRade \big[\ZoptRade \big([\oneplus] \; \rhat \big) \big] +
  \tfrac{4 \|\noise\|_\infty}{s} \: \rhat^2,
\end{align*}
where step (i) follows from~\Cref{LemRhatBasic}; and inequality (ii)
holds with probability at least $1 - e^{-s^2}$, based
on~\Cref{LemZconcRandom}.  By applying the bound~\eqref{EqnZopt2Wild}
from~\Cref{LemZopt2Wild} with $r = \rhat$, we find that
\begin{subequations}
\begin{align}
  \label{EqnAustinOne}
\rhat^2 & \leq \ExsRade \big[\ZwildRade \big([\twoplus] \; \rhat \big)
  \big] + \tfrac{4 \|\noise\|_\infty}{s} \: \rhat^2.
\end{align}
Next we apply the bound~\eqref{EqnZwildRadeConc}
from~\Cref{LemOptBound} with the choice $t = \rhat \sqrt{\numobs}/s$,
thereby obtaining\footnote{To be clear, while $\rhat$ is a random
radius, this randomness is independent of the Rademacher randomness
that defines $\ZwildRade$, so that we do not to use a uniform radius
result.}
\begin{align}
\label{EqnAustinTwo}  
\ExsRade[\ZwildRade \big ([\twoplus] \rhat \big)] & \leq \ZwildRade
\big([\twoplus] \; \rhat \big) + \tfrac{2 \|\noise\|_\infty}{s} \:
\rhat^2,
\end{align}
\end{subequations}
with probability at least $1 - e^{-t^2}$.  With our choice $t = \rhat
\sqrt{\numobs}/s$, we have $t^2 = \rhat^2 \numobs/s^2 \geq s^2$ since
we have assumed that $\rhat \geq s^2/\sqrt{\numobs}$ in this portion
of the argument; as consequence, the bound~\eqref{EqnAustinTwo} holds
with probability at least $1 - e^{-s^2}$.

By combining inequalities~\eqref{EqnAustinOne}
and~\eqref{EqnAustinTwo}, with probability at least $1 - 2 e^{-s^2}$,
we have
\begin{align*}
  \rhat^2 & \leq \ZwildRade \big([\twoplus] \; \rhat \big) + \tfrac{4
    \|\noise\|_\infty}{s} \: \rhat^2 \; \stackrel{(\star)}{\leq} \;
  \Zwild \big([\twoplus] \; \rhat \big) + \tfrac{4
    \|\noise\|_\infty}{s} \: \rhat^2 + \AppError,
\end{align*}
where step $(\star)$ follows inequality~\eqref{EqnRavenBound} from the
proof of~\Cref{LemFinal} in~\Cref{SecProofLemFinal}.  (In particular,
we use the bound~\eqref{EqnRavenBound} with the choice $ r = 1/2 \big(
[\twoplus] \; \rhat)$.)


Modulo the replacement of $s$ by $t$, we have thus established the
claim~\eqref{EqnRhatError} from~\Cref{ThmRhatError}.  (The additional
term $\tpar^2/\numobs$ arises from taking into account the possibility
that $\rhat \leq \tpar/\sqrt{\numobs}$ in our argument.)




\subsubsection{Proof of the bound~\eqref{EqnWildRefit}}
\label{SecCorWildRefit}
In order to prove the bound~\eqref{EqnWildRefit}, we require the
following auxiliary result.
\begin{lemma}
\label{LemZwildConcave}  
For any convex function class $\Fclass$, the function $u \mapsto
\Zwild(u)$ is concave on the interval $[0, \infty]$, and hence we have
the non-increasing property
  \begin{align}
    \label{EqnZwildConcave}
    \frac{\Zwild(s)}{s} \leq \frac{\Zwild(t)}{t} \qquad \mbox{for any
      $s \geq t > 0$.}
  \end{align}
\end{lemma}
\noindent See~\Cref{SecLemZwildConcave} for the proof.


Let us now prove the stated bound~\eqref{EqnWildRefit}.  Either we
have $\rhat \leq \rwild$, or $\rhat > \rwild$.  In the latter case, we
can write
\begin{align*}
\Zwild([\twoplust] \rhat) \; = \; [\twoplust] \rhat
\tfrac{\Zwild([\twoplust] \rhat)}{[\twoplust] \rhat} & \; \leq \;
      [\twoplust] \rhat \tfrac{\Zwild([\twoplust] \rwild)}{[\twoplust]
        \rwild} \\
%
& \; = \; \rhat \tfrac{\Zwild([\twoplust] \rwild)}{ \rwild},
\end{align*}
where the inequality follows from equation~\eqref{EqnZwildConcave}
in~\Cref{LemZwildConcave}.  Combining with
inequality~\eqref{EqnRhatError} from~\Cref{ThmRhatError} yields the
claim~\eqref{EqnWildRefit}.



\subsection{Auxiliary lemmas for~\Cref{ThmRhatError}}

In this section, we collect together proofs of the auxiliary
lemmas involved in~\Cref{ThmRhatError}.

\subsubsection{Proof of~\Cref{LemRhatBasic}}
\label{SecLemRhatBasic}

To prove this claim, we first observe that by definition $\fhat =
\Meth(\fstar + \wnoise)$ and $\fproj = \Meth(\fstar)$.  Since the
estimator $\Meth$ is firmly non-expansive around $\fstar$, we have
\begin{align*}
\rhat^2 = \empnorm{\fhat - \fproj}^2 = \empnorm{\Meth(\fstar +
  \wnoise) - \Meth(\fstar)}^2 & \leq \empinner{\wnoise}{\fhat -
  \fproj} \\
%
& = \FULLSUM \noise_i \big(\fhat(x_i) - \fproj(x_i) \big) \\
%
& \stackrel{(\dagger)}{\leq} \Zopt(\rhat),
\end{align*}
where inequality $(\dagger)$ follows from the definition of $\Zopt$.

\subsubsection{Proof of~\Cref{LemZconcRandom}}
\label{SecLemZconcRandom}

For an arbitrary $s > 0$, we apply the bound~\eqref{EqnZoptRadeConc}
with $t \defn \numobs r/s$ to obtain
\begin{align}
\label{EqnMammoth}
\Prob\big[\ZnewHat(r) \geq \ExsRade[\ZoptRade(r)] + \tfrac{2
    \|\noise\|_\infty}{s} \; r^2 \big] & \; \stackrel{(i)}{\leq} \;
e^{-\tfrac{r^2}{s^2} \numobs} \; \stackrel{(ii)}{\leq} \; e^{-s^2}.
\end{align}
where the final inequality (ii) follows as long as $r \geq
s^2/\sqrt{\numobs}$.

Now let $\Event$ be the event the bound~\eqref{EqnColdUpper} is
violated for some $r \geq \frac{s^2}{\sqrt{\numobs}}$.  Our strategy
is to exploit the tail bound~\eqref{EqnMammoth}(i) to prove that
$\Prob[\Event] \leq e^{-s^2}$.  In order to do so, we first define the
increasing sequence
\begin{align*}
q_0 \defn \tfrac{s^2}{\sqrt{\numobs}} \quad \mbox{and} \quad q_m \defn
(\oneplus)^m q_0 \qquad \mbox{for $m = 1, 2, 3 \ldots$,}
\end{align*}
and then decompose the event of interest as $\Event = \cup_{m
  =0}^\infty \Event_m$, where
\begin{align*}
  \Event_m \defn \Big \{ \exists r \in [q_m, q_{m+1}) \quad \mbox{such
      that the bound~\eqref{EqnColdUpper} is violated} \Big \}.
\end{align*}
We claim that it suffices to show that
\begin{align}
\label{EqnProvidence}  
\Prob[\Event_m] & \leq e^{-\frac{\numobs}{s^2} q_{m+1}^2} \qquad
\mbox{for each $m = 0, 1, 2, \ldots$.}
\end{align}
Taking this inequality as given, we can then apply the union bound to
obtain
\begin{align*}
\Prob[\Event] \leq \sum_{m = 0}^\infty \Prob[\Event_m] \;
\stackrel{(i)}{\leq} \; \sum_{m=0}^\infty e^{-\frac{\numobs}{s^2}
  q_{m+1}^2} & \stackrel{(ii)}{\leq} e^{-s^2} \sum_{m=0}^\infty e^{- 2
  (m + 1) s} \; \stackrel{(iii)}{\leq} \; e^{-s^2},
\end{align*}
where step (i) follows from the bound~\eqref{EqnProvidence}.  In order
to verify inequality (ii), we observe that
\begin{align*}
 \frac{\numobs}{s^2} q_{m+1}^2 \; = \; \frac{\numobs}{s^2} \, \big(
 \oneplus \big)^{2 (m+1)} q_0^2 & \geq \frac{\numobs}{s^2} q_0^2 \big \{ 1 + 2 (
 m + 1) (1/s) \big \} \\
 %
 & = s^2 + 2 (m + 1) s,
\end{align*}
using the fact that $(1 + (1/s))^{2 (m+1)} \geq 1 + 2 (m+1) (1/s)$,
and the equality $\frac{\numobs}{s^2} q_0^2 = s^2$.  Finally, step
(iii) follows since $\sum_{m=0}^\infty e^{- 2 (m + 1) s} \leq
\sum_{m=1}^\infty (1/2)^m = 1$, since the assumption that $s \geq 3$
implies that $e^{-2 s} \leq \tfrac{1}{2}$.


\paragraph{Proof of the bound~\eqref{EqnProvidence}:}

So as to reduce clutter, introduce the shorthand \mbox{$\Ztrue(r)
  \defn \ExsRade[\ZoptRade(r)]$.}  If the event $\Event_m$ holds, then
we are guaranteed to have some $r \in [q_m, q_{m+1}]$ such that
\begin{align*}
\ZnewHat(q_{m+1}) \stackrel{(i)}{\geq} \ZnewHat(r) &
\stackrel{(ii)}{\geq} \Ztrue( [\oneplus] r) + \tfrac{4
  \|\noise\|_\infty}{s} r^2 \\
%
& \stackrel{(iii)}{\geq} \Ztrue(q_{m+1}) + \tfrac{4
  \|\noise\|_\infty}{s} q_m^2 \\
%
& \stackrel{(iv)}{\geq} \Ztrue(q_{m+1}) + \tfrac{2
  \|\noise\|_\infty}{s} q_{m+1}^2,
\end{align*}
where step (i) follows since $q_{m+1} \geq r$ and the function $u
\mapsto \Zopt(u)$ is non-decreasing in $u$; inequality (ii) follows by
definition of the event $\Event_m$; inequality (iii) holds since $r
\geq q_m$ and $[\oneplus] r \geq [\oneplus] q_m = q_{m+1}$; and step
(iv) follows since
\begin{align*}
\tfrac{q_{m}^2}{q_{m+1}^2} & = \frac{1}{[\oneplus]^2} \geq \frac{1}{(1
  + \frac{1}{3})^2} \; = \; \frac{9}{16} \; \geq \; \frac{1}{2}
\end{align*}
using the assumption $s \geq 3$.

From this string of inequalities, we can conclude that
\begin{align*}
  \Prob[\Event_m] & \leq \Prob \Big[ \ZnewHat(q_{m+1}) \geq
    \Ztrue(q_{m+1}) + \tfrac{2 \|\noise\|_\infty}{s} q_{m+1}^2 \Big]
  \; \stackrel{(v)}{\leq} \; e^{-\frac{\numobs}{s^2} q_{m+1}^2},
\end{align*}
where inequality (v) follows by applying the
bound~\eqref{EqnMammoth}(i) with $r = q_{m+1}$.  This completes the
proof of the auxiliary claim~\eqref{EqnProvidence}, and hence the
overall proof.


%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

\subsubsection{Proof of~\Cref{LemZwildConcave}}
\label{SecLemZwildConcave}
Since $\Zwild(0) = 0$, the inequality~\eqref{EqnZwildConcave} is
equivalent to
\begin{align*}
  \frac{\Zwild(s) - \Zwild(0)}{s} & \leq \frac{\Zwild(t) -
    \Zwild(0)}{t} \qquad \mbox{for all $s \geq t > 0$.}
\end{align*}
It is a standard fact from convex analysis~\cite{Roc70} that any
concave function has this property.

Thus, it remains to show that $\Zwild$ is a concave function:
more precisely, we will show that any scalars $s, t \geq 0$
and $\alpha \in [0,1]$, we have
\begin{align*}
  \alpha \Zwild(s) + (1 - \alpha) \Zwild(t) & \leq \Zwild(r) \qquad
  \mbox{where $r \defn \alpha s + (1 - \alpha) t $.}
\end{align*}
Let $f_s$ and $f_t$ be functions achieving the suprema that define
$\Zwild(s)$ and $\Zwild(t)$, respectively, and introduce the shorthand
$f_r = \alpha f_s + (1-\alpha) f_t$.  By the assumed convexity of
$\Fclass$, we have $f_r \in \Fclass$, and moreover, by the triangle
inequality, we have
\begin{align*}
\empnorm{f_r- \fhat} & \leq \alpha \empnorm{f_s - \fhat} + (1- \alpha)
\empnorm{f_t - \fhat} \; \leq \; \alpha s + (1 - \alpha) t \; = \; r.
\end{align*}
Consequently, the function $f_\alpha$ is feasible for the supremum
defining $\Zwild(r)$, so that we can
write
\begin{align*}
\alpha \Zwild(s) + (1 - \alpha) \Zwild(t) & = \FULLSUM \rade{i}
\wtil_i \big( \alpha f_s(x_i) + (1 - \alpha) f_t(x_i) - \fhat(x_i)
\big) \\
%
& \leq \sup_{f \in \MyBall{r}{\fhat}} \FULLSUM \rade{i} \wtil_i
\big(f(x_i) - \fhat(x_i) \big) \; = \; \Zwild(r),
\end{align*}
as claimed.
