\title{Strong Watanabe–Yoshida conjecture for complete intersections}
\author{Joel Castillo-Rey}
\address{BCAM – Basque Center for Applied Mathematics, Mazarredo 14, 48009 Bilbao, Basque Country – Spain}
\email{jcastillo@bcamath.org}
\date{}

\begin{document}
\begin{abstract}
In this paper, we prove the strong form of the Watanabe–Yoshida conjecture for complete intersection singularities in every positive characteristic. In characteristics 2 and 3, we explicitly compute the Hilbert–Kunz functions of the $A_1$ and $A_2$ singularities.
\end{abstract}
\maketitle

\section*{Introduction}
Let $(R,\mathfrak{m})$ be a local Noetherian ring of dimension $d\geq 0$ and characteristic $p>0$. We denote by $\m^{[p^e]} = (a^{p^e}: a\in \m)$. The function introduced in \cite{k69},
\begin{gather*}
    \text{HK}_e(R):=\operatorname{length}_R{\left(\frac{R}{\m^{[p^e]}}\right)}
\end{gather*}
is called the Hilbert-Kunz function of $R$. Kunz also showed that this function detects singularities of local rings. Monsky \cite{monsky} proved that the limit
\begin{equation*}
    e_{\text{HK}}(R) = \lim_{e\rightarrow \infty} \frac{\HK_e(R)}{p^{ed}}
\end{equation*}
always exists, and is greater or equal than one. This limit is called the Hilbert–Kunz multiplicity of $R$. Watanabe and Yoshida \cite{wy05} proved that an unmixed local ring with $\eHK{R}=1$ has to be regular. This number need not be an integer, but it does not approach 1 arbitrarily when dimension and characteristic are fixed – see \cite{blien} and \cite{aben08}. The Watanabe–Yoshida conjecture states that the infimum is attained by the quadric hypersurfaces, and also provides a characteristic-free lower bound:


\begin{conjectureintro}[\cite{wy05}, \cite{yos}]
\label{cj: watanabe_yoshida}
Let $p>0$ prime and $d\geq 2$. Set $R_{p,d}:=\mathbb{F}_p[[x_0,...,x_d]]/(Q_d),$ where
\begin{equation*}
    Q_d = \begin{cases}x_0x_1+x_2x_3 + \dots + x_{d-1}x_d & \text{if $d$ is odd},\\
    x_0x_1 + x_2x_3 + \dots +x_{d-2}x_{d-1}+x_d^2 & \text{if $d$ is even}.\end{cases}
\end{equation*}
Let $(R,\m,k)$ be an unmixed non-regular local ring of dimension $d$ and characteristic $p$. Then
\begin{enumerate}
    \label{fr: the_inequalities}
    \item $e_{\text{HK}}(R)\geq e_{\text{HK}}(R_{p,d})$,
    \item if $\eHK{R}=\eHK{R_{p,d}}$, then $\hat{R}\cong R_{p,d}\hat{\otimes}_{\mathbb{F}_p} k$, i.e.~the completion of $R$ is isomorphic to the coordinate ring of a quadric hypersurface.
    \item $e_{\text{HK}}(R_{p,d})\geq 1+c_d$,
\end{enumerate}
where $c_d$ are the coefficients of the Taylor expansion of $\sec x + \tan x$.
\end{conjectureintro}
Note that by unmixed we mean that $\dim \hat{R}/\mathfrak{p} = \dim \hat{R}$ for every $\mathfrak{p}\in \text{Ass}(\hat{R})$. 

The first two parts are what we refer to as the strong Watanabe–Yoshida conjecture since they not only provide a lower bound for the Hilbert–Kunz multiplicity but also characterize the rings with minimal Hilbert–Kunz multiplicity among complete intersections.

The formula in the third part is often called the weaker inequality, or the weaker part of the conjecture. The bound is motivated by the result of Gessel and Monsky \cite{gm10} that $\lim_{p\rightarrow\infty}\eHK{R_{p,d}} = 1+c_d$. Moreover, Yoshida conjectured that $\eHK{R_{p,d}}$ is a decreasing sequence in $p$. Trivedi showed this for $p$ sufficiently larger than the dimension; see \cite{tri}.



Different cases of the Watanabe–Yoshida conjecture have been proven, but we still lack a general answer. The following are the existing results in low dimension:
\begin{theoremintro}[\cite{wy05,wy01,aben12,ac24,yos}]
    Using the same notation as in the Conjecture above, with $p>2$, and $e(R)$ the (usual) multiplicity of $R$, the following hold.
    \begin{enumerate}
    \item If $d\leq 7$, then $\eHK{R}\geq \eHK{R_{p,d}}\geq 1+c_d$.
    \item If $2\leq d \leq 4$, then $\eHK{R}=\eHK{R_{p,d}}$ if and only if $\hat{R}\cong R_{p,d}$. 
    \item If $e(R)\leq 5$, then $\eHK{R}\geq \eHK{R_{p,d}}$.
    \end{enumerate}
\end{theoremintro}

In 2005, Enescu and Shimomoto proved the first inequality of the conjecture for complete intersections in characteristic $p>2$, and provided a stronger result in characteristic $p>3$:
\begin{theoremintro}[\cite{enshi}]
    \label{th: enescu_shimomoto}
    Let $(R,\m)$ be a non-regular complete intersection of characteristic $p>2$ and dimension $d\geq 1$. Then, $\eHK{R}\geq \eHK{R_{p,d}}.$ Moreover, if $p>3$, and $\hat{R}\not\cong R_{p,d}$, then
    \begin{gather}
        \label{fr: weaker_inequality}
    \eHK{R}\geq \eHK{S_{p,d}}\geq \eHK{R_{p,d}},
    \end{gather}
    where $S_{p,d} = \overline{\mathbb{F}_p}[[x_0,\dots,x_d]]/(x_0^2+\dots+x_{d-1}^2+x_d^3)$.
\end{theoremintro}
However, to our knowledge, it has not been proven that $R_{p,d}$ and $S_{p,d}$ have different Hilbert–Kunz multiplicities. In other words, the Hilbert–Kunz multiplicity distinguishes the $A_1$ and $A_2$ singularities; see \cite{greuel}. This would directly imply the first two parts of the Watanabe–Yoshida conjecture for complete intersections. Proving this and extending the result to characteristics 2 and 3 is the main result of this paper:


\begin{maintheorem}[Theorems \ref{maintheoremA} and \ref{maintheoremB}]
    Let $(R,\m)$ be a non-regular complete intersection of characteristic $p>0$. If $\hat{R}\not\cong R_{p,d}$, then
    \begin{gather*}
    \eHK{R}\geq \eHK{S_{p,d}}>\eHK{R_{p,d}},
    \end{gather*}
    where we define $S_{p,d} \coloneqq \mathbb{F}_p[[x_0,...,x_d]]/(P_d)$ with
\begin{equation*}
P_d = \begin{cases}
x_0x_1 + \dots + x_{d-1}^2 + x_d^3 & \text{if $d$ is odd},\\
x_0x_1 + \dots + x_{d-2}x_{d-1} + x_d^3 & \text{if $d$ is even},
\end{cases}
\end{equation*}
for every $p>0$ and $d\geq 2$. In particular, the strong Watanabe–Yoshida conjecture holds for complete intersections.
\end{maintheorem}

The cases of characteristic $p>3$ and $2\leq p\leq 3$ are approached slightly differently since in the case of $p=2,3$ we can compute the Hilbert–Kunz function and multiplicity  of the $A_1$ and $A_2$ singularities:
\begin{maintheorem}[Theorems \ref{th: HK_function_A_1_char_2}, \ref{th: HK_function_A_2_char_2}, \ref{th: eHK_A_1_and_A_2_in_char_3}]
    For $d\geq 1$,
        \begin{gather*}
            \eHK{R_{2,d}} = \begin{dcases}
                \frac{2^m}{2^m-1} & (d=2m-1) \\
                \frac{2^m+1}{2^m} & (d=2m)\\
            \end{dcases}\qandq\eHK{S_{2,d}} = \begin{dcases}
                \frac{2^{m-1}+1}{2^{m-1}} & (d=2m-1) \\
                \frac{2^{m+1}+1}{2^{m+1}-1} & (d=2m) \\
            \end{dcases}
        \end{gather*}
        and 
        \begin{gather*}
        \eHK{R_{3,d}} = 1+\left(\frac{2}{3}\right)^{d-1} \qandq \eHK{S_{3,d}} = 1+\frac{3\cdot 2^d}{3^{d+1}-2^d+(-1)^d}.
        \end{gather*}
    \end{maintheorem}

    Theorem \ref{th: HK_function_A_1_char_2} confirms Yoshida's conjecture on the formula of the Hilbert–Kunz function of $\eHK{R_{2,d}}$. Moreover, with Theorem \ref{th: eHK_A_1_and_A_2_in_char_3}, it disproves Conjecture 2.7 in \cite{jnskw}.

    We obtain the following as a corollary of the main results of this work.

    \begin{maintheorem}[Theorem \ref{th: watanabe_yoshida_low_dimension}, \ref{cor: watanabe_yoshida_low_multiplicity}]
        The strong Watanabe–Yoshida conjecture holds in dimension $d\leq 6$ or multiplicity $e(R)\leq 5$, in characteristic $p>0$. Also if $d=7$ and $p>2$.
    \end{maintheorem}

Let us now lay out the structure of this paper. Section \ref{sec:han_monsky_ring} provides some preliminaries on the Han–Monsky ring since this is the main technique used in the following sections. See \cite{hanmonsky} for details.

Sections \ref{sec:strongwatanabeyoshida} and \ref{sec:HKmultiplicity_A1_and_A2_char_2_3} are devoted to showing that the $A_1$ and $A_2$ singularities indeed have different Hilbert–Kunz multiplicity. We will tackle the characteristic $p>3$ case first in Section \ref{sec:strongwatanabeyoshida}, and we will solve the characteristics $2$ and $3$ cases in Section \ref{sec:HKmultiplicity_A1_and_A2_char_2_3}. The Hilbert–Kunz functions of the $A_1$ and $A_2$ singularities in characteristic $2$ and $3$ are explicitly computed in that section.

In Section \ref{sec:enescu_shimomoto_char_2} of this paper, we will extend Enescu and Shimomoto's result to characteristics 2 and 3, in Theorems \ref{th: strong_enescu_shimomoto_char_2} and \ref{th: strong_enescu_shimomoto_char_3}, which implies that the strong Watanabe–Yoshida conjecture also holds in those two cases.

Finally, in Section \ref{sec:revisiting_literature}, we will revisit the low-dimensional and low-multiplicity cases of the conjecture that have been solved. We will refine them when necessary to obtain the strong Watanabe–Yoshida conjecture, including the characteristic 2 case, from the main results of this work.

