\section{The Han–Monsky ring.}\label{sec:han_monsky_ring}
This section briefly accounts for the Han–Monsky ring based on Yoshida's unpublished notes \cite{yos}. The Han–Monsky ring is the Grothendieck group of finitely generated $k[T]$-modules where the action of $T$ is nilpotent. It was introduced in \cite{hanmonsky} to compute the Hilbert–Kunz function of diagonal hypersurfaces.

\begin{definition}[$k$-object]
Let $k$ be a field. A $k$-object is a finitely generated $k[T]$-module $M$ such that the action of $T$ over $M$ is nilpotent.
\end{definition}
\begin{notation}
    \label{not: notation_k_objects_as_pairs}
We often obtain $k$-objects from taking a zero-dimensional $k$-algebra $R$ and defining the action of $T$ by multiplication by an element $f\in R$. We usually denote the $k$-object as a pair $(R,f)$.
\end{notation}

\begin{proposition}[Definition 1.3, \cite{hanmonsky}]
    \label{pr: product_and_sum_in_rep_ring}
Let $M,N$ be two $k$-objects. The $k$-vector spaces $M\otimes_k N$ and $M\oplus N$ can be regarded as $k$-objects if we define
\begin{align*}
    T\cdot (m\oplus n) &:= Tm\oplus Tn\\
    T\cdot(m\otimes_k n) &:= Tm\otimes_k n+m\otimes_k Tn.
\end{align*}
\end{proposition}

\begin{example}
    \label{ex: example_diagonal_hypersurface_k_object}
    Take the $k$-object $k[x,y]/(x^a,y^b)$ with $T$-action $x^c+y^d$. Then,
    \begin{gather*}
        \frac{k[x,y]}{(x^a,y^b)} = \frac{k[x]}{(x^a)}\otimes \frac{k[y]}{(y^b)},
    \end{gather*}
    where the $k$-objects on the right side have $T$-action $x^c$ and $y^d$, respectively. Generally, any $T$-action given by a diagonal equation will split this way.
\end{example}
We introduce the following equivalence relation over the pairs of $k$-objects: Let $(M_1,N_1)$ and $(M_2,N_2)$ be two pairs of $k$-objects. Then,
\begin{equation*}
    (M_1,N_1)\sim (M_2,N_2)\Leftrightarrow M_1 \oplus N_2 \cong M_2\oplus N_1, \text{ as $k[T]$-modules.}
\end{equation*}
The formal difference $M-N$ denotes the equivalence class containing $(M,N)$. In other words, this is the structure of the Grothendieck ring on the free monoid generated by the equivalence classes of $k$-objects.
\begin{definition}[Han–Monsky ring]
Let
\begin{equation*}
    \Gamma_k = \lbrace M- N\mid M \text{ and } N \text{ are $k$-objects}\rbrace,
\end{equation*}
and define $+$ and $\cdot$ in $\Gamma_k$ as follows:
\begin{align*}
    (M_1-N_1)+(M_2-N_2) &= (M_1\oplus M_2) - (N_1\oplus N_2),\\
    (M_1-N_1)\cdot (M_2-N_2) &= \left[(M_1\otimes M_2)\oplus (N_1\otimes N_2)\right] - \left[(M_1\otimes N_2)\oplus (M_2\otimes N_1)\right].
\end{align*}
This way we have a commutative ring with unity $k-0$, called the Han–Monsky ring over $k$.
\end{definition}
Usually, there is no ambiguity in denoting $\Gamma = \Gamma_k$, because $\Gamma$ only depends on the characteristic of the field, which is usually clear from the context.


\begin{definition}
Let $\delta_i := k[T]/(T^i),$ for every $i\geq 1$. We call these elements the $\delta$-basis.
\end{definition}

The fact that the $\delta$-basis indeed forms a $\mathbb{Z}$-basis is a rewording of the structure theorem for finitely generated modules over a PID:

\begin{corollary}
    \label{cor: delta_basis_is_a_basis}
The abelian group $\Gamma$ is a free $\mathbb{Z}$-module where $\delta_i$ is a free $\mathbb{Z}$-basis.
\end{corollary}
\begin{remark}
Let $k[x]/(x^a)$ be a $k$-object with $T$-action $x^c$. Let $a = ck+r$. Then, one can decompose $k[x]/(x^a)$ as $(c-r)\delta_k+ r\delta_{k+1}$. Looking back at Example \ref{ex: example_diagonal_hypersurface_k_object}, if $k[y]/y^b$ has $T$-action $x^d$ and $b = dl+s$, then $k[x,y]/(x^a,y^b)$ with $T$-action $x^c+y^d$ decomposes in the Han–Monsky ring as $\left((b-r)\delta_k+r\delta_{k+1}\right)\left((d-s)\delta_l+s\delta_{l+1}\right)$. Therefore, understanding the products $\delta_i\delta_j$ is crucial to get to a decomposition over the $\delta$-basis.
\end{remark}

To understand the multiplication table of $\Gamma$, a different $\mathbb{Z}$-basis is introduced, which has a simpler behavior.
\begin{definition}[$\lambda$-basis]
    \label{def: lambda}
    Let $\lambda_i := (-1)^i(\delta_{i+1}-\delta_i), i\geq 0$, noting that $\delta_0 = 0$ in $\Gamma$.
\end{definition}
\begin{remark}
    Note that $\delta_i = \lambda_0 - \lambda_1 + \dots + (-1)^i\lambda_{i-1},\text{ for } i\geq 1.$
\end{remark}
To finish, we define a $\mathbb{Z}$-linear function over $\Gamma$. 
\begin{definition}
    Let $M-0 = \bigoplus \delta_i^{\oplus a_i}$, and define
\begin{equation*}
    \alpha(M-0) := \dim_k M/TM = \sum_{i=1}^\infty a_i
\end{equation*}
Extending by linearity to all pairs $M-N$, we obtain a $\mathbb{Z}$-linear function $\alpha:\Gamma\rightarrow \mathbb{Z}$. For $s,a_i,b_i\in \mathbb{Z}$ with $s\geq 1$, $a_i\geq 1$, and $b_i\geq 0$, we denote
\begin{gather*}
D_k(a_1,\dots,a_s) := \alpha(\prod_{i=1}^s\delta_{a_i}) \hspace{4em} \ell_k(b_1,\dots,b_s) := \alpha(\prod_{i=1}^s\lambda_{a_i}).
\end{gather*}
\end{definition}
\begin{remark}
Note that $\alpha(\delta_j) = 1, \forall j\geq 1$, and
\begin{align*} 
\alpha(\lambda_i) = \begin{cases} 1 & (i=0),\\ 0 & (i\geq 1).\end{cases}
\end{align*}
    Now, let $R = k[[x_1,\dots,x_s]]/(f)$ be a characteristic $p>0$ hypersurface. Then $\HK_e(R) = \dim_k\left(k[[x_1,\dots,x_s]]/(f)+\mathfrak{m}^{[p^e]}\right).$ Observe that we can regard $\mu_e := k[[x_1,\dots,x_s]]/\mathfrak{m}^{[p^e]}$ as a $k$-object with $T$-action $f$, so that $\HK_e(R) = \dim_k(\mu_e/T\mu_e).$ If $\mu_e = \sum a_i\delta_i$ with the given $k$-object structure, then $\HK_e(R) = \sum a_i$.
\end{remark}
\subsection{Arithmetic of the Han–Monsky ring.}
The Han–Monsky ring $\Gamma$ can be filtered by subrings $\Lambda_e\subset \Lambda_{e+1}$:
\begin{theoremdefinition}
    [Theorem 3.2, \cite{hanmonsky}]
    \label{lambdadef}
        The additive subgroup of $\Gamma$ generated by the $\lambda_i$ for $0\leq i \leq p^e-1$ is closed under multiplication. We call this ring $\Lambda_e$.
\end{theoremdefinition}
\begin{theorem}[Theorem 2.5, \cite{hanmonsky}]
    \label{lm: structure_Lambda_1}
    Let $i\leq j\le p-1$. Then $\lambda_i\lambda_j = \sum_{j-i}^{\min{i+j,2p-2-i-j}} \lambda_k$.
\end{theorem}
\begin{table}[h]
    \label{tab: multiplication_table_lambda_1_char_2_and_char_3}
\centering
\begin{tabular}{c|cc}
    $\cdot$ & $\lambda_0$ & $\lambda_1$ \\ \hline
    $\lambda_0$ & $\lambda_0$ & $\lambda_1$ \\
    $\lambda_1$ & $\cdot$ & $\lambda_0$
\end{tabular}\hspace{2em}
\begin{tabular}{c|ccc}
$\cdot$ & $\lambda_0$ & $\lambda_1$ & $\lambda_2$ \\ \hline
$\lambda_0$ & $\lambda_0$ & $\lambda_1$ & $\lambda_2$ \\
$\lambda_1$ & $\cdot$ & $\lambda_0+\lambda_1+\lambda_2$ & $\lambda_1$ \\
$\lambda_2$ & $\cdot$ & $\cdot$ & $\lambda_0$
\end{tabular}
\caption{Multiplication table for the $\lambda$-basis of $\Lambda_1$ in characteristic $2$ and $3$, respectively.}
\end{table}


\begin{proposition}
\label{pr: delta_p_squared}
$\delta_p^2 = p\delta_p$.
\end{proposition}
\begin{proof}
First part of Lemma 3.3 in \cite{hanmonsky}.
\end{proof}

    \begin{lemma}[Lemma 3.4, \cite{hanmonsky}]
        \label{lm: lambda_p_adic_split}
        Let $q = p^n$, $n\geq 1$. Take $0\leq i \leq q-1.$ Then, in $\Gamma$,
        \begin{enumerate}[label=(\alph*)]
        \item $\lambda_i\lambda_{qj} =\lambda_{qj+i}$; \label{lm: p_adic_split}
        \item $\lambda_i\lambda_{qj-1} = \lambda_{qj-i-1}$. \label{lm: p_adic_opposite}
        \end{enumerate}
    \end{lemma}
    \begin{corollary}
    \label{cr: p_adic_expansion_rep_ring}
    Let $0\leq a< p^{n+1},$ and $a = a_0+a_1p+a_2p^2+\dots+a_np^n$ be its expansion in base $p$, $0\leq a_i<p$. Then, we have the following decomposition:
    \begin{gather*}
        \lambda_a = \prod_{k\geq 0}^n\lambda_{a_kp^k}.
    \end{gather*}
    \end{corollary}
    \begin{proof}
        We proceed by induction on $n$. For $n=0$, there is nothing to do. Now, observe that
        \begin{gather*}
            a_0 + pa_1 +\dots + p^na_n = (a_0 + pa_1+\dots+p^{n-1}a_{n-1})+p^na_n,
        \end{gather*}
    where $a_0+pa_1+\dots+p^{n-1}a_{n-1}<p^n.$ Thus, the lemma above gives
    \begin{gather*}
        \lambda_{a_0+pa_1+\dots+p^{n-1}a_{n-1}+p^na_n} = \lambda_{a_0+pa_1+\dots+p^{n-1}a_{n-1}}\lambda_{p^na_n}.
    \end{gather*}
    \end{proof}
This result implies that to understand the multiplication table of $\Gamma$, it is enough to understand the multiplication table of the $\lbrace \lambda_{qi}\rbrace_{0\leq i\leq q-1}$ for each $q = p^e$. For characteristic 2, the following result solves it:
\begin{lemma}[Theorem 3.7, \cite{hanmonsky}]
    \label{cr: lambdaqsquared}
        Given $q=2^n,$ then $\lambda_{q}^2 = \lambda_0$.
\end{lemma}


We finish the section with the Han–Monsky ring with rational coefficients:
\begin{definition}[Definition 4.8, \cite{hanmonsky}]
\label{df: representation_ring_rational_coefficients}
    Let $a\geq 0$ be a real number. In $\Gamma' := \mathbb{Q}\otimes_\mathbb{Z} \Gamma$, set 
    \begin{gather*}
        \delta_a := (1-z)\delta_r + z\delta_{r+1}, \text{ where } a=r+z, r\in \mathbb{Z}_{\geq 0}, z\in [0,1).
    \end{gather*}
    We extend $\alpha$ to $\Gamma'$ by $\mathbb{R}$-linearity, and denote $D(a_i,\dots,a_i) := \alpha(\prod \delta_{a_i})$. Note that $\delta_0 = 0$.
    \end{definition}

\section{Strong~Watanabe–Yoshida~for~Complete~Intersections of~characteristic~\texorpdfstring{$p>3$}{p gt 3}}\label{sec:strongwatanabeyoshida}
For the rest of the section, let $p>3$ and $d\geq 2$, unless otherwise stated. We will deal with the cases when $p=2$ and $p=3$ in the next section.
\begin{definition}[$A_1$ and $A_2$ singularities, \cite{greuel}]
    \label{df: Qd}
    Let $k$ be a field of positive characteristic $p$. The rings $R_{p,d} := k[[x_0,...,x_d]]/(Q_d)$ where
    \begin{gather*}
    Q_d := \begin{cases}
    x_0x_1+\dots + x_{d-1}x_d, & \text{if $d$ is odd},\\
    x_0x_1 + \dots + x_{d-2}x_{d-1} + x_d^2, & \text{if $d$ is even},
    \end{cases}
    \end{gather*}
    are the $A_1$ singularities. The rings $S_{p,d} \coloneqq k[[x_0,...,x_d]]/(P_d)$ where
    \begin{equation*}
        P_d = \begin{cases}
        x_0x_1 + \dots + x_{d-1}^2 + x_d^3 & \text{if $d$ is odd},\\
        x_0x_1 + \dots + x_{d-2}x_{d-1} + x_d^3 & \text{if $d$ is even}.
        \end{cases}
    \end{equation*}
    are the $A_2$ singularities.
    \end{definition}
    Note that for $p\geq 3$,
\begin{gather*}
    R_{p,d} \cong \frac{k[[x_0,\dots,x_d]]}{(x_0^2+\dots+x_{d}^2)}, \ S_{p,d} \cong \frac{k[[x_0,\dots,x_d]]}{(x_0^2+\dots+x_{d-1}^2+x_d^3)},
\end{gather*}
so the $A_1$ and $A_2$ singularities are diagonal hypersurfaces in characteristic $p\geq 3$. This is crucial to prove the main result of this section, the inequality $\eHK{S_{p,d}}>\eHK{R_{p,d}}$, since we will use Han and Monsky's results in \cite{hanmonsky}, the so-called \textit{Han–Monsky algorithm}.


\subsection{The Hilbert–Kunz function of a diagonal hypersurface}
Let us recap some results in Section 5 of \cite{hanmonsky}. Let $R$ denote the ring of power series at the origin of a diagonal hypersurface: 
\begin{gather*}
    R := \frac{k[[x_0,\dots,x_s]]}{(x_0^{d_0}+\dots+x_s^{d_s})}.
\end{gather*}

\begin{lemma}[Lemma 5.6, \cite{hanmonsky}]
\label{lm: lemmarepring}
    Let $q=p^e$. The $k$-object $k[[x_0,\dots,x_s]]/(x_0^{q},\dots,x_s^{q})$ with $T$-action $x_0^{d_0}+\dots+x_s^{d_s}$ is $\prod_{i=0}^s \delta_{q/d_i}$ in $\Gamma'$. Therefore,
    \begin{gather*}
        \HK_e(R) = d_0\dots d_sD\left(\frac{q}{d_0},\dots,\frac{q}{d_s}\right).
    \end{gather*}
\end{lemma}

This result expresses that we can understand the Hilbert–Kunz function of diagonal hypersurfaces by studying the function $D(a_0,\dots,a_s)$. The \textit{Han–Monsky algorithm} is the systematic method for computing a formula for $e\mapsto D(q/d_i,\dots,q/d_s)$ for $e$ large enough.

This algorithm starts with three data: the characteristic $p$, the vector of inverses of the exponents of the diagonal hypersurface $\beta = (1/d_0,\dots,1/d_s)$, and a \textit{period} $\mu$ of our choice. Should the period be chosen wisely – which can always be done – we will be under the hypotheses of Theorem \ref{th: th53} that spells out the Hilbert–Kunz function of the given diagonal hypersurface for every large $e$ in terms of these two data. To work with said theorem, we need to produce a series of vectors out of $p$, $\mu$, and $\beta$:

\begin{definition}
\label{df: vectors}
    Let $\beta$ be a vector of positive real numbers and $p$ be a prime. Let $\mu$ be a positive integer that we call the period. We obtain the following data associated to these $\beta, \mu$, and $p$.
    \begin{enumerate}
        \item Let $r\in \mathbb{Z}_{\geq 0}^s$ and $z\in [0,1)^{s+1}$ such that $\beta = r + z$.
        \item Let $R\in \mathbb{Z}_{\geq 0}^s$ and $z'\in [0,1)^{s+1}$ such that $p^{\mu}\beta = R + z'$.
        \item Let $t := p^{\mu}z - z' = t \in \mathbb{Z}_{\geq 0}^s$.
    \end{enumerate}
    We denote the coordinates as $r = (r_0,\dots,r_s)$.

    Let $v$ and $w$ be arbitrary vectors. We say that $v$ is \textbf{equivalent} to $w$, denoted $v\sim w$, if we can obtain it from $w$ by replacing $v_i$ by $1-v_i$ for an even number of indices $i$ (so in particular, if they are equal to each other). We also introduce the notation $v^*:= (1-v_0,v_1,\dots,v_s)$.

    Finally, we define the function $\ell^\sharp$:
    \begin{gather*}
        \ell^\sharp = \begin{cases} \ell_k(t) & \text{if } \sum r_i \text{ even,}\\ \ell_k(p^{\mu}-1-t_0,t_1,\dots,t_s) & \text{if } \sum r_i \text{ odd.}\end{cases}
    \end{gather*}
    We will refer to the elements $r,z,R,z',t$ and $\ell^\sharp$ as the data associated to $\beta,\mu$ and $p$.
\end{definition}

\begin{theorem}[Theorem 5.3 and remark, \cite{hanmonsky}]
\label{th: th53}
    Let $\beta$ be a vector of positive real numbers, and $\mu$ a positive integer, and let $r,z,R,z'$, and $t$ be the data associated to $\beta,\mu$, and $p$.

    Suppose that either one of these two sets of conditions is satisfied by the data:
    \begin{enumerate}
        \item $z'\sim z$ and $\sum R_i \equiv \sum r_i \mod{2}$, or
        \item $z'\sim z^*$ and $\sum R_i \not\equiv \sum r_i \mod{2}$.
    \end{enumerate}  Then, there is a rational number $C$ and rational numbers $\Delta_0,\Delta_1,\Delta_2,\dots$ such that 
    \begin{gather*}
        D(p^e\beta) = Cp^{de} + \Delta_e,
    \end{gather*} and $\Delta_{e+\mu}=\ell^\sharp \Delta_e$ for all $e\geq 0$, where $\ell^\sharp$ was defined in \ref{df: vectors}.
\end{theorem}
We note that given any $\beta$ vector with non-negative rational numbers, there always exists a period such that the first set of conditions in the hypotheses of Theorem \ref{th: th53} is satisfied, as it is shown in the proof of Theorem 5.3 of \cite{hanmonsky} – Han and Monsky provide the second set of conditions as a mere remark. However, to prove the main result of the section, we will exploit both sets of conditions.

\subsection{The Hilbert–Kunz multiplicity of \texorpdfstring{$A_1$}{A1} and \texorpdfstring{$A_2$}{A2} singularities, \texorpdfstring{$p>3$}{p gt 3}.}

It turns out that in the case that the diagonal hypersurface is an $A_1$ or an $A_2$ singularity, we can choose the period to be 1 for every $p>3$ and $d\geq 2$:
\begin{lemma}
\label{conditions}
    Let $\beta = (\frac{1}{2},\dots,\frac{1}{2},\frac{1}{3})$, $\mu = 1$, and $p>3$. Then, the data $r,z,R,z',t,\ell^\sharp$ associated to this pair satisfy the hypotheses of Theorem \ref{th: th53}. Also, $\sum r_i = 0$, so $\ell^\sharp = \ell_k(t)$. The same follows taking $\beta = (\frac{1}{2},\dots,\frac{1}{2})$, $\mu = 1$ and $p>2$.
\end{lemma}
\begin{proof}
Let us compute $r,z$ and $R$ first, according to Definition \ref{df: vectors}:
\begin{gather*}
    r = (0,\dots,0), z=\beta, R = (\left\lfloor\frac{p}{2}\right\rfloor,\dots,\left\lfloor\frac{p}{2}\right\rfloor,\left\lfloor\frac{p}{3}\right\rfloor).
\end{gather*}
Firstly, observe that $z = z^*$, given that $z_0 = \frac{1}{2}$. Thus, the hypotheses of the Theorem will be satisfied regardless of the parity of $\sum R_i$ once we prove that $z'$ is equivalent to $z$. 

When computing $z'$, two cases arise: either $p\equiv 1\mod{3}$ or $p\equiv 2\mod{3}$.
\begin{enumerate}
    \item If $p\equiv 1\mod{3}$, then $z' = (\frac{1}{2},\dots,\frac{1}{2},\frac{1}{3}) = z$.
    \item If $p\equiv 2\mod{3}$, then $z' = (\frac{1}{2},\dots,\frac{1}{2},\frac{2}{3})$. In this case, given that $s\geq 1$, and the first $s$ entries of $\beta$ are $1/2$, one sees that $z'$ is equivalent to $z$ by observing that $z' = (1-z_0,z_1,\dots,z_{s-1},1-z_s)$.
\end{enumerate}
The result follows.

As for $\beta = (1/2,\dots,1/2)$, $\mu = 1$ and $p>2$, it also happens that $z = z^*$, and so we do not have to bother about the parity of $\sum R_i$ either. Moreover, $p\equiv 1\pmod{2}$ for every $p>2$, so $z = z'$.
\end{proof}

The fact that the period can be chosen to be $1$ is useful because it will allow us to exploit the simplicity of the multiplication table of $\Lambda_1$. It will be for $S_{p,d}$ that we will need to use the second set of conditions in \ref{th: th53}. These observations are the content of the next lemma.
\begin{theorem}
\label{th: yoshida_theorem_mu_1}
For all $p>2$ and $d\geq 0$,
    \begin{gather*}
        e_{\text{HK}}(R_{p,d}) = 1 + \frac{\text{HK}_1(R_{p,d}) - p^d}{p^d-\ell^\sharp(R_{p,d})},
    \end{gather*}
    where $\ell^\sharp(R_{p,d}) = \alpha(\lambda_a^{d+1})$ for $a = \lfloor\frac{p}{2}\rfloor$. Similarly, for all $p>3$ and $d\geq 0$, it follows that
    \begin{gather*}
        e_{\text{HK}}(S_{p,d}) = 1 + \frac{\text{HK}_1(S_{p,d}) - p^d}{p^d-\ell^\sharp(S_{p,d})},
    \end{gather*}
    where $\ell^\sharp(S_{p,d}) = \alpha(\lambda_a^d\lambda_b)$ for $a = \lfloor\frac{p}{2}\rfloor$ and $b = \lfloor\frac{p}{3}\rfloor$.
\end{theorem}
\begin{proof}
    By Lemma \ref{lm: lemmarepring}, we know that $\HK_e(S_{p,d}) = 2^d3D(p^e\beta)$. Then, Theorem \ref{th: th53} yields that there exist rational numbers $C$, $\ell^\sharp_S$, and $\Delta_e$ such that
    \begin{gather*}
        2^d3D(p^e\beta) = 2^d3Cp^{de}+2^d3\Delta_e,
    \end{gather*}
    where $\Delta_{e+1} = \ell^\sharp_S \Delta_e$ for all $e\geq 0$. Note that $\eHK{S_{p,d}} = 2^d3C$ and let $c_1 = -2^d3\Delta_0$, so
    \begin{gather*}
        \HK_e(S_{p,d}) = \eHK{S_{p,d}}p^{de}-c_1(\ell^\sharp_S)^e,e\geq 0.
    \end{gather*}
    The same argument applies to $R_{p,d}$, for which we obtain
    \begin{gather*}
        \HK_e(R_{p,d}) = \eHK{R_{p,d}}p^{de}-c_1(\ell^\sharp_R)^e,e\geq 0.
    \end{gather*}

    Since $\HK_0(R) = 1$ for every ring, the computations above imply that
    \begin{gather*}
        \begin{dcases}
            \eHK{S_{p,d}} - c_1 = 1,\\
            \eHK{S_{p,d}}p^d - c_1\ell^\sharp = \text{HK}_1(S_{p,d}).
        \end{dcases}
    \end{gather*}
    Replacing $\eHK{S_{p,d}} = 1+c_1$ on the second equation, we obtain
    \begin{gather*}
    p^d + c_1p^d - c_1\ell^\sharp = \text{HK}_1(S_{p,d})\Rightarrow c_1 = \frac{\text{HK}_1(S_{p,d}) - p^d}{p^d-\ell^\sharp}.
    \end{gather*}
    The same argument applies to $\eHK{R_{p,d}}$.
\end{proof}

\begin{remark}
    The $A_1$ and $A_2$ singularities are not the only ones for which the formula above works. We can easily see that we get the same result for other diagonal hypersurfaces, for example, whenever $d_0 = 2$ and $p\equiv \pm 1\mod{d_i}$ for every $i$. In this case, it happens that $z = z^*$, and therefore $z'$ is equivalent to both $z$ and $z^*$, and both sets of conditions in Theorem \ref{th: th53} are satisfied. This is the case, for instance, of $A_3$ singularities with $p\geq 5$. The Hilbert–Kunz multiplicity of an $A_n$ singularity (see \cite{greuel}) verifies the formula in the previous theorem whenever $p\equiv \pm 1\pmod{n+1}$. 

    However, the formula does not work in full generality – take the $A_4$ surface singularity in characteristic 7, which has the equation $x^2+y^2+z^5$. The formula would give the value $43/25$, but it has Hilbert–Kunz multiplicity $2-1/5 = 9/5$ (see, for instance, Example 4.1 \cite{wy01}).
\end{remark}
\subsection{The powers of \texorpdfstring{$\gamma$}{gamma} in the Han–Monsky ring.} In this section, we prove some necessary technical corollaries in the following section and involve computations in the Han–Monsky ring.

\begin{notation}
    Let $p>2$ be a prime and $k$ a field of characteristic $p$. For the rest of the section, we will denote the $k$-object $\gamma:= \left(\frac{k[x]}{(x^{p})},x^2\right)$ and for $p>3$ prime, we will write $\eta:= \left(\frac{k[x]}{(x^{p})},x^3\right)$. Observe that $\gamma\in \Lambda_1$. We will use the following notation for the coordinates of the powers of $\gamma$ over the $\lambda$-basis:
    \begin{gather*}
    \gamma^d = a_0^{(d)}\lambda_0+\dots+a_{p-1}^{(d)}\lambda_{p-1}.
    \end{gather*}
\end{notation}


\begin{proposition}
    \label{pr: gamma_formula}
    Let $k$ be a field of characteristic $p\geq 3$. Set $a = (p-1)/2$. Then,
    \begin{gather*}
    \gamma = \delta_{a}+\delta_{a+1} = 2\lambda_0-2\lambda_1+\dots+(-1)^{a-1}2\lambda_{a-1}+(-1)^{a}\lambda_{a}.
    \end{gather*}
\end{proposition}

The point of this section is to prove that the first $a+1$ coefficients of $\gamma^d$ form a monotone sequence – proving this is the goal of the following propositions.

\begin{lemma}[\cite{yos}]
    \label{lm: product_gamma_lambda}
Let $k \geq  a$. Then, 
\begin{gather*} 
    \gamma\lambda_k = \begin{dcases}
    (-1)^k\left(2\sum_{i=0}^{a-k-1} (-1)^i\lambda_i + \sum_{i=a-k}^{a+k} (-1)^i\lambda_i\right) & (k < a) ;\\
    (-1)^a\delta_p & (k=a),
\end{dcases}
\end{gather*}
\end{lemma}
\begin{proof}
Explicit computation using Lemma \ref{lm: structure_Lambda_1} and Proposition \ref{pr: gamma_formula}. This formula is provided in matrix form in Section 4 of Yoshida's notes \cite{yos}.
\end{proof}

\begin{remark}
    Observe that for $p-1\geq k\geq a+1$, $\lambda_k\gamma = \lambda_{p-1}\lambda_{p-1-k}\gamma$, by \ref{lm: lambda_p_adic_split}\ref{lm: p_adic_opposite}.
\end{remark}
\begin{lemma}
    \label{lm: alpha_of_gamma_power_eta_and_gamma_power}
    Let $p>3$ and $d\geq 1$. Let $a,b,c\in\mathbb{Z}_{\geq 0}$ such that $p = 3b+c$ and $p = 2a + 1$, and $c<3$. Then, 
    \begin{align*}
        \alpha(\gamma^d\eta) &= 3a_0^{(d)}+\dots +3a_{b-1}^{(d)}+ca_b^{(d)},\\
        \alpha(\gamma^{d+1}) &= 2a_0^{(d)}+\dots+2a_{a-1}^{(d)}+ a_a^{(d)}.
    \end{align*}
    \end{lemma}
    \begin{proof}
        Observe that, by definition and Lemma \ref{lm: product_gamma_lambda},
    \begin{gather*}
    \alpha(\gamma^{d+1}) = \sum_{i=0}^{p-1} (-1)^i a_i^{(d)} \alpha(\lambda_i\gamma) = \sum_{i=0}^{a-1} (-1)^i a_i^{(d)} (-1)^i 2 + (-1)^i a_a^{(d)} (-1)^i.
    \end{gather*}
    \end{proof}


\begin{lemma}
    \label{lm: gamma_power_reflexions_sums_delta_p_power}
    For every $d\geq 1$, $\gamma^d(\lambda_{p-1}+\lambda_0) = 2\cdot p^{d-1}\delta_p.$ Equivalently, if we denote $\gamma^d = \sum_{i=0}^{p-1} (-1)^ia_i^{(d)}\lambda_i$, then
\begin{gather*}
a_i^{(d)} + a_{p-i}^{(d)} = 2p^{d-1}.
\end{gather*}
In particular, this implies that $a_a^{(d)} = p^{d-1}$, for $a = \frac{p-1}{2}$.
\end{lemma}
\begin{proof}
One can check by Lemma \ref{lm: product_gamma_lambda} that $\gamma(\lambda_0+\lambda_{p-1}) = 2\delta_p$. Now, $(\lambda_0+\lambda_{p-1})^2 = 2(\lambda_0+\lambda_{p-1})$ by \ref{lm: lambda_p_adic_split}. By \ref{pr: delta_p_squared}, the result follows.
\end{proof}


\begin{lemma}[Theorem 4.1, \cite{yos}]
    \label{lm: gamma_power_recursive_formula}
    For $d\geq 2$,
    \begin{gather*}
        \gamma^d-p^{d-1}\delta_p = 2\sum_{r=0}^{a-1}((-1)^r\gamma^{d-1}\lambda_r - p^{d-2}\delta_p).
    \end{gather*}
    Equivalently, for $k = 1,\dots, a$
    \begin{gather*}
        a_{a-k}^{(d)}-p^{d-1} = 2\sum_{r = a-k}^{a-1} (a^{(d-1)}_{a-r}-p^{d-2}).
    \end{gather*}
\end{lemma}
\begin{proof}
Lemma \ref{lm: gamma_power_reflexions_sums_delta_p_power} applied twice yields that
\begin{align*}
    \gamma^d - p^{d-1}\delta_p &= p^{d-1}\delta_p-\gamma^d\lambda_{p-1} = p^{d-1}\delta_p-\gamma(2p^{d-2}\delta_p-\gamma^{d-1})\\
     &= p^{d-1}\delta_p + 2\sum_{r=0}^{a-1}(-1)^r\lambda_r(\gamma^{d-1}-2p^{d-2}\delta_p) + (-1)^a\lambda_a(\gamma^{d-1}-2p^{d-2}\delta_p),
\intertext{and from Lemma \ref{lm: structure_Lambda_1} one can check that $(-1)^r\lambda_r\delta_p = \delta_p$, which yields}
\gamma^d - p^{d-1}\delta_p &= p^{d-1}\delta_p + 2\sum_{r=0}^{a-1}((-1)^r\lambda_r\gamma^{d-1}-2p^{d-2}\delta_p) + ((-1)^a\lambda_a\gamma^{d-1}-2p^{d-2}\delta_p)\\
    &= p^{d-1}\delta_p - (p-1)p^{d-2}\delta_p + 2\sum_{r=0}^{a-1}((-1)^r\lambda_r\gamma^{d-1}-p^{d-2}\delta_p) + ((-1)^a\lambda_a\gamma^{d-1}-2p^{d-2}\delta_p).
\end{align*}
To finish, note that $p^{d-1}\delta_p - (p-1)p^{d-2}\delta_p = p^{d-2}\delta_p,$ and adding the term in the rightmost side of the formula above,
\begin{gather*}
    p^{d-2}\delta_p + (-1)^a\lambda_a\gamma^{d-1}-2p^{d-2}\delta_p = (-1)^a\lambda_a\gamma^{d-1}-p^{d-2}\delta_p.
\end{gather*}
It follows from Lemma \ref{lm: gamma_power_reflexions_sums_delta_p_power} and the remark above that this is zero, so the result follows. 
\end{proof}
\begin{remark}
    Observe that, for $d\geq 2$, $2\sum_{r=0}^{a-1}((-1)^r\gamma^{d-1}\lambda_r - p^{d-2}\delta_p) = 2(\gamma^{d-1}-p^{d-2}\delta_p)\delta_a.$ Applying the result recursively, one obtains that $\gamma^d-p^{d-1}\delta_p = 2^{d-1}(\gamma-\delta_p)\delta_a^{d-1}$, for $d\geq 1$, which is an interesting identity on its own.
\end{remark}

From this lemma, we can now prove the result we were aiming for. We prove something slightly stronger, which is that the sequence is always strictly increasing for $d\geq 1$, but we will only use the fact that it is increasing.
\begin{proposition}
\label{pr: decreasing_sequence}
    Fix $d\geq 1$. Then, the sequence $a_i^{(d)}$ is decreasing on $0\leq i \leq a$. It is strictly decreasing for $d\geq 2$.
\end{proposition}
\begin{proof}
    Let $k = 0,\dots,a-1$. Then, by Lemma \ref{lm: gamma_power_recursive_formula},
    \begin{multline*}
        a_{a-k}^{(d)} - a_{a-k-1}^{(d)} = 2\sum_{r=a-k}^a (a_{a-r}^{(d-1)}-p^{d-2}) - 2\sum_{r=a-k-1}^a(a_{a-r}^{(d-1)}-p^{d-2}) = 2(a_{k+1}^{(d-1)}-p^{d-2}).
    \end{multline*}
    Since $p^{d-2} = a_{a}^{(d-1)}$, the result follows from Proposition \ref{pr: gamma_formula} and induction on $d$.
\end{proof}


\subsection{The inequality.} We finally conclude in this section that the Hilbert–Kunz multiplicity of the $A_1$ and $A_2$ singularities are different.
\begin{theorem}[Theorem 4.6, \cite{hanmonsky}]
    \label{cor: ell_bound}
    If $d\geq 2$, $q= p^e$ and $k_i\leq q-1$, then $\alpha(\prod_{i = 0}^{d} \lambda_{k_i})\leq q^{d-2}$. In particular, $\ell^\sharp(S_{p,d}) \leq p^{d-2}$.
\end{theorem}

\begin{proposition}
\label{pr: first_inequality}
    For $d\geq 2$ and $p>3$ prime, $\HK_1(S_{p,d})-\HK_1(R_{p,d})\geq \HK_1(R_{p,d-1})-p^{d-1}$.
\end{proposition}
\begin{proof}
    Let $a,b,c$ like in \ref{lm: alpha_of_gamma_power_eta_and_gamma_power}. Since $d$ is fixed throughout the proof, there is no ambiguity in denoting $\gamma^d = \sum_{i = 0}^{p-1} a_i\lambda_i$. 
    By Lemma \ref{lm: alpha_of_gamma_power_eta_and_gamma_power}, rearranging the coefficients we obtain:
    \begin{gather*}
        \hs = \alpha(\gamma^d\eta) = \sum_{k=1}^{p}a_{\left\lfloor\frac{k+2}{3}\right\rfloor-1} \qandq \hr = \alpha(\gamma^{d+1}) = \sum_{k=1}^{p}a_{\left\lfloor \frac{k+1}{2}\right\rfloor-1}.
    \end{gather*}

    Thus,
        \begin{gather*}
            \hs-\hr = \sum_{k=1}^{p}\left(a_{\left\lfloor\frac{k+2}{3}\right\rfloor-1}-a_{\left\lfloor \frac{k+1}{2}\right\rfloor-1}\right).
        \end{gather*}
        Now, it happens that $\lfloor\frac{k+1}{2}\rfloor\geq\lfloor\frac{k+2}{3}\rfloor$, and the equality only holds for $k=1,2$ or $4$. This implies that $\lfloor\frac{k+1}{2}\rfloor>\lfloor\frac{k+2}{3}\rfloor$ for $k=3$ and $p\geq k\geq 5$. Hence, by Proposition \ref{pr: decreasing_sequence}  
        \begin{gather*}
            a_{\left\lfloor\frac{k+2}{3}\right\rfloor-1}-a_{\left\lfloor \frac{k+1}{2}\right\rfloor-1} \neq 0
        \end{gather*}
        for $k=3$ and $p\geq k\geq 5$. So,
        \begin{gather*}
            \sum_{k=1}^{p}\left(a_{\left\lfloor\frac{k+2}{3}\right\rfloor-1}-a_{\left\lfloor \frac{k+1}{2}\right\rfloor-1}\right) = (a_0-a_1) + \sum_{k=5}^p \left(a_{\left\lfloor\frac{k+2}{3}\right\rfloor-1}-a_{\left\lfloor \frac{k+1}{2}\right\rfloor-1}\right).
        \end{gather*}
        where every term of the sum on the right side is non-zero. Note that
        \begin{gather*}
            a_{\left\lfloor\frac{k+2}{3}\right\rfloor-1}-a_{\left\lfloor \frac{k+1}{2}\right\rfloor-1}\geq a_{\left\lfloor\frac{k+1}{2}\right\rfloor-2}-a_{\left\lfloor \frac{k+1}{2}\right\rfloor-1}
        \end{gather*}
        therefore
        \begin{align*}
            \sum_{k=5}^p \left(a_{\left\lfloor\frac{k+2}{3}\right\rfloor-1}-a_{\left\lfloor \frac{k+1}{2}\right\rfloor-1}\right) &\geq  \sum_{k=5}^p \left(a_{\left\lfloor\frac{k+1}{2}\right\rfloor-2}-a_{\left\lfloor \frac{k+1}{2}\right\rfloor-1}\right) \\
            &= 2(a_1-a_2)+2(a_2-a_3)+\dots+2(a_{a-2}-a_{a-1}) + (a_{a-1}-a_a)\\
            &\geq (a_1-a_2)+(a_2-a_3)+\dots+(a_{a-1}-a_a) = a_1-a_a
        \end{align*}
        Thus, to sum up, we just proved that
                \begin{align*}
                    \hs-\hr &\geq (a_0-a_1)+(a_{1}-a_a) = a_0-a_a = \HK_1(R_{p,d-1})-p^{d-1}.
                \end{align*}
\end{proof}

\begin{proposition}
\label{pr: second_inequality}
    For $d\geq 2$ and $p>3$ prime, $p\HK_1(R_{p,d-1})\geq\HK_1(S_{p,d})$.
\end{proposition}
\begin{proof}
    We use the same notation in \ref{pr: first_inequality}. Then, by \ref{pr: decreasing_sequence},
    \begin{equation*}
        \HK_1(S_{p,d}) = 3a_{0}+\dots+3a_{b-1}+ca_{b} \leq 3a_{0}+\dots+3a_{0}+ca_{0} = pa_0 = p\HK_1(R_{p,d-1}).
    \end{equation*}
\end{proof}

\begin{theorem}
    \label{cr: A_2_A_1_ineq_large_char}
    For $p> 3$ prime and $d\geq 2$, $\eHK{S_{p,d}}>\eHK{R_{p,d}}$.
\end{theorem}
\begin{proof}
    By Theorem \ref{th: yoshida_theorem_mu_1} and Corollary \ref{cor: ell_bound},
\begin{gather*}
    \eHK{S_{p,d}} = \frac{\HK_1(S_{p,d})-p^d}{p^d-\ell^\sharp(S_{p,d})}\geq \frac{\HK_1(S_{p,d})-p^d}{p^d},\\
    \eHK{R_{p,d}}=\frac{\HK_1(R_{p,d})-p^d}{p^d-\ell^\sharp(R_{p,d})}\leq \frac{\HK_1(R_{p,d})-p^d}{p^d-p^{d-2}},
\end{gather*}
From Propositions \ref{pr: first_inequality} and \ref{pr: second_inequality}, it follows that
    \begin{multline}
        \label{fr: final_inequality_large_char}
        p^2(\HK_1(S_{p,d})-\HK_1(R_{p,d}))\geq p^2(\HK_1(R_{p,d-1})-p^{d-1}) >\\
        > p(\HK_1(R_{p,d-1})-p^{d-1})\geq \HK_1(S_{p,d})-p^d,
    \end{multline}
which implies that
\begin{gather*}
    \frac{\HK_1(S_{p,d})-p^d}{p^d}>\frac{\HK_1(R_{p,d})-p^d}{p^d-p^{d-2}}.
\end{gather*}
\end{proof}

\begin{theorem}[Strong Watanabe–Yoshida conjecture for complete intersections, $p>3$]
    \label{maintheoremA}
    Let $(R,\m)$ be a non-regular complete intersection of characteristic $p>3$ and dimension $d\geq 2$. If $\hat{R}\not\cong R_{p,d}$, then
    \begin{gather*}
    \eHK{R}\geq \eHK{S_{p,d}}>\eHK{R_{p,d}},
    \end{gather*}
    where $S_{p,d} \coloneqq \overline{\mathbb{F}_p}[[x_0,...,x_d]]/(x_0^2+\dots+x_{d-1}^2+x_d^3)$.
\end{theorem}
\begin{proof}
    The second inequality is Theorem \ref{cr: A_2_A_1_ineq_large_char}. As for the first, let $K|k$ be an uncountable field extension of $k$. Since field extensions are faithfully flat, then $\eHK{R} = \eHK{R\otimes_k K}$. Now, by Theorem 4.3 in \cite{enshi}, there exists some $F\in K[[x_0,\dots,x_d]]$ such that 
    \begin{gather*}
        \eHK{R\otimes_k K}\geq \eHK{K[[x_0,\dots,x_d]]/(F)}.
    \end{gather*}
    Finally, by Theorem 3.4 in \cite{enshi}, we have that $\eHK{K[[x_0,\dots,x_d]]/(F)}\geq \eHK{S_{p,d}}.$
\end{proof}

\section{HK functions of the \texorpdfstring{$A_1$}{A1} and \texorpdfstring{$A_2$}{A2} singularities in characteristics 2 and 3.}\label{sec:HKmultiplicity_A1_and_A2_char_2_3}


\subsection{\texorpdfstring{$\sigma$}{sigma}-basis}
We introduce a basis of idempotent elements of $\Lambda_e\otimes_\mathbb{Z} \mathbb{Q}$, which we will call the $\sigma$-basis. This will be the main tool to compute the Hilbert–Kunz functions of the $A_1$ and $A_2$ singularities.

\begin{definition}[$\sigma$-elements]
Let $e \geq 1$ and $0 \leq k \leq 2^e - 1$. Write $k$ in binary as $k = k_0 + 2k_1 + \dots + 2^{e-1}k_{e-1}$, where $k_i \in \{0, 1\}$. We define the $\sigma$-basis as:
\begin{equation*}
\sigma_{k,e} := \frac{1}{2^e} \prod_{j=0}^{e-1} (\lambda_0 + (-1)^{k_j} \lambda_{2^j}) \in \Lambda_e\otimes_\mathbb{Z} \mathbb{Q}
\end{equation*}
where $\lambda_i$ are the elements of the $\lambda$-basis.
\end{definition}
\begin{proposition}
\label{pr: sigmaproperties}
Let $e\geq 1$. The $\sigma$-elements have the following properties:
    \begin{enumerate}[label = (\alph*)]
        \item (Idempotency and orthogonality) $\sigma_{k,e}^2=\sigma_{k,e}$ and $\sigma_{k,e}\sigma_{l,e} = 0$ for $k\neq l$. \label{pr: idem_orth}
        \item If $\eta = \sum_{k=0}^{2^e-1} a_k\sigma_{k,e}$, then $\sigma_{k,e}\eta = a_k\sigma_{k,e}$. \label{pr: extracting_coordinates_orthogonality}
        \item (Interaction between $\sigma$-bases) Let $e\leq e'$,
        \begin{gather*}
            \sigma_{l,e'}\sigma_{k,e} = \begin{cases}
                \sigma_{l,e'} & \text{ if } l=k \text{ or } |l-k| \geq 2^{e},\\
                0 & \text{otherwise.}
                \end{cases}
        \end{gather*}
        In particular, if $l\leq 2^e$, then $\sigma_{l,e'}\sigma_{k,e} = \sigma_{l,e'}$ if $l = k$, and 0 otherwise. \label{pr: inter_orthogonality}
        \item (Recursive split) $\sigma_{k,e} = \sigma_{k,e+1}+\sigma_{2^e+k,e+1}$. \label{pr: recursive_split}
        \item Let $n = n_0+2n_1+\dots+2^{e-1}n_{e-1}$, $n_i = 0,1$. Then, $\sigma_{k,e} = \frac{1}{2^e}\sum_{i=0}^{2^e-1} (-1)^{\sum i_jk_j} \lambda_{i}$. \label{pr: sigma_in_terms_of_lambda}
        \item $\sigma_{1,e} = \frac{1}{2^e}\delta_{2^e} = \frac{1}{2^e}\left(\sum_{j=0}^{2^e-1} (-1)^j\lambda_{j}\right)$. \label{pr: sigma_1_delta_and_lambda}
        \item $\alpha(\sigma_{k,e}) = \frac{1}{2^e}$ for every $k$. \label{pr: alpha_of_sigma}
    \end{enumerate}
\end{proposition}
\begin{proof}
    Parts \ref{pr: sigma_1_delta_and_lambda} and \ref{pr: alpha_of_sigma} follow directly from \ref{pr: sigma_in_terms_of_lambda}.
\begin{enumerate}[label = (\alph*)]
\item From Corollary \ref{cr: lambdaqsquared} and the fact that $\lambda_0$ is the unit of the Han–Monsky ring, one checks that $(\lambda_0+\lambda_{2^n})^2=2(\lambda_0+\lambda_{2^n})$ and $(\lambda_0+\lambda_{2^n})(\lambda_0-\lambda_{2^n}) = 0.$ Applying the definition, the claim follows.
\item Follows directly from part \ref{pr: idem_orth}.
\item Both by the fact that $k<2^n$ and $|l-k|\geq 2^n$ we conclude that $l_j=k_j$ for $j=0,\dots,n-1$. Thus,
\begin{gather*}
    \left(\prod^{n-1}_{j=0} (\lambda_0+(-1)^{k_j}\lambda_{2^j})\right)\cdot\left(\prod^{m-1}_{j=0}(\lambda_0+(-1)^{l_j}\lambda_{2^j})\right) = \\
    \left(\prod^{n-1}_{j=0} (\lambda_0+(-1)^{l_j}\lambda_{2^j})^2\right)\cdot\left(\prod^{m-1}_{j=n}(\lambda_0+(-1)^{l_j}\lambda_{2^j})\right)= 2^n\prod^{m-1}_{j=0}(\lambda_0+(-1)^{l_j}\lambda_{2^j}).
\end{gather*}
\item By definition, $\sigma_{k,e+1} + \sigma_{2^{e}+k,e+1} = \frac{1}{2}\left(\sigma_{k,e}\cdot (\lambda_0+\lambda_{2^e})+\sigma_{k,e}\cdot (\lambda_0-\lambda_{2^e})\right) = \sigma_{k,e}.$
\item By induction on $e$. The base case is clear since $\sigma_{0,1} = \frac{1}{2}(\lambda_0+\lambda_1)$ and $\sigma_{1,1} = \frac{1}{2}(\lambda_0-\lambda_1)$. Now, by the induction hypothesis,
\begin{gather*}
\prod_{j=0}^{e-1} (\lambda_0+(-1)^{k_j}\lambda_{2^j}) = (\lambda_0+(-1)^{k_{e-1}}\lambda_{2^{e-1}})\sum_{i=0}^{2^{e-1}-1} (-1)^{\sum_{j=0}^{e-2} i_jk_j}\lambda_i,
\end{gather*}
which yields the formula.
\begin{gather*}
    \sigma_{1,e} := \frac{1}{2^e}(\lambda_0-\lambda_1)\prod_{j=1}^{e-1}(\lambda_0+\lambda_{2^j}) = \frac{1}{2^e}\left(\lambda_0-\lambda_1+\dots+(-1)^{e-1}\lambda_{2^e-1}\right) = \frac{1}{2^e}\delta_{2^e}.
\end{gather*}

\end{enumerate}
\end{proof}
\begin{remark}
    Since the $\sigma$-elements form a $\mathbb{Q}$-basis of $\Lambda_e\otimes \mathbb{Q}$, the statement of \ref{pr: sigmaproperties}\ref{pr: idem_orth} represents the fact that $\Lambda_e\otimes \mathbb{Q}$ is isomorphic as a $\mathbb{Q}$-algebra to the direct product of $p^e$ copies of $\mathbb{Q}$, where the $\sigma$-elements would be the canonical basis of this product.
\end{remark}

We provide two technical lemmas that we will need later:
\begin{lemma}
    \label{lm: lambda_sigma_product_e}
    Let $0\leq k\leq 2^e-1$, $e\geq 1$, and denote $k = k_0+2k_1+...+2^{e-1}k_{e-1}$ where $0\leq k_j\leq 1$ integers. Then, $\sigma_{k,e}\lambda_{2^e-1} = (-1)^{\sum_{j=0}^{e-1} k_j}\sigma_{k,e}.$
\end{lemma}
\begin{proof}
By \ref{pr: sigmaproperties}\ref{pr: sigma_in_terms_of_lambda}, recall that $\sigma_{k,e} = \sum_{i=0}^{2^e-1} (-1)^{\sum i_jk_j} \lambda_i$. Observe that $2^e-1 = 1+2+\dots+2^{e-1}$, so $2^e-i-1 = (1-i_0)+(1-i_1)2+(1-i_2)4+\dots+(1-i_{e-1})2^{e-1}$. Therefore,
\begin{gather*}
    \lambda_{2^e-1}\sigma_{k,e} = \sum_{i=0}^{2^e-1} (-1)^{\sum i_jk_j} \lambda_{2^e-i-1} = \sum_{i=0}^{2^e-1} (-1)^{\sum (1-i_j)k_j} \lambda_i = (-1)^{\sum_{j=0}^{e-1} k_j}\sigma_{k,e}.
\end{gather*}
\end{proof}
\begin{lemma}
    \label{lm: lambda_sigma_product_e+1}
    Let $0\leq k\leq 2^{e+1}-1$, $e\geq 1$. In the same notation as the previous lemma, we have that $\sigma_{k,e+1}\lambda_{2^e-1} = (-1)^{\sum_{j=0}^{e-1} k_j}\sigma_{k,e+1}.$
\end{lemma}
\begin{proof}
    Write $k' = k$ if $k\leq 2^e-1$ and $k-2^e$ if $2^e\leq k \leq 2^{e+1}-1$. Then $\sigma_{k,e+1} = \sigma_{k',e}(\lambda_0+(-1)^{k_e}\lambda_{2^e})$, and we apply Lemma \ref{lm: lambda_sigma_product_e}:
    \begin{align*}
        \lambda_{2^e-1}\sigma_{k,e+1} &= \lambda_{2^e-1}\sigma_{k',e}(\lambda_0+(-1)^{k_e}\lambda_{2^e})\\
        &= (-1)^{\sum_{j=0}^{e-1} k_j} \sigma_{k',e}(\lambda_0+(-1)^{k_e}\lambda_{2^e}) = (-1)^{\sum_{j=0}^{e-1} k_j}\sigma_{k,e+1}.
    \end{align*}
\end{proof}
\begin{remark}
    Thus, for example, $\sigma_{2^e,2^{e+1}}\lambda_{2^e-1} = \sigma_{2^e+1,2^{e+1}},$ and $\sigma_{2^e,2^{e+1}}\lambda_{2^e-1} = -\sigma_{2^e+1,2^{e+1}}$.
    \end{remark}

\subsection{\texorpdfstring{$A_1$}{A1} singularity in characteristic 2}
We will compute the Hilbert-Kunz function of $R_{2,d}$. When $d$ is even, Yoshida \cite{yos} computed it and conjectured the formula when $d$ is odd. First, a lemma about an object of the Han–Monsky ring:


\begin{lemma}
    \label{lm: M_e_over_delta_basis}
Let $k$ be a field of characteristic 2. For $e\geq 1$, set $\mu_e := \left(k[x,y]/(x^{2^e},y^{2^e}),xy\right)$. Then $\mu_e = \delta_{2^e}+2\delta_{1}+\dots+2\delta_{2^e-1}.$
\end{lemma}
\begin{proof}
    Given that the $T$-action is given by product by a monomial, it is easy to see that the orbits of the monomials $1,x,...,x^{2^n-1},y,...,y^{2^n-1}$ under the action of $T$ produce disjoint $k$-vector subspaces that span the $k$-object – more specifically, the orbits are the following:
    \begin{equation*} 
    \begin{array}{rllllll}
        1 &\mapsto xy &\mapsto \dots &\mapsto x^{2^e-1}y^{2^e-1} &\mapsto 0,\\[.5em]
        x^i &\mapsto x^{i+1}y &\mapsto \dots &\mapsto x^{2^e-1}y^{2^e-i-1}&\mapsto 0,\\[.5em]
        y^j &\mapsto xy^{j+1} &\mapsto \dots &\mapsto x^{2^e-j-1}y^{2^e-1}&\mapsto 0.
    \end{array}
    \end{equation*}
    According to this decomposition, one sees that $x^i$ (or $y^i$) generates a cyclic $k[T]$-submodule whose isomorphism class is $\delta_{2^e-i}$.
    \end{proof}


\begin{proposition}
\label{pr: A_1_in_representation_ring}
    Let $k$ be a field of characteristic 2. Then,
    \begin{gather*}
        \left(\frac{k[[x_0,\dots,x_d]]}{(x_0^{[2^e]},\dots,x_d^{[2^e]})},Q_d\right) = \begin{cases} \mu_e^m\cdot 2\delta_{2^{e-1}} & (d=2m)\\
        \mu_e^m & (d=2m-1)
        \end{cases}
    \end{gather*}
    where $Q_d$ is as in Definition \ref{df: Qd} and $\mu_e$ as in the previous lemma.
\end{proposition}
\begin{proof}
    If $d = 2m$, $m\geq 1$, then $Q_d = x_0x_1+\dots+x_{d-2}x_{d-1}+x_d^2$. This implies that the $k$-object in question decomposes as:
    \begin{gather*}
        \frac{k[x,y]}{(x^{[2^e]},y^{[2^e]})}\otimes \stackrel{(m)}\dots \otimes \frac{k[x,y]}{(x^{[2^e]},y^{[2^e]})}\otimes \frac{k[x]}{(x^{2^e})},
    \end{gather*}
    where the $k$-object $\frac{k[x,y]}{(x^{[2^e]},y^{[2^e]})}$ has $T$-action $xy$, the $k$-object $\frac{k[x]}{(x^{[2^e]})}$ has the $T$-action $y^2$.

    If $d = 2m-1$, $m\geq 1$, then $Q_d=x_0x_1+\dots+x_{d-3}x_{d-2}+x_{d-1}x_d$ and the $k$-object decomposes as
    \begin{gather*}
    \frac{k[x,y]}{(x^{[2^e]},y^{[2^e]})}\otimes \stackrel{(m)}\dots \otimes \frac{k[x,y]}{(x^{[2^e]},y^{[2^e]})},
    \end{gather*}
    where the $k$-object $\frac{k[x,y]}{(x^{[2^e]},y^{[2^e]})}$ has $T$-action $xy$.
\end{proof}

The aim of the following lemmas is expressing $\mu_e$ over the $\sigma$-basis:


\begin{lemma}
\label{lm: M_e_over_lambda_basis}
For $e\geq 1$, $\mu_e = \sum_{k=0}^{2^e-1} (-1)^{k}(2(2^e-k)-1)\lambda_{k}$.
\end{lemma}
\begin{proof}
We use the change of variables in the remark after Definition \ref{def: lambda} on the expression in Lemma \ref{lm: M_e_over_delta_basis},
\begin{align*}
    2\delta_1+...+2\delta_{2^e-1}+\delta_{2^e}&= 2\lambda_0 +2(\lambda_0-\lambda_1) + \cdots +2(\lambda_0- \dots +\lambda_{2^e-2}) +(\lambda_0-\dots -\lambda_{2^e-1})\\
    &= \left[2\cdot (2^e-1)\lambda_0 -2\cdot (2^e-2)\lambda_1 + ... +2\lambda_{2^e-2}\right] +\left[\lambda_0-\dots - \lambda_{2^e-1}\right]\\
    &=\sum_{k=0}^{2^e-1} (-1)^{k}(2(2^e-k-1)+1)\lambda_{k}.
\end{align*}
\end{proof}

\begin{corollary}
\label{cor: A1_recursion_char_2}
    The expression $\mu_e$ verifies the following recursive formula:
    \begin{gather*}
        \mu_e = (\lambda_0-\lambda_{2^{e-1}})\mu_{e-1} + 2^{2e-1}\sigma_{1,e-1}
    \end{gather*}
    for every $e\geq 2$. 
\end{corollary}
\begin{proof}
We use the expression given by Lemma \ref{lm: M_e_over_lambda_basis},
    \begin{align*}
    \mu_e &= \sum_{k=0}^{2^e-1} (-1)^{k}(2(2^e-k)-1)\lambda_{k}\\
    &=\sum_{k=0}^{2^{e-1}-1} (-1)^{k}(2(2^e-k)-1)\lambda_{k}
        + \sum_{k=2^{e-1}}^{2^e-1} (-1)^{k}(2(2^e-k)-1)\lambda_{k}.
    \end{align*}
    The second summand is $-\lambda_{2^{e-1}}\mu_{e-1}$ by \ref{lm: lambda_p_adic_split}; as for the first summand,
    \begin{align*}
        \sum_{k=0}^{2^{e-1}-1} (-1)^{k}(2(2^e-k)-1)\lambda_{k} &= \sum_{k=0}^{2^{e-1}-1} \left[(-1)^{k}(2(2^{e-1}-k)-1) + (-1)^k2\cdot 2^{e-1}\right]\lambda_{k}=\\
        &=\sum_{k=0}^{2^{e-1}-1} (-1)^{k}(2(2^{e-1}-k)-1)\lambda_k + 2^e\sum_{k=0}^{2^{e-1}-1} (-1)^k\lambda_k =\\
        &= \mu_{e-1} + 2^e2^{e-1}\sigma_{1,e-1}.
    \end{align*}
    and the result follows from the same lemma and \ref{pr: sigmaproperties}\ref{pr: sigma_1_delta_and_lambda}.

    Alternatively, one can deduce the same recursive formula from Lemma \ref{lm: M_e_over_delta_basis} directly observing that $(\mu_e-\delta_{2^e}) = (\lambda_0+\lambda_{2^{e-1}})(\mu_{e-1}-\delta_{2^{e-1}})+2^{e-1}\delta_{2^{e-1}}$, using the definition of $\lambda_i$ and Lemma 3.3 in \cite{hanmonsky}.
\end{proof}

\begin{remark}
    Using the notation and results in \cite{mt06}, one can deduce the results above in a way that is similar in essence. Using the formula for $\varphi_{fg}$ provided in Proposition 4.2 of that paper, one directly obtains that $\varphi:= \varphi_{xy} = 2t-t^2$, which is immediately seen to satisfy the functional equations $4\varphi(t/2) = \varphi+ t$ and $4\varphi((t+1)/2) = \varphi + 3$. Using arguments very similar to those in Example 1, one concludes that $4S(a) = a + \lambda_1 a + 2(\lambda_0-\lambda_1)\Delta$, where $a = \mathscr{L}(\varphi)$. It is not difficult to see that $(\lambda_0-\lambda_1)\Delta = 2S(\Delta)$, which shows that the formula obtained is equivalent to that in Corollary \ref{cor: A1_recursion_char_2}.
\end{remark}


Once we have these elements, using the recursive formula for $\mu_e$, the computation of the Hilbert-Kunz function is not too difficult.
\begin{proposition}
\label{pr: M_e_over_sigma_basis}
Given $e\geq 1$, then $\mu_e = 2^e(\sigma_{0,e} + 2^e\sigma_{1,e}+\sum_{k=1}^{e-1} 2^k\sigma_{2^k+1,e}).$
\end{proposition}
\begin{proof}
We prove it by induction on $e$. By Proposition \ref{cor: A1_recursion_char_2}, $M_1 = 3\lambda_0-\lambda_1 = 2\sigma_{0,1}+4\sigma_{1,1},$ so the result holds when $e=1$ (where we regard $\sum_{k=1}^{0}2^k\sigma_{2^k+1,1} = 0$.)

To show the general $e\geq 1$ case, we will employ the recursive formula in Proposition \ref{cor: A1_recursion_char_2}, the property that $(\lambda_0+\lambda_{2^e})\sigma_{k,e} = 2\sigma_{k,e+1}$, and Proposition \ref{pr: sigmaproperties}\ref{pr: recursive_split}:
\begin{align*}
\mu_{e+1} &= (\lambda_0 + \lambda_{2^{e}})\mu_e + 2^{2(e+1)-1}\sigma_{1,e}\\
    &=2^e(\lambda_0+\lambda_{2^e})(\sigma_{0,e} + 2^e\sigma_{1,e}+\sum_{k=1}^{e-1} 2^k\sigma_{2^k+1,e}) +2^{2e+1}\sigma_{1,e}\\
    &=2^e\cdot 2(\sigma_{0,e+1} + 2^e\sigma_{1,e+1} + \sum_{k=1}^{e-1}2^k\sigma_{2^k+1,e+1}) + 2^{2e+1}(\sigma_{1,e+1}+\sigma_{2^e+1,e+1})\\
    &=2^{e+1}(\sigma_{0,e+1} + 2^e\sigma_{1,e+1} + \sum_{k=1}^{e-1}2^k\sigma_{2^k+1,e+1}+2^e\sigma_{1,e+1}+2^e\sigma_{2^e+1,e+1}).
\end{align*}
The result follows from the last line.
\end{proof}
\begin{theorem}
\label{th: HK_function_A_1_char_2}
For $d\geq 2$,
\begin{gather*}
    \text{HK}_{e}(R_{2,d}) =\begin{dcases}
        \frac{2^m}{2^m-1}2^{de}-\frac{(2^{m-1})^e}{2^m-1}, &\text{ if } d=2m-1 ;\\
        \frac{2^m+1}{2^m}2^{de}, &\text{ if } d=2m.
    \end{dcases}
\end{gather*}
where $R_{p,d}$ is as in Definition \ref{df: Qd}. In particular, the Hilbert–Kunz multiplicity of an $A_1$ singularity in characteristic 2 is
\begin{gather*}
    \eHK{R_{2,d}} = \begin{dcases}
        \frac{2^m}{2^m-1}, &\text{ if } d=2m-1 ;\\
        \frac{2^m+1}{2^m}, &\text{ if } d=2m.\\
    \end{dcases}
\end{gather*}
\end{theorem}
\begin{proof}
    Firstly, let $d=2m-1$. The result follows from Proposition \ref{pr: M_e_over_sigma_basis}, using idempotency and orthogonality of the $\sigma$-elements and Proposition \ref{pr: sigmaproperties}\ref{pr: alpha_of_sigma}:
    \begin{align*} 
    \text{HK}_e(R_{2,d}) &= \alpha(\mu_e^m) = 2^{em}\alpha(\sigma_{0,e} + 2^{em}\sigma_{1,e} + \sum_{k=1}^{e-1}2^{km}\sigma_{2^k+1,e}) \\
        &= 2^{em}\sum_{k=0}^e 2^{km}\frac{1}{2^e} = 2^{e(m-1)}\sum_{k=0}^e 2^{km} = \frac{2^{(e+1)m}-1}{2^m-1}.
    \end{align*}
    So the formula follows in the odd-dimensional case.\\

Now, for the even-dimensional case, $d=2m$, observe that $R_{2,d}/\m^{[2^e]} = 2\delta_{2^{e-1}}\mu_e^m$, and by Proposition \ref{pr: sigmaproperties}\ref{pr: sigma_1_delta_and_lambda}, we have that $\delta_{2^{e-1}} = 2^{e-1}\sigma_{1,e-1} = 2^{e-1}(\sigma_{1,e}+\sigma_{2^{e-1}+1,e}).$ Then, we proceed similarly – by Proposition \ref{pr: A_1_in_representation_ring}, we have that $\HK_e(R_{2,2m}) = \alpha(\mu_e^m\cdot 2\delta_{2^{e-1}}),$ and
\begin{align*}
    \mu_e^m\cdot 2\delta_{2^{e-1}} &= 2^{em}(\sigma_{0,e} + 2^{em}\sigma_{1,e} + \sum_{k=1}^{e-1}2^{km}\sigma_{2^k+1,e})\cdot 2^e(\sigma_{1,e}+\sigma_{2^{e-1}+1,e})\\
    &= 2^{e(m+1)}(2^{em}\sigma_{1,e} + 2^{(e-1)m}\sigma_{2^{e-1}+1,e}).
\end{align*}
Again, using that $\alpha(\sigma_{k,e}) = \frac{1}{2^e}$, from applying $\alpha$ to the above, we obtain that $\text{HK}_n(R_{2,d})$ is
\begin{equation*}
    2^{e(m+1)}(2^{em}\frac{1}{2^e}+2^{(e-1)m}\frac{1}{2^e}) = 2^{em}(2^{em}+2^{(e-1)m}) = 2^{nd} + \frac{1}{2^m}2^{dn} = \frac{2^m+1}{2^m}2^{dn}.
\end{equation*}
\end{proof}

\subsection{\texorpdfstring{$A_2$}{A2} singularity in characteristic 2}

\begin{proposition}
    \label{pr: A_2_in_representation_ring}
        Let $k$ be a field of characteristic 2. Then, in the Han–Monsky ring
        \begin{gather*}
            \left(\frac{k[[x_0,\dots,x_d]]}{(x_0^{[2^e]},\dots,x_d^{[2^e]})},P_d\right) = \begin{cases} \mu_e^m3\delta_{2^{e}/3} & (d=2m)\\
            \mu_e^{m-1}2\delta_{2^{e-1}}3\delta_{2^e/3} & (d=2m-1)
            \end{cases}
        \end{gather*}
        where $P_d$ was defined in Definition \ref{df: Qd}, and $\mu_e$ is as defined in Lemma \ref{lm: M_e_over_delta_basis}.
    \end{proposition}
    \begin{proof}
        Let $d=2m+1$. Then, $P_d=x_0x_1+\dots+x_{d-3}x_{d-2}+x_{d-1}^2+x_d^3$ and the object decomposes as
        \begin{gather*}
        \frac{k[x,y]}{(x^{[2^e]},y^{[2^e]})}\otimes \dots \otimes \frac{k[x,y]}{(x^{[2^e]},y^{[2^e]})} \otimes \frac{k[y]}{(y^{[2^e]})} \otimes \frac{k[x]}{(x^{[2^e]})},
        \end{gather*}
        where the $k$-object $k[x,y]/(x^{[2^e]},y^{[2^e]})$ has $T$-action $xy$, the $k$-object $k[y]/(y^{[2^e]})$ has the $T$-action $y^2$, and finally the $k$-object $k[x]/(x^{[2^e]})$ has $T$-action $x^3$. We already know that the first is $\mu_e$ and the second $2\delta_{2^{e-1}}$. The third $k$-object is $3\delta_{2^e/3}$, as one deduces from Lemma \ref{lm: lemmarepring} for $s = 0$.

        If $d=2m$, then $P_d = x_0x_1+\dots+x_{d-2}x_{d-1}+x_d^3$ and the result follows from the same discussion.
    \end{proof}

    \begin{lemma}
        \label{lm: A2_char2_recursion}
        For $e\geq 1$, let $\xi_e := 3\delta_{2^e/3}$. Then, $\xi_1 = 2\lambda_0 = 2\sigma_{0,1}+2\sigma_{1,1},\xi_2 = 3\lambda_0-\lambda_1 = 2\sigma_{0,2}+4\sigma_{1,2}+2\sigma_{2,2}+4\sigma_{3,2}$,
    \begin{gather*}
    \xi_{e+1}-\lambda_{2^e-1}\xi_e = 3\delta_{2^e}, e\geq 1.
    \end{gather*}
    \end{lemma}
    \begin{proof}
    Let $e\geq 1$, and denote $2^e = 3d+r$ and $2^{e+1} = 3D+R$, where $d,r, D,R\in \mathbb{Z}$ and $0\leq r,R<3$. Then, from Definition \ref{df: representation_ring_rational_coefficients},
    \begin{align*}
        \xi_{e+1} &= 3\lambda_0-3\lambda_1+\dots+(-1)^{D-1}3\lambda_{D-1}+(-1)^DR\lambda_{D},\\
        \xi_e &= 3\lambda_0-3\lambda_1+\dots+(-1)^{D-1}3\lambda_{d-1}+(-1)^dr\lambda_{d}.
    \end{align*}
    Then, using \ref{lm: lambda_p_adic_split}\ref{lm: p_adic_opposite} one obtains
    \begin{multline}
        \label{fm: proving_recurrence_of_Ce}
    \xi_{e+1}-\lambda_{2^e-1}\xi_e = (3\lambda_0-\dots +(-1)^DR\lambda_D)-\\
    -((-1)^dr\lambda_{2^e-d-1}+(-1)^{d-1}3\lambda_{2^e-d-2}+\dots-3\lambda_{2^e-2}+3\lambda_{2^e-1}).
    \end{multline}
    One can check that $D = 2^e-(d+1)$ and $R+r = 3$, which implies that $(-1)^DR\lambda_D-(-1)^dr\lambda_{2^e-d-1} = (-1)^D3\lambda_D$, which implies that the RHS in (\ref{fm: proving_recurrence_of_Ce}) is $3\delta_{2^e}$.
    \end{proof}

        The point of the following lemma is giving a formula of the coefficients of $\xi_e$ over the $\sigma$-basis that we will need since the rest of them get canceled in the computation of the Hilbert–Kunz function of the $A_2$ singularity, as we will see in Theorem \ref{th: HK_function_A_2_char_2}.
    \begin{lemma}
        \label{lm: C_e_critical_coefficients}
        Let $\xi_e$ as in Lemma \ref{lm: A2_char2_recursion}. Let $a_{k,e}\in \mathbb{Q}$ such that $\xi_e = \sum_{k=0}^{2^e-1} a_{k,e}\sigma_{k,e}$. Then $a_{0,e} = 2$, $a_{1,e} = 2^{e+1}$, $a_{2^k+1,e} = 2^{k+1}$ for $k=1,\dots,e-2$, $e\geq 2$.
    \end{lemma}
\begin{proof}    
        Throughout the proof, we use that $\sigma_{k,e}\xi_e = a_{k,e}\sigma_{k,e}$, and the rest of the orthogonality and idempotency properties (\ref{pr: sigmaproperties}\ref{pr: idem_orth}, \ref{pr: extracting_coordinates_orthogonality} and \ref{pr: inter_orthogonality}) without further mention. Also, $e\geq 2$.
    \begin{enumerate}
        \item We start computing $a_{0,e}$ and $a_{1,e}$, for $e\geq 2$. Since $\delta_{2^e} = 2^e\sigma_{1,e}$ by \ref{pr: sigmaproperties}\ref{pr: sigma_1_delta_and_lambda}, it follows that $\sigma_{0,e+1}\delta_{2^e} = 0$, and $\sigma_{1,e+1}\delta_{2^e} = 2^e\sigma_{1,e+1}$. Also, by Lemma \ref{lm: lambda_sigma_product_e+1}, $\sigma_{0,e+1}\lambda_{2^e-1} = \sigma_{0,e+1}$ and $\sigma_{1,e+1}\lambda_{2^e-1} = -\sigma_{1,e+1}$. Thus, multiplying the recurrence in Lemma \ref{lm: A2_char2_recursion} by $\sigma_{0,e+1}$ and $\sigma_{1,e+1}$, we obtain in each case
    \begin{align*}
    \sigma_{0,e+1}\xi_{e+1}-\sigma_{0,e+1}\lambda_{2^e-1}\xi_e = 0 &\Longrightarrow a_{0,e+1}-a_{0,e} = 0,\\
    \sigma_{1,e+1}\xi_{e+1}-\sigma_{1,e+1}\lambda_{2^e-1}\xi_e = 3\cdot 2^e\sigma_{1,e+1} &\Longrightarrow a_{1,e+1}+a_{1,e} = 3\cdot 2^e.
    \end{align*}
    Given that $a_{0,1} = a_{1,1} = 2$ by \ref{lm: A2_char2_recursion}, we have that $a_{0,e} = 2$ and $a_{1,e} = 2^e$ for $e\geq 1$.
    \item In order to compute $a_{2^k+1,e}$ for $1\leq k\leq e-2$, we first need to compute $a_{2^{e-1}+1,e}$ for every $e\geq 2$. Using the recurrence in \ref{lm: A2_char2_recursion} again, 
    \begin{gather}
        \label{fr: base_case_product}
        a_{2^{e-1}+1,e}\sigma_{2^{e-1}+1,e} = \sigma_{2^{e-1}+1,e}\xi_{e} = \lambda_{2^{e-1}-1}\sigma_{2^{e-1}+1,e}\xi_{e-1} + 3\sigma_{2^{e-1}+1,e}\delta_{2^{e-1}}.
        \end{gather}

        As for the product $\sigma_{2^{e-1}+1,e}\delta_{2^{e-1}}$ above, by \ref{pr: sigmaproperties}\ref{pr: sigma_1_delta_and_lambda}, we have that $\sigma_{2^{e-1}+1,e}\delta_{2^{e-1}} = \sigma_{2^{e-1}+1,e}2^{e-1}\sigma_{1,e-1} = 2^{e-1}\sigma_{2^{e-1}+1,e},$ using that $\sigma_{2^{e-1}+1,e}\sigma_{1,e-1} = \sigma_{2^{e-1}+1,e}$.

        About the first summand in (\ref{fr: base_case_product}), observe that for $e\geq 2$, $\lambda_{2^{e-1}-1}\sigma_{2^{e-1}+1,e} = \sigma_{2^{e-1}+1,e}$ by Lemma \ref{lm: lambda_sigma_product_e+1}, so we continue with the RHS of (\ref{fr: base_case_product}):
        \begin{gather*}
        3\sigma_{2^{e-1}+1,e}\delta_{2^{e-1}}-\sigma_{2^{e-1}+1,e}\lambda_{2^{e-1}-1}\xi_{e-1} = 3\cdot 2^{e-1}\sigma_{2^{e-1}+1,e}-\sigma_{2^{e-1}+1,e}\xi_{e-1}.
        \end{gather*}
        Finally, from \ref{pr: sigmaproperties}\ref{pr: recursive_split},
        \begin{align*}
        \sigma_{2^{e-1}+1,e}\xi_{e-1} &= \sigma_{2^{e-1}+1,e}\sum a_{s,e-1}\sigma_{s,e-1} \\
        &= \sigma_{2^{e-1}+1,e}\left(\sum_{s=0}^{2^{e-1}-1} a_{s,e-1}\sigma_{s,e} + \sum_{s=2^{e-1}}^{2^{e}-1} a_{s,e-1}\sigma_{2^{e-1}+s,e}\right) = a_{1,e-1}\sigma_{2^{e-1}+1,e}.
        \end{align*}
        We conclude from this and (\ref{fr: base_case_product}) that $a_{2^{e-1}+1,e} = 3\cdot 2^{e-1}-a_{1,e-1} = 2\cdot 2^{e-1} = 2^{e}$, and therefore,
        \begin{gather}
            \label{fm: a2e_11e2e}
        a_{2^{e-1}+1,e} = 2^{e}, e\geq 2.
        \end{gather}
    \item We now compute $a_{2^k+1,e}$ for $1\leq k\leq e-2$ and $e\geq 2$. Note that, for those $k$ and $e$, it happens again that $\sigma_{2^k+1,e+1}\delta_{2^e} = 0$, so multiplying the recurrence in \ref{lm: A2_char2_recursion} by $\sigma_{2^k+1,e+1}$, we obtain
    \begin{gather*}
        \sigma_{2^k+1,e+1}\xi_{e+1}-\sigma_{2^k+1,e+1}\lambda_{2^e-1}\xi_e = 0 \Longrightarrow a_{2^k+1,e+1}-a_{2^k+1,e} = 0.
    \end{gather*}
    This implies that for all $1\leq k\leq e-2$, $a_{2^k+1,e} = a_{2^k+1,k+1}$, and we know by the previous part (setting $e = k+1$ in (\ref{fm: a2e_11e2e})) that $a_{2^k+1,k+1} = 2^{k+1}$ for $k\geq 2$. Therefore, we conclude that
    \begin{gather*}
    a_{2^k+1,e} = 2^{k+1}, 1\leq k\leq e-2, e\geq 2.
    \end{gather*}
    \end{enumerate}
    \end{proof}

