\begin{theorem}
    \label{th: HK_function_A_2_char_2}
    The Hilbert--Kunz function of an $A_2$ singularity in characteristic 2 is
    \begin{gather*}
        \HK_e(S_{2,d}) = \begin{dcases}
        \frac{2^{m+1}+1}{2^{m+1}-1}2^{de}-\frac{2}{2^{m+1}-1}2^{e(m-1)} &(d=2m) ;\\
        \frac{2^m+1}{2^m}2^{de} &(d=2m-1);
    \end{dcases}
\end{gather*}
with $S_{p,d}$ as in Definition \ref{df: Qd}. In particular, the Hilbert–Kunz multiplicity of an $A_2$ singularity in characteristic 2 is
\begin{gather*}
    \eHK{S_{2,d}} = \begin{dcases}
    \frac{2^{m+1}+1}{2^{m+1}-1} & (d=2m) ;\\
    \frac{2^{m-1}+1}{2^{m-1}} & (d=2m-1) ;\\
\end{dcases}
\end{gather*}
\end{theorem}
\begin{proof}
    We deal with even and odd-dimensional cases separately.

    Firstly, let $d=2m+1$. By \ref{pr: A_2_in_representation_ring}, $\HK_e(S_{3,2m+1}) = \alpha\left(\mu_e^m\xi_e\right)$. Let $\xi_e$ as in \ref{lm: C_e_critical_coefficients}, and $\mu_e$ as in \ref{pr: M_e_over_sigma_basis}, so
    \begin{align*}
        \mu_e^m\xi_e&= 2^{em}(\sigma_{0,e}+2^{em}\sigma_{1,e}+\sum_{k=1}^{e-1} 2^{km}\sigma_{2^k+1,e})\sum_{k=0}^{2^e-1} a_{k,e}\sigma_{k,e}\\
        &= 2^{em}(a_{0,e}\sigma_{0,e}+2^{em}a_{1,e}\sigma_{1,e}+\sum_{k=1}^{e-1}2^{km}a_{2^k+1,e}\sigma_{2^k+1,e}).
    \end{align*}
    Using Lemma \ref{lm: C_e_critical_coefficients}, the orthogonality properties of $\sigma$-basis, \ref{pr: sigmaproperties}, and the linearity of $\alpha$,
    \begin{align*}
        \alpha(\mu_e^m\xi_e) &= 2^{em}\alpha(a_{0,e}\sigma_{0,e}+2^{em}a_{1,e}\sigma_{1,e}+\sum_{k=1}^{e-1}2^{km}a_{2^k+1,e}\sigma_{2^k+1,e})\\
        &= 2^{em}(2\frac{1}{2^e}+2^{em}2^e\frac{1}{2^e}+\sum_{k=1}^{e-1}2^{km}2^{k+1}\frac{1}{2^e})\\
        &= 2^{em}(2+2^{e(m+1)}+2\sum_{k=1}^{e-1}2^{k(m+1)}) \\
        &= 2^{em}(-2^{e(m+1)}+2\sum_{k=0}^{e}2^{k(m+1)}) = 2^{em}(-2^{e(m+1)}+2\frac{2^{(e+1)(m+1)}-1}{2^{m+1}-1}).
    \end{align*}
    Thus,
    \begin{gather*}
        \HK_e(S_{2,d}) = 2^{em}(-2^{e(m+1)}+2\frac{2^{(e+1)(m+1)}-1}{2^{m+1}-1}) = -2^{de}+2\frac{2^{m+1}2^{de}-2^{e(m-1)}}{2^{m+1}-1},
    \end{gather*}
    from which the result follows for $d=2m+1$.

    Let now $d=2m$. Recall that by Proposition \ref{pr: sigmaproperties}, we have that $\delta_{2^{e-1}} = 2^{e-1}\sigma_{1,e-1} = 2^{e-1}(\sigma_{1,e}+\sigma_{2^{e-1}+1,e})$, so $2\delta_{2^{e-1}} = 2^e(\sigma_{1,e}+\sigma_{2^{e-1}+1,e})$. Now, by Proposition \ref{pr: A_2_in_representation_ring}, we have that $\HK_e(S_{3,2m}) = \alpha\left(2\mu_e^{m-1}\delta_{2^{e-1}}\xi_e\right)$, so
    \begin{align*}
        \mu_e^{m-1}2\delta_{2^{e-1}}\xi_e &= 2^{e(m-1)}(\sigma_{0,e}+2^{e(m-1)}\sigma_{1,e}+\sum_{k=1}^{e-1} 2^{k(m-1)}\sigma_{2^k+1,e})2^e(\sigma_{1,e}+\sigma_{2^{e-1}+1,e})\sum_{k=0}^{2^e-1} a_{k,e}\sigma_{k,e}\\
        &=2^{em}2^{e(m-1)}2^ea_{1,e}\sigma_{1,e} + 2^{em}2^{(e-1)(m-1)}2^ea_{2^{e-1}+1,e}\sigma_{2^{e-1}+1,e}.
    \end{align*}
    Thus, applying $\alpha$ to the above, and using Lemma \ref{lm: C_e_critical_coefficients},
    \begin{gather*}
        \HK_e(S_{2,d}) = 2^{de}2^e\frac{1}{2^e}+2^{de}\frac{1}{2^m}2^e\frac{1}{2^e} = \frac{2^m+1}{2^m}2^{de}.
    \end{gather*}
\end{proof}


\subsection{\texorpdfstring{$A_1$ and $A_2$}{A1 and A2} singularity in characteristic 3}\label{subsec:A2_in_char_3}
Here, we compute the Hilbert–Kunz multiplicity of the $A_2$ singularity.
\begin{theorem}
    \label{th: eHK_A_1_and_A_2_in_char_3}
    For $d\geq 2$,
    \begin{gather*}
        \eHK{R_{3,d}} = 1+\frac{3\cdot 2^d}{3^{d+1}-2^d+(-1)^d} \qandq \eHK{S_{3,d}} = 1+\left(\frac{2}{3}\right)^{d-1}
    \end{gather*}
\end{theorem}
\begin{proof}
    The Hilbert–Kunz multiplicity of $R_{3,d}$ was already computed in \cite{yos}.

    As for $S_{3,d}$, first note that $k[[x_0,\dots,x_{d-1},x_d^3]]\subset k[[x_0,\dots,x_d]]$ is a free extension of rank $3$. Thus, the following chain of inequalities follows:
    \begin{align*}
    \HK_e(S_{3,d}) &=\dim_k \frac{k[[x_0,\dots,x_d]]}{(x_0^{3^e},\dots,x_d^{3^e})+(x_0^2+\dots+x_{d-1}^2+x_d^3)}\\
    &= 3\cdot \dim_k \frac{k[[x_0,\dots,x_d^3]]}{(x_0^{3^e},\dots,x_d^{3^e})+(x_0^2+\dots+x_{d-1}^2+x_d^3)}\\
    &= 3\cdot \dim_k \frac{k[[x_0,\dots,x_{d-1}]]}{(x_0^{3^e},\dots,x_{d-1}^{3^e},(x_0^2+\dots+x_{d-1}^2)^{3^{e-1}})},
    \intertext{and now, since $k[[x_0^{3^{e-1}},\dots,x_{d-1}^{3^{e-1}}]]\subset k[[x_0,\dots,x_{d-1}]]$ is also a free extension of rank $3^{d(e-1)}$,}
    \HK_e(S_{3,d}) &=3\cdot 3^{(e-1)d}\cdot \dim_k \frac{k[[x_0^{3^{e-1}},\dots,x_{d-1}^{3^{e-1}}]]}{(x_0^{3^e},\dots,(x_0^2+\dots+x_{d-1}^2)^{3^{e-1}})}\\
    &= 3\cdot 3^{(e-1)d}\cdot \dim_k \frac{k[[y_0,\dots,y_{d-1}]]}{(y_0^3,\dots,y_{d-1}^3)+(y_0^2+\dots+y_{d-1}^2)} = 3\cdot 3^{(e-1)d}\cdot \HK_1(R_{3,d-1}).
    \end{align*}
    In the mentioned Yoshida's notes, it is proven that $\HK_1(R_{3,d-1}) = 2^{d-1}+3^{d-1}$, so
    \begin{gather*}
    \eHK{S_{3,d}} = \frac{3\cdot 3^{d(e-1)}\cdot (2^{d-1}+3^{d-1})}{3^{de}} = 1+\left(\frac{2}{3}\right)^{d-1}
    \end{gather*}


\end{proof}
A corollary to the formula of $\eHK{S_{3,d}}$ is that the $A_2$ singularity in characteristic 3 is a counterexample to Conjecture 2.7 in \cite{jnskw}:
\begin{corollary}
    $\eHK{S_{3,d}}<\eHK{R_{2,d}}$ if and only if $d\geq 8$ even and $d\geq 13$ odd.
\end{corollary}
\begin{proof}
    It follows from direct computation with the formula in Theorems \ref{th: eHK_A_1_and_A_2_in_char_3} and \ref{th: HK_function_A_1_char_2}.
\end{proof}

\subsection{The inequality.}
By the results in the previous chapter of this paper, it easily follows that the Hilbert–Kunz multiplicity of an $A_2$ singularity and an $A_1$ singularity are different: 
\begin{theorem}[Main theorem in characteristic 2]
    \label{th: A_1_A_2_ineq_char_2}
    For $d\geq 2$, $\eHK{S_{2,d}}>\eHK{R_{2,d}}$.
\end{theorem}
\begin{proof}
Let $d=2m-1$. Then, from Theorems \ref{th: HK_function_A_1_char_2} and \ref{th: HK_function_A_2_char_2},
\begin{gather*}
    \eHK{R_{2,d}}<\eHK{S_{2,d}} \Leftrightarrow \frac{2^m}{2^m-1}<\frac{2^{m-1}+1}{2^{m-1}} \Leftrightarrow 2^d<2^d+2^{m-1}-1,
\end{gather*}
which is true for every $m>1$. If $d = 2m$, from \textit{loc. cit.}
\begin{gather*}
    \eHK{R_{2,d}}<\eHK{S_{2,d}} \Leftrightarrow \frac{2^m+1}{2^m}<\frac{2^{m+1}+1}{2^{m+1}-1} \Leftrightarrow 2\cdot 2^d + 2^m-1<2\cdot 2^d+2^{m},
\end{gather*}
which is again true for every $m\geq 1$.
\end{proof}

\begin{theorem}[Main theorem in characteristic 3]
    \label{th: A_1_A_2_ineq_char_3}
    For $d\geq 2$, $\eHK{S_{3,d}}>\eHK{R_{3,d}}$.
\end{theorem}
\begin{proof}
By Theorem \ref{th: eHK_A_1_and_A_2_in_char_3}, we have to compare the terms $(2/3)^{d-1}$ and $3\cdot 2^d/(3^{d+1}-2^d+(-1)^d)$. Now,
    \begin{gather*}
        (2/3)^{d-1}> 3\cdot 2^d/(3^{d+1}-2^d+(-1)^d)\Leftrightarrow 3^{d+1}-2^d+(-1)^d > 3^d\cdot 2 \Leftrightarrow 3^d-2^d+(-1)^d >0,
    \end{gather*}
    where the second and last equivalence hold because $3^d-2^d+(-1)^d>0$ for all $d\geq 2$.
\end{proof}

\begin{corollary}
    Let $(R,\m)$ be a non-regular complete intersection of characteristic $p>3$ and dimension $d\geq 2$. Then, $\eHK{R}\geq \eHK{R_{p,d}}.$ Moreover, if $\hat{R}\not\cong R_{p,d}$, then
    \begin{gather}
    \eHK{R}\geq \eHK{S_{p,d}}> \eHK{R_{p,d}}.
    \end{gather}
    In particular, the strong Watanabe–Yoshida conjecture holds for complete intersections of characteristic $p>3$.
\end{corollary}

\section{Strong Watanabe--Yoshida conjecture for complete intersections of~characteristic~2~and~3.}\label{sec:enescu_shimomoto_char_2}

The goal of this section is to extend Theorem 3.4 in \cite{enshi} to characteristics 2 and 3, which, together with Theorems \ref{th: A_1_A_2_ineq_char_2} and \ref{th: A_1_A_2_ineq_char_3}, yield the strong Watanabe–Yoshida Conjecture for complete intersections in these two cases. Enescu and Shimomoto's argument relies on Lemma 3.1 in \cite{enshi}, allowing them to \say{complete squares} in the power series ring over a field whose characteristic is not 2. However, that lemma does not work in characteristic 2. This section provides a lemma that solves this issue, thus completing the proof in characteristic 2.

\begin{notation}
    We will use multi-index notation in the following lemmas, so we will write $f = \sum f_\ue x_1^{e_1}\dots x_n^{e_n}$ where $\ue:=(e_1,\dots,e_n)$, and we define $|\ue| = \sum e_i$ the norm of the multi-index.
\end{notation}
\subsection{Characteristic 2 case.}
\begin{lemma}
\label{lm: quadratic_equation_power_series_char_2}\label{lm: units_cubic_roots_in_char2}
    Let $k=\bar{k}$ be a field of characteristic 2 and $v,w\in k[[x_0,\dots,x_d]]$, where $v$ is a unit. Then,
    \begin{enumerate}[label=(\alph*)]
    \item There exists $t\in k[[x_0,\dots,x_d]]$ such that $t^2+vt+w = 0$. Moreover, if $w$ is a unit, then $t$ also is.
    \item There exists a unit $s\in k[[x_0,\dots,x_d]]$ such that $s^3 = v$.
    \end{enumerate}
\end{lemma}
\begin{proof}
    We first prove (a). Let $u=v^{-1}$. A solution to the equation exists if and only if $t$ exists such that $t = v^{-1}(t^2+w) = u(w+t^2)$, which is the case if and only if the following set of equations has a solution over $k$:
    \begin{gather}
        \label{fr: coefficients_of_t}
        t_{\ue} = \sum_{\ue'+\ue'' = \ue} u_{\ue'}(w_{\ue''}+\sum_{\uf+\uf'=\ue''} t_{\uf}t_{\uf'}).
    \end{gather}
    Observe that $t_\ue$ only appears on the RHS only if $\uf = 0, \uf' = \ue$ or $\uf = \ue$ and $\uf' = 0$. In both these cases, we have that $t_{\uf}t_{\uf'} = t_0t_{\ue}.$ Because $k$ has characteristic 2, these two terms cancel each other out. Thus, for every $\ue$, the expression on the right side depends on coefficients of $t$ of monomials of strictly lower degree, i.e., it depends on coefficients $t_{\uf},t_{\uf'}$ such that $|\uf|,|\uf'|< |\ue|.$

    The equation for $\ue = 0$ has a solution because the field is algebraically closed, so it follows by induction on the norm of the multi-index that the set of equations (\ref{fr: coefficients_of_t}) has a solution.

    Let us now prove (b). Let $u = \sum b_{\underline{e}} x_0^{e_0}\dots x_d^{e_d}$. There exists a series $s = \sum a_{\underline{e}} x_0^{e_0}\dots x_d^{e_d}$ such that $s^3 = u$ if and only if the following systems of equations have a solution:
\begin{gather}
    \label{fr: equations_cubic_root_char_2}
    \sum_{\underline{i}+\underline{j}+\underline{k} = \ue} a_{\underline{i}}a_{\underline{j}}a_{\underline{k}} = b_{\ue}, \ue \in \mathbb{Z}^{d+1}_{\geq 0}.
\end{gather}
The fact that these systems of equations have a solution in $k$ follows from induction on the norm of the multi-index $\ue$. 
\end{proof}

The following lemma is the characteristic 2 analog of Lemma 3.1 in \cite{enshi}, used for completing squares in characteristic not 2.
\begin{lemma}[Completing squares in characteristic 2]
\label{lm: power_series_completing_squares_in_char_2}
    Let $k$ be an algebraically closed field of characteristic 2 and put $A = k[[x_2,\dots,x_d]]$. Consider $B = A[[x_0,x_1]]$ and $F = x_0x_1 + Q(x_2,\dots,x_d) + G$ with $Q\in A$ a quadratic form and $G\in \mathfrak{m}_B^3$, where $\mathfrak{m}_B$ is the maximal ideal of $B$. Then there exist $a_0,a_1,b_0,b_1 \in B$ units, $a_2,b_2\in (x_2,\dots,x_d)B$ and $G_1\in (x_2,\dots,x_d)^3B$ such that 
    \begin{gather*}
        F = (a_0x_0+a_1x_1+a_2)(b_0x_0+b_1x_1+b_2)+Q(x_2,\dots,x_d) + G_1.
    \end{gather*}
\end{lemma}
\begin{proof}
    Let $x = x_0$ and $y = x_1$ for simplicity. We can assume that $F = x^2+xy+y^2+Q_{d-2}(x_2,\dots,x_d)$ after a change of variables. Then, note that we can express $G$ in the following way:
\begin{equation}
\label{gee}
G = c + ax + by + Ax^2 + Bxy + Cy^2,
\end{equation}
where $c\in (x_2,\dots, x_d)^3,$ $a,b\in (x_2,\dots, x_d)^2,$ $A,B,C\in (x_2,\dots,x_d).$

Let $u := 1 + A$, $v := 1 + B$ and $w := 1 + C$, which are units. Due to Lemma \ref{lm: quadratic_equation_power_series_char_2}, there exists a unit $t$ such that $ut^2+vt+w = 0$. The result follows by letting 
\begin{gather*}
\begin{array}{lll}
    a_0 = u,& a_1 = t^{-1}w,&a_2=uv^{-1}b+t^{-1}wv^{-1}a,\\
    b_0 = 1,& b_1 = t,& b_2 = v^{-1}ta+v^{-1}b,
\end{array} 
\end{gather*}
and $G_1 = c+a_2b_2$.
\end{proof}
\begin{lemma}
    \label{lm: change_of_variables_xy}
    Using the notation above, there is a change of variables transforming $(a_0x+a_1y+a_2)(b_0x+b_1y+b_2)$ into $xy.$
\end{lemma}
\begin{proof}
    Let us define a change of variables where $x_i\mapsto x_i$ for $i\geq 2$, and 
    \begin{gather*}
        \left(\begin{array}{c} x\\ y\end{array}\right)\mapsto \left(\begin{array}{cc} a_0 & a_1\\ b_0 & b_1\end{array}\right)^{-1}\left(\begin{array}{c} x\\ y\end{array}\right).
    \end{gather*}
    This matrix is invertible because its determinant is $a_0b_1+a_1b_0 = v,$ which is a unit.
\end{proof}
We will also use the following lemma of quadratic forms in characteristic 2 in the main result of the section.
\begin{corollary}[Diagonalization of quadratic forms in characteristic 2]
    \label{cor: diagonalization_quadratic_forms_char_2}
        Let $k$ be an algebraically closed field of characteristic 2. Let $Q$ be a quadratic form over $k$. Then, $Q = Q_k$ for some $k$, for $Q_k$ as in Definition \ref{df: Qd}.
    \end{corollary}
    \begin{proof}
        See Theorem 7.31 in \cite{elkame}.
    \end{proof}

The following result is the extension of Theorem 3.4 in \cite{enshi} to characteristic 2.
\begin{theorem}
    \label{th: strong_enescu_shimomoto_char_2}
        Let $(R,\mathfrak{m},k)$ be a $d$-dimensional singular complete local hypersurface ring of characteristic $p = 2$, where $k$ is algebraically closed. Then one of the following is true:
        \begin{enumerate}
        \item $R\cong k[[x_0,\dots,x_d]]/(Q_d),$ or
        \item $e_{HK}(R)\geq e_{HK}(k[[x_0,\dots,x_d]]/(P_d))$,
        \end{enumerate}
        where $P_d$ is as defined in Definition \ref{df: Qd}.
    \end{theorem}
    \begin{proof}
        Set $R = k[[x_0,...,x_d]]/(F),$ where we write $F = Q+G$ for $Q$ the homogeneous part of degree $2$ and $G\in \mathfrak{m}^3$. If $R\ncong R_{d,2},$ we will prove that $\eHK{R}\geq \eHK{S_{p,d}}$. Thanks to Lemma \ref{cor: diagonalization_quadratic_forms_char_2}, we can assume, after a suitable change of variables, that $Q = Q_k$ for some $k<d$, where $Q_k$ is as in Definition \ref{df: Qd} (note that the inequality is strict). Let us now define the polynomial with which we will deform the hypersurface. Let $\delta = 0$ if the coefficient of $x_d^3$ in $G$ is non-zero, and $\delta = 1$, otherwise.
        \begin{enumerate}
            \item If $k$ odd, then define 
            \begin{equation*}
                g := \begin{cases}
                    x_{k+1}x_{k+2} + \dots + x_{d-1}^2 + \delta x_d^3 & \text{if $d$ is odd},\\
                    x_{k+1}x_{k+2} + \dots + x_{d-2}x_{d-1} + \delta x_d^3 & \text{if $d$ is even}.
                \end{cases}
            \end{equation*}
            \item If $k$ is even, then let
                \begin{equation*}
                    g = \begin{cases}
                        x_{k}x_{k+1} + \dots + x_{d-1}^2 + \delta x_d^3 & \text{if $d$ is odd},\\
                        x_{k}x_{k+1} + \dots + x_{d-2}x_{d-1} + \delta x_d^3 & \text{if $d$ is even}.
                    \end{cases}
                \end{equation*}
        \end{enumerate}
            Due to the upper semi-continuity of the Hilbert-Kunz multiplicity, Theorem 2.6 in \cite{enshi}, there exists a dense $\Lambda\subset k$ such that $\forall \alpha\in \Lambda\setminus \lbrace 0 \rbrace,$ then
            \begin{equation*}
                e_{HK}\left(k[[x_0,\dots,x_d]]/(F+\alpha g)\right) \leq e_{HK}\left(k[[x_0,\dots,x_d]]/(F)\right).
            \end{equation*} 
            We make a different transformation depending on the parity of $k$:
        \begin{enumerate}
            \item If $k$ is odd, then $F_\alpha = F+\alpha g$ takes the following expression
            \begin{equation*}
                x_0x_1 + \dots + x_{k-1}x_k + \alpha x_{k+1}x_{k+2} + \dots + \begin{cases}
                \alpha x_{d-1}^2 + \alpha \delta x_d^3 + G & \text{if $d$ is odd},\\
                \alpha \delta x_d^3 + G & \text{if $d$ is even}.
                \end{cases}
            \end{equation*}
            Re-scaling the coordinates we can assume that $\alpha = 1$, $\delta = 1$ and $G \in \m^3$. 
            \item If $k$ is even, then the same argument we used above yields that
                \begin{equation*}
                    F_\alpha = x_0x_1 + \dots + x_k^2 + \alpha x_{k}x_{k+1} + \dots +
                    \begin{cases}
                    \alpha x_{d-1}^2 + \alpha \delta x_d^3 + G & \text{if $d$ is odd}\\
                    \alpha \delta x_d^3 + G &\text{if $d$ is even}
                    \end{cases}
                \end{equation*}
                where we can again assume $\alpha = 1$, $\delta = 1$ and $G \in \m^3$. Then transform $F_1$ via the change of variables defined by $x_{k} + x_{k+1}\mapsto x_{k+1}$ and $x_i\mapsto x_i$ for $i\neq k+1$ to obtain
            \begin{equation*}
            F_1 = x_0x_1 + \dots + x_{k}x_{k+1} + \dots +
            \begin{cases}
            x_{d-1}^2 + x_d^3 + G & \text{if $d$ is odd,}\\
            x_d^3 + G &\text{if $d$ is even.}
            \end{cases}
            \end{equation*}
        \end{enumerate}
        Now, if $d\geq 2$, Lemmas \ref{lm: power_series_completing_squares_in_char_2} and \ref{lm: change_of_variables_xy} imply that $F_\alpha = x_0x_1 + P_{d-2} + G_1$ where $G_1\in (x_2,\dots,x_d)^3$. If $d-2\geq 2$, we can apply the lemmas again to $P_{d-2}+G_1$, and continue recursively until we obtain the following:
        \begin{equation*}
            F_1 = x_0x_1 + \dots + \begin{cases} x_{d-1}^2 + x_d^3 + G & \text{if } d \text{ odd, where } G\in (x_{d-1}^3,x_{d-1}^2x_d,x_{d-1}x_d^2,x_d^4), \\ x_d^3 + G & \text{if } d \text{ even, where } G\in (x_d)^4.\end{cases}
        \end{equation*}
        Let's study both cases separately.
        \begin{enumerate}
        \item Let $d$ be odd. The general case is easily deduced from the case $d = 1$, so let $x = x_0$ and $y = x_1$ for simplicity. Note that $G = Ax^3 + Bx^2y + Cxy^2 + Dy^3$ where $A,B,C,D\in k[[x,y]],$ and $D$ is not a unit, so
        \begin{align*}
        F_1 =&\ x^2 + y^3 + Ax^3 + Bx^2y + Cxy^2 + Dy^3\\
        =&\ (1+Ax+By)x^2 + ((1+D)y+Cx)y^2.
        \end{align*}
        Let $u := 1+D$, which is a unit. Doing the change of variables $x \mapsto x; y \mapsto u^{-1}(Cx+y),$
        \begin{gather*}
            (1+Ax+Bu^{-1}(Cx+y))x^2+yu^{-2}(Cx+y)^2 = vx^2+u^{-2}y^3,
        \end{gather*}
        where $v = 1+(A+Bu^{-1}C)x+(Bu^{-1}+C^2u^{-2})y$ is a unit. Now, observe that $F_1$ and $v^{-1}F_1$ define the same principal ideal, so we can assume that $F_1 = x^2+wx^3$, with $w = (vu^2)^{-1}$. By Lemma \ref{lm: units_cubic_roots_in_char2}, there exists a unit $t$ such that $t^3 = w$, so after applying the change of variables $x \mapsto x; y \mapsto t^{-1}y,$
        we finally map $F_1$ to $x^2+y^3.$
        \item If $d$ is even, we can then write $F_1 = x_0x_1+\dots+x_{d-2}x_{d-1}+x_d^3(1+H)$ where $H$ is not a unit. Let $w = 1+H$. Since $F_1$ and $w^{-1}F_1$ generate the same principal ideal, we can assume that $F_1 = w^{-1}x_0x_1+\dots+w^{-1}x_{d-2}x_{d-1}+x_{d}^3$. Finally, we can apply the change of variables
        \begin{gather*}
        \begin{cases}
            x_{2m} \mapsto w^{-1}x_{2m}, &m<d/2\\
            x_{2m+1} \mapsto x_{2m+1}, &m<d/2\\
            x_d \mapsto x_d,
        \end{cases}
        \end{gather*}
        which maps $F_1$ to $x_0x_1+\dots+x_{d-2}x_{d-1}+x_d^3.$
        \end{enumerate}
    \end{proof}
    In particular, it follows from Theorem \ref{th: A_1_A_2_ineq_char_2} an extension of Theorem 3.1 in \cite{enshi} to characteristic 2:
    \begin{corollary}
        \label{th: enescu_shimomoto_char_2}
            Let $(R,\mathfrak{m},k)$ be a $d$-dimensional singular complete local hypersurface ring of characteristic $p = 2$, where $k$ is algebraically closed. Then one of the following is true:
            \begin{enumerate}
            \item $R\cong k[[x_0,\dots,x_d]]/(Q_d),$ or
            \item $e_{HK}(R)\geq e_{HK}(k[[x_0,\dots,x_d]]/(Q_d))$,
            \end{enumerate}
            where $Q_d$ is as defined in Definition \ref{df: Qd}.
        \end{corollary}

\subsection{Characteristic 3 case.}
A slight modification of Enescu and Shimomoto's proof is enough to extend Theorem 3.4 in \cite{enshi} to characteristic 3.
\begin{theorem}
    \label{th: strong_enescu_shimomoto_char_3}
    Let $(R,\mathfrak{m},k)$ be a $d$-dimensional singular complete local hypersurface ring of characteristic 3. Then, one of the following is true:
    \begin{enumerate}
    \item $R\cong k[[x_0,...,x_d]]/(\sum_{i=0}^d x_i^2),$ or
    \item $e_{HK}(R)\geq e_{HK}(k[[x_0,\dots,x_d]])/(x_0^2+\dots + x_{d-1}^2 + x_d^3).$
    \end{enumerate}
\end{theorem}
\begin{proof}
    Repeating the proof by Enescu and Shimomoto, if we write $R \cong k[[x_0,\dots,x_d]]/(f)$, and $f$ is not in case $(1)$, then we can deform $f$ to $F_\alpha = v_0x_0^2 + \dots + v_{d-1}x^2_{d-1} + v_dx_d^3,$ where the $v_i$ are units, and the Hilbert-Kunz multiplicity of $F_\alpha$ is less than that of $f$. Hence, the element $v_d^{-1}F_\alpha$ generates the same ideal as $F_\alpha.$ We now apply Lemma 3.3 in \cite{enshi} to solve the equations $w_i^2 = v_d^{-1}v_i,$ for $i<d.$ Then, $v_d^{-1}F_\alpha = x_0^2 + \dots + x_{d-1}^2 + x_d^3,$ and the result follows.
\end{proof}


\subsection{Main theorem in characteristic 2 and 3.}
\begin{theorem}[Strong Watanabe–Yoshida conjecture for complete intersections in characteristic 2 and 3]
    \label{maintheoremB}
    Let $d\geq 2,$ and $k$ be a field of characteristic $p = 2,3$. If $(R,\mathfrak{m},k)$ is a non-regular complete intersection ring of dimension $d$, and $\hat{R}\not \cong R_{p,d}$, then
    \begin{equation}
        \label{fr: final_inequality}
    \eHK{R}\geq \eHK{S_{p,d}}>\eHK{R_{p,d}}
    \end{equation}
    \end{theorem}
    \begin{proof}
        The first inequality is proven as in Theorem \ref{maintheoremA} using Theorem \ref{th: strong_enescu_shimomoto_char_2} for characteristic $2$ and Theorem \ref{th: strong_enescu_shimomoto_char_3} in the case of characteristic $3$. The second inequality is the content of Theorems \ref{th: A_1_A_2_ineq_char_2} and \ref{th: A_1_A_2_ineq_char_3}.
    \end{proof}

\section{Revisiting low dimension and low multiplicity.}\label{sec:revisiting_literature}

As mentioned in the introduction, the Watanabe–Yoshida conjecture has been solved in complete generality only in low-dimensional cases. In particular, the only instances in which the three statements of the conjecture have been solved are dimensions 2 through 4, with characteristic $p>2$. In dimensions 5 through 7, the Watanabe–Yoshida conjecture's strong form did not always follow from Aberbach and Enescu's results since some arguments depended on Enescu and Shimomoto's theorem.

Furthermore, the characteristic 2 case is hardly ever covered in the literature; the two-dimensional case does cover it, but it was not included as part of the general statement of the Watanabe–Yoshida conjecture until \cite{yos}.

In this section, we will extend these low-dimensional (and low-multiplicity) cases of the conjecture to characteristic 2, and also show that the strong version of the conjecture follows. In other words, the main result of this section is the following:
\begin{theorem}[Watanabe–Yoshida conjecture]
    \label{th: watanabe_yoshida_low_dimension}
    Let $p>0$ be prime and $2\leq d \leq 6$. Set
    \begin{equation*}
        R_{p,d}:=\mathbb{F}_p[[x_0,...,x_d]]/(Q_d),
    \end{equation*}
    where
    \begin{equation*}
        Q_d = \begin{cases}x_0x_1+x_2x_3 + \dots + x_{d-1}x_d & \text{if $d$ is odd},\\
        x_0x_1 + x_2x_3 + \dots +x_{d-2}x_{d-1}+x_d^2 & \text{if $d$ is even}.\end{cases}
    \end{equation*}
    Let $(R,\m,k)$ be an unmixed non-regular local ring of dimension $d$ and characteristic $p$. Then
    \begin{enumerate}
        \item $e_{\text{HK}}(R)\geq e_{\text{HK}}(R_{p,d})$,
        \item if $\eHK{R}=\eHK{R_{p,d}}$, then $\hat{R}\cong R_{p,d}\hat{\otimes}_{\mathbb{F}_p} k$, i.e.~the completion of $R$ is isomorphic to the coordinate ring of a quadric hypersurface.
        \item $e_{\text{HK}}(R_{p,d})\geq 1+c_d$,
    \end{enumerate}
    where $c_d$ are the coefficients of the Taylor expansion of $\sec x + \tan x$.
    \end{theorem}

We recall the known formulas for $\eHK{R_{p,d}}$. In characteristic $p\geq 3$, dimensions $4$ through $6$ where computed in \cite{yos}, and dimension 7 in \cite{ac24}. The values of $\eHK{R_{2,d}}$ are from Theorem \ref{th: HK_function_A_1_char_2}.
