\vspace{-2em}
\begin{remark}
Note that $\eHK{R_{p,d}}$ is a decreasing function on $p>0$ for $4\leq d\leq 7$.
\end{remark}
\begin{lemma}[Proposition 2.13, \cite{wy00}]
    \label{lm: ehkrpd_decreasing_with_dimension}
If $x$ is an $R$-regular element, then $\eHK{R/xR}\geq \eHK{R}$. In particular, for all $p>2$ and $d\geq 1$, we have that $\eHK{R_{p,d}}\geq \eHK{R_{p,d+1}}$.
\end{lemma}

\begin{proof}[Proof of Theorem \ref{th: watanabe_yoshida_low_dimension}]
    We will focus on the first two statements, the strong part of the conjecture, since it has already been proven up to dimension 7 that $\eHK{R_{p,d}}\geq 1+c_d$.

    We prove the result in a series of claims, first solving dimensions 3 and 4, then multiplicity 2 to 4, and finally dimensions 5 and 6.

\begin{claim}
    The strong Watanabe–Yoshida conjecture holds for dimension $d=3,4$ and characteristic $p>0$:
\end{claim}
    \begin{enumerate}
        \item Let $d = 3$ first. Lemma 3.3 in \cite{wy05} implies that if $e>2$, then $\eHK{R}>\frac{4}{3} = \eHK{R_{2,3}}$. So we only have to deal with the case when $R$ is a double point, i.e.~$e=2$. In that case, there are two options: either $\eHK{R} = 2$, in whose case the result follows, or $\eHK{R}<2$, in whose case $R$ is a hypersurface by Corollary 1.10, \cite{wy05}. In this last case, the result follows from Theorem \ref{maintheoremB}.
        \item Now, let us discuss the four-dimensional case. We will carefully adjust the computations in the proof of Theorem 4.3 \cite{wy05} to obtain sharper bounds that work in the characteristic 2 case.
        \begin{enumerate}
            \item Let $e=2$. The same argument applies; if $\eHK{R}=2$, the result follows since $2>\eHK{R_{2,4}}$, and if $\eHK{R}<2$, then $R$ is hypersurface by Corollary 1.10 \cite{wy05} and the strong Watanabe–Yoshida conjecture follows from Theorem \ref{maintheoremB}.
            \item Let $e = 3$. In the computation in Claim 1 in the proof of Theorem 4.3, \cite{wy05}, it is shown that $\eHK{R}\geq 3\left(v_s-\frac{2(s-1)^4}{4!}\right)$ for $s\geq 1$. For $s = 2$, this means $\eHK{R}\geq \frac{30}{24} = \frac{5}{4}$. To obtain the strict inequality with the value $\frac{5}{4}$, it is enough by setting $s = 2.1$, and using the formula
            \begin{gather}
                \label{fm: formula_vs}
                v_s = \sum_{n=0}^{\lfloor s\rfloor}(-1)^n\frac{(s-n)^d}{n!(d-n)!}
            \end{gather}
            from Section 3 of \cite{aben12}. This computation yields that $\eHK{R} \geq 1.3 >\frac{5}{4}.$
            \item Let $4\leq e\leq 9$. In the computation in Claim 1 in the proof of Theorem 4.3 in \cite{wy01}, it is shown that $\eHK{R}\geq \frac{(13-e)e}{24}$ for $3\leq e\leq 10$, and $\frac{(13-e)e}{24}>\frac{5}{4}$ whenever $4\leq e\leq 9$.
            \item Let $10\leq e\leq 30$. In Claim 2 in the proof of the same result, it is shown that $\eHK{R}\geq \frac{(78-e)e}{384}$, and $\frac{(78-e)e}{384}>\frac{5}{4}$ for every $10\leq e\leq 30$.
            \item Let $e\geq 31$. In this case, by the usual inequalities between the usual multiplicity and the Hilbert–Kunz multiplicity, we have that $\eHK{R}\geq \frac{e}{d!} \geq \frac{31}{24} >\frac{5}{4}.$
        \end{enumerate}
    \end{enumerate}


\begin{claim}
    \label{cl: low_multiplicity}
The strong Watanabe–Yoshida conjecture holds for dimension $d\geq 3$, characteristic $p>0$, and multiplicity $e(R) = 2,3,4$.
\end{claim}
    First, observe that we can assume the ring is complete, and therefore the homomorphic image of a Cohen–Macaulay ring.
\begin{enumerate}
    \item If $e(R) = 2$, the strong Watanabe–Yoshida conjecture follows from Corollary 1.10 in \cite{wy01} and Theorems \ref{maintheoremA} and \ref{maintheoremB}.
    \item As for $e(R) = 3$, if $\eHK{R}\geq \frac{3}{2}$, then $\eHK{R}>\eHK{R_{2,d}}$ for $d\geq 3$. If $\eHK{R}<\frac{3}{2}$, then $R$ is Gorenstein by Theorem 2.4 (iii) in \cite{aben12}, so if $R$ is not a complete intersection, Theorem 4.1 in \cite{aben12} implies that $\eHK{R}\geq 13/8 >\eHK{R_{2,d}}$ for all $d\geq 3$ – see Theorem \ref{th: HK_function_A_1_char_2}. Otherwise, $R$ is a complete intersection, and the result follows from Theorem \ref{maintheoremB}.
    \item Finally, let $e(R) = 4$. If $\eHK{R}\geq \frac{4}{3}$, again $\eHK{R}>\eHK{R_{2,d}}$ for $d\geq 4$. Otherwise, we have that $\eHK{R}<\frac{4}{3}$, and the same argument used in \cite{aben12} implies that $R$ has to be a complete intersection.
\end{enumerate}

\begin{claim}
The strong Watanabe–Yoshida conjecture holds for dimension $d =5, 6$ and characteristic $p>0$.
\end{claim}
    We revisit the proof of Theorem 5.2 \cite{aben12} --- see that paper for details. First, we can assume that the residue field of $R$ is infinite, that $\eHK{R}>2$, and therefore that $R$ is a domain. We can also assume that it is a domain. Let $J$ be a minimal reduction of $\m$. In the proof of the theorem, Aberbach and Enescu show that $R$ is either a Cohen–Macaulay ring with minimal multiplicity or $\mu(\mathfrak{m}/J^*)\leq e-2$, where $J^*$ is the tight closure of $J$.
    \begin{enumerate}
    \item In the minimal multiplicity case, either $\eHK{R_{p,d}}\geq 1.5$ or $R$ is a hypersurface, so in both cases the strong Watanabe–Yoshida conjecture holds in every positive characteristic by Theorems \ref{th: HK_function_A_1_char_2}, \ref{maintheoremA}, and \ref{maintheoremB}.
    \item Otherwise, $\mu(\m/J^*)\leq e-2$ and we have to separate between dimension 5 and 6.
    \begin{enumerate}
        \item Let $d = 5$. The bounds provided in Aberbach–Enescu are sharp for every multiplicity $e\neq 137$, i.e.~$\eHK{R}>\eHK{R_{p,d}}$. When $e = 137$, the lower bound is $e(R)/d! = \frac{137}{5!}<\eHK{R_{p,d}}$, so we need to improve the bound in this case, but simply applying Theorem 3.2 in \cite{aben12} and the expression (\ref{fm: formula_vs}) for $r = 135$ and $s = 1.4$ shows that $\eHK{R}\geq 4.5$.
        \item Let $d = 6$. Again, by the inequality between the Hilbert–Kunz multiplicity and the usual multiplicity, we have that for all $e\geq 811$, 
        \begin{gather*}
            \eHK{R}\geq \frac{811}{720} >\frac{810}{720} = \frac{9}{8}.
        \end{gather*}
        Let us now show the inequality when $5\leq e\leq 810$. For each $s\geq 1$, we define the function
        \begin{gather*}
            G_s(e) := e(v_s-(e-2)v_{s-1}) = -e^2v_s+(v_{s}+2v_{s-1})e.
        \end{gather*}
        We know from Theorem 3.2 in \cite{aben12} that $\eHK{R}\geq G_s(e)$ for every $s\geq 1$. We will prove that for every $5\leq e\leq 810$, $G_s(e)>\frac{9}{8}$.

        For example, if $s = 2.63$ and $5\leq e\leq 9$, it can be easily checked with a computer using (\ref{fm: formula_vs}) that $G_s(e)>\frac{9}{8}$. Table \ref{tab: e_vs_s_dimension_6} shows the value of $s$ that works for each $5\leq e\leq 810$.

        \begin{table}[h!]
        \centering
        \renewcommand{\arraystretch}{1.5} 
        \setlength{\tabcolsep}{10pt} 
        \begin{tabular}{c|c}
        $e$ & $s$ \\ \hline
        $5\leq e\leq 9$ & 2.63\\
        $10\leq e\leq 16$ & 2.31 \\
        $17\leq e\leq 28$ & 2.1 \\
        $29\leq e\leq 58$ & 1.9 \\
        $59\leq e\leq 296$ & 1.6 \\
        $297\leq e\leq 810$ & 1.3 \\
        \end{tabular}
        \vspace{1em} 
        \caption{Values of $s$ such that $G_s(e)>\eHK{R_{2,6}}$.}
        \label{tab: e_vs_s_dimension_6}
        \end{table}
    \end{enumerate}
    \end{enumerate} 



\end{proof}

\begin{corollary}
    \label{cor: watanabe_yoshida_low_multiplicity}
The strong Watanabe–Yoshida conjecture holds for dimension $d\geq 2$ and multiplicity $e(R)\leq 5$.
\end{corollary}
\begin{proof}
    The cases of multiplicity $e(R) = 2,3,4$ follow from Claims \ref{cl: low_multiplicity} and Watanabe–Yoshida in dimension 2. Thus, let $e(R) = 5$. Section 3 of \cite{aben12} shows a characteristic free argument that $\eHK{R}\geq 1.112$. By Theorem \ref{th: HK_function_A_1_char_2}, $\eHK{R_{2,7}} = \frac{16}{15}<1.112$. The result follows from the fact that $\eHK{R_{p,7}}$ is a decreasing function (see Table \ref{tab: eHK_quadrics_low_dimension} above), and Lemma \ref{lm: ehkrpd_decreasing_with_dimension}.
\end{proof}

\begin{theorem}
    The strong Watanabe–Yoshida conjecture holds for dimension $d=7$ and characteristic $p>2$.
\end{theorem}
\begin{proof}
    If the ring is a complete intersection, this is a consequence of \ref{maintheoremA} and \ref{maintheoremB}. If the ring is not a complete intersection, Aberbach and Cox-Steib provide a series of bounds in Section 4 of \cite{ac24} which are easily seen to be sharp whenever $p>2$ using the fact that $\eHK{R_{p,7}}$ is a decreasing function on $p>2$ and that $\eHK{R_{3,7}} \approx 1.056$.
\end{proof}

\begin{remark}
    Note that $\eHK{R_{2,7}} \approx 1.066$. All the bounds provided by Aberabach and Cox-Steib in dimension 7 are (positive) characteristic-free, and are enough to cover the characteristic 2 case when $\eHK{R}\geq 11$, but not when $6\leq \eHK{R}\leq 10$.

%As for the weaker inequality of the conjecture, the third part, would follow from proving that $\eHK{R_{p,d}}$ is a monotone function on $p$ since $\eHK{R_{p,d}}\rightarrow_{p\rightarrow \infty} 1+c_d$. That this sequence is monotone has been proven when the characteristic is sufficiently larger than the dimension, see \cite{tri}, so the missing piece is proving that this is true in small characteristic as well.
\end{remark}



