\section{Algebras in the Day convolution operad}\label{sec:main}

Throughout this section, fix a base operad $\cO^\otimes$ as well as $\cO$-monoidal categories $\cC$ and $\cD$.
Our goal is to prove the following strengthening of \cref{thm:day}.

\begin{theorem}\label{thm:day-improved}
    Let $\alpha \colon \cA^\otimes \to \cO^\otimes$ be an operad over $\cO^\otimes$.
    Then there exists a natural equivalence
    \[ \Alg_{\cA \times_\cO \cC/\cO}(\cD) \simeq \Alg_{\cA/\cO}(\Day_{\cC,\cD}). \]
\end{theorem}

Note that \cref{thm:day} follows from this by passing to groupoid cores.
The proof of this theorem is already implicit in \cite[Remark~5.2.5]{thenine-1}, but 
it will be convenient to formulate the argument in terms of some concepts introduced in
\cite{hhln:lax-adjunctions}.

\begin{defn}[{\cite[Observation~2.3.2]{hhln:lax-adjunctions}}]
 A functor $(p_1,p_2) \colon X \to Y \times Z$ is a \emph{curved orthofibration} if
 \begin{enumerate}
  \item $p_1 \colon X \to Y$ is a cartesian fibration;
  \item $p_2 \colon X \to Z$ is a cocartesian fibration;
  \item $p_1$-cartesian lifts of morphisms project to equivalences under $p_2$;
  \item $p_2$-cocartesian lifts of morphisms project to equivalences under $p_1$.
 \end{enumerate}
\end{defn}

Denote by $\Cocart^\lax(Y)$ the full subcategory of $\catinf_{/Y}$ spanned by the cocartesian fibrations, and by $\Cart^\oplax(Z)$ the full subcategory of $\catinf_{/Z}$ spanned by the cartesian fibrations.
In addition, $\CurvOrtho(Y,Z)$ denotes the subcategory of $\catinf_{/Y \times Z}$ whose objects are curved orthofibrations and whose morphisms are functors over $Y \times Z$ preserving both $p_1$-cartesian and $p_2$-cocartesian morphisms.
We will make use of the following description of $\CurvOrtho(Y,Z)$.

\begin{prop}[{\cite[Corollary~2.3.4]{hhln:lax-adjunctions}}]\label{prop:straighten-curved-ortho}
    Unstraightening over $Y$ and $Z$ induces equivalences
    \[ \Fun(Y^\op,\Cocart^\lax(Z))^\cart \simeq \CurvOrtho(Y,Z) \simeq \Fun(Z,\Cart^\oplax(Y))^\cocart \]
    which are natural in $Y$ and $Z$; the superscripts $\cocart$ and $\cart$ denote the wide subcategories on those natural transformations whose components all preserve (co)cartesian morphisms.
\end{prop}

We will also require the following statement about the interaction of cartesian and cocartesian morphisms in curved orthofibrations.

\begin{lem}\label{lem:preserve-lifts}
    Let $(p_1,p_2) \colon X \to Y \times Z$ be a curved orthofibration, and let $g \colon y \to y'$ and $h \colon z \to z'$ be morphisms in $Y$ and $Z$, respectively.
    Then the following are equivalent:
    \begin{enumerate}
        \item The cartesian transport $g^* \colon p_1^{-1}(a') \to p_1^{-1}(a)$ along $g$ preserves $p_2$-co\-car\-te\-sian lifts of $h$.
        \item The cocartesian transport $h_! \colon p_2^{-1}(b) \to p_2^{-1}(b')$ along $h$ preserves $p_1$-car\-te\-sian lifts of $g$.
    \end{enumerate}
\end{lem}
\begin{proof}
    This follows by inspection of the proof of \cite[Proposition~2.3.11]{hhln:lax-adjunctions}.
\end{proof}

Given \cref{lem:preserve-lifts}, we can make the following definition, see \cite[Definition~2.3.10]{hhln:lax-adjunctions}.

\begin{defn}
    A curved orthofibration 
    \[ p = (p_1,p_2) \colon X \to Y \times Z \]
    is an \emph{orthofibration} if it satisfies the following equivalent conditions:
    \begin{enumerate}
        \item the cartesian transport functor $g^* \colon p_1^{-1}(y') \to p_1^{-1}(y)$ preserves $p_2$-co\-car\-te\-sian morphisms for every morphism $g \colon y \to y'$ in $Y$;
        \item the cocartesian transport functor $h_! \colon p_2^{-1}(z) \to p_2^{-1}(x')$ preserves $p_1$-car\-te\-sian morphisms for every morphism $h \colon z \to z'$ in $Z$.
    \end{enumerate}
\end{defn}

By \cite[Corollary~2.5.6]{hhln:lax-adjunctions}, the equivalences of \cref{prop:straighten-curved-ortho} restrict to equivalences
\begin{equation}\label{eq:straighten-orthofibs}
    \Fun(Y^\op,\Cocart(Z)) \simeq \Ortho(Y,Z) \simeq \Fun(Z, \Cart(Y)),
\end{equation}
where $\Ortho(Y,Z) \subseteq \CurvOrtho(Y,Z)$ denotes the full subcategory of orthofibrations.
Consequently, every orthofibration straightens to a functor $Y^\op \times Z \to \catinf$, either by cocartesian straightening over $Z$ or by cartesian straightening over $Y$.
The resulting straightening functors $\Ortho(Y,Z) \to \Fun(Y^\op \times Z,\catinf)$ are equivalent, see \cite[Remark~2.5.7]{hhln:lax-adjunctions}.
% For the purposes of this note, we arbitrarily choose the straightening functor induced by cartesian straightening over $\cY$.

Since $(s,t) \colon \Ar^\oplax \to \catinf \times \catinf$ is an orthofibration by \cite[Proposition~7.9]{hhln:two-variable-fibrations},
combining \cite[Theorem~E]{hhln:lax-adjunctions} and \cite[Theorem~7.21]{hhln:two-variable-fibrations} shows that $(s,t)$ straightens to the functor
\[ \Fun \colon \catinf^\op \times \catinf \to \catinf. \]
In fact, we will reprove this statement without recourse to the 2-categorical machinery of \cite{hhln:two-variable-fibrations}.

\begin{theorem}\label{thm:main}
    The functor
    \[ (s_*,t_*) \colon \Alg_\cO(\Ar^\oplax) \to \Alg_\cO(\catinf) \times \Alg_\cO(\catinf) \]
    is an orthofibration which straightens to the obvious functor
    \[ (\cX,\cY) \mapsto \Alg_{\cX/\cO}(\cY). \]
\end{theorem}

\begin{rem}\label{rem:aropl-straightened}
    By specialising \cref{thm:main} to the case that $\cO^\otimes$ is the trivial operad, we recover the claim that the orthofibration $(s,t) \colon \Ar^\oplax \to \catinf \times \catinf$ straightens to the functor $\Fun \colon \catinf^\op \times \catinf \to \catinf$.
\end{rem}

Assuming this statement, we can prove \cref{thm:day-improved}.

\begin{proof}[Proof of \cref{thm:day-improved}]
    We will apply \cref{thm:main} to $\cA^\otimes$, which provides for every pair of $\cA$-monoidal categories $(\cX,\cY)$ an equivalence
    \[ \Alg_{/\cA}(\Day_{\cX,\cY}) \simeq \Alg_{\cX/\cA}(\cY). \]
    Therefore, we obtain equivalences
    \begin{align*}
        \Alg_{\cA/\cO}(\Day_{\cC,\cD})
        &\simeq \Alg_{/\cA}(\cA \times_\cO \Day_{\cC,\cD}) \\
        &\simeq \Alg_{/\cA}(\Day_{\cA \times_\cO \cC,\cA \times_\cO \cD}) \\
        &\simeq \Alg_{\cA \times_\cO \cC/\cA}(\cA \times_\cO \cD) \\
        &\simeq \Alg_{\cA \times_\cO \cC/\cO}(\cD).
    \end{align*}
    Specialising to the case $\cA^\otimes = \Day_{\cC,\cD}^\otimes$, this provides an evaluation map
    \[ \Day_{\cC,\cD}^\otimes \times_{\cO^\otimes} \cC^\otimes \to \cD^\otimes \]
    over $\cO^\otimes$ which induces the above equivalence, making it clear that this identification is natural.
\end{proof}

Before embarking on the proof of \cref{thm:main}, let us record another easy consequence.
We require some additional notation.

\begin{defn}\label{def:lax-slices}
    Define the operads $\lslice{\catinf}{\cC}{}^\otimes$ and $\lslice{\catinf}{}{\cD}^\otimes$ by the pullbacks
    \[\begin{tikzcd}
        \lslice{\catinf}{\cC}{}^\otimes\ar[r]\ar[d] & (\Ar^\oplax)^\times\ar[d, "{(s,t)}"] \\
        \cO^\otimes \times_{\Comm^\otimes} \catinf^\times\ar[r, "\cC \times \id"] & \catinf^\times \times_{\Comm^\otimes} \catinf^\times
    \end{tikzcd}\]
    and
    \[\begin{tikzcd}
        \lslice{\catinf}{}{\cD}^\otimes\ar[r]\ar[d] & (\Ar^\oplax)^\times\ar[d, "{(s,t)}"] \\
         \catinf^\times \times_{\Comm^\otimes} \cO^\otimes\ar[r, "\id \times \cD"] & \catinf^\times \times_{\Comm^\otimes} \catinf^\times
    \end{tikzcd}\]
\end{defn}


\begin{cor}
    Let $\alpha \colon \cA^\otimes \to \cO^\otimes$ be an operad over $\cO^\otimes$.
    \begin{enumerate}
        \item The functor
        \[ t_\cC \colon \Alg_{\cA/\cO}(\lslice{\catinf}{\cC}{}) \to \Alg_{\cA/\cO}( \cO \times \catinf) \simeq \Alg_\cA(\catinf) \]
        is a cocartesian fibration which straightens to the functor
        \[ \Alg_\cA(\catinf) \to \catinf,\quad \cY \mapsto \Alg_{\cA \times_\cO \cC/\cA}(\cY) \]
        whose functoriality is given by postcomposition with $\cA$-monoidal functors.
        \item The functor
        \[ s_\cD \colon \Alg_{\cA/\cO}(\lslice{\catinf}{}{\cD}) \to \Alg_{\cA/\cO}(\catinf \times \cO) \simeq \Alg_\cA(\catinf) \]
        is a cartesian fibration which straightens to the functor
        \[ \Alg_\cA(\catinf)^\op \to \catinf,\quad \cX \mapsto \Alg_{\cX/\cO}(\cD) \]
        whose functoriality is given by precomposition with $\cA$-monoidal functors.
    \end{enumerate}
\end{cor}
\begin{proof}
    This follows immediately from \cref{thm:main} applied to the base operad $\cA^\otimes$ together with the naturality of unstraightening. 
\end{proof}

The remainder of this section is concerned with the proof of \cref{thm:main}.
The key input for our argument is the existence of free cartesian fibrations.

\begin{const}\label{const:free}
 Let $I$ be a small category and let $f \colon X \to I$ be a functor.
 Define the \emph{free cartesian fibration} $\Fr(f)$ on $f$ as the pullback
 \[\begin{tikzcd}
  \Fr_\cart(f)\ar[r]\ar[d] & \Fun([1],I)\ar[d, "\ev_1"] \\
  X\ar[r, "f"] & I
 \end{tikzcd}\]
 together with the evaluation map
 \[ \Fr_\cart(f) \to \Fun([1],I) \xrightarrow{\ev_0} I. \]
\end{const}

\begin{prop}[{\cite[Theorem~4.5]{ghn:free-fibrations}}]\label{prop:free-cart}
    Let $I$ be a category.
    The functor $\Cart(I) \to \catinf_{/I}$ admits a left adjoint
    \[ \Fr_\cart \colon \catinf_{/I} \to \Cart(I) \]
    which sends $f \colon X \to I$ to $\Fr_\cart(f)$.
\end{prop}

\begin{rem}
 Dualising \cref{prop:free-cart} shows that the pullback
 \[\begin{tikzcd}
  \Fr_\cocart(f)\ar[r]\ar[d] & \Fun([1],I)\ar[d, "\ev_0"] \\
  X\ar[r, "f"] & I
 \end{tikzcd}\]
 together with the evaluation map
 \[ \Fr_\cocart(f) \to \Fun([1],I) \xrightarrow{\ev_1} I \]
 is the free cocartesian fibration on $f$.
\end{rem}


\begin{prop}\label{prop:aropl-orthofib}
    \ \begin{enumerate}
     \item\label{prop:aropl-orthofib-1} The functor
        \[ (s,t) \colon \Cart([1]) \to \catinf \times \catinf \]
        is an orthofibration.
        A morphism $f \colon p \to q$ in $\Cart([1])$ is $s$-cartesian if and only if $t(f)$ is an equivalence, and $f$ is $t$-cocartesian if and only if $s(f)$ is an equivalence.
     \item\label{prop:aropl-orthofib-2} The functor
        \[ (s,t) \colon \Ar^\oplax \to \catinf \times \catinf \]
        is an orthofibration.
        Moreover, the functor $\Cart([1]) \to \Ar^\oplax$ preserves both $s$-cartesian and $t$-cocartesian morphisms.
    \end{enumerate}
\end{prop}
\begin{proof}
    By unstraightening, $\Cart([1]) \simeq \Fun([1]^\op,\catinf)$, with $s$ and $t$ corresponding to evaluation at $1$ and $0$, respectively.
    By \cite[Corollary~2.4.7.11]{HTT}, the evaluation functor at $0$ is a cartesian fibration and the evaluation functor at $1$ is a cocartesian fibration, and the characterisation of $s$-cartesian and $t$-cocartesian morphisms follows from \cite[Lemma~2.4.7.5]{HTT}.
    The explicit description of $s$-cartesian and $t$-cocartesian morphisms also implies that $(s,t)$ is an orthofibration.

    For assertion~\eqref{prop:aropl-orthofib-2}, it suffices to show that $s$-cartesian morphisms in $\Cart([1])$ are also $s$-cartesian in $\Ar^\oplax$, and that the same holds true for $t$-cocartesian morphisms.

    So let $f \colon p \to q$ be an $s$-cartesian morphism in $\Cart([1])$, where $p \colon X \to [1]$ and $q \colon Y \to [1]$ are cartesian fibrations.
    For every cartesian fibration $r \colon Z \to [1]$, we have to show that the commutative square
    \[\begin{tikzcd}
	  \Hom_{\catinf_{/[1]}}(r,p)\ar[r, "f \circ -"]\ar[d] & \Hom_{\catinf_{/[1]}}(r,q)\ar[d] \\
	  \Hom_{\catinf}(s(r),s(p))\ar[r, "s(f) \circ -"] & \Hom_{\catinf}(s(r),s(q))
	\end{tikzcd}\]
	is a pullback.
	Observing that $s(\Fr_\cart(r)) \simeq [1]_{1/} \times s(r) \simeq s(r)$, this square is identified via \cref{prop:free-cart} with the commutative square
	\[\begin{tikzcd}
	  \Hom_{\Cart([1])}(\Fr_\cart(r),p)\ar[r]\ar[d] & \Hom_{\Cart([1])}(\Fr_\cart(r),q)\ar[d] \\
	  \Hom_{\catinf}(s(r),s(p))\ar[r, "s(f) \circ -"] & \Hom_{\catinf}(s(r),s(q))
	\end{tikzcd}\]
	which is a pullback by assumption.

	Let now $f \colon p \to q$ be a $t$-cocartesian morphism in $\Cart([1])$.
    %, which is equivalent to the assertion that $s(f)$ is an equivalence.
	Let $r \colon Z \to [1]$ be an arbitrary cartesian fibration.
	Note that $t(\Fr_\cart(p)) \simeq X$ and $t(\Fr_\cart(q)) \simeq Y$.
	Using \cref{prop:free-cart} once more, it suffices to show that the outer square in the commutative diagram
	\begin{equation}\label{eq:aropl-orthofib}
	\begin{tikzcd}[column sep=3em]
	  \Hom_{\Cart([1])}(\Fr_\cart(q),r)\ar[r, "- \circ \Fr(f)"]\ar[d, "t"'] & \Hom_{\Cart([1])}(\Fr_\cart(p),r)\ar[d, "t"] \\
	  \Hom_{\catinf}(Y,t(r))\ar[r, "- \circ f"]\ar[d] & \Hom_{\catinf}(X,t(r))\ar[d] \\
	  \Hom_{\catinf}(t(q),t(r))\ar[r, "- \circ t(f)"] & \Hom_{\catinf}(t(p),t(r))
	\end{tikzcd}
	\end{equation}
	is a pullback.
    Since $s(\Fr_\cart(f)) \simeq s(f)$ is an equivalence, the morphism $\Fr_\cart(f)$ is $t$-cocartesian, which means that the top square is a pullback.
	For the lower square, we use the explicit formula for cartesian unstraightening over $[1]^\op$ from \cite[Proposition~3.1]{ghn:free-fibrations}: since the left square and outer square in the commutative diagram
	\[\begin{tikzcd}
	  s(p)\ar[r, "\St(p)"]\ar[d, "1 \times \id"'] & t(p)\ar[r, "t(f)"]\ar[d] & t(q)\ar[d] \\
	  {[1]}^\op \times s(p)\ar[r] & X\ar[r, "f"] & Y
	\end{tikzcd}\]
	are pushouts, so is the right square.
	This implies that the bottom square in \eqref{eq:aropl-orthofib} is a pullback.
	Consequently, the outer square in \eqref{eq:aropl-orthofib} is a pullback as required.
\end{proof}

Since we are considering the cartesian symmetric monoidal structures on $\Ar^\oplax$ and $\catinf$, we can bootstrap the analogous statements for categories of $\cO$-algebras from this.

\begin{lem}\label{lem:orthofib-fun}
    Let $p = (p_1,p_2) \colon X \to Y \times Z$ be a curved orthofibration/an orthofibration and let $I$ be a small category.
    Then
    \[ p_* = ((p_1)_*,(p_2)_*) \colon \Fun(I,X) \to \Fun(I,Y) \times \Fun(I,Z) \]
    is also a curved orthofibration/an orthofibration.
    The relevant cartesian and cocartesian morphisms are given by those natural transformations whose components are all cartesian or cocartesian, respectively.
\end{lem}
\begin{proof}
    This is immediate from \cite[Corollary~3.2.2.12]{HTT}.
\end{proof}

\begin{lem}\label{lem:monoid-orthofib}
 Let $X$, $Y$ and $Z$ be categories with finite products.
 Suppose that $p = (p_1,p_2) \colon X \to Y \times Z$ is a functor such that
 \begin{enumerate}
  \item\label{lem:monoid-orthofib-1} $p$ is a curved orthofibration;
  \item\label{lem:monoid-orthofib-2} $p$ preserves finite products;
  \item\label{lem:monoid-orthofib-3} finite products of $p_1$-cartesian morphisms are $p_1$-cartesian;
  \item\label{lem:monoid-orthofib-4} finite products of $p_2$-cocartesian morphisms are $p_2$-cocartesian.
 \end{enumerate}
 Then the induced functor $p_* \colon \Mon_\cO(X) \to \Mon_\cO(Y) \times \Mon_\cO(Z)$ is a curved orthofibration.
 A morphism in $\Mon_\cO(X)$ is $(p_1)_*$-cartesian or $(p_2)_*$-cocartesian if and only if it is $(p_1)_*$-cartesian or $(p_2)_*$-cocartesian in $\Fun(\cO^\otimes,X)$.
\end{lem}
\begin{proof}
  By \cref{lem:orthofib-fun}, the induced functor
  \[ p_* = ((p_1)_*,(p_2)_*) \colon \Fun(\cO^\otimes,X) \to \Fun(\cO^\otimes,Y) \times \Fun(\cO^\otimes,Z) \]
  also satisfies properties~\eqref{lem:monoid-orthofib-1} -- \eqref{lem:monoid-orthofib-4}.

  Let $g \colon N \to N'$ be a morphism in $\Mon_\cO(Y)$ and let $M'$ be an $\cO$-monoid in $X$ lifting $N'$.
  Considering $g$ as a morphism in $\Fun(\cO^\otimes,Y)$, there exists a cartesian lift $f \colon M \to M'$ in $\Fun(\cO^\otimes,X)$.
  We claim that $M$ is also an $\cO$-monoid in $X$.
  For $x = x_1 \boxtimes \ldots \boxtimes x_n$ in $\cO^\otimes_{\langle n \rangle}$, the Segal maps of $M$ and $M'$ fit into a commutative square
  \[\begin{tikzcd}
   M(x)\ar[r]\ar[d] & \prod_{i=1}^n M(x_i)\ar[d] \\
   M'(x)\ar[r, "\simeq"] & \prod_{i=1}^n M'(x_i)
  \end{tikzcd}\]
  Since products of cartesian morphisms in $X$ are cartesian, both vertical arrows are cartesian morphisms.
  By \cite[Lemma~2.4.2.7]{HTT}, it follows that the top horizontal morphism is also cartesian.
  Since $N$ is an $\cO$-monoid, this morphism is a cartesian lift of an equivalence, and therefore itself an equivalence.
  It follows that $(p_1)_* \colon \Mon_\cO(X) \to \Mon_\cO(Y)$ is a cartesian fibration.

  Since $(p_1)_*$-cartesian lifts in $\Fun(\cO^\otimes,X)$ are characterised by being pointwise $p_1$-cartesian, it also follows that $(p_1)_*$-cartesian morphisms project to equivalences under $(p_2)_*$.

  The argument for $(p_2)_*$ is completely analogous.
\end{proof}

In particular, we obtain the following.

\begin{prop}\label{prop:alg-s-t-orthofibration}
    The functor
    \[ (s_*,t_*) \colon \Alg_\cO(\Ar^\oplax) \to \Alg_\cO(\catinf) \times \Alg_\cO(\catinf) \]
    is an orthofibration.
    Both $s_*$-cartesian and $t_*$-cocartesian morphisms are detected by the functor
    \[ \Alg_\cO(\Ar^\oplax) \xrightarrow{\sim} \Mon_\cO(\Ar^\oplax) \to \Fun(\cO^\otimes,\Ar^\oplax). \]
\end{prop}
\begin{proof}
    Due to \cref{prop:aropl-orthofib}, the functor $(s,t) \colon \Ar^\oplax \to \catinf \times \catinf$ is an orthofibration satisfying the assumptions of \cref{lem:monoid-orthofib}.
    The proposition follows.
\end{proof}

To determine the straightening of $(s_*,t_*)$, we require some additional preparation.
First, we observe that the existence of free (co)cartesian fibrations implies the existence of free orthofibrations.

\begin{cor}\label{prop:free-orthofib}
    The inclusion functor $\Ortho(Y,Z) \to \catinf_{/Y \times Z}$ admits a left adjoint
    \[ \Fr \colon \catinf_{/Y \times Z} \to \Ortho(Y,Z). \]
\end{cor}
\begin{proof}
    We write $p_Z \colon Y \times Z \to Z$ for the projection functor.
    Since $p_Z$ is a cartesian fibration, the equivalence $\catinf_{/Y \times Z} \simeq (\catinf_{/Y})/p_Z$ and \cref{prop:free-cart} induce an adjunction
    \[ \catinf_{/Y \times Z} \rightleftarrows \Cart(Y)/p_Z. \]
    After identifying
    \[ \Cart(Y)/p_Z \simeq \Fun(Y^\op,\catinf)_{/\con_Z} \simeq \Fun(Y^\op,\cat_{/Z}), \]
    the existence of free cocartesian fibrations induces an adjunction
    \[ \Cart(Y)/p_Z \rightleftarrows \Fun(Y^\op,\Cocart(Z)) \simeq \Ortho(Y,Z).\qedhere \]
\end{proof}

\begin{rem}
    Unwinding the proof of \cref{prop:free-orthofib}, one finds that the free orthofibration on a functor $f \colon X \to Y \times Z$ is given by the pullback
    \[\begin{tikzcd}
        \Fr(f)\ar[r]\ar[d] & \Fun([1],Y) \times \Fun([1],Z)\ar[d, "\ev_1 \times \ev_0"] \\
        X\ar[r, "f"] & Y \times Z
    \end{tikzcd}\]
    together with the evaluation map
    \[ \Fr(f) \to \Fun([1],Y) \times \Fun([1],Z) \xrightarrow{\ev_0 \times \ev_1} Y \times Z. \]
    One can adapt the proof of \cite[Theorem~4.5]{ghn:free-fibrations} to show directly that this yields a left adjoint to the functor $\Ortho(Y,Z) \to \catinf_{/Y \times Z}$.
\end{rem}

We can apply this statement to identify the straightenings of cotensors of orthofibrations.

\begin{lem}\label{lem:orthofib-cotensor}
    Let $p \colon X \to Y \times Z$ be an orthofibration.
    Consider the pullback
    \[\begin{tikzcd}
        X^I\ar[r]\ar[d, "p^I"'] & \Fun(I,X)\ar[d, "p_*"] \\
        Y \times Z\ar[r, "\con"] & \Fun(I,Y \times Z)
    \end{tikzcd}\]
    Then $p^I = (p^I_1,p^I_2)$ is an orthofibration such that both $p^I_1$-cartesian and $p^I_2$-cocartesian morphisms are detected componentwise in $\Fun(I,X)$.
    Moreover, $p^I$ straightens to the functor
    \[ \Fun(I,\St(p)) \colon Y^\op \times Z \to \catinf. \]
\end{lem}
\begin{proof}
    The first part of the lemma is precisely \cref{lem:orthofib-fun}, so we only have to prove the assertion about the straightening of $p^I$.
    For every functor $f \colon T \to Y \times Z$, there exist by \cref{prop:free-orthofib} natural equivalences
    \begin{align*}
        \Hom_{Y \times Z}(T,X^I)
        &\simeq \Hom_{Y \times Z}(T \times I,X) \\
        &\simeq \Hom_{\Ortho(Y,Z)}(\Fr(T \times I \to Y \times Z),X) \\
        &\simeq \Hom_{\Ortho(Y,Z)}(\Fr(f) \times I,X) \\
        &\simeq \Nat(\St(\Fr(f)) \times I,\St(p)) \\
        &\simeq \Nat(\St(\Fr(f)), \Fun(I,\St(p))) \\
        &\simeq \Hom_{\Ortho(Y,Z)}(\Fr(f),\Un(\Fun(I,\St(p)))) \\
        &\simeq \Hom_{Y \times Z}(T,\Un(\Fun(I,\St(p)))),
    \end{align*}
    which implies the lemma.
\end{proof}

Recall the following definition from \cite[Proposition~2.3.13]{hhln:lax-adjunctions}.

\begin{defn}
    A functor $p = (p_1,p_2) \colon X \to Y \times Z$ is a \emph{bifibration} if the following conditions are satisfied:
    \begin{enumerate}
        \item $p_1$ is a cartesian fibration such that a morphism in $X$ is $p_1$-cartesian if and only if it projects to an equivalence under $p_2$;
        \item $p_2$ is a cocartesian fibration such that a morphism in $X$ is $p_2$-cocartesian if and only if it projects to an equivalence under $p_1$.
    \end{enumerate}
\end{defn}

By \cite[Corollary~2.3.15]{hhln:lax-adjunctions}, the equivalences from~\eqref{eq:straighten-orthofibs} restrict to equivalences
\[ \Fun(Y^\op, \LFib(Z)) \simeq \Bifib(Y,Z) \simeq \Fun(Z,\RFib(Y)), \]
where $\Bifib(Y,Z) \subseteq \Ortho(Y,Z)$ denotes the full subcategory of bifibrations, and $\LFib(Z)$ and $\RFib(Y)$ denote the categories of left fibrations over $Z$ and right fibrations over $Y$, respectively.

\begin{ex}\label{ex:arrow-cat}
    The functor $(\ev_1,\ev_0) \colon \Fun([1]^\op,X) \to X$ is a bifibration for every category $X$---the special case $X=\catinf$ was covered in \cref{prop:aropl-orthofib}.
    Moreover, this functor straightens to the functor
    \[ \Hom_X \colon X^\op \times X \to \Spc. \]
    This follows for example from \cite[Corollary~A.2.5]{hms:shifted} because the cartesian unstraightening of $\Hom_X$ is the twisted arrow category.
\end{ex}

\begin{defn}
    Let $p = (p_1,p_2) \colon X \to Y \times Z$ be an orthofibration.
    Define $X_\bicart$ as the wide subcategory of $X$ generated by the collections of $p_1$-cartesian and $p_2$-cocartesian morphisms.
\end{defn}

\begin{lem}\label{lem:underlying-bifib}
    Let $p = (p_1,p_2) \colon X \to Y \times Z$ be an orthofibration.
    \begin{enumerate}
        \item\label{lem:underlying-bifib-1} The following are equivalent for a morphism $f$ in $X$:
         \begin{enumerate}
             \item $f$ lies in $X_\bicart$;
             \item $f$ is the composition of a $p_1$-cartesian morphism followed by a $p_2$-cocartesian morphism;
             \item $f$ is the composition of a $p_2$-cocartesian morphism followed by a $p_1$-cartesian morphism.
         \end{enumerate}
        \item\label{lem:underlying-bifib-2} The restriction $p_\bicart \colon X_\bicart \to Y \times Z$ of $p$ is a bifibration. The inclusion functors $X_\bicart \to X$ assemble to the counit transformation of an adjunction
        \[ \inc \colon \Bifib(Y,Z) \rightleftarrows \Ortho(Y,Z) \cocolon (-)_\bicart. \]
        \item\label{lem:underlying-bifib-3} The bifibration $p_\bicart$ straightens to the functor
        \[ Y^\op \times Z \xrightarrow{\St(p)} \catinf \xrightarrow{\iota} \Spc. \]
    \end{enumerate}
\end{lem}
\begin{proof}
    By \cite[Definition~2.3.10]{hhln:lax-adjunctions}, $p_1$-cartesian morphisms canonically commute with $p_2$-cocartesian morphisms, which shows assertion~\eqref{lem:underlying-bifib-1}.

    For assertion~\eqref{lem:underlying-bifib-2}, let us first check that $(p_\bicart)_1 \colon X_\bicart \to Y$ is a cartesian fibration.
    Every morphism in $Y$ admits a $p_1$-cartesian lift, so this reduces to checking that for a $p_1$-cartesian morphism $\xi \colon x \to x'$ in $X$, an arbitrary morphism $\alpha \colon a \to x$ lies in $X_\bicart$ if and only if $\xi \circ \alpha$ lies in $X_\bicart$.
    Writing $\alpha$ as the composite of a $p_2$-cocartesian morphism followed by a $p_1$-cartesian morphism, this is immediate from \cite[Lemma~2.4.2.7]{HTT}.
    In particular, every $(p_\bicart)_1$-cartesian morphism projects to an equivalence under $(p_\bicart)_2$.

    Suppose now that $\xi \colon x \to x'$ is a morphism in $X_\bicart$ such that $p_2(\xi)$ is an equivalence.
    Writing $\xi = \xi_\cocart \circ \xi_\cart$ as a composition of a $p_1$-cartesian morphism followed by a $p_2$-cocartesian morphism, it follows that $p_2(\xi_\cocart)$ is an equivalence.
    Hence $\xi_\cocart$ is a $p_2$-cocartesian lift of an equivalence, and thus an equivalence.
    It follows that $\xi$ is $p_1$-cartesian, and therefore also $(p_\bicart)_1$-cartesian.

    By dualising, we see that $(p_\bicart)_2 \colon X \to Z$ is a cocartesian fibration such that a morphism is $(p_\bicart)_2$-cocartesian if and only if it projects to an equivalence under $(p_\bicart)_1$.
    Hence $p_\bicart$ is a bifibration.

    Since morphisms in $\Ortho(Y,Z)$ preserve all relevant cartesian and cocartesian morphisms, it is immediate that the inclusion $X_\bicart \to X$ induces an equivalence
    \[ \Hom_{\Bifib(Y,Z)}(T,X_\bicart) \xrightarrow{\sim} \Hom_{\Ortho(Y,Z)}(T,X) \]
    for every bifibration $T \to Y \times Z$.

    Assertion~\eqref{lem:underlying-bifib-3} follows from the commutative diagram
    \[\begin{tikzcd}
        \Bifib(Y,Z)\ar[r, "\sim"]\ar[d, "\inc"] & \Fun(Z, \RFib(Y))\ar[r, "\sim"]\ar[d, "\inc"] & \Fun(Z, \Fun(Y^\op,\Spc))\ar[d, "\inc"] \\
        \Ortho(Y,Z)\ar[r, "\sim"] & \Fun(Z, \Cart(Y))\ar[r, "\sim"] & \Fun(Z,\Fun(Y^\op,\catinf))
    \end{tikzcd}\]
    by passing to right adjoints.
\end{proof}

Finally, recall that slice categories of $\Op$ are cotensored over $\catinf$ as follows.
For $I$ a small category and $\phi \colon \cX^\otimes \to \cB^\otimes$ an operad map, define $\Fun(I,\cX)^\otimes$ as the pullback
\[\begin{tikzcd}
    \Fun(I,\cX)^\otimes\ar[r]\ar[d] & \Fun(I,\cX^\otimes)\ar[d, "\phi_*"] \\
    \cB^\otimes\ar[r, "\con"] & \Fun(I,\cB^\otimes)
\end{tikzcd}\]
This operad has the universal property that
\[ \Alg_{\cA/\cB}(\Fun(I,\cX)) \simeq \Fun(I, \Alg_{\cA/\cB}(\cX)) \]
for every operad $\cA^\otimes \to \cB^\otimes$ over $\cB^\otimes$ \cite[Remark~2.1.3.4]{HA}.

If $\pi \colon \cX^\otimes \to \cX$ is a cartesian structure, one checks directly that
\[ \Fun(I,\cX)^\otimes \to \Fun(I,\cX^\otimes) \xrightarrow{\pi \circ - } \Fun(I,\cX) \]
exhibits $\Fun(I,\cX)^\otimes$ as a cartesian structure on $\Fun(I,\cX)$.
In particular, one obtains the cartesian symmetric monoidal structure
\[ \Fun(I,\Ar^\oplax)^\times \to \Comm^\otimes \]
by applying this construction to the operad $(\Ar^\oplax)^\times \to \Comm^\otimes$.

\subsection*{Proof of \texorpdfstring{\cref{thm:main}}{the main theorem}}
We can now finish the proof of our main result.
By \cref{prop:alg-s-t-orthofibration}, the functor
\[ (s_*,t_*) \colon \Alg_\cO(\Ar^\oplax) \to \Alg_\cO(\catinf) \times \Alg_\cO(\catinf) \]
is an orthofibration.
In combination with \cref{prop:aropl-orthofib}, we obtain a characterisation of the $s_*$-cartesian morphisms as those morphisms which map under
\[ \Alg_\cO(\Ar^\oplax) \to \Fun(\cO^\otimes,\Ar^\oplax) \]
to a natural transformation whose components all preserve cartesian morphisms and project to an equivalence under $t \colon \Ar^\oplax \to \catinf$.
Analogously for $t_*$-cocartesian morphisms.

We will identify the composite of the straightening of $(s_*,t_*)$ with the Yoneda embedding $\yo \colon \catinf \to \cP(\catinf)$.
By \cref{lem:orthofib-cotensor}, the composite
\begin{align*}
    \catinf^\op
    &\xrightarrow{(s_*,t_*)^{(-)}} \Ortho(\Alg_\cO(\catinf),\Alg_\cO(\catinf)) \\
    &\xrightarrow{\St} \Fun(\Alg_\cO(\catinf)^\op \times \Alg_\cO(\catinf),\catinf) \\
    &\xrightarrow{\iota \circ -} \Fun(\Alg_\cO(\catinf)^\op,\Spc)
\end{align*}
corresponds to $\yo \circ \St(s_*,t_*)$ after currying.
By virtue of \cref{lem:underlying-bifib}, the composite $(\iota \circ -) \circ \St$ is equivalent to the functor that first applies $(-)_\bicart$ and then straightens the resulting bifibration.
This leaves us with identifying the bifibrations $(s_*,t_*)^I_\bicart$.

Consider the natural fully faithful functor
\begin{align*}
    \Psi' \colon \Fun(I,\Alg_\cO(\Ar^\oplax))
    &\simeq \Alg_\cO(\Fun(I,\Ar^\oplax)) \\
    &\xrightarrow{\sim} \Mon_\cO(\Fun(I,\Ar^\oplax)) \\
    &\subseteq \Fun(\cO^\otimes, \Fun(I,\Ar^\oplax)) \simeq \Fun(\cO^\otimes \times I, \Ar^\oplax).
\end{align*}
Then $\Fun(I,s_*)$-cartesian morphisms in the domain correspond precisely to those natural transformations $\tau$ in the target with the property that for all $x \in \cO^\otimes$ and $i \in I$, the functor $\tau(x,i)$ preserves cartesian morphisms over $[1]$ and $t(\tau(x,i))$ is an equivalence.
From the analogous assertion for $\Fun(I,t_*)$-cocartesian morphisms, it follows that $\Psi'$ restricts to a fully faithful functor
\[ \Fun(I,\Alg_\cO(\Ar^\oplax))_\bicart \to \Fun(\cO^\otimes \times I, \Ar^\oplax)^\cart. \]
Composing with the natural equivalence of \cref{prop:straighten-curved-ortho}, we obtain a fully faithful functor
\[ \Psi \colon \Fun(I,\Alg_\cO(\Ar^\oplax))_\bicart \to \Fun([1]^\op, \Cocart^\lax(\cO^\otimes \times I))^\cocart. \]

\begin{lem}\label{lem:identify-monoids}
    The essential image of $\Psi$ comprises of those functors
    \[ E \colon [1]^\op \to \Cocart^\lax(\cO^\otimes \times I) \]
    satisfying the following conditions:
    \begin{enumerate}
        \item for $k=0,1$ and $i \in I$, the functor $E(k)_i \to \cO^\otimes \times \{i\}$ is a cocartesian fibration of operads;
        \item the functor $E(1)_i \to E(0)_i$ preserves inert morphisms for every $i \in I$.
    \end{enumerate}
\end{lem}
\begin{proof}
    A functor $M \colon \cO^\otimes \to \Fun(I,\Ar^\oplax)$ is an $\cO$-monoid if and only if the evaluation $M_i \colon \cO^\otimes \to \Ar^\oplax$ is an $\cO$-monoid for all $i \in I$.
    Recall that $M_i$ being an $\cO$-monoid means that for every $x = x_1 \boxtimes \ldots \boxtimes x_n \in \cO^\otimes_{\langle n \rangle}$, the appropriate inert morphisms induce equivalences
    \[\rho \colon  M_i(x) \xrightarrow{\sim} M_i(x_1) \mathop{\times}\limits_{[1]} \ldots \mathop{\times}\limits_{[1]} M_i(x_n) \]
    of cartesian fibrations over $[1]$.
    This is the case if and only if each $\rho$ preserves cartesian morphisms and induces fibrewise equivalences.

    Denote by $E \colon [1]^\op \to \Cocart(\cO^\otimes \times I)$ the image of $M$ under $\Psi$, and let $E(k)_i$ be the restriction of $E(k)$ to $\cO^\otimes \times \{i\}$.
    The cocartesian fibration $E(k)_i \to \cO^\otimes$ is given by the unstraightening of the composite $\cO^\otimes \to \Fun(I,\Ar^\oplax) \xrightarrow{ev_i} \Ar^\oplax \xrightarrow{(-)|_{\{k\}}} \catinf$, which is an $\cO$-monoid because $\ev_i$ preserves products.
    Consequently, each map $\rho$ is a fibrewise equivalence if and only if both $E(0)_i$ and $E(1)_i$ are cocartesian fibrations of operads \cite[Example~2.4.2.4]{HA}.
    Since inert morphisms in $E(k)_i$ are precisely the cocartesian lifts of inert morphisms in $\cO^\otimes \times \{i\}$, \cref{lem:preserve-lifts} shows that $\rho$ preserves all cartesian morphisms if and only if $E(1)_i \to E(0)_i$ preserves all inert morphisms.
\end{proof}

Note that $\Psi$ fits into a natural commutative diagram
\[\begin{tikzcd}
    \Fun(I,\Alg_\cO(\Ar^\oplax))_\cart\ar[r, "\Psi"]\ar[d, "{(s,t)}"'] & \Fun([1]^\op, \Cocart^\lax(\cO^\otimes \times I))^\cocart\ar[d, "{(\ev_1,\ev_0)}"] \\
    \Fun(I,\Alg_\cO(\catinf)) \times \Fun(I,\Alg_\cO(\catinf))\ar[r, "\Phi"] & \Cocart(\cO^\otimes \times I) \times \Cocart(\cO^\otimes \times I)
\end{tikzcd}\]
with both $\Phi$ and $\Psi$ fully faithful.
The essential image of $\Phi$ comprises precisely of those pairs of functors whose restriction to $\cO^\otimes \times \{i\}$ is a cocartesian fibration of operads for every $i \in I$.
In particular, this induces a natural fully faithful functor $\Psi_I$ from $\Alg_\cO(\Ar^\oplax)^I_\bicart$ to the pullback of
\[\begin{tikzcd}[column sep=5em]
    & \Fun([1]^\op, \Cocart^\lax(\cO^\otimes \times I))^\cocart\ar[d, "{(\ev_1,\ev_0) =: \epsilon}"] \\
    \Cocart(\cO^\otimes) \times \Cocart(\cO^\otimes)\ar[r, "(- \times I) \times (- \times I)"] & \Cocart(\cO^\otimes \times I) \times \Cocart(\cO^\otimes \times I)
\end{tikzcd}\]
The right vertical evaluation functor is the pullback of
\[ (\ev_1,\ev_0) \colon \Fun([1]^\op, \Cocart^\lax(\cO^\otimes \times I)) \to \Cocart^\lax(\cO^\otimes \times I) \times \Cocart^\lax(\cO^\otimes \times I), \]
along the inclusion functor
\[ \Cocart(\cO^\otimes \times I) \times \Cocart(\cO^\otimes \times I) \to \Cocart^\lax(\cO^\otimes \times I) \times \Cocart^\lax(\cO^\otimes \times I). \]
Consequently, the naturality of unstraightening together with \cref{ex:arrow-cat} implies that this pullback of $\epsilon$ straightens to the functor
\[ \Hom_{\Cocart^\lax(\cO^\otimes \times I)}(- \times I, - \times I) \colon \Cocart(\cO^\otimes) \times \Cocart(\cO^\otimes) \to \Spc. \]
Observe in addition that
\[ \Hom_{\Cocart^\lax(\cO^\otimes \times I)}(- \times I, - \times I) \simeq \Hom_{\Cocart^\lax(\cO^\otimes)}(- \times I,-). \]
It follows from \cref{lem:identify-monoids} that $\Psi_I$ identifies the straightening of $\Alg_\cO(\Ar^\oplax)^I_\bicart$ with the full subfunctor of $\Hom_{\Cocart^\lax(\cO^\otimes)}(- \times I,-)$ given by those functors $\cX^\otimes \times I \to \cY^\otimes$ such that $\cX^\otimes \times \{i\} \to \cY^\otimes$ is an operad map for all $i \in I$.
After currying, we obtain a natural equivalence
\[ \St((s_*,t_*)^I_\bicart) \simeq \Hom_\catinf(I, \Alg_{\cX/\cO}(\cY)), \]
which is precisely what we needed to show.
\cref{thm:main} is now proved.



