\section{Variation: Day convolution in suboperads of \texorpdfstring{$\catinf^\times$}{the cartesian symmetric monoidal structure on Cat}}\label{sec:variations}
From the preceding results, one can deduce analogous assertions for certain symmetric monoidal categories which arise as suboperads of $\catinf^\times$.
Consider a subcategory $\cU$ of $\catinf$ which is closed under finite products.
If $U_1$, $U_2$ and $T$ are objects in $\cU$, call a functor $F \colon U_1 \times U_2 \to T$ \emph{$\cU$-biexact} if both $F(u_1,-) \colon U_2 \to T$ and $F(-,u_2) \colon U_1 \to T$ are morphisms in $\cU$ for all $u_1 \in U_1$ and $u_2 \in U_2$.
There is an evident notion of a \emph{$\cU$-multiexact} functor for functors in more than two variables.

Assume that
\begin{enumerate}
    \item for each pair $U_1$ and $U_2$ of objects in $\cU$, there exists an initial $\cU$-biexact functor $U_1 \times U_2 \to U_1 \otimes U_2$;
    \item there exists a category $U \in \cU$ and an object $u \in U$ such that evaluation at $u$ induces an equivalence $\Hom_\cU(U,T) \xrightarrow{\sim} \iota T$.
\end{enumerate}
One example of a subcategory satisfying these conditions is the category $\catst$ of stable categories and exact functors.

Under these assumptions, $\cU$ refines to a symmetric monoidal category by considering the suboperad $\cU^\otimes$ of $\catinf^\times$ determined by the following conditions:
\begin{enumerate}
    \item the underlying category of $\cU^\otimes$ is $\cU$;
    \item morphisms $U_1 \boxtimes \ldots \boxtimes U_n \to T$ over the active map $\langle n \rangle \to \langle 1 \rangle$ correspond to $\cU$-multiexact functors $U_1 \times \ldots \times U_n \to T$.
\end{enumerate}
Observe that $\cO$-algebras in $\cU^\otimes$ correspond under unstraightening to cocartesian fibrations of operads over $\cO^\otimes$ whose fibres lie in $\cU$ and whose cocartesian transport functors are $\cU$-multiexact.

Consider now the suboperad $(\Ar^\oplax_\cU)^\otimes$ of $(\Ar^\oplax)^\times$ determined by the following properties:
\begin{enumerate}
    \item objects in the underlying category $\Ar^\oplax_\cU$ are given by cartesian fibrations $X \to [1]$ which straighten to functors $[1]^\op \to \cU$;
    \item morphisms are precisely those morphisms in $(\Ar^\oplax)^\times$ which map to the suboperad $\cU^\otimes \times_{\Comm^\otimes} \cU^\otimes$ under $(s,t)$.
\end{enumerate}
As before, given $\cO$-algebras $\cC$ and $\cD$ in $\cU$, we let $\lslice{\cU}{\cC}{}^\otimes$ and $\lslice{\cU}{}{\cD}^\otimes$ be given by the following pullbacks:
\[\begin{tikzcd}
    \lslice{\cU}{\cC}{}^\otimes\ar[r]\ar[d] & (\Ar^\oplax_\cU)^\otimes\ar[d, "{(s,t)}"] \\
    \cO^\otimes \times_{\Comm^\otimes} \cU^\otimes\ar[r, "\cC \times \id"] & \cU^\otimes \times_{\Comm^\otimes} \cU^\otimes
\end{tikzcd}
\quad
\begin{tikzcd}
    \lslice{\cU}{}{\cD}^\otimes\ar[r]\ar[d] & (\Ar^\oplax_\cU)^\otimes\ar[d, "{(s,t)}"] \\
    \cU^\otimes \times_{\Comm^\otimes} \cO^\otimes\ar[r, "\id \times \cD"] & \cU^\otimes \times_{\Comm^\otimes} \cU^\otimes
\end{tikzcd}\]
As a final piece of notation, denote by $\Alg_{\cC/\cO}^\cU(\cD)$ the full subcategory of $\Alg_{\cC/\cO}(\cD)$ spanned by those operad maps $\cC^\otimes \to \cD^\otimes$ over $\cO^\otimes$ such that $\cC^\otimes_x \to \cD^\otimes_x$ is a morphism in $\cU$ for every $x \in \cO^\otimes$.

\begin{prop}\label{prop:alg-aropl-s-straighten}
    Let $p \colon \cC^\otimes \to \cO^\otimes$ and $q \colon \cD^\otimes \to \cO^\otimes$ be cocartesian fibrations of operads corresponding to $\cO$-algebras in $\cU$. 
    \begin{enumerate}
        \item\label{prop:alg-aropl-s-straighten-1} The functor
        \[ (s_*,t_*) \colon \Alg_{\cO}(\Ar^\oplax_\cU) \to \Alg_\cO(\cU) \times \Alg_\cO(\cU) \]
        is an orthofibration which straightens to the functor
        \[ (\cX,\cY) \mapsto \Alg_{\cX/\cO}^\cU(\cY).\]
        \item\label{prop:alg-aropl-s-straighten-2} For every operad $\cA^\otimes \to \cO^\otimes$ over $\cO^\otimes$, the functor
        \[ t_\cC \colon \Alg_{\cA/\cO}(\lslice{\cU}{\cC}{}) \to \Alg_\cA(\cU) \]
        is a cocartesian fibration which straightens to the functor
        \[ \cY \mapsto \Alg_{\cA \times_\cO \cC/\cA}^\cU(\cY). \]
        \item\label{prop:alg-aropl-s-straighten-3} For every operad $\cA^\otimes \to \cO^\otimes$ over $\cO^\otimes$, the functor
        \[ s_\cD \colon \Alg_{\cA/\cO}(\lslice{\cU}{}{\cD}) \to \Alg_\cA(\cU) \]
        is a cartesian fibration which straightens to the functor
        \[ \cX \mapsto \Alg_{\cX/\cO}^\cU(\cD). \]
    \end{enumerate}
\end{prop}
\begin{proof}
    The operad $(\Ar^\oplax_\cU)^\otimes$ can be constructed in two steps.
    Consider first the pullback
    \[\begin{tikzcd}
        (\widetilde{\Ar^\oplax_\cU})^\otimes\ar[r]\ar[d] & (\Ar^\oplax)^\times\ar[d, "{(s,t)}"] \\
        \cU^\otimes \times_{\Comm^\otimes} \cU^\otimes\ar[r] & \catinf^\times \times_{\Comm^\otimes} \catinf^\times
    \end{tikzcd}\]
    Then $(\Ar^\oplax_\cU)^\otimes$ is the full subcategory of $(\widetilde{\Ar^\oplax_\cU})^\otimes$ spanned by objects corresponding to tuples of cartesian fibrations over $[1]$, each of which straightens to a functor $[1]^\op \to \cU$.
    Consequently, \cref{thm:main} implies that
    \[ (\tilde{s}_*,\tilde{t}_*) \colon \Alg_{\cO}\Big(\widetilde{\Ar^\oplax_\cU}\Big) \to \Alg_\cO(\cU) \times \Alg_\cO(\cU) \]
    is an orthofibration which straightens to the functor
    \[ (\cX,\cY) \mapsto \Alg_{\cX/\cO}(\cD). \]
    By construction, the fibre of $(\Ar^\oplax_\cU)^\otimes$ over $(\cX,\cY)$ is precisely the full subcategory $\Alg_{\cX/\cA}^\cU(\cY)$, and both the $\tilde{s}_*$-cartesian and $\tilde{t}_*$-cocartesian transport functors along morphisms in $\Alg_\cO(\cU)$ preserve these full subcategories.
    This identifies $\St(s_*,t_*)$ as the correct subfunctor.

    Assertions~\eqref{prop:alg-aropl-s-straighten-2} and \eqref{prop:alg-aropl-s-straighten-3} follow as before from \eqref{prop:alg-aropl-s-straighten-1}.
\end{proof}





