\section{\texorpdfstring{Day convolution as an $\cO$-monoidal category}{Day convolution as an O-monoidal category}}\label{sec:day-o-monoidal}

Fix a base operad $\cO^\otimes$ as well as $\cO$-monoidal categories $\cC$ and $\cD$.
In this section, we reprove a well-known statement, see \cite[Proposition~2.2.6.16]{HA}, which is key for working with the Day convolution operad.
We include a proof to demonstrate that $\Day_{\cC,\cD}^\otimes$ is a feasible description of Day convolution.

For every operation $\phi \in \mathrm{Mul}_\cO(\{x_i\}_i,y)$, denote the associated tensor functors by $\otimes^\cC_\phi \colon \prod_i \cC(x_i) \to \cC(y)$ and $\otimes^\cD_\phi \colon \prod_i \cD(x_i) \to \cD(y)$.

\begin{prop}\label{prop:day-o-monoidal}
    For each $y \in \cO$, consider the following collection of slice categories:
    \[ \cK(y) := \left\{ \otimes^\cC_\psi/c \mid \psi \in \mathrm{Mul}_\cO(\{x_i\}_i,y),\ c \in \cC(y) \right\} \]
    Assume the following is true:
    \begin{enumerate}
        \item\label{prop:day-o-monoidal-1} for all $y \in \cO$, the category $\cD(y)$ admits all $\cK(y)$-shaped colimits;
        \item\label{prop:day-o-monoidal-2} for every operation $\phi \in \mathrm{Mul}_\cO(\{x_i\}_i,y)$ and every $j$, the associated tensor functor $\otimes^\cD_\phi \colon \prod_i \cD(x_i) \to \cD(y)$ preserves all $\cK(x_j)$-shaped colimits in the $j$-th component.
    \end{enumerate}
    Then $\Day_{\cC,\cD}^\otimes \to \cO^\otimes$ is a cocartesian fibration of operads.
\end{prop}


\begin{rem}
    The assumptions of \cref{prop:day-o-monoidal} are for example satisfied if there exists some regular cardinal $\kappa$ with the property that each $\cD(y)$ is $\kappa$-cocomplete, every tensor functor of $\cD$ preserves $\kappa$-small colimits in each variable, and each $\cC(y)$ is $\kappa$-small, reproducing \cite[Proposition~2.2.6.16]{HA}.
\end{rem}

\begin{proof}[Proof of \cref{prop:day-o-monoidal}]
	By construction, $\Day_{\cC,\cD}^\otimes$ is an operad, so \cite[Proposition~2.1.2.12]{HA} shows that we only have to check that $\Day_{\cC,\cD}^\otimes \to \cO^\otimes$ is a cocartesian fibration.
    As in \cite[Section~2.2.6]{HA}, the crucial part of the argument lies in identifying mapping anima in $\Day_{\cC,\cD}^\otimes$.

    We require some notation.
    Let $\pi \colon \Day_{\cC,\cD}^\otimes \to \cO^\otimes$ and $u \colon \Day_{\cC,\cD}^\otimes \to (\Ar^\oplax)^\times$ denote the projection functors, and abbreviate $\cX^\times := \catinf^\times \times_{\Comm^\otimes} \catinf^\times$.
    Note that then $\cX = \catinf \times \catinf$.
    Let $\phi \colon x \to y$ be a morphism in $\cO^\otimes$, let $F \in \pi^{-1}(x)$ and $G \in \pi^{-1}(y)$, and denote by $\Hom_{\Day_{\cC,\cD}^\otimes}^\phi(F,G)$ the anima of morphisms lying over $\phi$.
    Since $\Day_{\cC,\cD}^\otimes$ is defined as a pullback, we have a natural pullback square
    \[\begin{tikzcd}
		\Hom_{\Day_{\cC,\cD}^\otimes}^\phi(F,G)\ar[r]\ar[d] & \Hom_{(\Ar^\oplax)^\times}(uF,uG)\ar[d] \\
		*\ar[r, "{(\cC,\cD) \circ \phi}"] & \Hom_{\cX^\times}((s,t)F,(s,t)G)
	\end{tikzcd}\]
	In particular, the objects $sF$, $tF$, $sG$ and $tG$ are identified with $\cC(x)$, $\cD(x)$, $\cC(y)$ and $\cD(y)$, respectively.
	Denoting by $\alpha \colon \langle k \rangle \to \langle l \rangle$ the image of $\phi$ in $\Comm^\otimes$, the anima $\Hom_{\Day_{\cC,\cD}^\otimes}^\phi(F,G)$ sits in a natural fibre square
	\[\begin{tikzcd}
		\Hom_{\Day_{\cC,\cD}^\otimes}^\phi(F,G)\ar[r]\ar[d] & \Hom_{(\Ar^\oplax)^\times}^\alpha(uF,uG)\ar[d] \\
		*\ar[r, "{(\cC,\cD) \circ \phi}"] & \Hom_{\cX^\times}^\alpha((s,t)F,(s,t)G)
	\end{tikzcd}\]
	Since both $(s,t) \colon (\Ar^\oplax)^\times \to \cX^\times$ and $\cX^\times \to \Comm^\otimes$ are cocartesian fibrations, the right vertical map is identified with the map
	\[ \Hom_{(\Ar^\oplax)^\times_{\langle l \rangle}}^{\id_{\langle l \rangle}}(\alpha_!(uF),uG) \to \Hom_{\cX^\times_{\langle l \rangle}}^{\id_{\langle l \rangle}}(\alpha_!((s,t)F),(s,t)G) \]
	induced by $(s,t)$.
	Write $F = F_1 \boxtimes \ldots \boxtimes F_k$ and $G = G_1 \boxtimes \ldots \boxtimes G_l$.
	As both $\Ar^\oplax$ and $\cX$ carry the cartesian symmetric monoidal structure, this map is in turn identified with the map
	\begin{equation}\label{eq:day-o-monoidal-1}
		\prod_{j=1}^l \Hom_{\Ar^\oplax}\Big( \prod_{i \in \alpha^{-1}(j)} F_i, G_j \Big) \to \prod_{j=1}^l \Hom_{\cX}\Big( \prod_{i \in \alpha^{-1}(j)} (s,t)F_i, (s,t)G_j \Big)
	\end{equation}
	induced by $(s,t)$.
    Consequently, it suffices to consider the case that $\alpha \colon \langle k \rangle \to \langle 1 \rangle$ is an active morphism so that $\phi \in \mathrm{Mul}_\cO(\{x_i\}_i,y)$.

    With respect to the given identifications, the base point $(\cC,\cD) \circ \phi$ now becomes the point in
    \begin{align*}
     \Hom_{\cX}&\big(\prod_{i=1}^k (\cC(x_i), \cD(x_i)), (\cC(y),\cD(y)\big) \\
     &\simeq \Hom_\catinf\big(\prod_{i=1}^k \cC(x_i),\cC(y)\big) \times \Hom_\catinf\big(\prod_{i=1}^k \cD(x_i),\cD(y)\big)
    \end{align*}
    corresponding to the pair of multiplication functors $(\otimes_\phi^\cC,\otimes_\phi^\cD)$ of $\cC$ and $\cD$.

    By \cref{thm:main} and \cref{rem:aropl-straightened}, the fibre of \eqref{eq:day-o-monoidal-1} is identified with the anima of natural transformations
    \[ \Nat\big(\otimes_\phi^\cD \circ \prod_{i=1}^k \St(F_i), \St(G) \circ \otimes_\phi^\cC\big).\]
    Fix now $\phi \colon x \to y$ and $F \in \pi^{-1}(x)$.
    As before, let $\alpha \colon \langle k \rangle \to \langle l \rangle$ be the image of $\phi$ in $\Comm^\otimes$ and let $F = F_1 \boxtimes \ldots \boxtimes F_k$ be the canonical decomposition of $F$ with $F_i \in \Ar^\oplax$.
    Denote by $\phi_j \in \mathrm{Mul}_\cO(\{x_i\}_{i \in \alpha^{-1}(j)},y_j)$ the active morphisms determined by $\phi$ and $\alpha$.
    Using assumption~\eqref{prop:day-o-monoidal-1} and the pointwise formula for left Kan extensions, the composite
    \[ \prod_{i \in \alpha^{-1}(j)} \cC(x_i) \xrightarrow{\prod_i \St(F_i)} \prod_{i \in \alpha^{-1}(j)} \cD(x_i) \xrightarrow{\otimes_{\phi_j}^\cD} \cD(y_j) \]
    admits a left Kan extension $G_j$ along $\otimes_{\phi_j}^\cC \colon \prod_{i \in \alpha^{-1}(j)} \cC(x_i) \to \cC(y_j)$ for each $j \in \langle l \rangle$.
    As we have seen, the unit transformations
    \[ \eta_j \colon \otimes_{\phi_j}^\cD \circ \prod_{i \in \alpha^{-1}(j)} \St(F_i) \Rightarrow \St(G_j) \circ \otimes_{\phi_j}^\cC \]
    determine a point $\eta \in \Hom_{\Day_{\cC,\cD}^\otimes}^\phi(F,G)$, where $G := G_1 \boxtimes \ldots \boxtimes G_l$.
    We claim that $\eta$ is a cocartesian lift of $\phi$.

    This amounts to checking that for each $H \in \Day_{\cC,\cD}^\otimes$, the induced commutative square
    \[\begin{tikzcd}
        \Hom_{\Day_{\cC,\cD}^\otimes}(G,H)\ar[r, "- \circ \eta"]\ar[d] & \Hom_{\Day_{\cC,\cD}^\otimes}(F,H)\ar[d] \\
        \Hom_{\cO^\otimes}(y,z)\ar[r, "- \circ \phi"] & \Hom_{\cO^\otimes}(x,z)
    \end{tikzcd}\]
    is a pullback, where we set $z := \pi(H)$.
    This is equivalent to the assertion that for each $\psi \in \Hom_{\cO^\otimes}(y,z)$, the induced map on vertical fibres
    \begin{equation}\label{eq:day-o-monoidal-2}
        - \circ \eta \colon \Hom_{\Day_{\cC,\cD}^\otimes}^{\psi}(G,H) \to \Hom_{\Day_{\cC,\cD}^\otimes}^{\psi\phi}(F,H)    
    \end{equation}
    is an equivalence.
    Letting $\beta \colon \langle l \rangle \to \langle n \rangle$ denote the image of $\psi$ in $\Comm^\otimes$, the preliminary discussion and 
    \cref{thm:main} identify this map with the product of the maps
    \begin{align*}
        \Nat\Big(&\otimes_{\psi_m}^\cD \circ \prod_{j \in \beta^{-1}(m)} \big(\St(G_j) \circ \otimes_{\phi_j}^\cC\big), \St(H_m) \circ \otimes_{\psi_m}^\cC \circ \prod_{j \in \beta^{-1}(m)} \otimes_{\phi_j}^\cC\Big) \\
        &\xrightarrow{\eta_j^*} \Nat\Big( \otimes_{\psi_m}^\cD \circ \prod_{j \in \beta^{-1}(m)} \big(\otimes_{\phi_j}^\cD \circ \prod_{i \in \alpha^{-1}(j)} \St(F_i)\big), \St(H_m) \circ \otimes_{(\psi\phi)_m}^\cC\Big) \\
        &\simeq \Nat\Big( \otimes_{(\phi\psi)_m}^\cD \circ \prod_{i \in (\beta\alpha)^{-1}(m)} \St(F_i), \St(H_m) \circ \otimes_{(\psi\phi)_m}^\cC\Big).
    \end{align*}
    Using assumption~\eqref{prop:day-o-monoidal-2}, the pointwise formula for left Kan extensions implies that the transformation
    \[ \otimes_{\psi_m}^\cD \circ \prod_{j \in \beta^{-1}(m)} \big(\otimes_{\phi_j}^\cD \circ \prod_{i \in \alpha^{-1}(j)} \St(F_i)\big) \Rightarrow \otimes_{\psi_m}^\cD \circ \prod_{j \in \beta^{-1}(m)} \big(\St(G_j) \circ \otimes_{\phi_j}^\cC\big) \]
    induced by $\eta_j$ also exhibits $\otimes_{\psi_m}^\cD \circ \prod_{j \in \beta^{-1}(m)} \St(G_j)$ as a left Kan extension, so \eqref{eq:day-o-monoidal-2} is an equivalence.
\end{proof}


\begin{rem}
    In the situation of \cref{prop:day-o-monoidal}, assume that $\cO$ is a symmetric monoidal category, so that $\cC$ and $\cD$ correspond to lax symmetric monoidal functors $\cO \to \catinf$.
    Unwinding the proof of \cref{prop:day-o-monoidal}, one obtains the following description of the lax symmetric monoidal functor $\cO \to \catinf$ given by the straightening of $\Day_{\cC,\cD}^\otimes \to \cO^\otimes$:
    \begin{enumerate}
        \item The underlying functor $\cO \to \catinf$ sends $x \in \cO$ to $\Fun(\cC(x),\cD(x))$ and a morphism $f \colon x \to x'$ to the composite
        \[ \Fun(\cC(x),\cD(x)) \xrightarrow{f \circ -} \Fun(\cC(x),\cD(x')) \xrightarrow{f_!} \Fun(\cC(x'),\cD(x')), \]
        where $f_!$ denotes the left Kan extension functor.
        \item For $x, x' \in \cO$, the lax monoidal structure map is given by the composite
        \begin{align*}
            \Fun(\cC(x),\cD(x)) \times \Fun(\cC(x'),\cD(x'))
            &\to \Fun(\cC(x) \times \cC(x'),\cD(x) \times \cD(x')) \\
            &\xrightarrow{\otimes_\cD \circ -} \Fun(\cC(x) \times \cC(x'), \cD(x \otimes x')) \\
            &\xrightarrow{(\otimes_\cC)_!} \Fun(\cC(x \otimes x'),\cD(x \otimes x')),
        \end{align*}
        where the first arrow arises from the lax symmetric monoidal structure on $\Fun \colon \catinf^\op \times \catinf \to \catinf$, and $\otimes_\cC$ and $\otimes_\cD$ denote the tensor operations in $\cC$ and $\cD$, respectively.
        \item The structure map associated to the monoidal unit is given by the object in $\Fun(\cC(\mathbf{1}_\cO),\cD(\mathbf{1}_\cO))$ which arises as the left Kan extension of $* \xrightarrow{\mathbf{1}_\cD} \cD(\mathbf{1}_\cO)$ along $* \xrightarrow{\mathbf{1}_\cC} \cC(\mathbf{1}_\cO)$.
    \end{enumerate}
\end{rem}



