\subsubsection{The Leland model}

Following the standard computational approach, we first transform the terminal-boundary value problem~\eqref{eq:Leland}--\eqref{eq:bcLeland2} to an initial-boundary value problem by applying the following change of variables~\cite{Wei2024}:
\begin{itemize}
  \item $\displaystyle \tau = \frac{1}{2} \sigma^2 (T - t)$;
  \item $\displaystyle x = \ln(S) + \kappa \tau $; and
  \item $\hat{v}(x,\tau) = e^{\kappa \tau} V(S,t)$,
\end{itemize}
where $\kappa = 2r/\sigma^2$. It can then be shown that the PDE~\eqref{eq:Leland} is transformed to 
\begin{equation}
    \displaystyle \frac{\partial \hat{v}}{\partial \tau} = \frac{\partial^2 \hat{v}}{\partial x^2} - \frac{\partial \hat{v}}{\partial x} + \textit{Le}\left|\frac{\partial^2 \hat{v}}{\partial x^2} - \frac{\partial \hat{v}}{\partial x}\right|= 0, \quad (\tau,x) \in (0,\frac{1}{2}\sigma^2 T) \times (-\infty,\infty),\label{eq:Lelandtrans}
\end{equation}
after using the fact that $\sign(\cdot) \times \cdot = |\cdot|$. For the construction of our IGA, we shall consider a mixed formulation of~\eqref{eq:Lelandtrans}, given by
\begin{eqnarray}
\begin{cases}
    \displaystyle \frac{\partial \hat{v}}{\partial \tau} = \frac{\partial^2 \hat{v}}{\partial x^2} - \frac{\partial \hat{v}}{\partial x} + \textit{Le}\left|\Tilde{v}\right|,\\[10pt]
     \displaystyle \Tilde{v} = \frac{\partial^2 \hat{v}}{\partial x^2} - \frac{\partial \hat{v}}{\partial x}.
\end{cases}
\label{eq:system_of_transformed_eqxns_for_Leland}
\end{eqnarray}
The terminal and the boundary conditions are transformed to the initial and boundary conditions
\begin{align}
%    \hat{v}(x,0) &= \max(\textcolor{red}{S_{int}}e^x-\hat{K},0),\\[5pt]
    \hat{v}(x,0) &= \max(e^x-\hat{K},0),\\[5pt]
    \hat{v}(x,\tau) &= 0 ~~\text{as}~x\rightarrow -\infty,\\[5pt]
%    \hat{v}(x,\tau) &\approx \textcolor{red}{S_{int}}e^x ~~\text{as}~x\rightarrow \infty.
    \hat{v}(x,\tau) &\approx e^x - \hat{K} ~~\text{as}~x\rightarrow \infty.
\end{align}

\subsubsection{AFV model}

For the AFV model, we consider the change of variables~\cite{Zhu_Landau}:
\begin{itemize}
  \item $\displaystyle \tau = T - t $, and
  \item $\displaystyle x = \ln\left(\frac{S}{S_{\text{int}}}\right)$,
\end{itemize}
where $S_{\text{int}}$ is the stock price at the initial time $t = 0$. Applying the change of variables to the PDEs \eqref{Ueqxn}--\eqref{Ceqxn} results in the transformed PDEs
\begin{align}
\displaystyle\frac{\partial U}{\partial \tau} &= \frac{\sigma^2}{2}\frac{\partial^2 U}{\partial x^2} +\left(r+p\eta -\frac{\sigma^2}{2}\right)\frac{\partial U}{\partial x} - (r+p)U + p\delta, \label{eq:transU} \\[10pt]
\displaystyle\frac{\partial B}{\partial \tau} &= \frac{\sigma^2}{2}\frac{\partial^2 B}{\partial x^2} + \left(r+p\eta -\frac{\sigma^2}{2}\right)\frac{\partial B}{\partial x} - (r+p)B +\hat{R}pB,\label{eq:transB}\\[10pt]
\displaystyle\frac{\partial C}{\partial \tau} &= \frac{\sigma^2}{2}\frac{\partial^2 C}{\partial x^2} + \left(r+p\eta -\frac{\sigma^2}{2}\right)\frac{\partial C}{\partial x} - (r+p)C + p\gamma,\label{eq:transC}
\end{align}
where
\begin{align}
\delta = \begin{cases}
                   \hat{R}B,&\text{if } \hat{R}B > kS_{\text{int}}e^x(1-\eta), \\[5pt]
                   kS_{\text{int}}e^x(1-\eta), &\text{otherwise},
               \end{cases}
\end{align}
and
\begin{align}
    \displaystyle \gamma = \begin{cases}
                   0, &\text{if } kS_{\text{int}}e^x(1-\eta) - \hat{R}B < 0, \\[5pt]
                  kS_{\text{int}}e^x(1-\eta) - \hat{R}B , &\text{otherwise},
               \end{cases}
\end{align}
with $(\tau,x) \in (0,T)\times (-\infty,\infty)$.

The terminal, boundary conditions and inequality constraints can be transformed in the same manner.

