% % At $x= x_{max}$, the convertible bond is going to be converted into stock:
To construct the penalty PDEs for the convertible bond valuation, we  reformulate the inequality constraint ~\eqref{constraint:u_constrain_1} as follows \cite{Forsyth2002}:
$$
   U(x,\tau) \ge \max(B_{put}, kS_{\text{int}}e^x) \, \Rightarrow \, \Pi_{put} :=  U_{put}^{\star} - U(x,\tau) \le 0,
$$
where $U_{put}^{\star} = \max(B_{put}, kS_{\text{int}}e^x)$. With~\eqref{constraint:u_constrain_2} reformulated as $\Pi_{call} := U(x,\tau) - U_{call}^{\star} \le 0$, where $U_{call}^{\star} = \max(B_{call},kS_{\text{int}}e^x)$, the PDE for the convertible bond valuation (Eq.~\eqref{eq:transU}) can be written as the penalty PDE
\begin{align}
    \frac{\partial U}{\partial \tau} &= \frac{\sigma^2}{2}\frac{\partial^2 U}{\partial x^2} +\left(r +p\eta - \frac{\sigma^2}{2}\right)\frac{\partial U}{\partial x}-(r+p)U + p\delta +\rho\max(U - U_{call}^{\star},0) + \rho\max(U_{put}^{\star} - U,0)  \notag\\     
    &= \frac{\sigma^2}{2}\frac{\partial^2 U}{\partial x^2}+\left(r +p\eta - \frac{\sigma^2}{2}\right)\frac{\partial U}{\partial x} - (r+p)U  + p\delta+ \rho \alpha_{call}\Pi_{call}  + \rho \alpha_{put} \Pi_{put}, \label{eq:transpenU}
\end{align}
where $\rho > 0$ is the penalty parameter,
\begin{eqnarray}
    \alpha_{call} = \begin{cases}
                   1,& \text{if } U-U_{call}^{\star} \ge 0, \\[5pt]
                   0,& \text{otherwise},
               \end{cases}  \text{ \, and \, }
    \alpha_{put} = \begin{cases}
                   1,& \text{if } U_{put} ^{\star} -U\ge 0, \\[5pt]
                   0,& \text{otherwise}.
               \end{cases}  \label{eq:alpha}
\end{eqnarray}
%\sout{Note that this penalty PDE is not defined in the entire time domain $[0,T]$. Instead, the penalty term is only active in the time interval where the right to Call or Put is active.}


