\section{Isogeometric analysis}
 \label{sec:methodology}

To describe IGA for solving the two nonlinear PDE models given by the system~\eqref{eq:system_of_transformed_eqxns_for_Leland} and the set of PDEs~\eqref{eq:transpenU},~\eqref{eq:transB}, and~\eqref{eq:transC}, we consider the unified PDE
\begin{align}
    \frac{\partial w}{\partial \tau } = \Upsilon_{1,w} \frac{\partial^2 w}{\partial x^2} + \Upsilon_{2,w} \frac{\partial w}{\partial x} - \Upsilon_{3,w} w + \mathcal{N}_w, \label{eq:unified}
\end{align}
where $w \in \{\hat{v},U,B,C\}$, with
\begin{align}
    \Upsilon_{1,w} =\begin{cases}
        1,& w = \hat{v}, \\
        \sigma^2/2,&\text{otherwise},
    \end{cases}
    \quad
    \Upsilon_{2,w} = \begin{cases}
       -1,& w = \hat{v}, \\
       r + p \eta - \sigma^2/2,& \text{otherwise},
    \end{cases} 
    \quad
    \Upsilon_{3,w} = \begin{cases}
       0,& w = \hat{v}, \\
       (r + p) - \hat{R} p, & w = B, \\
       r + p, &\text{otherwise},
    \end{cases} \notag
\end{align}
and
\begin{align}
\mathcal{N}_w = \begin{cases}
       Le|\tilde{v}|,& w = \hat{v}, \\
       p\delta + \rho(\alpha_{call} \Pi_{call} + \alpha_{put} \Pi_{put}), & w = U, \\
       0, &w = B, \\
       p \gamma, &w = C.
    \end{cases} \notag
\end{align}

