\section{Time integration scheme}
\label{sec:timeintegral}

Numerical integration of inner products in~\eqref{FEMsystem_of_eqxns} results in the differential algebraic equation
\begin{equation}\label{eq:deagen}
  \frac{\partial}{\partial \tau} (M \mathbf{w} + \mathbf{b}_{M,w}) = - \Upsilon_{1,w} (K \mathbf{w} + \mathbf{b}_{K,w} ) - \Upsilon_{2,w} (N \mathbf{w} + \mathbf{b}_{N,w}) -
  \Upsilon_{3,1} (M \mathbf{w} + \mathbf{b}_{M,w}) 
  + M \mathbf{y}(w) + \mathbf{b}_v =: \mathbf{F}(w),   
\end{equation}
where $\mathbf{w} := [w_j]_{j=2}^{n-1} \in \mathbb{R}^{n-2}$. The matrices $M$, $N$, and $K$ are of size $(n-2)\times (n-2)$ and sparse, due to the small support each NURBS basis function has relative to the computational domain. $\mathbf{b}$ is the boundary condition vector associated with the interpolatory NURBS basis functions $R_{1,p}$ and $R_{n,p}$. The equation~\eqref{eq:deagen} is integrated using the $\theta$-scheme:
\begin{align}
  M\mathbf{w}^{m+1} + \mathbf{b}_{M,w}^{m+1} = M\mathbf{w}^m + \mathbf{b}^m_{M,w} + \Delta \tau \theta \mathbf{F}^{m+1}(w) + \Delta \tau \mathbf{F}^m(w), \label{eq:thetagen}
\end{align}
where $\Delta \tau$ is the time step. To improve stability, a number of Rannacher steps \cite{Rannacher1984} is performed at the initial step from $m =0$ to $m=1$ using the implicit scheme $(\theta = 0)$. 

In the sequel, we discuss the time integration procedure for each model in detail.

\subsection{The Leland model} \label{sec:CN_Leland}

Using the constants given after the Equation~\eqref{eq:unified}, the $\theta$-scheme~\eqref{eq:thetagen} for Leland's model reads
\begin{align}
  A_1 \widehat{\mathbf{v}}^{m+1} - \Delta \tau \theta \left( Le M| \widetilde{\mathbf{v}}^{m+1}| - \mathbf{b}^{m+1}_{M,\widetilde{v}}\right) &= A_0 \widehat{\mathbf{v}}^{m}  - \Delta \tau (1-\theta) \left( Le M| \widetilde{\mathbf{v}}^{m}| - \mathbf{b}^{m}_{M,\widetilde{v}}\right) \notag \\
  &- \Delta \tau \theta \left( \mathbf{b}^{m+1}_{K,\widehat{v}} + \mathbf{b}^{m+1}_{N,\widehat{v}} \right) - \Delta \tau (1-\theta) \left( \mathbf{b}^{m}_{K,\widehat{v}} + \mathbf{b}^m_{N,\widehat{v}} \right), \label{eq:thetaleland}
\end{align}
where $A_0 = M - \Delta \tau (1-\theta)(K + N)$ and $A_1 = M + \Delta \tau \theta (K + N)$, and $\widehat{\mathbf{v}}^m := [\widehat{v}_j]$ satisfies the equation
$$
  M \widetilde{\mathbf{v}}^m = - (K + N) \widehat{\mathbf{v}}^m - \mathbf{b}^m_{K,\widehat{v}} - \mathbf{b}^m_{N,\widehat{v}},
$$
obtained from the weak formulation of the second PDE in~\eqref{eq:system_of_transformed_eqxns_for_Leland}. Linearization of~\eqref{eq:thetaleland} by assuming $|\widetilde{\mathbf{v}}^{m+1}| \approx |\widetilde{\mathbf{v}}^{m}|$ results in the time integration procedure
\begin{align}
\begin{cases}
  \widetilde{\mathbf{v}}^m = - M^{-1} \left((K + N) \widehat{\mathbf{v}}^m + \mathbf{b}^m_{K,\widehat{v}} - \mathbf{b}^m_{N,\widehat{v}} \right), \\
  \mathbf{f}^m = A_0 \widehat{\mathbf{v}}^m - \Delta \tau \left( Le M| \widetilde{\mathbf{v}}^{m}| - \mathbf{b}^{m}_{M,\widetilde{v}}\right) - \Delta \tau \theta \left( \mathbf{b}^{m+1}_{K,\widehat{v}} + \mathbf{b}^{m+1}_{N,\widehat{v}} \right) - \Delta \tau (1-\theta) \left( \mathbf{b}^{m}_{K,\widehat{v}} + \mathbf{b}^m_{N,\widehat{v}} \right), \\
  \widehat{\mathbf{v}}^{m+1} = A_1^{-1} \mathbf{f}^m,
\end{cases}
\label{eq:DAE Leland model}
\end{align}
for $m =0,1,\dots.$

