% $$}

% \sout{In the context of American-style derivatives, the convertible bond problem refers to the stopping criteria used to terminate iteration to conserve computational resource. 
% the first typical criterion is the difference of two consecutive solution vectors $\displaystyle \parallel \bsu^{m+1,k} - \bsu^{m+1,k-1}\parallel_{\infty}\leq tol$, which serves to guarantee the termination. The importance of the second criterion deserves attention, since we are talking about gaps arising from the penalty matrices. Its equivalence (i.e $\displaystyle P_{call}^{m+1,k-1} = P_{call}^{m+1,k}$) is crucial to facilitate the convergence of Newton's method using the less number of iterations per time step.}

The procedure for computing the solutions in the interior for one $\theta$-scheme step is summarized in Algorithm~\ref{alg:Interior}.

\begin{algorithm}[H] 
\begin{algorithmic}[1] 
\Require input $\bfU^m$, $\bfB^m$;
\State compute $B_p(\tau^{m+1})$ and $B_c(\tau^{m+1})$;
\State compute $\bfB^{m+1}$ from~\eqref{CNsystem2}, without constraints;
\State compute $\gamma$;
\State compute $\bfC^{m+1}$ from~\eqref{CNsystem3};
\State apply minimum-maximum value constraints (i.e., \eqref{constraint:v_constrain_1} and~\eqref{constraint:v_constrain_2}) on $\bfB^{m+1}$ using $\bfC^{m+1}$;
\For{$k = 1,2,\dots$ until convergence}
    \State compute $\bsf(\bfU^{m+1,k-1})$ using~\eqref{eqnonlinU};
    \State compute $\nabla \bsf(\bfU^{m+1,k-1})$ using~\eqref{eqjacf};
    \State $\bfU^{m+1,k} \leftarrow \bfU^{m+1,k-1} - \left( \nabla \bsf(\bfU^{m+1,k-1}) \right)^{-1} \bsf(\bfU^{m+1,k-1})$;
    \If {$\parallel\bfU^{m+1,k} - \bfU^{m+1,k-1}\parallel_{\infty}\leq tol~\text{OR}~\left[P_{call}^{m+1,k-1} = P_{call}^{m+1,k}~\text{AND}~ P_{put}^{m+1,k-1} = P_{put}^{m+1,k}\right]$} 
        \State\algorithmicbreak
    \EndIf
\EndFor
\State apply the constraints ~\eqref{constraint:c_constrain_1} and~\eqref{constraint:c_constrain_2} on  $\bfB^{m+1}$ using $\bfU^{m+1,k}$;
\If{$\tau^{m+1} \in \mathcal{T}_{\text{coupon}}$}
    \State $\bfU^{m+1} \leftarrow \bfU^{m+1} + K_{coup}$;
    \State $\bfB^{m+1} \leftarrow \bfB^{m+1} + K_{coup}$;
\EndIf
\end{algorithmic}
\caption{Computing the interior solutions}\label{alg:Interior}
\end{algorithm}
