\section{Compatible actions of inverse semigroups and partial actions of groups}\label{sec-comp-act}

\subsection{From compatible actions of $S$ to partial actions of $\cG(S)$}

%Let $S$ be an inverse semigroup and $A$ a {\color{blue} unital}  $K$-algebra. Recall that an \textit{action} of $S$ on $A$ is a homomorphism $\0:S\to\cI(A)$,  such that $\dom\0_s$ and $\ran\0_s$ are ideals of $A$ and $\0_s$ is an algebra isomorphism for all $s\in S$.

We give the next:

\begin{defn}
	Let $\0$ be a (unital) action of $S$ on $A$. We say that $\0$ is \textit{compatible}, if for all $(s,t)\in\sg$ the partial bijections $\0_s$ and $\0_t$ agree on the intersection of their domains, i.e.
	\begin{align*}
		\0_s|_{\dom\0_s\cap\dom\0_t}=\0_t|_{\dom\0_s\cap\dom\0_t}.
	\end{align*}
\end{defn}

By \cite[Proposition 1.2.1 (2)]{Lawson} the latter is equivalent to $\0_{s\m t}$ and $\0_{st\m}$ being idempotents. In particular, any action of an $E$-unitary semigroup $S$ is compatible, as $s\m t,st\m\in E(S)$ for all $(s,t)\in\sg$.

Assume that $\0$ is compatible. For any $g\in \cG(S)$ define 
\begin{align*}
	\D_g=\sum_{s\in g} 1_sA.
\end{align*} 
Then $\D_{g\m}=\sum_{s\in g\m} 1_sA=\sum_{s\in g} 1_{s\m}A$. Given $a=\sum_{s\in g}a_{s\m}\in \D_{g\m}$ with $a_{s\m}\in 1_{s\m}A$, set
\begin{align}\label{tl-0_g(a)}
	\tl\0_g(a)=\sum_{s\in g}\0_s(a_{s\m}).
\end{align}

\begin{lem}\label{tl-0_g-bigection}
	Equality \cref{tl-0_g(a)} defines a bijection from $\D_{g\m}$ to $\D_g$ whose inverse is $\tl\0_{g\m}$.
\end{lem}
\begin{proof}
In order to show that $\tl\0_g$ is well-defined, assume that $\sum_{s\in g}a_{s\m}=0$ with $a_{s\m}\in 1_{s\m}A$ for all $s\in g$ and $\{s\in g\mid a_{s\m}\ne 0\}$ finite.  We are going to prove by induction on the cardinality of $\{s\in g\mid a_{s\m}\ne 0\}$ that $\sum_{s\in g}\0_s(a_{s\m})=0$. The base case (cardinality $1$) is trivial. For the induction step fix $s\in g$ and write 
	\begin{align*}
		0=(1_A-1_{s\m})\sum_{t\in g}a_{t\m}=\sum_{t\in g}(1_A-1_{s\m})a_{t\m},
	\end{align*}
	where $(1_A-1_{s\m})a_{t\m}\in 1_{t\m}A$ and
	\begin{align*}
		|\{t\in g\mid (1_A-1_{s\m})a_{t\m}\ne 0\}|<|\{s\in g\mid a_{s\m}\ne 0\}|,
	\end{align*}
	because $(1-1_{s\m})a_{s\m}=0$. By the induction hypothesis 
	\begin{align*}
		0 &=\sum_{t\in g}\0_t\left((1_A-1_{s\m})a_{t\m}\right)=\sum_{t\in g,t\ne s}\0_t\left((1_A-1_{s\m})a_{t\m}\right)\\
		&=\sum_{t\in g,t\ne s}\0_t\left(a_{t\m}\right)-\sum_{t\in g,t\ne s}\0_t\left(1_{s\m}a_{t\m}\right),
	\end{align*}
	so using compatibility, we have
	\begin{align*}
		\sum_{t\in g,t\ne s}\0_t\left(a_{t\m}\right)&=\sum_{t\in g,t\ne s}\0_t\left(1_{s\m}a_{t\m}\right)=\sum_{t\in g,t\ne s}\0_s\left(1_{s\m}a_{t\m}\right)\\
		&=\0_s\left(1_{s\m}\sum_{t\in g,t\ne s}a_{t\m}\right)=\0_s\left(-1_{s\m}a_{s\m}\right)=-\0_s(a_{s\m}).
	\end{align*}
	Thus, $\sum_{s\in g}\0_s(a_{s\m})=0$, so $\tl\0_g$ is well-defined. It is easy to see that $\tl\0_g(a)\in \D_g$ and that the map $\tl\0_{g\m}:\D_g\to\D_{g\m}$ is inverse to $\tl\0_g$.
		\end{proof}

In order to prove that $\{\tl\0_g\}_{g\in \cG(S)}$ is a partial action of $\cG(S)$ on the algebra $A$, we need some preparation. The following fact should be known. Since we did not find a reference for it, we include a proof for the sake of completeness.

\begin{lem}\label{R=sum-orth-ideals}
	Let $R$  be a (non-necessarily unital) ring and $e_1,\dots,e_n$ central idempotents of $R$ such that $R=\sum_{i=1}^n Re_i$. Then  $R$ is unital with 
	\begin{align}\label{unit of R}
	1_R= \sum _i e_i - \sum_{i<j} e_i e_j + \sum _{i<j<k}e_i e_j e_k +\dots + (-1)^{n+1} e_1 e_2 \cdots e_n,
	\end{align} and
	\begin{align}\label{R=Re_1+...+R.prod(1-e_i)}
R=Re_1\oplus R(1_R-e_1)e_2
 \oplus R(1_R-e_1)(1_R-e_2)e_3
 \oplus\dots\oplus R\prod_{i=1}^{n-1}(1_R-e_i)e_n.
	\end{align} 
\end{lem}
\begin{proof}
	 We use induction on $n$ to show \eqref{unit of R}. For $n=1$ there is nothing to prove. Suppose that \eqref{unit of R} holds for 
	all rings  $R'$ admitting a decomposition $R'=\sum_{i=1}^{n-1} R'e_i$ with some central idempotents $e_i \in R'$.  Now consider our ring  $R=\sum_{i=1}^{n} Re_i$.
	Then by induction the ideal $R'=\sum_{i=1}^{n-1} Re_i = \sum_{i=1}^{n-1} R' e_i  $ is a unital subring with the unity element
	\begin{align}\label{unity of R'}
	  1_{R'}=\sum _{1\leq i \leq n-1} e_i - 
	\sum_{1\leq i<j \leq n-1} e_i e_j + \sum _{1\leq i<j<k\leq n-1}e_i e_j e_k +\dots  + (-1)^{n} e_1 e_2 \cdots e_{n-1}.\end{align} Hence $R'= R 1_{R'}$ and, since  $R= R 1_{R'} + Re_{n+1},$ it is readily seen that 
	the element $ 1_{R'} + e_{n+1} -1_{R'} e_{n+1}$ is the unity element of $R.$  Then using \eqref{unity of R'}  we obtain that
	 $ 1_{R'} + e_{n+1} -1_{R'} e_{n+1}$ equals \eqref{unit of R}, as desired.

	 Finally, \cref{R=Re_1+...+R.prod(1-e_i)} directly follows from the following decomposition of $1_R$ into a sum of pairwise orthogonal central idempotents:
	 \begin{align}\label{expresssion for 1_R}
1_R=e_1 + (1_R-e_1)e_2
  + (1_R-e_1)(1_R-e_2)e_3
 + \dots + \prod_{i=1}^{n-1}(1_R-e_i)e_n,
	\end{align} which is readily verified by removing the parentheses in the right hand side of \eqref{expresssion for 1_R}.
