\begin{lem}\label{tl-0_g-circ-tl-0_h-le-tl-0_gh}
	For all $g,h\in \cG(S)$ one has $\tl\0_g\circ\tl\0_h\le \tl\0_{gh}$.
\end{lem}
\begin{proof}
	Let $a\in\D_{h\m}\cap\D_{h\m g\m}$. We first show that $\tl\0_h(a)\in\D_{g\m}$. We have
	\begin{align*}
		a=\sum_{i=1}^m a_{s\m_i}=\sum_{j=1}^n b_{t\m_j},
	\end{align*}
	where $s_i\in gh$, $t_j\in h$, $a_{s\m_i}\in 1_{s\m_i}A$ and $b_{t\m_j}\in 1_{t\m_j}A$. Applying \cref{a=sum-a_k-with-a_k-in-R_ek} to the ideal $I=\sum_{i=1}^m 1_{s\m_i}A=\sum_{i=1}^m 1_{s\m_i}I$, we  obtain
	\begin{align*}
		a=\sum_{k=1}^m\sum_{j=1}^n b_{t\m_j}f_k,
	\end{align*}
	where, for all $1\le k\le m$,
	\begin{align*}
		f_k=\prod_{i=1}^{k-1}\left(1_I-1_{s\m_i}\right)1_{s\m_k}=\prod_{i=1}^{k-1}\left(1_{s\m_k}-1_{s\m_i}1_{s\m_k}\right)=\prod_{i=1}^{k-1}\left(1_A-1_{s\m_i}\right)1_{s\m_k}.
	\end{align*}
	Observe, using \eqref{theta on units}, that for all $1\le k\le m$ and $1\le j\le n$, 
	\begin{align*}
		\0_{t_j}\left(1_{t\m_j}f_k\right)&=\prod_{i=1}^{k-1}\0_{t_j}\left(1_{t\m_j}\left(1_A-1_{s\m_i}\right)1_{s\m_k}\right)\\
		&=\prod_{i=1}^{k-1}\0_{t_j}\left(1_{t\m_j}1_{s\m_k}-1_{t\m_j}1_{s\m_i}\cdot 1_{t\m_j}1_{s\m_k}\right)\\
		&=\prod_{i=1}^{k-1}\left(1_{t_js\m_k}-1_{t_js\m_i}\cdot 1_{t_js\m_k}\right)=\prod_{i=1}^{k-1}\left(1_A -1_{t_js\m_i}\right)1_{t_js\m_k}.
	\end{align*}
	Then, for all $1\le k\le m$ and $1\le j\le n$,
	\begin{align}\label{eq:theta t_j}
		\0_{t_j}\left(b_{t\m_j}f_k\right)=\0_{t_j}\left(b_{t\m_j}\right)\0_{t_j}\left(1_{t\m_j}f_k\right)=\0_{t_j}\left(b_{t\m_j}\right)\prod_{i=1}^{k-1}\left(1_A - 1_{t_js\m_i}\right)1_{t_js\m_k},
	\end{align}
	which belongs to $\D_{g\m}$ because $t_js\m_k\in h(gh)\m=g\m$. It follows that
	\begin{align*}
		\tl\0_h(a)=\sum_{k=1}^m\sum_{j=1}^n\0_{t_j}\left(b_{t\m_j}f_k\right)\in\D_{g\m}.
	\end{align*}
Thus, $\tl\0_h(\D_{h\m}\cap\D_{h\m g\m})\sst  \D_{h}\cap\D_{g\m}$. It is then easy to prove that $\tl\0_h(\D_{h\m}\cap\D_{h\m g\m})= \D_{h}\cap\D_{g\m},$ using the fact that $\tl\0 \m _h = \tl\0_{h\m}.$ In particular,
\begin{align*}
	\dom(\tl\0_g\circ\tl\0_h)=\tl\0_{h\m}(\D_h\cap\D_{g\m})=\D_{h\m}\cap\D_{h\m g\m}.
\end{align*} 

It remains to show that $\tl\0_g(\tl\0_h(a))=\tl\0_{gh}(a)$. Indeed, in view of \eqref{eq:theta t_j}, we see that
	\begin{align*}
		\tl\0_g(\tl\0_h(a))&=\sum_{k=1}^m\sum_{j=1}^n\0_{s_kt\m_j}\left(\0_{t_j}\left(b_{t\m_j}f_k\right)\right)=\sum_{k=1}^m\sum_{j=1}^n\0_{s_k}\left(\0_{t\m_jt_j}\left(b_{t\m_j}f_k\right)\right)\\
		&=\sum_{k=1}^m\sum_{j=1}^n\0_{s_k}\left(1_{t\m_j}b_{t\m_j}f_k\right)=\sum_{k=1}^m\sum_{j=1}^n\0_{s_k}\left(b_{t\m_j}f_k\right)=\tl\0_{gh}(a).
	\end{align*}
	\end{proof}





\begin{prop}\label{tl-0-part-act}
	 Let $\0$ be a compatible action of $S$ on $A.$ Then the family $\{\tl\0_g\}_{g\in \cG(S)}$ is a partial action of $\cG(S)$ on $A$.
\end{prop}
\begin{proof}
	This is a consequence of \cref{tl-0_g-bigection,tl-0_g-circ-tl-0_h-le-tl-0_gh}.
\end{proof}

		\subsection{The crossed product   $A\rtimes_\0 S$}
	Given an inverse monoid $S$ and a unital action $\0$ of $S$ on a $K$-algebra $A$, denote $L(A,\0,S)=\bigoplus_{s\in S} 1_sA\dl_s$, where $\delta_s$ is a symbol. Since unital ideals of an associative algebra are always $(L,R)$-associative, it follows from~\cite[Theorem 3.4]{EV} that $L(A,\0,S)$ is an associative $K$-algebra under the multiplication $a\delta_s\cdot b\delta_t=a\0_s(1_{s\m} b)\delta_{st}$. It is also an $A$-bimodule via the homomorphism of algebras $A\to L(A,\0,S)$, $a\mapsto a\dl_1$.

	\begin{defn}\label{defn-cross_prod_for_S-mod}
		Denote by $\N$ the ideal of $L(A,\0,S)$ generated by 
		\begin{equation}\label{rel_on_L_gen_rho}
			\{a\delta_s-a\delta_t\in L(A,\0,S)\mid a\in 1_sA\text{ and } s\le t\}.
		\end{equation}
		The quotient algebra $L(A,\0,S)/\N$ will be denoted by $A\rtimes_\0 S$ and called {\it the crossed product}  by $\0 .$ Observe that $A\rtimes_\0 S$ inherits the $A$-bimodule structure from $L(A,\0,S)$ in the natural way.
	\end{defn} 

	\noindent Notice that the element $a$ in \eqref{rel_on_L_gen_rho} is contained in  $1_tA$  by \eqref{eq:ideals natural order}.
	 In this case  we also have that $1_{s\m}1_{t\m}=1_{s\m}$ (because $s\m\le t\m$).

	\begin{lem}\label{rho_is_trans_closure}
		The set~\cref{rel_on_L_gen_rho} is invariant under the multiplication on the left and on the right in $L(A,\0,S)$, so $\N$ is the $K$-subspace of $L(A,\0,S)$ spanned by~\cref{rel_on_L_gen_rho}.
	\end{lem}
	\begin{proof}
		Denote  by $X$ the set~\cref{rel_on_L_gen_rho}. Given $a\delta_s,a\delta_t\in L(A,\0,S)$, such that $s\le t$, and an arbitrary $b\delta_u\in L(A,\0,S)$, we see that
		\[
		b\delta_u(a\delta_s-a\delta_t)=b\delta_u\cdot a\delta_s-b\delta_u\cdot a\delta_t=b\0_u(1_{u\m}a)\delta_{us}-b\0_u(1_{u\m}a)\delta_{ut}\in X,
		\]
		because $us\le ut$. Similarly,
		\[
		(a\delta_s-a\delta_t)b\delta_u=a\delta_s\cdot b\delta_u-a\delta_t\cdot b\delta_u=a\0_s(1_{s\m}b)\delta_{su}-a\0_t(1_{t\m}b)\delta_{tu},
		\]
		which belongs to $X$ if $a\0_s(1_{s\m}b)=a\0_t(1_{t\m}b)$. This is indeed the case: since $s\le t$, then $\0_s\le\0_t$ and 
		\begin{align*}
			a\0_s(1_{s\m}b)&=a\0_t(1_{s\m}1_{t\m} b)=a\0_t(1_{s\m}1_{t\m})\0_t(1_{t\m}b)\\
			&=a\0_s(1_{s\m})\0_t(1_{t\m}b)=a\0_t(1_{t\m}b).
		\end{align*}
	\end{proof}

Observe that the natural partial order $\le$ on $S$ is compatible with the multiplication on the left or on the right in $S$. Hence, the equivalence relation generated by $\le$ is a congruence on $S$. It is easy to see that this congruence coincides with $\sg$.

\begin{lem}\label{sum-s-in-C-a_s=0}
	Let $a=\sum_{s\in S}a_s\dl_s\in \N$. Then for any $\sg$-class $C$ of $S$ we have $\sum_{s\in C}a_s=0$.
\end{lem}
\begin{proof}
	Since $a\in \N$, by \cref{rho_is_trans_closure} there exists 
	$\{b_{s,t}\}_{s<t}\sst A$ such that $a=\sum_{s<t}(b_{s,t}\dl_s-b_{s,t}\dl_t)$. Then for any $s\in C$ we have
	\begin{align*}
		a_s=\sum_{s<v}b_{s,v}-\sum_{u<s}b_{u,s}.
	\end{align*}
Observe that $u<s\impl u\in C$ and $s<v\impl v\in C$. It follows that
\begin{align*}
	\sum_{s\in C}a_s=\sum_{s\in C}\left(\sum_{s<v}b_{s,v}-\sum_{u<s}b_{u,s}\right)=\sum_{s,v\in C, s<v}b_{s,v}-\sum_{u,s\in C, u<s}b_{u,s}=0.
\end{align*}
\end{proof}

\begin{rem}\label{rem:Adelta_1Embedding}  Lemma~\ref{sum-s-in-C-a_s=0} immediately implies that the homomorphism of $K$-algebras 
$A \to A\rtimes_\0 S,$ given by $a \mapsto a\dl _1 + \N $, is injective. 
\end{rem}



\begin{lem}\label{sum-a_s=0=>a-in-N}
	 Suppose that  $S$ is $E$-unitary and $a=\sum_{s\in S}a_s\dl_s\in L(A,\0,S)$. If $\sum_{s\in C}a_s=0$ for any $\sg$-class $C$ of $S$, then $a\in \N$.
\end{lem}
\begin{proof}
	It is enough to prove that $a_C:=\sum_{s\in C}a_s\dl_s\in \N$ for any  $\sg$-class $C$. The proof will be by induction on $n=|\{s\in C\mid a_s\ne 0\}|$.

	The case $n=1$ is impossible, as $a_C=0$ in this case. For $n=2$ we have $a_C=a_{s_1}\dl_{s_1}-a_{s_1}\dl_{s_2}$, where $s_1,s_2\in C$. Since $S$ is $E$-unitary, $s\m_1 s_2\in E(S)$. Then  $u:=s_1s\m_1 s_2\le s_1,s_2$  and
	 $$u u\m = s_1 s\m_1 ( s_2 s\m_2) (s_1 s\m_1)= 
	 s_1 s\m_1 ( s_1 s\m_1) (s_2 s\m_2)= (s_1 s\m_1 ) (s_2 s_2\m).$$ Then using \eqref{eq:thetaOnProductOfIdempotents} we see that  $1_u=1_{u u\m}=1_{s_1 s\m_1}1_{s_2 s\m_2} =1_{s_1}1_{s_2}$, so that $a_{s_1}\in 1_uA$. It follows that $a_C=(a_{s_1}\dl_{s_1}-a_{s_1}\dl_u)+(a_{s_1}\dl_u-a_{s_1}\dl_{s_2})\in \N$.

	Assume that $m\ge 2$ and $a_C\in \N$ for all $n\le m$.  Suppose that $n=m+1$  for our element $a$  and write $a_C=\sum_{i=1}^{m+1}a_{s_i}\dl_{s_i}$. Then $a_{s_{m+1}}=1_{s_{m+1}}a_{s_{m+1}}=-\sum_{i=1}^m 1_{s_{m+1}}a_{s_i}$, so that
	\begin{align}
		a_C&=\sum_{i=1}^m (a_{s_i}\dl_{s_i}-1_{s_{m+1}}a_{s_i}\dl_{s_{m+1}})\notag\\
		&=\sum_{i=1}^m (1_{s_{m+1}}a_{s_i}\dl_{s_i}-1_{s_{m+1}}a_{s_i}\dl_{s_{m+1}})+\sum_{i=1}^m (a_{s_i}\dl_{s_i}-1_{s_{m+1}}a_{s_i}\dl_{s_i}).\label{sum-a_s_idl_s_i=two-sums}
	\end{align}
	Observe that each summand of the first sum of \cref{sum-a_s_idl_s_i=two-sums} belongs to $\N$ by the case $n=2$. Now, the second sum of \cref{sum-a_s_idl_s_i=two-sums} equals $\sum_{i=1}^m (1_A-1_{s_{m+1}})a_{s_i}\dl_{s_i}$, where 
	$$\sum_{i=1}^m (1_A-1_{s_{m+1}})a_{s_i}=
	\sum_{i=1}^m a_{s_i} 
	-\sum_{i=1}^m 1_{s_{m+1}}a_{s_i}= \sum_{i=1}^m a_{s_i} +a_{s_{m+1}}=0,$$  so it also belongs to $\N$ by the case $n=m$. Thus, $a_C\in \N$.
\end{proof}

