\begin{prop}\label{prop:SurjectivePhi}
	 Assume that  $\0 $ is a compatible  action of an inverse monoid $S$ on the algebra $A.$ Then there is a surjective algebra homomorphism $\Phi:A\rtimes_\0 S\to A\rtimes_{\tl\0} \cG(S)$ sending $a\dl_s+\N$ to $a\dl_{[s]}$, where $[s]\in\cG(S)$ is the $\sg$-class of $s$.
\end{prop}
\begin{proof}
	Let us first show that the mapping $\Phi$ is well-defined. Assume that $\sum a_s\dl_s\in \N$. Then $\sum a_s\dl_{[s]}=0$ because the coefficient of $\dl_{[s]}$ equals $\sum_{t\in[s]}a_t$, which is zero by \cref{sum-s-in-C-a_s=0}. Clearly, $\Phi$ is surjective. Now,
	\begin{align*}
		\Phi(a\dl_s\cdot b\dl_t+\N)&=\Phi(\0_s(\0_{s\m}(a)b)\dl_{st}+\N) =\0_{s}(\0_{s\m}(a)b)\dl_{[st]}\\ &
		=\tl\0_{[s]}(\tl\0_{[s]\m}(a)b)\dl_{[st]}=a\dl_{[s]}\cdot b\dl_{[t]}=
		\Phi(a\dl_s+\N)\Phi( b\dl_t+\N).
	\end{align*} 
\end{proof}

\begin{cor}\label{cor:IsoPhi}
	 Suppose that $\0 $ is a unital action of an  $E$-unitary monoid $S$ on the algebra $A.$ Then $A\rtimes_\0 S\cong A\rtimes_{\tl\0} \cG(S)$ as $K$-algebras.
\end{cor}
\begin{proof}
	 Since any action of $S$ is compatible, Proposition~\ref{prop:SurjectivePhi} is applicable, and we  only need to prove that $\Phi$ is injective. Let $a=\sum a_s\dl_s$ such that $\Phi(a+\N)=0$. Then for any $\sg$-class $C$ we have $\sum_{s\in C}a_s=0$. Thus, $a\in \N$ by \cref{sum-a_s=0=>a-in-N}.
\end{proof}

\begin{rem}\label{rem:A-bimodule mapping}
	The mapping $\Phi:A\rtimes_\0 S\to A\rtimes_{\tl\0} \cG(S)$ from \cref{prop:SurjectivePhi} is also a morphism of $A$-bimodules.
\end{rem}
\begin{proof}
	Indeed, for all $a\in A$ and $b\in 1_sA$ we have
	\begin{align*}
		\Phi(a\cdot(b\dl_s+\N))&=\Phi(a\dl_{1}\cdot b\dl_s+\N)=\Phi(ab\dl_s+\N)=ab\dl_{[s]}\\
		&=a\dl_{[1]}\cdot b\dl_{[s]}=a\cdot\Phi(b\dl_s+\N),\\
		\Phi((b\dl_s+\N)\cdot a)&=\Phi(b\dl_s\cdot a\dl_1+\N)=\Phi(\0_s(\0_{s\m}(b)a)\dl_s+\N)=\0_{[s]}(\0_{[s]\m}(b)a)\dl_{[s]}\\
		&=b\dl_{[s]}\cdot a\dl_{[1]}=\Phi(b\dl_s+\N)\cdot a.
	\end{align*}
\end{proof}

