\subsection{$K S$ as skew group algebra for $E$-unitary $S$}


We know from~\cite[Theorem 3.17]{KL} (which is a reformulation of~\cite[Theorem 3.2]{Petrich-Reilly79}) that any $E$-unitary inverse semigroup $S$ is isomorphic to $E(S)\rtimes_\tau \cG(S)$, where $\tau$ is the partial action of $\cG(S)$ on $E(S)$ whose domains are $D_g=\{ss\m\mid s\in g\}$ for all $g\in\cG(S)$ and 
\begin{align}\label{tau_g(s-inv-s)=ss-inv}
	\tau_g(s\m s)=ss\m
\end{align}
for all $s\in g$. The isomorphism $\vf:S\to E(S)\rtimes_\tau \cG(S)$ maps $s\in S$ to 
\begin{align}\label{vf(s)=ss-inv.dl_[s]}
	\vf(s)=ss\m\dl_{[s]},
\end{align}
where $[s]$ is the $\sg$-class of $s$ in $S$ (see \cite[Theorem 3.2]{Petrich-Reilly79}). Clearly, $\vf$ extends by linearity to an isomorphism of $K$-algebras
\begin{equation}\label{eq:KS Iso1}
KS\to K(E(S)\rtimes_\tau \cG(S)).
\end{equation} 


 \begin{lem}\label{lem:tilde par action} With the notation above, for every  $g\in \cG(S)$ let $$\tilde{\tau}_g :  K D _{g\m} \to  K D _g $$ be the linear extension of $\tau_g.$ Then the collection 
 $\tilde{\tau}$ of the $K$-linear isomorphisms $\tilde{\tau}_g$ is a partial action of $\cG(S)$ on the commutative semigroup algebra  $K E(S).$
 \end{lem}
 \begin{proof} Observe that for every $g\in \cG(S)$ the semigroup algebra $K D _g $ has local units, i.e. for any 
  $a \in K D _g $ there exists an idempotent $e\in K D_g $
  such that $a = ae.$ Indeed,  write
 $a= \sum _i \lb _i s_is\m_i,$ where $\lb _i \in K,s_i \in g.$
 Then by Lemma~\ref{R=sum-orth-ideals}, the subalgebra of
 $K D _g ,$ generated by the idempotents $s_is\m_i$ has a unity element $e$ which is an idempotent element in $K D _g,$ so that $ae=a,$ as desired. Then for any $g,h \in \cG(S)$ we have that $K D _{g} \cap K D _h = K D_g D_h,$ and the fact that $\tau $ is a partial action of  $\cG(S)$ on $E(S)$ readily implies that $\tilde{\tau} $ is a partial action of $\cG(S)$ on $K E(S).$
 \end{proof}




In view of Lemma~\ref{lem:tilde par action} we may also consider the   obvious $K$-algebra isomorphism 
$$
K(E(S)\rtimes_\tau \cG(S))\cong (KE(S))\rtimes_{\tilde{\tau}} \cG(S).
$$
 The latter isomorphism acts as the identity map on the $K$-basis $\{e\dl_g\mid g\in \cG(S),\ e\in D_g\}$ of both $K(E(S)\rtimes_\tau \cG(S))$ and $(KE(S))\rtimes_{\tl\tau} \cG(S)$. Thus, composing it with \eqref{eq:KS Iso1}, we obtain a $K$-algebra isomorphism 
 $$
 KS\to (KE(S))\rtimes_{\tl\tau} \cG(S),\footnote{One can also obtain this isomorphism from \cref{cor:IsoPhi} by showing that $\tl\tau=\tl\0$ and $KS\cong (KE(S))\rtimes_\0 S$, where $\0$ is the natural action of $S$ on $KE(S)$.}
 $$ 
 sending $s$ to $ss\m\dl_{[s]}$, which is now seen as an element of $(KE(S))\rtimes_{\tl\tau} \cG(S)$. Let us denote this isomorphism by the same letter $\vf$, so that \cref{vf(s)=ss-inv.dl_[s]} holds.


\begin{lem}\label{KS-cong-KE(S)-rtimes-G(S)}
	The $K$-algebra isomorphism $\vf:KS\to (KE(S))\rtimes_{\tl\tau} \cG(S)$ is also an isomorphism of $KE(S)$-bimodules.
\end{lem}
\begin{proof}
	Let $e\in E(S)$ and $s\in S$. Since $[es]=[se]=[s]$, we have 
	\begin{align*}
		e\cdot\vf(s)&\overset{\cref{vf(s)=ss-inv.dl_[s]}}{=}e\dl_{[1]}\cdot ss\m \dl_{[s]}=ess\m \dl_{[s]}=(es)(es)\m\dl_{[s]}\overset{\cref{vf(s)=ss-inv.dl_[s]}}{=}\vf(es),\\
		\vf(s)\cdot e&\overset{\cref{vf(s)=ss-inv.dl_[s]}}{=}ss\m\dl_{[s]}\cdot e\dl_{[1]}=\tl\tau_{[s]}(\tl\tau\m_{[s]}(ss\m)e)\dl_{[s]}\overset{\cref{tau_g(s-inv-s)=ss-inv}}{=}\tl\tau_{[s]}(s\m se)\dl_{[s]}\\
		&=\tl\tau_{[s]}((se)\m (se))\dl_{[s]}\overset{\cref{tau_g(s-inv-s)=ss-inv}}{=}(se)(se)\m\dl_{[s]}\overset{\cref{vf(s)=ss-inv.dl_[s]}}{=}\vf(se).
	\end{align*}
\end{proof}

\cref{KS-cong-KE(S)-rtimes-G(S)} and \cite[Proposition 5.3]{DJ2} imply the following.

\begin{cor}\label{cor:KS pojective over KR(S)} Let $S$ be an $E$-unitary inverse semigroup. Then $K S$ is projective as a left 
$K E(S)$-module and as a right $K E(S)$-module.
\end{cor}







		\section{(Co)homology of an inverse monoid $S$ with values in a $K S$-module}\label{sec-(co)hom}
	Our study of homology and cohomology of the crossed product by an action of an inverse monoid on an algebra involves (co)homology of inverse monoids with values in a module over its semigroup algebra, which we introduce next. It is inspired by the concept of partial  group cohomology  defined in \cite{AAR} and that of  partial  group homology analogously defined in \cite{ADK}.



%	\subsection{Definition of  (co)cohomology}

	%	Let $S$ be an inverse monoid and $A$ a (left) $K$-module. We say that $A$ is a left \textit{$S$-module} if it is a (left) module over the semigroup algebra $K S$. Clearly, $S$-modules form an abelian category which we denote by $\smod$.


%	\begin{defn}
		 Given an inverse monoid $S$, there is a 
		left $K S$-module structure on $KE(S)$, defined by
		\begin{align}\label{left KS-mod KE(S)}
			s\cdot e=ses\m,
		\end{align}
		where $s\in S$ and $e\in E(S)$.	 Similarly, $KE(S)$ is a right $KS$-module by
		\begin{equation}\label{right KS-mod KE(S)}
			e \cdot s =  s\m e s.
		\end{equation} 

		This  $K S$-module will be called \textit{trivial}, because in the definition of the (co)homology below it appears in the place  usually occupied by the trivial module in the traditional sense.
%	\end{defn}

	 \begin{defn}\label{def:Inv Monoid (co)homol} 
    Let $S$ be  an inverse monoid. Given a left $K S$-module   $V$ and $n\in\bbN$\footnote{Here and below the set of natural numbers $\bbN$ includes zero.} we define the  \textit{$n$-th homology group of $S$ with values in $V$} by setting
    $$H_n(S,V)= \operatorname{Tor}^{K S}_n(K E(S), V). $$
     Analogously, the \textit{$n$-th cohomology group of $S$ with values in $V$} is
     \begin{align*}
			H^n(S,V) =\Ext^n_{KS}(KE(S),V).
		\end{align*}
	\end{defn}

%	\subsection{A projective resolution of the trivial $S$-module}
	Given an inverse monoid $S$ and $s\in S$, we write
	\begin{align*}
		\bd(s)&=s\m s\mbox{ and }\br(s)=ss\m.
	\end{align*}

	Since both $ \operatorname{Tor}$ and  
	$\operatorname{Ext}$ may be computed using projective resolutions of the first variable, we proceed by constructing one of the trivial left $K S$-module $K E(S).$
	\begin{defn}
		Let $S$ be an inverse monoid and $n\in \bbN $. We define the following sequence of projective (see \cite[Lemma 2.8]{DKS2}) left $K S$-modules:
		\begin{align*}
			P_0&=KS,\\
			P_n&=\bigoplus_{s_1,\dots,s_n\in S}KS\br(s_1\dots s_n),\ n> 0.
		\end{align*}
	\end{defn}
	As in \cite[Remark 2.10]{DKS2}, for $n>0$ one shows that $P_n$ is (isomorphic to) the free $K$-module with free basis
	\begin{align*}
		\{t(s_1,\dots,s_n)\mid t,s_1,\dots,s_n\in S,\ \bd(t)\le\br(s_1\dots s_n)\}.
	\end{align*}
	We shall identify the $n$-tuple $(s_1,\dots,s_n)$ with the element $\br(s_1\dots s_n)(s_1,\dots,s_n)$ of $P_n$, $n>0$. Thus, we may write $t(s_1,\dots,s_n)$ for \textit{arbitrary} $t,s_1,\dots,s_n\in S$, meaning $t\br(s_1\dots s_n)(s_1,\dots,s_n)\in P_n$. This does not lead to a confusion, because, whenever $t(s_1,\dots,s_n)\in P_n$, one has
	\begin{align}\label{eq:t=t range}
		t=t\br(s_1\dots s_n).
	\end{align}
	On the other hand, if we do not impose any condition on $t,s_1,\dots,s_n$ in $t(s_1,\dots,s_n)$, then we may have $t(s_1,\dots,s_n)=v(u_1,\dots,u_n)$ for $t\ne v$. More precisely,
	\begin{align*}
	t(s_1,\dots,s_n)=v(u_1,\dots,u_n)\iff
	\begin{cases}
	(s_1,\dots,s_n)=(u_1,\dots,u_n),\\
	t\br(s_1\dots s_n)=v\br(u_1\dots u_n).
	\end{cases}
	\end{align*}

	For uniformity, we also represent $P_0$ as the free $K$-module with free basis
	\begin{align*}
		\{t\emp\mid t\in S\}.
	\end{align*}

	\begin{defn}\label{d_n:P_n->P_(n+1)-defn}
		We define the following morphisms of left $KS$-modules $\cb_0:P_0\to KE(S)$ and $\cb_n:P_n\to P_{n-1}$, $n>0$:
		\begin{align}
		\cb_0(s\emp)&=\br(s),\ s\in S,\label{d_0(s())=ss^(-1)}\\
		\cb_1(t(s))&=t(s\emp-\emp),\ t(s)\in P_1,\notag
			\end{align}
			\begin{align}
		\cb_n(t(s_1,\dots,s_n))&=t(s_1(s_2,\dots,s_n)\notag\\
		&\quad+\sum_{i=1}^{n-1}(-1)^i(s_1,\dots,s_is_{i+1},\dots,s_n)\notag\\
		&\quad+(-1)^n(s_1,\dots,s_{n-1})),\label{cb_n(t(s_1...s_n)=...)}
		\end{align}	
		where $n>1$ and $t(s_1,\dots,s_n)\in P_n$.
	\end{defn}

	In order to prove that $\{P_n\}_{n\ge 0}$ is a projective resolution of $KE(S)$, we introduce the next.
	\begin{defn}\label{sigma_n-defn}
		We define the following morphisms of $K$-modules: $\s_{-1}:KE(S)\to P_0$ and $\s_n:P_n\to P_{n+1}$, $n\in \bbN $, where
		\begin{align}
		\s_{-1}(e)&=e\emp,\ e\in E(S),\label{sigma_(-1)(e)=e()}\\
		\s_0(s\emp)&=(s),\ s\in S,\notag\\
		\s_n(t(s_1,\dots,s_n))&=(t,s_1,\dots,s_n),\label{sigma_n(t(s_1...s_n))}
		\end{align}
		where $n>0$ and $t(s_1,\dots,s_n)\in P_n$.
	\end{defn}

	\begin{lem}
		The following equalities hold
		\begin{align}
		\cb_0\circ\s_{-1}&=\id_{KE(S)},\label{d_0-sigma_(-1)=id}\\
		\cb_{n+1}\circ\s_n+\s_{n-1}\circ\cb_n&=\id_{P_n},\ n\ge 0.\label{d_(n+1)-sigma_n+sigma_(n-1)-d_n=id}
		\end{align}
	\end{lem}
	\begin{proof}
		Equality \cref{d_0-sigma_(-1)=id} is an easy consequence of \cref{sigma_(-1)(e)=e(),d_0(s())=ss^(-1)}. Now, taking an arbitrary $s\in S$, we have
		\begin{align*}
			(\cb_1\circ\s_0+\s_{-1}\circ\cb_0)(s\emp)&=\cb_1(\br(s)(s))+\s_{-1}(\br(s))\\
			&=\br(s)(s\emp-\emp)+\br(s)\emp\\
			&=s\emp.
		\end{align*}
		Given $n>0$ and $t(s_1,\dots,s_n)\in P_n$, we observe, keeping in mind \eqref{eq:t=t range}, that $\br(ts_1\dots s_n)=\br(t).$  Then by \cref{sigma_n(t(s_1...s_n)),cb_n(t(s_1...s_n)=...)} we have
		\begin{align}
			(\cb_{n+1}\circ\s_n)(t(s_1,\dots,s_n))&=\cb_{n+1}(\br(t)(t,s_1,\dots,s_n))\notag\\
			&=\br(t)(t(s_1,\dots,s_n)-(ts_1,s_2,\dots,s_n)\notag\\
			&\quad+\sum_{i=1}^{n-1}(-1)^{i+1}(t,s_1,\dots,s_is_{i+1},\dots,s_n)\notag\\
			&\quad+(-1)^{n+1}(t,s_1,\dots,s_{n-1}))\notag\\
			&=t(s_1,\dots,s_n)-(ts_1,s_2,\dots,s_n)\notag\\
			&\quad+\sum_{i=1}^{n-1}(-1)^{i+1}(t,s_1,\dots,s_is_{i+1},\dots,s_n)\notag\\
			&\quad+(-1)^{n+1}(t,s_1,\dots,s_{n-1}).\label{cb_(n+1)s_n(t(s_1...s_n))}
		\end{align}
		Furthermore,
		\begin{align}
			(\s_{n-1}\circ\cb_n)(t(s_1,\dots,s_n))&=\s_{n-1}(t(s_1(s_2,\dots,s_n)\notag\\
			&\quad+\sum_{i=1}^{n-1}(-1)^i(s_1,\dots,s_is_{i+1},\dots,s_n)\notag\\
			&\quad+(-1)^n(s_1,\dots,s_{n-1})))\notag\\
			&=(ts_1,s_2,\dots,s_n)\notag\\
			&\quad+\sum_{i=1}^{n-1}(-1)^i(t,s_1,\dots,s_is_{i+1},\dots,s_n)\notag\\
			&\quad+(-1)^n(t,s_1,\dots,s_{n-1})),\label{s_(n-1)cb_n(t(s_1...s_n))}
		\end{align}
		because $ts_1(s_2,\dots,s_n),t(s_1,\dots,s_{n-1})\in P_{n-1}$ (the fact that $t(s_1,\dots,s_is_{i+1},\dots,s_n)\in P_{n-1}$ is obvious). Indeed,
		\begin{align*}
			\bd(ts_1)&=s\m_1\bd(t)s_1\le s\m_1\br(s_1\dots s_n)s_1=\bd(s_1)\br(s_2\dots s_n)\le\br(s_2\dots s_n),\\
			\bd(t)&\le\br(s_1\dots s_n)\le\br(s_1\dots s_{n-1}).
		\end{align*}
		Thus, adding \cref{s_(n-1)cb_n(t(s_1...s_n)),cb_(n+1)s_n(t(s_1...s_n))}, we obtain $t(s_1,\dots,s_n)$. 
	\end{proof}

	\begin{prop}\label{P_n-is-res-of-KE(S)}
		The sequence
		\begin{align}\label{...->P_1->P_0->KE(S)}
		\dots\arr{\cb_2}P_1\arr{\cb_1}P_0\arr{\cb_0} KE(S)\to 0
		\end{align}
		is a projective resolution of $KE(S)$ in the category of left $K S$-modules.
	\end{prop}
	\begin{proof}
		Indeed, \cref{...->P_1->P_0->KE(S)} is exact in $KE(S)$ in view of \cref{d_0-sigma_(-1)=id}. It also follows from \cref{d_(n+1)-sigma_n+sigma_(n-1)-d_n=id} that $\ker\cb_n\sst\im\cb_{n+1}$ for all $n\ge 0$. However, we cannot use \cref{d_(n+1)-sigma_n+sigma_(n-1)-d_n=id} to prove the converse inclusion, because $\s_n(P_n)$ does not generate $P_{n+1}$ as a $K S$-module. So, let us do this by a straightforward computation. Applying $\cb_n\circ\cb_{n+1}$ to a generator $(s_1,\dots,s_{n+1})$ of the $S$-module $P_{n+1}$, we obtain
		\begin{align}
			\cb_n\circ\cb_{n+1}(s_1,\dots,s_{n+1})&=\cb_n(\br(s_1\dots s_{n+1})(s_1(s_2,\dots,s_{n+1})\notag\\
			&\quad+\sum_{i=1}^n(-1)^i(s_1,\dots,s_is_{i+1},\dots,s_{n+1})\notag\\
			&\quad+(-1)^{n+1}(s_1,\dots,s_n)))\notag\\
			&=\br(s_1\dots s_{n+1})s_1\br(s_2\dots s_{n+1})(s_2(s_3,\dots,s_{n+1})\label{s_1(s_2(s_3...s_(n+1)))}\\
			&\quad+\sum_{j=2}^n(-1)^{j+1}(s_2,\dots,s_js_{j+1},\dots,s_{n+1})\label{sum(-1)^n(s_2...s_js_(j+1)...s_(n+1))}\\
			&\quad+(-1)^n(s_2,\dots,s_n))\label{(-1)^n(s_2...s_n)}\\
			&\quad+\sum_{i=1}^n(-1)^i\br(s_1\dots s_{n+1})\cb_n(s_1,\dots,s_is_{i+1},\dots,s_{n+1})\label{sum(-1)^icb_n(s_1...s_is_(i+1)...s_(n+1))}\\
			&\quad+(-1)^{n+1}\br(s_1\dots s_{n+1})\cb_n(s_1,\dots,s_n))).\label{(-1)^(n+1)cb_n(s_1...s_(n+1))}
		\end{align}
		Observe that $\br(s_1\dots s_{n+1})s_1=s_1\br(s_2\dots s_{n+1})$, so $\br(s_1\dots s_{n+1})s_1\br(s_2\dots s_{n+1})=\br(s_1\dots s_{n+1})s_1$ and
		\begin{align*}
			\br(s_1\dots s_{n+1})s_1\br(s_2\dots s_{n+1})s_2&=s_1\br(s_2\dots s_{n+1})s_2\\
			&=s_1s_2\br(s_3\dots s_{n+1})\\
			&=\br(s_1\dots s_{n+1})s_1s_2.
		\end{align*}
		It follows that the term \cref{s_1(s_2(s_3...s_(n+1)))} will be canceled with the first term of the expansion of the 1-st summand (corresponding to $i=1$) of \cref{sum(-1)^icb_n(s_1...s_is_(i+1)...s_(n+1))}; the $j$-th summand of \cref{sum(-1)^n(s_2...s_js_(j+1)...s_(n+1))} will be canceled with the first term of the expansion of the $j$-th summand (corresponding to $i=j$) of \cref{sum(-1)^icb_n(s_1...s_is_(i+1)...s_(n+1))}; and the term \cref{(-1)^n(s_2...s_n)} will be canceled with the first term of the expansion of \cref{(-1)^(n+1)cb_n(s_1...s_(n+1))}. The rest of the terms of \cref{sum(-1)^icb_n(s_1...s_is_(i+1)...s_(n+1)),(-1)^(n+1)cb_n(s_1...s_(n+1))} will be exactly the same as in the classical case, but multiplied by $\br(s_1\dots s_{n+1})$ on the left. Hence, they will also be canceled. Thus, $\cb_n\circ\cb_{n+1}=0$ proving $\im\cb_{n+1}\sst\ker\cb_n$.
	\end{proof}

	\begin{defn}\label{C^n_par(G_A)-defn}
		Given a left $K S$-module $V$ and $n\in \bbN$, we define the following $K$-modules
		\begin{align*}
		C^0(S,V)&=V,\\
		C^n(S,V)&=\{\s:S^n\to V\mid \s(s_1,\dots,s_n)\in \br(s_1\dots s_n)V\},\ n>0,
		\end{align*}
		and their morphisms $\dl^n:C^n(S,V)\to C^{n+1}(S,V)$:
		\begin{align}
		(\dl^0 x)(s)&=sx-\br(s)x,\ x\in C^0(S,V),\label{(dl^0m)(g)=...}\\
		(\dl^n\s)(s_1,\dots,s_{n+1})&=s_1\s(s_2,\dots,s_{n+1})\notag\\
		&\quad +\sum_{i=1}^n (-1)^i \s(s_1,\dots,s_is_{i+1},\dots,s_{n+1})\notag\\
		&\quad + (-1)^{n+1} \br(s_1\dots s_{n+1})\s(s_1,\dots,s_n),\ n>0,\ \s\in C^n(S,V).\label{(dl^nf)(g_1...g_n)=...}
		\end{align}
	\end{defn}

	\begin{prop}
		The sequence
		\begin{align}\label{C^0(S_A)->...}
		0\to C^0(S,V)\arr{\dl^0}C^1(S,V)\arr{\dl^1}\dots
		\end{align} 
		is a cochain complex of $K$-modules whose $n$-th cohomology $K$-module is isomorphic to $H^n(S,V)$.
	\end{prop}
	\begin{proof}
		The proof is similar to the proof of \cite[Lemma 2.16]{DKS2} and consists in showing that \cref{C^0(S_A)->...} is the result of application of the functor $\Hom_{KS}(-,V)$ to the projective resolution \cref{...->P_1->P_0->KE(S)}.
	\end{proof}

	\begin{defn}
		Let $V$ be a left $K S$-module and $n\in \bbN$. We introduce the following notations: $Z^n(S,V):=\ker{\dl^n}$, $n\ge 0$, and $B^n(S,V):=\im{\dl^{n-1}}$, $n>0$, where $\dl^n$ is given by \cref{(dl^0m)(g)=...,(dl^nf)(g_1...g_n)=...}.
	\end{defn}

	\begin{cor}
		Given  a left   $K S$-module $V$, we have $H^0(S,V)=Z^0(S,V)$ and $H^n(S,V)=Z^n(S,V)/B^n(S,V)$  for all $n\in\bbN$, $n>0$.
	\end{cor}

	\begin{exm}
		Let $V$ be a left $K S$-module. We have
		\begin{align*}
			Z^0(S,V)&=\{x \in V\mid \forall s\in S: sx=\br(s)x\},\\
			Z^1(S,V)&=\{\s\in C^1(S,V)\mid\forall s,t\in S:\ s\s(t)-\s(st)+\br(st)\s(s)=0\},\\
			B^1(S,V)&=\{\s\in C^1(S,V)\mid\exists x\in V\ \forall s\in S:\ \s(s)=sx-\br(s)x\},\\
			Z^2(S,V)&=\{\s\in C^2(S,V)\mid\forall s,t,u\in S:\ s\s(t,u)-\s(st,u)+\s(s,tu)-\br(stu)\s(s,t)=0\},\\
			B^2(S,V)&=\{\s\in C^2(S,V)\mid\exists \tau\in C^1(S,V)\ \forall s,t\in S:\ \s(s,t)=s\tau(t)-\tau(st)+\br(st)\tau(s)\}.
		\end{align*}
	\end{exm}

Similarly, for all $n\in\bbN$, we have the following projective right $KS$-modules:
	\begin{align*}
		P'_0&=KS,\\
		P'_n&=\bigoplus_{s_1,\dots,s_n\in S}K\bd(s_n\dots s_1)S,\ n>0.
	\end{align*}
It can be seen that, for all $n>0$, $P'_n$ is isomorphic to the free $K$-module with free basis
\begin{align*}
	\{(s_n,\dots,s_1)t\mid t,s_1,\dots,s_n\in S,\ \br(t)\le\bd(s_n\dots s_1)\}.
\end{align*}
Then, identifying $P'_0$ with the free $K$-module with free basis
\begin{align*}
	\{\emp t\mid t\in S\},
\end{align*}
and an $n$-tuple $(s_n,\dots,s_1)\in S^n$ with the element $(s_n,\dots,s_1)\bd(s_n\dots s_1)\in P'_n ,$
we can define the following morphisms of right $KS$-modules $\cb'_0:P'_0\to KE(S)$ and $\cb'_n:P'_n\to P'_{n-1}$, $n>0$:
\begin{align*}
	\cb'_0(\emp s)&=\bd(s),\ s\in S,\\
	\cb'_1((s)t)&=(\emp s-\emp)t,\ (s)t\in P'_1,\\
	\cb'_n((s_n,\dots,s_1)t)&=((s_n,\dots,s_2)s_1\notag\\
	&\quad+\sum_{i=1}^{n-1}(-1)^i(s_n,\dots,s_{i+1}s_i,\dots,s_1)\notag\\
	&\quad+(-1)^n(s_{n-1},\dots,s_1))t,
	%\ (s_n,\dots,s_1)t\in P'_n,\ n>1.
\end{align*}	 where $ (s_n,\dots,s_1)t\in P'_n,\ n>1.$
%In the above formulas we identify an $n$-tuple $(s_n,\dots,s_1)\in S^n$ with the element $(s_n,\dots,s_1)\bd(s_n\dots s_1)\in P'_n$.%
 It follows that
\begin{align}\label{...->P'_1->P'_0->KE(S)}
	\dots\arr{\cb'_2}P'_1\arr{\cb'_1}P'_0\arr{\cb'_0} KE(S)\to 0
\end{align}
	is a projective resolution of $KE(S)$ in the category of right $KS$-modules. 

	Let $V$ be a left $KS$-module. Applying the functor $-\ot_{KS}V$ to the sequence \cref{...->P'_1->P'_0->KE(S)} (with $KE(S)$ removed), we obtain the sequence of $K$-modules
\begin{align*}
	\dots\larr{\cb'_2\ot\id}P'_1\ot_{KS}V\larr{\cb'_1\ot\id}P'_0\ot_{KS}V\larr{\cb'_0\ot\id} 0,
\end{align*}
whose $n$-th homology $K$-module is $H_n(S,V)$, $n\in\bbN$. Observe that 
\begin{align*}
	P'_0\ot_{KS}V&=KS\ot_{KS}V\cong V,\\
	P'_n\ot_{KS}V&\cong\bigoplus_{s_1,\dots,s_n\in S}K\bd(s_n\dots s_1)S\ot_{KS}V\cong\bigoplus_{s_1,\dots,s_n\in S}\bd(s_n\dots s_1)V,\ n>0.
\end{align*}
We thus define the following $K$-modules:
\begin{align*}
	C'_0(S,V)&=V,\\
	C'_n(S,V)&=\left\{\sum_{i}(s_{n,i},\dots,s_{1,i})v_i\mid s_{1,i},\dots,s_{n,i}\in S,\ v_i\in\bd(s_{n,i}\dots s_{1,i})V\right\},\ n>0,
\end{align*}
and their morphisms $\dl'_n:C'_n(S,V)\to C'_{n-1}(S,V)$, $n>0$:
\begin{align*}
	\dl'_1((s)v)&=sv-v,\ (s)v\in C'_1(S,V),\\
	\dl'_n((s_n,\dots,s_1)v)&=(s_n,\dots,s_2)s_1v\\
	&\quad+\sum_{i=1}^{n-1}(-1)^i(s_n,\dots,s_{i+1}s_i,\dots,s_1)v\\
	&\quad+(-1)^n(s_{n-1},\dots,s_1)v,\ (s_n,\dots,s_1)v\in C'_n(S,V),\ n>1.
\end{align*}
Then set $Z_n(S,V):=\ker{\dl'_n}$, $n>0$, and $B_n(S,V):=\im{\dl'_{n+1}}$, $n\ge 0$.


\begin{cor}
	Given  a left $KS$-module $V$, we have $H_0(S,V)=V/B_0(S,V)$ and $H_n(S,V)=Z_n(S,V)/B_n(S,V)$, $n\in\bbN$, $n>0$.
\end{cor}

\begin{exm}
	Let $V$ be a left $KS$-module. We have
	\begin{align*}
		B_0(S,V)&=\left\{\sum (s_iv_i-v_i)\mid s_i\in S,\ v_i\in \bd(s_i)V\right\}\\
		&=\left\{\sum (s_iv_i-\bd(s_i)v_i)\mid s_i\in S,\ v_i\in V\right\},\\
		Z_1(S,V)&=\left\{\sum(s_i)v_i\in C'_1(S,V)\mid \sum (s_iv_i-v_i)=0\right\},\\
		B_1(S,V)&=\left\{\sum((s_{2,i})s_{1,i}v_i-(s_{2,i}s_{1,i})v_i+(s_{1,i})v_i)\mid(s_{2,i},s_{1,i})v_i\in C'_2(S,V), \forall i\right\},\\
		Z_2(S,V)&=\left\{\sum(s_{2,i},s_{1,i})v_i\in C'_2(S,V)\mid\sum((s_{2,i})s_{1,i}v_i-(s_{2,i}s_{1,i})v_i+(s_{1,i})v_i)=0\right\},\\
		B_2(S,V)&=\Big\{\sum((s_{3,i},s_{2,i})s_{1,i}v_i-(s_{3,i}s_{2,i},s_{1,i})v_i+(s_{3,i},s_{2,i}s_{1,i})v_i-(s_{2,i},s_{1,i})v_i)\mid\\
		&\quad\quad (s_{3,i},s_{2,i},s_{1,i})v_i\in C'_3(S,V),\forall i\Big\}.
	\end{align*}
\end{exm}





	\section{Homology of $A\rtimes_\0 S $}\label{sec:Homol}

	\subsection{Preparatory results}
 For an algebra $R$ over a commutative ring $K$ let $R^{\rm op}$ be its opposite algebra and denote by $R^e$ the en\-ve\-lo\-ping algebra $R \otimes _K R^{\rm op}.$ It is well-known that an $R$-bimodule $N$ is a left $R^e$-module and also a right $R^e$-module with the actions defined by 

 \begin{equation}\label{left right R^e-mod}
 (a\otimes _K b) \cdot x = a \cdot x \cdot b
 \;\;\;\; \text{and}\;\;\;\; 
 x \cdot (a\otimes _K b) = b \cdot x \cdot a,
\end{equation} $x \in N, a,b \in R.$

 The following easy property will be frequently used.

 \begin{lem}\label{lem:dentro fora}\cite[Lemma 2.15]{DJ1} Let  $N_1$ and $N_2$ be bimodules over a $K$-algebra $R.$ Then 
 \begin{equation}\label{dentro}
 x \cdot a \otimes _{R^e} y = x  \otimes _{R^e} a \cdot y,
  \end{equation} 

and 
  \begin{equation}\label{fora}
 a \cdot x \otimes _{R^e} y = x  \otimes _{R^e} y \cdot a,
  \end{equation} 
  for any $a\in R, x \in N_1, y\in N_2.$
 \end{lem}


\begin{rem}\label{rem:left R^e on (R')^e}
If $R$ is a  unital $K$-subalgebra  of a unital $K$-algebra $R' ,$   then there is the obvious   homomorphism of unital $K$-algebras 
$R^e \to (R') ^e,$ which sends $a\otimes _K b \in R^e$ to $a\otimes _K b \in (R')^e.$ This endows  $(R')^e$ with the structure of a left $R^e$-module given by 
\begin{equation}\label{eq:left R^e on (R')^e}
 (a\otimes _K b) \cdot (x \ot _K y) = ax \ot _K yb, 
\end{equation}
and with the structure of a right $R^e$-module defined by 
\begin{equation}\label{eq:right R^e on (R')^e}
  (x \ot _K y) \cdot  (a\otimes _K b) = xa \ot _K by, 
\end{equation}
where $a,b \in R$ and $x,y \in R'.$ Of course, this gives  $R$-bimodule structures on $(R') ^e.$ Obviously,  in the case of \eqref{eq:left R^e on (R')^e}  the right $R$-action on
$(R')^{\rm op}$ is given by the multiplication in $R',$ that is  $y\cdot b := yb.$ Thus  $(R')^{\rm op}$ and $R'$ are identical 
as right $R$-modules. Analogously, in the case of \eqref{eq:right R^e on (R')^e} the left $R$-modules  $(R')^{\rm op}$ and $R'$ are identical.


Evidently, we may replace the condition of $R$ being a $K$-subalgebra of $R'$ by the assumption of the existence of a $K$-algebra homomorphism $R \to R'.$ If $R \to R''$
is another  $K$-algebra homomorphism such that  the  $R$-bimodules
  $R'$ and $R''$  are isomorphic, then the left (right) $R^e$-modules 
$(R')^e$ and $(R'')^e$ are also isomorphic.
\end{rem}




As above, let $\0 =\{\0 _s : 1_{s\m}A \to 1_s A \}_{s\in S}  $ be a unital action of the inverse monoid $S$ on the algebra $A.$ Then   
$A$ becomes a left $KS$-module by means of the formula 
\begin{equation}\label{left KS-mod A}
s \cdot a = \0 _s (1_{s\m}a), \;\;\;\;\;\; s\in S, a \in A.
\end{equation}  For details see the proof of Theorem 3.7 in \cite{DK}, in particular, formula (9) in \cite{DK}.

For further use we  display the following obvious equality:

\begin{equation}\label{EmmanuelLemma(i)}
(s s\m) \cdot a  = \0_s (\0_{s\m} (1_s a))= 1_s a,
\end{equation} for any $a\in A.$ 


For $w \in L(A, \0 , S)$ we shall write   
$\overline{w} = w+ \N \in A\rtimes_\0 S .$




We proceed with the next easy but important for us fact.


\begin{lem}\label{lem:monoid hom} The mapping
\begin{equation}
\Gamma ^{\0} : S \to  A\rtimes_\0 S, \;\; s \mapsto \overline{1_s\delta_s},
\end{equation} is a homomorphism of monoids. 
\end{lem}
\begin{proof} It is enough to show that 
$$
\tilde{\Gamma} ^{\0} : S \to  L(A, \0 , S) , \;\; s \mapsto {1_s\delta_s},$$
 is a homomorphism of monoids. 
 Using \cref{theta on units} we have 
\begin{align*}
	\tilde{\Gamma} ^{\0} (s)  \tilde{\Gamma}^{\0} (t)&=
	 1_s\delta_s \cdot 1_t\delta_t  =  \0 _s (1_{s\m}1_t) \delta_{st} =
	1_{st} \delta_{st} = \tilde{\Gamma} ^{\0} (st),\\
	 \tl\Gamma^{\0}(1)& =1_A\dl_1=1_{L(A,\0,S)}.
\end{align*}



 \end{proof}

Let $M$ be an $A\rtimes_\0 S$-bimodule. Then it easily follows from Lemma~\ref{lem:monoid hom}  that $M$ has a structure of a left $KS$-module via 

\begin{equation}\label{left KS-mod M}
s \cdot x =  (\overline{1_s \delta_s}) \cdot  x \cdot (\overline{1_{s\m} \delta_{s\m}}),
\end{equation} for any $x\in M, s \in S.$ Symmetrically, $M$ is a right $KS$-module by means of 
\begin{equation*}
 x \cdot s =  (\overline{1_{s\m} \delta_{s\m}})  \cdot  x \cdot (\overline{1_s \delta_s}).
\end{equation*}  Furthermore, $M$ will be also considered as an $A$-bimodule with the actions defined by 
\begin{equation}\label{A-bimod M}
a \cdot x =  (\overline{a \delta_1}) \cdot  x  \;\;\; \mbox{and} \;\;\; x \cdot a = x \cdot (\overline{a \delta_1}),
\end{equation} $a\in A, x \in M.$

The following equality will be useful for us.
\begin{lem}\label{lemma:EmmanuelLemma(ii)} For any $s\in S, x \in M$ we have that
\begin{equation}\label{EmmanuelLemma(ii)}  
(ss\m )\cdot x = 1_s  x 1_s.
\end{equation} 
\end{lem} 
\begin{proof} Indeed, 
$$(ss\m )\cdot x \overset{\eqref{left KS-mod M}}{=}  
(\overline{1_s \delta_s})(\overline{1_{s^{-1}} \delta_{s^{-1}}}) \cdot x \cdot (\overline{1_s \delta_s})(\overline{1_{s^{-1}} \delta_{s^{-1}}})
 =  (\overline{1_s \delta_{ss\m}}) \cdot x \cdot 
 (\overline{1_s \delta_{ss\m}}).$$ Since $ss\m \leq 1_S$ we have  
 $1_{s} \delta _{1} - 1_{s} \delta _{ss\m}  \in {\mathcal N}, $
 so that $\overline{1_s \delta_{ss\m}} = \overline{1_s \delta_{1}},$ which implies that 
 $$(ss\m )\cdot x   =  (\overline{1_s \delta_{1}})   \cdot x \cdot 
 (\overline{1_s \delta_{1}}) \overset{\eqref{A-bimod M}}{=}   1_s x 1_s,$$ as desired.
 \end{proof}




\begin{prop}\label{prop:left KS-module A otimes M}
 The tensor product $A \otimes _{A^e} M$ is a left $KS$-module with the action 
\begin{equation}\label{left KS-module A otimes M}
s \cdot (a \otimes _{A^e} x) = s \cdot a \otimes _{A^e} s \cdot x,
\end{equation} $s \in S, a\in A, x \in M.$
\end{prop}
\begin{proof} Since $A$ and $M$ are left $KS$-modules via \cref{left KS-mod A,left KS-mod M}, we only need to check that \eqref{left KS-module A otimes M} is well-defined. For $s\in S$ consider the map 
$$f_s : A \times M \to A \otimes _{A^e} M, \;\;\; 
(a,x) \mapsto s \cdot a \otimes _{A^e} s \cdot x .$$ Then using Lemma \ref{lem:dentro fora} we see that
\begin{align*}
f_s(a\cdot (b \otimes _K c), x) & =  
s \cdot (a \cdot (b \otimes _K c)) \otimes _{A^e} s \cdot x
=  s \cdot (c  a b ) \otimes _{A^e} s \cdot x\\
& =  \0 _s   (1 _{s\m }c  a b ) \otimes _{A^e} s \cdot x
=    \0 _s  (1 _{s\m }c)  \0 _s   (1 _{s\m } a) \0 _s   (1 _{s\m } b)  \otimes _{A^e} s \cdot x\\
%& =  \0_s   (1 _{s\m }c)  \0 _s   (1 _{s\m } a) \0 _s   %(1 _{s\m } b) ) \otimes _{A^e} s \cdot x\\ 
&=   \0 _s   (1 _{s\m } a)   \otimes _{A^e} \0 _s   (1 _{s\m } b) \cdot (s \cdot x ) \cdot \0_s   (1 _{s\m }c)\\
&= s   \cdot  a  \otimes _{A^e} 
(\overline{\0 _s   (1 _{s\m } b) \delta_1}) \cdot ((\overline{1_s \delta_s }) \cdot  x \cdot (\overline{1_{s\m} \delta_{s\m}})) \cdot 
\overline{\0_s   (1 _{s\m }c) \delta _1}\\
&= s   \cdot  a   \otimes _{A^e} 
(\overline{\0 _s   (1 _{s\m } b)  \delta_s}) \cdot  x \cdot (\overline{c 1 _{s\m } \delta_{s\m}})\\
&=  s   \cdot  a    \otimes _{A^e} 
  (\overline{1 _{s }  \delta_s}) \cdot (( \overline{ b\delta_1} ) \cdot  x \cdot 
 ( \overline{c\delta _1})) \cdot (\overline{1 _{s\m } \delta_{s\m}})\\
 &= s   \cdot  a   \otimes _{A^e} 
  s \cdot (  b \cdot  x \cdot 
  c)
  = s   \cdot  a   \otimes _{A^e} 
  s \cdot (   (b \otimes _K c) \cdot  x )\\
  &= f_s(a,  (b \otimes _K c) \cdot x).
\end{align*} It follows that $f_s$ is balanced over $A^e$ and
there is a well-defined map
$$ A \otimes _{A^e }M \to A \otimes _{A^e} M, \;\;\; 
a  \otimes _{A^e} x \mapsto s \cdot a \otimes _{A^e} s \cdot x .$$  This yields  that \eqref{left KS-module A otimes M} is well-defined.
\end{proof}

With respect to the  left $KS$-module structure on 
 $A \otimes _{A^e} M$ the following property will be useful, which is an analogue of item (iv) of \cite[Lemma 5.7]{DJ2}.
 \begin{lem}\label{lemma:EmmanuelLemma(iv)} For any $e\in E(S)$,  $a\in A$ and $x \in M$ we have that
  $$ e  \cdot (a \otimes_{A^e} x) = a \otimes_{A^e} e \cdot x = e  \cdot a \otimes_{A^e}  x.$$
  Consequently, 
   $$\omega \cdot (a \otimes_{A^e} x) = \omega \cdot a \otimes_{A^e} x = a \otimes_{A^e} \omega \cdot x,$$ for all $\omega \in K E(S).$ 
 \end{lem}
 \begin{proof} Taking the trivial twist in the proof of item  (iv) of \cite[Lemma 5.7]{DJ2}, it can be easily adapted to the case of an inverse monoid action, using \eqref{left right R^e-mod}, Lemma~\ref{lem:dentro fora}, \eqref{EmmanuelLemma(i)} and \eqref{EmmanuelLemma(ii)}. \end{proof}


\begin{rem}\label{bimod map becomes KS-mod map} It is readily seen that a homomorphism $f : M \to N$ of $A\rtimes_\0 S$-bimodules becomes a mapping of left $KS$-modules in view of \eqref{left KS-mod M}. Then  thanks to  Proposition~\ref{prop:left KS-module A otimes M} it is readily seen that $A \otimes _{A^e} f : A \otimes _{A^e} M \to A \otimes _{A^e} N$ is a homomorphism of left $KS$-modules.
\end{rem}

Proposition~\ref{prop:left KS-module A otimes M} and Remark~\ref{bimod map becomes KS-mod map} allow us to define the following right exact functor
\begin{align}\label{functor-F_1-hom}
  F_1(-):= A \otimes_{A^e}-: (A\rtimes_\0 S)^e\textbf{-Mod} \to KS\textbf{-Mod}.
\end{align}

Recall that $KE(S)$ is a left $KS$-module with the action \cref{left KS-mod KE(S)} and a right $KS$-module with the action \cref{right KS-mod KE(S)}.
