The next fact is an analogue of \cite[Lemma 5.7, (iii)]{DJ2} for the case of inverse monoid actions. The proof is similar, but we include it for reader's convenience.

\begin{lem}\label{lemma:EmmanuelLemma(iii)} Let $X$ be a left $KS$-module. Then in $KE(S) \otimes_{KS} X$  we have that
\begin{equation*}
s s\m \otimes_{KS} x = 1 \otimes_{KS} s\m \cdot x = 1 \otimes_{KS} (s s\m) \cdot x,
\end{equation*}  for all $s \in S$ and $x \in X.$
\end{lem}
\begin{proof} Using \eqref{right KS-mod KE(S)} we have that 
	\begin{align*}
		s s\m \otimes_{KS} x &= (1 \cdot s\m) \otimes_{KS} x = 1  \otimes_{KS} s\m \cdot x,\\
		s s\m \otimes_{KS} x &= 1\cdot (s s\m) \otimes_{KS} x=
		1    \otimes_{KS}  (s  s\m) \cdot x, 
	\end{align*}
as desired.
 \end{proof}


 With the right $KS$-action  \eqref{right KS-mod KE(S)}, we consider the right exact functor
\begin{align}\label{functor-F_2-hom}
   F_2(-): = KE(S) \otimes_{KS}-: KS \textbf{-Mod} \to K\textbf{-Mod}. 
\end{align}
We also need the  functor 
\begin{align}\label{functor-F-hom}
   F(-) := (A\rtimes_\0 S) \otimes_{(A\rtimes_\0 S)^e}-: (A\rtimes_\0 S)^e\textbf{-Mod} \to K\textbf{-Mod},
\end{align} 
whose  left-derived functor gives the Hochschild homology of
$A\rtimes_\0 S.$ 

Thanks to Lemma~\ref{lem:monoid hom}, $A\rtimes_\0 S$ is a left $KS$-module via $s \cdot \overline{a \delta _t} = \Gamma ^{\0} (s) \; \overline{ a \delta _t}  = \overline{1_s \delta _s \cdot a\delta _t},$ that is 
\begin{equation}\label{left KS-action on cross}
s \cdot \overline{a \delta _t} 
=  \overline{\0_s (1_{s\m} a ) \delta _{st}}.
\end{equation} In particular, $A\rtimes_\0 S$ is a left $K E(S)$-module with
\begin{equation}\label{left KE(S)-action on cross}
(s s\m) \cdot \overline{a \delta _t}   = 
\overline{1_s  a \delta _t}.
\end{equation} Since any idempotent of $S$ is of the form $s s\m, $ with $s\in S,$ the equality \eqref{left KE(S)-action on cross} determines a left
$K E(S)$-action on  $A\rtimes_\0 S.$

Note that $A\rtimes_\0 S$ may be considered as an $A\rtimes_\0 S$-bimodule, but  the left $K S$-action \eqref{left KS-action on cross} on $A\rtimes_\0 S$ differs from the left $K S$-action \eqref{left KS-mod M}. In all what follows we shall consider \eqref{left KS-action on cross} as a left action of $KS$ on $A\rtimes_\0 S.$

We shall need the following.


\begin{lem} \label{prop:bimodule structure X tensor cross}
	Let $X$ be a right $K S$-module. Then the actions 
	\begin{equation}\label{left crossprod-action}
		\overline{a \delta_s} \cdot (x \otimes_{K E(S)} 
		\overline{c \delta_t}) = x \cdot s^{-1} \otimes_{K E(S)} (\overline{a \delta_s})(\overline{c \delta_t})
	\end{equation}
	and
	\begin{equation} \label{right crossprod-action}
		(x \otimes_{K E(S)} \overline{c \delta_t}) \cdot \overline{a \delta_s} = x \otimes_{K E(S)} (\overline{c \delta_t}) (\overline{a \delta_s}).
	\end{equation}
	give an  $A\rtimes_\0 S$-bimodule structure on  
	$X \otimes_{K E(S)} (A\rtimes_\0 S).$
\end{lem}

\begin{proof} Obviously, the structure of a right $A\rtimes_\0 S$-module is well-defined. As to the left action we check first that 
 $X \otimes_{K E(S)} (A\rtimes_\0 S ) $ is a left $L(A, \0 , S)$-module
 via 
 \begin{equation*}
a \delta_s \cdot (x \otimes_{K E(S)} 
\overline{c \delta_t}) = x \cdot s^{-1} \otimes_{K E(S)} (\overline{a \delta_s})(\overline{c \delta_t}).
        \end{equation*}
For any fixed $a \delta_s\in L(A, \0 , S)$ let
       $$ 
       \tilde{\psi }_{a \delta_s}: X \times (A\rtimes_\0 S) \to X \otimes_{ K E(S)} A\rtimes_\0 S
       $$ 
       be defined by   
        $$ 
        \tilde{\psi}_{a \delta_s}(x, \overline{c\delta_t}) = 
        x \cdot s^{-1} \otimes_{K E(S)}\overline{(a \delta_s)(c \delta_t)}.
         $$
   We check that $ \tilde{\psi }_{a \delta_s}$  is balanced over $K E(S).$ Indeed, for any $ t \in S$ and $c \delta _v \in   L(A, \0 , S)$ we compute 
    \begin{align*}
        \tilde{\psi}_{a \dl_s}(x \cdot (t t\m), \overline{c\dl_v})
        &= (x \cdot  (t t\m) ) \cdot {  s^{-1} } \otimes_{K E(S)} \overline{(a \dl_s)(c \dl_v)} \\
        &= (x \cdot  (t t\m s\m s s\m) \otimes_{K E(S)} \overline{ (a \dl_s)(c \dl_v) } \\  
        &= (x \cdot  s^{-1})\cdot (st t\m s\m) \otimes_{K E(S)} \overline{ (a \dl_s)(c \dl_v)} \\ 
        &= x \cdot  s^{-1}  \otimes_{K E(S)} (st t\m s\m)  \cdot \left(\overline{(a \dl_s)(c \dl_v)}\right) \\ 
        &\overset{\eqref{left KE(S)-action on cross}}{=}  x \cdot {  s^{-1} } \otimes_{K E(S)} \overline{ (1_{st} a \dl_s)(c \dl_v)} \\
        &\overset{\eqref{theta on units}}{=} x \cdot {  s^{-1} } \otimes_{K E(S)} \overline{(a \dl_s)(1_t \dl_1)(c \dl_v)} \\
        &\overset{\eqref{left KE(S)-action on cross}}{=} x \cdot {  s^{-1} } \otimes_{K E(S)} \overline{(a \dl_s)}\left({ (t t\m)} \cdot \overline{(c \dl_v)}\right) \\
        &= \tilde{\psi}_{a \dl_s}(x , { (t t\m)} \cdot  \overline{c\dl_v}).
    \end{align*}
    Hence, we have a well-defined mapping 
    \[
        \psi_{a \delta_s}: X \otimes_{K E(S)}  (A\rtimes_\0 S)  \to X \otimes_{K E(S)} (A\rtimes_\0 S )   
    \]
    determined by 
    \[
        \psi_{a \delta_s}(x \otimes_{K E(S)} \overline{c\delta_t}) = x \cdot s^{-1} \otimes_{K E(S)} \overline{(a \delta_s) (c \delta_t)}
    \]
     for all $s \in S$ and  $a \in 1_s A$.  Then it can be directly verified that 
      $$ 
      \psi_{a \dl_s} (\psi_{b \dl_t}(x \otimes_{K E(S)} \overline{c\dl_v})) = \psi_{(a \dl_s )(b \dl_t)}(x \otimes_{K E(S)} \overline{c\dl_v}) 
      $$
      for all $s, t, v \in S,$ $ a\in 1_sA$, $b\in 1_tA$, $c\in 1_vA$ and $x\in X,$
 so that    we obtain     a left 
 $ L(A, \0 , S)$-module structure on $X \otimes_{K E(S)} (A\rtimes_\0 S),$ by setting
 $$ 
 a \dl_s \cdot (x \otimes_{K E(S)} \overline{c\dl_t}) =  \psi_{a \dl_s}(x \otimes_{K E(S)} \overline{c\dl_t}).
 $$

 Observe now that 
 $${\mathcal N} \cdot ( X \otimes_{K E(S)} (A\rtimes_\0 S))=0. $$
 Indeed, let $s,t \in S$ be such that $s \leq t$ and let $a \in 1_sA.$ Then $1_sA \subseteq 1_t A,$ 
 $\overline{a \delta _s}= \overline{a \delta _t} ,$  $s = s s\m t$ and for any $x \in X,$ $c\in 1_vA$ we see that
 \begin{align*}
 	a \dl _s \cdot (x \ot_{K E(S)} \ol{c \dl_v}) 
 	& =  x \cdot s^{-1} \ot_{K E(S)} (\ol{a \dl_s}) (\ol{c \dl_v})\\
 	&=  x \cdot (ss\m t)^{-1} \ot_{K E(S)} (\ol{a \dl_t}) (\ol{c \dl_v})\\
 	&=  x \cdot t^{-1} \ot_{K E(S)} (ss\m )\cdot (\ol{a \dl_t}) (\ol{c \dl_v})\\
 	&\overset{\eqref{left KE(S)-action on cross}}{=}
 	x \cdot t^{-1} \ot_{K E(S)} (\ol{1_{s}  a \dl_t}) (\ol{c \dl_v})\\
 	& = x \cdot t^{-1} \ot_{K E(S)} (\ol{a \dl_t}) (\ol{c \dl_v})\\
 	&=a \delta _t  \cdot (x \otimes_{K E(S)} \overline{c\delta_v}),
 \end{align*}
% \begin{align*}
% &(a \delta _s - a \delta _t) \cdot (x \otimes_{K E(S)} \overline{c \delta_v})
% = a \delta _s  \cdot (x \otimes_{K E(S)} \overline{c\delta_v}) -
%   a \delta _t  \cdot (x \otimes_{K E(S)} \overline{c\delta_v})\\
%   & =  x \cdot s^{-1} \otimes_{K E(S)} (\overline{a \delta_s}) (\overline{c \delta_v}) -  
%   x \cdot t^{-1} \otimes_{K E(S)} (\overline{a \delta_t}) (\overline{c \delta_v})\\
%   &=  x \cdot (ss\m t)^{-1} \otimes_{K E(S)} (\overline{a \delta_t}) (\overline{c \delta_v}) -  
%   x \cdot t^{-1} \otimes_{K E(S)} (\overline{a \delta_t}) (\overline{c \delta_v})\\
%    &=  x \cdot t^{-1} \otimes_{K E(S)} (ss\m )\cdot (\overline{a \delta_t}) (\overline{c \delta_v}) -  
%   x \cdot t^{-1} \otimes_{K E(S)} (\overline{a \delta_t}) (\overline{c \delta_v})\\
%   &\overset{\eqref{left KE(S)-action on cross}}{=}
%   x \cdot t^{-1} \otimes_{K E(S)} (\overline{1_{s}  a \delta_t}) (\overline{c \delta_v}) -  
%   x \cdot t^{-1} \otimes_{K E(S)} (\overline{a \delta_t}) (\overline{c \delta_v})\\
%   & =  x \cdot t^{-1} \otimes_{K E(S)} (\overline{a \delta_t}) (\overline{c \delta_v}) -  
%   x \cdot t^{-1} \otimes_{K E(S)} (\overline{a \delta_t}) (\overline{c \delta_v})=0,
% \end{align*} 
 since $a \in 1_s A.$
  Consequently, $(a\dl_s-a\dl_t) \cdot (x \ot_{K E(S)} \ol{c \dl_v})=0$, and the left $ L(A, \0 , S)$-action on $X \otimes_{K E(S)} (A\rtimes_\0 S)$ induces a left  $A\rtimes_\0 S$-module structure on  $X \otimes_{K E(S)} (A\rtimes_\0 S)$ determined by
 \eqref{left crossprod-action}. 

  Finally, it is readily seen  that the actions \eqref{left crossprod-action} and \eqref{right crossprod-action} commute, providing an $A\rtimes_\0 S$-bimodule structure on 
 $X \otimes_{K E(S)} (A\rtimes_\0 S).$ 
     \end{proof}

     It evidently follows from \eqref{left crossprod-action} and \eqref{right crossprod-action} that if $f : X \to X'$ is a homomorphism of right $KS$-modules, then
     \begin{align*}
     	f \otimes_{K E(S)} (A\rtimes_\0 S): X \otimes_{K E(S)} (A\rtimes_\0 S) \to X' \otimes_{K E(S)} (A\rtimes_\0 S)
     \end{align*}
     is a homomorphism of $A\rtimes_\0 S$-bimodules. Therefore, by  Lemma~\ref{prop:bimodule structure X tensor cross} we may consider the functor 
     $$
     - \otimes_{K E(S)} (A\rtimes_\0 S): \textbf{Mod-}K S \to (A\rtimes_\0 S)^e\textbf{-Mod}.
     $$





As in \cite{DJ2}, in order to obtain the homology spectral sequence we shall use a  result by A. Grothendieck 
\cite[Theorem 10.48]{Rotman}, for which we will need to show that the composition $F_2 F_1$ is naturally isomorphic to $F$ and that $F_1(P)$ is right $F_2$-acyclic for any projective $A\rtimes_\0 S $-bimodule $P$ (the latter means any projective object in $(A\rtimes_\0 S)^e\textbf{-Mod} $). For this purpose we shall use the next proposition, which is an inverse semigroup analogue of
\cite[Proposition 5.10]{DJ2}. 





\begin{prop} \label{prop:bifunctor iso}
    There is a natural isomorphism of the bifunctors
    \[
        -\otimes_{K S} (A \otimes_{A^e} - ): \rMod K S \times  (A\rtimes_\0 S)^e \Mod \to K\Mod
    \]
    and
    \[
        (- \otimes_{K E(S)} (A\rtimes_\0 S)) \otimes_{(A\rtimes_\0 S)^e}-: \rMod KS \times (A\rtimes_\0 S)^e \Mod \to K\Mod.
    \]  
\end{prop}

\begin{proof}
    Take  a right $K S$-module $X$ and an $(A\rtimes_\0 S)^e$-module $M.$ Fixing  $x \in X ,$ consider the mapping
    \begin{align*}
         A \times M & \to (X \otimes_{K E(S)} (A\rtimes_\0 S))  \otimes_{(A\rtimes_\0 S)^e}M,\\
        (a,m) & \mapsto (x \otimes_{K E(S)} \overline{1_A \delta_1}) \otimes_{(A\rtimes_\0 S)^e} a \cdot m,
    \end{align*}
    which, using Lemma~\ref{lem:dentro fora}, can be directly  verified to be $A^e$-balanced (see also the proof of \cite[Proposition 5.10]{DJ2}). Thus we have the following  well-defined function
    \begin{align*}
        \xi _{x,M}: A \otimes_{A^e} M & \to (X \otimes_{K E(S)} (A\rtimes_\0 S))  \otimes_{(A\rtimes_\0 S)^e}M, \\ 
        a \otimes_{A^e} m &\mapsto (x \otimes_{K E(S)} 
        \overline{1_A \delta_1}) \otimes_{(A\rtimes_\0 S)^e} a \cdot m.
    \end{align*} 
    Varying $x\in X ,$ consider the mapping
    \begin{align*}
        \tilde{\xi}_{(X,M)} : X \times (A\otimes_{A^e}M) & \to (X \otimes_{K E(S)}( A\rtimes_\0 S))  \otimes_{(A\rtimes_\0 S)^e}M, \\ 
        (x,a\otimes_{A^e} y) &\mapsto \xi _{x,M}(a\otimes_{A^e}y)=(x \otimes_{K E(S)} \overline{1_A \delta_1}) \otimes_{(A\rtimes_\0 S)^e} a \cdot y.
    \end{align*}
    In order  to show that  $\tilde{\xi }_{(X,M)}$ is $K S$-balanced, notice first that by \cref{1_(ss-inv)=1_s} we have $1_{s\m}=1_{ s\m s}$, and $s\m  s \leq 1$ implies
    $\overline{1_{s\m } \delta _{s\m s}} = \overline{1_{s\m } \delta _1} .$ Then for $s\in S$ and $x\in X$
     we see that
    \begin{align}
    	x \cdot s \ot_{K E(S)} \ol{1_A \dl_1}
    	&= x \cdot s (s\m s)  \ot_{K E(S)} \ol{1_A \dl_1} 
    	= x \cdot s \ot_{K E(S)} (s^{-1}s) \cdot (\ol{1_A \dl_1})\notag\\ 
    	&\overset{\eqref{left KE(S)-action on cross}}{=} x \cdot s \ot_{K E(S)} \ol{1_{s^{-1}}\dl_1} 
    	= x \cdot s \ot_{K E(S)} \ol{1_{s^{-1}}\dl_{s\m s}}\notag\\ 
    	&= x \cdot s \ot_{K E(S)} (\ol{1_{s^{-1}} \dl_{s^{-1}}})(\ol{1_s \dl_s})\notag \\ 
    	&\overset{\eqref{left crossprod-action}, \eqref{right crossprod-action}}{=}  (\ol{1_{s^{-1}} \dl_{s^{-1}}}) \cdot \big(x \ot_{K E(S)}\ol{1_A \dl_1} \big) \cdot (\ol{1_s \dl_s }). \label{xs-ot-1_A.dl_1}
  \end{align}
  Furthermore, for all $a \in A$ and $y \in M$ we have
  \begin{align}
    	(\ol{1_s \dl_s}) \cdot (a \cdot y) \cdot (\ol{1_{s\m} \dl_{s^{-1}}})&\overset{\eqref{A-bimod M}}{=}(\ol{1_s \dl_s})(\ol{a \dl_1}) \cdot y \cdot (\ol{1_{s\m} \dl_{s^{-1}}}) \notag\\ 
    	&= (\ol{\theta_s(1_{s^{-1}}a)\dl_s}) \cdot y \cdot (\ol{1_{s\m} \dl_{s^{-1}}}) \notag\\
    	&= (\ol{\theta_s(1_{s^{-1}}a) \dl_1}) (\ol{1_{s} \dl_s}) \cdot y \cdot (\ol{1_{s\m} \dl_{s^{-1}}}) \notag\\
    	& \overset{\eqref{left KS-mod M}}{=}(\ol{\theta_s(1_{s^{-1}}a) \dl_1}) ( s \cdot y) 
    	\overset{\eqref{left KS-mod A}}{=}((\ol{s \cdot a)\dl_1}) \cdot (s \cdot y).\label{1_s.dl_s(ay)1_(s-inv).dl_(s-inv)}
    \end{align}
It follows that
    \begin{align*}
    	\tilde{\xi}_{(X,M)}(x \cdot s,a\ot_{A^e}y) 
    	&= (x \cdot s \ot_{K E(S)} \ol{1_A \dl_1}) \ot_{(A\rtimes_\0 S)^e} a \cdot y \\
    	&\overset{\cref{xs-ot-1_A.dl_1}}{=} (\ol{1_{s^{-1}} \dl_{s^{-1}}}) \cdot \big(x \ot_{K E(S)}\ol{1_A \dl_1} \big) \cdot (\ol{1_s \dl_s })\ot_{(A\rtimes_\0 S)^e} a \cdot y \\
    	&\overset{\eqref{dentro},\eqref{fora}}{=}  \big(x \ot_{K E(S)}\ol{1_A \dl_1} \big) \ot_{(A\rtimes_\0 S)^e} (\ol{1_s \dl_s}) \cdot (a \cdot y) \cdot (\ol{1_{s\m} \dl_{s^{-1}}}) \\ 
    	&\overset{\cref{1_s.dl_s(ay)1_(s-inv).dl_(s-inv)}}{=}\big(x \ot_{K E(S)}\ol{1_A \dl_1} \big) \ot_{(A\rtimes_\0 S)^e} ((\ol{s \cdot a)\dl_1}) \cdot (s \cdot y)  \\ 
    	&= \tilde{\xi}_{(X,M)}(x , (s \cdot a)\ot_{A^e}(s \cdot y)) 
    	\overset{\eqref{left KS-module A otimes M}}{=} \tilde{\xi}_{(X,M)}(x ,s \cdot (a\ot_{A^e}y)),
    \end{align*}    
%     \begin{align*}
%        \tilde{\xi}_{(X,M)}(x \cdot s,a\otimes_{A^e}y) 
%        &= (x \cdot s \otimes_{K E(S)} \overline{1_A \delta_1}) \otimes_{(A\rtimes_\0 S)^e} a \cdot y \\
%        &= (x \cdot s (s\m s)  \otimes_{K E(S)} \overline{1_A \delta_1}) \otimes_{(A\rtimes_\0 S)^e} a \cdot y \\ 
%        &= (x \cdot s \otimes_{K E(S)} (s^{-1}s) \cdot (\overline{1_A \delta_1})) \otimes_{(A\rtimes_\0 S)^e} a \cdot y \\ 
%        &\overset{\eqref{left KE(S)-action on cross}}{=} \big(x \cdot s \otimes_{K E(S)} \overline{1_{s^{-1}}\delta_1} \big) \otimes_{(A\rtimes_\0 S)^e} a \cdot y \\ 
%        &=  \big(x \cdot s \otimes_{K E(S)} \overline{1_{s^{-1}}\delta_{s\m s}} \big) \otimes_{(A\rtimes_\0 S)^e} a \cdot y \\ 
%        &= \big(x \cdot s \otimes_{K E(S)} (\overline{1_{s^{-1}} \delta_{s^{-1}}})(\overline{1_s \delta_s}) \big)\otimes_{(A\rtimes_\0 S)^e} a \cdot y \\ 
%        &\overset{\eqref{left crossprod-action}, \eqref{right crossprod-action}}{=}  (\overline{1_{s^{-1}} \delta_{s^{-1}}}) \cdot \big(x \otimes_{K E(S)}\overline{1_A \delta_1} \big) \cdot (\overline{1_s \delta_s })\otimes_{(A\rtimes_\0 S)^e} a \cdot y \\ 
%        &\overset{\eqref{dentro},\eqref{fora}}{=}  \big(x \otimes_{K E(S)}\overline{1_A \delta_1} \big) \otimes_{(A\rtimes_\0 S)^e} (\overline{1_s \delta_s}) \cdot (a \cdot y) \cdot (\overline{1_{s\m} \delta_{s^{-1}}}) \\ 
%        &\overset{\eqref{A-bimod M}}{=}  \big(x \otimes_{K E(S)} \overline{1_A \delta_1} \big) \otimes_{(A\rtimes_\0 S)^e} (\overline{1_s \delta_s})(\overline{a \delta_1}) \cdot y \cdot (\overline{1_{s\m} \delta_{s^{-1}}}) \\ 
%        &=  \big(x \otimes_{K E(S)} \overline{1_A \delta_1} \big) \otimes_{(A\rtimes_\0 S)^e} (\overline{\theta_s(1_{s^{-1}}a)\delta_s}) \cdot y \cdot (\overline{1_{s\m} \delta_{s^{-1}}}) \\
%        &=  \big(x \otimes_{K E(S)} \overline{1_A \delta_1 } \big) \otimes_{(A\rtimes_\0 S)^e} (\overline{\theta_s(1_{s^{-1}}a) \delta_1}) (\overline{1_{s} \delta_s}) \cdot y \cdot (\overline{1_{s\m} \delta_{s^{-1}}}) \\
%        & \overset{\eqref{left KS-mod M}}{=} \big(x \otimes_{K E(S)} \overline{1_A \delta_1} \big) \otimes_{(A\rtimes_\0 S)^e} (\overline{\theta_s(1_{s^{-1}}a) \delta_1}) ( s \cdot y) \\
%        &\overset{\eqref{left KS-mod A}}{=} \big(x \otimes_{K E(S)}\overline{1_A \delta_1} \big) \otimes_{(A\rtimes_\0 S)^e} ((\overline{s \cdot a)\delta_1}) \cdot (s \cdot y)  \\ 
%        &= \tilde{\xi}_{(X,M)}(x , (s \cdot a)\otimes_{A^e}(s \cdot y)) \\
%        &\overset{\eqref{left KS-module A otimes M}}{=} \tilde{\xi}_{(X,M)}(x ,s \cdot (a\otimes_{A^e}y)),
%    \end{align*}
    as desired. Consequently, we obtain the following   well-defined
    mapping
    \begin{align*}
        \xi _{(X,M)} : X \otimes_{K S} (A\otimes_{A^e}M) & \to (X \otimes_{K E(S)} (A\rtimes_\0 S))  \otimes_{(A\rtimes_\0 S)^e}M, \\ 
        x \otimes_{K S} (a\otimes_{A^e} y) &\mapsto (x \otimes_{K E(S)} \overline{1_A \delta_1}) \otimes_{(A\rtimes_\0 S)^e} a \cdot y.
    \end{align*}



    We are going to produce an inverse  of $   \xi _{(X,M)}.$  Fix  $m \in M$ and define the mapping
    \begin{align*}
        \tilde{\eta}_{X,m}: X \times  (A\rtimes_\0 S)  & \to  X \otimes_{K S} (A\otimes_{A^e}M), \\ 
        (x, \overline{a \dl_t})&\mapsto x \otimes_{K S}(1_A \otimes_{A^e} (\overline{a \dl_t}) \cdot m).
    \end{align*}
    Then   $\tilde{\eta}_{X,m}$ is $K E(S)$-balanced. Indeed,
    \begin{align*}
        \tilde{\eta}_{X,m}(x \cdot (s s\m ) , a \dl_t)    &=  x \cdot (s s\m )  \otimes_{K S}(1_A \otimes_{A^e} (\ol{a \dl_t}) \cdot m) \\
        &=  x \otimes_{K S} (s s\m)   \cdot (1_A \otimes_{A^e} (\ol{a \dl_t}) \cdot m) \\
        (\text{by Lemma~\ref{lemma:EmmanuelLemma(iv)}} )&=  x \otimes_{K S} \big( 1_A \otimes_{A^e} s s\m \cdot( (\ol{a \dl_t}) \cdot m) \big)  \\
        &\overset{\eqref{EmmanuelLemma(ii)}}{=}  x \otimes_{K S} \big( 1_A \otimes_{A^e} 1_s ( (\ol{a \dl_t}) \cdot m) 1_s \big)  \\ 
        &= x \ot_{K S} \big(1_s 1_A 1_s \ot_{A^e}  (\ol{a \dl_t}) \cdot m \big) \\
        &= x \ot_{K S} \big(1_A 1_s \ot_{A^e}  (\ol{a \dl_t}) \cdot m \big) \\
        &\overset{\cref{dentro}}{=} x \ot_{K S} \big(1_A \ot_{A^e}  1_s((\ol{a \dl_t}) \cdot m) \big) \\
        &\overset{\cref{A-bimod M}}{=} x \ot_{K S} \big(1_A \ot_{A^e}  \ol{1_s\dl_1}((\ol{a \dl_t}) \cdot m) \big) \\
        %&=  x \otimes_{K S} \big(  1_A 1_s \otimes_{A^e}  (\ol{1_s \red{a} \dl_t}) \cdot m \big) \\
        %&\overset{\eqref{dentro}}{=}  x \otimes_{K S} \big( 1_A  \otimes_{A^e}  (\ol{1_s \red{a} \dl_t}) \cdot m \big)  \\
        &= x \otimes_{K S} \big(  1_A \otimes_{A^e}  (\ol{1_s a \dl_t}) \cdot m \big) \\
        &=\tilde{\eta}_{X,m}(x, \ol{1_s a \dl_t}) \overset{\eqref{left KE(S)-action on cross}}{=}\tilde{\eta}_{X,m}(x, (s s\m) \cdot (\ol{a \dl_t})).
    \end{align*}
    Thus we obtain the following   well-defined mapping
    \begin{align*}
        \eta _{X,m}: X \otimes_{K E(S)} (A\rtimes_\0 S) & \to  X \otimes_{K S} (A\otimes_{A^e}M),\\ 
        x \otimes_{K E(S)} \overline{a \dl_t} &\mapsto x \otimes_{K S}(1_A \otimes_{A^e} (\overline{a \dl_t})\cdot m).
    \end{align*}
    Then we may  consider the  mapping
    \begin{align*}
        \tilde{\eta}_{(X,M)}: (X \otimes_{K E(S)} (A\rtimes_\0 S))  \times M  & \to  X \otimes_{K S} (A\otimes_{A^e}M),\\ 
        (x \otimes_{K E(S)} \overline{a \dl_t}, m) &\mapsto \eta _{X,m}(x \otimes_{K E(S)} \overline{a \dl_t})=x \otimes_{K S}(1_A \otimes_{A^e} (\overline{a \dl_t}) \cdot m).
    \end{align*}
    Let us see that $ \tilde{\eta}_{(X,M)}$ is 
    $(A\rtimes_\0 S)^e$-balanced. On the one hand,
    \begin{align*}
        \tilde{\eta}_{(X,M)}((x \ot_{K E(S)} \ol{a \dl_t})\cdot (\ol{b \dl_s}), m) 
        &\overset{\cref{right crossprod-action}}{=}  \tilde{\eta}_{(X,M)}(x \ot_{K E(S)} (\ol{a \dl_t})(\ol{b \dl_s}), m) \\
        &= x \ot_{K S}(1_A \ot_{A^e} \left((\ol{a \dl_t})(\ol{b \dl_s})\right) \cdot m) \\ 
        &= x \ot_{K S}(1_A \ot_{A^e} (\ol{a \dl_t})\cdot ((\ol{b \dl_s}) \cdot m)) \\
        &=\tilde{\eta}_{(X,M)}(x \ot_{K E(S)} \ol{a \dl_t},  (\ol{b \dl_s })\cdot m).
    \end{align*}
    On the other hand,
    \begin{align*}
        \tilde{\eta}_{(X,M)}((\ol{b \dl_s}) \cdot (x \ot_{K E(S)} \ol{a \dl_t}), m)  & \overset{\cref{left crossprod-action}}{=} \tilde{\eta}_{(X,M)}(x \cdot s\m \ot_{K E(S)} (\ol{b \dl_s})(\ol{a \dl_t}), m) \\
        &= x \cdot s^{-1} \ot_{K S} \bigl( 1_A \ot_{A^e} (\ol{b \dl_s})(\ol{a \dl_t}) \cdot m \bigr) \\ 
        &= x \cdot s^{-1} \ot_{K S} \bigl( 1_A \ot_{A^e}(\ol{b\dl_1})(\ol{1_s \dl_s})(\ol{a \dl_t}) \cdot m \bigr)\\
        &= x \cdot s^{-1} \ot_{K S} \bigl( 1_A \ot_{A^e}(\ol{b\dl_1})\cdot\left((\ol{1_s \dl_s})(\ol{a \dl_t}) \cdot m\right) \bigr)\\
        &\overset{\cref{A-bimod M}}{=}x \cdot s^{-1} \ot_{K S} \bigl( 1_A \ot_{A^e}b\cdot\left((\ol{1_s \dl_s})(\ol{a \dl_t}) \cdot m\right) \bigr)\\
        &\overset{\eqref{dentro}}{=} x \cdot s^{-1} \ot_{K S} \bigl( b \ot_{A^e} (\ol{1_s \dl_s})(\ol{a \dl_t}) \cdot m \bigr) \\ 
        &\overset{\eqref{fora}}{=} x \cdot s^{-1} \ot_{K S} \bigl( 1_A \ot_{A^e} (\ol{1_s \dl_s})(\ol{a \dl_t}) \cdot m \cdot b\bigr) \\ 
        &\overset{\cref{A-bimod M}}{=}x \cdot s^{-1} \ot_{K S} \bigl( 1_A \ot_{A^e} (\ol{1_s \dl_s})(\ol{a \dl_t}) \cdot m \cdot (\ol{b \dl_1})\bigr) \\ 
        %&\overset{\eqref{fora}}{=} x \cdot s^{-1} \ot_{K S} \bigl( 1_A \ot_{A^e} (\ol{1_s \dl_s})(\ol{a \dl_t}) \cdot m \cdot (\ol{b \dl_1})\bigr) \\ 
        &= x  \ot_{K S} s^{-1} \cdot \bigl( 1_A \ot_{A^e} (\ol{1_s \dl_s})(\ol{a \dl_t}) \cdot m \cdot (\ol{b \dl_1})\bigr) \\ 
        &\overset{\eqref{left KS-module A otimes M}}{=} x  \ot_{K S} \bigl( s^{-1} \cdot  1_A \ot_{A^e} s^{-1} \cdot ((\ol{1_s \dl_s})(\ol{a \dl_t}) \cdot m \cdot (\ol{b \dl_1}))\bigr) \\ 
        &\overset{\eqref{left KS-mod M}}{=} x  \ot_{K S} \bigl( s^{-1} \cdot  1_A \ot_{A^e} (\ol{1_{s^{-1}}\dl_{s^{-1}}})(\ol{1_s \dl_s})(\ol{a \dl_t}) \cdot m \cdot (\ol{b \dl_1})(\ol{1_s \dl_s})\bigr)\\
        &= x  \ot_{K S} \bigl( s^{-1} \cdot  1_A \ot_{A^e} (\ol{1_{s^{-1}}\dl_{s^{-1}s}})(\ol{a \dl_t}) \cdot m \cdot (\ol{b \dl_s})\bigr).
\end{align*} 
Since $\overline{1_{s^{-1}}\delta_{s^{-1}s}}= \overline{1_{s^{-1}}\delta_{1}}$ and $s\m\cdot 1_A=1_{s\m}$ by \cref{left KS-mod A}, in view of \cref{A-bimod M} the last equals
 \begin{align*}
        x  \ot_{K S} \Bigl( 1_{s^{-1}} \ot_{A^e} 1_{s^{-1}}\left((\ol{a \dl_t}) \cdot m \cdot (\ol{b \dl_s})\right)\Bigr)
        &\overset{\eqref{dentro}}{=} x \ot_{K S} \Bigl(1_{s^{-1}} \ot_{A^e}  (\ol{a\dl_t}) \cdot m \cdot (\ol{b\dl_s})\Bigr) \\ 
        &\overset{\eqref{fora}}{=} x  \ot_{K S} \Bigl( 1_A \ot_{A^e} \big( (\ol{a\dl_t}) \cdot m \cdot (\ol{b\dl_s})\big)1_{s\m}\Bigr) \\  
        &\overset{\cref{A-bimod M}}{=} x  \ot_{K S} \Bigl( 1_A \ot_{A^e}  (\ol{a \dl_t}) \cdot m \cdot (\ol{b \dl_s})(\ol{1_{s^{-1}} \dl_1})\Bigr) \\  
        &= x  \ot_{K S} \Bigl( 1_A \ot_{A^e} (\ol{a \dl_t}) \cdot m \cdot (\ol{b \dl_s})\Bigr) \\
        &= \tilde{\eta}_{(X,M)}(x \ot_{K E(S)} \ol{a \dl_t}, m \cdot (\ol{b \dl_s }) ).
    \end{align*}
    Consequently, we obtain a well-defined mapping  
    \begin{align*}
        \eta_{(X,M)} :  (X \otimes_{K E(S)} (A\rtimes_\0 S))  \otimes_{(A\rtimes_\0 S)^e} M  & \to  X \otimes_{K S} (A\otimes_{A^e}M), \\ 
        (x \ot_{K E(S)} \ol{a \dl_t}) \ot_{(A\rtimes_\0 S)^e}  m &\mapsto x \ot_{K S}(1_A \ot_{A^e} (\ol{a \dl_t}) \cdot m).
    \end{align*}
     Composing $\xi_X$ and $\eta_X$ we see that
    \begin{align*}
        \eta_{(X,M)}\big( \xi _{(X,M)}(x \otimes_{K S}(a\otimes_{A^e}m))\big) &=  \eta _{(X,M)}\big( (x \otimes_{K E(S)} 1_A \delta_1) \otimes_{(A\rtimes_\0 S)^e} a \cdot m\big) \\ 
        &=x \otimes_{K S}(1_A \otimes_{A^e} a \cdot m) \\
        &\overset{\eqref{dentro}}{=}x \otimes_{K S}(a \otimes_{A^e} m)
    \end{align*}
    and
    \begin{align*}
        \xi _{(X,M)}\big( \eta _{(X,M)}((x \otimes_{K E(S)} \overline{a_t \delta_t}) 
        \otimes_{(A\rtimes_\0 S)^e} m) \big)
        &= \xi _{(X,M)} \big(x \otimes_{K S}(1_A \otimes_{A^e} (\overline{a_t \delta_t}) \cdot m) \big) \\
        &=  (x \otimes_{K E(S)} \overline{1_A \delta_1})
 \otimes_{(A\rtimes_\0 S)^e} (\overline{a_t \delta_t} ) \cdot m \\
        &\overset{\eqref{dentro}}{=}(x \otimes_{K E(S)} \overline{a_t \delta_t})
 \otimes_{(A\rtimes_\0 S)^e} m,
    \end{align*} so that  $\xi _X$ and $\eta _X$ are mutually inverse.

    To see that  $\xi $  is natural, let  $f: X \to X'$ be a homomorphism of right $K S$-modules and $\phi : M \to M'$ be a homomorphism of $A\rtimes_\0 S$-bimodules. Write   $\nu_{(f,\phi)}=f \otimes_{K S}(1_A \otimes_{A^e} \phi)$ and $\nu ^{(f,\phi )}=(f \otimes_{K E(S)}1_A\delta_1)
    \otimes_{(A\rtimes_\0 S)^e} \phi$. Consider the  diagram 
    \[\begin{tikzcd}
        {X \otimes_{K S} (A\otimes_{A^e}M)} & {X' \otimes_{K S} (A\otimes_{A^e}M')} \\
        {(X \otimes_{K E(S)} (A\rtimes_\0 S))  \otimes_{(A\rtimes_\0 S)^e}M} & {(X' \otimes_{K E(S)} (A\rtimes_\0 S))  \otimes_{(A\rtimes_\0 S)^e}M'.}
        \arrow["{\nu_{(f,\phi)}}", from=1-1, to=1-2]
        \arrow["{\nu ^{(f,\phi )}}", from=2-1, to=2-2]
        \arrow["{\xi_{(X,M)}}"', from=1-1, to=2-1]
        \arrow["{\xi_{(X',M')}}"', from=1-2, to=2-2]
    \end{tikzcd}\] 
    It is easily seen to be commutative:
    \begin{align*}
        \xi_{(X',M')} \left( \nu_{(f,\phi)}(x \otimes_{K S}(a \otimes_{A^e} m)) \right)
        &=\xi_{(X,M)} \left(f(x) \otimes_{K S}(a \otimes_{A^e} \phi (m))\right) \\
        &= (f(x) \otimes_{K E(S)} \overline{1_A \delta_1}) \otimes_{(A\rtimes_\0 S)^e} a \cdot \phi (m) \\
        &= (f(x) \otimes_{K E(S)} \overline{1_A \delta_1}) \otimes_{(A\rtimes_\0 S)^e} \phi (a \cdot m) \\ 
        &= \nu ^{(f,\phi )}\left( (x \otimes_{K E(S)} \overline{1_A \delta_1}) \otimes_{(A\rtimes_\0 S)^e} a \cdot m \right) \\
        &= \nu ^{(f,\phi )}\left(\xi_{(X,M)}(x \otimes_{K S}(a \otimes_{A^e} m))  \right),
    \end{align*}
implying that $\xi $ is a natural isomorphism.
\end{proof}




We proceed with the next.

\begin{lem} \label{l_AsemidirSisoBsemidirS}
    The mapping 
    \begin{align*}
        \varphi:A\rtimes_\0 S        &\to K E(S) \otimes_{K E(S)} (A\rtimes_\0 S) , \\ 
            \overline{a \delta_t}    &\mapsto 1_{K E(S)} \otimes_{K E(S)} \overline{a \delta_t},
    \end{align*}
    is an isomorphism of $A\rtimes_\0 S$-bimodules.
\end{lem}
\begin{proof}  Evidently, $\varphi $ is a homomorphism of $K$-modules. In order to see that  it is a  $A\rtimes_\0 S $-bimodule mapping, take  arbitrary  $b\in 1_vA$, $a\in 1_sA$ and $c\in 1_tA$. Recall that we consider $K E(S)$ as a right $K S$-module by means of \eqref{right KS-mod KE(S)}. Then
    \begin{align*}
        \varphi((\ol{b \dl_v})(\ol{a \dl_s})(\ol{c \dl_t}))  
        &= 1_{K E(S)} \ot_{K E(S)} (\ol{b \dl_v})(\ol{a \dl_s})(\ol{c \dl_t}) \\  
        %&= \big(1_{K E(S)} \ot_{K E(S)} (\ol{b \dl_v})(\ol{a \dl_s})\big) \cdot (\ol{c \dl_t}) \\ 
        & = 1_{K E(S)} \ot_{K E(S)} ( \ol{1_v b \dl_v})(\ol{a \dl_s})  (\ol{c \dl_t})  \\ 
        &\overset{\eqref{left KE(S)-action on cross}}{=} 1_{K E(S)} \ot_{K E(S)} (v v\m)  \cdot ((\ol{b \dl_v})(\ol{a \dl_s}) (\ol{c \dl_t}) ) \\ 
        &= v v\m \ot_{K E(S)} (\ol{b \dl_v})(\ol{a \dl_s})  (\ol{c \dl_t}) \\
        &\overset{\eqref{right crossprod-action}}{=} \big( v v\m\ot_{K E(S)} (\ol{b \dl_v})(\ol{a \dl_s})\big) \cdot \ol{c \dl_t} \\
        &\overset{\eqref{right KS-mod KE(S)}}{=} \big(  1_{K E(S)}\cdot v\m \ot_{K E(S)} (\ol{b \dl_v})(\ol{a \dl_s})\big) \cdot \ol{c \dl_t} \\ 
        &\overset{\eqref{left crossprod-action}}{=} \ol{b \dl_v} \cdot \big(1_{K E(S)} \ot_{K E(S)} \ol{a \dl_s}\big) \cdot \ol{c \dl_t} \\
        &= \ol{b \dl_v} \cdot \varphi (\ol{a \dl_s}) \cdot \ol{c \dl_t}.
    \end{align*}
    Thus, $\varphi$ is a homomorphism of $A\rtimes_\0 S$-bimodules. Since  $A\rtimes_\0 S$ is a left $K E(S)$-module by \eqref{left KE(S)-action on cross}, the mapping 
      \begin{align*}
        {\varphi}': K E(S) \otimes_{K E(S)} (A\rtimes_\0 S) &\to A\rtimes_\0 S, \\ 
        \omega \otimes_{K E(S)} \overline{a\delta_t}   &\mapsto \omega \cdot \overline{a\delta_t},
    \end{align*}
    is well-defined and easily seen to be   an inverse of $\varphi .$ Consequently, $\varphi$ is an isomorphism of $A\rtimes_\0 S $-bimodules.
\end{proof}

Recall that $F_1$, $F_2$ and $F$ are the functors defined in \cref{functor-F_1-hom,functor-F_2-hom,functor-F-hom}, respectively. As a consequence of \cref{prop:bifunctor iso,l_AsemidirSisoBsemidirS}, we obtain the following.
\begin{cor} \label{cor:F2F1isoF}
    The functors $F_2F_1$ and $F$ are naturally isomorphic. 
\end{cor}

\begin{proof} Taking  $X=K E(S)$ as the first argument of the bifunctors from 
   Proposition~\ref{prop:bifunctor iso}  we conclude that the functors
    \[
        K E(S) \otimes_{K S} (A \otimes_{A^e}-): (A\rtimes_\0 S)^e\textbf{-Mod}  \to K\textbf{-Mod}
    \]
    and
    \[
        (K E(S) \otimes_{K E(S)} (A\rtimes_\0 S)) \otimes_{(A\rtimes_\0 S)^e}-:(A\rtimes_\0 S)^e\textbf{-Mod}  \to K\textbf{-Mod}
    \] 
    are naturally isomorphic. On the one hand, $F_2F_1 = K E(S)\otimes_{K S} (A \otimes_{A^e}-),$ and on the other hand Lemma~\ref{l_AsemidirSisoBsemidirS} gives us an $A\rtimes_\0 S$-bimodule isomorphism  
    $$
    K E(S) \otimes_{K E(S)} (A\rtimes_\0 S) \cong A\rtimes_\0 S.
    $$ 
    The latter   implies the natural isomorphism  
    $$
    F \cong (K E(S) \otimes_{K E(S)} (A\rtimes_\0 S)) \otimes_{(A\rtimes_\0 S)^e}- 
    $$ 
    of functors, proving  our statement.
\end{proof}

  We also need the following auxiliary fact on flat modules, which is known, but we did not find a  bibliographic reference for it and we include a proof for reader's convenience. 

\begin{lem}\label{lem:FlatTransitivity} (Transitivity of the flatness)
 Let $\phi:R\to R'$ be a  homomorphism of unital rings such that $_RR'$ (resp. $R'_R$) is flat, and let $_{R'}M$ (resp. $M_{R'}$) be a  flat left (resp. right) module. Then $_RM$ (resp. $M_R$) is also flat.
\end{lem}
\begin{proof}
We will prove the statement for left modules. Consider an exact sequence of right $R$-modules 
$0\to K\to N$. Since $_RR'$ is flat then $0\to K \otimes_R R'\to N\otimes _R R'$ is an exact sequence in  the category of right $R'$-modules. The sequence   $0\to (K \otimes_R R')\otimes_{R'} M\to (N\otimes _R R')\otimes_{R'} M$ is also exact, because of the flatness of  $_{R'}M$. Then by the associativity of the tensor product and the canonical isomorphism $R'\otimes_{R'} M\cong M$, we have that $0\to K \otimes_R  M\to N\otimes _R M$ is exact.
\end{proof}


