\subsection{Homology of $A\rtimes_\0 S $ over a field $K$}
To proceed with an arbitrary inverse monoid $S$  \underline{we  assume during this subsection} that $K$ is a field.



By \cite[Proposition 5.14]{DJ2} any commutative algebra over a field
%commutative ring
 ge\-ne\-ra\-ted by idempotents is von Neumann regular. Thus, $K E(S)$ is von Neumann regular. Consequently, any module over $ K E(S)$ is flat (see  \cite[Corollary 1.13)]{Goodearl}). Therefore, we have the next:

\begin{lem}\label{lem:exactfunctor} The functor 
$- \otimes_{K E(S)} (A\rtimes_\0 S) $ is exact.
\end{lem}

Now we are ready to give the following result.

\begin{thrm} \label{teo:HLH}
   Let $\0$ be a unital action of an   inverse monoid $S$ on an algebra  $A$  over a field $K$ and $M$ an $A\rtimes_\0 S$-bimodule. Then   there exists a first quadrant homology spectral sequence
    \[
        E^2_{p,q} = H_p(S, (L_q F_1)M  ) \Rightarrow H_{p+q}(A\rtimes_\0 S, M). 
    \]
\end{thrm}
\begin{proof} We are going to use \cite[Theorem 10.48]{Rotman} for the functors
 \[
       (A\rtimes_\0 S)^e\textbf{-Mod}  
       \overset{F_1}{\longrightarrow} K S\textbf{-Mod}  \overset{F_2}{\longrightarrow} K\textbf{-Mod}.
    \]
 Note that the functors  $F_1$ and $F_2$ are right exact and that  
 \begin{align*}
 	L_\bullet F_2 (-) = \operatorname{Tor}^{K S}_\bullet (K E(S),-)\text{ and }L_{\bullet}F(-)=H_{\bullet}(A\rtimes_\0 S, -).
 \end{align*}
  Since by Corollary~\ref{cor:F2F1isoF} the functors $F_2 F_1$ and $ F$ are naturally isomorphic,  it  remains to show that for any projective object $P$ in $(A\rtimes_\0 S)^e$\textbf{-Mod} the left $K S$-module $F_1(P)$ is left $F_2$-acyclic. Equivalently,
    \[
        \operatorname{Tor}^{K S}_n(K E(S),F_1(P))=0, \, \forall n>0.
    \]
    So let  $P$ be a projective $(A\rtimes_\0 S)^e$-module. Then $-\otimes_{(A\rtimes_\0 S)^e} P$ is an exact functor. In addition, the functor  $- \otimes_{K E(S)} (A\rtimes_\0 S)$ is also exact thanks to Lemma~\ref{lem:exactfunctor}. Consequently, 
    $(- \otimes_{K E(S)} (A\rtimes_\0 S)) \otimes_{(A\rtimes_\0 S)^e}P$ is an exact functor. Taking $M=P$ as the second argument of the bifunctors from Proposition~\ref{prop:bifunctor iso},  we have that $- \otimes_{K S} (A \otimes_{A^e} P)$ is naturally isomorphic to $(- \otimes_{K E(S)} (A\rtimes_\0 S)) \otimes_{(A\rtimes_\0 S)^e}P.$ Then  
    \begin{align*}
        \operatorname{Tor}^{K S}_n(K E(S),F_1(P))
        &=L_n(- \otimes_{K S} (A \otimes_{A^e} P))(K E(S)) \\ 
        &\cong  L_n((- \otimes_{K E(S)} (A\rtimes_\0 S) \otimes_{(A\rtimes_\0 S)^e}P)(K E(S)) =0,
    \end{align*} for all $n>0,$ as desired. Thus we can apply \cite[Theorem 10.48]{Rotman}, which gives us the following first quadrant homology spectral sequence 
    \[
        E^2_{p,q} = \operatorname{Tor}^{K S}_p(K E(S), (L_q F_1)M  ) \Rightarrow H_{p+q}(A\rtimes_\0 S, M). 
    \] Finally, observe that by Definition~\ref{def:Inv Monoid (co)homol} we have that
    $$ \operatorname{Tor}^{K S}_p(K E(S), (L_q F_1)M  ) =
    H_p(S, (L_q F_1)M  ),
    $$  completing our proof.
    \end{proof}





