\begin{cor}\label{cor:flatHHH}
	Let $\0$ be a unital action of an  inverse monoid $S$ on  a $K$-algebra $A$ over a field $K$ and $M$ an $A\rtimes_\0 S$-bimodule. Assume that %$A\rtimes_\0 S$ is flat as a left $A$-module and also as a right $A$-module.
	$(A\rtimes_\0 S)^e $ is flat as a left $A^e$-module. Then   there exists  a first quadrant homology spectral sequence
	\begin{align*}
	   E^2_{p,q} = H_p(S, H_q (A, M)) \Rightarrow H_{p+q}(A\rtimes_\0 S, M). 
   \end{align*}
	   \end{cor}
	   \begin{proof}  
	   %By Lemma~\ref{lem:biFlatness} we have that $(A\rtimes_\0 S)^e $ is flat as a left $A^e$-module. 
	   By the transitivity of the flatness (Lemma~\ref{lem:FlatTransitivity}) every flat left 
	   $(A\rtimes_\0 S)^e $-module is flat as a left $A^e$-module. Consequently, any flat resolution of $M$ in  $(A\rtimes_\0 S)^e\textbf{-Mod}$ is a flat resolution of $M$ in  $A^e\textbf{-Mod}.$    Since
	   $\operatorname{Tor}^{A^e}_q (A,M)$ can be computed using flat resolutions of $M$ in  $A^e\textbf{-Mod}$  (see, for example,  \cite[Theorem 7.5]{Rotman}), it follows that  
   $(L_q F_1)M =   \operatorname{Tor}^{A^e}_q (A,M) = H_q (A,M)$  for all $q,$ and our statement is obtained by applying
   Theorem~\ref{teo:HLH}. 
		\end{proof}


   Observe that it is well-known that if  $N$ is an $A$-bimodule, then   the  groups 
$H_n(A,N) := \operatorname{Tor}_n^{A^e} (A,N),$ $n\geq 0,$  can be identified with the homology groups of the Hochschild complex  (see, for example,  \cite[Section 1.1]{Loday}). In particular, there are isomorphisms between the $K$-spaces
$H_0(A,N)$ and    $N/[A, N].$   In our case, under the assumptions of Corollary~\ref{cor:flatHHH},  the identification between   
$H_0(A,M)$  and    $M/[A, M]$  turns out to be an isomorphism 
of  $KS$-modules:  

\begin{lem}\label{lem:0-homology} Let $\0$ be a unital action of an  inverse monoid $S$ on  a $K$-algebra $A$ over a field $K$ and $M$ an $A\rtimes_\0 S$-bimodule. Assume that 
	$(A\rtimes_\0 S)^e $ is flat as a left $A^e$-module. Then there is a  left $KS$-module isomorphism
	$$H_0(A,M)  \cong M/[A, M].  $$
\end{lem}
\begin{proof} Thanks to Lemma~\ref{lem:for0-homology} it is enough to establish a left $KS$-module isomorphism between $H_0(A,M) $ and $ A \ot _{A^e} M.$   An identification of these $K$-spaces is well-known and we only need to observe that it is a $KS$-isomorphism. 

Let 
\begin{equation}\label{eq:flatResolution}
 \ldots \to P_1 \to P_0 \to M\to 0
 \end{equation}  be a flat resolution of $M$ in  $(A\rtimes_\0 S)^e\textbf{-Mod}.$ Applying to the exact sequence $ P_1 \to P_0 \to M\to 0$ the right exact functor $F_1,$ we obtain the exact sequence of left $KS$-modules and  $KS$-homomorphisms  
$$ A \ot _{A^e}  P_1 \to A \ot _{A^e} P_0 \to A \ot _{A^e} M\to 0.$$ As in the proof of Corollary~\ref{cor:flatHHH},   the complex \eqref{eq:flatResolution} is also  a flat resolution of $M$ in $A^e\textbf{-Mod}$ and, consequently, 
 $$H_0(A,M) = 
( A \ot _{A^e} P_0) / {\rm im}\, (A \ot _{A^e}  P_1 \to A \ot _{A^e} P_0).$$  This yields  the desired isomorphism between the left $KS$-modules $H_0(A,M)$ and  $ A \ot _{A^e} M.$ 
\end{proof}


\begin{rem}\label{rem:separable}
    Under the conditions of Corollary~\ref{cor:flatHHH} assume in addition that $A$ is separable over $K.$ Then   there is  an isomorphism
    \[
         H_n(S, M/[A, M]) \cong H_{n}(A\rtimes_\0 S, M). 
    \] Indeed, the separability of $A$ means that $A$ is projective as a left  (equivalently, right) $A^e$-module. Consequently, the spectral sequence collapses on the $p$-axis and by 
    \cite[Proposition 10.21]{Rotman} we obtain an isomorphism
    $$ H_n(S, H_0(A,M)) \cong H_{n}(A\rtimes_\0 S, M).  $$
	Finally, thanks to Lemma~\ref{lem:0-homology},
	the left $KS$-modules   $H_0(A,M)$ and $  M/[A, M]$ are isomorphic. 
\end{rem}



