\subsection{Homology of $A\rtimes_\0 S $ with $E$-unitary $S$}
 In the $E$-unitary case we are able to drop the restriction on $K$ to be a field, replacing it by the assumption that $A$ is flat over the commutative ring $K.$  Moreover, we shall see below   that if $A$ is flat over $K,$ then  $(A\rtimes_\0 S)^e $ is flat as a left (right) $A^e$-module for any $E$-unitary inverse semigroup $S.$  

\begin{lem}\label{lem:acyclic}
	Let $\0$ be a unital action of an  $E$-unitary inverse monoid $S$ on a $K$-algebra  $A$  over a commutative ring $K,$ 
	 $M$ be a left $K S$-module, and let $P_\bullet \to K E(S)$ be a projective resolution  of $K E(S)$ in $\rMod KS.$  Then, $H_n(P_\bullet \otimes_{K E(S)} M) = 0$ for all $n \geq 1$.
\end{lem}

\begin{proof} 
   By Corollary~\ref{cor:KS pojective over KR(S)},   $K S$ is projective  as a right $K E(S)$-module.  Then by the transitivity of projectivity (see \cite[Proposition 1.4]{DeMeyerIngraham}) any projective right $KS$-module is  projective as a right $K E(S)$-module.  Consequently,
	  $P_{\bullet} \to K E(S)$ is also a projective resolution of $K E(S)$ in \textbf{Mod-}$K E(S)$. Therefore,
	\[
		H_n(P_{\bullet}\otimes_{K E(S)} M)= \operatorname{Tor}_n^{K E(S)}(K E(S), M)= \left\{\begin{matrix}
			0 & \text{ if } n \geq 1 \\ 
			M & \text{ if } n=0.
			\end{matrix}\right.
	\]
\end{proof}


  \begin{prop} \label{p_F1sendPtoF2acylic} Let $\0$ be a unital action of an  $E$-unitary inverse monoid $S$ on a $K$-algebra  $A$  over a commutative ring $K.$ Then
     $F_1$ sends projective $A\rtimes_\0 S$-bimodules to left $F_2$-acyclic modules.
 \end{prop}
 \begin{proof} Let $P$ be an arbitrary projective 
  $(A\rtimes_\0 S)^e$-module. We need to show that 
     \[
         (L_nF_2)(A \otimes_{A^e}P) = 0, \, \, \forall n \geq 1.
     \] Using the fact that $\operatorname{Tor}(-,-)$ is symmetric, we see that
     \begin{align*}
         (L_nF_2)(A \otimes_{A^e}P)
         &= L_n(K E(S) \otimes_{K S} -)(A \otimes_{A^e}P) \\
         &\cong\operatorname{Tor}^{K S}_n (K E(S),A \otimes_{A^e}P)\\
         &\cong L_n(- \otimes_{K S} (A \otimes_{A^e}P))(K E(S)) \\
        (\text{by Proposition \ref{prop:bifunctor iso}}) &\cong L_n((- \otimes_{K E(S)} (A\rtimes_\0 S)) \otimes_{(A\rtimes_\0 S)^e}P)(K E(S)).
     \end{align*}
     Let $Q_{\bullet} \to K E(S)$ be a projective resolution of $K E(S)$ in \textbf{Mod-}$K S$. Then,
     \begin{align*}
         (L_nF_2)(A \otimes_{A^e}P) &\cong L_n((- \otimes_{K E(S)} (A\rtimes_\0 S)) \otimes_{(A\rtimes_\0 S)^e}P)(K E(S))\\ &= H_n \left(  (Q_{\bullet}\otimes_{K E(S)} (A\rtimes_\0 S)) \otimes_{(A\rtimes_\0 S)^e}P \right).
     \end{align*}
    By Lemma~\ref{lem:acyclic} we have that $ H_n(Q_{\bullet}\otimes_{K E(S)}( A\rtimes_\0 S))= 0$ for all $n>0.$ 
      This yields that the complex $Q_{\bullet}\otimes_{K E(S)}  (A\rtimes_\0 S)$ is exact at the $n$-th term for all $n \geq 1$. It follows that 
      the complex $(Q_{\bullet}\otimes_{K E(S)} (A\rtimes_\0 S)) \otimes_{(A\rtimes_\0 S)^e}P$ is also exact at the $n$-th term for all $n \geq 1$ since $P$ is projective as an $(A\rtimes_\0 S)^e$-module, and thus
     \[
         H_n \left(  (Q_{\bullet}\otimes_{K E(S)}(A\rtimes_\0 S)) \otimes_{(A\rtimes_\0 S)^e}P \right) = 0,\ \forall n \geq 1,
     \]
     completing our proof. 
 \end{proof}



 In view of  Remark~\ref{rem:Adelta_1Embedding} we may consider $A$ as a $K$-subalgebra of $A\rtimes_\0 S$ by means of the embedding $A\to  A\rtimes_\0 S,$ given by $a \mapsto a \dl _1.$ Then  $(A\rtimes_\0 S)^e$ is a left $A^e$-module with the action given in \eqref{eq:left R^e on (R')^e} and it is also a right
  $A^e$-module with the action defined in \eqref{eq:right R^e on (R')^e}. Similarly, 
 $(A\rtimes_{\tl\0} {\mathcal G}(S))^e$ is also a left and right  $A^e$-module via \eqref{eq:left R^e on (R')^e} and \eqref{eq:right R^e on (R')^e}, respectively. 


\begin{lem}\label{lem:FlatnessInE-unitaryCase}
  Suppose that the $K$-algebra $A$ is flat over the commutative ring $K$ and $\0$ is a  unital action of an  $E$-unitary inverse monoid $S$ on  $A.$ Then  $(A\rtimes_\0 S)^e $ is flat as a left (right) $A^e$-module.
\end{lem}
\begin{proof}  We know  from Proposition~\ref{cor:IsoPhi} and Remark~\ref {rem:A-bimodule mapping} that
      $A\rtimes_\0 S $ and $  A\rtimes_{\tl\0} {\mathcal G}(S)$ are isomorphic not only as  $K$-algebras, but also as $A$-bimodules. By Remark~\ref{rem:left R^e on (R')^e} this implies that  $(A\rtimes_\0 S)^e $ and 
      $(A\rtimes_{\tl\0} {\mathcal G}(S))^e$ are isomorphic as left (right)  $A^e$-modules. Thus, it is enough to prove that $(A\rtimes_{\tl\0} {\mathcal G}(S))^e$ is flat as a left (right) $A^e$-module.

   We shall show first that  $\D _g$ is flat as a right (left) $A$-module  for any $g \in {\mathcal G}(S).$
   Indeed,  let $g\in \cG(S)$ and $(\cF(g),\sst)$ be the directed set of all finite subsets of the $\sg$-class $g$. For any $T\in \cF(g)$ consider the finite sum $\cI(T):= \sum_{t\in T}1_tA$ of unital ideals. Then $\cI(T)$ is also a unital ideal in $A$ by \cref{R=sum-orth-ideals}.  It follows that $\cI(T)$ is of the form $Ae$, where $e \in \D_ g$ is an idempotent, which is central in $A.$ Then $\cI(T)$ is a direct summand of $A$, and, consequently, it is projective as a left (right)  $A$-module. Therefore, $\cI(T)$ is flat  as a left (right)  $A$-module.  Consider the direct system $\{\cI(T),\vf^T_U\}$ of left (right) $A$-modules, where $\vf^T_U:\cI(T)\to\cI(U)$ is the inclusion map for all $T\sst U$. Observe by \cite[Corollary 5.31]{Rotman} that
     	\begin{align*}
     		\D_g=\sum_{s\in g}1_sA=\bigcup_{T\in\cF(g)}\cI(T)
     	\end{align*}
     	is the direct limit of $\{\cI(T),\vf^T_U\}$. Thus, by \cite[Corollary 5.34]{Rotman},  $\D_ g$  is  flat  as a left (right) $A$-module.

     	Take $t,s \in S.$ With a slight abuse of notation we denote by $ (1_sA)^{\rm op}$ the subset $1_sA $ of  $ A^{\rm op}.$  Since $1_tA$  is a direct summand of $A,$  $ (1_sA)^{\rm op}$ is a direct summand of $ A^{\rm op}$ and tensor product respects direct sums, it follows that  
     	$1_tA \otimes _K  (1_sA)^{\rm op}$ is a direct summand of  $A^e = A \ot _K A^{\rm op}.$  Hence $1_tA \otimes _K  (1_sA)^{\rm op}$ is a flat  left (right) $A^e$-module, being projective over $A^e.$ 

   We know already that $\D_g$ is flat as a right $A$-module for every $g \in \cG(S).$ Using  the fact that $A$ is flat over $K$ and the transitivity of flat modules (Lemma~\ref{lem:FlatTransitivity}), we conclude that $\D_g$ is flat over $K.$   	Then for any $h\in  \cG(S)$ the inclusion mapping 
     	$ (\D _h)^{\rm op} \to A^{\rm op}$ gives rise to the exact sequence 
     	\begin{equation}\label{eq:mono1}
0 \to \D _g \otimes _K  (\D _h)^{\rm op} \to \D _g \ot _K A^{\rm op}. 
\end{equation} Here, similarly as above, $ (\D _h)^{\rm op}$ stands for the subset  $\D _h$ of  $A^{\rm op}.$ Obviously, the mapping $\D_g \ot _K (\D _h)^{\rm op} \to \D _g \ot _K A^{\rm op} $ is a monomorphism of non-necessarily unital algebras,  
      which allows us to identify the algebra $\D_g \ot _K (\D _h)^{\rm op} $ with its image in $\D _g \ot _K A^{\rm op}.$
      Now, since $A$ is flat over the commutative ring $K, $ then $A^{\rm op}$ is also flat over $K,$ and from the inclusion map $\D _g \to A$ we obtain the exact sequence of algebras
\begin{equation}\label{eq:mono2}
0 \to \D _g \ot _K A^{\rm op} \to A \ot _K A^{\rm op} = A^e.
\end{equation} Combining \eqref{eq:mono1} and \eqref{eq:mono2} we obtain a monomorphism of algebras  (considered as non-necessarily unital algebras)
$$0 \to \D _g \otimes _K  (\D _h)^{\rm op} \to A \ot _K A^{\rm op}, $$ and identify $\D _g \otimes _K  (\D_h)^{\rm op}$ with its image in $A\ot _K  A^{\rm op}, $  so that   $\D_g \otimes _K  (\D _h)^{\rm op}$ becomes an ideal in $A^e.$ Moreover, we may write
 $$\D_g \otimes _K  (\D _h)^{\rm op}=  \sum_{t\in g, s\in h}1_tA \otimes _K (1_s A)^{\rm op}.$$

     Let $g, h\in \cG(S)$ and $\cF(g,h)$ be the  set of all subsets $T$ of the Cartesian product $g \times h$ of the form  $T=T_g \times T_h,$ where $T_g$ is a  finite subset of the  $\sg$-class $g$ and $T_h$ is a  finite subset of the  $\sg$-class $h.$ For 
     $T=T_g \times T_h \in \cF(g,h)$ and $U= U_g \times  U_h \in \cF(g,h)$ it is clear that  
     $T \sst U$ if and only if 
      $T_g \sst U_g$ and  $T_h \sst U_h.$ Evidently, $(\cF(g,h),\sst)$ is a directed partially ordered set.


     Given any  $T=T_g \times T_h\in \cF(g,h)$, consider the finite sum 
     $$\cI(T):= \sum_{t\in T_g, s\in T_h}1_tA \otimes _K (1_s A)^{\rm op}$$ of unital ideals of $A^e.$ Then using again  \cref{R=sum-orth-ideals} we see that $\cI(T)$ is also a unital ideal in $A^e .$  Hence, 
      $\cI(T) = A^e a^e$, where $a^e \in A^e$ is an idempotent, which is central in $A^e.$ Thus $\cI(T)$ is a direct summand of $A^e$, and, consequently, it is  flat as a left (right)  $A^e$-module, being  projective over $A^e.$
        Now we look at the direct system 
       $\{\cI(T),\psi^{T}_{U}\}$ of left (right) $A^e$-modules, where $\psi^T_U:\cI(T)\to\cI(U)$ is the inclusion map 
        for all $T\sst U$. Referring again to \cite[Corollary 5.31]{Rotman} we have that
     	\begin{align*}
     		\D_g \otimes _K (\D _h)^{\rm op}=\sum_{t\in g, s \in h}1_tA \otimes _K (1_sA)^{\rm op} =\bigcup_{T\in\cF(g,h)}\cI(T)
     	\end{align*}
     	is the direct limit of $\{\cI(T),\psi^T_U\}$. Then, $ \D_g \otimes _K (\D _h)^{\rm op} \subseteq A \otimes _K A^{\rm op}$  is  flat  as a left (right)  $A^e$-module, being a direct limit of flat  left (right)  $A^e$-modules   (see \cite[Corollary 5.34]{Rotman}).  

     Given $g, h \in \cG(S),$ denote by $(\D_h \dl_h)^{\rm op}$ the subset $\D_h\dl_h$ of $(A\rtimes_{\tl\0} {\mathcal G}(S))^{\rm op}$ and consider the mapping 	
     $$
     \psi :  \D_g \otimes _K (\D _{h\m})^{\rm op} \to \D _g \delta _g \otimes _ K (\D _h \delta _h)^{\rm op},
     $$ 
     given by 
     $$a \ot b \mapsto a \delta _g \ot {\tl\0}_h (b) \dl_h, $$
     where $a \in  \D_g\text{ and }b \in \D _{h\m}.$ Then $\psi $ is an isomorphism of left $A^e$-modules. Indeed, clearly, it is a $K$-isomorphism. Moreover, for $a \in  \D_g, b \in \D _{h\m}$ and $c \ot d \in A^e$ we have that 
      \begin{align*}
      	\psi ((c \ot d)\cdot (a \ot b)) 
      	&= \psi (ca \ot bd) 
      	= ca \dl _g \ot  \tl\0_h (bd) \dl_h =  ca \dl _g \ot \tl\0_h(\tl\0\m_h(\tl\0_h(b))d)\dl_h\\
      	 &=c\dl_1 \cdot a \dl _g \ot \tl\0_h (b) \dl _h \cdot d \dl_1  = 	(c \ot d)\cdot \psi (a \ot b),
      \end{align*} showing that $\psi $  is a mapping of left $A^e$-modules. 
      Similarly, for $g, h \in \cG(S),$ define 	
      $$
      \eta :  \D_{g\m} \otimes _K (\D_h)^{\rm op} \to \D_g \delta_g \otimes_K (\D_h \delta _h)^{\rm op}
      $$ 
      by 
      $$
      a \ot b \mapsto {\tl\0}_g(a) \delta_g \ot b \dl_h, 
      $$
      where $a \in  \D_{g\m}$ and $b \in \D _h.$ Then $\eta$ is an isomorphism of right $A^e$-modules. For, $\eta$ is obviously a $K$-isomorphism and for all $a \in \D_{g\m}, b \in \D _h$ and $c \ot d \in A^e$ one has
      \begin{align*}
      	\eta((a \ot b) \cdot (c \ot d)) 
      	      	&= \eta (ac \ot db)={\tl\0}_g(ac) \delta_g \ot db \dl_h=\tl\0_g(\tl\0\m_g(\tl\0_g(a))c) \delta_g \ot db \dl_h\\  
      	      	&=\tl\0_g(a)\dl _g \cdot c\dl_1 \ot d \dl_1 \cdot b\dl_h= \eta(a \ot b)\cdot (c \ot d).
      \end{align*} 
%      As to the right $A^e$-action we see that
%      \begin{align*}
%      	\psi ( (a \ot b) \cdot (c \ot d)) 
%      	&= \psi (ac \ot db) 
%      	= \red{ac \dl _g \ot  \tl\0_h (bd) \dl_h =  ac \dl _g \ot \tl\0_h(\tl\0\m_h(\tl\0_h(b))d)\dl_h}\\
%      	 &\red{=c\dl_1 \cdot a \dl _g \ot \tl\0_h (b) \dl _h \cdot d \dl_1  = 	(c \ot d)\cdot \psi (a \ot b)},
%      \end{align*}  
       This yields that 
      $\D _g \delta _g \otimes _ K (\D _h \delta _h)^{\rm op}$ is also flat as a left (right) $A^e$-module.

      Now, since  
      $  A\rtimes_{\tl\0} {\mathcal G}(S) = \bigoplus_{g \in {\mathcal G}(S)} \D _g \dl _g$ and $\ot _K$ respects direct sums,
      we obtain the direct sum  
 $$( A\rtimes_{\tl\0} {\mathcal G}(S))^{e} =
 \bigoplus _{g,h \in {\mathcal G}(S)} \D _g \delta _g \otimes _ K (\D _h \delta _h)^{\rm op} $$ of $K$-modules. Evidently, it is a direct sum of left (right) $A^e$-modules, which implies that  $( A\rtimes_{\tl\0} {\mathcal G}(S))^{e}$ is flat as a left (right) $A^e$-module. 
 \end{proof}       





\begin{thrm}\label{teo:E-UnitaryHomolSpectralSeq}
   Suppose that the $K$-algebra $A$ is flat over the commutative ring $K.$ Let $\0$ be a  unital action of an  $E$-unitary inverse monoid $S$ on  $A$ and $M$ an $A\rtimes_\0 S$-bimodule. Then   there exists  a first quadrant homology spectral sequence
    \begin{equation}\label{eq:E-UnitaryHomolSpectralSeq}
        E^2_{p,q} = H_p(S, H_q (A, M)) \Rightarrow H_{p+q}(A\rtimes_\0 S, M). 
    \end{equation}
    \end{thrm}
    \begin{proof} 
    Since  the functor  $F_2$ is right exact and   by Proposition~\ref{p_F1sendPtoF2acylic} the functor 
     $F_1$ sends projective $A\rtimes_\0 S$-bimodules to left $F_2$-acyclic modules,  we are in conditions to apply \cite[Theorem 10.48]{Rotman} to the functors
 \[
       (A\rtimes_\0 S)^e\textbf{-Mod}  
       \overset{F_1}{\longrightarrow} K S\textbf{-Mod}  \overset{F_2}{\longrightarrow} K\textbf{-Mod},
    \]  
    which gives us  a first quadrant Grothendieck spectral sequence
    \begin{equation}\label{eq:SpectralSeqFromRotman}
        E^2_{p,q} = (L_p F_2) (L_q F_1) M \Rightarrow L_{p+q} ( F_2 F_1 ) M. 
    \end{equation} Thanks to the natural isomorphism
   of the functors $F_2 F_1$ and $ F$  provided  by Corollary~\ref{cor:F2F1isoF} and keeping in mind that
    \begin{align*}
 	L_\bullet F_2 (-) = \operatorname{Tor}^{K S}_\bullet (K E(S),-)\text{ and }L_{\bullet}F(-)=H_{\bullet}(A\rtimes_\0 S, -),
 \end{align*} we  obtain from \eqref {eq:SpectralSeqFromRotman} the  first quadrant  spectral sequence 
    \[
        E^2_{p,q} = \operatorname{Tor}^{K S}_p(K E(S), (L_q F_1)M  ) \Rightarrow H_{p+q}(A\rtimes_\0 S, M). 
    \] Since by definition of homology of $S$ (see Definition~\ref{def:Inv Monoid (co)homol}), we have that 
    $$ \operatorname{Tor}^{K S}_p(K E(S), (L_q F_1)M  ) =
    H_p(S, (L_q F_1)M  ),
    $$  the spectral sequence takes the form
    \begin{align}\label{eq:IntermediateSpectralSeq}
        E^2_{p,q} = H_p(S, (L_q F_1)M  ) \Rightarrow H_{p+q}(A\rtimes_\0 S, M). 
    \end{align}

            By  Lemma~\ref{lem:FlatnessInE-unitaryCase} we have that $(A\rtimes_\0 S)^e $ is flat as a left $A^e$-module. Then by the transitivity of the flatness (Lemma~\ref{lem:FlatTransitivity}) every flat left 
	   $(A\rtimes_\0 S)^e $-module is flat as a left $A^e$-module. Consequently, any flat resolution of $M$ in  $(A\rtimes_\0 S)^e\textbf{-Mod}$ is a flat resolution of $M$ in  $A^e\textbf{-Mod}.$    As it was mentioned already,
	   $\operatorname{Tor}^{A^e}_q (A,M)$ can be computed using flat resolutions of $M$ in  $A^e\textbf{-Mod}.$ It follows that  
   $(L_q F_1)M =   \operatorname{Tor}^{A^e}_q (A,M) = H_q (A,M)$  for all $q,$ and the spectral sequence \eqref{eq:IntermediateSpectralSeq} takes the form 
    \eqref{eq:E-UnitaryHomolSpectralSeq}, completing our proof. 
   \end{proof}



        Since an algebra over a field $K$ is obviously flat over $K,$ we immediately obtain the next:

   \begin{cor}\label{cor:E-unitaryOverField}
   Let $\0$ be a unital action of an  $E$-unitary inverse monoid $S$ on an algebra $A$ over a field $K$ and $M$ be an $A\rtimes_\0 S$-bimodule. Then   there exists  a first quadrant homology spectral sequence of the form 
   \eqref{eq:E-UnitaryHomolSpectralSeq}.
   \end{cor}


