    \section{Cohomology of $A\rtimes_\0 S$}\label{sec-cohom}

\subsection{Preliminary results} As in the case of homology, we need some preparation. Let, as above,  $M$ be an $A \rtimes_\0 S$-bimodule.

\begin{lem}\label{Gamma-hom-S-to-End(Hom)}
	There is a homomorphism $\Gamma : S \to \End_K (\Hom_{A^e}(A, M))$, $s\mapsto\Gamma _s$,
	given by  
	\begin{align*}
		\Gamma _s(f)(a) = s \cdot f(s\m \cdot a),
	\end{align*}
	for all $f \in \Hom_{A^e} (A, M)$ and $a\in A$, where $A$ is considered as a left $KS$-module via \cref{left KS-mod A} and $M$ is a left $KS$-module via \cref{left KS-mod M}.
\end{lem}
\begin{proof}
	Let us first show that $\Gamma _s(f) \in \Hom_{A^e} (A, M)$. For all $a,b,c\in A$ we have
	\begin{align*}
		\Gamma _s (f) (bac) &= s \cdot f(s\m \cdot (bac))
		= s \cdot f (s\m  b \cdot s\m  a \cdot s\m  c)
		= s \cdot (s\m  b \cdot f(s\m  a) \cdot s\m  c)\\
		&\overset{\cref{left KS-mod M}}{=}\ol{1_s\dl_s}\cdot (s\m  b \cdot f(s\m  a) \cdot s\m  c)\cdot \ol{1_{s\m} \dl_{s\m}}\\
		&\overset{\cref{left KS-mod A}}{=}\ol{1_s\dl_s}\cdot (\0_{s\m} (1_sb) \cdot f(s\m  a) \cdot \0_{s\m} (1_sc))\cdot \ol{1_{s\m} \dl_{s\m}}\\
		&\overset{\cref{A-bimod M}}{=}\ol{1_s\dl_s}\cdot \ol{\0_{s\m}(1_sb)\dl_1} \cdot f(s\m  a) \cdot \ol{\0_{s\m} (1_sc)\dl_1}\cdot \ol{1_{s\m} \dl_{s\m}}\\
		&=\ol{\0_s\circ\0_{s\m}(1_sb)\dl_s} \cdot f(s\m  a) \cdot \ol{\0_{s\m} (1_sc)\dl_{s\m}}\\
		&=\ol{1_sb\dl_s} \cdot f(s\m  a) \cdot \ol{\0_{s\m} (1_sc)\dl_{s\m}}=\ol{b\dl_1}\cdot\left(\ol{1_s\dl_s} \cdot f(s\m  a) \cdot \ol{1_{s\m}\dl_{s\m}}\right)\cdot\ol{c\dl_1}\\
		&\overset{\cref{left KS-mod M}}{=}\ol{b\dl_1}\cdot\left(s \cdot f(s\m  a) \right)\cdot\ol{c\dl_1}\overset{\cref{A-bimod M}}{=}b\cdot\left(s \cdot f(s\m  a) \right)\cdot c=b\cdot\Gamma _s(a)\cdot c.
	\end{align*}
	Now we prove that $\Gamma _s\circ\Gamma _t = \Gamma _{st}$. For all $f \in \Hom_{A^e} (A, M)$ and $a\in A$ we have
	\begin{align*}
		\Gamma _s(\Gamma _t(f))(a) = s \cdot \Gamma _t(f)(s\m\cdot  a) &= s \cdot t \cdot f(t\m \cdot s\m \cdot a)= (st) \cdot f( (t\m s\m)\cdot  a)\\
		&=(st) \cdot f( (st)\m\cdot  a)= \Gamma _{st}(f)(a).
	\end{align*}	
\end{proof}

%\red{\textbf{(Mykola: Could one change the statement of \cref{Gamma-hom-S-to-End(Hom)} to ``There is a left $KS$-module structure on $\Hom_{A^e}(A, M)$ given by...''?)}}

Thus, $\Gamma $ endows $\Hom_{A^e}(A, M)$ with a left $KS$-module structure via the action
\begin{align}\label{(sf)(a)=sf(s-inv-a)}
	(s\la f)(a)=s\la f(s\m\la a).
\end{align}

%\red{\textbf{(Mykola: The definitions of $T_1$, $T_2$ and $T$ are not used in the following lemma.) }}

Hence, we can define the following left exact functors:
\begin{align*}
	T_1&:=\Hom_{A^e}(A,-): (A \rtimes_\0 S)^e\Mod\to KS\Mod,\\
	T_2&:=\Hom_{KS}(KE(S),-):KS\Mod\to K\Mod.
\end{align*}
We shall also need  the functor which determines the Hochschild cohomology of $A \rtimes_\0 S$ with coefficients in an $A \rtimes_\0 S$-bimodule:
\begin{align*}
	T:=\Hom_{(A \rtimes_\0 S)^e}(A \rtimes_\0 S,-) : (A \rtimes_\0 S)^e\Mod\to K\Mod.
\end{align*}

Let $X$ be a left $KS$-module. Then $X$ can be considered as a right $KE(S)$-module via
\begin{align}\label{x-cdot-b=b-cdot-x}
	x\cdot b:=b\cdot x,
\end{align}	
for all $x\in X$ and $b\in KE(S)$, since $KE(S)$ is commutative.
\begin{lem}
	Let $X$ be a left $KS$-module. Then $X\ot_{KE(S)}(A \rtimes_\0 S)$ is an $A \rtimes_\0 S$-bimodule with the actions \cref{right crossprod-action} and
	\begin{align}\label{a.dl_s(x-ot-b.dl_t)}
		\ol{a\dl_s}\la(x\ot_{KE(S)}\ol{b\dl_t})=s\la x\ot_{KE(S)}\ol{a\dl_s}\cdot\ol{b\dl_t}.
	\end{align}
\end{lem}
\begin{proof}
	The proof is similar to the proof of \cref{prop:bimodule structure X tensor cross}.
\end{proof}

\begin{lem}\label{construction-of-gm}
	There is a $K$-linear map
	\begin{align*}
		\gm:\Hom_{KS}(X,\Hom_{A^e}(A,M))\to\Hom_{(A \rtimes_\0 S)^e}(X\ot_{KE(S)} (A \rtimes_\0 S) ,M)
	\end{align*}
	such that, for all $f\in\Hom_{KS}(X,\Hom_{A^e}(A,M))$,
	\begin{align}\label{gm(f)(x-ot-a.dl_s)=f_s(1_A)a.dl_s}
		\gm(f)(x\ot_{KE(S)}\ol{a\dl_s})=f_x(1_A)\cdot \ol{a\dl_s},
	\end{align}
	where $f_x:=f(x)\in\Hom_{A^e}(A,M)$.
\end{lem}
\begin{proof}
	Let us see that, for a fixed 
	 $f\in\Hom_{KS}(X,\Hom_{A^e}(A,M))$, the map 
	\begin{align*}
		\gm^f: X\times (A \rtimes_\0 S) \to M,\ (x,\ol{a\dl_s})\mapsto f_x(1_A)\cdot \ol{a\dl_s},
	\end{align*}
	is balanced over $KE(S)$. Note that $f_{s\la x}=s\la f_x$ for all $s\in S$ and $x\in X$, since $f$ is a morphism of left $KS$-modules. Let $e\in E(S)$. Then
	\begin{align*}
		f_{x\cdot e}(1_A)&\overset{\cref{x-cdot-b=b-cdot-x}}{=}f_{e\cdot x}(1_A)=(e\cdot f_x)(1_A)\overset{\cref{(sf)(a)=sf(s-inv-a)}}{=}e\cdot f_x(e\cdot 1_A)\overset{\cref{EmmanuelLemma(i)}}{=}e\cdot f_x(1_e)
		\overset{\cref{EmmanuelLemma(ii)}}{=}1_ef_x(1_e)1_e\\
		&=f_x(1_e1_e1_e)=f_x(1_A1_e)=f_x(1_A)1_e\overset{\cref{A-bimod M}}{=}f_x(1_A)\cdot\ol{1_e\dl_1}.
	\end{align*}
	%where the penultimate equality is due to $f_x\in\Hom_{A^e}(A,M)$. 
	It follows that
	\begin{align*}
		\gm^f(x\cdot e,\ol{a\dl_s})&=f_{x\cdot e}(1_A)\cdot \ol{a\dl_s}=f_x(1_A)\cdot\ol{1_e\dl_1}\cdot \ol{a\dl_s}=f_x(1_A)\cdot\ol{1_ea\dl_s}\\
		& \overset{\cref{left KE(S)-action on cross}}{=}f_x(1_A)\cdot(e\la\ol{a\dl_s})=\gm^f(x,e\la\ol{a\dl_s}).
	\end{align*}
	Thus, $\gm^f$ is balanced over $KE(S)$, so that $\gm(f)$ given by \cref{gm(f)(x-ot-a.dl_s)=f_s(1_A)a.dl_s} is well-defined.

	Let us show that  $\gm(f)$ is an $A \rtimes_\0 S$-bimodule mapping. 
	We have
	\begin{align*}
		\gm(f)((x\ot_{KE(S)}\ol{a\dl_s})\cdot\ol{b\dl_t})&\overset{\cref{right crossprod-action}}{=}\gm(f)(x\ot_{KE(S)}(\ol{a\dl_s}\cdot\ol{b\dl_t}))\\
		&\overset{\cref{gm(f)(x-ot-a.dl_s)=f_s(1_A)a.dl_s}}{=}f_x(1_A)\cdot(\ol{a\dl_s}\cdot\ol{b\dl_t})=(f_x(1_A)\cdot \ol{a\dl_s})\cdot\ol{b\dl_t}\\
		&\overset{\cref{gm(f)(x-ot-a.dl_s)=f_s(1_A)a.dl_s}}{=}\gm(f)(x\ot_{KE(S)}\ol{a\dl_s})\cdot\ol{b\dl_t}.
	\end{align*}
	Furthermore, 
	\begin{align*}
		\gm(f)(\ol{b\dl_t}\la(x\ot_{KE(S)}\ol{a\dl_s}))&\overset{\cref{a.dl_s(x-ot-b.dl_t)}}{=}\gm(f)(t\cdot x\ot_{KE(S)}(\ol{b\dl_t}\cdot\ol{a\dl_s}))\\
		&\overset{\cref{gm(f)(x-ot-a.dl_s)=f_s(1_A)a.dl_s}}{=}f_{t\la x}(1_A)\cdot (\ol{b\dl_t}\cdot\ol{a\dl_s}).
	\end{align*}
	Since
	\begin{align*}
		f_{t\la x}(1_A)&=(t\la f_x)(1_A)\overset{\cref{(sf)(a)=sf(s-inv-a)}}{=}t\la f_x(t\m \la 1_A)\overset{\cref{left KS-mod A}}{=}t\la f_x(\0_{t\m}(1_t1_A))\\
		&\overset{\cref{left KS-mod M}}{=}\ol{1_t\dl_t}\cdot f_x(1_{t\m})\cdot\ol{1_{t\m}\dl_{t\m}},
	\end{align*}
	it follows that
	\begin{align*}
		\gm(f)(\ol{b\dl_t}\la(x\ot_{KE(S)}\ol{a\dl_s}))&=\ol{1_t\dl_t}\cdot f_x(1_{t\m})\cdot\ol{1_{t\m}\dl_{t\m}}\cdot (\ol{b\dl_t}\cdot\ol{a\dl_s})\\
		&=\ol{1_t\dl_t}\cdot f_x(1_{t\m}1_A)\cdot(\ol{1_{t\m}\dl_{t\m}}\cdot \ol{b\dl_t})\cdot\ol{a\dl_s}.
	\end{align*}
	Now,
	\begin{align*}
		\ol{1_t\dl_t}\cdot f_x(1_{t\m}1_A)\cdot(\ol{1_{t\m}\dl_{t\m}}\cdot \ol{b\dl_t})
		&=\ol{1_t\dl_t}\cdot 1_{t\m}\cdot f_x(1_A)\cdot \ol{\0_{t\m}(b)\dl_{t\m t}}\\
		&\overset{\cref{A-bimod M}}{=}(\ol{1_t\dl_t}\cdot \ol{1_{t\m}\dl_1})\cdot f_x(1_A)\cdot \ol{\0_{t\m}(b)\dl_1}\\
		&\overset{\cref{A-bimod M}}{=} \ol{\0_t(1_{t\m})\dl_t}\cdot (f_x(1_A)\cdot \0_{t\m}(b))\\
		&=\ol{1_t\dl_t}\cdot f_x(\0_{t\m}(b))=\ol{1_t\dl_t}\cdot \0_{t\m}(b)\cdot f_x(1_A)\\
		&\overset{\cref{A-bimod M}}{=}(\ol{1_t\dl_t}\cdot \ol{\0_{t\m}(b)\dl_1})\cdot f_x(1_A)\\
		&=\ol{(\0_t(\0_{t\m}(b))\dl_t}\cdot f_x(1_A)=\ol{b\dl_t}\cdot f_x(1_A).
	\end{align*}
	Thus,
	\begin{align*}
		\gm(f)(\ol{b\dl_t}\la(x\ot_{KE(S)}\ol{a\dl_s}))&=\ol{b\dl_t}\cdot f_x(1_A)\cdot\ol{a\dl_s}\overset{\cref{gm(f)(x-ot-a.dl_s)=f_s(1_A)a.dl_s}}{=}\ol{b\dl_t}\cdot\gm(f)(x\ot_{KE(S)}\ol{a\dl_s}),
	\end{align*}
	completing the proof that  $\gm(f)\in \Hom_{(A \rtimes_\0 S)^e}(X\ot_{KE(S)} (A \rtimes_\0 S) ,M).$
\end{proof}

\begin{lem}
	There is a $K$-linear map
	\begin{align*}
		\eta:\Hom_{(A \rtimes_\0 S)^e}(X\ot_{KE(S)}(A \rtimes_\0 S),M)\to\Hom_{KS}(X,\Hom_{A^e}(A,M))
	\end{align*}
	such that, for all $f\in\Hom_{(A \rtimes_\0 S)^e}(X\ot_{KE(S)}(A \rtimes_\0 S),M)$,
	\begin{align}\label{eta(f)_x(a)=f(x-ot-a.dl_1)}
		\eta(f)_x(a)=f(x\ot_{KE(S)}\ol{a\dl_1}).
	\end{align}
\end{lem}
\begin{proof}
	Let us show that $\eta(f)_x$ is an $A^e$-module map. For all $a,b,c\in A$ we have
	\begin{align*}
		\eta(f)_x(bac)&\overset{\cref{eta(f)_x(a)=f(x-ot-a.dl_1)}}{=}f(x\ot_{KE(S)}\ol{bac\dl_1})=f(x\ot_{KE(S)}\ol{b\dl_1}\cdot\ol{a\dl_1}\cdot\ol{c\dl_1})\\
		&\overset{\cref{right crossprod-action}}{=}f((1\cdot x\ot_{KE(S)}\ol{b\dl_1}\cdot\ol{a\dl_1})\cdot\ol{c\dl_1})\overset{\cref{a.dl_s(x-ot-b.dl_t)}}{=}f(\ol{b\dl_1}\cdot(x\ot_{KE(S)}\ol{a\dl_1})\cdot\ol{c\dl_1})\\
		&=\ol{b\dl_1}\cdot f(x\ot_{KE(S)}\ol{a\dl_1})\cdot\ol{c\dl_1}\overset{\cref{A-bimod M}}{=}b\cdot f(x\ot_{KE(S)}\ol{a\dl_1})\cdot c\\
		&\overset{\cref{eta(f)_x(a)=f(x-ot-a.dl_1)}}{=}b\cdot \eta(f)_x(a)\cdot c.
	\end{align*}
	Thus, $\eta(f)_x\in\Hom_{A^e}(A,M)$.

	We now prove that $\eta(f)$ is a homomorphism of left $KS$-modules.
	%$\eta(f)\in\Hom_{KS}(X,\Hom_{A^e}(A,M))$. 
	For all $s\in S$, $x\in X$ and $a\in A$ we have
	\begin{align*}
		(s\cdot \eta(f)_x)(a)&\overset{\cref{(sf)(a)=sf(s-inv-a)}}{=}s\la \eta(f)_x(s\m\la a)\overset{\cref{eta(f)_x(a)=f(x-ot-a.dl_1)}}{=}s\la f(x\ot_{KE(S)}\ol{(s\m\la a)\dl_1})\\
		&\overset{\cref{left KS-mod A}}{=}s\la f(x\ot_{KE(S)}\ol{\0_{s\m}(1_sa)\dl_1})\\
		&\overset{\cref{left KS-mod M}}{=}\ol{1_s\dl_s}\la f(x\ot_{KE(S)}\ol{\0_{s\m}(1_sa)\dl_1})\cdot\ol{1_{s\m}\dl_{s\m}}\\
		&=f(\ol{1_s\dl_s}\la(x\ot_{KE(S)}\ol{\0_{s\m}(1_sa)\dl_1})\cdot\ol{1_{s\m}\dl_{s\m}})\\
		&\overset{\cref{right crossprod-action}}{=}f(\ol{1_s\dl_s}\la(x\ot_{KE(S)}\ol{\0_{s\m}(1_sa)\dl_1}\cdot\ol{1_{s\m}\dl_{s\m}}))\\
		&\overset{\cref{a.dl_s(x-ot-b.dl_t)}}{=}f(s\la x\ot_{KE(S)}\ol{1_s\dl_s}\cdot\ol{\0_{s\m}(1_sa)\dl_1}\cdot\ol{1_{s\m}\dl_{s\m}})\\
		&=f(s\la x\ot_{KE(S)}\ol{1_sa\dl_s}\cdot\ol{1_{s\m}\dl_{s\m}})=f(s\la x\ot_{KE(S)}\ol{1_sa\dl_{ss\m}})\\
		&=f(s\la x\ot_{KE(S)}\ol{1_sa\dl_1})\overset{\cref{left KE(S)-action on cross}}{=}f(s\la x\ot_{KE(S)}ss\m\la \ol{a\dl_1})\\
		&=f(s\la x\cdot ss\m\ot_{KE(S)}\ol{a\dl_1})\overset{\cref{x-cdot-b=b-cdot-x}}{=}f(ss\m(s\la x)\ot_{KE(S)}\ol{a\dl_1})\\
		&=f((ss\m s)\la x\ot_{KE(S)}\ol{a\dl_1})=f(s\la x\ot_{KE(S)}\ol{a\dl_1})	\overset{\cref{eta(f)_x(a)=f(x-ot-a.dl_1)}}{=}\eta(f)_{s\cdot x}(a).
	\end{align*}
	Thus, $\eta(f)\in\Hom_{KS}(X,\Hom_{A^e}(A,M))$, and so $\eta$ is well-defined.
\end{proof}

\begin{lem}
	The maps $\gm$ and $\eta$ are inverse to each other.
\end{lem}
\begin{proof}
	Let us show that $\gm\circ\eta=\id$. For all $f\in \Hom_{(A \rtimes_\0 S)^e}(X\ot_{KE(S)}(A \rtimes_\0 S),M)$ we have
	\begin{align*}
		\gm(\eta(f))(x\ot_{KE(S)}\ol{a\dl_s})&\overset{\cref{gm(f)(x-ot-a.dl_s)=f_s(1_A)a.dl_s}}{=}\eta(f)_x(1_A)\cdot \ol{a\dl_s}\overset{\cref{eta(f)_x(a)=f(x-ot-a.dl_1)}}{=}f(x\ot_{KE(S)}\ol{1_A\dl_1})\cdot \ol{a\dl_s}\\
		&=f((x\ot_{KE(S)}\ol{1_A\dl_1})\cdot \ol{a\dl_s})\overset{\cref{right crossprod-action}}{=}f(x\ot_{KE(S)}\ol{1_A\dl_1}\cdot \ol{a\dl_s})\\
		&=f(x\ot_{KE(S)}\ol{a\dl_s}),
	\end{align*}
	whence $\gm(\eta(f))=f$, as desired.

	We now show that $\eta\circ\gm=\id$. Take $g\in\Hom_{KS}(X,\Hom_{A^e}(A,M))$. For all $x\in X$ and $a\in A$ we have
	\begin{align*}
		\eta(\gm(g))_x(a)&\overset{\cref{eta(f)_x(a)=f(x-ot-a.dl_1)}}{=}\gm(g)(x\ot_{KE(S)}\ol{a\dl_1})\overset{\cref{gm(f)(x-ot-a.dl_s)=f_s(1_A)a.dl_s}}{=}g_x(1_A)\cdot \ol{a\dl_1}\\
		&\overset{\cref{A-bimod M}}{=}g_x(1_A)\cdot a=g_x(1_A\cdot a)=g_x(a),
	\end{align*}
	whence $\eta(\gm(g))=g$, as desired.
\end{proof}

\begin{prop}\label{nat-iso-Homs}
	\begin{enumerate}
		\item\label{contravar-Homs-nat-iso} For arbitrary $A \rtimes_\0 S$-bimodule $M$ the functors 
		\begin{align*}
			\Hom_{KS}(-,\Hom_{A^e}(A,M)):KS\Mod\to K\Mod
		\end{align*}
		and
		\begin{align*}
			\Hom_{(A \rtimes_\0 S)^e}(-\ot_{KE(S)}(A \rtimes_\0 S),M):KS\Mod\to K\Mod
		\end{align*}
		are naturally isomorphic.

		\item\label{covar-Homs-nat-iso} For arbitrary left $KS$-module $X$ the functors
		\begin{align*}
			\Hom_{KS}(X,\Hom_{A^e}(A,-)):(A \rtimes_\0 S)^e\Mod\to K\Mod
		\end{align*}
		and
		\begin{align*}
			\Hom_{(A \rtimes_\0 S)^e}(X\ot_{KE(S)}(A \rtimes_\0 S),-):(A \rtimes_\0 S)^e\Mod\to K\Mod
		\end{align*}
		are naturally isomorphic.
	\end{enumerate}
\end{prop}
\begin{proof} Write $\Lb = A \rtimes_\0 S.$

	\cref{contravar-Homs-nat-iso}. Take an arbitrary morphism $\vf:X\to X'$ of left $KS$-modules and consider the diagram
	\begin{align}\label{diagr-contravar-Homs}
		\begin{tikzcd}[column sep=3.5cm,ampersand replacement=\&]
			{\Hom_{KS}(X,\Hom_{A^e}(A,M))} \& {\Hom_{KS}(X',\Hom_{A^e}(A,M))} \\
			{\Hom_{\Lb^e}(X\ot_{KE(S)} \Lb ,M)} \& {\Hom_{\Lb^e}(X'\ot_{KE(S)}\Lb ,M),}
			\arrow[swap,"{\Hom_{KS}(\vf,\Hom_{A^e}(A,M))}", from=1-2, to=1-1]
			\arrow["{\Hom_{\Lb^e}(\vf\ot_{KE(S)}\Lb,M)}", from=2-2, to=2-1]
			\arrow[swap,"\gm", from=1-1, to=2-1]
			\arrow["\gm'", from=1-2, to=2-2]
		\end{tikzcd}
	\end{align}
	where $\gm'$ is defined as $\gm$ in \cref{construction-of-gm}, but with $X$ replaced by $X'$. For any $f\in \Hom_{KS}(X',\Hom_{A^e}(A,M))$ let $g$ be its image under $\Hom_{KS}(\vf,\Hom_{A^e}(A,M))$. Then 
	\begin{align*}
		\gm(g)(x\ot_{KE(S)}\ol{a\dl_s})\overset{\cref{gm(f)(x-ot-a.dl_s)=f_s(1_A)a.dl_s}}{=}g_x(1_A)\cdot\ol{a\dl_s}=f_{\vf(x)}(1_A)\cdot\ol{a\dl_s}.
	\end{align*}
	Since $\Hom_{\Lb^e}(\vf\ot_{KE(S)}\Lb,M)(\gm'(f))(x\ot_{KE(S)}\ol{a\dl_s})$ equals
	\begin{align*}
		\gm'(f)(\vf(x)\ot_{KE(S)}\ol{a\dl_s})=f_{\vf(x)}(1_A)\cdot\ol{a\dl_s},
	\end{align*}
	diagram \cref{diagr-contravar-Homs} commutes, which proves \cref{contravar-Homs-nat-iso}.

	\cref{covar-Homs-nat-iso}. Take an arbitrary morphism $\psi:M\to M'$ of $\Lb$-bimodules and consider the diagram
	\begin{align}\label{diagr-covar-Homs}
		\begin{tikzcd}[column sep=3.5cm,ampersand replacement=\&]
			{\Hom_{KS}(X,\Hom_{A^e}(A,M))} \& {\Hom_{KS}(X,\Hom_{A^e}(A,M'))} \\
			{\Hom_{\Lb^e}(X\ot_{KE(S)}\Lb,M)} \& {\Hom_{\Lb^e}(X\ot_{KE(S)}\Lb,M'),}
			\arrow["{\Hom_{KS}(X,\Hom_{A^e}(A,\psi))}", from=1-1, to=1-2]
			\arrow[swap,"{\Hom_{\Lb^e}(X\ot_{KE(S)}\Lb,\psi)}", from=2-1, to=2-2]
			\arrow[swap,"\gm", from=1-1, to=2-1]
			\arrow["\gm'", from=1-2, to=2-2]
		\end{tikzcd}
	\end{align}
	where $\gm'$ is as in \cref{construction-of-gm}, but with $M$ replaced by $M'$. Given a morphism $f\in \Hom_{KS}(X,\Hom_{A^e}(A,M))$, let $g=\Hom_{KS}(X,\Hom_{A^e}(A,\psi))(f)$. Then 
	\begin{align*}
		\gm'(g)(x\ot_{KE(S)}\ol{a\dl_s})\overset{\cref{gm(f)(x-ot-a.dl_s)=f_s(1_A)a.dl_s}}{=}g_x(1_A)\cdot\ol{a\dl_s}=\psi(f_x(1_A))\cdot\ol{a\dl_s}.
	\end{align*}
	Since $\Hom_{\Lb^e}(X\ot_{KE(S)}\Lb,\psi)(\gm(f))(x\ot_{KE(S)}\ol{a\dl_s})$ equals

	\begin{align*}
		\psi(\gm(f)(x \ot_{KE(S)}\ol{a\dl_s}))
\overset{\cref{gm(f)(x-ot-a.dl_s)=f_s(1_A)a.dl_s}}{=}  \psi(f_x(1_A)\cdot\ol{a\dl_s})=\psi(f_x(1_A))\cdot\ol{a\dl_s},
	\end{align*} 
		diagram \cref{diagr-covar-Homs} commutes, which proves \cref{covar-Homs-nat-iso}.
\end{proof}

\begin{cor} \label{T_2T_1-iso-T}
	The functors $T_2T_1$ and $T$ are naturally isomorphic.
\end{cor}
\begin{proof}  As above, denote 
$\Lb = A \rtimes_\0 S.$ Applying \cref{nat-iso-Homs}\cref{covar-Homs-nat-iso} with $X=KE(S)$ we see that $T_2T_1$ is naturally isomorphic to 
	\begin{align*}
		\Hom_{\Lb^e}(KE(S)\ot_{KE(S)}\Lb,-):\Lb^e\Mod\to K\Mod.
	\end{align*}
	Let $\vf:\Lb\to KE(S)\ot_{KE(S)}\Lb$ be the isomorphism of $\Lb$-bimodules from \cref{l_AsemidirSisoBsemidirS}. For any morphism of $\Lb$-bimodules $\psi:M\to M'$ consider the following diagram
	\begin{align}\label{diagr-Hom(Lb_M)-and-Hom(B-ot-Lb_M)}
		\begin{tikzcd}[column sep=3.5cm,ampersand replacement=\&]
			{\Hom_{\Lb^e}(\Lb,M)} \& {\Hom_{\Lb^e}(\Lb,M')} \\
			{\Hom_{\Lb^e}(KE(S)\ot_{KE(S)}\Lb,M)} \& {\Hom_{\Lb^e}(KE(S)\ot_{KE(S)}\Lb,M').}
			\arrow["{\Hom_{\Lb^e}(\Lb,\psi)}", from=1-1, to=1-2]
			\arrow[swap,"{\Hom_{\Lb^e}(KE(S)\ot_{KE(S)}\Lb,\psi)}", from=2-1, to=2-2]
			\arrow["{\Hom_{\Lb^e}(\vf,M)}", from=2-1, to=1-1]
			\arrow[swap,"{\Hom_{\Lb^e}(\vf,M')}", from=2-2, to=1-2]
		\end{tikzcd}
	\end{align}
	Given $f\in \Hom_{\Lb^e}(KE(S)\ot_{KE(S)}\Lb,M)$, we have
	\begin{align*}
		(\Hom_{\Lb^e}(\Lb,\psi)\circ\Hom_{\Lb^e}(\vf,M))(f)&=\psi\circ (f\circ\vf),\\
		(\Hom_{\Lb^e}(\vf,M')\circ\Hom_{\Lb^e}(KE(S)\ot_{KE(S)}\Lb,\psi))(f)&=(\psi\circ f)\circ\vf,
	\end{align*}
	so \cref{diagr-Hom(Lb_M)-and-Hom(B-ot-Lb_M)} establishes a natural isomorphism between $\Hom_{\Lb^e}(KE(S)\ot_{KE(S)}\Lb,-)$ and $\Hom_{\Lb^e}(\Lb,-)=T$. Thus, $T_2T_1\cong T$.
\end{proof}



In an analogy with the homology case we give the next:

\begin{lem}\label{lem:for0-cohomology} Let    $\0$ be a  unital action of an   inverse monoid $S$ on  an algebra $A$ over a commutative ring $K.$ Let  $M$ be an $A\rtimes_\0 S$-bimodule and write 
$$M^A = \{x\in M \; \mid \; a\cdot x =x\cdot a  \;\;\; \text{for all} \;\;\; a\in A\}.$$   Then $M^A$ is a left $KS$-submodule of $M$ and the
$K$-module mapping
 $${\psi}': \Hom_{A^e}(A,M) \to   M^A, \;\;\; f   \mapsto  f(1_A),$$  is an isomorphism of left $KS$-modules.
 \end{lem}
 \begin{proof} It is well-known and  readily seen  that ${\psi}'$ is a well-defined $K$-module isomorphism. Moreover, for any $x\in M^A, s \in S$ and $a \in A,$ in view of  \eqref{left KS-mod A},  \eqref{left KS-mod M} and \eqref{A-bimod M}, we see that
\begin{align*}
a\cdot (s\cdot x) &= 
 (\overline{a\delta _1} \overline{ 1_s \delta _s}) \cdot x \cdot (\overline{ 1_{s\m} \delta _{s\m}})=
(\overline{ 1_s \delta _s  \theta _{s\m}(a1_{s})\delta _1}) \cdot x \cdot (\overline{ 1_{s\m} \delta _{s\m}})\\
&= (\overline{ 1_s \delta _s}) \cdot 
(\theta _{s\m}(a1_{s}) \cdot x) \cdot 
(\overline{ 1_{s\m} \delta _{s\m}})=
(\overline{ 1_s \delta _s}) \cdot 
(  x\cdot \theta _{s\m}(a1_{s})) \cdot 
(\overline{ 1_{s\m} \delta _{s\m}})\\
&=(\overline{ 1_s \delta _s}) \cdot 
  x\cdot (\overline{\theta _{s\m}(a1_{s}) 
 1_{s\m} \delta _{s\m}})
 =(\overline{ 1_s \delta _s}) \cdot 
  x\cdot (\overline{ 1_{s\m} \delta _{s\m} a\delta_1})= (s\cdot x)\cdot a,
\end{align*} showing that $M^A$ is a $KS$-submodule of $M.$ Finally, for any $f \in  \Hom_{A^e}(A,M)$
and $s\in S,$ using \eqref{left KS-mod M}, \eqref{A-bimod M} and \eqref{(sf)(a)=sf(s-inv-a)} we have that 
\begin{align*}
{\psi}'(s\cdot f) &=  (s\cdot f)(1_A) = 
s\cdot f(s\m \cdot 1_A)= 
(\overline{ 1_s \delta _s} ) \cdot f(1_{s\m}) \cdot (\overline{ 1_{s\m} \delta _{s\m}})\\
&= (\overline{ 1_s \delta _s} ) \cdot (f(1_A)\cdot 1_{s\m}) \cdot (\overline{ 1_{s\m} \delta _{s\m}})
= (\overline{ 1_s \delta _s} ) \cdot f(1_A) \cdot (\overline{ 1_{s\m} \delta _{s\m}})\\
&= s \cdot f(1_A) = s\cdot {\psi}' (f),
\end{align*} proving that ${\psi}' $ is a left $KS$-module isomorphism.
	\end{proof}



