 Recall from  Definition~\ref{def:Inv Monoid (co)homol} that, given a left $KS$-module $N$, the cohomology of $S$ with values in $N$ is defined by $H^n(S,N)=\Ext^n_{KS}(KE(S),N).$


\begin{thrm}\label{E^pq_2=>H^(p+q)}
	Let $\0$ be a unital action of an inverse monoid $S$ on an algebra $A$  over a field $K.$
	%and $\Lb=A\rtimes_\0 S$. 
	Then for any $A\rtimes_\0 S$-bimodule $M$ there exists a third quadrant cohomology spectral sequence
	\begin{align*}
		E^{p,q}_2=H^p(S,(R^qT_1)M)\impl H^{p+q}(A\rtimes_\0 S,M).
	\end{align*} 
\end{thrm}
\begin{proof}We claim  that the functor $T_1$ sends injective 
	$(A \rtimes_\0 S)^e$-modules to right $T_2$-acyclic $KS$-modules. Indeed, let $Q$ be an injective $(A \rtimes_\0 S)^e$-module and $P_\bullet\to KE(S)$ be a projective resolution of $KE(S)$ in $KS\Mod$. In particular, the functor 
	$\Hom  _{(A \rtimes_\0 S)^e}(-, Q)$ is exact. 
	 Recall that, since $K$ is a filed, the $K$-algebra  $KE(S)$ is  von Neumann regular, and therefore $A \rtimes_\0 S$ is  a flat $KE(S)$-module. Hence, the functor 
	$-\ot_{KE(S)} (A \rtimes_\0 S)$ is also exact. Then 
	\begin{align*}
		(R^nT_2)(T_1(Q))&=\Ext^n_{KS}(KE(S),\Hom_{A^e}(A,Q))=H^n(\Hom_{KS}(P_\bullet,\Hom_{A^e}(A,Q))).
	\end{align*}
	By \cref{nat-iso-Homs}\cref{covar-Homs-nat-iso} the latter equals $H^n(\Hom_{(A \rtimes_\0 S)^e}(P_\bullet\ot_{KE(S)}(A \rtimes_\0 S),Q))$, which is $0$ for all $n\ge 1$, because $\Hom_{(A \rtimes_\0 S)^e}(-,Q)$ and $-\ot_{KE(S)}(A \rtimes_\0 S)$ are exact. This proves our claim.

	Next, since  the functor $T_2$ is left exact, in view of the natural isomorphism  $T_2T_1\cong T,$ provided  by \cref{T_2T_1-iso-T},  and
	\begin{align*}
		(R^nT)M=\Ext^n_{(A\rtimes_\0 S)^e}(A\rtimes_\0 S,M)=H^n(A\rtimes_\0 S,M),
	\end{align*}
 we obtain from \cite[Theorem 10.47]{Rotman}  the third quadrant Grothendieck spectral sequence
    \begin{equation}\label{eq:CohomSpectralSeqFromRotman}
        E_2^{p,q} = (R^p T_2) (R^q T_1) M \Rightarrow H^{p+q}(A\rtimes_\0 S,M). 
        \end{equation} 
	 Since by definition of cohomology of $S$, we have that 
    $$(R^p T_2) (R^q T_1) M = \operatorname{Ext}_{K S}^p (K E(S), (R^q F_1)M  ) =
    H^p(S, (R^q F_1)M  ),
    $$  the spectral sequence \eqref{eq:CohomSpectralSeqFromRotman} takes the desired form.
\end{proof}

\begin{cor}\label{cor:FlatCondition}
	Under the assumptions of \cref{E^pq_2=>H^(p+q)},  assume that $(A\rtimes_\0 S)^e$ is flat as a right $A^e$-module. Then for any $A\rtimes_\0 S$-bimodule $M$ there exists a third quadrant cohomology spectral sequence
	\begin{align*}
		E^{p,q}_2=H^p(S,H^q(A,M))\impl H^{p+q}(A\rtimes_\0 S,M).
	\end{align*} 
\end{cor}
\begin{proof}
	Since  $(A\rtimes_\0 S)^e$ is a flat right $A^e$-module, it follows from \cite[Corollary 3.6A]{Lam} that any injective left $(A\rtimes_\0 S)^e$-module is an injective left $A^e$-module. Thus, any injective  resolution of $M$ in $(A\rtimes_\0 S)^e\Mod$ is an injective  resolution of $M$ in $A^e\Mod$. Consequently, the right derived functor of $T_1$ computes the Hochschild cohomology of $A$ with values in $M$, i.e.
	\begin{align*}
		(R^qT_1)M=\Ext^q_{A^e}(A,M)=H^q(A,M),
	\end{align*}
	and the result follows from \cref{E^pq_2=>H^(p+q)}.
\end{proof}



\begin{lem}\label{lem:0-cohomology} Let $\0$ be a unital action of an  inverse monoid $S$ on  a $K$-algebra $A$ over a field $K$ and $M$ an $A\rtimes_\0 S$-bimodule. Assume that 
	$(A\rtimes_\0 S)^e $ is flat as a right $A^e$-module. Then there is a  left $KS$-module isomorphism
	$$H^0(A,M)  \cong M^A.  $$
\end{lem}
\begin{proof} In view of Lemma~\ref{lem:for0-cohomology} it is enough to establish a left $KS$-module isomorphism between $H^0(A,M) $ and $\Hom_{A^e}(A,M).$   An isomorphism between these $K$-spaces is well-known and we will easily  show that  it is a  $KS$-isomorphism.

Let 
\begin{equation}\label{eq:InjResolution}
0\to M \to Q_0 \stackrel{d^0}{\to} Q_1 \stackrel{d^1}{\to}  \ldots
 \end{equation} be 
an injective resolution of $M$ in $(A\rtimes_\0 S)^e\Mod.$ Applying to the exact sequence 
$0\to M \to Q_0 \stackrel{d^0}{\to} Q_1$  the left exact functor  $T_1,$ we obtain the exact sequence  of left $KS$-modules and  $KS$-homomorphisms
$$0\to \Hom_{A^e}(A, M) \to   \Hom_{A^e}(A, Q_0) \stackrel{\Hom_{A^e}(A,d^0)}{\longrightarrow }  \Hom_{A^e}(A,  Q_1) .$$
   Then, as in the proof Corollary~\ref{cor:FlatCondition}, we see that the complex \eqref{eq:InjResolution} is also  an injective resolution of $M$ in $A^e\textbf{-Mod}$ and consequently  
 $$H^0(A,M) = {\rm ker}\, (\Hom_{A^e}(A,d^0)).$$
 This gives   the desired isomorphism between the left $KS$-modules $H^0(A,M)$ and  $\Hom_{A^e}(A,M).$ 
\end{proof}



\begin{rem}\label{rem:separableCohom}
    Under the conditions of Corollary~\ref{cor:FlatCondition} assume in addition that $A$ is separable over $K.$ Then   there is  an isomorphism
    \[
         H^n(S, M^A) \cong H^{n}(A\rtimes_\0 S, M), 
    \] where $M^A$ is the $K$-submodule of invariants of $M,$ as defined in Lemma~\ref{lem:for0-cohomology}.

     Indeed, since  $A$ is separable,  $A$ is projective as a left  $A^e$-module, and the spectral sequence collapses on the $p$-axis, so that  by 
    \cite[Proposition 10.26]{Rotman} we obtain an isomorphism
    $$ H^n(S, H^0(A,M)) \cong H^{n}(A\rtimes_\0 S, M).  $$ Finally, by Lemma~\ref{lem:0-cohomology},  
	the left $K S$-modules  $H^0(A,M)$ and $M^A$ are isomorphic.
\end{rem}




