\subsection{Cohomology of $A\rtimes_\0 S $ with $E$-unitary $S$}
 As we did in the case of homology, dealing with an   $E$-unitary $S$ we will abandon  the restriction on $K$ to be a field, replacing it by the flatness of $A$  over $K$ when needed. 

\begin{prop}\label{prop:T1sendInjtoT2acylic}
   Let $\0$ be a unital action of an $E$-unitary inverse monoid $S$ on an algebra $A$  over a commutative ring $K.$ 
   Then  $T_1$ sends injective $(A\rtimes_\0 S)^e$-modules to right $T_2$-acyclic modules.
\end{prop}

\begin{proof} Let $Q$ be an arbitrary injective $(A\rtimes_\0 S)^e$-module.
    We need to show that
    \[
        (R^n T_2)(\operatorname{Hom}_{A^e}(A,Q)) = 0 ,
    \] for all $n > 0.$
     Notice that
    \begin{align*}
        (R^n T_2)(\operatorname{Hom}_{A^e}(A,Q))
        &= R^n(\operatorname{Hom}_{K S}(K E(S),-))(\operatorname{Hom}_{A^e}(A,Q)) \\
        &\cong R^n(\operatorname{Hom}_{K S}(-,\operatorname{Hom}_{A^e}(A,Q)))(K E(S)) \\
       (\text{by Proposition \ref{nat-iso-Homs} (i)}) &\cong R^n(\operatorname{Hom}_{(A\rtimes_\0 S)^e}(- \otimes_{K E(S)} (A\rtimes_\0 S), Q))(K E(S)).
    \end{align*}
    Take a projective resolution  $P_{\bullet} \to K E(S)$  of $K E(S)$ in $K S$-\textbf{Mod}. Then,
    \[
        (R^n T_2)(\operatorname{Hom}_{A^e}(A,Q)) \cong H^n \left( \operatorname{Hom}_{(A\rtimes_\0 S)^e}(P_\bullet \otimes_{K E(S)} (A\rtimes_\0 S), Q)\right).
    \]
    Observe  that   Lemma~\ref{lem:acyclic} states that $H_n(P_{\bullet}\otimes_{K E(S)} (A\rtimes_\0 S))=0$ for all $n\geq 1,$ which means that the complex  $P_{\bullet}\otimes_{K E(S)} (A\rtimes_\0 S)$ is exact at the $n$-th term for all $n\ge 1$. Then the chain complex $\operatorname{Hom}_{(A\rtimes_\0 S)^e}(P_\bullet \otimes_{K E(S)} (A\rtimes_\0 S), Q)$ is also exact at the $n$-th term for all $n \geq 1,$ because $Q$ is injective as an $(A\rtimes_\0 S)^e$-module. Therefore, 
    \[
        H^n \left( \operatorname{Hom}_{(A\rtimes_\0 S)^e}(P_\bullet \otimes_{K E(S)} (A\rtimes_\0 S), Q)\right) = 0,\ \forall n \geq 1,
    \] 
    completing our proof.  \end{proof}


\begin{thrm} \label{teo:EunitaryCohomSpectralSeq}
 Let $\0$ be a unital action of an $E$-unitary inverse monoid $S$ on an algebra $A$  over a commutative ring $K.$ Assume that $A$ is flat over $K.$ Then, for any $(A\rtimes_\0 S)^e$-module $M$ there exists a third quadrant  cohomology spectral sequence $E_r$ such that
    \begin{equation}\label{eq:EunitaryCohomSpectralSeq}
        E_2^{p,q} = H^p (S,H^q(A,M) ) \Rightarrow H^{p+q}(A\rtimes_\0 S, M). 
    \end{equation}
\end{thrm}

\begin{proof}  By Proposition~\ref{prop:T1sendInjtoT2acylic} the functor $T_1$ sends injective $(A\rtimes_\0 S)^e$-modules to right $T_2$-acyclic modules. Then, since   $T_2$ is a  left exact functor and by Corollary~\ref{T_2T_1-iso-T} there is a natural isomorphism  $T_2 T_1 \cong T,$ we are in conditions to apply   \cite[Theorem 10.47]{Rotman}  to obtain the  spectral sequence
\[
        E_2^{p,q} = (R^p T_2)(R^q T_1)M \Rightarrow (R^{p+q}T) M. 
    \]
 Obviously, $$(R^{p+q}T)(-)=H^{p+q}(A\rtimes_\0 S, -)$$ and $$R^p T_2 (-) = \operatorname{Ext}_{K S}^p(K E(S),-)= H^p(S,-),$$
      so that the spectral sequence takes the form
     \begin{equation}\label{eq:AlmostFinalCohomolSpectralSeq}
        E_2^{p,q} = H^p_{K S}(KS, (R^q T_1)M ) \Rightarrow H^{p+q}(A\rtimes_\0 S, M).
	 \end{equation} 

		Thanks to  Lemma~\ref{lem:FlatnessInE-unitaryCase} the right $A^e$-module $(A\rtimes_\0 S)^e$ is flat and, as in the  proof of Corollary~\ref{cor:FlatCondition},
		we conclude that
		\[ 
       R^q T_1(-)=H^q(A,-), 
    \] so that the spectral sequence  
	\eqref{eq:AlmostFinalCohomolSpectralSeq} takes the announced form \eqref{eq:EunitaryCohomSpectralSeq}.
  \end{proof}


  If $K$ is a field, then the flatness of $A$ over $K$ is guaranteed, so that we immediately obtain the next:

  \begin{cor}
   Let $\0$ be a unital action of an $E$-unitary inverse monoid $S$ on an algebra $A$  over a field $K.$  Then, for any $(A\rtimes_\0 S)^e$-module $M$ there exists a third quadrant  cohomology spectral sequence $E_r$  of the form \eqref{eq:EunitaryCohomSpectralSeq}.
   \end{cor}



