\begin{equation}\label{eq:SteinbergHomology}
	H_{n}(A_K(\sG), M) \cong  H_n({\mathcal S}^{a}(\sG ), M/[{\mathcal L}( \sG ^{(0)}), M]),
	\end{equation} where the left $K {\mathcal S}^{a}(\sG )$-module structure on $M$ is given by 
	\begin{equation}\label{eq:SliceLeftAction}
	U \cdot x =  (1_{{\bf r} (U)} \Delta_U) \cdot  x \cdot (1_{{\bf s} (U)} \Delta_{U\m}), 
	\end{equation} for any  $U \in {\mathcal S}^{a}(\sG )$ 
	and
	 $ x \in M.$
