\section{Preliminaries}
\label{sec:prelims}
Given a finite group $G$, let $\pi(G)$ denote the primes dividing the order of $G$.
We begin by defining our main object of study.
\begin{definition}
Given a finite group $G$, the \textit{prime simplicial complex} $\Pi(G)$ of $G$ is a partially ordered set, consisting of all subsets $S = \{p_1, p_2, \dots, p_k\} \subseteq \pi(G)$ such that $G$ contains an element of order $p_1p_2 \dots p_k$. 
%The partial ordering on $\Pi(G)$ is inclusion.
\end{definition}

Each element $S$ of $\Pi(G)$ is called a \textit{prime simplex}. In a slight abuse of terminology, we will often refer to a prime simplex not only as a set of primes, but also as the product of primes contained within it.

\begin{example}
\begin{enumerate}
    \item Let $G=S_n$. The prime simplices of $\Pi(G)$ consist of all subsets of distinct primes $\{p_1,p_2\dots, p_k\}$ with $p_1+p_2+ \dots +p_k\leq n$.
    \item If $G$ is nilpotent, then $\Pi(G)$ consists of all subsets of $\pi(G)$.
\end{enumerate}

\end{example}


We record some elementary properties of prime simplicial complexes.
\begin{lemma}
Let $G$ be a group, $H\leq G$ and $N \lhd G.$ \begin{enumerate}
    \item    If $S$ is a prime simplex in $H$ then it is also a prime simplex in $G.$ 
    \item If $S$ is a prime simplex in $G/N,$ then it is also a prime simplex in $G.$
\end{enumerate}

\end{lemma}

\begin{lemma} \label{directprod}
    Let $G_1$ and $G_2$ be finite groups. Then $S$ is a simplex in $G=G_1 \times G_2$ if and only if there exist simplices $S_i \in G_i$ with $S=S_1 \cup S_2$. In particular, if $G_1$ is unrecognisable by prime simplicial complex, then so is $G$.
\end{lemma}
\begin{proof}
The first assertion follows directly from the fact that the order of an element $(g_1,g_2)$ in $G$ is the lowest common multiple of $|g_1|$ and $|g_2|$. Therefore, if $G_1$ and $H$ have $\Pi(G_1) =\Pi(H)$, then $\Pi(G) = \Pi(H \times G_2)$. The second assertion follows.
\end{proof}


We now highlight the connections in recognisability between the prime graph, prime simplicial complex and spectrum of a group.

\begin{lemma}
\label{graph_imps}
Let $G$ be a finite group.
    \begin{enumerate}
        \item If $G$ is recognizable by prime graph, then it is recognizable by prime simplicial complex, and by spectrum.
        \item If $G$ is unrecognizable by spectrum, then it is unrecognizable by prime simplicial complex, and by prime graph.
    \end{enumerate}
    \begin{proof}
The first result follows directly from the fact that the element orders encoded in the prime graph are contained in both the prime simplicial complex and spectrum for $G$. The second result is the contrapositive of the first.
\end{proof}
\end{lemma}
In light of \Cref{graph_imps}, we often analyse the prime simplicial complex of a group by beginning with its prime graph. We briefly recall some graph-theoretic terminology. A \textit{(co)-clique} in a graph is a subset of the vertices that are all pairwise (non)-adjacent. A vertex in a graph is \textit{universal} if it is adjacent to every other vertex in the graph.

We now proceed with some further preliminary results.

\begin{lemma}\label{centralizerproof}
    Let $G$ be finite group, $p$ be a prime divisor of $G$ and $S$ be a prime simplex of $G$ not containing $p.$ Then the following are equivalent. 
    \begin{enumerate}
        \item $\{p\} \cup S$ is a maximal simplex of $G$
        \item There exists an element $g_p$ or order $p$ such that $\{p\}\cup S$ is a maximal simplex of $C_G(g_p).$
    \end{enumerate}
\end{lemma}
\begin{proof}
First assume that $\{p\} \cup S$ is a maximal simplex of $G.$ Then there is an element $x\in G$ of order $p\prod_{s\in S} s,$ so $x^{\prod_{s\in S} s}$ has order $p$ and $x^p$ has order $\prod_{s\in S} s.$ Then $x\in C_G(x^{\prod_{s\in S} s}),$ so $\{p\} \cup S$ is a simplex of $C_G(x^{\prod_{s\in S} s})$ and it is maximal as it is maximal in $G.$ \par 
Now assume that $\{p\}\cup S$ is a maximal simplex of $C_G(g_p)$ for some element $g_p$ of order $p.$ Then $\{p\}\cup S$ is a simplex in $G.$ We show maximality in $G$ by contradiction. Assume there exists a prime $r$ such that $r\not \in\{p\}\cup S$ and $\{r\}\cup\{p\}\cup S$ is a simplex. Then repeating the same argument as earlier,  $\{r\}\cup\{p\}\cup S$ is a simplex of $C_G(g_p),$ which is a contradiction.
\end{proof}
Recall that the \textit{solvable radical} $\mathrm{Sol}(G)$ of a finite group $G$ is its unique largest normal solvable subgroup.
\begin{proposition}[{\cite[Proposition 1]{vasil2005connection}}]
\label{vas_indep_set}
 Let $G$ be a finite group and let $\mathrm{Sol}(G)$ be the solvable radical of $G$. For every subset $\rho\subseteq\pi(G)$  with $|\rho|\geq 3$ that are pairwise non-adjacent in $\Gamma(G)$, the intersection $\rho \cap \pi(\mathrm{Sol}(G))$ contains at most one prime. 
\end{proposition}


We will require the following number-theoretic results in the sections that follow.

\begin{lemma}[{\cite[Lemma A.1(i)]{BG}}]
\label{mult_order_lemma}
    Let $p\neq r$ be a prime and let $i$ be the smallest integer such that $r\mid q^i-1.$ Then $r$ divides $q^m-1$ if any only if $i$ divides $m.$
\end{lemma}




\begin{theorem}[Zsigmondy's Theorem]\label{zsigmondy}
 Let $1\leq b < a$ such that $(a,b)=1$ and $n\in \mathbb{N}.$ Then $a^n-b^n$ has a primitive prime divisor unless one of the following holds. \begin{enumerate}
     \item $a=2,$ $b=1,$ $n=1,6$,
     \item \label{zsig_square} $n=2,$ $a+b=2^m$ for some $m\geq 1.$
 \end{enumerate}   
\end{theorem}
Note that if one considers part (\ref{zsig_square}) with $b=1$, then  $a-1$ has at least two distinct prime divisors provided that $a>3$. In this case, we will abuse terminology and define $2$ to be a primitive prime divisor of $a-1$, and a primitive prime divisor of $a^2-1$ to be an odd prime divisor of $a-1$.



\begin{lemma}[{\cite{MR2076124}}]
    \label{2-3prime}
Suppose $n$ and $n+1$ are consecutive prime powers. Then one of the following holds.
\begin{enumerate}
    \item $(n,n+1) = (2^k,2^k+1)$ for some $k\geq 1$ a power of two and $n+1$ is a \textit{Fermat} prime.
    \item $(n,n+1) = (2^l-1,2^l)$ for some prime $l \geq 3$, and $n$ is a \textit{Mersenne} prime.
\item $(n,n+1)=(8,9)$.
\end{enumerate}
    % The only solutions to the equation $|2^i-3^j| = 1$ for positive integral $i,j$ are are $(i,j)=(1,1),(2,1)$ and $(3,2)$.
\end{lemma}
\begin{lemma}
[{\cite{crescenzo1975diophantine,khosravi2004alternating}}]
\label{dio_eqn}
With the exception of the solutions $(239)^2-2(13)^4=-1$ and $(3^5)-2(11)^2 = 1$, every solution of the equation
$p^a-2r^b=\pm 1$ with $p,r$ prime and $a,b>1$ has $a=b=2$.
\end{lemma}
\begin{lemma}\label{q4lemma}
    Let $q\geq 4.$ Then $\frac{q^4-1}{(4,q-1)}$ has at least 3 distinct prime divisors. 
\end{lemma}

\begin{proof}
    Note that $(q^4-1)$ factorizes as $(q^2-1)(q^2+1)=(q-1)(q+1)(q^2+1).$ By \Cref{zsigmondy}, $q-1,$ $q^2-1$ and $q^4-1$ all have a primitive prime divisor unless $q+1=2^m$ for some $m\in \mathbb{N}$ in which case $\pi (q^2-1)=\pi (q-1).$ However, if $q+1$ is a power of two, then $q-1$ has an odd prime divisor unless $q=3,$ as the only $2$ and $4$ are powers of two with difference two. 
    Note that if $q-1$ is divisible by $4$ then $q^4-1$ is divisible by $8,$ so we do not lose a prime divisor by division by $(4,q-1).$
\end{proof}



\begin{proposition}
\label{q2_divisors}
Let $q$ be a prime power such that $q^2-1$ has exactly two distinct prime divisors. Then $q \in \{4,5,7,8,9,17\}$. Moreover, if $q$ is odd, then $q^2-1$ has exactly two distinct prime divisors if and only if $(q^2-1)/4$ does.
\end{proposition}
\begin{proof}
If $q$ is even, then $q-1$ and $q+1$ are coprime, hence both must be prime powers, and in particular, one must be a power of three. Hence, $q\in \{4,8\}$ by Lemma \ref{2-3prime} as required.
Suppose now that $q$ is odd. Then $q-1$ and $q+1$ are divisible by two, hence one of them must be a power of two. If $q-1=2^k$ for some $k\geq 2$, then $k$ must be equal to three or a power of two,  $q+1 = 2(2^{k-1}+1)$, so $(2^{k-1}+1)$ must be a prime power. Hence
$k-1$ is also equal to three or a power of two by Lemma \ref{2-3prime}, so $k\in \{2,3,4\}$ and $q \in \{5,9,17\}$ as required. If instead $q+1=2^k$ for some $k \geq 2$, then $q$ is a Mersenne prime and $k$ is prime. Thus $q-1 = 2(2^{k-1}-1)$, and $(2^{k-1}-1)$ must be a prime power. So $k--1$ must also be prime and so $k=3$ and $q=7$.

Finally, if $q$ is odd, then $q^2-1$ is a multiple of 8, hence $q^2-1$ is even if and only if $(q^2-1)/4$ is.
\end{proof}
\begin{proposition}[{\cite{MR50615}}]
\label{primes}
For every integer $n$, there is a prime strictly between $n$ and $2n$. Moreover, if $n\geq 25$, there is a prime strictly between $n$ and $6n/5$.
\end{proposition}
\begin{lemma} \label{sumprimes}
Let $n\geq 3$ be an integer. The sum of the primes at most $n$ is strictly greater than $n$.
\end{lemma}
\begin{proof}

We proceed by induction. Let $P(n)$ be the statement that the sum of the primes at most $n$ is strictly greater than $n$, and let $g(n)$ denote the sum of primes at most $n$.  We verify the base cases $P(3)$, $P(4)$ directly. Now suppose $P(k)$ is true, and consider $P(k+1)$. We have $g(\lfloor \frac{k+1}{2} \rfloor) > \lfloor \frac{k+1}{2} \rfloor$. By \Cref{primes}, there is at least one prime $p$ between $\lfloor \frac{k+1}{2} \rfloor$ and $k+1$. Hence
\[
g(k+1) \geq g(\lfloor \frac{k+1}{2} \rfloor)+p > \lfloor \frac{k+1}{2} \rfloor+\lfloor \frac{k+1}{2} \rfloor+1 \geq k+1.
\]
This completes the proof.
\end{proof}


\section{Recognisability by prime simplicial complex}
\label{sec:recog}

In this section we consider the recognisability of finite groups by prime simplicial complex. Recall that the prime graph $\Gamma(G)$ of a finite group $G$ is a subset of its prime simplicial complex $\Pi(G)$. In particular, each group $H$ with $\Pi(H)=\Pi(G)$ must also have $\Gamma(H) = \Gamma(G)$. We therefore begin by recalling some results pertaining to groups with identical prime graphs.

We begin with an adapted version of \cite[Lemma 4.2]{lee2024recognisabilitysporadicgroupsisomorphism}. Recall that the \textit{Fitting subgroup} of a group $G$ is the unique largest normal nilpotent subgroup of $G$. It is generated by the largest normal nilpotent $p$-subgroups $O_p(G)$ for each prime dividing $|G|$. We will also often denote by $O_\pi(G)$ the largest nilpotent normal $\pi$-subgroup of $G$ with $\pi \subseteq \pi(G)$.
\begin{proposition}
\label{semi}
Let $G$ be a finite group with Fitting subgroup $F(G)$. Suppose $G$ contains an element of order $pr$, with $p,r$ primes. Then without loss, $p \mid |G/F(G)|$ and one of the following holds.
\begin{enumerate}
    \item $G/F(G)$ contains an element of order $pr$.
    \item  $G/F(G)$ admits an irreducible module in characteristic $r$ such that an element of order $p$ in $G/F(G)$ fixes a non-zero vector. 
\end{enumerate}
\end{proposition}


\begin{proposition}[{\cite[Theorem 7.1]{MR2213302}}]
Suppose that $G$ is a non-abelian finite simple group such that $2$ is a universal vertex in $\Gamma(G)$. Then $G$ is isomorphic to $A_n$, with $n\geq 5$ and the largest prime $p$ at most $n$ satisfying $p\leq n-3$.
\end{proposition}



\begin{proposition}[{\cite[Theorem~1]{VasilevGorshkov}}] \label{GKthmVasilev}
Suppose $G$ is a finite insoluble group such that $\Gamma(G)$ contains a vertex non-adjacent to 2. Then there exists a non-abelian simple group $S$ and soluble subgroup $K\unlhd G$ such that $S \leq G/K \leq \mathrm{Aut}(S)$.
\end{proposition}
\begin{proposition}[{\cite[Theorem 2]{MR3395066}}]
\label{solv_prime_graphs}
An unlabelled graph $\Gamma$ is isomorphic to the prime graph of a solvable group if and only if the complement $\bar{\Gamma}$ is 3-colourable and triangle-free.
\end{proposition}
\begin{proposition}[{\cite[Theorem 4.2]{MR4506711}}]
\label{num_as_grps}
Let $\pi$ be a finite set of primes.
There are at most $O(|\pi|^7)$ pairwise non-isomorphic almost simple groups $G$ such that
$\pi(G) \subseteq \pi$.
\end{proposition}
% \begin{proposition}[{\cite[Proposition 1]{vasil2005connection}}]
% Let $G$ be a finite group, and let $K$ be the solvable radical of $G$. Then for any subset $\rho \subseteq \pi(G)$ of size at least 3 with every pair of primes in $\rho$ non-adjacent in $\Gamma(G)$, we have $|\rho \cap \pi(K)|\leq 1$. In particular, if  $\Gamma(G)$ contains at least 3 pairwise non-adjacent vertices, then $G$ is insoluble. 
% \end{proposition}
We now can show the following result, which is a consequence of \cite{MR2986582}.

\begin{proposition}
\label{unrec_sol_rad}
    Let $G$ be a finite group. If $G$ is unrecognisable by prime simplicial complex, then either
    \begin{enumerate}
        \item \label{unrec_cond_1} there exists a group $H$ with non-trivial solvable radical with $\Pi(G) = \Pi(H)$, or
        \item The vertex 2 is adjacent to all other primes in $\Gamma(G)$ and $\Pi(G)$ has an odd maximal simplex.
    \end{enumerate}
Moreover, if \ref{unrec_cond_1} holds, then $G$ is unrecognisable by prime simplicial complex.
\end{proposition}

\begin{proof}
Suppose that $G$ is unrecognisable by prime simplicial complex and that for each group $H$ with $\Pi(G) = \Pi(H)$, the solvable radical of $H$ is trivial. Note that $G$ is also unrecognisable by prime graph by \Cref{graph_imps}.
If every prime simplex $s$ in $\Pi(G)$ is such that $2s \in \Pi(G)$, then $\Pi(C_2^k \times G) = \Pi(G)$ for any $k\geq 1$, which is a contradiction. Hence there exists a prime simplex $r\in \Pi(G)$ such that $2r \notin \Pi(G)$. If there exists a prime $p$ dividing $r$ such that $2p \notin \Pi(G)$, then $2p \notin \Gamma(G)$. Hence, by \Cref{GKthmVasilev} $G$ is almost simple, as is any group $H$ with the same prime graph. But by \Cref{num_as_grps}, there are only finitely many almost simple groups $H$ with $\pi(H) \subseteq \pi(G)$, contradicting the unrecognisability of $G$ by prime graph. Therefore, $2$ and $p$ must be adjacent in $\Gamma(G)$. Applying this argument as many times as necessary, we see that 2 must be adjacent to every odd prime in $\Gamma(G)$.
Finally, assume that there exists $N\unlhd G$ such that $N$ is non-trivial and solvable. Then, by \cite[Theorem]{MR2986582}, there exist infinitely many groups with the same spectrum as $G$. Each of these groups also has the same prime simplicial complex as $G$.
\end{proof}

\begin{proposition}
Suppose $G$ is $k$-recognisable by prime simplicial complex for some integer $k$. Then either $G$ is almost simple, or $2\in \Gamma(G)$ is connected to every other vertex, and $\Pi(G)$ has an odd maximal simplex.
\end{proposition}
\begin{proof}
Suppose $G$ is $k$-recognisable by prime simplicial complex for some integer $k$. Then $G$ cannot be soluble by \Cref{unrec_sol_rad}. If $\Gamma(G)$ has a prime $p$ not adjacent to 2, then \Cref{GKthmVasilev} implies that $G$ is almost simple, otherwise it is unrecognisable by \Cref{unrec_sol_rad}. The result follows.
\end{proof}
\begin{lemma}
Let $G$ be a finite group, and let $k$ be the minimum number of prime simplices of $\Pi(G)$ with union equal to $\pi(G)$. Then the direct product $G^m$ is unrecognisable by prime simplicial complex for each $m\geq k$.
\end{lemma}
\begin{proof}
If $m\geq k$, then $\Pi(G^m)$ contains a simplex equal to $\pi(G)$, and hence the simplex lattice is complete. Therefore, $\Pi(G^m)= \Pi(C)$, where $C = \cup_{p \in \pi(G)} C_p$. The result follows from \Cref{unrec_sol_rad}.
\end{proof}

\begin{proposition}
\label{dir_prod}
Let $S$ be a finite group of even order. Then the direct product $G=S^m$, $m\geq 2$ is not recognisable by prime simplicial complex.
\end{proposition}
\begin{proof}
We will show that $G$ has the same prime simplicial complex as $H=G \rtimes C$, where $C= \langle (1\,2)\rangle \leq S_m$. Let $g=(g_1, g_2, \dots, g_m, \sigma) \in H$. If $\sigma=1$, then $g \in G \leq H$, and so all prime simplices dividing the order of $g$ lie in $\Pi(G)$. So now suppose $\sigma=(1\, 2)$. For each $k \geq 1$ we have  
\[
g^{2k} = ((g_1g_2)^k, (g_2g_1)^k, g_3^{2k}, \dots g_m^{2k}, 1)
\]
and 
\[
g^{2k+1} = ((g_1g_2)^kg_1, (g_2g_1)^kg_2, g_3^{2k+1}, \dots g_m^{2k+1}, \sigma)
\]
Noting also that $g_1g_2$ and $g_2g_1$ are conjugate and thus of the same order, we deduce that the order of $g$ divides $2 \times \mathrm{LCM}(|g_1g_2|,|g_3|,\dots |g_m|)$. Now, letting $i \in G$ be an involution, we find that  $g' = (i, g_1g_2, g_3, \dots g_m,1) \in G$ has order a multiple of $|g|$. Hence, $\Pi(H) = \Pi(G)$ as required.
\end{proof}
\begin{remark}
None of the known groups that are not almost simple but recognisable by spectrum are recognisable by prime simplicial complex by \Cref{dir_prod}. This demonstrates that the converse to \Cref{graph_imps} does not hold.
It is unknown if the groups in \Cref{dir_prod} are \textit{unrecognisable} by prime simplicial complex, or just not recognisable. 
\end{remark}
\begin{proposition}
\label{recog_psc}
The group $G = \mathrm{PSL}_2(173)\times \mathrm{PSL}_2(283)$ is recognisable by prime simplicial complex.
\end{proposition}
\begin{proof}
We begin by exhibiting the prime graphs $\Gamma(\mathrm{PSL}_2(173))$ and $\Gamma(\mathrm{PSL}_2(283))$:
