\begin{lemma}
The Held group $\mathrm{He}$ is unrecognisable by prime graph, but recognisable by prime simplicial complex.
\end{lemma}
\begin{proof}
 The group is unrecognisable by prime graph by \cite[Theorem 4]{MR4057271}. By \cite[Theorem 3(4)]{MR1995543}, if $G$ is a finite group with $\Gamma(G) \cong \Gamma(\mathrm{He})$, then $G/F(G)$ is isomorphic to one of: $\mathrm{L}_2(16)$, $\mathrm{L}_2(16).2$, $\mathrm{L}_2(16).4$, $O_8^-(2)$, $O_8^-(2).2$,  $\mathrm{\rm{PSp}}_8(2)$, $\mathrm{He}.2$ or $\mathrm{He}$. Kondrat'ev \cite[p. 84]{MR4057271} shows that the first three cases do not give rise to groups with the same prime graph as $\mathrm{He}$. The groups $O_8^-(2)$, $O_8^-(2).2$,  $\mathrm{\rm{PSp}}_8(2)$ contain an element of order 30, which is not present in $\mathrm{He}$, so these do not arise. Moreover, $\mathrm{He}.2$ has an element of order 42, so that also does not arise. Hence $\Gamma(G)/F(G) \cong \mathrm{He}$. Inspecting the $p$-modular character tables of $\mathrm{He}$, we observe that if $p \neq 17$, then elements of order 17 do not act fixed-point-freely, and if $p=17$, then elements of order 2 do not act fixed point freely. So we must have $F(G)$ being trivial, and $G \cong \mathrm{He}$.
\end{proof}
\begin{lemma}
 The group $\mathrm{M}_{12}$ is unrecognisable by prime simplicial complex.
\end{lemma}
\begin{proof}
The simplices of $\Pi(\mathrm{M}_{12})$ are $\{2,3,5,6,10,11\}$.
By \cite[Theorem 3(5)]{MR1995543}, $\Gamma(\mathrm{M}_{12}) = \Gamma(2^{10}:\mathrm{M}_{11})$, so the result follows by \Cref{unrec_sol_rad}.
\end{proof}
\begin{lemma}
The group $\mathrm{Co}_3$ is unrecognisable by prime simplicial complex.
\end{lemma}
\begin{proof}
The prime simplicial complex of $\mathrm{Co}_3$ contains $2, 3, 5, 6, 7, 10, 11, 14, 15, 21, 22, 23, 30 $. In particular, for every odd number $r$ that appears as a simplex, $2r$ is also a simplex except if $r=21,23$. Inspecting the 2-modular character table of $\mathrm{Co}_3$, we see that there are two 11-dimensional irreducible modules $V,V'$ for $\mathrm{Co}_3$ where elements of orders 21, 23 act fixed-point-freely. Hence $(V^k):\mathrm{Co}_3$ has the same prime simplicial complex as $\mathrm{Co}_3$ for each $k \geq 1$. Therefore, $\mathrm{Co}_3$ is unrecognisable.
\end{proof}

\begin{lemma}
The group $\mathrm{McL}$ is unrecognisable by prime simplicial complex.
\end{lemma}
\begin{proof}
The prime simplicial complex of $\mathrm{McL}$ is composed of simplices $2, 3, 5, 6, 7, 10, 11, 14, 15, 30$. In particular, for every odd number $r$ that appears as a simplex, $2r$ is also a simple except if $r=11$.
By direct calculation, the group $HS.2$ has the same prime simplicial complex as $\mathrm{McL}$. Inspection of the 2-modular character table of $\mathrm{HS}.2$ reveals that there is an irreducible 20-dimensional module $V$ of $\mathrm{HS}.2$ where elements of order 11 act fixed-point-freely. Hence $(V^k):\mathrm{HS}.2$ has the same prime simplicial complex as $\mathrm{McL}$ for each $k\geq 1$. The result follows.
\end{proof}

\begin{lemma}
The group $\mathrm{J}_2$ is unrecognisable by prime simplicial complex.
\end{lemma}
\begin{proof}
The prime simplicial complex of $\mathrm{J}_2$ is composed of simplices $2,3,5,6,7,10,15$. Now, let $H = \mathrm{Sp}_6(2)$. Its prime simplicial complex is identical to that of $\mathrm{J}_2$. Moreover, the natural module $W$ for $H$ is irreducible, and elements of orders 7 and 15 do not fix any non-trivial subspaces of $W$. Hence, $(W^k):H$ has the same prime simplicial complex as $\mathrm{J}_2$ for each $k\geq 1$. 
\end{proof}

This completes the proof of \Cref{spor_recog}.


