\begin{proposition}
Let $n\geq3,$ $p$ a prime and $q=p^e.$ If $\{r_1, r_2, \dots, r_k\}$ is a prime simplex of $\mathrm{PSL}_{n-2}(q)$ not containing $p,$ then $\{p, r_1, r_2, \dots, r_k\}$ is a prime simplex of $\mathrm{PSL}_{n}(q)$.
\end{proposition}

\begin{proof}
   We have that $\rm{PSL}_2(q)\times\rm{PSL}_{n-2}(q)\leq\rm{PSL}_n(q),$ so the result follows by \Cref{directprod}.  
\end{proof}

\begin{proposition}
If $G = \mathrm{PSL}_n(q)$ with $q=p^e$ and $r$ divides $|G|$ with $e(r,q)>n-2$, then $r$ and $p$ do not lie in a prime simplex together. That is, $G$ does not contain an element of order $pr$.
\end{proposition}
\begin{proof}
This is \cite[Proposition 3.1(1)]{MR2213302}.
\end{proof}


\begin{proposition}
\label{psl2_pure}
    The prime simplicial complex of $\rm{PSL}_2(q)$ for $q\geq 4$ in characteristic $p$ is pure if and only if $q=4,$ $5,$ $8,$ $9$ or $17.$
\end{proposition}

\begin{proof}
    We use GAP \cite{GAP4} to verify directly that $\mathrm{PSL}_2(q)$ is pure for $q=4,$ $5,$ $8,$ $9$ or $17$. \par 
    Now assume that $q$ is odd and not $5,$ $9$ or $17.$
    By \cite[Proposition 3.1]{MR2213302}, $p$ is an isolated vertex in the prime graph, hence lies in a maximal simplex of size 1. By \Cref{torusprimes}, the non-characteristic primes dividing $\frac{q+1}{2}$ or $\frac{q-1}{2}$ form a simplex, so we need to show that at least one of them will have at least 2 prime divisors. This happens unless one of $\frac{q+1}{2}$ or $\frac{q-1}{2}$ is a power of two. If $\frac{q+1}{2}=2^{k}$ for some $k,$ then either $q=2^{k+1}-1$ or $\frac{q-1}{2}=2^k-1$ are divisible by $3.$ If $q$ is divisible by $3,$ then it is a power of $3,$ and the only powers of $3$ that are incident to a power of $2$ are $3$ and $9$ by \Cref{2-3prime}, so the result follows. If $\frac{q-1}{2}$ is divisible by $3,$ then it is a power of $3$ and so $q=5$ or $17$ by \Cref{2-3prime} and the result holds. If $\frac{q-1}{2}=2^{k}$ for some $k,$ then by a similar argument we reach the same conclusion. 
    Hence, at least one of $\frac{q+1}{2}$ and $\frac{q-1}{2}$ is a product of at least two primes, which form a maximal simplex of size at least 2, so the prime simplicial complex is not pure as required. \par 
    Now assume $q$ is even. Then, $2$ lies in a maximal simplex of size $1$ by \cite[Proposition 3.1]{MR2213302}. By \Cref{torusprimes}, the non-characteristic primes dividing $q+1$ or $q-1$ form a simplex. Out of two consecutive odd numbers, one is divisible by $3,$ and unless it is a power of $3,$ then the result holds. If one is a power of three, it is either $3$ or $9$ by \Cref{2-3prime}, so $q=4,$ $8,$ in which case the prime complex is pure. 
    \par 

\end{proof}

\begin{proposition}
\label{2b2_pure}
     The prime simplicial complex of ${}^2\mathrm{B}_2(2^{2m+1})$ for $m\geq 1$ is pure if and only if $m\in \{1,2\}.$
\end{proposition}

\begin{proof}
    We can check in GAP that the prime simplicial complex of ${}^2\mathrm{B}_2(2^{2m+1})$ is pure when $m\in \{1,2\}.$ Now assume $n\geq 3.$ By \cite{suzuki}, centralizers of involutions in ${}^2\mathrm{B}_2(2^{2m+1})$ are $2$-groups, so $2$ lies in a maximal simplex of size $1.$ It remains to show that there are two distinct odd primes that lie in a simplex together. By \cite[Proposition 2.6 (i)]{MR2213302}, any two distinct prime divisors of the odd numbers $Q_{\pm}=q\pm \sqrt{2q}+1$ lie in a simplex together, so the prime simplicial complex is pure if and only if they are both prime powers. By \cite[Lemma 2.14]{lee2024recognisabilitysporadicgroupsisomorphism}, $Q_{\pm}=q\pm \sqrt{2q}+1$ are both prime powers if and only if $m\in \{1,2\}.$ Hence, for $m\geq 3,$ at least one of them has at least 2 distinct prime divisors which lie in a simplex together, so the complex is not pure. 
\end{proof}
\begin{proposition}
\label{2g2pure}
     The prime simplicial complex of $G \cong {}^2\mathrm{G}_2(q)$ with $q = 3^{2m+1}$ and $m \geq 1$ is never pure. 
\end{proposition}
\begin{proof}
By \cite[Proposition 3.3]{MR2213302}, $\{3,2\}$ forms a maximal simplex, so $G$ is pure if and only if it is pure with maximal simplex size $2.$
$G$ has maximal tori of sizes $q\pm 1$ and $q \pm \sqrt{3q}+1$. Now $q \equiv 3 \mod 4$, so if $q-1$ is divisible by only two distinct primes, it must be of the form $2r^a$ for some prime $r$ and $a\geq 1$. By Lemma \ref{dio_eqn}, the only possibility is $q=3^5$, but $q+ \sqrt{3q}+1=257$ is prime, and forms a maximal simplex of size one. Therefore, $G$ is not pure.
\end{proof}

