\subsection*{Conventions}

Throughout this paper, $G$ is a finite group, and $\hat\B$ and $\C$ are idempotent-complete additive categories. Functors between additive categories are always taken to be additive.
We do not require the categories to be linear over a field.

In addition $\C$ is ribbon, and $\hat\B$ is $G$-crossed ribbon (we recall our conventions in Section~\ref{sec:crossed_equiv}). 
The graded components of $\hat\B$ are denoted by $\hat{\B} = \bigoplus_{g \in G} \B_g$ with neutral component $\B := \B_e$.
We assume the monoidal structure of $\C$ and $\hat\B$ to be strict to simplify notation.

All string diagrams are written using the optimistic convention and are read bottom to top and left to right. 

\section{\texorpdfstring{\boldmath $G$}{G}-crossed ribbon categories and equivariantisation}\label{sec:crossed_equiv}

In this section, we quickly recall the notion of a $G$-crossed ribbon category $\hat\B$ and its $G$-equivariantisation $\hat\B^G$. For more details we refer to \cite[Ch.\,8.24]{EGNO-book} (which defines $G$-crossed braided categories with coherences, but does not define the $G$-crossed ribbon structure) and \cite[Ch.\,VI.2]{TuraevBook2010} (which includes the ribbon case but assumes the $G$-action to be strict). The definition in \cite[Sec.\,3]{Galindo:2024} is closest to what we use here, as there the underlying category is strict, but the action is not. In Section~\ref{sec:equiv}, we will assume that the $G$-action is also strict, but until then we will keep track of the associated natural isomorphisms. Note that throughout this paper we use right actions while these sources use left actions.

\medskip

Let $\hat\B = \bigoplus_{g\in G}\B_g$ be an additive monoidal category which is faithfully graded, i.e.\ $\B_g\not= \emptyset$ for all $g\in G$, and let $\Aut_\otimes(\hat\B)$ be the monoidal category of its (additive and) monoidal autoequivalences and monoidal natural transformations.


Let $\underline{G^{op}}$ denote the discrete monoidal category whose objects are the group elements of $G$ with tensor product given by reversing the group multiplication so that $g \otimes h = hg$.
A \textit{right $G$-action} on a monoidal category $\C$ is a monoidal functor 
\[
\varphi\colon  \underline{G^\op}\to \Aut_\otimes(\C). 
\]
We will denote the associated natural transformations by 
\[
\mu_g^{X,Y}:= \vphi(g)(X \otimes Y) \isomto \vphi(g)(X) \otimes \vphi(g) (Y)
\quad \text{and} \quad
\gamma_{g,h}^X: \vphi(g)\vphi(h) (X) \isomto \vphi(hg)(X)  \ ,
\]
and refer to them as \textit{tensorators} and \textit{compositors}, respectively.
Without loss of generality we may assume that 
\[
\varphi(e)=\Id ,
\]
rather than the two just being naturally isomorphic. 
The isomorphism for the tensor unit is written as $\mu_g^0 : \varphi(g)(\1) \isomto \1$.

\begin{remark}\label{rem:G-strict}
Without loss of generality, we can and will assume that $\hat\B$ is strict as a monoidal category. By \cite[Thm.\,1.1]{Galindo:2016}, we may also assume that the right action is \textit{strict} in the sense that the natural isomorphism $\mu_g$ and $\gamma_{g,h}$ above are identities. We will make use of this result in  Section~\ref{sec:equiv}, but for now we keep these isomorphisms explicit.
\end{remark}


\begin{definition}
    A \textit{(right) $G$-crossed ribbon} category is a faithfully graded additive monoidal category $\hat\B=\bigoplus_{g\in G}\B_g$ with:
    \begin{itemize}
        \item A right action $\varphi\colon  \underline{G^\op}\to \Aut_\otimes(\hat\B)$ satisfying $\varphi(h)(\B_g)\subset \B_{h^{-1}gh}$, for all $g,h\in G$.
        \item A \textit{$G$-braiding} consisting of natural isomorphisms $c_{X,Y_h}\colon X\otimes Y_h\to Y_h\otimes \varphi(h)(X)$, for all $X\in \hat\B$, $Y_h\in \B_h$, satisfying:
\begin{enumerate}
    \item (Compatibility with the $G$-action)  
    \[\adjustbox{scale = 0.85, center}{\begin{tikzcd}
        {\varphi(g)(X \otimes Y_h)} && {\varphi(g)(Y_h \otimes \varphi(h)(X))} && {\varphi(g)(Y_h) \otimes \varphi(g)\varphi(h)(X)} \\
    	\\
        {\varphi(g)(X) \otimes \varphi(g)(Y_h)} && {\varphi(g)(Y_h) \otimes \varphi(g^{-1}hg)\varphi(g)(X)} && {\varphi(g)(Y_h) \otimes \varphi(hg)(X)}
        \arrow["{\varphi(g)c_{X,Y_h}}", from=1-1, to=1-3]
        \arrow["{\mu_{g}^{X,Y_h}}"', from=1-1, to=3-1]
        \arrow["{\mu_g^{Y_h,\varphi(h)(X)}}", from=1-3, to=1-5]
