\overline{\tau_i}^{M\otimes N} := \pic[1.5]{32_prod_Tcross_inv.pdf}, \qquad i=1,2 ~;
\end{equation*}

    \item \textit{Monoidal Unit}: The monoidal unit $\1_{\C_\A}:= (A, \tau_1^A, \tau_2^A, \overline{\tau_1}^A, \overline{\tau_2}^A)$ with $\tau_i^{A}$ and $\overline{\tau_i}^{A}$ given by: 
    \begin{equation*}
\label{eq:unit_T-cross}
\pic[1.5]{32_unit_Tcross_lhs.pdf} := \pic[1.5]{32_unit_Tcross_rhs.pdf}, \quad
\pic[1.5]{32_unit_Tcross_inv_lhs.pdf} := \pic[1.5]{32_unit_Tcross_inv_rhs.pdf}, \qquad i=1,2 ~;
\end{equation*}

    \item \textit{Associator and Unitors}: The associators and unitors of this tensor product are inherited from the category $_A \C_A$ of $A$-$A$-bimodules in $\C$;

    \item \textit{Duals}: For any object $(M, \tau_1^M, \tau_2^M, \overline{\tau_1}^M, \overline{\tau_2}^M) $ in $\C_\A$, take its dual in $\C_\A$ to be the dual bimodule $M^*$ with the T-crossings and pseudo-inverses given below:  
    \begin{equation*}
\pic[1.5]{32_dual_Tcross_lhs.pdf}
:= \pic[1.5]{32_dual_Tcross_rhs.pdf}, \quad
\pic[1.5]{32_dual_Tcross_inv_lhs.pdf}
:= \pic[1.5]{32_dual_Tcross_inv_rhs.pdf} \qquad i=1,2
\end{equation*}
with evaluation and coevaluation maps given by
\begin{align*}
&[\ev_M: M^* \otimes_A M \to A] := \pic[1.5]{32_ev.pdf},
&&[\coev_M: A \to M \otimes_A M^*] := \pic[1.5]{32_coev.pdf}, \nonumber \\
\label{eq:evs_evts_in_D} 
&[\widetilde{ev}_M: M \otimes_A M^* \to A] := \pic[1.5]{32_evt.pdf},
&&[\widetilde{coev}_M: A \to M^* \otimes_A M] := \pic[1.5]{32_coevt.pdf};
\end{align*}

    \item \textit{Braiding}: The braiding of two objects $(M, \tau_1^M, \tau_2^M, \overline{\tau_1}^M, \overline{\tau_2}^M)$ and $(N, \tau_1^N, \tau_2^N, \overline{\tau_1}^N, \overline{\tau_2}^N)$ in $\C_\A$ is given by the isomorphism $c_{M,N}$: 
    \begin{equation*}
\label{eq:D_braiding}
c_{M,N} := \pic[1.5]{32_braiding.pdf} \cdot \phi
\ , \qquad
c^{-1}_{M,N} := \pic[1.5]{32_braiding_inv.pdf} \cdot \phi
\ ;
\end{equation*}

    \item \textit{Ribbon Twist}: For $(M, \tau_1^M, \tau_2^M, \overline{\tau_1}^M, \overline{\tau_2}^M) \in \C_\A$, we define the twist $\theta_M$ using the braiding on $\C_\A$ in the typical way. 
\begin{equation*}
\label{eq:twist}
\theta_M 
:=
\pic[1.5]{32_twist1.pdf} 
=
\pic[1.5]{32_twist2.pdf} \cdot \phi.
\end{equation*}
\end{itemize}



\begin{proposition}
    $\C_\A$ with the above structure morphisms is an idempotent-complete additive ribbon category.
\end{proposition}

This is shown in \cite[Sec.\,3.2]{Mulevicius:2022} and \cite[Sec.\,4.2]{Carqueville:2021dbv}. The setting in \cite{Mulevicius:2022} is different (there, $\C$ is a modular fusion category over an algebraically closed field), but the proof given there that $\C_\A$ is braided just use the diagrammatic rules and still works in the present setting (the proof that $\C_\A$ is ribbon given there, however, relies on semisimplicity). That $\C_\A$ is ribbon follows along the same lines as in \cite[Sec.\,4.2]{Carqueville:2021dbv} (where instead the starting point is a certain 3-category obtained from a defect TFT). Idempotent-completeness can be checked using the same argument as in the proof of \cite[Prop.\,3.13]{Mulevicius:2022}.


\section{Orbifold data from \texorpdfstring{\boldmath $G$}{G}-crossed ribbon categories}\label{sec:G-crossed-to-orb}

Given a ribbon $G$-crossed category $\hat{\B}$, in \cite[Sec.\,5]{Carqueville:2018sld} a construction of an orbifold datum $\A$ in the trivial component $\B\coloneqq \B_e$ of $\hat{\B}$ is given. Namely, for each component of the grading on $\hat{\B}$, we choose a simple object $m_g \in \B_g$ such that $m_e = \1$ and we set 
$$\dm{g}\coloneqq \dim m_g.$$ 
We need to assume that
\begin{itemize}
    \item for each $g\in G$ there is an invertible element $\sqrt{d_g} \in \End(\1)$ which squares to $d_g$,\footnote{It is possible to adapt the conventions such that no square roots of $d_g$ are needed in the construction. We will not pursue this here and instead stick to the present conventions to match the notation in \cite{Carqueville:2018sld,Mulevicius:2022}. \label{fn:square-root}}
    and
    \item the element $|G| \cdot \id \in \End(\1)$ is invertible.
\end{itemize}

