$\A := (A, T, \alpha, \overline{\alpha}, \psi, \phi)$ defined in 
(i)--(v) is an orbifold datum in $\B_e$.
\end{theorem}


\section{Equivalence}\label{sec:equiv}

Recall that $\B = \B_e$ denotes the neutral component of $\hat\B$.
In this section, we prove the main theorem of this paper:

\begin{theorem}\label{thm:main}
Let $G$ be a finite group and $\hat\B$ an idempotent-complete additive ribbon $G$-crossed category such that${}^{\,\ref{fn:square-root}}$
\begin{itemize}
    \item $|G|$ is invertible in $\End_{\B}(\1)$, and
    \item for each $g \in G$ there is $m_g \in \B_g$ and an invertible $\sqrt{d_g} \in \End_{\B}(\1)$ such that $\dim m_g = (\sqrt{d_g})^2$.
\end{itemize}
Let $\A$ the orbifold datum 
in $\B$ obtained from $\hat{\B}$ via Theorem~\ref{thm:Gcrossed-to-orb}.
Then there is an explicit ribbon equivalence $E \colon \hat{\B}^G \to \B_\A$.
\end{theorem}

We will define the functor $E\colon \hat{\B}^G \to \B_\A$ and prove its properties in four steps:
\begin{enumerate}
    \item Denote by ${}_A \B_A$ the category of $A$-$A$-bimodules in $\B$. We define a faithful monoidal functor $J\colon \hat{\B} \to {}_A\B_A$, and we characterise its image in the Hom-spaces of ${}_A \B_A$.
    \item The functor $J$ can be lifted to a functor $E \colon \hat{\B}^G \to \B_\A$ in the sense that the following diagram commutes (on the nose):
\[
\begin{tikzcd}
    \hat{\B}^G \arrow[d,"\text{forget}"'] \arrow[r,"E"] & \B_\A \arrow[d,"\text{forget}"] \\
    \hat\B \arrow[r,"J"]  & {}_A \B_A 
\end{tikzcd}
\]
    \item We check that $E$ is a ribbon functor.
    \item We check that $E$ is an equivalence.
\end{enumerate}


\subsection[The monoidal functor \texorpdfstring{$J$}{J}]{The monoidal functor \texorpdfstring{\boldmath $J$}{J}}\label{sec:functorJ}

Recall from Section~\ref{sec:G-crossed-to-orb} that the algebra $A$ in the orbifold datum $\A$ decomposes as $A = \bigoplus_{g \in G} A_g$. All $A_g$ are objects in the neutral component $\B = \B_e$. This is not to be confused with the decomposition $X = \bigoplus_{g \in G} X_g$ of an object in $\hat{\B}$ into homogeneous components $X_g \in \B_g$.

Below, we will often use a special case of the relative tensor product over $A$, namely when $M = X \otimes m_g$ and $N = m_h^* \otimes Y$, for objects $X,Y \in \hat{\B}$. The $A$-action is as in the description of $T$ in Section~\ref{sec:G-crossed-to-orb} above. For example, only the component $A_g$ has a non-zero right action on $M$, and it is given by
\[
\rho_M = \big[ M \otimes A_g = X \otimes m_g \otimes m_g^* \otimes m_g \xrightarrow{\id \otimes \widetilde{\ev}_{m_g} \otimes \id} X \otimes m_g = M \big] \ .
\]
We have:

\begin{lemma}\label{lem:tensor-A}
    For $M = X \otimes m_g$ and $N = m_h^* \otimes Y$, the image of $P_{M,N}$ is $0$ if $g \neq h$ and $X \otimes Y$ if $g=h$, that is, $M \otimes_A N = \delta_{g,h} \, X \otimes Y$.
\end{lemma}

The proof is straightforward, and we just state the form of the projector $P_{M,N}$ from Section~\ref{sec:orbdata} in this case,
\[
P_{M,N} = \frac{\delta_{g,h}}{\dm{g}} \Big[ X \otimes m_g \otimes m_g^* \otimes Y 
\xrightarrow{\id \otimes \widetilde{\ev}_{m_g} \otimes \id} X \otimes Y \xrightarrow{\id \otimes \coev_{m_g} \otimes \id} X \otimes m_g \otimes m_g^* \otimes Y \Big] \ .
\]
For the projection and embedding map we choose the convention to include the factor $d_g^{-1}$ with the embedding,
\begin{align*}
\pi_{M,N} 
&= \delta_{g,h} \Big[ X \otimes m_g \otimes m_g^* \otimes Y 
\xrightarrow{\id \otimes \widetilde{\ev}_{m_g} \otimes \id} X \otimes Y \Big] \ ,
\\
\iota_{M,N}
&=
\frac{1}{\dm{g}} \Big[  X \otimes Y \xrightarrow{\id \otimes \coev_{m_g} \otimes \id} X \otimes m_g \otimes m_g^* \otimes Y \Big]
\ .
\end{align*}

Let ${}_A \B_A$ be the category of $A$-$A$-bimodules in $\B$ and define the functor 
\begin{align*}
J\colon \hat{\B} &\to {}_A\B_A,\\
X=\bigoplus_{g\in G} X_g &\mapsto \bigoplus_{g,h\,\in\,G} m_g^* \otimes X_{gh^{-1}} \otimes m_h,\\
\left[\bigoplus_{g\in G} X_g \xrightarrow{\underset{g\,\in\,G}{\bigoplus} f_g} \bigoplus_{g\in G} Y_g\right] &\mapsto \bigoplus_{g,h \in G} \id_{m_g^*} \otimes f_{gh^{-1}} \otimes \id_{m_h},
\end{align*}
where $X_{gh^{-1}}$ is the summand of $X$ in the $gh^{-1}$ component.
The left and right action of $A = \bigoplus_{g \in G} A_g$  on $J(X)$ is given by 
\[
\includegraphics[scale=4.50,valign=c]{pics/JXActions.pdf}
\qquad .
\]
In more detail, the left action by $A_g$ and right action by $A_h$ projects to the $m_g^* \otimes X_{gh^{-1}} \otimes m_h$ summand of $J(X)$ and is zero on the other summands. Note that, as in Section~\ref{sec:G-crossed-to-orb}, in string diagrams we abbreviate object labels $m_g \equiv g$ to make the diagram less crowded.



\begin{lemma}
The functor $J$ defined above is a faithful monoidal functor with monoidal structure $J^2$ and $J^0$ given by identity morphisms.
\end{lemma}

\begin{proof}
It is immediate that $J$ is faithful as $\id\otimes - \otimes \id$ is injective on $\Hom$-spaces. 
For the monoidal structure, we have
\begin{align*}
    J(X) \otimes_A J(Y) &= \bigoplus_{g,h,k,l\,\in\,G} \Bigl(m_g^* \otimes X_{gk^{-1}} \otimes m_k\Bigr) \otimes_A  \Bigl(m_l^* \otimes  Y_{lh^{-1}} \otimes m_h\Bigr)
    \\
    &= \bigoplus_{g,h,k\,\in\,G} m_g^* \otimes X_{gk^{-1}} \otimes  Y_{kh^{-1}} \otimes m_h 
     \ ,
\end{align*}
where the second equality follows from Lemma~\ref{lem:tensor-A}.
Setting $u = hk^{-1}$, one observes that
$$
\bigoplus_{k\,\in\,G} X_{gk^{-1}} \otimes Y_{kh^{-1}} = \bigoplus_{u\,\in\,G} X_{gh^{-1}u} \otimes Y_{u^{-1}} = (X \otimes Y)_{gh^{-1}} \ ,
$$
so that altogether
$$J(X) \otimes_A J(Y) = \bigoplus_{g,h\,\in\,G} m_g^* \otimes (X \otimes Y)_{gh^{-1}} \otimes m_h = J(X \otimes Y) \ .$$
This is  consistent with the choice $J^2_{X,Y} = \id$, and also with the hexagon as both, $J(X) \otimes_A (J(Y) \otimes_A J(Z))$ and $(J(X) \otimes_A J(Y)) \otimes_A J(Z)$ are equal to $\bigoplus_{g,h\,\in\,G} m_g^* \otimes (X \otimes Y \otimes Z)_{gh^{-1}} \otimes m_h$, and the associator is trivial
(see e.g.\ \cite[App.\,A]{Barmeier:2007idm} where the associator for $\otimes_A$ in the case of $\Delta$-separable Frobenius algebras is discussed in more detail).

For the tensor unit $\1 \in \hat{\B}$ one finds 
$$
J(\1) 
= 
\bigoplus_{g,h\,\in\,G} m_g^* \otimes \1_{gh^{-1}} \otimes m_h
= 
\bigoplus_{g\,\in\,G} m_g^*  \otimes m_g
= 
A \ ,
$$
where we used that $\1_{gh^{-1}} = \delta_{g,h}\, \1$. It is immediate that $J^0=\id$ solves the triangle conditions.
\end{proof}

The next lemma describes the image of $J : \Hom_{\hat{\B}}(X,Y) \to \Hom_{{}_A \B_A}(J(X),J(Y))$.

\begin{lemma}\label{lem:image-J-Hom}
    The image of the functor $J$ defined above on $\Hom$-spaces is
    \[
    \im\left(J_{|\Hom_{\hat{\B}}(X,Y)}\right)=\left\{\begin{array}{l}
        \underbrace{\left[\underbrace{\bigoplus_{g,h\,\in\,G} m_g^* \otimes X_{gh^{-1}} \otimes m_h}_{J(X)}\xrightarrow{\underset{g,h,k,l\,\in\,G}{\bigoplus} f_{g,h,k,l}}\underbrace{\bigoplus_{k,l\,\in\,G} m_k^* \otimes Y_{kl^{-1}} \otimes m_l}_{J(Y)}\right]}_{\in\,\Hom_{{}_A\B_A}(J(X),J(Y))}\\\hline
        \forall g,h,k,l\in G\colon\left\{\begin{array}{rl}
            (i)&g\not= k\Rightarrow f_{g,h,k,l}=0,\\
            (ii)&h\not= l\Rightarrow f_{g,h,k,l}=0,\\
            (iii)&f_{g,h,g,h}=\id_{m_g^*}\otimes f_{g,h}\otimes \id_{m_h},\\
            (iv)&f_{g,e}=f_{gh,h}
            \end{array}\right.
        \end{array}\right\} \ ,
    \]
where  $f_{g,h,k,l} : m_g^* \otimes X_{gh^{-1}} \otimes m_h \to m_k^* \otimes Y_{kl^{-1}} \otimes m_l$ runs over all morphisms in $\hat{\B}$ satisfying (i)--(iv), and $f_{g,h}$ runs over morphisms $X_{gh^{-1}} \to Y_{gh^{-1}}$ in $\hat{\B}$. 
\end{lemma}

\begin{proof}
It is easy to check that the morphisms on the right hand side in the statement are indeed $A$-$A$-bimodule morphisms. 

We first show the inclusion ``$\subset$''.
Let $X\overset{\hat{f}}{\to}Y$ be a morphism in $\Hom_{\hat{\B}}(X,Y)$. Then
    \[J(\hat{f})=\bigoplus_{g,h \in G} \id_{m_g^*} \otimes \hat{f}_{gh^{-1}} \otimes \id_{m_h}=\left[\bigoplus_{g,h\,\in\,G} m_g^* \otimes X_{gh^{-1}} \otimes m_h\xrightarrow{\underset{g,h,k,l\,\in\,G}{\bigoplus} f_{g,h,k,l}}\bigoplus_{k,l\,\in\,G} m_k^* \otimes Y_{kl^{-1}} \otimes m_l\right]\]
    immediately implies that conditions $(i)$ -- $(iii)$ hold with $f_{g,h}\coloneqq \hat{f}_{gh^{-1}}$. Further, $f_{g,e}=\hat{f}_g=f_{gh,h}$ for all $g,h\in G$, and so $(iv)$ holds as well.

To show the inclusion ``$\supset$'', let
    \[f=\left[\bigoplus_{g,h\,\in\,G} m_g^* \otimes X_{gh^{-1}} \otimes m_h\xrightarrow{\underset{g,h,k,l\,\in\,G}{\bigoplus} f_{g,h,k,l}}\bigoplus_{k,l\,\in\,G} m_k^* \otimes Y_{kl^{-1}} \otimes m_l\right]\]
    satisfy conditions $(i)$ -- $(iv)$, i.e.
    \[f=\left[\bigoplus_{g,h\,\in\,G} m_g^* \otimes X_{gh^{-1}} \otimes m_h\xrightarrow{\underset{g,h\,\in\,G}{\bigoplus} \id_{m_g^*}\,\otimes\,f_{g,h}\,\otimes\,\id_{m_h}}\bigoplus_{g,h\,\in\,G} m_g^* \otimes Y_{gh^{-1}} \otimes m_h\right]\ , \] 
    and $f_{g,h}$ satisfies condition $(iv)$.
    Define $[X\overset{\hat{f}}{\to} Y]\in \Hom_{\hat{\B}}(X,Y)$ via $[X_g\overset{\hat{f}_g}{\to} Y_g]\coloneqq f_{g,e}$ for all $g\in G$. Then 
    \[\hat{f}_{gh^{-1}}=f_{gh^{-1},e}\overset{(iv)}{=}f_{gh^{-1}h,h}=f_{g,h}\]
    and hence $J(\hat{f})=f$.
\end{proof}

\subsection[The functor \texorpdfstring{$E$}{E}]{The functor \texorpdfstring{\boldmath $E$}{E}}\label{sec:functorE}

We will lift the functor $J$ to a functor $E$ such that the following diagram of functors commutes (on the nose):
\[
\begin{tikzcd}
    \hat{\B}^G \arrow[d,"\text{forget}"'] \arrow[r,"E"] & \B_\A \arrow[d,"\text{forget}"] \\
    \hat\B \arrow[r,"J"]  & {}_A \B_A 
\end{tikzcd}
\]
To construct $E$ it is useful to investigate how $J$ interacts with the actions on $T$. Hence, we take a closer look at the $A_0$-$(A_1\otimes A_2)$-bimodules obtained by tensoring $T$ and $J(X)$. Here, $A_{0,1,2}$ and also $B$ below all stand for $A$, the different notation is intended to show which copy of $A$ acts where:
\begin{align*}
    J(X) \otimes_0 T &= {\vphantom{\Big)}}_{A_0}\Bigl({}_{A_0}J(X)_B\otimes_B {}_BT_{A_1 A_2}\Bigr)_{A_1 A_2},\\
    T\otimes_1 J(X) &= {\vphantom{\Big)}}_{A_0}\Bigl({}_{A_0}T_{B A_2}\otimes_B {}_BJ(X)_{A_1}\Bigr)_{A_1 A_2},\\
    T\otimes_2 J(X) &= {\vphantom{\Big)}}_{A_0}\Bigl({}_{A_0}T_{A_1 B}\otimes_B {}_BJ(X)_{A_2}\Bigr)_{A_1 A_2}.
\end{align*}

We spell out the components, always taking the indices in advance in such a way that the outer $A_0$-, $A_1$- and $A_2$-action includes the projection to the action of $A_g \subset A_0$, $A_h \subset A_1$, and $A_k \subset A_2$. 
Tensoring with $J(X)$ from the left gives
\begin{align*}
J(X) \otimes_0 T &= \bigoplus_{g,h,k,l\,\in\,G} \Bigl[m_g^* \otimes X_{gl^{-1}} \otimes m_l\Bigr] \otimes_A \Bigl[m_{hk}^* \otimes m_h \otimes m_k\Bigr]
&\overset{(*)}= \bigoplus_{g,h,k\,\in\,G} m_g^* \otimes X_{g(hk)^{-1}} \otimes m_h \otimes m_k.
\end{align*}
In $(*)$ we used Lemma~\ref{lem:tensor-A} to compute the relative tensor product $\otimes_A$, which is non-zero only if $l = hk$.

Tensoring with $J(X)$ from the right over $A_1$ gives
\begin{align*}
T \otimes_1 J(X) &= \bigoplus_{g,h,k,l\,\in\,G} \Bigl(m_g^* \otimes m_{gk^{-1}} \otimes m_k\Bigr) \otimes_A \Bigl(m_l^* \otimes X_{lh^{-1}} \otimes m_h\Bigr)
\\
  &\overset{(1)}\cong \bigoplus_{g,h,k,l\,\in\,G} \Bigl(m_g^* \otimes \varphi\big( (gk^{-1} )^{-1}\big)(m_k)  \otimes m_{gk^{-1}} \Bigr) \otimes_A \Bigl(m_l^* \otimes X_{lh^{-1}} \otimes m_h\Bigr)
\\
&\overset{(2)}= \bigoplus_{g,h,k\,\in\,G} m_g^* \otimes 
\varphi\big( k g^{-1} \big)(m_k) 
\otimes X_{gk^{-1}h^{-1}} \otimes m_h.
\end{align*}
In step (1) we use the $G$-braiding $\tilde c_{m_{gk^{-1}},m_k}$ to exchange the two objects (the $G$-braiding $c_{m_{gk^{-1}},m_k}$ would not be compatible with the $A$-action). Step (2) is Lemma~\ref{lem:tensor-A}.

Note that here the external $A_0$ action is defined on $m_g^*$, the $A_2$ action is defined on $\varphi((gk^{-1})^{-1})(m_k)$, and the $A_1$ action is defined on $m_h$. We would prefer to explicitly have the order $A_0$-$A_1$-$A_2$, so we use the isomorphism
$$\phi_1 \colon T \otimes_1 J(X) \isomto \bigoplus_{g,h,k\,\in\,G} m_g^* \otimes X_{gk^{-1}h^{-1}} \otimes m_h \otimes m_k$$
given by 
\[
\phi_1 ~=~
\sum_{g,h,k \in G}
\includegraphics[scale=4.50,valign=c]{pics/phi1--edited.pdf}
\qquad .
\]
Tensoring with $J(X)$ from the right over $A_2$ results in
\begin{align*}
T \otimes_2 J(X) &= \bigoplus_{g,h,k,l\,\in\,G} \Bigl(m_g^* \otimes m_h \otimes m_{h^{-1}g}\Bigr) \otimes_A \Bigl(m_l^* \otimes X_{lk^{-1}} \otimes m_k\Bigr)
\\
&= \bigoplus_{g,h,k\,\in\,G} m_g^* \otimes m_h \otimes X_{h^{-1}gk^{-1}} \otimes m_k.
\end{align*}
Likewise, to reorder the tensor factors here, we use the isomorphism 
$$\phi_2\colon T \otimes_2 J(X) \isomto \bigoplus_{g,h,k\,\in\,G} m_g^* \otimes \varphi(h^{-1})\big(X_{h^{-1}gk^{-1}}\big) \otimes m_h \otimes m_k$$
given by 
\[
\phi_2 ~=~\sum_{g,h,k \in G}
\includegraphics[scale=4.50,valign=c]{pics/phi2--edited.pdf}
\qquad .
\]
In total, we have
\begin{align*}
J(X) \otimes_0 T &= \bigoplus_{g,h,k\,\in\,G} m_g^* \otimes X_{gk^{-1}h^{-1}} \otimes m_h \otimes m_k,\\
T \otimes_1 J(X) \overset{\phi_1}&{\iso} \bigoplus_{g,h,k\,\in\,G} m_g^* \otimes X_{gk^{-1}h^{-1}} \otimes m_h \otimes m_k,\\
T \otimes_2 J(X) \overset{\phi_2}&{\iso} \bigoplus_{g,h,k\,\in\,G} m_g^* \otimes 
\varphi(h^{-1})\big(X_{h^{-1}gk^{-1}}\big)
 \otimes m_h \otimes m_k.
\end{align*}

The isomorphism $\phi_1$ and $\phi_2$ can also be used to give the morphisms $\tau_{1,2}$, $\overline\tau_{1,2}$ which form part of the data of an object in $\B_\A$: 
{\allowdisplaybreaks
    \begin{align*}
        \tau_1 &\coloneqq        
        \left[\underbrace{\bigoplus_{g,h,k\,\in\,G} m_g^* \otimes X_{gk^{-1}h^{-1}} \otimes m_h \otimes m_k}_{J(X)\,\otimes_0\,T} 
        \xrightarrow{\tau_1^{g,h,k}} T \otimes_2 J(X)\right], 
        \\
        \tau_2 &\coloneqq        
        \left[\underbrace{\bigoplus_{g,h,k\,\in\,G} m_g^* \otimes X_{gk^{-1}h^{-1}} \otimes m_h \otimes m_k}_{J(X)\,\otimes_0\,T} 
        \xrightarrow{\tau_2^{g,h,k}} T \otimes_2 J(X)\right], 
        \\
        \overline{\tau_1} &\coloneqq 
        \left[\underbrace{\bigoplus_{g,h,k\,\in\,G} m_g^* \otimes X_{gk^{-1}h^{-1}} \otimes m_h \otimes m_k}_{T \otimes_1 J(X)} 
        \xrightarrow{\overline{\tau}_1^{g,h,k}} 
        J(X) \otimes_0 T \right],
        \\
        \overline{\tau_2} &\coloneqq \left[\underbrace{\bigoplus_{g,h,k\,\in\,G} m_g^* \otimes \varphi\left(h^{-1}\right)\left(X_{h^{-1}gk^{-1}}\right) \otimes m_h \otimes m_k}_{T \otimes_2 J(X)} 
        \xrightarrow{\overline{\tau}_2^{g,h,k}} 
        J(X)\,\otimes_0\,T \right].
    \end{align*}}
where
    \begin{align*}
        \tau_1^{g,h,k} &= \dm{gk^{-1}} \Bigg(\frac{\dm{hk}}{\dm{h}}\Bigg)^{\!\frac{1}{2}} \phi_1^{-1} \ ,
        &
        \tau_2^{g,h,k} &=
        \dm{h^{-1}g} \Bigg(\frac{\dm{hk}}{\dm{h}}\Bigg)^{\!\frac{1}{2}}
        \phi_2^{-1}\,\circ\,\left[\bigoplus_{g,h,k\,\in\,G} \id_{m_g^*}\,\otimes\,\left(\eta^X_{h^{-1}}\right)^{-1}\,\otimes\,\id_{m_h\otimes m_k}\right] \ ,
        \\
        \overline{\tau}_1^{g,h,k} &=
        \dm{hk} \Bigg(\frac{\dm{h}}{\dm{hk}}\Bigg)^{\!\frac{1}{2}} \phi_1 \ ,
        &
        \overline{\tau}_2^{g,h,k} &= \dm{hk}
        \Bigg(\frac{\dm{k}}{\dm{hk}}\Bigg)^{\!\frac{1}{2}}
        \left[\bigoplus_{g,h,k\,\in\,G} \id_{m_g^*}\,\otimes\,\eta^X_{h^{-1}}\,\otimes\,\id_{m_h\otimes m_k}\right]\,\circ\,\phi_2 \ .
    \end{align*}
If we include explicitly the projection and embedding for the relative tensor products, as string diagrams, $\tau_1$ and $\tau_2$ are given by (recall from below Lemma~\ref{lem:tensor-A} that there is an extra dimension factor included in the embedding map):
{\allowdisplaybreaks
\begin{align*}    
\iota_{T,J(X)} \circ \tau_1 \circ \pi_{J(X),T} &~=~
\sum_{g,h,k}
\Bigg(\frac{\dm{hk}}{\dm{h}}\Bigg)^{\!\frac{1}{2}}
~~
\includegraphics[scale=4.25,valign=c]{pics/Tau_1.pdf}
~~, 
\\
\iota_{T,J(X)} \circ \tau_2 \circ \pi_{J(X),T} &~=~
\sum_{g,h,k}
\Bigg(\frac{\dm{hk}}{\dm{k}}\Bigg)^{\!\frac{1}{2}}
~~
\includegraphics[scale=4.25,valign=c]{pics/Tau_2.pdf}
\ .
\end{align*}}The morphism $\gamma_{h,h^{-1}}$ appears when computing the inverse of $\tilde c$ which is part of $\phi_2$, cf.\ the discussion of $G$-braidings in Section~\ref{sec:crossed_equiv}.
The string diagrams for $\overline\tau_1$ and $\overline\tau_2$ are similar.

The definition of the functor $E$ above still includes the coherence isomorphisms of the $G$-action. To simplify the proofs, from this point on we will make use of Remark~\ref{rem:G-strict} and assume the $G$-action to be strict.

