\end{proof}

\subsection[\texorpdfstring{$E$}{E} is an equivalence]{\texorpdfstring{\boldmath $E$}{E} is an equivalence}

To complete the proof of Theorem~\ref{thm:main}, we still need to show that the functor $E$ is an equivalence. This will be done in the next two lemmas. 


Recall that $m_g$ is a $\1$-$A_g$-bimodule, and $m_g^*$ an $A_g$-$\1$-bimodule. These two bimodules provide a Morita-context: $A_g = m_g^* \otimes m_g$ and $m_g \otimes_A m_g^* \cong \1$ (cf.\ Lemma~\ref{lem:tensor-A}).

\begin{lemma}\label{lem:AgAh-bimodhom}
\begin{enumerate}
	\item Let $M$ be an $A$-$A$-bimodule in $\B \equiv \B_e$. Then there exist $N_{g,h} \in \B_{gh^{-1}}$ s.t.
	\[
	M \cong \bigoplus_{g,h \in G} m_g^* \otimes N_{g,h} \otimes m_h\]
	as $A$-$A$-bimodules.

	\item Let now $M =  \bigoplus_{g,h \in G} m_g^* \otimes N_{g,h} \otimes m_h$, $M' =  \bigoplus_{g,h \in G} m_g^* \otimes N'_{g,h} \otimes m_h$ and $F : M \to M'$ an $A$-$A$-bimodule map. Then there are $f_{g,h} : N_{g,h} \to N'_{g,h}$ such that
	\[
	F = \sum_{g,h} \id_{m_g^*} \otimes f_{g,h} \otimes \id_{m_h} \ .
	\]
\end{enumerate}
\end{lemma}

\begin{proof}
Part 1:
The units $\eta_g :  \1 \to A_g$ of the individual algebras act as idempotents. Set
    $$M_{g,h} := \text{im}(\eta_g \otimes_A M \otimes_A \eta_h) $$
Then $M = \bigoplus_{g,h \in G} M_{g,h}$ as $A$-$A$-bimodules. We have the following isomorphism of $A_g$-$A_h$-bimodules,
\[
M_{g,h} \cong A_g \otimes_A M \otimes_A A_h \cong m_g \otimes m_g^* \otimes_A M \otimes_A m_h \otimes m_h^* \ ,
\]
so that we can take $N_{g,h} := m_g^* \otimes_A M \otimes_A m_h$.

\medskip

\noindent
Part 2: Since $F$ commutes with the action of the units $\eta_g$ on both sides, it decomposes as $F = \sum_{g,h} F_{g,h}$ with $F_{g,h} : m_g^* \otimes N_{g,h} \otimes m_h \to  m_g^* \otimes N'_{g,h} \otimes m_h$ an $A_g$-$A_h$-bimodule map. Since $m_g$ and $m_h$ are Morita-contexts, the functor $m_g^* \otimes (-) \otimes m_h$ is an equivalence of categories from $\B_{gh^{-1}}$ to $A_g$-$A_h$-bimodules in $\B$, and hence $F_{g,h} = \id_{m_g^*} \otimes f_{g,h} \otimes \id_{m_h}$ for appropriate $f_{g,h}$.
\end{proof}

\begin{lemma}
    $E$ is an equivalence of categories.
\end{lemma}

\begin{proof}
We will show that $E$ is fully faithful and essentially surjective.

\medskip

\noindent
\textit{Faithful:} This is clear as $J$ is faithful and morphism spaces in $\B_\A$ are subspaces of bimodule maps.

\medskip

\noindent
\textit{Full:}
Let $F\colon E\left(X, \eta^X\right) \to E\left(Y,\eta^Y\right)$ be a morphism in $\B_\A$.
This means, that
$F\colon J(X)\to J(Y)$ is an $A$-$A$-bimodule map such that the diagram
	\[\begin{tikzcd}
		J(X)\otimes_0 T \arrow[d, "\tau_i"] \arrow[r, "{F\,\otimes_0\,\id}"] & J(Y)\otimes_0 T \arrow[d, "\tau_i"] \\
		T\otimes_i J(X) \arrow[r, "{\id\,\otimes_i\,F}"] & T\otimes_i J(Y)
	\end{tikzcd}\]
commutes for $i\in\{1,2\}$.
By Lemma~\ref{lem:AgAh-bimodhom}, we can write
$F = \sum_{g,h} \id_{m_g^*} \otimes f_{g,h} \otimes \id_{m_h}$ for some $f_{g,h} : X_{gh^{-1}} \to Y_{gh^{-1}}$.
The above commuting diagram, together with the definition of $\tau_i$ for $E\left(X, \eta^X\right)$ and $E\left(Y,\eta^Y\right)$ results in the conditions
\begin{align*}
\tau_1 &: f_{g,hk} = f_{gk^{-1},h} \ ,
\\
\tau_2 &: (\eta_{h^{-1}}^Y)^{-1} \circ f_{g,hk} = \varphi(h^{-1})f_{gk^{-1},h} \circ (\eta_{h^{-1}}^X)^{-1} \ .
\end{align*}
The condition for $\tau_1$ shows that $f_{g,k} = f_{gk^{-1},e}$, and so by Lemma~\ref{lem:image-J-Hom}, $F = J(\hat f)$, where $\hat f : X \to Y$ has components $\hat f_g = f_{g,e}$. Condition $\tau_2$ ensures that $\hat f : (X,\eta^X) \to (Y,\eta^Y)$ is a morphism in $\hat\B^G$. Indeed, setting $h = k^{-1}$ results in $f_{g,e} \circ \eta_{k}^X = \eta_k^Y \circ \varphi(k)f_{g,e}$.

\medskip

\noindent
\textit{Essentially surjective:}
Let $(M, \tau_1, \tau_2, \overline{\tau_1}, \overline{\tau_2})) \in \B_\A$.
We need to give $(X,\eta^X) \in \hat{\B}^G$ such that $(M, \tau_1, \tau_2, \overline{\tau_1}, \overline{\tau_2}) \cong E(X,\eta^X)$. We first construct $X \in \hat\B$ such that $M \cong J(X)$ as bimodules, and then find the equivariant structure $\eta^X$ on $X$.

First note that by Lemma~\ref{lem:AgAh-bimodhom} we may assume that $M = \bigoplus_{a,b \in G} m_a^* \otimes N_{a,b} \otimes m_b$ for some $N_{a,b} \in \B_{ab^{-1}}$.
We now proceed along the same lines as when defining the functor $E$ in Section~\ref{sec:functorE}, except that here we do not already know that $M \cong J(X)$ for some $X$.
Namely, we have
\begin{align*}
	M \otimes_0 T &= \bigoplus_{g,h,k,x \in G} (m_g^* \otimes N_{g,x} \otimes m_x) \otimes_A (m_{hk}^* \otimes m_h \otimes m_k)
\overset{\text{Lem.\,\ref{lem:tensor-A}}}=
\bigoplus_{g,h,k \in G} m_g^* \otimes N_{g,hk} \otimes m_h \otimes m_k \ ,
\\
T \otimes_1 M &\cong \bigoplus_{g,h,k\,\in\,G} m_g^* \otimes
\varphi\big( k g^{-1} \big)(m_k)
\otimes N_{gk^{-1},h} \otimes m_h \ ,
\\
T \otimes_2 M &= \bigoplus_{g,h,k\,\in\,G} m_g^* \otimes m_h \otimes N_{h^{-1}g,k} \otimes m_k \ ,
    \end{align*}
where the outer $A_0$-, $A_1$- and $A_2$-action includes the projection to the action of $A_g \subset A_0$, $A_h \subset A_1$, and $A_k \subset A_2$.
Define the $A_0$-$A_1\otimes A_2$-bimodule isomorphism $\varphi_1: T \otimes_1 M \isomto \bigoplus_{g,h,k\,\in\,G} m_g^* \otimes N_{gk^{-1},h} \otimes m_h \otimes m_k$ and $\varphi_2 : T \otimes_2 M \isomto \bigoplus_{g,h,k\,\in\,G} m_g^* \otimes \varphi(h^{-1})\big(N_{h^{-1}g,k}\big) \otimes m_h \otimes m_k$ by
\[
\varphi_1 =
\includegraphics[scale=4.50,valign=c]{pics/phi1ES.pdf} ~~,\quad
\varphi_2 =
\includegraphics[scale=4.50,valign=c]{pics/phi2ES.pdf} \ .
\]
Then also
\begin{align*}
\varphi_1 \circ \tau_1 &: \bigoplus_{g,h,k \in G} m_g^* \otimes N_{g,hk} \otimes m_h \otimes m_k \isomto \bigoplus_{g,h,k \in G} m_g^* \otimes N_{gk^{-1},h} \otimes m_h \otimes m_k
~,
\\
\varphi_2 \circ \tau_2&: \bigoplus_{g,h,k \in G} m_g^* \otimes N_{g,hk} \otimes m_h \otimes m_k \isomto \bigoplus_{g,h,k \in G} m_g^* \otimes \varphi(h^{-1}) N_{h^{-1}g,k} \otimes m_h \otimes m_k
\end{align*}
are $A_0$-$A_1\otimes A_2$-bimodule isomorphisms.
As in the proof of Lemma~\ref{lem:AgAh-bimodhom}\,(ii) we conclude that
\begin{align*}
\varphi_1 \circ \tau_1 &= \bigoplus_{g,h,k \in G}\dm{gk^{-1}} \Bigg(\frac{\dm{hk}}{\dm{h}}\Bigg)^{\!\frac{1}{2}} \cdot  \id_{m_g^*} \otimes t^1_{g,h,k} \otimes \id_{m_h} \otimes \id_{m_k}
\\
\varphi_2 \circ \tau_2 &= \bigoplus_{g,h,k \in G}
\dm{h^{-1}g} \Bigg(\frac{\dm{hk}}{\dm{h}}\Bigg)^{\!\frac{1}{2}}
\cdot
 \id_{m_g^*} \otimes t^2_{g,h,k} \otimes \id_{m_h} \otimes \id_{m_k}
\end{align*}
for some isomorphisms
\[
    t^1_{g,h,k}: N_{g,hk} \isomto N_{gk^{-1}, h}
    ~~,\quad
    t^2_{g,h,k}: N_{g,hk} \isomto \varphi(h^{-1})N_{h^{-1}g, k}
    \ .
\]
in $\B_{gk^{-1}h^{-1}}$. 
The dimension factors mirror those for $\tau_i^{g,h,k}$ in Section~\ref{sec:functorE}.
Inverting this relation to extract $\tau_i$, we get
{\allowdisplaybreaks
\begin{align*}    
\iota_{T,M} \circ \tau_1 \circ \pi_{M,T} &~=~
\Bigg(\frac{\dm{hk}}{\dm{h}}\Bigg)^{\!\frac{1}{2}}
~~
\includegraphics[scale=4.25,valign=c]{pics/tau1ES.pdf}
~~, 
\\
\iota_{T,M} \circ \tau_2 \circ \pi_{M,T} &~=~
\Bigg(\frac{\dm{hk}}{\dm{k}}\Bigg)^{\!\frac{1}{2}}
~~
\includegraphics[scale=4.25,valign=c]{pics/tau2ES.pdf}
\ .
\end{align*}}
For later use, we record the following conditions on the $t^i_{g,h,k}$ implied by the fact that $\tau_1$, $\tau_2$ satisfy \eqrefT{1}--\eqrefT{3}. Namely, for all $a,g,h,k \in G$ we have: 
\begin{align*}
	t^1_{g,h,k} &= t^1_{ga^{-1}, h, ka^{-1}} \circ t^1_{g, hka^{-1},a}
	&& \eqrefT{1}
	\\
	\varphi(h^{-1})t^1_{h^{-1}g, ka^{-1}, a} \circ t^2_{g,h,k} &= t^2_{ga^{-1},h,ka^{-1}} \circ t^1_{g,hka^{-1},a}
	&& \eqrefT{2}
	\\
	\varphi(h^{-1})t^2_{h^{-1}g, ka^{-1}, a} \circ t^2_{g,h,k} &= t^2_{g,hka^{-1},a}
	&& \eqrefT{3}
\end{align*}
To check e.g.\ the last condition, one can use Figure~\ref{fig:T3check} as a guide and replace the $\eta$-morphisms there by $t^2$ morphisms as in the string diagram for $\tau_2$ above.

We can now define $X = \bigoplus_{g \in G} X_g \in \hat\B$ such that $M \cong J(X)$ as $A$-$A$-bimodules. Namely, we set
\[
X_g := N_{g,e}
\]
and observe that $t^1_{g,h,k}$ specialised to $h=e$ gives an isomorphism $t^1_{g,e,k}: N_{g,k} \isomto N_{gk^{-1}, e} = X_{gk^{-1}}$.

Next we turn to the equivariant structure $\eta^X_a : \varphi(a)X \isomto  X$. We define it  componentwise via
\[
\eta^X_a\big|_{\varphi(a)X_b}:= 
\Big[ \varphi(a)X_{b} = \varphi(a)N_{b,e} \xrightarrow[]{\left(t^2_{a^{-1}b,a^{-1},e}\right)^{-1}} N_{a^{-1}b,a^{-1}} \xrightarrow[]{\left(t^1_{a^{-1}ba, a^{-1}, a}\right)^{-1}} N_{a^{-1}ba,e} = X_{a^{-1}ba} \Big] \ .
\]
The coherence condition condition for the $(\eta_a^X)_{a \in G}$ then amounts to commutativity of the outer diagram in:
\[
\begin{tikzcd}
	{\vphi(g) \vphi(h) N_{b,e}} &&& {\vphi(g)N_{h^{-1}b,h^{-1}}} &&& {\vphi(g)N_{h^{-1}bh,e}} \\
	\\
	&&&&&& {N_{g^{-1}h^{-1}bh,g^{-1}}} \\
	\\
	{\vphi(g) \vphi(h) N_{b,e}} &&& {N_{g^{-1}h^{-1}b,g^{-1}h^{-1}}} &&& {N_{g^{-1}h^{-1}bhg,e}}
	\arrow["{\vphi(g) \big(t^2_{h^{-1}b,h^{-1},e}\big)^{-1}}", from=1-1, to=1-4]
	\arrow["{\gamma_{g,h}=\id}"', from=1-1, to=5-1, equal]
	\arrow["\eqrefT{3}"{description}, draw=none, from=1-1, to=5-4]
	\arrow["{\vphi(g) \big(t^1_{h^{-1}bh,h^{-1},h}\big)^{-1}}", from=1-4, to=1-7]
	\arrow["\eqrefT{2}"{description}, draw=none, from=1-4, to=3-7]
	\arrow["{\big(t^2_{g^{-1}h^{-1}b,g^{-1},h^{-1}}\big)^{-1}}"{description}, from=1-4, to=5-4]
	\arrow["{\big(t^2_{g^{-1}h^{-1}bh,g^{-1},e}\big)^{-1}}", from=1-7, to=3-7]
	\arrow[""{name=0, anchor=center, inner sep=0}, "{\big(t^1_{g^{-1}h^{-1}bhg,g^{-1},g}\big)^{-1}}", from=3-7, to=5-7]
	\arrow["{\big(t^2_{g^{-1}h^{-1}b,g^{-1}h^{-1},e}\big)^{-1}}"', from=5-1, to=5-4]
	\arrow["{\big(t^1_{g^{-1}h^{-1}bh,g^{-1}h^{-1},h}\big)^{-1}}"{description}, from=5-4, to=3-7]
	\arrow[""{name=1, anchor=center, inner sep=0}, "{\big(t^1_{g^{-1}h^{-1}bhg,g^{-1}h^{-1},hg}\big)^{-1}}"', from=5-4, to=5-7]
	\arrow["\eqrefT{1}"', shift left=5, draw=none, from=1, to=0]
\end{tikzcd}
\]
Here we label the center of the subdiagrams by which coherence axioms imply their commutativity.

Having constructed our candidate $(X,\eta^X)$, we still need to check that it is isomorphic to 
$(M, \tau_1, \tau_2, \overline{\tau_1}, \overline{\tau_2})$. Consider the isomorphism of $A$-$A$-bimodules
\[
\Phi := \Big[ M = \bigoplus_{g,h \in G} m_g^* \otimes N_{g,h} \otimes m_h
\xrightarrow{\bigoplus_{g,h \in G} \id \otimes t^1_{g,e,h} \otimes \id} \bigoplus_{g,h \in G} m_g^* \otimes N_{gh^{-1},e} \otimes m_h = J(X) \Big] \ .
\]
We will check that $\Phi : (M, \tau_1, \tau_2, \overline{\tau_1}, \overline{\tau_2}) \to E(X,\eta^X)$ is an isomorphism in $\B_\A$. For this it remains to see that $\Phi$ commutes with $\tau_i$ as in Definition~\ref{def:cat-of-wilson}. One finds the conditions:
\begin{align*}	
\tau_1 ~&:~ t^1_{g,e,hk} = t^1_{gk^{-1},e,h} \circ t^1_{g,h,k}
\ ,
\\
\tau_2 ~&:~ \Big(\eta_{h^{-1}}\big|_{\varphi(h^{-1})X_{h^{-1}g k^{-1}}}\Big)^{-1} 
\circ
t^1_{g,e,hk}
= \varphi(h^{-1})t^1_{h^{-1}g,e,k} \circ t^2_{g,h,k} 
\ .
\end{align*}
The condition for $\tau_1$ is just a special case of the identity that $t^1$ satisfies because of \eqrefT{1} as listed above (set $a=k$, $h=e$ there). To verify the condition for $\tau_2$ we substitute the definition of $\eta$ to get
\[
t^2_{g k^{-1} ,h,e} \circ \underbrace{t^1_{g k^{-1} h^{-1}, h, h^{-1}} 
\circ 
t^1_{g,e,hk}}_{=t^1_{g,h,k} \text{ by \eqrefT{1}}} 
= 
\varphi(h^{-1})t^1_{h^{-1}g,e,k} \circ t^2_{g,h,k} \ ,
\]
which in turn holds by \eqrefT{2} (set $a=k$ there).
\end{proof}

This completes the proof of Theorem~\ref{thm:main}.

