For given positive integers $k,p$, consider the graphs $S$ and $S_{xy}$ defined in Figure~\ref{fig:size_density}. Recall that~\cite{BoVAC}:

\begin{definition}[Density axiom]
    We say that a centrality $\ce f$ satisfies the \emph{density axiom} iff for every fixed $k \geq 3$ and $p=k$, $\ce f_{S_{xy}}(x) > \ce f_{S_{xy}}(y)$.
\end{definition}

\begin{definition}[Size axiom]
    We say that a centrality $\ce f$ satisfies the \emph{size axiom} iff for every fixed $p$, there exists $k_0$ such that for all $k\geq k_0$, $\ce f_S(x) > \ce f_S(y)$, and for every fixed $k$, there exists $p_0$ such that for all $p\geq p_0$, $\ce f_S(x) < \ce f_S(y)$.
\end{definition}


Given a coefficient vector $\vc a$, the geometric linear centralities of $x$ and $y$ in the two graphs $S$ and $S_{xy}$ are given by:
\begin{alignat*}{2}
    \celg{a}{S_{xy}}(x) &= a_0 + k \cdot a_1 + \sum_{i=2}^p a_i && \celg{a}{S}(x) = a_0 + (k-1) \cdot a_1 \\
    \celg{a}{S_{xy}}(y) &= a_0 + 2 \cdot a_1 + (k-1) \cdot a_2 + \sum_{i=2}^{p-1} a_i \qquad\quad && \celg{a}{S}(y) = \sum_{i=0}^{p-1} a_i.
\end{alignat*}

For the density axiom, we have that:
\begin{proposition}\label{prop:density}
$\celg{a}{}$ satisfies the density axiom iff:
\[
        a_k > k(a_2 - a_1) + (2a_1 - a_2)
\]
for all $k \geq 3$.
\end{proposition}
\begin{proof}
We start observing that     
\begin{align*}
        \celg{a}{S_{xy}}(x) - \celg{a}{S_{xy}}(y) & = (k-2) a_1 + (1-k) a_2 + a_p \\
        & = k (a_1 - a_2) + (a_2 - 2a_1) + a_p. 
\end{align*}
So, the condition
\[
        \celg{a}{S_{xy}}(x) > \celg{a}{S_{xy}}(y)
\]
for $p=k$ is equivalent to 
\[
        a_k > k(a_2 - a_1) + (2a_1 - a_2).
\]\qed
\end{proof}

We now turn to the size axiom:

\begin{proposition}\label{prop:size}
    $\cel{a}$ satisfies the size axiom iff $a_1 > 0$ and $\sum_{i} a_i$ diverges.
\end{proposition}
\begin{proof}
    The size axiom requires that
    \begin{equation}
        \label{eqn:sizefixp}
        \celg{a}{S}(x) > \celg{a}{S}(y)
    \end{equation}
    holds ultimately (in $k$) for every fixed $p$, whereas 
    \begin{equation}
        \label{eqn:sizefixk}
        \celg{a}{S}(x) < \celg{a}{S}(y)
    \end{equation}
    should hold ultimately (in $p$) for every fixed $k$.
    This time we have:
    \[
        \celg{a}{S}(x) - \celg{a}{S}(y) = a_0 + (k-1) a_1 - \sum_{i=0}^{p-1} a_i.
    \]
    For~\eqref{eqn:sizefixp} to hold, we must have that for every fixed $p$
    \begin{equation}
        \label{eqn:sizefixpbis}
        (k-1) a_1 > \sum_{i=1}^{p-1} a_i
    \end{equation}
    holds for sufficiently large $k$. If $a_1<0$, there is an upper bound on the largest $k$ for which~\eqref{eqn:sizefixpbis} can hold:
    \[
        k < \frac{\sum_{i=1}^{p-1} a_i}{a_1} + 1.   
    \]
    So we must have $a_1 \geq 0$.
    For~\eqref{eqn:sizefixk} to hold, we must have that for every fixed $k$
    \begin{equation}
        \label{eqn:sizefixkbis}
        (k-1) a_1 < \sum_{i=1}^{p-1} a_i
    \end{equation}
    holds for sufficiently large $p$.  If $a_1=0$, this condition is incompatible with~\eqref{eqn:sizefixpbis}.

    We conclude that $a_1>0$. On the other hand, when $a_1>0$,~\eqref{eqn:sizefixkbis} implies the statement.\qed
\end{proof}

Power-law and exponential decay centralities~\cite{BDFSRSMCBDDC} are special cases of linear centralities;
the former have coefficients of the form $a_i = 1/i^\gamma$ for some $\gamma>0$ and $i>0$, with $\gamma=1$ corresponding to harmonic centrality. 
The latter, instead, have coefficients of the form $a_i = \delta^i$ for some $\delta\in(0,1)$ and $i>0$;
in both cases, as usual, we have $a_0=0$.
From the properties above we can conclude that:

\begin{corollary}
    Power-law decay centralities always satisfy the density axiom, and they satisfy the size axiom iff $\gamma\leq1$.
\end{corollary}
\begin{proof}
    The only non-trivial part of the proof is showing that the density axiom holds.

    We have that $a_k = k^{-\gamma}$, for some $\gamma>0$. Consider the inequality of Proposition~\ref{prop:density}, that in this case becomes:
    \begin{equation}
        \label{eqn:proofpld}
        k^{-\gamma} > k(2^{-\gamma}-1) + 2 - 2^{-\gamma}.
    \end{equation}
    When $k=3$, the right-hand side is $2^{1-\gamma}-1$, which is negative or null for $\gamma \geq 1$ (and a fortiori for larger values of $k$, because the coefficient of $k$ itself is negative), so~\eqref{eqn:proofpld} certainly holds for all $k \geq 3$. 
    We are left to consider the case $\gamma \in (0,1)$. Let us study at the function
    \[
        f(k) = k^{-\gamma} - k(2^{-\gamma}-1) - 2 + 2^{-\gamma}.
    \]
    for $\gamma \in (0,1)$. 
    Since 
    \[
        f'(k)=-\gamma k^{-(\gamma+1)} - (2^{-\gamma}-1),
    \]
    the derivative $f'(k)$ is null at
    \[
        k_0 = \exp\left(-\frac{\log\left(\frac{1-2^{-\gamma}}{\gamma}\right)}{\gamma+1}\right) = \left( \frac\gamma{1-2^{-\gamma}}\right)^{\frac1{\gamma+1}}.
    \]
    Since $f(1)=f(2)=0$, by Rolle's theorem we have that $k_0 \in (1,2)$.

    As a result, $f$ is monotonic for $k\geq 3$; its value at 3 is:
    \[
            f(3)=3^{-\gamma}-3(2^{-\gamma}-1) - 2 + 2^{-\gamma} = 3^{-\gamma} - 2^{1-\gamma} + 1 > 0.
    \]
    On the other hand, 
    \[
        \lim_{k \to \infty} f(k)=\infty.
    \]
 So the function $f(k)$ is increasing, hence positive, for $k \geq 3$.\qed
\end{proof}

\begin{corollary}
    Exponential decay centralities always satisfy the density axiom, and never satisfy the size axiom.
\end{corollary}
\begin{proof}
    Once again, the only non-trivial part of the proof is showing that the density axiom holds.
    The inequality of Proposition~\ref{prop:density} in this case is:
    \[
        \delta^k > k(\delta^2 - \delta) + 2 \delta - \delta^2;
    \]
    thus, we want to show that
    \[
        f(k) = \delta^k + k(\delta - \delta^2) + \delta^2 - 2\delta 
    \]
    is positive for all $\delta\in(0,1)$ and $k\geq 3$.
    The derivative of the function is
    \[
        f'(k) = \delta^k \log\delta + \delta - \delta^2;
    \]
    let us call $k_0$ the value in which $f'(k)$ is null, that is,
    \[
        k_0 = \frac{\log\left(\frac{\delta^2 - \delta}{\log(\delta)}\right)}{\log(\delta)}.
    \]

    Noting that $f(1)=f(2)=0$, we can state by Rolle's theorem that $k_0\in(1,2)$, since it is the only stationary point of the function $f$.
    Finally, we highlight that
    \[
        f(3) = \delta^3 + 3(\delta - \delta^2) + \delta^2 - 2\delta = \delta^3 - 2\delta^2 + \delta =\delta(\delta-1)^2 > 0,
    \]
    and
    \[
        \lim_{k\to\infty} f(k) = \infty.
    \]
    Again, the function is increasing, hence positive, for $k\geq 3$.\qed


\end{proof}

In particular, among power-law and exponential decay centralities, harmonic has the property of satisfying both axioms, and it is the one doing so with the fastest possible decay.


\subsection{Score monotonicity}

We now consider the score monotonicity axiom~\cite{BoVAC}, that is related to what happens to the centrality of node $y$ when an arc $x \to y$ is added to an arbitrary graph.

\begin{definition}[Score monotonicity]
    A centrality measure is \emph{score monotone} if for every graph $G$ and every pair of nodes $x$, $y$ such that $x\not\rightarrow y$, when we add $x\rightarrow y$ to $G$ the centrality of $y$ increases.
\end{definition}

To characterize score monotonicity, it is useful to introduce (as  we did in~\cite{BDFSRSMCBDDC}) the \emph{discrete derivative operator} $\Delta$ on sequences: given a sequence $\vc a$, we define $\Delta \vc a$ as the sequence
\[
    \left(\Delta \vc a\right)_i = a_{i+1} - a_i
\]
for all indices $i>0$, and $(\Delta \vc a)_0=0$.
It is also useful to write $\vc a \geq 0$ ($\vc a \leq 0$, respectively) to mean that $a_i \geq 0$ ($a_i \leq 0$, resp.) for all $i$.

Score monotonicity for linear centrality can then be characterized by the following:

\begin{proposition}
    \label{prop:scoremon}
    Given a coefficient vector $\vc a$, the centrality $\celg{a}{}$ is score monotone iff $\vc a \geq 0$, $\Delta \vc a \leq 0$ and $\left(\Delta \vc a\right)_1 < 0$.
\end{proposition}
\begin{proof}
    The condition can be restated as follows: $a_1 > a_2$ and $a_i \geq a_{i+1} \geq 0$ for all $i$.
    Given a graph $G$ and a pair of nodes $x,y$ such that $x\not\rightarrow y$, let us call $G'$ the graph obtained from $G$ by adding the arc $x\rightarrow y$.
    Let us assume that $a_1 > a_i \geq a_{i+1} \geq 0$ for all $i\geq2$, and call $d'(z)=d_{G'}(z,y)$ and $d(z)=d_{G}(z,y)$ for all $z\in V_G$.
    Adding an arc in a graph cannot increase distances, that is:
    \begin{equation*}
        d'(z) \leq d(z) \text{ for all } z\in V_G,
    \end{equation*}
    which implies that $a_{d'(z)} \geq a_{d(z)}$, with the two inequalities being strict when $z=x$.
    Noting that linear centralities can be expressed also as summation over nodes, we can state that:
    \begin{align*}
        \celg{a}{G'}(y) = \sum_{z\in V_G} a_{d'(z)} 
        > \sum_{z\in V_G} a_{d(z)} = \celg{a}{G}(y),
    \end{align*}
    where, again, the inequality is strict because it is so when $z=x$.

    For the ``only if'' part of the proof, we consider the following cases, and provide for each of them an example on which $\celg{a}{}$ fails to be score monotone.

    \noindent\emph{(a) Case $a_1\leq 0$.} Suppose $a_1 \leq 0$ and consider the following graph $G$: 
    \[
        \begin{tikzpicture}[main/.style = {draw, circle}, node distance=1cm]
            \node[main] (y) at (0, 0) {$y$};
            \node[main] (x) at (1.5, 0) {$x$};
            \draw[<-,dashed] (y)--(x);
        \end{tikzpicture}
    \]
    We would then have
    \[
        \celg{a}{G'}(y)=a_1 \leq 0 = \celg{a}{G}(y).
    \]

    \noindent\emph{(b) Case $a_i<0$.}
    Suppose $a_1>0$ but $a_i<0$ for some $i>1$. Let $i$ be the smallest such index, and $k$ be defined by
    \[
        k = \left\lceil\frac{a_1+\dots+a_{i-1}+1}{|a_i|}\right\rceil
    \]
    and consider the following graph $G$:
    \[
        \begin{tikzpicture}[main/.style = {draw, circle}, node distance=1cm]
            \node[main] (z0) at (0, 0) {$y$};
            \node[main] (z1) at (1.5, 0) {$x$};
            \node[main] (z2) at (3, 0) {$z_2$};
            \node (z3) at (4.5, 0) {\dots};
            \node[main] (zim) at (6, 0) {$z_{i-1}$};
            \node[main] (zi1) at (7.5, 1.5) {$z_i^1$};
            \node[main] (zi2) at (7.5, 0.5) {$z_i^2$};
            \node (zi3) at (7.5, -0.5) {$\vdots$};
            \node[main] (zik) at (7.5, -1.5) {$z_i^k$};
            \draw[<-,dashed] (z0)--(z1);
            \draw[<-] (z1)--(z2);
            \draw[<-] (z2)--(z3);
            \draw[<-] (z3)--(zim);
            \draw[<-] (zim)--(zi1);
            \draw[<-] (zim)--(zi2);
            \draw[<-] (zim)--(zik);
        \end{tikzpicture}
    \]
    We have that:
    \begin{multline*}
        \celg{a}{G'}(y)=a_1+a_2+\dots+a_{i-1}+k \cdot a_i =\\
        =a_1+a_2+\dots+a_{i-1}-k \cdot |a_i| \leq\\ 
        \leq a_1+a_2+\dots+a_{i-1}-(a_1+\dots+a_{i-1}+1) < 0 = \celg{a}{G}(y).
    \end{multline*}

    \noindent\emph{(c) Case $a_i<a_{i+1}$.}
    To complete our proof, suppose that $a_1>0$ and $a_i \geq 0$ for all $i>1$, but
    that $a_i < a_{i+1}$ for some $i \geq 1$; let $i$ be the smallest such index $i$, and $k$ be defined by:
    \[
        k = \left\lceil\frac{a_1+1}{a_{i+1}-a_i}\right\rceil
    \]
    Consider the following graph $G$.
    \[
        \begin{tikzpicture}[main/.style = {draw, circle}, node distance=1cm]
            \node[main] (y) at (0, 0) {$y$};
            \node[main] (z) at (1.5, 1) {$z$};
            \node[main] (x) at (3, 0) {$x$};
            \node[main] (w2) at (4.5, 0) {$w_3$};
            \node (w3) at (6, 0) {\dots};
            \node[main] (wi) at (7.5, 0) {$w_i$};
            \node[main] (wip11) at (9, 1) {$w_{i+1}^1$};
            \node (wip13) at (9, 0) {$\vdots$};
            \node[main] (wip1k) at (9, -1) {$w_{i+1}^k$};
            \draw[<-,dashed] (y)--(x);
            \draw[<-] (y)--(z);
            \draw[<-] (z)--(x);
            \draw[<-] (x)--(w2);
            \draw[<-] (w2)--(w3);
            \draw[<-] (w3)--(wi);
            \draw[<-] (wi)--(wip11);
            \draw[<-] (wi)--(wip1k);
        \end{tikzpicture}
    \]
    We have:
    \begin{eqnarray*}
        \celg{a}{G}(y) &=& a_1+a_2+\dots+k\cdot a_{i+1}\\
        \celg{a}{G'}(y) &=& 2a_1+a_2+\dots+k\cdot a_{i}.
    \end{eqnarray*}
    Hence
    \[
        \celg{a}{G}(y)-\celg{a}{G'}(y) = -a_1+a_i+k(a_{i+1}-a_i) > 0,
    \]
    that is, $\celg{a}{G'}(y)<\celg{a}{G}(y)$.\qed
\end{proof}


\subsection{Rank monotonicity}

The rank monotonicity axiom~\cite{BLVRMCM} considers the same scenario as for score monotonicity, but this time looking at what happens to the relation between the centrality of $y$ and that of \emph{other} nodes.

\begin{definition}[Rank monotonicity]
    A centrality measure is \emph{rank monotone}\footnote{This is called ``strict'' rank monotonicity in~\cite{BLVRMCM}, but in this paper we are not going to treat the weak case.} if for every graph $G$ and every pair of nodes $x$, $y$ such that $x\not\rightarrow y$, when we add $x\rightarrow y$ to $G$ the following happens for all nodes $w$:
    \begin{itemize}
        \item if the score of $w\neq y$ was smaller than or equal to the score of $y$, after adding $x\rightarrow y$ the score of $w$ is smaller than the score of $y$.
    \end{itemize}
\end{definition}


The first property we prove is that score monotonicity is necessary for rank monotonicity:

\begin{lemma}
    \label{lemma:twocopies}
    Given a coefficient vector $\vc a$, if $\celg{a}{}$ is rank monotone, then it is score monotone.
\end{lemma}
\begin{proof}
    Suppose, by contradiction, that $\celg{a}{}$ is rank monotone but not score monotone, and let $G$ be a graph for which score monotonicity fails.
    Let $\overline G$ be an identical copy of $G$ (the nodes of $\overline G$ have the same names as those of $G$, with an $\overline{\cdot}$ to distinguish them).
    For the moment, assume that $a_1 > 0$, and consider the graph:
    \[
        H = G \oplus \overline G 
    \]
    where $\oplus$ denotes disjoint union.
    Of course
    \[
        \celg{a}{H}(y) = \celg{a}{G}(y) = \celg{a}{\overline G}(\overline y)=\celg{a}{H}(\overline y).
    \]
    If we add $x \to y$ to the graph $H$, without any other modification, and let $H'$ be the new graph, we have (because score monotonicity does not hold):
    \[
        \celg{a}{H'}(y) = \celg{a}{G'}(y) \le \celg{a}{G}(y) = \celg{a}{H}(\overline y).
    \]
    So the score of $y$ in $H$ used to be $\geq$ (in fact: equal) to the score of $\overline y$, but it should become strictly higher once the arc $x \to y$ is added, which does not happen if score monotonicity fails.\qed
\end{proof}

Hence, if we want to look for vectors $\vc a$ for which rank monotonicity holds, we can limit ourselves to those for which score monotonicity holds as well.

Like in~\cite{BDFSRSMCBDDC}, we will show that rank monotonicity is related to the second-order discrete derivative $\Delta^2 \vc a$ of the coefficient vector $\vc a$ (obtained from $\vc a$ by applying the operator $\Delta$ twice).
To characterize rank monotonicity, we will need the following lemma:

\begin{lemma}[Lemma 5.1 of~\cite{BDFSRSMCBDDC}]
    \label{lemma:convexity}
    Given a coefficient vector $\vc a$, if $\Delta^2 \vc a \geq 0$ then for all $i,j,k,\ell$ with $i \leq j$, $k \geq 0$, $0\leq \ell \leq j-i$ we have:
    \[
        a_{i+k} - a_{j+k-\ell} \leq a_i - a_j
    \]
    with the inequality being strict if $i<j$, $k>0$ and $\left(\Delta^2 \vc a\right)_i >0$.
\end{lemma}

We now present our conditions for rank monotonicity:
\begin{proposition}
    \label{prop:rankmon}
    Suppose that the coefficient vector $\vc a$ satisfies the following conditions:
    \begin{enumerate}
        \item $\celg{a}{}$  is score monotone, i.e., $\vc a \geq 0$, $\Delta \vc a \leq 0$ and $\left(\Delta \vc a\right)_1 < 0$;
        \item $\Delta^2 \vc a \geq 0$ and $\left(\Delta^2 \vc a\right)_1 > 0$.
    \end{enumerate}
    Then, the centrality $\celg{a}{}$ is rank monotone.
\end{proposition}
\begin{proof}
    Suppose that the two conditions hold, let $G$ be a graph and $G'$ the graph obtained after the addition of $x \to y$ to $G$, as usual. Let us use $d(-,-)$
    and $d'(-,-)$ to denote distances in $G$ and $G'$, respectively. 

    Consider any two nodes $z$ and $w$: of course $d'(z,w) \leq d(z,w)$ (because adding an arc cannot make distances larger); suppose that $d'(z,w)<d(z,w)$. 
    This means that there is a new shortest path from $z$ to $w$ using the new arc $x \to y$. Hence
    \begin{equation}
        \label{eqn:dleq}
        d'(z,w) = d(z,x) + 1 + d(y,w) \geq d'(z,y) + d(y,w).
    \end{equation}
    On the other hand, because of the triangular inequality
    \begin{equation}
        \label{eqn:triangular}
        d(z,w) \leq d(z,y)+d(y,w);
    \end{equation}
    hence, applying~\eqref{eqn:dleq} first and then~\eqref{eqn:triangular}, we have
    \begin{equation}
        \label{eqn:dleq2}
        d'(z,y) \leq  d'(z,w)-d(y,w) \leq d'(z,w)-d(z,w)+d(z,y).
    \end{equation}
    Let
    \begin{eqnarray*}
        i &=& d'(z,y)\\
        j &=& d(z,y)\\
        k &=& d'(z,w) - i = d'(z,w)-d'(z,y)\\
        \ell &=& j + k - d(z,w) = d'(z,w)-d(z,w)+d(z,y)-d'(z,y).
    \end{eqnarray*}
    Let us check that all conditions of Lemma~\ref{lemma:convexity} hold: $i\leq j$ holds because distances cannot become larger; $k\geq0$ holds because of~(\ref{eqn:dleq}); finally $\ell\geq 0$ (because of~\eqref{eqn:dleq2}) and
    \[
        \ell+i-j =i+k-d(z,w)=d'(z,w)-d(z,w) \leq 0.
    \]
    therefore $\ell\leq j-i$.
    Hence, applying the lemma we have:
    \begin{eqnarray}
        \label{eqn:score_increase}
        %a_{i+k} - a_{j+k-\ell} &\leq& a_{i} - a_{j}\\
        a_{d'(z,w)} - a_{d(z,w)} &\leq& a_{d'(z,y)} - a_{d(z,y)}.        
    \end{eqnarray}
    This relation holds for all $z$ such that $d'(z,w)<d(z,w)$, but it is trivially true also when $d'(z,w)=d(z,w)$, because the sequence $\vc a$ is non-increasing.

    Moreover, when $z=x$ and $w \neq y$, if $d'(x,w)<d(x,w)$ we have $i=d'(x,y)=1$, $j=d(x,y)>1=i$, $k=d'(x,w)-1>0$. Hence, the inequality~\eqref{eqn:score_increase} holds strictly for $z=x$. If otherwise $d'(x,w)=d(x,w)$, then still the inequality holds strictly, because $a_1>a_2 \geq a_j$, since $\left(\Delta \vc a\right)_1<0$.

    Recalling that 
    \[
        \celg{a}{G}(w)  = \sum_{z} a_{d(z,w)}  \qquad
        \celg{a}{G'}(w)  = \sum_{z} a_{d'(z,w)},
    \]
    we can state the following for all $w \neq y$:
    \begin{align*}
        \celg{a}{G'}(y)-\celg{a}{G}(y) & = \sum_{z} (a_{d'(z,y)}-a_{d(z,y)}) \\
        & > \sum_{z} (a_{d'(z,w)}-a_{d(z,w)}) = \celg{a}{G'}(w)-\celg{a}{G}(w).
    \end{align*}
    This means that the addition of the arc $x\to y$ increases the score of $y$ more than the score of any other node $w$, and this is enough to conclude that rank monotonicity holds for $\celg{a}{}$.\qed
\end{proof}

Observe that the conditions of Proposition~\ref{prop:rankmon} are sufficient for rank monotonicity, but not necessary (although score monotonicity is). We conjecture that they are also necessary: a clue in this direction is given in~\cite{BDFSRSMCBDDC}, where convexity is proven to be equivalent in the undirected case to a property known as ``basin dominance'', which implies rank monotonicity. But also in that case we were unable to prove that convexity is necessary for rank monotonicity.

\section{Distinguishable Coefficients}
\label{sec:distinguish}

A natural question we may want to ask is the following: how does $\celg{a}{G}$ change as a function of $\vc a$?
Is it possible that using different coefficients we end up defining equivalent linear centralities?
The short answer is no, unless the coefficient vectors differ by a positive multiplicative constant.
Let us provide a specific definition for this case.

\begin{definition}[Proportionality]
    \label{def:proportionality}
    We say that $\vc a, \vc b \in \RR^\NN$ are \emph{proportional} iff there is a $\lambda>0$ such that
    \begin{equation}
    \label{eqn:prop}
        b_k = \lambda \cdot a_k   \text{ for all $k>0$}.
    \end{equation}
\end{definition}

Observe that in the definition the 0-th coefficient has no role. For this reason, and for what we have said before, in the rest of this section we can safely assume that the $0$-th coefficient of all sequences is $0$.
Some observations are in order:
\begin{itemize}
    \item if $\vc a$ and $\vc b$ are proportional then for all $k>0$, either $a_k$ and $b_k$ are both zero, or they are both non-zero (and have the same sign);
    \item no sequence is proportional to $\vc 0=(0,0,0,\dots)$, except $\vc 0$ itself;
    \item if $\vc a$ and $\vc b$ are proportional, and $\vc a \neq \vc 0$, then the constant $\lambda>0$ of Definition~\ref{def:proportionality} is unique;
    %\item if $\vc a$ and $\vc b$ are not proportional, there exist an index $k>1$ and $\lambda>0$ such that $a_i=\lambda\cdot b_i$ for all $0 <i<k$, but $a_k\neq \lambda\cdot b_k$.
    \item if $\vc a$ and $\vc b$ are not proportional, one of the following mutually exclusive statements holds:
    \begin{itemize}
        \item[(a)] there is some $k>0$ such that $a_kb_k=0$ and $a_k\neq b_k$ (for example, $\vc a=(0,1,2,\dots)$ and $\vc b=(0,1,0,\dots)$, with $k=2$);
        \item[(b)] for all $i>0$, $a_i=0 \iff b_i=0$ and the minimum index $h$ such that $a_h\neq 0$ satisfies $b_h=\lambda\cdot a_h$ for some $\lambda<0$ (for example, $\vc a=(0,0,2,3,0,\dots)$ and $\vc b=(0,0,-4,-6,0,\dots)$, with $h=2$ and $\lambda=-2$); 
        \item[(c)] for all $i>0$, $a_i=0 \iff b_i=0$ and there exists an index $k>1$ and $\lambda>0$ such that $b_i=\lambda\cdot a_i$ for all $0 <i<k$, but $b_k\neq \lambda\cdot a_k$, and moreover $a_h\neq 0$ for some $0<h<k$ (for example, $\vc a=(0,1,2,3,0,\dots)$ and $\vc b=(0,2,4,9,0,\dots)$, with $k=3$ and $\lambda=2$).
    \end{itemize}
\end{itemize}

The only non-trivial observation is the last one, which we are now going to prove.
If there is any index for which either sequence is non-zero and the other is zero (case (a) above), there cannot exist a $\lambda>0$ for Definition~\ref{def:proportionality}. Now, let us assume that the zeroes are aligned (i.e., that they appear in the same positions in both sequences): there must be an index at which the sequences are both non-zero (for otherwise both sequences would be $\vc 0$ and proportional). Consider the minimum index $h$ at which they are both non-zero, and let $\lambda=a_h/b_h$. If $\lambda<0$, then case (b) of the last observation holds. If $\lambda>0$, since the sequences are non-proportional there must be a larger index $k$ such that $a_k \neq \lambda b_k$; the smaller such $k>h$ makes the statement of case (c) above true.

It is worth noting that case (c) above has some interesting implications:

\begin{lemma}
\label{lemma:altc}
    Given $\vc a$ and $\vc b$, if case (c) of the previous observation holds, then the values $a_h, a_k, b_h, b_k$ are all non-zero and $b_h a_k \neq b_k a_h$.
    Moreover, the inequality
    \begin{equation}
    \label{eqn:nonprop_cond}
        (a_h-a_k)(b_{h+1}-b_{k-1}) \neq (a_{h+1}-a_{k-1})(b_h-b_k)
    \end{equation}
    holds iff $a_{h+1} \neq a_{k-1}$ and $h+1<k$.
\end{lemma}

\begin{proof}
    We start by proving the first part of the statement.
    By assumption $a_h\neq 0$ and $b_h=\lambda a_h \neq 0$.
    Moreover, either $a_k$ and $b_k$ are both zero, or none of them is;
    if they are, then $b_k= \lambda a_k$, contradicting the hypothesis.
    Finally,
    \[
        b_h a_k = \lambda a_h a_k \neq a_h b_k.
    \]

    For the second part of the statement, assume that $a_{h+1} \neq a_{k-1}$ and $h+1<k$, and, by contradiction, consider the following chain of equalities:
    \begin{align*}
        (a_h-a_k)(b_{h+1}-b_{k-1}) & = (a_{h+1}-a_{k-1})(b_h-b_k)\\
        (a_h-a_k)(\lambda a_{h+1}-\lambda a_{k-1}) & = (a_{h+1}-a_{k-1})(\lambda a_h-b_k) \\
        \lambda a_h a_{h+1} - \lambda a_h a_{k-1} - \lambda a_{h+1} a_k + \lambda a_{k-1} a_k & = \lambda a_h a_{h+1} - a_{h+1} b_k - \lambda a_h a_{k-1} + a_{k-1} b_k \\
        - \lambda a_{h+1} a_k + \lambda a_{k-1} a_k & = - a_{h+1} b_k + a_{k-1} b_k \\
        \lambda a_k (a_{k-1} - a_{h+1}) & = b_k (a_{k-1} - a_{h+1}) \\
        \lambda a_k & = b_k,
    \end{align*}
    contradicting the assumptions.
    For the \q{only if} part, if $h+1=k$, we obtain
    \[
        (a_h-a_k)(b_k-b_h) = (a_k-a_h)(b_h-b_k),
    \]
    contradicting~\eqref{eqn:nonprop_cond}.
    On the other hand, if $h+1<k$ and $a_{h+1} = a_{k-1}$, then we have
    $a_{h+1} - a_{k-1}=0$ but also
    $b_{h+1} - b_{k-1} =\lambda (a_{h+1}-a_{k-1})=0$, again contradicting~\eqref{eqn:nonprop_cond}.\qed
\end{proof}

