        1 & 1 & 1 & 1 & 1 & \dots & 1 & 2 & 0 \\
        1 & 1 & 1 & 1 & 1 & \dots & 1 & 1 & 1 \\
    \end{bmatrix}
\end{equation*}
}
which is easily seen to have rank $n$ (it is lower-triangular with no zeros on its diagonal).
\qed\end{proof}

