\title{Tunable cavity coupling of a single \SnV center in nanodiamond across bad-emitter and bad-cavity regimes}

\author{S. Sachero\texorpdfstring{$^1$}{1}, R.Berghaus\texorpdfstring{$^1$}{1}, E. Nieto Hernandez\texorpdfstring{$^2$}{2}, F. Feuchtmayr\texorpdfstring{$^1$}{1},  N. Lettner\texorpdfstring{$^1$}{1}, P. Maier\texorpdfstring{$^1$}{1}, S. Ditalia Tchernij\texorpdfstring{$^2$}{2}, A. Kubanek\texorpdfstring{$^1,^3$}{1,3}}

