\subsection{The logarithmic limit set of a character variety}\label{subsec:log_limit_set}
The boundary slopes detected by the character variety are recovered by the \textbf{logarithmic limit set} of the eigenvalue variety. We list three definitions following \cite{B_logarithmic_limit_set}.
\medbreak
Let $I$ be an ideal in $\F[x_1^{\pm},\cdots,x_n^{\pm}]$ and  $V = V(I)$ be the variety in $(\F\backslash\{0\})^n$. 
\begin{enumerate}
    \item An absolute value function on $\F$ is a function $|\cdot|: \F\to\R_{\geq 0}$ such that $|0| = 0$, $|1| = 1$, $|xy| = |x||y|$,
$|x+y|\leq|x|+|y|$ and there exists $x\in \F$ such that $0 < |x| < 1$. $V_{log}$ is the set of limit points on $S^{n-1}$ of the set 
    \[\Bigl\{\dfrac{(\log |x_1|,\cdots,\log |x_n|)}{\sqrt{1+\sum_{i=1}^n (\log |x_i|)^2}}\mid (x_1,\cdots,x_n)\in V\Bigr\}\]
    \item The \textbf{tropical variety} $V_{val}$ is the set of $n$-tuples
    \[ (-v(x_1),\cdots,-v(x_n))\]
    where $v$ is any real-valued valuation on $\mathbb{\F}[x_1^{\pm},\cdots,x_n^{\pm}]/I$ such that $\sum_{i=1}^n v(x_i)^2 = 1$.
    \item Let the support $s(f)$ of $f\in \mathbb{\F}[x_1^{\pm},\cdots,x_n^{\pm}]$ to be set of points $\alpha =(\alpha_1,\cdots,\alpha_n)\in \mathbb{Z}^n$ such that the monomial $X^\alpha = X^{\alpha_1}\cdots X^{\alpha_n}$ appears in $f$. Let $V_{sph}$ be the set of points $\xi\in S^{n-1}$ such that for any non-zero $f\in I$, the maximal value of $\xi\cdot \alpha$ is achieved at least twice. Geometrically, 
    \[V_{sph} = \cap_{f\neq0\in I}\text{Sph}(\text{Newt}(f))\] is the intersection of spherical duals of the Newton polytopes of all nonzero elements $f$ in $I$.
\end{enumerate}
\medbreak
It is shown in \cite{B_logarithmic_limit_set} that $V_\infty  = V_{val} = V_{sph}$ and $V_{log}\subseteq V_{\infty} $ is a closed subset.
\medbreak
We denote $V_\infty(K_\F^M)$ as the logarithmic limit set of the eigenvalue variety $E_2^p(M)$. By symmetry, for any ideal point $(m_1,l_1,\cdots,m_i,l_i,\cdots,m_h,l_h)\in E_2^p(M)$, clearly the point $(m_1,l_1,\cdots,m_i^{-1},l_i^{-1},\cdots,m_h,l_h)$ is also in $E_2^p(M)$. Hence $(x_1,x_2,\cdots,x_{2i-1},x_{2i},\cdots ,x_{2h-1},x_{2h})$ is in $V_\infty(K_\F^M)$ implies that \linebreak $(x_1,x_2,\cdots,-x_{2i-1},-x_{2i},\cdots x_{2h-1},x_{2h})$ is in $V_\infty(K_\F^M)$. This induces a quotient map \[\mathbb{R}P^{2h-1}\to \mathbb{R}P^{2h-1}/\mathbb{Z}_2^{h-1}\cong S^{2h-1}\]
and extends to a map $\Psi: S^{2h-1}\to S^{2h-1}$. Let 
\[ T = \begin{pmatrix} 0 & 1\\ -1 & 0\end{pmatrix}\]
and $T_h$ be the block diagonal matrix consisting of $h$ copies of $T$.




\subsection{Dehn fillings}
Let $M$ be a irreducible, orientable compact $3$-manifold with boundary components consisting of tori $\partial_1 M, \partial_2 M,\cdots,\partial_n M$. Let $c_i$ be a slope of $\partial_i M$ for $1\leq i\leq n$ with empty slopes allowed. We denote the Dehn filled manifold obtained by filling $\partial_iM$ along $c_i$ as $M_{c_i}$. The main result in \cite{xuDehnfillings} concerning the profinite completions of the Dehn-filled manifolds is as follows.

\begin{lemma}[{\cite[Theorem A]{xuDehnfillings}}]\label{xustructuretheorem}
    Suppose $M$ and $N$ are orientable cusped finite-volume hyperbolic 3-manifolds and $\Phi:\widehat{\pi_1(M)}\to\widehat{\pi_1(N)}$ is a profinite isomorphism. Then
    \begin{enumerate}
        \item $\Phi$ respects the peripheral structure, i.e. there is a one-to-one correspondence between the boundary components of $M$ and $N$, which we simply denote as $\partial_iM\leftrightarrow\partial_iN$, so that $\Phi(\overline{\pi_1(\partial_iM}))$ is a conjugate of $\overline{\pi_1(\partial_iN)}$ in $\widehat{\pi_1(N)}$.
        \item Under the correspondence between the cusps $\partial_i M$ of $M$ and $\partial_{i}N$ of $N$, there is an isomorphism $\psi_i:\pi_1\partial_i M\to \pi_1\partial_i N$ such that, for any boundary slopes $(c_i)$ on $\partial M$ (allowing empty slopes), there is an isomorphism $\widehat{\pi_1(M_{c_i}})\cong\widehat{\pi_1(N_{\psi(c_i)})} $ that respects the peripheral structure.
        \item At the level of fundamental group, $\exists g_i\in\widehat{\pi_1(N)}$ and a profinite unit $\mu_i\in\hat{\Z}$ such that $m_{\mu_i}\circ\psi_i=  C_{g_i}\circ\Phi:\overline{\pi_1(\partial_iM)}\to\overline{\pi_1(\partial_iN)}$ where $m_{\mu_i}$ is multiplication by $\mu_i$ and $C_{g_i}$ is conjugation by $g_i$.
    \end{enumerate}
\end{lemma}

