\medbreak
We now improve a result of \cite{ptilmanngarden} so that the $A$-polynomial over $\SL(2,\C)$ is determined by the mod-$p$ $A$-polynomials. This shows that the $A$-polynomial is a regular profinite invariant in \Cref{pro:A_poly_profinite_inv}. To do so, we need the following lemma using some algebraic geometry. We say that a polynomial $f$ over a field $k$ is \textit{reduced} if it has no multiple factor when considered over $\bar{k}$.

\begin{lemma}\label{lem:polynomial_reduction}
If $f\in\Z[m,l]$ is reduced when considered over $\bar{\Q}$, then for all but finitely many prime $p$, $\overline{f} = f\bmod p$ is reduced over $\bar{\F}_p$.
\begin{proof}
    Denote $\varphi:\Spec \Z[m,l]/(f)\to \Spec \Z$ as the structure morphism of the natural map from $\Z$ to $\Z[m,l]/(f)$. We aim to apply the following lemma in the stack project:
\begin{lemma}[{\cite[\href{https://stacks.math.columbia.edu/tag/0578}{Lemma 0578}]{stacks-project}}]\label{lem:scheme_morphism}
    Let $\varphi:X\to Y$ be a morphism of schemes. Assume that
    \begin{enumerate}
        \item $Y$ is irreducible with generic point $\eta$,
        \item $X_\eta$ is geometrically reduced,
        \item $f$ is of finite type.
    \end{enumerate}
    Then there exists a nonempty open subscheme $V\subset Y$ such that $X_V\to V$ has geometrically reduced fibers.
\end{lemma}
Clearly $Y =\Spec \Z$ is irreducible with the unique generic point $(0)$. Note that \[X_{(0)}\times_{\Spec\Q}\Spec\bar{\Q}\cong \Spec \bar{\Q}[m,l]/(f)\]
$f$ is reduced implies that $X_{(0)}\times_{\Spec\Q}\Spec\bar{\Q}$ is reduced. $\varphi$ is clearly of finite type. Thus, there is an nonempty open subset $V$ of $\Spec\Z$ satisfying the conclusion in \Cref{lem:scheme_morphism}. $V$ must be of form \[V = \Spec \Z \backslash \{(p_i)\mid \text{prime }p_i \text{ for } i = 1,\cdots,n \}\]Then, for all but finitely many prime $p$,
\[X_{p}\times_{\Spec\F_p}\Spec\bar{\F}_p\cong \Spec \bar{\F}_p[m,l]/(\bar{f})\]
is reduced where $\bar{f} = f\bmod p$ and $\overline{f}$ is reduced over $\bar{\F}_p$. 
\end{proof}
\end{lemma}


\begin{proposition}\label{pro:A_poly_profinite_inv}
    Let $N_1,N_2$ be regularly profinitely equivalent 1-cusped finite-volume hyperbolic 3-manifolds. Then $A_0^{N_1}(L,M)\cong A_0^{N_2}(L,M)$. 
    \begin{proof}
Let $M$ be an one-cusped $3$-manifold and denote its A-polynomials as $A_0$ and $A_p$. For a prime $p$, denote $\overline{A_0} = A_0 \bmod p$.
By \cite[Lemma 40]{ptilmanngarden}, for all but finitely many prime $p$,
\[\overline{A_0}(l,m) = g(l,m)A_p(l,m)\]
where $g\in \Z_p[l,m]$ consists of factors appearing in $A_p$. Applying \Cref{lem:polynomial_reduction}, $\overline{A_0}$ is reduced so that $g(l,m) = 1$ for all but finitely many $p$.
\medbreak
If $\widehat{\pi_1(N_1)}\cong \widehat{\pi_1(N_2)}$, the mod $p$ $A$-polynomials $A_p^{N_1}(l,m), A_p^{N_2}(l,m)$ agree for all prime $p$. Then $\overline{A_0^{N_1}}(l,m) = \overline{A_0^{N_2}}(l,m)$ for all but finitely many prime $p$, this forces the result.
\end{proof}
\end{proposition}
\begin{theorem}\label{onecusp}
    Let $N_1$ be a 1-cusped hyperbolic 3-manifold, and let $N_2$ be a 3-manifold with a regular isomorphism $\Phi:\widehat{\pi_1(N_1)}\cong\widehat{\pi_1(N_2)}$. Then there is a bijection between the strongly detected boundary slopes of $N_1$ and $N_2$. The Xu ( \cite[Theorem A]{xuDehnfillings}) correspondence of slopes restricts to this bijection on strongly detected boundary slopes. 
    \begin{proof}
    By Theorem 47 of \cite{ptilmanngarden}, a boundary slope is strongly detected in characteristic $0$ if and only if it is strongly detected in characteristic $p$ for all but finitely many primes $p$. 
    \medbreak By Lemma~\ref{mod_p_A-polynomial}, we show that the characteristic $p$ $A-$polynomial $A_p$ is a profinite invariant, i.e. that both cusped 3-manifolds have the same characteristic $p$ $A-$polynomial. Since the boundary slopes of the Newton polygon for $A_p^{N_1}(L,M)=A_p^{N_2}(L,M)$ are the strongly detected boundary slopes for $X(\pi_1(N_1),\F)\cong X(\pi_1(N_2),\F)$  by Theorem 37 \cite{ptilmanngarden}, $N_1,N_2$ have the same set of strongly detected boundary slopes in characteristic $0$.
    \medbreak
    It remains to show that the bijection between strongly detected boundary slopes is a restriction of Xu's correspondence in Lemma~\ref{xustructuretheorem}. For a fixed identification $\Phi:\widehat{\pi_1(N_1)}\to\widehat{\pi_1(N_2)}$, and for a strongly detected boundary slope $c\in\partial N_1$ corresponding to a primitive element in $\Z^2\cong\pi_1(\partial N_1)$, $c=m^\alpha l^\beta$ where $\{m,l\}$ is a basis for $\Z^2$ and $\alpha,\beta\in\Z$. There is an element $g\in\widehat{\pi_1(N_2)}$ such that $g\Phi(\overline{\pi_1(\partial N_1)})g^{-1}=\pi_1(\partial N_2)$. Let the ``conjugation by $g$" map be denoted by $C_g:\widehat{\pi_1(N_2)}\to\widehat{\pi_1(N_2)}$. There is a profinite unit $\mu\in\hat{\Z}^\times$ such $\mu\circ C_g\circ \Phi|_{\pi_1(\partial N_1)}$ has image $\pi_1(\partial N_2)$, and this is the isomorphism induced on $\pi_1$ by the map called $\psi_i$ in Lemma~\ref{xustructuretheorem} (b). We denote this isomorphism on the cusps by $\pi_1(\psi_i)$. The set $\{m',l'\}=\{\pi_1(\psi_i)(m),\pi_1(\psi_i)(l)\}$ is a basis for $\pi_1(\partial N_2)$ since $\pi_1\psi_i$ is an isomorphism and $\{m,l\}$ is a basis of $\Z^2\cong\pi_1(\partial N_1)$. To show that $m'^\alpha l'^\beta$ is a strongly detected boundary slope for $N_2$, we apply Lemma~\ref{mod_p_A-polynomial} to see that for all primes $p$, $A_p^{N_1}(L,M)=A_p^{N_2}(L,M)\in \Z_p[m^\pm,l^\pm]$ and therefore by Lemma~\ref{TG_slope_theorem} and Lemma~\ref{bslopesarebslopes}, $m'^\alpha l'^\beta$ is a strongly detected boundary slope for $N_2$. 
    \end{proof}
\end{theorem}

\section{The case of multiple cusps}
\noindent To handle the case of hyperbolic 3-manifolds with multiple boundary components, we show that the {\it logarithmic limit set} of the character variety over characteristic $p$ is a regular profinite invariant. 
\begin{lemma}\label{lem:eigenval_variety}
Let $M,N$ be finite-volume cusped hyperbolic 3-manifolds with $\Phi:\widehat{\pi_1(M)}\to\widehat{\pi_1(N)}$ a regular
 isomorphism. The identification $\Phi$ induces an equality of the characteristic $p$ eigenvalue varieties $E_2(M,\F)=E_2(N,\F)$ and therefore an equality of the logarithmic limit sets $V_\infty(K^\mathbb{F})$ of $E_2^p(M)$. 
\begin{proof}
Fix $\F=\bar{\F}_p$ for some prime $p$. Similar as the proof in \Cref{mod_p_A-polynomial}, there is an identification $\Phi_*: R(N,\F)\to R(M,\F)$ sending $\rho$ to $(\hat{\rho}\circ \Phi)\mid_{\pi_1(M)}$. In addition, for each cusp correspondence $\partial_i M\leftrightarrow\partial_iN$, the restriction of $\hat{\rho}\circ\Phi$ to $\pi_1(\partial_{i}M)$ is $\hat{\rho}\circ (C_{g_i}\circ m_{\mu}\circ \psi_i)$ for some $g_i\in \widehat{\pi_1(N)}$ and $\mu = \pm 1\in \hat{\Z}$. Fix a basis $\langle\mathcal{L}_i,\mathcal{M}_i\rangle$ of $\pi_1(\partial_i M)$ and $\langle\mathcal{L}_i',\mathcal{M}_i'\rangle = \langle\psi(\mathcal{L}_i'),\psi(\mathcal{M}_i')\rangle$ of $\pi_1(\partial_iN)$. The trace function $I_{\alpha}\in\F[R(M,\F)]$ maps to $I_{\psi_i(\alpha)}\in \F[R(N,\F)]$ for any $\alpha\in \partial_i(M)$, which implies $R_E(M,\F)=R_E(N,\F)$ by definition. This directly implies the equality $E_2(M,\F)=E_2(N,\F)$ and the equality of the logarithmic limit sets.

\end{proof}
\end{lemma}
