Let $G$ be a graph and $S$ be a non-empty subset of its vertex set $V(G)$. The notation $G - S$ represents the induced subgraph formed by removing all vertices in $S$ and their incident edges from $G$. When $S$ consists of a single vertex $x$, we simplify the notation to $G - x$. Similarly, for any subgraph $H$ of $G$, we use $G - H$ to denote the subgraph obtained from $G$ by deleting all vertices of $H$ and their incident edges.
Denote by $H + x$  the subgraph induced by the vertex set $V(H) \cup \{x\}$.

Let $\mathfrak{G}_{0}$ be the set of connected mixed graphs $\widetilde{G}$~($c(G)\geq 1$) with pairwise vertex-disjoint cycles which satisfies the following properties: (a) $\widetilde{G}$ containing no pendant vertices; (b)  $\widetilde{G}$ has a pendant odd cycle $\widetilde{C}_{q}$ with odd signature; (c) $r(\widetilde{H})=2m(H)-2c(H)$~(i.e. $\widetilde{H}$ satisfies three conditions in Theorem \ref{th:1.1}), where $\widetilde{H}=\widetilde{G}-V(C_{q})+x$ and $x$ is the unique vertex of degree $3$ in $C_q$.



For an even integer $p$ and two odd integers $q$ and $l$, we define the following four sets:
\begin{itemize}
\item $\mathfrak{X}_{1}$: the set of mixed bicyclic graphs $\widetilde{\infty}(p,1,q)$ whose odd cycle  has odd signature and even cycle $\widetilde{C}_{p}$  satisfies $\sigma(\widetilde{C}_{p})\equiv p~(\mathrm{mod}~4)$;

\item  $\mathfrak{X}_{2}$: the set of mixed bicyclic graphs $\widetilde{\theta}(p,l,q)$ whose two odd cycles have odd signatures and  even cycle $\widetilde{C}_{q+l-2}$ satisfies $q+l+\sigma(\widetilde{C}_{q+l-2})\equiv 2~(\mathrm{mod}~ 4)$;

    \item $\mathfrak{Y}_{1}$: the set of mixed bicyclic graphs $\widetilde{\infty}(p,1,q)$ whose odd cycle  has even signature and even cycle $\widetilde{C}_{p}$  satisfies $\sigma(\widetilde{C}_{p})\equiv p~(\mathrm{mod}~4)$;

    \item $\mathfrak{Y}_{2}$: the set of mixed bicyclic graphs $\widetilde{\theta}(p,l,q)$ whose two odd cycles have even signatures and even cycle $\widetilde{C}_{q+l-2}$ satisfies $q+l+\sigma(\widetilde{C}_{q+l-2})\equiv 2~(\mathrm{mod}~ 4)$.
    \end{itemize}

Let $\mathfrak{G}_{1}=\mathfrak{G}_{0}\cup \mathfrak{X}_{1} \cup \mathfrak{X}_{2}$.  Let $\mathfrak{G}_{2}$ be the set consisting of $\mathfrak{G}_{1}$ and mixed odd cycles with odd signature.

If $u$ is a pendant vertex of a mixed graph $\widetilde{G}$ and $v$ is its unique neighbor in $\widetilde{G}$, then the
operation of obtaining $\widetilde{G}-\{u, v\}$ from $\widetilde{G}$ is called a \emph{pendant $K_{2}$ deletion}. The resultant subgraph $\widetilde{G}_{0}$ of $\widetilde{G}$ without pendant vertices, obtained from $\widetilde{G}$ by applying a series of pendant $K_2$ deletion operations, is called a \emph{crucial subgraph} of $\widetilde{G}$.

Let $\mathfrak{F}_{0}$ be the set of connected mixed graphs $\widetilde{G}$~($c(G)\geq 2$) with pairwise vertex-disjoint cycles which satisfies the following properties: (a) $\widetilde{G}$ containing no pendant vertices; (b)  $\widetilde{G}$ has a pendant odd cycle  with even signature and each other cycle  $\widetilde{C}_{p}$ is even cycle with $\sigma({\widetilde{C}_p})\equiv p~(\mathrm{mod}~4)$; (c) a series of pendant $K_2$ deletion operations can switch $\widetilde{H}$ to a crucial subgraph $\widetilde{H}_1$, which is disjoint union of $c(H)$ even cycles and an odd cycle with even signature, where $\widetilde{H}=\widetilde{G}-V(C_{q})+x$, $\widetilde{C}_{q}$ is a pendant even cycle of $\widetilde{G}$ and $x$ is the unique vertex of degree $3$ of $C_q$.

\begin{remark}
In the definition of $\mathfrak{F}_{0}$, since $\widetilde{G}$  is connected with pairwise vertex-disjoint cycles, $c(G)\geq 2$ and $\widetilde{G}$ contains no pendant vertices,  $\widetilde{G}$ has exactly two pendant cycles.
So $\widetilde{G}$ must have a pendant even cycle $\widetilde{C}_{q}$.
\end{remark}

Let $\mathfrak{F}_{1}=\mathfrak{F}_{0}\cup \mathfrak{Y}_{1}\cup \mathfrak{Y}_{2}$. Let $\mathfrak{F}_{2}$ be the set consisting of $\mathfrak{F}_{1}$ and mixed odd cycles with even signature.



We characterize some classes of mixed graphs with rank $r(\widetilde{G})=2m(G)-2\kappa(G)$ and $r(\widetilde{G})=2m(G)-2\kappa(G)+1$, respectively.


\noindent\begin{theorem}\label{th:1.3}
Let $\widetilde{G}$ be a mixed graph and $\kappa(G)=c(G)-1$. Then $r(\widetilde{G})=2m(G)-2\kappa(G)$ if and only if the following conditions both hold:
\begin{enumerate}[(a)]
\item any two even cycles (if any) of $\widetilde{G}$ share no common vertices;
%\item  each even cycle $\widetilde{C}_{q}$ (if any) of $\widetilde{G}$ satisfies  $\eta(\widetilde{C}_{q})\equiv q~(\mathrm{mod}~4)$;
\item  a series of pendant $K_{2}$ deletion operations can switch $\widetilde{G}$ to a crucial subgraph $\widetilde{G}_{1}$ with $\kappa(\widetilde{G}_{1})=\kappa(\widetilde{G})$, which is an empty  graph or has at most a connected component that is a graph in  $\mathfrak{G}_{2}$ and each other connected component is either an even cycle $\widetilde{C}_{q}$ with $\sigma(\widetilde{C}_{q})\equiv q~(\mathrm{mod}~4)$ or an isolated vertex.
\end{enumerate}
\end{theorem}


\noindent\begin{theorem}\label{th:1.4}
Let $\widetilde{G}$ be a mixed graph and $\kappa(G)=c(G)-1$. Then $r(\widetilde{G})=2m(G)-2\kappa(G)+1$ if and only if the following conditions both hold:
\begin{enumerate}[(a)]
\item any two even cycles (if any) of $\widetilde{G}$ share no common vertices;
%\item  each even cycle $\widetilde{C}_{q}$ (if any) of $\widetilde{G}$ satisfies $\eta(\widetilde{C}_{q})\equiv q~(\mathrm{mod}~4)$;
\item  a series of pendant $K_{2}$ deletion operations can switch $\widetilde{G}$ to a crucial subgraph $\widetilde{G}_{1}$ with $\kappa(\widetilde{G}_{1})=\kappa(\widetilde{G})$, which has exactly a connected component that is a graph in  $\mathfrak{F}_{2}$ and each other connected component is  either an even cycle $\widetilde{C}_{q}$ with $\sigma(\widetilde{C}_{q})\equiv q~(\mathrm{mod}~4)$ or an isolated vertex.
\end{enumerate}
\end{theorem}

Define $E_1(C)$ as the edge set where one endpoint resides in $C$ while the other lies outside $C$. Let $\mathcal{F}$ denote the collection of functions $f$ satisfying $\sum_{e \in E(G)} f(e) = m^{\ast}(G)$ and $f(e) \in \left\{ 0, \frac{1}{2}, 1 \right\}$ for all $e \in E(G)$. A fractional matching $f$ of graph $G$ is termed an optimal fractional matching if $f \in \mathcal{F}$ and $f$ attains the largest number of edges with $f(e)=1$ within $\mathcal{F}$. It is evident that a perfect matching is an optimal fractional matching. For an optimal fractional matching $f$, we define $E_2(G)$ as $\left\{ e \in E(G) \mid f(e) = 1 \right\}$.
\begin{remark}
According to \cite{SU}, for any graph $G$, $2m^{\ast}(G)$ is an integer. Moreover, there is a fractional matching $f$ for which
$$\sum_{e\in E(G)} f(e) = m^{\ast}(G),$$ such that $f(e)\in \{0, \frac{1}{2}, 1\}$ for every edge $e$. Thus for any graph $G$, $\mathcal{F}\neq \emptyset$.
\end{remark}

 Some class of mixed graphs with rank  $r(\widetilde{G})=2m^{\ast}(G)$ is identified as follows.
\noindent\begin{theorem}\label{th:1.5}
Let $\widetilde{G}$ be a bipartite cycle-disjoint mixed graph of order $n$. Then $\widetilde{G}$ is nonsingular if and only if the following conditions both hold:
\begin{enumerate}[(a)]
\item $G$ has a perfect fractional matching;
\item there exists an optimal fractional matching, for any even cycle $\widetilde{C}_{q}$ with $\sigma(\widetilde{C}_{q})\equiv q~(\mathrm{mod}~4)$, $E_{1}(C_{q})\cap E_{2}(G)\neq \emptyset$.
\end{enumerate}
\end{theorem}

\begin{remark}
In Theorem \ref{th:1.5}, if $\widetilde{G}$ is nonsingular, then $r(\widetilde{G})=n$. Recall that in definition of fractional matching, we show that $2m^{\ast}(G)\leq n$.
 By Inequality $(2)$, $r(\widetilde{G})\leq 2m^{\ast}(G)\leq n$.  Thus $r(\widetilde{G})=2m^{\ast}(G)= n$.
\end{remark}

An \emph{oriented graph} $G^{\sigma}$ obtained from $G$ is defined by assigning to each edge of $G$ a direction $\sigma$, where $G$ is called the underlying graph of $G^{\sigma}$. The \emph{skew-adjacency matrix} associated to $G^{\sigma}$ of order $n$, denoted by $S(G^{\sigma})$, is defined as a matrix $(s_{xy})_{n \times n}$ such that $s_{xy}=1$ if there is an arc from $x$ to $y$, $s_{xy }= -1$ if there is an arc from $y$ to $x$ and $s_{xy}=0$ otherwise. The \emph{skew-rank} of $G^{\sigma}$, denoted by $sr(G^{\sigma})$, is defined to be the rank of $sr(G^{\sigma})$. Obviously, an oriented graph $G^{\sigma}$ can be regraded as a mixed graph $\widetilde{G}$ without undirected edges. Consequently, $H(\widetilde{G})=iS(G^{\sigma})$ and $r(\widetilde{G})=sr(G^{\sigma})$. Hence Theorems \ref{th:1.2}, \ref{th:1.3}, \ref{th:1.4} and \ref{th:1.5} can be applied to  oriented graphs.





