\noindent\begin{lemma}\label{le:2.1}\cite{M}
If $v$ is a vertex of a mixed graph $\widetilde{G}$, then $r(\widetilde{G})-2\leq r(\widetilde{G}-v)\leq r(\widetilde{G})$.
\end{lemma}


\noindent\begin{lemma}\label{le:2.2}\cite{WYL}
Let $\widetilde{G}$ be a mixed graph containing a pendant vertex $x$ with the unique neighbor $y$. Then $r(\widetilde{G})=r(\widetilde{G}-x-y)+2$.
\end{lemma}


\noindent\begin{lemma}\label{le:2.3}\cite{M}
Let $\widetilde{G}$ be a mixed graph.
\begin{enumerate}[(a)]
\item If $\widetilde{G}=\widetilde{G}_{1}\cup \widetilde{G}_{2}\cup \cdots \cup \widetilde{G}_{t}$, where $\widetilde{G}_{1}, \widetilde{G}_{2},\ldots, \widetilde{G}_{t}$ are connected components of $\widetilde{G}$, then $r(\widetilde{G})=\Sigma_{i=1}^{t} r(\widetilde{G}_{i})$.
\item   $r(\widetilde{G})=0$ if and only if $\widetilde{G}$ is a graph without edges.
\end{enumerate}
\end{lemma}



 \noindent\begin{lemma}\label{le:2.4}\cite{CHL}
 Let $\widetilde{T}$ be a mixed tree. Then $r(\widetilde{T})=r(T)=2m(T)$.
\end{lemma}


\noindent\begin{lemma}\label{le:2.5}\cite{WYL}
%\cite{yqt}
Let $\widetilde{C}_{n}$ be a mixed cycle. Then
\begin{displaymath}
r(\widetilde{C_{n}})=\left\{\
\begin{array}{ll}
n-1, & \mathrm{if}~n~is~odd,~ \sigma(\widetilde{C}_{n})~is~odd;\\
n, & \mathrm{if}~n~is~odd,~ \sigma(\widetilde{C}_{n})~is~even;\\
n, & \mathrm{if}~n~is~even,~ \sigma(\widetilde{C}_{n})~is~odd;\\
n, & \mathrm{if}~n~is~even,~ n+\sigma(\widetilde{C}_{n})\equiv 2~(\mathrm{mod} ~4);\\
n-2, & \mathrm{if}~n~is~even,~ n+\sigma(\widetilde{C}_{n})\equiv 0~(\mathrm{mod} ~4).\\
\end{array}
\right.
\end{displaymath}
\end{lemma}





A \emph{gain graph} is a graph with the additional structure that each
orientation of an edge is given a group element, called a \emph{gain}, which is the inverse of
the group element assigned to the opposite orientation.  Denote by $\Phi=(G, \mathbb{T}, \varphi)$  a \emph{complex unit gain graph}, where $G$ is the underlying graph of $\Phi$, $\mathbb{T}= \{z\in \mathbb{C} : |z|=1\}$ is the \emph{circle group} and $\varphi: \overrightarrow{E} \rightarrow  \mathbb{T}$ is a gain function such that $\varphi(e_{ij})=\varphi(e_{ji})^{-1}=\overline{\varphi(e_{ji})}$.   The \emph{adjacency matrix} associated to  $\Phi$ is the Hermitian matrix $A(\Phi) = (a_{ij})_{n \times n}$, where $a_{ij}=\varphi(e_{ij})$ if $v_{i}$ is adjacent to $v_{j}$, otherwise $a_{ij}=0$.
%For convenience, $\varphi(e_{ij})$ is also written as  $\varphi(v_{i}v_{j})$ for $v_{i}v_{j}\in E(\Phi)$.
  Mixed graph is a special case when  $\varphi(\overrightarrow{E}) \subseteq \{1, i, -i\}$ for $\mathbb{T}$-gain graph. Hence, the following Lemma \ref{le:2.8} follows directly from Theorem 2.8 in \cite{LWX}.
\noindent\begin{lemma}\label{le:2.8}\cite{LWX}
Let $\widetilde{H}$ be a mixed graph and $\widetilde{C}_{n}$ be a mixed cycle.  Assume that $\widetilde{G}$ is the mixed graph obtained by identifying a vertex of $\widetilde{C}_{n}$ with a vertex of $\widetilde{H}$ (i.e. $V(\widetilde{C}_{n})\cap V(\widetilde{H})=x$). Let $\widetilde{F}=\widetilde{H}-x$. Then \begin{displaymath}
r(\widetilde{G})=\left\{\
\begin{array}{ll}
r(\widetilde{H})+n-1, & \mathrm{if}~n~is~odd,~ \sigma(\widetilde{C}_{n})~is~odd;\\
r(\widetilde{H})+n-2, & \mathrm{if}~n~is~even,~ \sigma(\widetilde{C}_{n})\equiv n~(\mathrm{mod}~4);\\
r(\widetilde{F})+n, & \mathrm{if}~n~is~even,~ either~ \sigma(\widetilde{C}_{n})+n\equiv 2~(\mathrm{mod}~4) ~or~ \sigma(\widetilde{C}_{n})~ is~ odd.
\end{array}
\right.
\end{displaymath}
\end{lemma}

\noindent\begin{lemma}\label{le:2.12}\cite{CG1,HHLG}
For any mixed graph $\widetilde{G}$, $r(\widetilde{G})\neq 2m(G)-2c(G)+1$.
\end{lemma}

Denote by  $\beta(G)$  the number of cycles in graph $G$.  The \emph{characteristic polynomial} of a mixed graph $\widetilde{G}$ of order $n$ is the characteristic polynomial of the Hermitian adjacency matrix of $\widetilde{G}$, defined as $f(\widetilde{G}, \lambda)=\mathrm{det}|\lambda I_{n}-H(\widetilde{G})|=\sum_{i=0}^{n}a_{i}\lambda^{n-i}$, where $I_{n}$ denotes the unite matrix of order $n$.
\noindent\begin{lemma}\label{le:2.9}\cite{CHL}
Let $\widetilde{G}$ be a mixed graph of order $n$. Then the characteristic polynomial $f(\widetilde{G}, \lambda)=\sum_{i=0}^{n}a_{i}\lambda^{n-i}$
has coefficients equal to $$a_{i}=\sum_{\widetilde{B}} (-1)^{\frac{1}{2}\sigma(\widetilde{B})+\omega(B)}2^{\beta(B)},$$
where the sum runs over all basic subgraphs $\widetilde{B}$ of order $i$ in $\widetilde{G}$.
\end{lemma}


\noindent\begin{lemma}\label{le:2.14}\cite{CHL}
Let $\widetilde{G}$ be a mixed graph containing a pendant vertex $x$ with unique neighbor $y$. If $r(\widetilde{G})= 2m(G)-2c(G)$, then
\begin{enumerate}[(a)]
\item $y$ lies outside any mixed cycle of $\widetilde{G}$;
\item $r(\widetilde{G}-x-y)=2m(G-x-y)-2c(G-x-y)$.
\end{enumerate}
\end{lemma}

For a simple graph, we have the following lemmas.
\noindent\begin{lemma}\label{le:2.6}\cite{CHL}
Let $G$ be a graph with a vertex $x$. Then $m(G)-1\leq m(G-x)\leq m(G)$.
\end{lemma}


\noindent\begin{lemma}\label{le:2.7}\cite{MWT}
Let $G$ be a graph with a pendant vertex $x$. Let $y$ be the unique neighbor of $x$. Then $m(G-y)=m(G-x-y)=m(G)-1$.
\end{lemma}


\noindent\begin{lemma}\label{le:2.10}\cite{CG}
Let $G$ be a graph with at least one cycle. Then the even cycles of $G$ are pairwise vertex-disjoint if and only if for any vertex $u$ of $G$ that lies on a even cycle,
$\kappa(G-u)=\kappa(G)-1$.
\end{lemma}


\noindent\begin{lemma}\label{le:2.11}\cite{MWT}
Let $T$ be a tree with at least one edge. If $r(T)=r(T-W)$ for a subset $W$ of $V(T)$, then there is a pendant vertex $v$ of $T$ such that $v\notin W$.
\end{lemma}





\noindent\begin{lemma}\label{le:2.13}\cite{SU}
Let $G$ be a bipartite graph. Then $m^{\ast}(G)=m(G)$.
\end{lemma}

\noindent\begin{lemma}\label{le:2.15}\cite{FHLL}
Let $G$ be a graph with  a pendant odd cycle $C_{q}$ and $x$ be a vertex of $C_{q}$  of degree $3$. Let $F=G-V(C_{q})$ and $H=F+x$. Then $m(G)=m(H)+\frac{q-1}{2}$.
\end{lemma}

Let $M$ be a matching of a graph $G$. We say that a vertex $v$ of $G$ is $M$-\emph{saturated} if it is an endpoint of some edge of $M$. Similarly, we say that a vertex $v$ of $G$ is $M$-\emph{unsaturated} if it is not any endpoint of any edge of $M$. An $M$-\emph{alternating path}
in $G$ is a path whose edges are alternately in $M$ and $E(G)\setminus M$. If neither its origin nor its
terminus is saturated by $M$, the path is called an $M$-\emph{augmenting path}.

\noindent\begin{lemma}\label{le:2.16}(Berge's Theorem)\cite{BM}
A matching $M$ of a graph $G$ is a maximum matching if and only if $G$ contains no $M$-augmenting path.
\end{lemma}

\section{Proof of Theorem \ref{th:1.2}}
~~~~In this section, we will  prove that  $2m(G)-2\kappa(G)\leq r(\widetilde{G})\leq 2m^{\ast}(G)$ for a mixed graph $\widetilde{G}$. At first, we need the following two lemmas.
%We first give several technical lemmas about the rank of a mixed graph, which is useful for the proof of Theorem \ref{th:1.1}.







\noindent\begin{lemma}\label{le:3.1}\cite{CG}
If an even-cycle-free graph has a perfect matching, then it has a unique maximum matching.
\end{lemma}





\noindent\begin{lemma}\label{le:3.2}
If a mixed graph $\widetilde{G}$ has a unique maximum matching, then $r(\widetilde{G})\geq 2m(G)$.
\end{lemma}
\begin{proof} Let $m= m(G)$ and $f(\widetilde{G}, \lambda)=\sum_{i=0}^{n}a_{i}\lambda^{n-i}$ be characteristic polynomial of $\widetilde{G}$.
By Lemma \ref{le:2.9}, $$a_{i}=\sum_{\widetilde{B}} (-1)^{\frac{1}{2}\sigma(\widetilde{B})+\omega(B)}2^{\beta(B)},$$
where the sum runs over all basic subgraphs $\widetilde{B}$ of order $i$ in $\widetilde{G}$.


 Since $\widetilde{G}$ has a unique maximum matching, $\widetilde{G}$ has a unique basic subgraph of order $2m$ with $m$
copies of $K_{2}$. As a result, the expression for $a_{2m}$ includes a summand $(-1)^{m}$. Apart from this summand, each other component in the expression must be an even
integer, since each takes  the form $(-1)^{\frac{1}{2}\sigma(\widetilde{B})+\omega(B)}2^{\beta(B)}$ with $\beta(B)\geq 1$. Therefore, $a_{2m}$ is an odd integer and  $a_{2m}\neq 0$. From this, it follows that $r(\widetilde{G})\geq 2m(G)$.
 \end{proof}





\noindent\textbf{Proof of Theorem \ref{th:1.2}:} We first prove the upper bound. Let $r=r(\widetilde{G})$ and $f(\widetilde{G}, \lambda)=\sum_{i=0}^{n}a_{i}\lambda^{n-i}$ be characteristic polynomial of $\widetilde{G}$.
By Lemma \ref{le:2.9}, $$a_{i}=\sum_{\widetilde{B}} (-1)^{\frac{1}{2}\sigma(\widetilde{B})+\omega(B)}2^{\beta(B)},$$
where the sum runs over all basic subgraphs $\widetilde{B}$ of order $i$ in $\widetilde{G}$. So $a_{r}\neq 0$ as $r=r(\widetilde{G})$. Then there is a basic subgraph $\widetilde{H}$ of order $r$. Since a basic subgraph consists of disjoint cycles and single edges, $r=2m^{\ast}(H)\leq 2m^{\ast}(G)$.


Now we prove the lower bound. We apply induction on $\kappa(G)$. Suppose that $\kappa(G)=0$. Let $M$ be a maximum matching of $G$. Let $\widetilde{F}$ be the subgraph of $\widetilde{G}$ induced by all endpoints of the edges  of $M$. Clearly, $F$ contains no even cycle and has a perfect matching. By Lemma \ref{le:3.1}, $F$ has a unique maximum matching. By Lemma \ref{le:3.2}, $r(\widetilde{F})\geq 2m(F)=2m(G)$. Since $\widetilde{F}$ is an induced subgraph of $\widetilde{G}$, $r(\widetilde{G})\geq r(\widetilde{F})\geq 2m(G)$.

 Now assume that $\kappa(G)\geq 1$. Let $u$ be a vertex on some even cycle of $G$. Obviously, $\kappa(G-u)\leq \kappa(G)-1$. By induction hypothesis, $r(\widetilde{G}-u)\geq 2m(G-u)-2\kappa(G-u)$. By Lemmas \ref{le:2.1} and \ref{le:2.6}, we have $r(\widetilde{G})\geq r(\widetilde{G}-u)\geq 2m(G-u)-2\kappa(G-u)\geq 2(m(G)-1)-2(\kappa(G)-1)=2m(G)-2\kappa(G)$.
 %There exists an edge $e$ of an even cycle such that it is not in a maximum matching of $G$. Let $H=G-e$. Then $m(H)=m(G)$. By induction hypothesis, $r(H)\geq 2m(H)-2\kappa(H)$.
 ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\quad $\square$



\section{Proofs of Theorems \ref{th:1.3} and \ref{th:1.4}}

~\quad By the proof of Theorem \ref{th:1.2}, the above  inequalities  become equalities when  $r(\widetilde{G})= 2m(G)- 2\kappa(G)$. Hence we have the following Lemma \ref{le:4.1}.
\noindent\begin{lemma}\label{le:4.1}
Let $\widetilde{G}$ be a mixed graph and $r(\widetilde{G})= 2m(G)- 2\kappa(G)$, where
$0\leq \kappa(G)\leq c(G)$. Then
%\begin{enumerate}[(a)]
%\item   all even cycles are pairwise vertex-disjoint.
 for any vertex $u$ on any even cycle of $G$, $\kappa(G-u)=\kappa(G)-1$, $m(G-u)=m(G)-1$, $r(\widetilde{G})=r(\widetilde{G}-u)$ and $r(\widetilde{G}-u)= 2m(G-u)- 2\kappa(G-u)$.
%\end{enumerate}


\end{lemma}



\noindent\begin{lemma}\label{le:4.2}
Let $\widetilde{G}$ be a mixed graph and $r(\widetilde{G})= 2m(G)- 2\kappa(G)+1$, where
$0\leq \kappa(G)\leq c(G)$. Then
%\begin{enumerate}[(a)]
%\item   all even cycles are pairwise vertex-disjoint.
 for any vertex $u$ on any even cycle of $G$, $\kappa(G-u)=\kappa(G)-1$, $m(G-u)=m(G)-1$ and $r(\widetilde{G}-u)= 2m(G-u)- 2\kappa(G-u)+a_{u}$, where $a_{u}\in \{0,1\}$.
%\end{enumerate}


\end{lemma}

\begin{proof} Suppose on the contrary that $\kappa(G-u)\neq \kappa(G)-1$. So  $\kappa(G-u)\leq \kappa(G)-2$. By Lemmas \ref{le:2.1} and \ref{le:2.6} and  Inequality  (2),
$$\begin{aligned}
r(\widetilde{G})&\geq r(\widetilde{G}-u)\\
       &\geq 2m(G-u)-2\kappa(G-u)\\
       &\geq 2(m(G)-1)-2(\kappa(G)-2)\\
       &=2m(G)-2\kappa(G)+2,
\end{aligned}$$
a contradiction to $r(\widetilde{G}) = 2m(G)-2\kappa(G)+1$. Hence, $\kappa(G-u)=\kappa(G)-1$.



Suppose on the contrary that $m(G)= m(G-u)$.
By Lemma \ref{le:2.1} and Inequality (2),
$$\begin{aligned}
r(\widetilde{G})&\geq r(\widetilde{G}-u)\\
       &\geq 2m(G-u)-2\kappa(G-u)\\
       &=2m(G)-2(\kappa(G)-1)\\
       &=2m(G)-2\kappa(G)+2,
\end{aligned}$$
a contradiction to  $r(\widetilde{G})=2m(G)-2\kappa(G)+1$.
Hence, $m(G-u)=m(G)-1$.

Suppose on the contrary that $r(\widetilde{G}-u)\geq 2m(G-u)- 2\kappa(G-u)+2$. By Lemma \ref{le:2.1}, Inequality (2), $\kappa(G-u)=\kappa(G)-1$ and $m(G-u)=m(G)-1$,
$$\begin{aligned}
r(\widetilde{G})&\geq r(\widetilde{G}-u)\\
       &\geq 2m(G-u)-2\kappa(G-u)+2\\
       &= 2(m(G)-1)-2(\kappa(G)-1)+2\\
      &=2m(G)-2\kappa(G)+2,
\end{aligned}$$
a contradiction to  $r(\widetilde{G}) = 2m(G)-2\kappa(G)+1$. Hence, $r(\widetilde{G}-u)= 2m(G-u)- 2\kappa(G-u)+a_{u}$, where $a_{u}\in\{0,1\}$.
\end{proof}


\noindent\begin{lemma}\label{le:4.3}
Let $\widetilde{G}$ be a mixed graph  with a pendant vertex $u$, and $v$ be the unique neighbor of $u$ in $G$, $\widetilde{H}=\widetilde{G}-\{u,v\}$. If $r(\widetilde{G})= 2m(G)-2\kappa(G)+s$, where $s\in \{0,1\}$, then $v$ lies outside any even cycle of $G$.
\end{lemma}

\begin{proof} Suppose that the assertion is false. By Lemmas \ref{le:2.2} and \ref{le:2.7} and Inequality (2),
$$\begin{aligned}
   r(\widetilde{G})&=r(\widetilde{H})+2 \\
          &\geq 2m(H)-2\kappa(H)+2 \\
          &\geq 2m(G)-2-2(\kappa(G)-1)+2 \\
          &=2m(G)-2\kappa(G)+2,
 \end{aligned}$$ a contradiction. \end{proof}

 \noindent\begin{lemma}\label{le:4.4}
Let $\widetilde{G}$ be a mixed graph  with a pendant vertex $u$, and $v$ be the unique neighbor of $u$ in $G$,  $\widetilde{H}=\widetilde{G}-\{u,v\}$. If $v$ is not on any even cycle of $G$, then
$r(\widetilde{G})=2m(G)-2\kappa(G)+s$ if and only if $r(\widetilde{H})=2m(H)-2\kappa(H)+s$, where $0\leq \kappa(G)\leq c(G)$, $s$ is an integer and $0\leq s\leq 2m^{\ast}(G)-2m(G)+2\kappa(G)$.
\end{lemma}

\begin{proof}  Since $v$ is not on any even cycle of $G$, $\kappa(G)=\kappa(H)$.

\textbf{Necessity:} By Lemmas \ref{le:2.2} and \ref{le:2.7},
$$\begin{aligned}
   r(\widetilde{H})&=r(\widetilde{G})-2 \\
             &=2m(G)-2\kappa(G)+s-2 \\
             &=2m(H)-2\kappa(H)+s.
 \end{aligned}$$

\textbf{Sufficiency:} By Lemmas \ref{le:2.2} and \ref{le:2.7},
$$\begin{aligned}
   r(\widetilde{G})&=r(\widetilde{H})+2 \\
             &=2m(H)-2\kappa(H)+s+2 \\
             &=2m(G)-2\kappa(G)+s.
 \end{aligned}$$\end{proof}

 By Lemma \ref{le:2.3} and Inequality (\ref{eq:2}), we can obtain the following lemma.
 \noindent\begin{lemma}\label{le:4.5}
Let $\widetilde{G}$ be a  mixed graph. Then
\begin{enumerate}[(a)]
\item $r(\widetilde{G})=2m(G)-2\kappa(G)$ if and only if for each connected component $\widetilde{G}_{i}$ of $\widetilde{G}$, $r(\widetilde{G}_{i})=2m(G_{i})-2\kappa(G_{i})$.
\item $r(\widetilde{G})=2m(G)-2\kappa(G)+1$ if and only if $\widetilde{G}$ has exactly a connected component $\widetilde{G}_{0}$ satisfying that $r(\widetilde{G}_{0})=2m(G_{0})-2\kappa(G_{0})+1$ and for each  other connected component $\widetilde{G}_{i}$, $r(\widetilde{G}_{i})=2m(G_{i})-2\kappa(G_{i})$.
\end{enumerate}
\end{lemma}







 \noindent\begin{lemma}\label{le:4.6}
Let $\widetilde{G}$ be a  mixed graph  containing no pendant vertices and isolated vertices and $\kappa(G)=c(G)-1~(c(G)\geq 2)$.  If $r(\widetilde{G})=2m(G)-2\kappa(G)+s$, where $s\in \{0,1\}$, then  either $G$ has a perfect matching or $G$ has a connected component which is an odd cycle.
\end{lemma}

\begin{proof} Assume that $G$ is connected. Let $M$ be a maximum matching of $G$. Since $r(\widetilde{G})=2m(G)-2\kappa(G)+s$, $s\in \{0,1\}$, by Lemmas \ref{le:4.1} and \ref{le:4.2},   any vertex $u$ of any even cycle of $G$ is saturated by $M$ as $m(G-u)=m(G)-1$. Suppose that $M$  is not a perfect matching. Then there is an $M$-unsaturated vertex $v$ which is not on any even cycle of $G$. Let $w$ be a vertex on some even cycle of $G$. Then there is an $M$-alternating path between $v$ and $w$, say $P$. Otherwise, there is an $M$-augmenting path between $v$ and $w$, by Lemma \ref{le:2.16}, we can obtain a contradiction. Let $X$ be the set of edges of $P$ which are not in $M$ and $Y$ be the set of edges of $P$ which are in $M$. Let $M'=M\setminus Y \cup X$. Clearly, $|M'|=|M|$ and $w$ is an $M'$-unsaturated vertex, a contradiction to $m(G-w)=m(G)-1$. So $G$ has a perfect matching.

Now assume that $G$ is disconnected.
If $G$ has a connected component which is an odd cycle, then we are done. If not, each connected component $G_{j}$ of $G$ is an even cycle or $c(G_{j})\geq 2$.
Since $r(\widetilde{G})=2m(G)-2\kappa(G)+s$, $s\in\{0,1\}$, by Lemma \ref{le:4.5}, $\widetilde{G}$ has exactly a connected component $\widetilde{G}_{0}$ satisfying that $r(\widetilde{G}_{0})=2m(G_{0})-2\kappa(G_{0})+s$ and for each other  connected component $\widetilde{G}_{i}$, $r(\widetilde{G}_{i})=2m(G_{i})-2\kappa(G_{i})$.
For each connected component of $G$ which is an even cycle, it has a perfect matching. For each connected component $G_{t}$ of $G$ with $c(G_{t})\geq 2$,  similar as the above proof, $G_{t}$ has a perfect matching. Hence $G$ has a perfect matching.
\end{proof}

For mixed bicyclic graphs, we have the following two lemmas.

\noindent\begin{lemma}\label{le:4.7}
  Let $\widetilde{G}$ be a mixed bicyclic graph $\widetilde{\infty}(p,1,q)$, where $p$ is even and $q$ is odd. Then
   \begin{enumerate}[(a)]
  \item $r(\widetilde{G})=2m(G)-2\kappa(G)$ if and only if odd cycle of $\widetilde{G}$ has odd signature and even cycle $\widetilde{C}_{p}$ of it satisfies $\sigma(\widetilde{C}_{p})\equiv p~(\mathrm{mod}~4)$.
  \item $r(\widetilde{G})=2m(G)-2\kappa(G)+1$ if and only if odd cycle of $\widetilde{G}$ has even signature and even cycle $\widetilde{C}_{p}$ of it satisfies $\sigma(\widetilde{C}_{p})\equiv p~(\mathrm{mod}~4)$.
  \end{enumerate}
  \end{lemma}
\begin{proof}It is obvious that  $m(G)=(p+q-1)/2$ and $\kappa(G)=1$. We first prove (a) of this lemma.

\textbf{Sufficiency:} Since $\widetilde{C}_{q}$ has odd signature and $\widetilde{C}_{p}$  satisfies $\sigma(\widetilde{C}_{p})\equiv p~(\mathrm{mod}~4)$, by Lemmas \ref{le:2.5} and \ref{le:2.8}, $r(\widetilde{G})=p-2+r(\widetilde{C}_{q})=p+q-3=2m(G)-2\kappa(G)$.

\textbf{Necessity:} Assume that  $\widetilde{C}_{p}$ dose not satisfy $\sigma(\widetilde{C}_{p})\equiv p~(\mathrm{mod}~4)$. By Lemmas \ref{le:2.4} and \ref{le:2.8}, $r(\widetilde{G})=p+r(\widetilde{P}_{q-1})=p+q-1\neq 2m(G)-2\kappa(G)$, a contradiction. Hence $\sigma(\widetilde{C}_{p})\equiv p~(\mathrm{mod}~4)$. By Lemma \ref{le:2.8}, $r(\widetilde{G})=p-2+r(\widetilde{C}_{q})$. Since $r(\widetilde{G})=2m(G)-2\kappa(G)=p+q-3$, $r(\widetilde{C}_{q})=q-1$. By Lemma \ref{le:2.5}, $\widetilde{C}_q$ has odd signature.

Similarly, we can obtain (b) of this lemma.
\end{proof}



\noindent\begin{lemma}\label{le:4.8}
  Let $\widetilde{G}$ be a mixed bicyclic graph $\widetilde{\theta}(p,l,q)$, where $p$ is even,  $l$ and $q$ are odd. Then
  \begin{enumerate}[(a)]
  \item $r(\widetilde{G})=2m(G)-2\kappa(G)$ if and only if two  odd cycles of $\widetilde{G}$ have odd signatures and even cycle $\widetilde{C}_{q+l-2}$ satisfies $q+l+\sigma(\widetilde{C}_{q+l-2})\equiv 2~(\mathrm{mod}~ 4)$.
  \item $r(\widetilde{G})=2m(G)-2\kappa(G)+1$ if and only if two odd cycles of $\widetilde{G}$ have even signatures and even cycle $\widetilde{C}_{q+l-2}$ satisfies $q+l+\sigma(\widetilde{C}_{q+l-2})\equiv 2~(\mathrm{mod}~ 4)$.
  \end{enumerate}
\end{lemma}
\begin{proof} Let $m=m(G)$ and let  $f(\widetilde{G}, \lambda)=\sum_{i=0}^{n}a_{i}\lambda^{n-i}$ be characteristic polynomial of $\widetilde{G}$.
By Lemma \ref{le:2.9}, $$a_{i}=\sum_{\widetilde{B}} (-1)^{\frac{1}{2}\sigma(\widetilde{B})+\omega(B)}2^{\beta(B)},$$
where the sum runs over all basic subgraphs $\widetilde{B}$ of order $i$ in $\widetilde{G}$. Let $u$ be a vertex of even cycle $C_{q+l-2}$~(which is not on the odd cycle $C_{p+l-2}$) adjacent to vertex of degree 3 in $G$.
We first prove (a) of this lemma.

\textbf{Sufficiency:} It is obvious that $m(G)=(p+l+q-4)/2$ and $\kappa(G)=1$.  Since two  odd cycles of $\widetilde{G}$ have odd signatures, $\widetilde{G}$ has no basic subgraph of order $2m-1$. Hence $a_{2m-1}=0$. Note that there are three basic subgraphs of order $2m$ in $\widetilde{G}$. One of them is disjoint union of cycle $\widetilde{C}_{q+l-2}$ and a perfect matching of path $\widetilde{P}_{p-2}$. The other two are obtained by replacing cycle $\widetilde{C}_{q+l-2}$ with two distinct perfect matchings of it. So $a_{2m}= (-1)^{\frac{1}{2}\sigma(\widetilde{C}_{q+l-2})+\frac{p-2}{2}+1}\cdot 2+ (-1)^{\frac{p+l+q-4}{2}}\cdot 2=0$ as $q+l+\sigma(\widetilde{C}_{q+l-2})\equiv 2~(\mathrm{mod}~ 4)$. Hence $r(\widetilde{G})\leq 2m-2=2m(G)-2\kappa(G)$. By Inequality (2), we have that $r(\widetilde{G})=2m(G)-2\kappa(G)$.

\textbf{Necessity:} Without loss of generality, assume that odd cycle $\widetilde{C}_{p+l-2}$ has even signature. By Lemmas \ref{le:2.1}, \ref{le:2.2} and \ref{le:2.5}, $r(\widetilde{G})\geq r(\widetilde{G}-u)=q-3+r(\widetilde{C}_{p+l-2})=p+q+l-5=2m(G)-2\kappa(G)+1$, a contradiction. Hence two  odd cycles of $\widetilde{G}$ have odd signatures. So  the unique even cycle $\widetilde{C}_{q+l-2}$ of $\widetilde{G}$ has even signature. Then  $a_{2m}= (-1)^{\frac{1}{2}\sigma(\widetilde{C}_{q+l-2})+\frac{p-2}{2}+1}\cdot 2+ (-1)^{\frac{p+l+q-4}{2}}\cdot 2$. Since $r(\widetilde{G})=2m-2$, $a_{2m}=0$. Hence $q+l+\sigma(\widetilde{C}_{q+l-2})\equiv 2~(\mathrm{mod}~ 4)$.

Now we prove (b) of this lemma.

\textbf{Sufficiency:}  Since two  odd cycles of $\widetilde{G}$ have even signatures, by Lemmas \ref{le:2.1}, \ref{le:2.2} and \ref{le:2.5}, $r(\widetilde{G})\geq r(\widetilde{G}-u)=2m-1=2m(G)-2\kappa(G)+1$. Similar as the above proof, $a_{2m}=0$. So $r(G)=2m-1=2m(G)-2\kappa(G)+1$.

\textbf{Necessity:} Since $r(\widetilde{G})=2m(G)-2\kappa(G)+1=2m-1$, there is a basic subgraph of order $2m-1$. Hence at least one of two  odd cycles of $\widetilde{G}$ has even signature. Suppose that the other one has odd signature. Then the unique even cycle $\widetilde{C}_{q+l-2}$ has odd signature. So  $a_{2m}=(-1)^{\frac{p+l+q-4}{2}}\cdot 2\neq 0$. Hence $r(\widetilde{G})=2m$, a contradiction. So two odd cycles of $\widetilde{G}$ have even signatures. Then the unique even cycle $\widetilde{C}_{q+l-2}$ has even signature. So $a_{2m}= (-1)^{\frac{1}{2}\sigma(\widetilde{C}_{q+l-2})+\frac{p-2}{2}+1}\cdot 2+ (-1)^{\frac{p+l+q-4}{2}}\cdot 2=0$. Hence $q+l+\sigma(\widetilde{C}_{q+l-2})\equiv 2~(\mathrm{mod}~ 4)$.
\end{proof}



For a connected mixed graph, we have the following three lemmas.

\noindent\begin{lemma}\label{le:4.9}
Let $\widetilde{G}$ be a connected mixed graph  with $\kappa(G)=c(G)-1~(c(G)\geq 2)$ vertex-disjoint even cycles and $\widetilde{G}$ has no pendant vertices and no pendant even cycles.
Let $p$ be even and let $q$ and $l$ be odd.
 \begin{enumerate}[(a)]
  \item If $r(\widetilde{G})=2m(G)-2\kappa(G)$, then $\widetilde{G}$ is either a mixed bicyclic graph $\widetilde{\infty}(p,1,q)$ whose odd cycle  has odd signature and even cycle $\widetilde{C}_{p}$  satisfies $\sigma(\widetilde{C}_{p})\equiv p~(\mathrm{mod}~4)$ or a mixed bicyclic graph $\widetilde{\theta}(p,l,q)$ whose two odd cycles have odd signatures and even cycle $\widetilde{C}_{q+l-2}$ satisfies $q+l+\sigma(\widetilde{C}_{q+l-2})\equiv 2~(\mathrm{mod}~ 4)$.
  \item If $r(\widetilde{G})=2m(G)-2\kappa(G)+1$, then $\widetilde{G}$ is either a mixed bicyclic graph $\widetilde{\infty}(p,1,q)$ whose odd cycle  has even signature and even cycle $\widetilde{C}_{p}$  satisfies $\sigma(\widetilde{C}_{p})\equiv p~(\mathrm{mod}~4)$ or a mixed bicyclic graph $\widetilde{\theta}(p,l,q)$ whose two odd cycles have even signatures and even cycle $\widetilde{C}_{q+l-2}$ satisfies $q+l+\sigma(\widetilde{C}_{q+l-2})\equiv 2~(\mathrm{mod}~ 4)$.
  \end{enumerate}
\end{lemma}
\begin{proof}Let $\widetilde{G}$ be a connected mixed graph satisfying conditions of this lemma with rank $r(\widetilde{G})=2m(G)-2\kappa(G)+s$, where $s\in \{0,1\}$. Since $G$ has no pendant vertices and no pendant even cycles and $\kappa(G)=c(G)-1~(c(G)\geq 2)$,  any even cycle $\widetilde{C}^{i}$~($1\leq i\leq \kappa(G)$) in $\widetilde{G}$ must contain exactly two vertices of degree $3$ or one vertex of degree $4$. Denoted such vertices as $u_{i_{1}}$ and $u_{i_{2}}$~(if $u_{i_{1}}= u_{i_{2}}$, then this vertex has degree 4). Let $P_{i_{1}}$ and $P_{i_{2}}$ represent the two paths between $u_{i_{1}}$ and $u_{i_{2}}$ on $\widetilde{C}^{i}$. Since $r(\widetilde{G})=2m(G)-2\kappa(G)+s$, $s\in\{0,1\}$ and $G$ is connected with $c(G)\geq 2$, Lemma \ref{le:4.6} implies that $\widetilde{G}$ has a perfect matching. Consequently, $\widetilde{G}$ must contain at least an even cycle $\widetilde{C}^{i}$ such that both paths $P_{i_{1}}$ and  $P_{i_{2}}$ have odd length (without loss of generality, let this even cycle be $\widetilde{C}^{1}$). If, instead, any even cycle $\widetilde{C}^{i}$ has even paths $P_{i_{1}}$ and $P_{i_{2}}$,  then the existence of  a perfect matching would force  $\widetilde{G}$ to lack any odd cycle, a contradiction to $\kappa(G)=c(G)-1$.

Now, let $y$ be one of vertices adjacent to the vertex with degree 3 or 4 in $V(C^{1})$ (see an example shown in Fig. 2). By Lemmas \ref{le:4.1} and \ref{le:4.2},  $r(\widetilde{G}-y)=2m(G-y)-2\kappa(G-y)+t$, $t\in\{0,1\}$~(when $s=0$, $t=0$ and when $s=1$, $t\in\{0,1\}$). After pendant $K_{2}$ deletion operations for $\widetilde{G}-y$, we can get a crucial  subgraph $\widetilde{G}_{1}$. By Lemmas \ref{le:4.3} and \ref{le:4.4},  $r(\widetilde{G}_{1})=2m(G_{1})-2\kappa(G_{1})+t$, $t\in\{0,1\}$. If
$c(G_{1})\geq 2$, by Lemma \ref{le:4.6},  both of $\widetilde{G}$ and $\widetilde{G}_{1}$ have a perfect matching,
however, the order of $\widetilde{G}_{1}$ is odd, a contradiction. If $c(G_{1})=1$, then $\widetilde{G}_{1}$ is a mixed
odd cycle. So $\widetilde{G}$ is a mixed bicyclic graph $\widetilde{\infty}(p,1,q)$ or $\widetilde{\theta}(p,l,q)$. By Lemmas \ref{le:4.7} and \ref{le:4.8},  assertions (a) and (b) hold.
\end{proof}

