\noindent\begin{lemma}\label{le:4.10}
Let $\widetilde{G}$ be a connected mixed graph  with pairwise vertex-disjoint  cycles and $\kappa(G)=c(G)-1~(c(G)\geq 2)$. If $\widetilde{G}$ has a pendant odd cycle $\widetilde{C}_{q}$ with odd signature and  $\widetilde{G}$ has no pendant vertices, then $r(\widetilde{G})= 2m(G)-2\kappa(G)$
if and only if $r(\widetilde{H})=2m(H)-2c(H)$, where $\widetilde{H}=\widetilde{G}-V(C_{q})+x$ and $x$ is the unique vertex of degree $3$ in $C_q$.
\end{lemma}
\begin{proof} Since $\widetilde{C}_{q}$ is a pendant odd cycle  with odd signature, by Lemma \ref{le:2.8}, $r(\widetilde{G})= q-1+r(\widetilde{H})$. By Lemma \ref{le:2.15}, $m(G)=m(H)+(q-1)/2$. Note that $\kappa(G)=\kappa(H)=c(H)$.
So $2m(G)-2\kappa(G)=2m(H)+q-1-2c(H)$. Combining this with $r(\widetilde{G})= q-1+r(\widetilde{H})$, we have $r(\widetilde{G})= 2m(G)-2\kappa(G)$
if and only if $r(\widetilde{H})=2m(H)-2c(H)$.
%\textbf{Necessity:}   By $r(\widetilde{G})=2m(G)-2\kappa(G)$, $r(\widetilde{G})=2m(G)-2\kappa(G)=2m(H)+q-1-2c(H)$. Combining this with $r(\widetilde{G})= q-1+r(\widetilde{H})$, we have  $r(\widetilde{H})=2m(H)-2c(H)$.
%\textbf{Sufficiency:}  By $r(\widetilde{H})=2m(H)-2c(H)$, $r(\widetilde{G})= q-1+r(\widetilde{H})=q-1+2m(H)-2c(H)=2m(G)-2\kappa(G)$.
\end{proof}




\noindent\begin{lemma}\label{le:4.11}
Let $\widetilde{G}$ be a connected mixed graph  with $\kappa(G)=c(G)-1~(c(G)\geq 2)$ vertex-disjoint even cycles and $\widetilde{G}$ has no pendant vertices. If
 $r(\widetilde{G})= 2m(G)-2\kappa(G)$, then $\widetilde{G}$ is a connected mixed graph in $\mathfrak{G}_{1}$.
\end{lemma}
\begin{proof}
 If $\widetilde{G}$ is  a connected mixed bicyclic graph in $\mathfrak{G}_{1}\setminus \mathfrak{G}_{0}$, then we are done. If not, since $r(\widetilde{G})= 2m(G)-2\kappa(G)$, by Lemma \ref{le:4.9}(a), $G$ has a pendant even cycle, say $C$. Let $x$ be a vertex in $V(C)$ with $d_{G}(x)=3$ and $y$ be one of vertices adjacent to $x$ in $V(C)$. By Lemma \ref{le:4.1}, $r(\widetilde{G}-y)=2m(G-y)-2\kappa(G-y)$.
After a series of pendant $K_{2}$ deletion operations for $\widetilde{G}-y$, we can get a crucial subgraph $\widetilde{F}$. By Lemmas \ref{le:4.3} and \ref{le:4.4}, $r(\widetilde{F})=2m(F)-2\kappa(F)$. By Lemma \ref{le:4.6}, $\widetilde{G}$ has a perfect matching. Hence the order of $\widetilde{F}$ is odd.

Suppose that $c(F)\geq 2$ and $\widetilde{F}$ has no isolated vertices. If $\widetilde{F}$ has no connected component which is an odd cycle, by Lemma \ref{le:4.6}, $\widetilde{F}$ has a perfect matching, a contradiction to the order of $\widetilde{F}$ is odd.
Hence  $\widetilde{F}$ has a connected component which is an odd cycle, say $C_{q}$. Then $C_q$ is a pendant odd cycle of $G$. Since $r(\widetilde{F})=2m(F)-2\kappa(F)$, by Lemma \ref{le:4.5}(a), $r(\widetilde{C}_{q})=2m(C_q)-2\kappa(C_q)=q-1$. By Lemma \ref{le:2.5}, $\widetilde{C}_{q}$ is an odd cycle with odd signature. Let $w$ be a vertex in $V(C_{q})$ with $d_{G}(w)=3$.
Let $\widetilde{H}=\widetilde{G}-V(C_q)+w$. By Lemma \ref{le:4.10}, $r(\widetilde{H})=2m(H)-2c(H)$. Thus $\widetilde{G}$ is a mixed graph in $\mathfrak{G}_{0}$, as required.

Otherwise, either $\widetilde{F}$ is isomorphic to a mixed odd  cycle (in this case, $\widetilde{G}$ is a mixed graph in $\mathfrak{G}_{0}$, as required), or $\widetilde{F}$ has at least one isolated vertex. Since $\widetilde{G}-y$ is a connected graph with exactly one pendant vertex,  by Lemma \ref{le:4.3}, the isolated vertex in $\widetilde{F}$ must lie  on the odd cycle of $\widetilde{G}-y$, this is impossible.
\end{proof}

For a mixed unicyclic graph, we have the following lemma.

\noindent\begin{lemma}\label{le:4.12}
Let $\widetilde{G}$ be a  mixed unicyclic graph  with unique odd cycle $\widetilde{C}_{q}$.
\begin{enumerate}[(a)]
\item If $r(\widetilde{G})= 2m(G)$, then $\widetilde{G}$ satisfies (b) of Theorem \ref{th:1.3}.
\item If $r(\widetilde{G})= 2m(G)+1$, then $\widetilde{G}$ satisfies (b) of Theorem \ref{th:1.4}.
\end{enumerate}
\end{lemma}
\begin{proof} We first prove (a) of this lemma. Suppose that the assertion is false. Let $\widetilde{G}_{0}$ be a counterexample with minimum order. Clearly, $r(\widetilde{G}_{0})= 2m(G_{0})$ and $\widetilde{G}_{0}$ does not satisfy (b) of Theorem \ref{th:1.3}.
If $G_{0}$ has a pendant vertex $x$ with unique neighbor $y$, then by Lemma \ref{le:4.4}, $r(\widetilde{G}_{0}-x-y)= 2m(G_{0}-x-y)$, a contradiction to minimality of order of $\widetilde{G}_{0}$. So $G_{0}$ consists of an odd cycle $C_q$ and some isolated vertices. Since $\widetilde{G}_{0}$ does not satisfy (b) of Theorem \ref{th:1.3}, $\widetilde{C}_q$ is a mixed odd cycle with even signature. So by Lemma \ref{le:2.5}, $r(\widetilde{G}_{0})=2m(G_{0})+1$, a contradiction.

Similarly, we can obtain (b) of this lemma.
\end{proof}



For lower bound of Inequality (1), we have the following lemma.

\noindent\begin{lemma}\label{le:4.13}
Let $\widetilde{G}$ be a mixed graph. If $r(\widetilde{G})=2m(G)-2c(G)$, then  a series of pendant $K_{2}$ deletion operations can switch $\widetilde{G}$ to a crucial subgraph $\widetilde{G}_{1}$, which is disjoint union of $c(G)$ even cycles and some isolated vertices~(possibly non-existent).
\end{lemma}
\begin{proof} %\textbf{Sufficiency:} By conditions (a)-(c) and Lemma \ref{le:2.5}, we have $r(\widetilde{G}_{1})=2m(G_1)-2c(G_1)$. Assume that switching $\widetilde{G}$ to $\widetilde{G}_{1}$ by $k$-step pendant $K_2$ deletion operations. By Lemmas \ref{le:2.2} and \ref{le:2.7}, $r(\widetilde{G})=r(\widetilde{G}_1)+2k=2m(G_1)-2c(G_1)+2k=2m(G)-2c(G)$.
%\textbf{Necessity:} By Theorem \ref{th:1.1}, we have (a) and (b) hold. Now we prove (c).
We apply induction on $|V(G)|$. If $|V(G)|\leq 2$, the assertion  holds trivially. Now assume that $|V(G)|\geq 3$. By Theorem \ref{th:1.1}(a) and (b), any two  cycles (if any) of $\widetilde{G}$ share no common vertices and
  each  cycle $\widetilde{C}_{q}$ of $\widetilde{G}$ satisfies  $\sigma(\widetilde{C}_{q})\equiv q~(\mathrm{mod}~4)$. If $T_G$ is an empty graph, then $G$ consists of disjoint cycles and some isolated vertices. So the assertion  holds. Suppose that $T_G$ has at least an edge. By Theorem \ref{th:1.1}(c), $m(T_G)=m([T_G])$. According to Lemma \ref{le:2.4}, $r(T_G)=r([T_G])$. By Lemma \ref{le:2.11}, $T_G$ has at least a pendant vertex which is not cyclic vertex, say $x$. Then $x$ is a pendant vertex of $G$. Let $y$ be the unique neighbor of $x$ in $G$.  By Lemma \ref{le:2.14}, $y$ lies outside any mixed cycle of $\widetilde{G}$ and
 $r(\widetilde{G}-x-y)=2m(G-x-y)-2c(G-x-y)$. By induction hypothesis,  a series of pendant $K_{2}$ deletion operations can switch $\widetilde{G}-x-y$ to a crucial subgraph $\widetilde{G}_{1}$, which is disjoint union of $c(G-x-y)$ even cycle and some isolated vertices~(possibly non-existent). Note that $c(G)=c(G-x-y)$. Thus  a series of pendant $K_{2}$ deletion operations can switch $\widetilde{G}$ to a crucial subgraph $\widetilde{G}_{1}$, which is disjoint union of $c(G)$ even cycle and some isolated vertices~(possibly non-existent).
\end{proof}




Now, we will prove Theorem \ref{th:1.3}.


\medskip
\noindent\textbf{Proof of Theorem \ref{th:1.3}.} \textbf{Sufficiency:} By conditions (a) and (b) and Lemmas \ref{le:2.5}, \ref{le:4.7}(a), \ref{le:4.8}(a) and \ref{le:4.10}, for each connected component $\widetilde{F}_{i}$ of $\widetilde{G}_{1}$, $r(\widetilde{F}_{i})=2m(F_{i})-2\kappa(F_{i})$. By Lemma \ref{le:4.5}(a), $r(\widetilde{G}_{1})=2m(G_1)-2\kappa(G_1)$. Suppose that switching $\widetilde{G}$ to $\widetilde{G}_{1}$ by $k$-step pendant $K_{2}$ deletion operations. By Lemmas \ref{le:2.2} and \ref{le:2.7}, $r(G)=r(G_{1})+2k=2m(G_1)-2\kappa(G_1)+2k=2m(G)-2\kappa(G)$.


\textbf{Necessity:}
 By Lemma \ref{le:4.5}(a), we can assume that $\widetilde{G}$ is connected. Since $r(\widetilde{G})=2m(G)-2\kappa(G)$, by Lemma \ref{le:4.1}, $\kappa(G-u)=\kappa(G)-1$ for any vertex $u$ on any even cycle of $G$. By Lemma \ref{le:2.10}, assertion (a) holds.

 For assertion (b), we apply induction on the order of $G$. If $|V(G)|\leq 2$, then the results hold trivially.
Now assume that $|V(G)|\geq 3$. If $c(G)=0$, then $G$ is an acyclic graph. By Lemma \ref{le:2.4},  $r(\widetilde{G})=2m(G)$ and we are done.
If $c(G)=1$, then $\kappa(G)=c(G)-1=0$ and $\widetilde{G}$ is a mixed unicyclic  graph with an odd cycle.  By Lemma \ref{le:4.12}(a),  assertion (b) holds.

Suppose that $c(G)\geq 2$. Note that $\mathfrak{G}_{1}\subseteq \mathfrak{G}_{2}$. If $\widetilde{G}$ is a mixed graph in $\mathfrak{G}_{1}$, then we are done.  If not, by Lemma \ref{le:4.11}, $\widetilde{G}$ has at least one pendant vertex, say $x$. Let $y$ be the unique neighbor of $x$ in $G$.
 Let $\widetilde{H}=\widetilde{G}-\{x,y\}$. If  $y$ is on the odd cycle of $G$, then by Lemma \ref{le:4.4},
$r(\widetilde{H})= m(H)-2\kappa(H)= m(H)-2c(H)$. By Theorem \ref{th:1.1} (a) and (b), any two  cycles (if any) of $\widetilde{H}$ share no common vertices and
  each  cycle $\widetilde{C}_{q}$ of $\widetilde{H}$ satisfies  $\sigma(\widetilde{C}_{q})\equiv q~(\mathrm{mod}~4)$. Then by Lemma \ref{le:4.13},  assertion (b) holds.
Suppose that $y$ is not on the odd cycle of $G$. Since $r(\widetilde{G})=m(G)-2\kappa(G)$, by Lemma \ref{le:4.3}, $y$ is not on any even cycle of $G$.
By Lemma \ref{le:4.4}, $r(\widetilde{H})=m(H)-2\kappa(H)$.
Note that $\kappa(G)= \kappa(H)= c(H)-1=c(G)-1$. By induction hypothesis, $\widetilde{H}$ satisfies condition (b). Thus $\widetilde{G}$ satisfies condition (b). ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\quad $\square$
%~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\quad $\square$



\medskip
Now, we give an example that satisfies the equality in Theorem \ref{th:1.3}. Let $\widetilde{G}$ be a  mixed graph with an odd cycle $\widetilde{C}_{3}$ having odd signature and each other cycle  is $\widetilde{C}_{4}$ with $\sigma(\widetilde{C}_{4})\equiv 0~(\mathrm{mod}~ 4)$ shown in Fig. 3.
By Lemmas \ref{le:2.2}, \ref{le:2.5} and \ref{le:2.7}, $r(\widetilde{G})=r(\widetilde{G}-\{u,v\})+2=(4-2)\kappa(G)+3-1+2=2\kappa(G)+4$ and $m(G)=m(G-\{u,v\})+1=2\kappa(G)+1+1=2\kappa(G)+2$.  Thus $r(\widetilde{G})=2m(G)-2\kappa(G)$.





We give the following four lemmas which will be useful in the proof of Theorem \ref{th:1.4}.
\noindent\begin{lemma}\label{le:4.14}
Let $\widetilde{G}$ be a  mixed graph  with pairwise vertex-disjoint  cycles and $\widetilde{G}$ has no pendant vertices. If $\widetilde{G}$ has a pendant even cycle $\widetilde{C}_{q}$ with $\sigma(\widetilde{C}_{q})\equiv q~(\mathrm{mod}~ 4)$ and  $r(\widetilde{G})=2m(G)-2\kappa(G)+1$, then $r(\widetilde{H})=2m(H)-2\kappa(H)+1$, where  $\widetilde{H}=\widetilde{G}-V(C_q)+x$ and $x$ is the unique vertex of degree $3$ in $C_q$.
\end{lemma}
\begin{proof}
 Let  $y$ be a vertex adjacent to $x$ in $V(C_{q})$.
 Since $r(\widetilde{G})=2m(G)-2\kappa(G)+1$, by Lemma \ref{le:4.2},  $m(G-y)=m(G)-1$. By Lemma \ref{le:2.7}, $m(G-y)=m(H)+(q-2)/2$. Hence $m(H)=m(G)-q/2$.
Since $\widetilde{C}_{q}$ is an even cycle with $\sigma(\widetilde{C}_{q})\equiv q~(\mathrm{mod}~ 4)$, by Lemma \ref{le:2.8}, $r(\widetilde{H})+q-2=r(\widetilde{G})=2m(G)-2\kappa(G)+1=2m(H)+q-2\kappa(H)-2+1$. It follows that $r(\widetilde{H})=2m(H)-2\kappa(H)+1$.
\end{proof}


