\noindent\begin{lemma}\label{le:4.15}
Let $\widetilde{G}$ be a  mixed graph  with pairwise vertex-disjoint cycles and $\widetilde{G}$ has   no odd cycles. Then $r(\widetilde{G})\neq 2m(G)-2\kappa(G)+1$.
\end{lemma}
\begin{proof} Suppose that  the assertion is false. Let $\widetilde{G}_{0}$ be a counterexample with minimum order. Clearly, $r(\widetilde{G}_{0})= 2m(G_{0})-2\kappa(G_{0})+1$. If $c(G_{0})=0$, then $G_{0}$ is an acyclic graph. By Lemma \ref{le:2.4}, $r(\widetilde{G}_{0})= 2m(G_{0})$, a contradiction. Suppose that $c(G_{0})\geq 1$. If $G_0$ has a pendant vertex $u$ with unique neighbor $v$, by Lemmas \ref{le:4.3} and \ref{le:4.4}, $r(\widetilde{G}_{0}-u-v)= 2m(G_{0}-u-v)-2\kappa(G_{0}-u-v)+1$, a contradiction to minimality of order of $\widetilde{G}_0$. Thus $G_0$ has no pendant vertices. Note that $G_{0}$ has no odd cycles. If $G_0$ has no pendant even cycles, then $G_0$ consists of disjoint even cycles and some isolated vertices. By Lemmas \ref{le:2.3} and \ref{le:2.5},
$r(\widetilde{G}_0)\neq 2m(G_{0})-2\kappa(G_{0})+1$, a contradiction.

Now assume that  $\widetilde{G}_{0}$ has a pendant even cycle, say $\widetilde{C}_{q}$. Let $x$ be the unique vertex of degree 3 in $C_q$. Let $y$ be a vertex of $C_q$ adjacent to $x$. Let $\widetilde{F}=\widetilde{G}_{0}-V(C_{q})$ and $\widetilde{H}=\widetilde{F}+x$. Since $r(\widetilde{G}_{0})= 2m(G_{0})-2\kappa(G_{0})+1$, by Lemmas \ref{le:2.7} and \ref{le:4.2}, $m(F)=m(G_{0}-x)-(q-2)/2=m(G_{0})-1-(q-2)/2=m(G_{0})-q/2$ and $m(H)=m(G_{0}-y)-(q-2)/2=m(G_{0})-1-(q-2)/2=m(G_{0})-q/2$.
If $\sigma(\widetilde{C}_{q})$  is odd or $\sigma(\widetilde{C}_{q})+q \equiv 2~(\mathrm{mod}~4)$, then by Lemma \ref{le:2.8}, $r(\widetilde{F})+q =r(\widetilde{G}_{0})=2m(G_{0})-2\kappa(G_{0})+1=2m(F)+q-2\kappa(F)-2+1$. Thus $r(\widetilde{F})=2m(F)-2\kappa(F)-1$, a contradiction to Inequality (2). So $\widetilde{C}_{q}$ satisfies $\sigma(\widetilde{C}_{q})\equiv q~(\mathrm{mod}~4)$.
By Lemma \ref{le:2.8}, $r(\widetilde{H})+q-2=r(\widetilde{G}_{0})=2m(G_{0})-2\kappa(G_{0})+1=2m(H)+q-2\kappa(H)-2+1$. It follows that $r(\widetilde{H})=2m(H)-2\kappa(H)+1$, a contradiction to minimality of order of $\widetilde{G}_0$.
\end{proof}



\noindent\begin{lemma}\label{le:4.16}
Let $\widetilde{G}$ be a connected mixed graph  with $\kappa(G)=c(G)-1~(c(G)\geq 2)$ vertex-disjoint even cycles and $\widetilde{G}$ has no pendant vertices. If $r(\widetilde{G})= 2m(G)-2\kappa(G)+1$, then $\widetilde{G}$ is a connected mixed graph in $\mathfrak{F}_{1}$.
\end{lemma}
\begin{proof} If $\widetilde{G}$ is a connected mixed bicyclic graph in $\mathfrak{F}_{1}\setminus \mathfrak{F}_{0}$, then we are done. If not, since $r(\widetilde{G})= 2m(G)-2\kappa(G)+1$, by Lemma \ref{le:4.9}(b), $\widetilde{G}$ has a pendant even cycle, say $\widetilde{C}_{q}$. Let $x$ be a vertex in $V(C_q)$ with $d_{G}(x)=3$ and $y$ be a vertex adjacent to $x$ in $V(C_q)$. Let $\widetilde{F}=\widetilde{G}-V(C_{q})$ and $\widetilde{H}=\widetilde{F}+x$. By Lemmas \ref{le:2.7} and \ref{le:4.2}, $m(F)=m(G-x)-(q-2)/2=m(G)-q/2$ and $m(H)=m(G-y)-(q-2)/2=m(G)-q/2$.

If $\sigma(\widetilde{C}_{q})$ is odd or $\sigma(\widetilde{C}_{q})+q \equiv 2~(\mathrm{mod}~4)$, then by Lemma \ref{le:2.8}, $r(\widetilde{G})=r(\widetilde{F})+q=2m(G)-2\kappa(G)+1=2m(F)+q-2\kappa(F)-2+1$. Thus $r(\widetilde{F})=2m(F)-2\kappa(F)-1$, a contradiction to Inequality (2). So $\widetilde{C}_{q}$ satisfies $\eta(\widetilde{C}_{q})\equiv q~(\mathrm{mod}~4)$. By Lemma \ref{le:2.8}, $r(\widetilde{G})=r(\widetilde{H})+q-2=2m(G)-2\kappa(G)+1=2m(H)+q-2\kappa(H)-2+1$. It follows that $r(\widetilde{H})=2m(H)-2\kappa(H)+1$. Applying pendant $K_2$ deletion operations on $\widetilde{H}$, we can obtain a crucial subgraph $\widetilde{H}_{1}$ such that $r(\widetilde{H}_{1})=2m(H_1)-2\kappa(H_1)+1$. Since $r(\widetilde{G})= 2m(G)-2\kappa(G)+1$, by Lemma \ref{le:4.6}, $\widetilde{G}$ has a perfect matching. So the order of $H_1$ is odd. By Lemma \ref{le:4.6}, $\widetilde{H}_1$ has a connected component which is an odd cycle, say $\widetilde{C}_{t}$. If $\widetilde{C}_{t}$ has odd signature, then by Lemma \ref{le:2.5}, $r(\widetilde{C}_{t})=2m(C_{t})$. So by Lemma \ref{le:4.5}(b), $\widetilde{H}_{1}$ has a connected component $\widetilde{H}_{2}$~(different from $\widetilde{C}_{t}$) satisfying that $r(\widetilde{H}_{2})=2m(H_{2})-2\kappa(H_{2})+1$. Note that $\widetilde{H}_{2}$ has no odd cycles.  By Lemma \ref{le:4.15}, we obtain a contradiction. So $\widetilde{C}_{t}$ has even signature. Then by Lemma \ref{le:2.5}, $r(\widetilde{C}_{t})=2m(C_{t})+1$. So by Lemma \ref{le:4.5}(b), for each other connected component $\widetilde{H}^{i}$ of $\widetilde{H}_{1}$, $r(\widetilde{H}^{i})=2m(H^{i})-2\kappa(H^{i})=2m(H^{i})-2c(H^{i})$. So each other connected component $\widetilde{H}^{i}$ of $\widetilde{H}_{1}$ satisfies assertions (a) and (b) of Theorem \ref{th:1.1} and the assertion of Lemma \ref{le:4.13}. Then $\widetilde{G}$ is a mixed graph in $\mathfrak{F}_{0}$, as required.
\end{proof}


\noindent\begin{lemma}\label{le:4.17}
Let $\widetilde{G}$ be a connected mixed graph in $\mathfrak{F}_{2}$. Then $r(\widetilde{G})= 2m(G)-2\kappa(G)+1$.
\end{lemma}
\begin{proof}If $\widetilde{G}$ is  a connected mixed graph in $\mathfrak{F}_{2}\setminus \mathfrak{F}_{0}$, then by Lemmas \ref{le:2.5}, \ref{le:4.7}(b) and \ref{le:4.8}(b), the result holds. Now assume that $\widetilde{G}$ is a mixed graph in $\mathfrak{F}_{0}$. In property (c) of definition of $\mathfrak{F}_{0}$, assume that switching $\widetilde{H}$ to $\widetilde{H}_{1}$ by $k$-step pendant $K_2$ deletion operations. By Lemma \ref{le:2.7}, $m(H)=m(H_1)+2k$. Let $S$ be the set of deleted vertices by switching $\widetilde{H}$ to $\widetilde{H}_{1}$. Let $F$ be the subgraph of $H$ induced by $S$. Let $M_1$ be a maximum matching of $H_1$.  We can select an appropriate matching $M_2$ of size $k$ from $E(F)$ such that $x$ is $M_2$-unsaturated and edges of $M_1$ and $M_2$ have no common incident vertices. Let $M=M_1\cup M_2$. So $M$ is a maximum matching of $H$. Note that $H=G-V(C_q)+x$. Then $m(G)=m(H)+q/2$ as $x$ is an $M$-unsaturated vertex. By properties (a)-(c) of definition of $\mathfrak{F}_{0}$ and Lemmas \ref{le:2.2}, \ref{le:2.5} and \ref{le:2.7}, $r(H)=2m(H)-2\kappa(H)+1$. Since $\widetilde{C}_{q}$ is an even cycle and $\sigma(\widetilde{C}_{q})\equiv q~(\mathrm{mod}~4)$, by Lemma \ref{le:2.8}, $r(\widetilde{G})=r(\widetilde{H})+q-2=2m(H)-2\kappa(H)+1+q-2=2m(G)-2\kappa(G)+1$.
\end{proof}





\medskip
We are ready to give a proof of Theorem \ref{th:1.4}.

\noindent\textbf{Proof of Theorem \ref{th:1.4}.} \textbf{Sufficiency:} By conditions (a) and (b) and Lemmas \ref{le:2.3}, \ref{le:2.5} and \ref{le:4.17}, $r(\widetilde{G}_{1})=2m(G_1)-2\kappa(G_1)+1$. Assume that switching $\widetilde{G}$ to $\widetilde{G}_{1}$ by $k$-step pendant $K_2$ deletion operations. So by Lemmas \ref{le:2.2} and \ref{le:2.7}, $r(\widetilde{G})=r(\widetilde{G}_{1})+2k=2m(G_1)-2\kappa(G_1)+2k=2m(G)-2\kappa(G)$.

\textbf{Necessity:}
 By Theorem \ref{th:1.3} and Lemma \ref{le:4.5}(b), we can assume that $\widetilde{G}$ is connected. Since $r(\widetilde{G})=2m(G)-2\kappa(G)+1$, by Lemma \ref{le:4.2}, $\kappa(G-u)=\kappa(G)-1$ for any vertex $u$ on any even cycle of $G$. By Lemma \ref{le:2.10},  assertion (a) holds.

 For assertion (b), we apply induction on the order of $G$.  If $c(G)=0$, then by Lemma \ref{le:2.4},  $r(\widetilde{G})=2m(G)$, a contradiction. Thus $c(G)\geq 1$. So  $|V(G)|\geq 3$.  If $|V(G)|= 3$, then  $\widetilde{G}$ is a mixed cycle $\widetilde{C}_{3}$. By Lemma \ref{le:2.5}, $\widetilde{G}$ is a mixed cycle $\widetilde{C}_{3}$ with even signature as $r(\widetilde{G})=2m(G)-2\kappa(G)+1$. Then $\widetilde{G}$ is a mixed graph in $\mathfrak{F}_{2}$. So assertion (b)  holds.
Now assume that $|V(G)|\geq 4$.
If $c(G)=1$, then $\kappa(G)=c(G)-1=0$ and $\widetilde{G}$ is a mixed unicyclic  graph with an
odd cycle.  Since $r(\widetilde{G})=2m(G)-2\kappa(G)+1=2m(G)+1$, by Lemma \ref{le:4.12}(b),  assertion (b) holds.

Suppose that $c(G)\geq 2$. Note that $\mathfrak{F}_{1}\subseteq \mathfrak{F}_{2}$. If $\widetilde{G}$ is a mixed graph in $\mathfrak{F}_{1}$, then we are done.  If not, by Lemma \ref{le:4.16}, $\widetilde{G}$ has at least one pendant vertex, say $x$. Let $y$ be the unique neighbor of $x$ in $G$.
 Let $\widetilde{H}=\widetilde{G}-\{x,y\}$. If  $y$ is on the odd cycle of $G$, then by Lemma \ref{le:4.4},
$r(\widetilde{H})= 2m(H)-2\kappa(H)+1= 2m(H)-2c(H)+1$, a contradiction to Lemma \ref{le:2.12}.
Hence $y$ is not on the odd cycle of $G$. Since $r(\widetilde{G})=2m(G)-2\kappa(G)+1$, by Lemma \ref{le:4.3}, $y$ is not on any even
cycle of $G$. By Lemma \ref{le:4.4}, $r(\widetilde{H})=2m(H)-2\kappa(H)+1$.
Note that $\kappa(G)= \kappa(H)= c(H)-1=c(G)-1$. By induction hypothesis, $\widetilde{H}$ satisfies condition (b). Thus $\widetilde{G}$ satisfies condition (b).  ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\quad $\square$

Now, we give an example that satisfies the equality in Theorem \ref{th:1.4}. Let $\widetilde{G}$ be a  mixed graph with an odd cycle $\widetilde{C}_{3}$ having even signature and each other cycle is $\widetilde{C}_{4}$  with $\sigma(\widetilde{C}_{4})\equiv q~(\mathrm{mod}~ 4)$ shown in Fig. 3.
By Lemmas \ref{le:2.2}, \ref{le:2.5} and \ref{le:2.7}, $r(\widetilde{G})=r(\widetilde{G}-\{u,v\})+2=(4-2)\kappa(G)+3+2=2\kappa(G)+5$ and $m(G)=m(G-\{u,v\})+1=2\kappa(G)+1+1=2\kappa(G)+2$.  Thus $r(\widetilde{G})=2m(G)-2\kappa(G)+1$.


\section{Proof of Theorem \ref{th:1.5}}
\noindent\begin{lemma}\label{le:5.1}
Let $\widetilde{G}$ be a bipartite cycle-disjoint mixed graph of order $n$. If $\widetilde{G}$ is nonsingular, then there exists a perfect matching, for any even cycle $\widetilde{C}_{q}$ with $\sigma(\widetilde{C}_{q})\equiv q~(\mathrm{mod}~4)$, $E_{1}(C_{q}) \cap E_{2}(G)\neq \emptyset$.
\end{lemma}
\begin{proof} Since $\widetilde{G}$ is nonsingular, by Remark 1.8, $2m^{\ast}(G)=n$. Since $G$ is a bipartite graph, by Lemma \ref{le:2.13}, $m^{\ast}(G)=m(G)$. Then $2m(G)= n$. So $G$ has a perfect matching. Suppose that the assertion is false. Then there are a perfect matching and an even cycle $\widetilde{C}_{q}$ with $\sigma(\widetilde{C}_{q})\equiv q~(\mathrm{mod}~4)$ such that $E_{1}(C_{q}) \cap E_{2}(G)= \emptyset$. Let $f(\widetilde{G}, \lambda)=\sum_{i=0}^{n}a_{i}\lambda^{n-i}$ be characteristic polynomial of $\widetilde{G}$.
By Lemma \ref{le:2.9}, $$a_{i}=\sum_{\widetilde{B}} (-1)^{\frac{1}{2}\sigma(\widetilde{B})+\omega(B)}2^{\beta(B)},$$
where the sum runs over all basic subgraphs $\widetilde{B}$ of order $i$ in $\widetilde{G}$.

Let $m=m(G)$. Then $a_{2m}\neq 0$ as $\widetilde{G}$ is nonsingular and $G$ has a perfect matching. Since $E_{1}(C_{q}) \cap E_{2}(G)= \emptyset$, for a given basic subgraph $\widetilde{U}$ of order $2m$, three related basic subgraphs of order $2m$ (including $\widetilde{U}$) emerges at the same time. One of them, say $\widetilde{U}$, contains $\widetilde{C}_{q}$ as a component, and the other two are obtained by replacing $\widetilde{C}_{q}$ with two distinct perfect
matchings of $\widetilde{C}_{q}$. The contributions to $a_{2m}$ of the three basic subgraphs are the following three terms:
$$(-1)^{\frac{1}{2}\sigma(\widetilde{U})+\omega(U)}2^{\beta(U)},~ (-1)^{\frac{1}{2}[\sigma(\widetilde{U})-\sigma(\widetilde{C}_q)]+\omega(U)-1+\frac{q}{2}}2^{\beta(U)-1},~ (-1)^{\frac{1}{2}[\sigma(\widetilde{U})-\sigma(\widetilde{C}_q)]+\omega(U)-1+\frac{q}{2}}2^{\beta(U)-1}.$$
Since $q$ is even and $\sigma(\widetilde{C}_{q})\equiv q~(\mathrm{mod}~4)$, the sum of the above three terms equals zero. Thus $a_{2m}=0$, a contradiction.
\end{proof}

Let $\mathcal{B}_{2m(G)}$ be the set of basic subgraphs of order $2m(G)$ in a mixed graph $\widetilde{G}$.


\noindent\textbf{Proof of Theorem \ref{th:1.5}.} \textbf{Necessity:} Since $\widetilde{G}$ is nonsingular, by Remark 1.8, $m^{\ast}(G)=n/2$. So assertion (a) holds. By Lemma \ref{le:5.1},  assertion (b) holds.



 \textbf{Sufficiency:} We apply induction on the order $n$ of $\widetilde{G}$. If $n=2$, then the result holds trivially.
 Now assume that $n\geq 3$. For any perfect matching of $\widetilde{G}$, if for any even mixed cycle $\widetilde{C}_{q}$ of $\widetilde{G}$,
$E_{1}(C_{q})\cap E_{2}(G)\neq \emptyset$. Let $\alpha(G)$ be the number of perfect matchings of $G$. We claim that $\alpha(G)=1$. If $\alpha(G)\geq 2$, note that
$\widetilde{G}$ is a bipartite cycle-disjoint mixed graph with perfect matching, in this case, there
must exists an even mixed cycle $\widetilde{C}$ of $\widetilde{G}$ and a perfect matching, $E_{1}(C)\cap E_{2}(G)=\emptyset$, a contradiction. By Lemma \ref{le:3.2}, we have $r(\widetilde{G})\geq 2m(G)$. Since $G$ is bipartite, by Lemma \ref{le:2.13}, $m^{\ast}(G)=m(G)$. Then by condition (a) and Inequality (2), $r(\widetilde{G})=2m^{\ast}(G)=n$. So $\widetilde{G}$ is nonsingular.

Otherwise, if there exist an even mixed cycle $\widetilde{C}_{q}$ of $\widetilde{G}$ and a perfect matching of $\widetilde{G}$, $E_{1}(\widetilde{C}_{q})\cap E_{2}(G)=\emptyset$, then by condition (b), either $\sigma(\widetilde{C}_{q})+q\equiv 2~(\mathrm{mod}~4)$ or $\sigma(\widetilde{C}_{q})$ is odd. For any basic subgraph $\widetilde{B}$ of order $2m(G)$ of $\widetilde{G}$, $\widetilde{B}$ contains either $\widetilde{C}_{q}$ or a perfect matching of $\widetilde{C}_{q}$. Let $\widetilde{H}=\widetilde{G}-V(C_q)$.
 By induction hypothesis, $\widetilde{H}$ is nonsingular. So $a_{2m(\widetilde{H})}\neq 0$.   If $\sigma(\widetilde{C}_{q})+q\equiv 2~(\mathrm{mod}~4)$, then
 $$\begin{aligned}
a_{2m(\widetilde{G})}&=\sum_{\widetilde{B}\in \mathcal{B}_{2m(G)}} (-1)^{\frac{1}{2}\sigma(\widetilde{B})+\omega(B)}2^{\beta(B)}\\
&=\sum_{\widetilde{U}\in \mathcal{B}_{2m(H)}} (-1)^{\frac{1}{2}[\sigma(\widetilde{U})+\sigma(\widetilde{C}_q)]+\omega(U)+1}2^{\beta(U)+1}+2(-1)^{\frac{1}{2}\sigma(\widetilde{U})+\omega(U)+\frac{q}{2}}2^{\beta(U)}\\
&=\sum_{\widetilde{U}\in \mathcal{B}_{2m(H)}} (-1)^{\frac{1}{2}\sigma(\widetilde{U})+\omega(U)}2^{\beta(U)}[(-1)^{\frac{1}{2}\sigma(\widetilde{C}_q)+1}\cdot 2+2\cdot (-1)^{\frac{q}{2}}]\\
&=\pm 4a_{2m(\widetilde{H})}\neq 0.
\end{aligned}$$
If $\sigma(\widetilde{C}_{q})$ is odd, then
$$\begin{aligned}
a_{2m(\widetilde{G})}&=\sum_{\widetilde{B}\in \mathcal{B}_{2m(G)}} (-1)^{\frac{1}{2}\sigma(\widetilde{B})+\omega(B)}2^{\beta(B)}\\
&=\sum_{\widetilde{U}\in \mathcal{B}_{2m(H)}} 2(-1)^{\frac{1}{2}\sigma(\widetilde{U})+\omega(U)+\frac{q}{2}}2^{\beta(U)}\\
&=\sum_{\widetilde{U}\in \mathcal{B}_{2m(H)}} (-1)^{\frac{1}{2}\sigma(\widetilde{U})+\omega(U)}2^{\beta(U)}2\cdot (-1)^{\frac{q}{2}}\\
&=\pm 2a_{2m(\widetilde{H})}\neq 0.
\end{aligned}$$
Thus $\widetilde{G}$ is nonsingular.   ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\quad $\square$


