\section{Omitted Proof in Section \ref{sec: model}}
\label{sec: proof of lemma -- decomposition}
In this section, we provide the formal proof of Lemma~\ref{lem: score decomposition -- heterogeneous}.

\begin{proof}{Proof of Lemma~\ref{lem: score decomposition -- heterogeneous}.}
By definition, the marginal distribution of $\mathbf R_t$ is
\begin{align*}
p_t(\mathbf r) 
& = \int \underbrace{\phi(\mathbf r; \alpha_t \mathbf r_0, h_t \mathbf I_d)}_{\textrm{Gaussian transition kernel}} p_{\textrm{data}}(\mathbf r_0) \dd \mathbf r_0 \\
& \stackrel{(i)}{=} \int \phi(\mathbf r; \alpha_t (\bm\beta \mathbf f + \bm\varepsilon), h_t \mathbf I_d) {p_{\textrm{fac}}(\mathbf f) \phi\big(\bm\varepsilon;\mathbf 0, \operatorname{diag}\{\sigma_1^2, \sigma_2^2, \dots, \sigma_d^2\}\big) \dd \mathbf f \dd \bm\varepsilon.}
\end{align*}
Here, equality $(i)$ invokes the factor model \eqref{equ: factor model} to represent $\mathbf r_0$ and the independence between factor and noise.

Since $\bm\varepsilon$ is Gaussian with uncorrelated entries, we can simplify $p_t$ as
\begin{align}\label{equ: p_t}
p_t(\mathbf r) 
& = \int \frac{1}{(2\pi h_t)^{d/2}} \exp\left(-\frac{\| \mathbf r - \alpha_t (\bm\beta \mathbf f + \bm\varepsilon)\|_2^2}{2 h_t}\right) \prod_{i=1}^d \frac{1}{\sqrt{2\pi} \sigma_i} \exp\left(-\frac{\varepsilon_{i}^2}{2\sigma_{i}^2}\right) p_{\textrm{fac}}(\mathbf f) \dd \varepsilon_{i} \dd \mathbf f \nonumber \\
& \overset{(i)}{=} \int \prod_{i=1}^d \frac{1}{\sqrt{2\pi(h_t + \sigma_i^2 \alpha_t^2)}} \exp\left(-\frac{([\mathbf r - \alpha_t \bm\beta \mathbf f]_i)^2}{2 (h_t + \sigma_i^2 \alpha_t^2)}\right) p_{\textrm{fac}}(\mathbf f) \dd \mathbf f \nonumber \\
& = \int \frac{1}{\sqrt{(2\pi)^d \det(\bm\Lambda_t)}} \exp\left(-\frac{\|\bm\Lambda_t^{-\frac{1}{2}} \mathbf r - \alpha_t \bm\Lambda_t^{-\frac{1}{2}} \bm\beta \mathbf f \|_2^2}{2}\right) p_{\textrm{fac}}(\mathbf f) \dd \mathbf f,
\end{align}
where $(i)$ holds by completing the squares and integrating with respect to $\varepsilon_{i}$, and the last equality holds by applying the formula of $\bm\Lambda_{t}$ in \eqref{equ: Lambda_t}.


Now we define orthogonal decomposition of the rescaled returns $\bm\Lambda_t^{-\frac{1}{2}} \mathbf r$ into the subspace spanned by $\bm\Lambda_t^{-\frac{1}{2}} \bm\beta$ and its complement:
$$
\bm\Lambda_t^{-\frac{1}{2}} \mathbf r = (\mathbf I - \mathbf T_t)\bm\Lambda_t^{-\frac{1}{2}} \mathbf r + \mathbf T_t \bm\Lambda_t^{-\frac{1}{2}} \mathbf r,
$$
where $\bm\Gamma_t$ and $\mathbf T_t$ are defined in \eqref{equ: Projection_t}, respectively. Along with the fact that $\mathbf T_t(\mathbf I - \mathbf T_t) = \mathbf 0$, we can rewrite $p_t(\mathbf r)$ in \eqref{equ: p_t} as
\begin{equation}
\label{equ: density of r}
\begin{aligned}
    p_t(\mathbf r) = \frac{(2\pi)^{-\frac{d}{2}}}{\sqrt{\det(\bm\Lambda_t)}} \exp \bigg( - \frac{\| (\mathbf I - \mathbf T_t) \bm\Lambda_t^{-\frac{1}{2}} \mathbf r \|_2^2}{2} \bigg) \int \exp \bigg( - \frac{\| \mathbf T_t \bm\Lambda_t^{-\frac{1}{2}} \mathbf r - \alpha_t \bm\Lambda_t^{-\frac{1}{2}}\bm\beta \mathbf f \|_2^2}{2} \bigg) p_{\textrm{fac}}(\mathbf f) \dd \mathbf f.
\end{aligned}
\end{equation}
Take the take gradient of $\log p_t$ with respect to $\mathbf r$ using expression in \eqref{equ: density of r}, we obtain:
\begin{align*}
    \nabla \log p_t(\mathbf r) &= -\bm\Lambda_t^{-\frac{1}{2}} \left(\mathbf I - \mathbf T_t\right)^2 \bm \Lambda_t^{-\frac{1}{2}} \mathbf r \\
    &\qquad - \frac{\int \bm\Lambda_t^{-\frac{1}{2}} \mathbf T_t ( \mathbf T_t \bm\Lambda_t^{-\frac{1}{2}} \mathbf r - \alpha_t \bm\Lambda_t^{-\frac{1}{2}}\bm\beta \mathbf f ) \exp \left( - \frac{\| \mathbf T_t \bm\Lambda_t^{-\frac{1}{2}} \mathbf r - \alpha_t \bm\Lambda_t^{-\frac{1}{2}}\bm\beta \mathbf f \|_2^2}{2} \right) p_{\textrm{fac}}(\mathbf f) \dd \mathbf f}{\int \exp \left( - \frac{\| \mathbf T_t \bm\Lambda_t^{-\frac{1}{2}} \mathbf r - \alpha_t \bm\Lambda_t^{-\frac{1}{2}}\bm\beta \mathbf f \|_2^2}{2} \right) p_{\textrm{fac}}(\mathbf f) \dd \mathbf f} \\ 
    &\stackrel{(i)}{=} -\bm\Lambda_t^{-\frac{1}{2}} \left(\mathbf I - \mathbf T_t\right) \bm \Lambda_t^{-\frac{1}{2}} \mathbf r \\
    &\qquad - \frac{\int \bm\Lambda_t^{-1} \bm\beta ( \bm\beta^\top \bm\Lambda_t^{\frac{1}{2}} \mathbf T_t \bm\Lambda_t^{-\frac{1}{2}} \mathbf r - \alpha_t \mathbf f ) \exp \left( - \frac{\| \bm\Lambda_t^{-\frac{1}{2}} \bm\beta ( \bm\beta^\top \bm\Lambda_t^{\frac{1}{2}} \mathbf T_t \bm\Lambda_t^{-\frac{1}{2}} \mathbf r - \alpha_t \mathbf f ) \|_2^2}{2} \right) p_{\textrm{fac}}(\mathbf f) \dd \mathbf f}{\int \exp \left( - \frac{\| \bm\Lambda_t^{-\frac{1}{2}} \bm\beta ( \bm\beta^\top \bm\Lambda_t^{\frac{1}{2}} \mathbf T_t \bm\Lambda_t^{-\frac{1}{2}} \mathbf r - \alpha_t \mathbf f ) \|_2^2}{2} \right) p_{\textrm{fac}}(\mathbf f) \dd \mathbf f} \\
    &\stackrel{(ii)}{=} - \underbrace{\bm \Lambda_t^{-\frac{1}{2}} (\mathbf I - \mathbf T_t) \cdot \bm \Lambda_t^{-\frac{1}{2}} \mathbf r}_{\mathbf s_{\textrm{comp}}(\mathbf r, t):\textrm{ Complement score }} + \underbrace{\mathbf T_t \bm\Lambda_t^{\frac{1}{2}} \bm\beta \cdot \nabla \log p_t^{\rm{fac}}( \bm\beta^\top \bm\Lambda_t^{\frac{1}{2}} \mathbf T_t \cdot \bm\Lambda_t^{-\frac{1}{2}} \mathbf r)}_{\mathbf s_{\textrm{sub}}( \bm\beta^\top \bm\Lambda_t^{\frac{1}{2}} \mathbf T_t \cdot \bm\Lambda_t^{-\frac{1}{2}} \mathbf r, t):\textrm{ Subspace score }},
\end{align*}
where $(i)$ holds due to the fact that $(\mathbf I -\mathbf T_t)^2 = \mathbf I -\mathbf T_t$ and the following straightforward calculation by invoking the formula $\mathbf T_t$ in \eqref{equ: Projection_t} and $\bm\beta^{\top} \bm\beta = \mathbf I_k$:
\begin{align*}
    \mathbf T_t \bm\Lambda_t^{-\frac{1}{2}} \mathbf r - \alpha_t \bm\Lambda_t^{-\frac{1}{2}}\bm\beta \mathbf f = \bm\Lambda_t^{-\frac{1}{2}} \bm\beta \bm\Gamma_t \bm\beta^\top \bm\Lambda_t^{-\frac{1}{2}} \cdot \bm\Lambda_t^{-\frac{1}{2}} \mathbf r - \alpha_t \bm\Lambda_t^{-\frac{1}{2}}\bm\beta \mathbf f = \bm\Lambda_t^{-\frac{1}{2}} \bm\beta \left( \bm\beta^\top \bm\Lambda_t^{\frac{1}{2}} \mathbf T_t \bm\Lambda_t^{-\frac{1}{2}} \mathbf r - \alpha_t \mathbf f \right).
\end{align*}
In addition, $(ii)$ follows the definition of $p_t^{\rm{fac}}$. \hfill\Halmos
\end{proof}

\section{Omitted Proofs in Section \ref{sec: score approximation and estimation}}
\label{sec:proofs}
In this section, we provide proofs of Theorem~\ref{theorem: score approximation}, Theorem~\ref{theorem: score estimation} and the lemmas used in the proof.


\subsection{Proof of Theorem~\ref{theorem: score approximation}}
\label{subsec: proof of theorem -- score approximation}
\iftrue
\begin{proof}{Proof.}
Given the neural network architecture defined in \eqref{equ: ReLU network},
our goal is to construct a diagonal matrix $\mathbf D_t = \operatorname{diag}\left\{ 1/(h_t + \alpha_t^2 c_1), \dots, 1/(h_t + \alpha_t^2 c_d)\right\} \in \bb R^d$ induced by a vector $\mathbf c = (c_1, \dots, c_d) \in \bb R^d$, a matrix $\mathbf V \in \mathbb{R}^{d \times k}$ with orthonormal columns, and a ReLU network $\mathbf g_{\bm\zeta}(\mathbf V^\top \mathbf D_t \mathbf r, t) \in \calS_{\textrm{ReLU}}$ so that $\mathbf s_{\bm\theta}(\mathbf r, t)$ serves as a good approximator to $\nabla \log p_t(\mathbf r)$. Thanks to the score decomposition in \eqref{equ: score function rearranged}, we choose $\mathbf D_t(\sigma_1, \dots, \sigma_d) = \operatorname{diag}\{ 1/(h_t + \sigma_1^2 \alpha_t^2), \dots, 1/(h_t + \sigma_d^2 \alpha_t^2) \}$ and $\mathbf V = \bm\beta$. It remains to choose neural network hyper-parameters to guarantee the desired approximation power.

\noindent \underline{\bf Step 1: Approximation on $\calC \times \left[0, T\right]$.} 
Define $\calC = \left\{\mathbf z\in \mathbb{R}^k |\left\|\mathbf z\right\|_{2} \leq S \right\}$ as a $k$-dimensional  ball of radius $S > 0$, with the choice of 
\begin{equation}
\label{equ: choice of S}
S = \order(\sqrt{(1+\sigma_{\max}^2) (k + \log (1/\epsilon))} ).
\end{equation}
On $\calC \times\left[0, T\right]$, we approximate the coordinate $\xi_i$ separately for each $i = 1, \dots, d$. 
To ease the analysis, we define the following linear transformation:
\begin{equation}
\label{equ: definition of (xi, y, t) prime}
    \bm\xi^{\prime}(\mathbf y^{\prime}, t^{\prime}) := \bm\xi(\mathbf z, t) \textrm{ with } \mathbf y^{\prime} := (\mathbf z + S \mathbf{1}) / (2S) \textrm{ and } t^{\prime} := t / T
\end{equation}
such that the domain of $\calC \times [0, T]$ is transformed to be contained within $[0,1]^{k} \times [0, 1]$. Therefore, we can equivalently approximate $\xi_i^{\prime}$ for each $i = 1, \dots, d$ on the new domain $[0,1]^{k} \times [0, 1]$.

Recall that the subspace score $\mathbf{s}_{\textrm{sub}}\left(\mathbf z, t\right)$ is $L_s$-Lipschitz in $\mathbf z$ by Assumption \ref{assumption: Lipschitz}. Then, by the definition of $\mathbf s_{\textrm{sub}}$ and $\bm\xi$ in \eqref{equ: s_parallel} and \eqref{equ: definition of xi}, we derive that $\bm\xi(\mathbf z, t)$ is $2(1+L_s)(1+\sigma_{\max}^4)$-Lipschitz in $\mathbf z$. Immediately, we obtain that $\bm\xi^{\prime}(\mathbf y^{\prime}, t^{\prime})$ is $4S (1+L_s)(1+\sigma_{\max}^4)$-Lipschitz in $\mathbf{y}^{\prime}$; so is each coordinate~$\xi_i$. Denote $L_z = 2(1+L_s)(1+\sigma_{\max}^4)$.

Next, define
\begin{equation}
\label{equ: definition of tauS}
\tau(S) := \sup_{t \in [0, T]} \sup_{\mathbf z \in \calC}\left\|\frac{\partial}{\partial t} \bm\xi\left(\mathbf z, t\right)\right\|_2.
\end{equation}
Then for any $\mathbf{y}^{\prime} \in [0,1]^k$, the Lipschitz constant of $\bm\xi^{\prime}(\mathbf{y}^{\prime}, t^{\prime})$ with respect to $t^{\prime}$ is bounded by~$T \tau(S)$. Substituting the order of $S$ in \eqref{equ: choice of S} into the upper bound of $\tau(S)$ in \eqref{equ: upper bound of tauS} in Lemma \ref{lem: lipschitz constant bound in Theorem 1}, we have
\begin{equation}
\label{equ: upper bound of tauS in Theorem 1}
    \tau(S) = \order(L_s (1+\sigma_{\max}^7) \operatorname{poly} k^{3/2} \log^{3/2} (1/\epsilon)).
\end{equation}
For notation simplicity, we abbreviate $\tau(S)$ as $\tau$ when there is no confusion. 

Now we construct a partition of the product space $[0, 1]^k \times [0, 1]$. For the hypercube $[0, 1]^k$, we partition it uniformly into smaller, non-overlapping hypercubes, each with an edge length of $e_1$. Similarly, we partition the interval $[0, 1]$ into non-overlapping subintervals, each of length $e_2$. Here, we take
$$
e_{1} = \calO\left(\frac{\epsilon}{S L_z}\right) \quad \text{and} \quad e_{2} = \calO\left(\frac{\epsilon}{T \tau}\right).
$$
In addition, we denote $N_1=\left\lceil\frac{1}{e_{1}}\right\rceil, N_2=\left\lceil\frac{1}{e_{2}}\right\rceil$.

Let $\mathbf m=\left[m_1, \ldots, m_k \right]^{\top} \in\left\{0, \ldots, N_1 - 1\right\}^{k}$ be a multi-index. We define a function $\Bar{g}^{\prime} : \bb R^{k+1} \mapsto \bb R^k$, with the $i$-th component $g_i^{\prime}$ being
\begin{equation}\label{eq:gprimei}
    \Bar{g}_i^{\prime} \left(\mathbf y^{\prime}, t^{\prime}\right)= \sum_{\mathbf m, j=0, \ldots, N_{2}-1} \xi_i^{\prime} \left(\frac{\mathbf m}{N_1}, \frac{j}{N_{2}}\right) \Psi_{\mathbf{m}, j}\left(\mathbf y^{\prime}, t^{\prime}\right).
\end{equation}
Here $\Psi_{\mathbf{m}, j}\left(\mathbf{y}^{\prime}, t^{\prime}\right)$ is a partition of unity function. Specifically, we choose $\Psi_{\mathbf m, j}$ as a product of coordinate-wise trapezoid functions:
$$
\Psi_{\mathbf{m}, j}\left(\mathbf{y}^{\prime}, t^{\prime}\right)=\psi\left(3 N_{2}\left(t^{\prime}-\frac{j}{N_{2}}\right)\right) \prod_{i=1}^{d} \psi\left(3 N_{1}\left(y_{i}^{\prime}-\frac{m_{i}}{N_{1}}\right)\right),
$$
where $\psi$ is a one-demensional trapezoid function with the specific formula:
$$
\psi(a)= \begin{cases}1, & |a|<1 \\ 2-|a|, & |a| \in[1,2] \\ 0, & |a|>2\end{cases}.
$$
For any $1 \leq i \leq k$, we claim that 
\begin{enumerate}
    \item $\Bar{g}_i^{\prime}$ defined in \eqref{eq:gprimei} can approximate $\xi_i$ arbitrarily well as long as $N_1$ and $N_2$ are sufficiently large;
    \item $\Bar{g}_i^{\prime}$ can be well approximated by a ReLU neural network $\Bar{g}_{\bm\zeta, i}^{\prime}$ with a controllable error.
\end{enumerate}
The above two claims can be verified using Lemma 10 in \citet{chen2020statistical}, in which we substitute the Lipschitz coefficients $4S(1+L_s)(1+\sigma_{\max}^4)$ and $T \tau$ of $\bm\xi^{\prime}$ into the error analysis. Specifically, for any $1 \leq i \leq k$, we consider the ReLU neural network $\Bar{g}_{\bm\zeta, i}^{\prime}$ that satisfies the following Lipschitz property:
\begin{align*}
    &\left\|\Bar{g}_{\bm\zeta, i}^{\prime}\left(\mathbf y_1^{\prime}, t^{\prime}\right)-\Bar{g}_{\bm\zeta, i}^{\prime}\left(\mathbf y_2^{\prime}, t^{\prime}\right)\right\|_{\infty} \leq 10 k S L_z\left\|\mathbf y_1^{\prime} - \mathbf y_1^{\prime}\right\|_{2},\quad \forall~ \mathbf y_1^{\prime}, \mathbf y_1^{\prime} \in [0, 1]^k, t^{\prime} \in [0, 1],~ \textrm{and} \\
    &\left\|\Bar{g}_{\bm\zeta, i}^{\prime}\left(\mathbf y^{\prime}, t_1^{\prime}\right)-\Bar{g}_{\bm\zeta, i}^{\prime}\left(\mathbf y^{\prime}, t_2^{\prime}\right)\right\|_{\infty} \leq 10 T \tau\left\|t_{1}-t_{2}\right\|_{2}, \forall~ t_1^{\prime}, t_2^{\prime} \in [0, 1], \mathbf y^{\prime} \in [0, 1]^k.
\end{align*} 
By concatenating $\Bar{g}_{\bm\zeta, i}^{\prime}$'s together, we construct $\overline{\mathbf g}_{\bm\zeta} = \left[\Bar{g}_{\bm\zeta, 1}, \dots, \Bar{g}_{\bm\zeta, k}\right]^{\top}$. For a given error level $\epsilon > 0$, with a neural network configuration
\begin{gather*}
M=\order\left(T \tau (L_s+1)^k (1+\sigma_{\max}^k) \epsilon^{-(k+1)} \left(\log \frac{1}{\epsilon} + k\right)^{\frac{k}{2}}\right), \gamma_1 = 20k(1+L_s)(1+\sigma_{\max}^4), \\
L=\order\left(\log \frac{1}{\epsilon}+ k \right),\ J=\order\left(T \tau (1+L_s)^k (1+\sigma_{\max}^{k}) \epsilon^{-(k+1)} \left(\log \frac{1}{\epsilon} + k \right)^{\frac{k+2}{2}}\right), \gamma_{2}=10 \tau, \\
K = \order\bigg((1+L_s) (1+\sigma_{\max}^{4}) \left(\log \frac{1}{\epsilon} + k\right)^{\frac{1}{2}}\bigg), \kappa=\max \bigg\{(1+L_s) (1+\sigma_{\max}^4)\bigg(\log \frac{1}{\epsilon} + k\bigg)^{\frac{1}{2}}, T \tau\bigg\},
\end{gather*}
we have
$$
\sup_{(\mathbf y^{\prime}, t^{\prime}) \in [0,1]^k \times [0, 1]}\left\|\overline{\mathbf g}_{\bm\zeta}^{\prime}(\mathbf y^{\prime}, t^{\prime})-\bm\xi^{\prime}(\mathbf y^{\prime}, t^{\prime})\right\|_{\infty} \leq \epsilon.
$$
{To transform the function $\overline{\mathbf g}_{\bm\zeta}^{\prime}$ back to domain $\calC \times (0,T]$, we define 
\begin{equation}
\label{equ: definition of overline g_zeta}
\overline{\mathbf g}_{\bm\zeta}(\mathbf z, t) := \overline{\mathbf g}_{\bm\zeta}^{\prime}(\mathbf y^{\prime}, t^{\prime}) \indicator\{\| \mathbf z \|_2 \leq S\}.
\end{equation}
} By the definition of $\bm\xi^{\prime}$ in \eqref{equ: definition of (xi, y, t) prime}, we deduce that
\begin{equation}
\label{equ: L_infty bound of g_zeta minus xi}
\sup_{(\mathbf z, t) \in \calC \times [0, T]}\left\|\overline{\mathbf g}_{\bm\zeta}(\mathbf z, t)-\bm\xi(\mathbf z, t)\right\|_{\infty} \leq \epsilon.
\end{equation}
Also by the variable transformation in \eqref{equ: definition of (xi, y, t) prime}, we obtain that  $\overline{\mathbf g}_{\bm\zeta}$ is Lipschitz continuous in $\mathbf z$ and $t$. Specifically, for any $\mathbf z_1, \mathbf z_2 \in \calC$ and $t \in [0, T]$, it holds that
$$
\left\|\overline{\mathbf g}_{\bm\zeta}\left(\mathbf z_1, t\right)-\overline{\mathbf g}_{\bm\zeta}\left(\mathbf z_2, t\right)\right\|_{\infty} \leq 10kL_z\left\|\mathbf z_1 - \mathbf z_2\right\|_{2}.
$$
In addition, for any $t_{1}, t_{2} \in [0, T]$ and $\mathbf z \in \calC$, it holds that
$$
\left\|\overline{\mathbf g}_{\bm\zeta}\left(\mathbf z, t_{1}\right)-\overline{\mathbf g}_{\bm\zeta}\left(\mathbf z, t_{2}\right)\right\|_{\infty} \leq 10 \tau|t_{1}-t_{2}|.
$$
By definition of $\overline{\mathbf g}_{\bm\zeta}$ in \eqref{equ: definition of overline g_zeta}, we have $\overline{\mathbf g}_{\bm\zeta}\left(\mathbf z, t\right)=\mathbf{0}$ for $\| \mathbf z \|_2 > S$. Therefore, the Lipschitz continuity property in $\mathbf z$ can be extended to  $\bb R^k$.

\vspace{5pt}
\noindent \underline{\bf Step 2: Bounding $L^2$ Approximation Error.} {Denote $\mathbf Z =\bm\beta^\top \bm\Lambda_t^{-1} \mathbf R_t$ with the distribution $P_{t}^{\textrm{fac}}$. The $L^2$ approximation error of $\overline{\mathbf g}_{\bm\zeta}$ can be decomposed into two terms
\begin{equation}
\begin{aligned}
\label{equ: L2 approximation error decomposition}
    \left\| \bm\xi\left(\mathbf Z, t\right)-\overline{\mathbf g}_{\bm\zeta}\left(\mathbf Z, t\right)\right\|_{L^2\left(P_{t}^{\rm fac}\right)} &= \left\|\left(\bm\xi\left(\mathbf Z, t\right)-\overline{\mathbf g}_{\bm\zeta}\left(\mathbf Z, t\right)\right) \indicator\{\left\| \mathbf Z \right\|_2 < S \}\right\|_{L^2(P_{t}^{\rm fac})} \\
    &\quad + \left\| \bm\xi\left(\mathbf Z, t\right) \indicator \{\|\mathbf Z\|_2 > S\} \right\|_{L^2 \left(P_{t}^{\rm fac}\right)}.
\end{aligned}
\end{equation}
By applying the $L^{\infty}$ approximation error bound in \eqref{equ: L_infty bound of g_zeta minus xi},} the first term in \eqref{equ: L2 approximation error decomposition} is bounded by
\begin{equation}\label{eq:first_term}
\left\|\left(\bm\xi\left(\mathbf Z, t\right)-\overline{\mathbf g}_{\bm\zeta}\left(\mathbf Z, t\right)\right) \indicator\{\left\| \mathbf Z \right\|_2 < S \}\right\|_{L^2(P_{t}^{\rm fac})} \leq \sqrt{k} \underset{(\mathbf z, t) \in \calC \times [0, T]}{\sup}\left\|\left(\bm\xi\left(\mathbf z, t\right)-\overline{\mathbf g}_{\bm\zeta}\left(\mathbf z, t\right)\right) \right\|_{\infty} \leq \sqrt{k} \epsilon.
\end{equation}
The second term on the right-hand side of \eqref{equ: L2 approximation error decomposition} is controlled by the upper bound \eqref{equ: truncation error -- heterogeneous} in Lemma \ref{lem: truncation error -- heterogeneous}. Specifically, by choosing $S = \order
(\sqrt{(1+\sigma_{\max}^2) (k + \log (1/\epsilon))} )$, we have
\begin{equation}\label{eq:second_term}
    \left\| \bm\xi\left(\mathbf Z, t\right) \indicator \{\|\mathbf Z\|_2 > S\} \right\|_{L^2 \left(P_{t}^{\rm fac}\right)} \leq \epsilon.
\end{equation}
Combining \eqref{eq:first_term} and \eqref{eq:second_term}, we deduce that
\begin{equation}
\label{eq:inter_error}
\left\|\bm\xi\left(\mathbf Z, t\right)-\overline{\mathbf g}_{\bm\zeta}\left(\mathbf Z, t\right)\right\|_{L^2\left(P_{t}^{\rm fac}\right)} \leq(\sqrt{k}+1) \epsilon.    
\end{equation}
Furthermore, by involving $\bar{\mathbf g}_{\bm\zeta}$, we construct the following approximator $\overline{\mathbf s}_{\bm\theta}$ for $\nabla \log p_{t}(\mathbf r)$ 
\begin{equation}
\label{equ: Bar s theta}
\overline{\mathbf s}_{\bm\theta}(\mathbf r, t) := \alpha_t\bm\Lambda_t^{-1} \bm\beta \overline{\mathbf g}_{\bm\zeta}(\bm\beta^\top \bm\Lambda_t^{-1} \mathbf r, t) - \bm\Lambda_t^{-1} \mathbf r.
\end{equation}
Then, by applying the formula of $\nabla \log p_t$ and $\overline{\mathbf s}_{\bm\theta}$ in \eqref{equ: score function rearranged} and \eqref{equ: Bar s theta} respectively, we obtain that
\begin{align*}
    \|\nabla \log p_{t}(\cdot)-\overline{\mathbf s}_{\bm\zeta}(\cdot, t)\|_{L^2\left(P_{t}\right)} &= \left\|\alpha_t \bm\Lambda_t^{-1/2} \bm\beta (\bm\xi(\mathbf Z, t) - \overline{\mathbf g}_{\bm\zeta}(\mathbf Z, t)) \right\|_{L^2\left(P_{t}^{\rm fac}\right)} \leq \frac{(\sqrt{k}+1)\epsilon}{\min\{\sigma_d^2, 1\}},
\end{align*}
where the inequality invokes $\| \bm\Lambda_t^{-1} \bm\beta \|_{\mathrm{op}} \leq 1 /(h_t + \sigma_d^2 \alpha_t^2) \leq 1/\min\{\sigma_d^2, 1\}$ and the error bound \eqref{eq:inter_error}. \hfill\Halmos
\end{proof}
\fi

\subsection{Proof of Theorem~\ref{theorem: score estimation}}
\label{subsec: proof of theorem -- score estimation}
\iftrue
\begin{proof}{Proof.}

\vspace{4pt}
\noindent \underline{\bf Step 1: Error Decomposition.} 
The proof is based on the following bias-variance decomposition on $\calL\left(\widehat{\mathbf s}_{\bm\theta}\right)$.
For any $a \in(0,1)$, we decompose $\calL\left(\widehat{\mathbf s}_{\bm\theta}\right)$ as
\begin{align*}
\calL\left(\widehat{\mathbf s}_{\bm\theta}\right) &= \calL\left(\widehat{\mathbf s}_{\bm\theta}\right)-(1+a) \widehat{\calL}\left(\widehat{\mathbf s}_{\bm\theta}\right)+(1+a) \widehat{\calL}\left(\widehat{\mathbf s}_{\bm\theta}\right) \\
& \leq \underbrace{\calL^{\textrm{trunc}}\left(\widehat{\mathbf s}_{\bm\theta}\right) - (1+a) \widehat{\calL}^{\textrm{trunc}}\left(\widehat{\mathbf s}_{\bm\theta}\right)}_{(A)}+\underbrace{\calL\left(\widehat{\mathbf s}_{\bm\theta}\right)-\calL^{\textrm{trunc}}\left(\widehat{\mathbf s}_{\bm\theta}\right)}_{(B)} + (1+a) \underbrace{\inf _{\mathbf s_{\bm\theta} \in \calS_{\textrm{NN}}} \widehat{\calL}\left(\mathbf s_{\bm\theta}\right)}_{(C)},
\end{align*}
where $\calL^{\textrm{trunc}}$ is defined as
\begin{equation}
\label{equ: definition of truncated loss function}
\calL^{\textrm{trunc}}\left(\mathbf s_{\bm\theta}\right) := \int \ell^{\textrm{trunc}}(\mathbf r ; \mathbf s_{\bm\theta}) p_t(\mathbf r) \dd \mathbf r \quad \textrm{ with } \quad \ell^{\textrm{trunc}}(\mathbf r ; \mathbf s_{\bm\theta}) := \ell(\mathbf r ; \mathbf s_{\bm\theta}) \indicator\left\{\|\mathbf r\|_{2} \leq \rho \right\}
\end{equation}
subject to some truncation radius $\rho$ to be determined.

In the sequel, we bound $(A)$ -- $(C)$ separately. The term $(A)$ is the statistical error due to finite samples, term $(B)$ is the truncation error, term $(C)$ reflects the approximation error of $\calS_{\textrm{NN}}$.

Note that the introduction of the hyper-parameter $a>0$ (to be determined) is to handle the bias by applying Bernstein's concentration inequality \cite[Lemma 15]{chen2023score}. Conversely, setting $a=0$ results in a convergence rate at $\order(n^{-1/2})$, as derived using only Hoeffding's concentration inequality.

\vspace{5pt}
\noindent \underline{\bf Step 2: Bounding Term $(A)$.} We denote $\mathcal{G}:=\left\{\ell^{\textrm{trunc}}\left(\cdot ; \mathbf s_{\bm\theta}\right): \mathbf s_{\bm\theta} \in \calS_{\textrm{NN}}\right\}$ as the class of loss functions induced by the score network $\calS_{\textrm{NN}}$. We first determine an upper bound on all functions in $\mathcal{G}$ by  bounding $\sup_{\mathbf s_{\bm\theta} \in \calS_{\textrm{NN}}} \sup_{\mathbf r \in \bb{R}^{d}} 
| \ell^{\textrm{trunc}}(\mathbf r; \mathbf s_{\bm\theta}) |$.

To start, we consider 
\begin{align}
\bigg\|\mathbf s_{\bm\theta}(\mathbf r^{\prime}, t)+\frac{(\mathbf r^{\prime}-\alpha_t \mathbf r)}{h_t}\bigg\|_2 &\leq \|\mathbf s_{\bm\theta}(\mathbf r^{\prime}, t) + \mathbf D_t \mathbf r^{\prime} \|_2 + \bigg\| \frac{(\mathbf I - h_t \mathbf D_t) \mathbf r^{\prime}}{h_t} \bigg\|_2 + \bigg\|\frac{\alpha_t \mathbf r}{h_t} \bigg\|_2 \nonumber \\
&\stackrel{(i)}{=} \alpha_t \|\mathbf D_t \mathbf V \mathbf g_{\bm\theta}(\mathbf V^{\top} \mathbf D_t \mathbf r^{\prime}, t)\|_2 + \frac{\| \mathbf I - h_t \mathbf D_t \|_2 \| \mathbf r^{\prime} \|_2}{h_t} + \frac{\alpha_t \|\mathbf r \|_2}{h_t} \nonumber \\
&= \order \bigg(\frac{K + \| \mathbf r^{\prime} \|_2 + \| \mathbf r \|_2}{h_t}\bigg), \label{equ: first bound for ell in (A) of Theorem 2}
\end{align}
where $(i)$ holds by applying the formula of $\mathbf s_{\bm\theta}$ in \eqref{equ: score network} and $(ii)$ follows from the facts that $\alpha_t^2 \leq 1$, $\| \mathbf D_t \|_{\textrm{op}} \leq 1/h_t$, $\| \mathbf V \|_{\textrm{op}} = 1$, and $\| \mathbf g_{\bm\theta} \|_2 \leq K$.

By the definition of $\ell^{\textrm{trunc}}$ in \eqref{equ: definition of truncated loss function}, for any $\mathbf s_{\bm\theta} \in \calS_{\textrm{NN}}$ we have  $\ell^{\textrm{trunc}}(\mathbf r ; \mathbf s_{\bm\theta}) = 0$  if $\| \mathbf r \|_2 > \rho$. For any $\| \mathbf r \|_2 \leq \rho$, we have
\begin{align*}
\ell^{\textrm{trunc}}(\mathbf r ; \mathbf s_{\bm\theta}) & = \frac{1}{T - t_0} \int_{t_0}^T \E_{\mathbf R_t|\mathbf R_0 = \mathbf r} \bigg\|\mathbf s_{\bm\theta}(\mathbf R_t, t) + \frac{\mathbf R_t - \alpha_t \mathbf r}{h_t} \bigg\|_2^2 \cdot \indicator\left\{\|\mathbf r\|_{2} \leq \rho\right\} \dd t \\
& \stackrel{(i)}{=} \order \bigg( \frac{1}{T - t_0} \int_{t_0}^{T} \E_{\mathbf R_t|\mathbf R_0 = \mathbf r} \bigg(\frac{K^2 + \| \mathbf R_t \|_2^2 + \| \mathbf r \|_2^2 }{h_t^2}\bigg) \cdot \indicator\left\{\|\mathbf r\|_{2} \leq \rho\right\} \dd t \bigg) \\
& \stackrel{(ii)}{=} \order \bigg( \frac{1}{T - t_0} \int_{t_0}^{T} \bigg( \frac{2 \rho^2 + K^2}{h_t^2} + \frac{d}{h_t} \bigg) \dd t \bigg) \\
& = \order \bigg( \frac{\rho^2 + K^2}{t_0\left(T-t_0\right)} + \frac{d}{T - t_0}\log \frac{T}{t_0} \bigg),
\end{align*}
where $(i)$ holds by the uniform upper bound \eqref{equ: first bound for ell in (A) of Theorem 2}; $(ii)$ holds by applying the facts that $(\mathbf R_t | \mathbf R_0 = \mathbf r) \sim \mathcal{N}(\alpha_t \mathbf r, h_t \mathbf I_d)$ and $\| \mathbf r \|_2 \leq \rho$ and $\alpha_t^2 \leq 1$.


To bound term $(A)$, it is essential to consider the covering number of $\calS_{\textrm{NN}}$,  as it measures the approximation power of the neural network class. Take $\mathbf s_{\bm\theta_1}$ and $\mathbf s_{\bm\theta_2}$ such that 
$$
\sup_{\|\mathbf r^{\prime}\|_{2} \leq 3\rho + \sqrt{d \log d}, t \in\left[t_0, T\right]}\left\|\mathbf s_{\bm\theta_1}(\mathbf r^{\prime}, t)-\mathbf s_{\bm\theta_2}(\mathbf r^{\prime}, t)\right\|_{2} \leq \iota,
$$
we then have
\begin{align*}
&\quad \left\|\ell^{\textrm{trunc}}\left(\cdot ; \mathbf s_{\bm\theta_1}\right)-\ell^{\textrm{trunc}}\left(\cdot ; \mathbf s_{\bm\theta_2}\right)\right\|_{\infty} \\
&= \sup _{\|\mathbf r\|_{2} \leq \rho} \frac{1}{T - t_0} \int_{t_0}^{T}  \E_{\mathbf R_t|\mathbf R_0 = \mathbf r} \bigg[\left\|\mathbf s_{\bm\theta_1}\left(\mathbf R_t, t\right)-\mathbf s_{\bm\theta_2}\left(\mathbf R_t, t\right)\right\|_{2} \cdot \left\|\mathbf s_{\bm\theta_1}\left(\mathbf R_t, t\right) + \mathbf s_{\bm\theta_2}\left(\mathbf R_t, t\right) + \frac{2(\mathbf R_t - \alpha_t \mathbf r)}{h_t}\right\|_{2}\bigg] \dd t \\
& \stackrel{(i)}{\leq} \sup _{\|\mathbf r\|_{2} \leq \rho} \frac{1}{T-t_0} \int_{t_0}^{T} \E_{\mathbf R_t | \mathbf R_0 = \mathbf r} \left[ \frac{2}{h_t} \left(K + \left\| \mathbf R_t \right\|_2 + \left\| \mathbf r \right\|_2 \right) \left\|\mathbf s_{\bm\theta_1}\left(\mathbf R_t, t\right)-\mathbf s_{\bm\theta_2}\left(\mathbf R_t, t\right)\right\|_{2} \right. \\
&\qquad \qquad \left. \cdot \indicator\left\{\left\|\mathbf R_t\right\|_{2} \leq 3\rho + \sqrt{d \log d}\right\}\right] \dd t \\
&\quad + \sup _{\|\mathbf r\|_{2} \leq \rho} \frac{1}{T-t_0} \int_{t_0}^{T} \E_{\mathbf R_t | \mathbf R_0 = \mathbf r} \left[ \frac{2}{h_t} \left(K + \left\| \mathbf R_t \right\|_2 + \left\| \mathbf r \right\|_2 \right) \left\|\mathbf s_{\bm\theta_1}\left(\mathbf R_t, t\right)-\mathbf s_{\bm\theta_2}\left(\mathbf R_t, t\right)\right\|_{2} \right. \\
&\qquad \qquad \left. \cdot \indicator\left\{\left\|\mathbf R_t\right\|_{2} > 3\rho + \sqrt{d \log d}\right\}\right] \dd t \\
& \stackrel{(ii)}{\leq} \sup_{\|\mathbf r\|_{2} \leq \rho} \frac{2 \iota}{T-t_0} \int_{t_0}^{T} \E_{\mathbf R_t | \mathbf R_0 = \mathbf r} \left[ \frac{1}{h_t} \left(K + \left\| \mathbf R_t \right\|_2 + \left\| \mathbf r \right\|_2 \right) \cdot \indicator\left\{\left\|\mathbf R_t\right\|_{2} \leq 3\rho + \sqrt{d \log d}\right\}\right] \dd t \\
&\quad + \sup _{\|\mathbf r\|_{2} \leq \rho} \frac{1}{T-t_0} \int_{t_0}^{T} \E_{\mathbf R_t | \mathbf R_0 = \mathbf r} \left[ \frac{2}{h_t} \left(K + \left\| \mathbf R_t \right\|_2 + \left\| \mathbf r \right\|_2 \right) \left\|\mathbf s_{\bm\theta_1}\left(\mathbf R_t, t\right)-\mathbf s_{\bm\theta_2}\left(\mathbf R_t, t\right)\right\|_{2} \right. \\
&\qquad \qquad \left. \cdot \indicator\left\{\left\|\mathbf R_t\right\|_{2} > 3\rho + \sqrt{d \log d}\right\}\right] \dd t,
\end{align*}
where $(i)$ follows from applying the upper bound in \eqref{equ: first bound for ell in (A) of Theorem 2} and decomposing the error into two parts: within the compact domain of radius $3\rho + \sqrt{d \log d}$, and outside this domain; $(ii)$ holds since $\left\|\mathbf s_{\bm\theta_1}(\mathbf r^{\prime}, t)-\mathbf s_{\bm\theta_2}(\mathbf r^{\prime}, t)\right\|_{2} \leq \iota$ in the compact domain $\| \mathbf r^{\prime} \| \leq 3\rho + \sqrt{d \log d}$. Then, we deduce that
\begin{align*}
& \quad \|\ell^{\textrm{trunc}}(\cdot ; \mathbf s_{\bm\theta_1})-\ell^{\textrm{trunc}}(\cdot ; \mathbf s_{\bm\theta_2})\|_{\infty} \\
& \stackrel{(i)}{=} \order \bigg( \frac{2 \iota}{T-t_0} \int_{t_0}^{T} \frac{K + \sqrt{h_t d} + 2\rho}{h_t} \dd t + \frac{2}{T-t_0} \int_{t_0}^{T} \frac{1}{h_t} \bigg(\rho K^2 h_t^{-\frac{d+4}{2}} \left(\frac{\rho}{d}\right)^{d} \exp \bigg(-\frac{\rho^2}{h_t} \bigg) \bigg) \dd t \bigg) \\
& \stackrel{(ii)}{=} \order\bigg(\iota \cdot \frac{(\rho + K)\log (T/t_0) + \sqrt{d}(\sqrt{T}-\sqrt{t_0})}{T-t_0} + \rho K^2 \left( \frac{\rho}{d} \right)^{\frac{d}{2}} \exp \left(- \frac{\rho^2}{2 h_T}\right) \bigg),
\end{align*}
where $(i)$ holds by applying $ (\mathbf R_t | \mathbf R_0 = \mathbf r) \sim \mathcal{N}(\alpha_t \mathbf r, h_t \mathbf I_d)$, $\| \mathbf r \|_2 \leq \rho$ and the upper bound \eqref{equ: SNN truncation error} in Lemma \ref{lem: SNN truncation error -- heterogeneous}; $(ii)$ follows from the facts that $h_t = \order(t)$ as $t \to 0$ and the second term in $(i)$ has a dominating exponential decay rate $\exp (-\rho^2 / h_t)$. 
For notational simplicity, we denote
\begin{equation}
\label{equ: definition of eta}
\eta := \rho K^2 ( \rho / d )^{d/2} \exp (- \rho^2 / (2 h_T) ).
\end{equation}
Denote the $\tau$-covering number of a class of functions $\mathcal{H}$ under a metric $\Psi(\cdot)$ by
\begin{equation}
\label{equ: definition of covering number}
\mathfrak{N}(\tau, \mathcal{H}, \Psi(\cdot)) = \inf\{|\mathcal{H}_1|: \mathcal{H}_1 \subseteq \mathcal{H},\ \forall h \in \mathcal{H},\ \exists h_1 \in \mathcal{H},\ \mathrm{s.t.} \ \Psi(h, h_1) \leq \tau \},
\end{equation}
where $|\mathcal{H}_1|$ represents the number of functions in the class $\mathcal{H}_1$.
Immediately, we can deduce that an $\iota$-covering of $\calS_{\textrm{NN}}$ induces a covering of $\mathcal{G}$ with an accuracy $\iota \cdot \frac{(\rho + K)\log (T/t_0) + \sqrt{d}(\sqrt{T}-\sqrt{t_0}))}{T-t_0}+ \eta$. To apply Bernstein-type concentration inequality \cite[Lemma 15]{chen2023score} for $\ell^{\textrm{trunc}}\left(\cdot ; \mathbf s_{\bm\theta}\right)$, let us take $B = \order(\frac{\rho^2 + K^2 + t_0 d \log (T/t_0)}{t_0(T-t_0)})$, $\tau = \iota$ and the corresponding covering number of $\calS_{\textrm{NN}}$ as
\begin{equation*}
\mathfrak{N}\left( \frac{(\iota - \eta)(T-t_0)}{(\rho + K)\log (T/t_0) + \sqrt{d}(\sqrt{T}-\sqrt{t_0}))}, \calS_{\textrm{NN}},\|\cdot\|_{2}\right)
\end{equation*}
Then by Lemma 15 of \cite{chen2023score}, with probability $1-\delta$, it holds that
\begin{equation}
\label{equ: error bound of term (A) in Theorem 2}
    (A) = \order\left(\frac{(1+\frac{3}{a}) \big(\frac{\rho^2 + K^2 + t_0 d \log (\frac{T}{t_0})}{t_0(T-t_0)}\big)}{n} \log \frac{\mathfrak{N}\Big( \frac{(\iota - \eta)(T-t_0)}{(\rho + K)\log (\frac{T}{t_0}) + \sqrt{d}(\sqrt{T}-\sqrt{t_0})}, \calS_{\textrm{NN}},\|\cdot\|_{2}\Big)}{\delta}+(2+a) \iota \right).
\end{equation}

\vspace{5pt}
\noindent \underline{\bf Step 3: Bounding Term $(B)$.} By applying the formulas of $\ell$ and $\ell^{\textrm{trunc}}$ in \eqref{equ: empirical loss function} and \eqref{equ: definition of truncated loss function}, we have
\begin{align*}
(B) &= \frac{1}{T - t_0} \int_{t_0}^{T} \E_{\mathbf R_0 \sim P_{\textrm{data}}} \E_{\mathbf R_t | \mathbf R_0}\bigg[\bigg\|\widehat{\mathbf s}_{\bm\theta}(\mathbf R_t, t)+\frac{(\mathbf R_t-\alpha_t \mathbf R_0)}{h_t}\bigg\|_2^2 \indicator\left\{\|\mathbf R_0\|_{2} > \rho\right\}\bigg] \dd t \\
& \leq \frac{2}{T - t_0} \int_{t_0}^{T} \E_{\mathbf R_0 \sim P_{\textrm{data}}} \bigg[ \frac{h_t d + K^2 + 2\|\mathbf R_0\|^2_2}{h_t^2} \indicator\{ \| \mathbf R_0 \|_2 > \rho \} \bigg] \dd t,
\end{align*}
where the inequality follows from applying the upper bound \eqref{equ: first bound for ell in (A) of Theorem 2} and $(\mathbf R_t | \mathbf R_0 = \mathbf r) \sim \mathcal{N}(\alpha_t \mathbf r, h_t \mathbf I_d)$.
Notice that the density of $\mathbf R_0 = \bm\beta \mathbf F + \bm\varepsilon$ can be bounded by
\begin{align}
    p_{\textrm{data}}(\mathbf r) &= \prod_{i=1}^d \frac{1}{\sqrt{2\pi} \sigma_i} \exp\left(-\frac{\varepsilon_{i}^2}{2\sigma_{i}^2}\right) p_{\textrm{fac}}(\mathbf f) \nonumber \\
    & \stackrel{(i)}{\leq} \frac{(2 \pi)^{-(d+k)/2} C_1}{\prod_{i=1}^d \sigma_i} \exp\left(- \frac{\sigma_{\max}^{-2} \| \bm\epsilon \|_2^2 + C_2 \| \bm\beta \mathbf f \|_2^2}{2}\right) \nonumber \\
    & \leq \frac{C_1 (2 \pi)^{-(d+k)/2}}{\prod_{i=1}^d \sigma_i} \exp\left(- \frac{\| \mathbf r \|_2^2 }{2 (\sigma_{\max}^2 + 1 / C_2)}\right), \label{equ: R0 sub-Gaussian tail -- heterogeneous}
\end{align}
where $(i)$ follows from the sub-Gaussian tail \eqref{eqn:subgaussian} in Assumption \ref{assumption: subgaussian} and the fact that $\bm\beta$ is a norm-preserving transformation satisfying $\bm\beta^\top \bm\beta = \mathbf I$ in Assumption~\ref{assumption: factor}. Therefore, by applying the upper bound of $p_{\textrm{data}}$ in \eqref{equ: R0 sub-Gaussian tail -- heterogeneous}, we obtain
\begin{align}
(B) & \leq \frac{2}{T - t_0} \int_{t_0}^{T} \bigg[ \bigg( \frac{h_t d + K^2 + 2\|\mathbf r\|^2}{h_t^2} \bigg) \frac{C_1 (2 \pi)^{-\frac{d+k}{2}}}{\prod_{i=1}^d \sigma_i} \exp\left(- \frac{\| \mathbf r \|_2^2 }{2 (\sigma_{\max}^2 + 1 / C_2)}\right) \indicator\{ \| \mathbf r \|_2 > \rho \} \bigg] \dd t \nonumber \\
& \stackrel{(i)}{\leq} \frac{C_1 d (\sigma_{\max}^2 + 1 / C_2) 2^{-(d+k)/2}}{(\prod_{i=1}^{d} \sigma_i) (T - t_0)\Gamma(d/2 + 1)} \exp \bigg(- \frac{\rho^2}{2 (\sigma_{\max}^2 + 1 / C_2)} \bigg) \displaystyle\int_{t_0}^{T} \frac{\rho^{d-1} (h_t d + K^2 + \rho^2)}{h_t^2} \dd t \nonumber \\
& =\order\left( \frac{d \rho^{d-1} 2^{-(d+k)/2} (\sigma_{\max}^2 + 1 / C_2)}{(\prod_{i=1}^{d} \sigma_i)(T - t_0)\Gamma(d/2 + 1)} \left(\frac{\rho^2 + K^2}{t_0} + d\log \frac{T}{t_0} \right) \exp \left(- \frac{\rho^2}{2 (\sigma_{\max}^2 + 1 / C_2)} \right) \right), \label{equ: error bound of term (B) in Theorem 2}
\end{align}
where $(i)$ follows from the tail estimation in Lemma 16 of \cite{chen2023score}.

\vspace{5pt}
\noindent \underline{\bf Step 4: Bounding Term $(C)$.} Recall that $\overline{\mathbf s}_{\bm\theta}$ is the constructed network approximator in Theorem \ref{theorem: score approximation}. For any $\epsilon>0$, we have
$$
(C) \leq \underbrace{\widehat{\calL}(\overline{\mathbf s}_{\bm\theta})-(1+a) \calL^{\textrm{trunc}}(\overline{\mathbf s}_{\bm\theta})}_{(\spadesuit)}+(1+a) \underbrace{\calL^{\textrm{trunc}}(\overline{\mathbf s}_{\bm\theta})}_{(\clubsuit)},
$$
where $(\spadesuit)$ is the statistical error and $(\clubsuit)$ is the approximation error.

First, we can bound $(\spadesuit)$ with high probability using the fact that $\mathbf R_0$ has a sub-Gaussian tail. Specifically, applying Lemma 16 of \citet{chen2023score} to $\mathbf R_0$ with density bound \eqref{equ: R0 sub-Gaussian tail -- heterogeneous}, we obtain
\begin{equation}
\label{equ: definition of probability q}
    \mathbb{P}\left(\|\mathbf R_0\|_{2} > \rho\right) \leq \frac{C_1 d (\sigma_{\max}^2 + 1 / C_2) 2^{-(d+k)/2}}{(T - t_0)\Gamma(d/2 + 1) \left(\prod_{i=1}^d \sigma_i\right)} \rho^{d-1} \exp \left(- \frac{\rho^2}{2 (\sigma_{\max}^2 + 1/C_2)} \right) := q.
\end{equation}
Applying union bound for $n$ i.i.d. data samples $\{\mathbf R_0^i\}_{i=1}^{n}$ from $P_{\textrm{data}}$ leads to
\begin{align*}
\mathbb{P}\left(\left\|\mathbf R_{0}^{i}\right\|_{2} \leq \rho \textrm{ for all } i=1, \ldots, n\right) \geq 1 - nq.
\end{align*}
Immediately, we obtain that, with probability $1 - nq$, it holds
$$
(\spadesuit) = \widehat{\calL}^{\textrm{trunc}}(\overline{\mathbf s}_{\bm\theta})-(1+a) \calL^{\textrm{trunc}}(\overline{\mathbf s}_{\bm\theta}).
$$
Meanwhile, Lemma 15 of \cite{chen2023score} implies that with probability $1 - \delta$, it holds that
\begin{equation}
\label{equ: error bound of (Box)}
(\spadesuit) = \order\bigg(\frac{(1+6 / a)}{n}\bigg( \frac{\rho^2 + K^2}{t_0(T-t_0)} + \frac{d}{T - t_0}\log \frac{T}{t_0} \bigg) \log \frac{1}{\delta}\bigg).
\end{equation}
Here, we take $\delta$ defined in \eqref{equ: error bound of term (A) in Theorem 2}. For $(\clubsuit)$, we have 
\begin{align}
(\clubsuit) \leq \calL(\overline{\mathbf s}_{\bm\theta}) &= \frac{1}{T-t_0} \int_{t_0}^{T}\E_{\mathbf R_t \sim P_t}\left\|\overline{\mathbf s}_{\bm\theta}(\mathbf R_t, t)-\nabla \log p_{t}(\mathbf R_t)\right\|_{2}^{2} \dd t \nonumber \\
&\qquad + \underbrace{\calL\left(\overline{\mathbf s}_{\bm\theta}\right)-\frac{1}{T-t_0} \int_{t_0}^{T}\E_{\mathbf R_t \sim P_t}\left\|\overline{\mathbf s}_{\bm\theta}(\mathbf R_t, t)-\nabla \log p_{t}(\mathbf R_t)\right\|_{2}^{2} \dd t}_{(E)}. \label{equ: definition of (E)}
\end{align}
Then, by Theorem~\ref{theorem: score approximation}, we have
\begin{equation}
\label{equ: error bound of (Diamond)}
(\clubsuit) = \order\bigg(\frac{k \epsilon^2}{t_0 (T-t_0)}\bigg) + (E).
\end{equation}
Note that the two terms in $(E)$ are equivalent to the score-matching objectives \eqref{equ: score-matching loss function} and \eqref{equ: denoising score-matching loss function}, hence $(E)$ is on a constant order.



Combining two error bounds for $(\spadesuit)$ and $(\clubsuit)$ in \eqref{equ: error bound of (Box)} and \eqref{equ: error bound of (Diamond)}, we deduce that, with probability $(1 - nq)(1-\delta)$, it holds
\begin{equation}
\label{equ: error bound of term (C) in Theorem 2}
    (C) = \order\bigg(\frac{(1+6 / a)}{n}\left( \frac{\rho^2 + K^2}{t_0\left(T-t_0\right)} + \frac{d}{T - t_0}\log \frac{T}{t_0} \right) \log \frac{1}{\delta} + \frac{(1+a) k \epsilon^2}{t_0 (T-t_0)} \bigg) + (1+a) \cdot (E).
\end{equation}



\vspace{5pt}
\noindent \underline{\bf Step 5: Choosing $\rho$ and putting together $(A)$, $(B)$ and $(C)$.} 
Under a fixed $\delta > 0$ in \eqref{equ: error bound of term (A) in Theorem 2}, we choose $\rho$ and $\tau$ as the following to balance terms $(A)$, $(B)$, and $(C)$,
\begin{equation}
\label{equ: choice of rho and tau}
    \rho = \order \left( \sqrt{\sigma_1^2 \left(d + \log K + \log (n / \delta) \right) }\right) \textrm{ and } \tau = \order \bigg( \frac{1}{n t_0 (T-t_0)} \bigg).
\end{equation}
By direct calculation, our choice of $\rho$ implies that $q \leq \delta / n$, where $q$ is defined in \eqref{equ: definition of probability q}. Next, we derive the error bound for terms (A)-(C) under our choice of the hyper-parameters.
\begin{enumerate}
    \item For term $(A)$, we first give an upper bound for $\eta$ defined in \eqref{equ: definition of eta}. Substituting the order of $\rho$ in \eqref{equ: choice of rho and tau} into \eqref{equ: definition of eta}, we deduce that
    \begin{equation}
    \label{equ: order of eta}
        \eta = \order\bigg( \frac{1}{nt_0(T-t_0)} \bigg).
    \end{equation}
    Then, substituting the order of $K$ in \eqref{equ: order of parameters in Theorem 1} in Theorem \ref{theorem: score approximation} and the hyperparameters in \eqref{equ: choice of rho and tau} and \eqref{equ: order of eta} into \eqref{equ: error bound of term (A) in Theorem 2}, we obtain that with probability $1 - \delta$, it holds that
    \begin{equation}
    \begin{aligned}
    \label{equ: final error bound of term (A) in Theorem 2}
        (A) &= \order\Bigg(\frac{(1+\sigma_{\max}^8) (1 + 3/a) \left((1+L_s)^2 \left(\log \frac{1}{\epsilon} + k\right)^2 + d + \log \frac{n}{\delta} \right)}{n t_0 (T - t_0)} \\
        &\qquad \qquad \qquad \cdot \log \frac{\mathfrak{N}\left( \frac{1}{n t_0 \left( \rho + K + \sqrt{d}(\sqrt{T} - \sqrt{t_0}) \right)}, \calS_{\textrm{NN}},\|\cdot\|_{2}\right)}{\delta} + \frac{1}{n t_0 (T - t_0)} \Bigg) \\
        & \stackrel{(i)}{=} \order\Bigg(\frac{(1+\sigma_{\max}^8) (1 + 3/a) \left((L_s+1)^2 (\log \frac{1}{\epsilon} + k)^2 + d + \log \frac{n}{\delta} \right)}{n t_0 (T - t_0)} \\
        &\qquad \cdot \bigg( dk + T \tau(1+L_s)^k (1+\sigma_{\max}^k) \epsilon^{-(k+1)} \big(\log \frac{1}{\epsilon}+ k \big)^{\frac{k+4}{2}} \bigg) \log \frac{T \tau d k}{t_0 \iota \epsilon} + \frac{1}{n t_0 (T - t_0)} \Bigg),
    \end{aligned}
    \end{equation}
    where $(i)$ follows from applying the upper bound \eqref{equ: covering number of SNN} for the covering number of $\calS_{\textrm{NN}}$ in Lemma~\ref{lem: SNN covering number}.
    \item For term $(B)$, by plugging the order of $\rho$ and $K$, defined in \eqref{equ: choice of rho and tau} and \eqref{equ: order of parameters in Theorem 1}, into \eqref{equ: error bound of term (B) in Theorem 2} and by straightforward calculations, we have
    \begin{equation}
    \label{equ: final error bound of term (B) in Theorem 2}
        (B) = \order \bigg( \frac{1}{nt_0(T-t_0)} \bigg).
    \end{equation}
    \item For term $(C)$, applying the fact that $q \leq \frac{\delta}{n}$ and the order of $\rho$ and $K$ in \eqref{equ: choice of rho and tau} and \eqref{equ: order of parameters in Theorem 1} to \eqref{equ: error bound of term (C) in Theorem 2}, with probability $1 - 2\delta$, it holds
    \begin{equation}
    \begin{aligned}
    \label{equ: final error bound of term (C) in Theorem 2}
        (C) &= \order\left(\frac{(1+\sigma_{\max}^8) (1 + 6/a) \left((1+L_s)^2 \left(\log \frac{1}{\epsilon} + k\right)^2 + d + \log \frac{n}{\delta} \right)}{n t_0 (T - t_0)} \log \frac{1}{\delta} \right. \\
        &\qquad \qquad \qquad \left. + \frac{1}{n t_0 (T - t_0)} + \frac{k \epsilon^2}{\min \{ \sigma_d^4, 1 \}}\right) + (1+a) \cdot (E).
    \end{aligned}
    \end{equation}
\end{enumerate}
Summing up the error terms in \eqref{equ: final error bound of term (A) in Theorem 2}-\eqref{equ: final error bound of term (C) in Theorem 2}, we derive that with probability $1 - 3\delta$, it holds that
\begin{align*}
\calL\left(\widehat{\mathbf s}_{\bm\theta}\right) & \leq  (A) + (B) + (1+a) \cdot(C) \\
& =  \order\Bigg(\frac{(1+\sigma_{\max}^8) (1 + 6/a) \left((1+L_s)^2 (\log \frac{1}{\epsilon} + k\right)^2 + d + \log \frac{n}{\delta} )}{n t_0 (T - t_0)} \\
& \qquad \cdot \bigg( dk + T \tau(1+L_s)^k (1+\sigma_{\max}^k) \epsilon^{-(k+1)} \bigg(\log \frac{1}{\epsilon}+ k \bigg)^{\frac{k+4}{2}} \bigg) \log \frac{T \tau d k}{t_0 \iota \epsilon} \Bigg) \\
& \qquad \qquad + \order \Bigg( \frac{1}{n t_0 (T - t_0)} + \frac{k \epsilon^2}{t_0 (T - t_0)} \Bigg) + (1+a)^2 \cdot (E).
\end{align*}
By the definition of $(E)$ in \eqref{equ: definition of (E)} and setting $a=\epsilon^2$, with probability $1 - 3\delta$, it holds that
\begin{equation*}
\begin{aligned}
    &\quad \frac{1}{T-t_0} \int_{t_0}^{T}\E_{\mathbf R_t \sim P_t}\left\|\overline{\mathbf s}_{\bm\theta}(\mathbf R_t, t)-\nabla \log p_{t}(\mathbf R_t)\right\|_{2}^{2} \dd t \\
    & =  \order\Bigg(\frac{(1+\sigma_{\max}^8) \left((1+L_s)^2 (\log \frac{1}{\epsilon} + k\right)^2 + d + \log \frac{n}{\delta} )}{\epsilon^2 n t_0 (T - t_0)} \\
    & \qquad \cdot \bigg( dk + T \tau(1+L_s)^k (1+\sigma_{\max}^k) \epsilon^{-(k+1)} \bigg(\log \frac{1}{\epsilon}+ k \bigg)^{\frac{k+4}{2}} \bigg) \log \frac{T \tau d k}{t_0 \iota \epsilon} \Bigg) \\
    & \qquad \qquad + \order \Bigg( \frac{1}{n t_0 (T - t_0)} + \frac{k \epsilon^2}{t_0 (T - t_0)} \Bigg) \\
    & =: (E_1) + (E_2).
\end{aligned}
\end{equation*}

\vspace{5pt}
\noindent \underline{\bf Step 6: Balancing Error Terms.} 
Take $\delta = 1/(3n)$ such that with probability $1-1/n$, it holds that
\begin{equation}
\begin{aligned}
    (E_1) &= \order\bigg( \frac{(1+\sigma_{\max}^{k+8}) (1+L_s)^{k} (d^2\log d) (k^{\frac{k+7}{2}} \log k) (\tau \log \tau) T \epsilon^{-(k+3)} \log^{\frac{k+7}{2}} (\frac{1}{\epsilon}) \log^3 n}{n t_0} \bigg) \nonumber \\
    & \stackrel{(i)}{=} \order\bigg( \frac{(1+\sigma_{\max}^{2k}) (1+L_s)^{k} (d^{\frac{7}{2}}\log d) (k^{\frac{k+10}{2}} \log^{\frac{5}{2}} k) \epsilon^{-(k+3)} \log^{\frac{k+10}{2}} (\frac{1}{\epsilon}) \log^{\frac{9}{2}} n}{n t_0} \bigg) \\
    & \stackrel{(ii)}{=} \Tilde{\order} \bigg( \frac{1}{n}\epsilon^{-(k+3)}\log^{\frac{k+10}{2}} (\frac{1}{\epsilon}) \bigg)
\end{aligned}
\end{equation}
and
\begin{equation}
    (E_2) = \Tilde{\order}\bigg( \frac{1}{n} + \epsilon^2 \bigg).
\end{equation}
Here $(i)$ follows from invoking the upper bound of $\tau(S)$ in \eqref{equ: upper bound of tauS in Theorem 1} and $\Tilde{\order}(\cdot)$ in $(i)$ holds by keeping terms only on the sample size $n$ and the error term $\epsilon$. 


To balance two error terms $(E_1)$ and $(E_2)$, we choose $\epsilon$ as the following
\begin{equation}
\label{equ: choice of epsilon and delta(n)}
\epsilon = n^{-\frac{1-\delta(n)}{k+5}} \textrm{ with } \delta(n) = \frac{(k+10)\log \log n}{2 \log n}.
\end{equation}
Consequently, we obtain
\begin{equation*}
\begin{aligned}
    \frac{1}{n} \epsilon^{-(k+3)} \log^{\frac{k+10}{2}} (1/\epsilon) &= n^{-1+\frac{(k+3)(1 - \delta(n))}{k+5}} (1/\epsilon)^{\frac{(k+10)\log \log (1/\epsilon)}{2\log (1/\epsilon)}} \\
    &= n^{-\frac{2-2\delta(n)}{k+5}} \cdot n^{-1 + \big(1 + \frac{(k+10)\log \log (1/\epsilon)}{2(k+5)\log (1/\epsilon)}\big) \big(1 - \delta(n)\big)} \\
    &\stackrel{(i)}{=} \order \bigg( n^{-\frac{2-2\delta(n)}{k+5}} \bigg) = \epsilon^2,
\end{aligned}
\end{equation*}
where $(i)$ holds by the formula of $\delta(n)$ in \eqref{equ: choice of epsilon and delta(n)}. By straightforward calculations, we deduce that, with probability $1-\frac{1}{n}$, it holds
\begin{equation*}
\begin{aligned}
    &\quad \frac{1}{T-t_0} \int_{t_0}^{T}\E_{\mathbf R_t \sim P_t}\left\|\overline{\mathbf s}_{\bm\theta}(\mathbf R_t, t)-\nabla \log p_{t}(\mathbf R_t)\right\|_{2}^{2} \dd t \\
    & = \order\bigg(\frac{1}{t_0}(1+\sigma_{\max}^{2k})(1+L_s)^{k} d^2 k^{\frac{k+10}{2}}\left(\sqrt{d} n^{-\frac{2-2 \delta(n)}{k+5}}+ n^{-\frac{k+3+2 \delta(n)}{k+5}}\right) \log d \log^4 n\bigg) \\
    & = \Tilde{\order}\bigg( \frac{1}{t_0}(1 + \sigma_{\max}^{2k}) d^{\frac{5}{2}} k^{\frac{k+10}{2}} n^{-\frac{2-2 \delta(n)}{k+5}} \log^4 n \bigg),
\end{aligned}
\end{equation*}
where the last equality follows from omitting terms associated with $L_s$ and polynomial terms in $\log t_0$, $\log d$, and $\log k$. \hfill\Halmos
\end{proof}
\fi


\subsection{Supporting Lemmas and Proofs}


\begin{lemma}
\label{lem: lipschitz constant bound in Theorem 1}

Under the same assumptions as in Theorem \ref{theorem: score approximation}, it holds that
\begin{equation}
\label{equ: upper bound of tauS}
    \tau(S) = \order\bigg(L_s \operatorname{poly} (1+\sigma_{\max}^2) \operatorname{poly} (\sqrt{k} S) \bigg),
\end{equation}
where $\tau(S)$ is defined in \eqref{equ: definition of tauS} and $\operatorname{poly}(\cdot)$ represents a cubic polynomial.
\end{lemma}

\begin{proof}{Proof of Lemma~\ref{lem: lipschitz constant bound in Theorem 1}.}

Recall that $\tau(S)$ is associated with $\bm\xi(\mathbf z, t)$, which is defined in \eqref{equ: definition of xi}.
By direct calculation, we have
\begin{align}
    \frac{\partial \bm\xi}{\partial t} &= - \frac{1}{2} \frac{\int \mathbf f \frac{\partial \| \bm\Gamma_t^{-\frac{1}{2}} (\mathbf z - \alpha_t \mathbf f) \|_2^2}{\partial t} \phi(\mathbf z ; \alpha_t \mathbf f, \bm\Gamma_t) p_{\textrm{fac}}(\mathbf f) \, \dd \mathbf f}{\int \phi(\mathbf z ; \alpha_t \mathbf f, \bm\Gamma_t) p_{\textrm{fac}}(\mathbf f) \, \dd \mathbf f}
    + \frac{1}{2} \bm\xi \frac{\int \frac{\partial \| \bm\Gamma_t^{-\frac{1}{2}} (\mathbf z - \alpha_t \mathbf f) \|_2^2}{\partial t} \phi(\mathbf z ; \alpha_t \mathbf f, \bm\Gamma_t) p_{\textrm{fac}}(\mathbf f) \, \dd \mathbf f}{\int \phi(\mathbf z ; \alpha_t \mathbf f, \bm\Gamma_t) p_{\textrm{fac}}(\mathbf f) \, \dd \mathbf f} \nonumber \\
    &\stackrel{(i)}{=} \frac{\alpha_t^2}{2} \E[\mathbf F \mathbf F^\top \bm\beta^\top \bm\Lambda_t^{-2} \bm\beta \mathbf F | \mathbf Z = \mathbf z] + \frac{\alpha_t}{2} \operatorname{Cov}[\mathbf F | \mathbf Z = \mathbf z] \mathbf C_t \mathbf z + \frac{\alpha_t^2}{2} \E[\mathbf F| \mathbf Z = \mathbf z]\E[\mathbf F^\top \bm\beta^\top \bm\Lambda_t^{-2} \bm\beta \mathbf F | \mathbf Z = \mathbf z], \label{equ: partial xi partial t}
\end{align}
where $(i)$ follows from plugging in 
\begin{align*}
\frac{\partial \| \bm\Gamma_t^{-\frac{1}{2}} (\mathbf z - \alpha_t \mathbf f) \|_2^2}{\partial t} &= - \alpha_t^2 \mathbf f^\top \bm\beta^\top \bm\Lambda_t^{-2} \bm\beta \mathbf f + \alpha_t \mathbf f^\top \mathbf C_t \mathbf z + \mathbf z^\top \bm\beta^\top (\bm\Lambda_t^{-1} - \bm\Lambda_t^{-2}) \bm\beta \mathbf z
\end{align*}
with $\mathbf C_t = \bm\beta^\top (2\bm\Lambda_t^{-2} - \bm\Lambda_t^{-1}) \bm\beta$ and re-arranging terms. To bound $\|\partial \bm\xi/\partial t \|_2$, we provide the following two upper bounds.


\paragraph{Conditional Third Moment Bound.} By Cauchy-Schwarz inequality, we have
\begin{align}
    \left\| \E[\mathbf F \mathbf F^\top \bm\beta^\top\bm\Lambda_t^{-2}\bm\beta \mathbf F |\mathbf Z = \mathbf z] \right\|_2 &\leq \sqrt{\E[\| \mathbf F \|_2^2 |\mathbf Z = \mathbf z] \cdot \E [\| \mathbf F^\top \bm\beta^\top\bm\Lambda_t^{-2}\bm\beta \mathbf F \|_2^2 |\mathbf Z = \mathbf z]} \nonumber \\
    &\leq \frac{1}{h_t + \sigma_d^2 \alpha_t^2} \sqrt{\E[\| \mathbf F \|_2^2 |\mathbf Z = \mathbf z] \cdot \E [\| \mathbf F \|_2^4 |\mathbf Z = \mathbf z]}, \label{equ: conditional third moment bounds}
\end{align}
where the second inequality holds due to $\bm\beta^\top \bm\beta = \mathbf I_k$ and $\| \bm\Lambda_t^{-2} \|_{\rm{op}} \leq 1 / (h_t + \sigma_d^2 \alpha_t^2)$.

\paragraph{Conditional Covariance Bound.} 
Recall $\mathbf s_{\textrm{sub}}$ defined in \eqref{equ: s_parallel}. Taking the derivative of $\mathbf s_{\textrm{sub}}$ with respect to $\mathbf z$, we have
\begin{align}
    \frac{\partial \mathbf{s}_{\textrm{sub}}\left(\mathbf z, t\right)}{\partial \mathbf z} & = -\bm\Lambda_t^{-1} \bm\beta + \alpha_t^2 \bm\Lambda_t^{-1} \bm\beta \frac{\int \mathbf f \mathbf f^\top \bm\Gamma_t^{-1} \phi(\mathbf z ; \alpha_t \mathbf f, \bm\Gamma_t) p_{\textrm{fac}}(\mathbf f) \dd \mathbf f}{\int \phi(\mathbf z ; \alpha_t \mathbf f, \bm\Gamma_t) p_{\textrm{fac}}(\mathbf f) \dd \mathbf f} \nonumber \\
    &\quad - \alpha_t^2 \bm\Lambda_t^{-1} \bm\beta \frac{\int \mathbf f \phi(\mathbf z ; \alpha_t \mathbf f, \bm\Gamma_t) p_{\textrm{fac}}(\mathbf f) \dd \mathbf f}{\int \phi(\mathbf z ; \alpha_t \mathbf f, \bm\Gamma_t) p_{\textrm{fac}}(\mathbf f) \dd \mathbf f} \frac{\int \mathbf f^\top \bm\Gamma_t^{-1} \phi(\mathbf z ; \alpha_t \mathbf f, \bm\Gamma_t) p_{\textrm{fac}}(\mathbf f) \dd \mathbf f}{\int \phi(\mathbf z ; \alpha_t \mathbf f, \bm\Gamma_t) p_{\textrm{fac}}(\mathbf f) \dd \mathbf f} \nonumber \\
    & = \alpha_t^2 \bm\Lambda_t^{-1} \bm\beta \left[\operatorname{Cov}\left(\mathbf F |\mathbf Z = \mathbf z \right)\bm\Gamma_t^{-1} - \frac{1}{\alpha_t^2} \mathbf I_k\right]. \label{equ: equation s_parallel and Cov(F|Z=z)}
\end{align}
Since $\mathbf s_{\textrm{sub}}$ is $L_s$-Lipschitz by Assumption \ref{assumption: Lipschitz}, we deduce from \eqref{equ: equation s_parallel and Cov(F|Z=z)} that for any $t \in (0, T]$, it holds
$$
\left\|\operatorname{Cov}\left(\mathbf F | \mathbf Z = \mathbf z \right)\right\|_{\textrm{op}} \leq \frac{(h_t+\sigma_{\max}^2\alpha_t^2)(1+L_s(h_t+\sigma_{\max}^2\alpha_t^2))}{\alpha_t^2} \leq (1+\sigma_{\max}^4) (1+L_s),
$$
where the second inequality follows from taking $t = 0$.

Furthermore, as 
$$
\|\mathbf C_t\|_{\rm{op}} = \|\bm\beta^\top (2\bm\Lambda_t^{-2} - \bm\Lambda_t^{-1}) \bm\beta\|_{\rm{op}} \leq \| 2\bm\Lambda_t^{-2} - \bm\Lambda_t^{-1} \|_{\rm{op}} \leq \frac{3}{(h_t + \sigma_d^2 \alpha_t^2)^2},
$$ it holds that
\begin{align}
\label{equ: conditional covariance bounds}
    \left\| \operatorname{Cov}[\mathbf F |\mathbf Z = \mathbf z] \mathbf C_t \mathbf z \right\|_{2} &\leq \frac{3}{(h_t + \sigma_d^2 \alpha_t^2)^2} \left\| \operatorname{Cov}[\mathbf F |\mathbf Z = \mathbf z] \right\|_{\rm{op}} \| \mathbf z \|_2 \\
    &\leq \frac{3(1+\sigma_{\max}^4) (1+L_s)}{(h_t + \sigma_d^2 \alpha_t^2)^2} \| \mathbf z \|_2.
\end{align}

By substituting the conditional third moment bound in \eqref{equ: conditional third moment bounds} and covariance bound in \eqref{equ: conditional covariance bounds} into \eqref{equ: partial xi partial t}, and using the fact that $\mathbf F, \mathbf Z$ have the sub-Gaussian tails in the compact domain $\calS$, we conclude that
\begin{align*}
    \tau(S) = \order\bigg(L_s (1+\sigma_{\max}^4) \operatorname{poly} (\sqrt{k} S) \bigg).
\end{align*}
where $\operatorname{poly}(\cdot)$ represents a cubic polynomial. \hfill\Halmos

\end{proof}



\begin{lemma}
\label{lem: truncation error -- heterogeneous}
Suppose Assumption \ref{assumption: subgaussian} holds. Let $\bm\xi$ be defined in \eqref{equ: definition of xi} and $\mathbf Z = \bm\beta^\top \bm\Lambda_t^{-1} \mathbf R$ with distribution $P_t^{\rm fac}$. Given $\epsilon > 0$, with $S = c\left(\sqrt{(1+\sigma_{\max}^2) (k + \log (1/\epsilon))} \right)$
for some constant $c > 0$, it holds that
\begin{equation}
\label{equ: truncation error -- heterogeneous}
\left\| \bm\xi\left(\mathbf Z, t\right) \indicator \{\|\mathbf Z\|_2 > S\} \right\|_{L^2 \left(P_{t}^{\rm fac}\right)} \leq \epsilon, \quad \forall t \in (0, T].
\end{equation}
\end{lemma}

\begin{proof}{Proof of Lemma~\ref{lem: truncation error -- heterogeneous}.}

Plugging in the expression of $\bm\xi$ in \eqref{equ: definition of xi}, we obtain that
\begin{align*}
&\quad \int \left\|\int \frac{\mathbf f \phi (\bm\Gamma_t \bm\beta^\top \bm\Lambda_t^{-1} \mathbf r ; \alpha_t \mathbf f, \bm\Gamma_t )  p_{\textrm{fac}}(\mathbf f) \dd \mathbf f}{\int \phi (\bm\Gamma_t \bm\beta^\top \bm\Lambda_t^{-1} \mathbf r ; \alpha_t \mathbf f, \bm\Gamma_t ) p_{\textrm{fac}}(\mathbf f) \dd \mathbf f}\right\|_2^2 \indicator \{\|\bm\beta^\top \bm\Lambda_t^{-1} \mathbf r\|_2 > S\} p_t(\mathbf r) \dd \mathbf r \\
& \stackrel{(i)}{\leq} \int_{\|\bm\beta^\top \bm\Lambda_t^{-1} \mathbf r\|_2 > S} \|\mathbf f\|_2^2 \frac{\phi (\bm\Gamma_t \bm\beta^\top \bm\Lambda_t^{-1} \mathbf r ; \alpha_t \mathbf f, \bm\Gamma_t )  p_{\textrm{fac}}(\mathbf f) \dd \mathbf f}{\int \phi (\bm\Gamma_t \bm\beta^\top \bm\Lambda_t^{-1} \mathbf r ; \alpha_t \mathbf f, \bm\Gamma_t )  p_{\textrm{fac}}(\mathbf f) \dd \mathbf f} p_t(\mathbf r) \dd \mathbf r \\
& \stackrel{(ii)}{\leq} \int \int_{\|\bm\beta^\top \bm\Lambda_t^{-1} \mathbf r\|_2 > S} \|\mathbf f\|_2^2 \phi (\mathbf T_t \bm\Lambda_t^{-\frac{1}{2}} \mathbf r ; \alpha_t \bm\Lambda_t^{-\frac{1}{2}} \bm\beta \mathbf f, \mathbf I )  \phi ((\mathbf I - \mathbf T_t)\bm\Lambda_t^{-\frac{1}{2}} \mathbf r ; \mathbf 0, \mathbf I )  p_{\textrm{fac}}(\mathbf f) \dd \mathbf r \dd \mathbf f \\
& = \underbrace{\int_{\|\bm\beta^\top \bm\Lambda_t^{-1} \mathbf r\|_2 > S} \int_{\|\bm\Lambda_t^{-\frac{1}{2}} \bm\beta \mathbf f\|_2 \leq \frac{1}{2}\|\mathbf T_t \bm\Lambda_t^{-\frac{1}{2}} \mathbf r\|_2} \|\mathbf f\|_2^2 \phi (\mathbf T_t \bm\Lambda_t^{-\frac{1}{2}} \mathbf r ; \alpha_t \bm\Lambda_t^{-\frac{1}{2}} \bm\beta \mathbf f, \mathbf I ) p_{\textrm{fac}}(\mathbf f) \dd \mathbf f \dd (\mathbf T_t \bm\Lambda_t^{-\frac{1}{2}} \mathbf r)}_{(A)} \\
&\quad + \underbrace{\int_{\|\bm\beta^\top \bm\Lambda_t^{-1} \mathbf r\|_2 > S} \int_{\|\bm\Lambda_t^{-\frac{1}{2}} \bm\beta \mathbf f\|_2 > \frac{1}{2}\|\mathbf T_t \bm\Lambda_t^{-\frac{1}{2}} \mathbf r\|_2} \|\mathbf f\|_2^2 \phi(\mathbf T_t \bm\Lambda_t^{-\frac{1}{2}} \mathbf r ; \alpha_t \bm\Lambda_t^{-\frac{1}{2}} \bm\beta \mathbf f, \mathbf I ) p_{\textrm{fac}}(\mathbf f) \dd \mathbf f \dd (\mathbf T_t \bm\Lambda_t^{-\frac{1}{2}} \mathbf r)}_{(B)},
\end{align*}
where $(i)$ holds due to the Cauchy-Schwarz inequality, $(ii)$ invokes the expression of $p_t(\mathbf r)$ in \eqref{equ: density of r}  and re-arranging terms, and the last equality holds by straightforward calculations.



\paragraph{Bounding Term $(A)$.} We define the change of variable $\mathbf X := \mathbf T_t \bm\Lambda_t^{-\frac{1}{2}} \mathbf R_t$ and denote by $\mathbf x$ a realization of $\mathbf X$.  By the Cauchy-Schwarz inequality and $\|\bm\Lambda_t^{-\frac{1}{2}} \bm\beta \mathbf f\|_2 \leq \frac{1}{2}\|\mathbf T_t \bm\Lambda_t^{-\frac{1}{2}} \mathbf r\|_2$, we have
$$
\|\mathbf x - \alpha_t \bm\Lambda_t^{-\frac{1}{2}} \bm\beta \mathbf f\|_2^2 \geq \frac{1}{2}\|\mathbf x\|_2^2 - \alpha^2_t \|\bm\Lambda_t^{-\frac{1}{2}} \bm\beta \mathbf f\|_2^2 \geq \frac{1}{4}\|\mathbf x\|_2^2.
$$
As a result, we can deduce that
\begin{align}
    (A) & \leq \int_{\|\bm\beta^\top \bm\Lambda_t^{-\frac{1}{2}} \mathbf x\|_2 > S} \int_{\|\bm\Lambda_t^{-\frac{1}{2}} \bm\beta \mathbf f\|_2 \leq \frac{1}{2}\|\mathbf x\|_2} \| \mathbf f\|_2^2 (2 \pi)^{-\frac{k}{2}} \exp \left(-\frac{\| \mathbf x\|_2^2}{8}\right) p_{\textrm{fac}}(\mathbf f) \dd \mathbf f \dd \mathbf x \nonumber \\
    & \leq \E\left[\|\mathbf f\|_2^2\right] \cdot \int_{\|\bm\beta^\top \bm\Lambda_t^{-\frac{1}{2}} \mathbf x\|_2 > S} (2 \pi)^{-\frac{k}{2}} \exp \left(-\frac{\| \mathbf x\|_2^2}{8}\right) \dd \mathbf x \nonumber \\
    & \stackrel{(i)}{\leq} \E\left[\|\mathbf f\|_2^2\right] \cdot \int_{\left\|\mathbf x\right\|_2 > (h_t + \sigma_d^2 \alpha_t^2)^{\frac{1}{2}} S} (2 \pi)^{-\frac{k}{2}} \exp \left(-\frac{\| \mathbf x\|_2^2}{8}\right) \dd \mathbf x \nonumber \\
    & \stackrel{(ii)}{\leq} \E\left[\|\mathbf f\|_2^2\right] \cdot \frac{2^{-\frac{k}{2} + 2} k S^{k-2} (h_t + \sigma_d^2 \alpha_t^2)^{(k-2)/2}}{(\frac{1}{2}-\eta) \Gamma(\frac{k}{2} + 1) } \exp \left(-\frac{(h_t + \sigma_d^2 \alpha_t^2) S^2}{8}\right). \label{equ: bound (A) in truncation error}
\end{align}
where $(i)$ holds due to $\| \bm\beta^\top \bm\Lambda_t^{-\frac{1}{2}} \|_{\textrm{{op}}} \leq (h_t + \sigma_d^2 \alpha_t^2)^{-\frac{1}{2}}$, and $(ii)$ follows from the sub-Gaussian tail in Lemma 16 of \citet{chen2023score}.

\paragraph{Bounding Term $(B)$.} We define the change of variable $\mathbf Y := \bm\beta^\top \bm\Lambda_t^{-1} \mathbf R_t$ and denote by $\mathbf y$ the realization of $\mathbf Y$. Given $S > \min\{B/2, 1\}$, applying the sub-Gaussian tail of $p_{\textrm{fac}}(\mathbf f)$ in \eqref{eqn:subgaussian}, we obtain that
\begin{align}
(B) & \leq \int_{\left\|\mathbf y\right\|_2 > S} \int_{\|\bm\Lambda_t^{-\frac{1}{2}} \bm\beta \mathbf f\|_2 > \frac{1}{2}\|\bm\Lambda_t^{-\frac{1}{2}} \bm\beta \bm\Gamma_t \mathbf y\|_2} \phi(\bm\Lambda_t^{-\frac{1}{2}} \bm\beta \bm\Gamma_t \mathbf y; \alpha_t \bm\Lambda_t^{-\frac{1}{2}} \bm\beta \mathbf f, \mathbf I) \cdot \frac{C_1}{(2 \pi)^{\frac{k}{2}}} \|\mathbf f\|_2^2 \exp \left(-\frac{C_{2}\|\mathbf f\|_2^2}{2}\right) \dd \mathbf f \dd \mathbf y \nonumber \\
& \stackrel{(i)}{\leq} \frac{C_1}{(2 \pi)^{k}} \int_{\left\|\mathbf y\right\|_2 > S} \int_{\|\bm\Lambda_t^{-\frac{1}{2}} \bm\beta \mathbf f\|_2 > \frac{1}{2}\|\bm\Lambda_t^{-\frac{1}{2}} \bm\beta \bm\Gamma_t \mathbf y\|_2} \exp \Bigg( - \frac{C_{2}\big\| (\alpha_t^2 \mathbf I_k + C_{2} \bm\Gamma_t)^{-\frac{1}{2}} \bm\Gamma_t \mathbf y \big\|_2^2}{2} \Bigg) \nonumber \\
&\qquad \cdot \|\mathbf f\|_2^2 \exp \Bigg( - \frac{\big\| (\alpha_t^2 \bm\Gamma_t^{-1} + C_{2} \mathbf I_k)^{\frac{1}{2}} \left( \mathbf f - \alpha_t (\alpha_t^2 \bm\Gamma_t^{-1} + C_{2} \mathbf I_k)^{-1} \mathbf y \right) \big\|_2^2}{2} \Bigg) \dd \mathbf f \dd \mathbf y \nonumber \\
& \stackrel{(ii)}{\leq} \frac{C_1}{(2 \pi)^{k}} \int_{\left\|\mathbf y\right\|_2 > S} \int_{\|\bm\Lambda_t^{-\frac{1}{2}} \bm\beta \mathbf f\|_2 > \frac{1}{2}\|\bm\Lambda_t^{-\frac{1}{2}} \bm\beta \bm\Gamma_t \mathbf y\|_2} \exp \Bigg( - \frac{C_{2}\big\| (\alpha_t^2 \mathbf I_k + C_{2} \bm\Gamma_t)^{-\frac{1}{2}} \bm\Gamma_t \mathbf y \big\|_2^2}{2} \Bigg) \nonumber \\
&\qquad \cdot \|\mathbf f\|_2^2 \exp \left( - \frac{C_{2}\left\| \mathbf f - \alpha_t (\alpha_t^2 \bm\Gamma_t^{-1} + C_{2} \mathbf I_k)^{-1} \mathbf y \right\|_2^2}{2} \right) \dd \mathbf f \dd \mathbf y, \label{equ: temp_bound (B) in truncation error}
\end{align}
where $(i)$ invokes the formula of $\phi(\mathbf y; \alpha_t \mathbf f, \bm\Gamma_t)$ in \eqref{equ: score decomposition -- heterogeneous} and completing the square for $\mathbf f$, $(ii)$ follows from $\|\alpha_t^2 \bm\Gamma_t^{-1} + C_{2} \mathbf I_k \|_{\textrm{op}} \geq C_2$.

Furthermore, applying $\E[\|\mathbf f\|_2^2] \leq \alpha_t^2 \| (\alpha_t^2 \bm\Gamma_t^{-1} + C_{2} \mathbf I_k)^{-\frac{1}{2}} \mathbf y \|_2^2 + k$ to \eqref{equ: temp_bound (B) in truncation error}, we deduce that
\begin{align}
(B) & \leq \frac{C_1}{C_2^{\frac{k}{2}} (2 \pi)^{k} } \int_{\left\|\mathbf y\right\|_2 > S}\left[ \alpha_t^2 \| (\alpha_t^2 \bm\Gamma_t^{-1} + C_{2} \mathbf I_k)^{-1} \mathbf y \|_2^2 + k \right] \cdot \exp \Bigg( - \frac{C_{2}\big\| (\alpha_t^2 \mathbf I_k + C_{2} \bm\Gamma_t)^{-\frac{1}{2}} \bm\Gamma_t \mathbf y \big\|_2^2}{2} \Bigg) \dd \mathbf y \nonumber \\
& \leq \frac{C_1 2^{-\frac{k}{2} + 2} k S^k}{C_2 \Gamma(\frac{k}{2} + 1) (\alpha_t^2 + C_2(h_t + \sigma_{\max}^2 \alpha_t^2))} \exp \left(-\frac{ (\alpha_t^2 + C_2(h_t + \sigma_{\max}^2 \alpha_t^2)) C_2 S^2}{2} \right), \label{equ: bound (B) in truncation error}
\end{align}
where the last inequality is due to $\| \bm\Gamma_t \|_{\textrm{op}} \geq h_t + \sigma_d^2 \alpha_t^2$, $\|(\alpha_t^2 \mathbf I_k + C_2 \bm\Gamma_t)^{-\frac{1}{2}} \|_{\textrm{op}} \geq \sqrt{\alpha_t^2 + C_2(h_t + \sigma_{\max}^2 \alpha_t^2)}$ and the sub-Gaussian tail in Lemma 16 of \citet{chen2023score} and similar operator norm bounds in $(ii)$.

Combining the error bounds \eqref{equ: bound (A) in truncation error} and \eqref{equ: bound (B) in truncation error} for $(A)$ and $(B)$, we conclude that
\begin{align}
\left\| \bm\xi\left(\mathbf Z, t\right) \indicator \{\|\mathbf Z\|_2 > S\} \right\|_{L^2 \left(P_{t}^{\rm fac}\right)} \leq & c^{\prime} \frac{2^{-\frac{k}{2} + 3} k (h_t + \sigma_d^2 \alpha_t^2)^{\frac{k}{2}} S^k}{\Gamma(\frac{k}{2} + 1) (\alpha_t^2 + C_2(h_t + \sigma_{\max}^2 \alpha_t^2))} \exp \left(-\frac{(h_t + \sigma_d^2 \alpha_t^2) S^2}{8} \right) \label{equ: final truncation error}
\end{align}
for some constant $c^{\prime} > 0$. Given any $\epsilon > 0$, by the upper bound of truncation error in \eqref{equ: final truncation error}, we can choose
$$
S = c\left(\sqrt{\bigg(1+\sigma_{\max}^2\bigg) \bigg(k + \log \frac{1}{\epsilon}\bigg)} \right),
$$
such that $\left\| \bm\xi\left(\mathbf Z, t\right) \indicator \{\|\mathbf Z\|_2 > S\} \right\|_{L^2 \left(P_{t}^{\rm fac}\right)} \leq \epsilon$. Here, $c$ is an absolute constant. \hfill\Halmos
\end{proof}

\begin{lemma}
\label{lem: SNN truncation error -- heterogeneous}
Suppose Assumption \ref{assumption: subgaussian} holds. For any $\mathbf s_{\bm\theta_1}\left(\cdot, t\right)$ and $\mathbf s_{\bm\theta_2}\left(\cdot, t\right)$, when $\rho$ is sufficiently large, it holds that
\begin{align}
    &\quad \sup_{\|\mathbf r\|_{2} \leq \rho} \E_{\mathbf R_t | \mathbf R_0 = \mathbf r} \bigg[ \left(K + \left\| \mathbf R_t \right\|_2 + \left\| \mathbf r \right\|_2 \right) \left\|\mathbf s_{\bm\theta_1}\left(\mathbf R_t, t\right)-\mathbf s_{\bm\theta_2}\left(\mathbf R_t, t\right)\right\|_{2} \cdot \indicator\left\{\left\|\mathbf R_t\right\|_{2} > 3\rho + \sqrt{d \log d}\right\}\bigg] \nonumber \\
    & = \order \bigg(\rho K^2 h_t^{-2-\frac{d}{2}} \left(\frac{\rho}{d}\right)^{d} \exp \left(-\frac{\rho^2}{h_t} \right) \bigg).
    \label{equ: SNN truncation error}
\end{align}
\end{lemma}

\begin{proof}{Proof of Lemma~\ref{lem: SNN truncation error -- heterogeneous}.}
Denote $\mathbf D_{ti} = \operatorname{diag}\{ 1/(h_t + c_{i1} \alpha_t^2), \dots, 1/(h_t + c_{i1} \alpha_t^2) \}$ for $i =1, 2$. Applying the formula of $\mathbf s_{\bm\theta_1}$ and $\mathbf s_{\bm\theta_2}$ in \eqref{equ: score network}, we calculate
\begin{align}
&\quad \E_{\mathbf R_t | \mathbf R_0 = \mathbf r} \bigg[ \left(K + \left\| \mathbf R_t \right\|_2 + \left\| \mathbf r \right\|_2 \right) \left\|\mathbf s_{\bm\theta_1}\left(\mathbf R_t, t\right)-\mathbf s_{\bm\theta_2}\left(\mathbf R_t, t\right)\right\|_{2} \cdot \indicator\left\{\left\|\mathbf R_t\right\|_{2} > 3\rho + \sqrt{d \log d}\right\}\bigg] \nonumber \\
&\stackrel{(i)}{\leq} \displaystyle\int \bigg(K + \left\| \mathbf r^{\prime} \right\|_2 + \left\| \mathbf r \right\|_2 \bigg) \bigg(\| (\mathbf D_{t1} - \mathbf D_{t2}) \mathbf r^{\prime} \|_2 + \|\alpha_t(\mathbf D_{t1} \mathbf V_1 - \mathbf D_{t2} \mathbf V_2) \mathbf g_{\bm\zeta_1}(\mathbf V_1^\top \mathbf D_{t1} \mathbf r^{\prime}, t) \|_2 \nonumber \\
&\quad + \|\alpha_t\mathbf D_{t2} \mathbf V_2 (\mathbf g_{\bm\zeta_1}(\mathbf V_1^\top \mathbf D_{t1} \mathbf r^{\prime}, t) - \mathbf g_{\bm\zeta_2}(\mathbf V_2^\top \mathbf D_{t2} \mathbf r^{\prime}, t))\|_2 \bigg) \cdot \indicator\left\{\left\|\mathbf r^{\prime}\right\|_{2}>3\rho + \sqrt{d \log d}\right\} \phi(\mathbf r^{\prime} ; \alpha_t \mathbf r, h_t \mathbf I) \dd \mathbf r^{\prime} \nonumber \\
& \stackrel{(ii)}{=} \order \bigg( \displaystyle\int_{\| \mathbf r^{\prime} \|_2 > 3\rho + \sqrt{d \log d}} \frac{(K + \left\| \mathbf r^{\prime} \right\|_2 + \left\| \mathbf r \right\|_2)(K + \left\| \mathbf r^{\prime} \right\|_2)}{h_t^2 (2 \pi h_t)^{\frac{d}{2}}} \exp \left(-\frac{1}{2 h_t}\left(\frac{1}{2}\left\|\mathbf r^{\prime}\right\|_2^2-\|\mathbf r\|_2^2\right)\right) \dd \mathbf r^{\prime} \bigg), \label{equ: upper bound of score tail estimation in Theorem 2}
\end{align}
where $(i)$ is due to Cauchy-Schwarz inequality; $(ii)$ follows from the upper bounds \eqref{equ: ReLU network} and \eqref{equ: score network} of $\{\mathbf g_{\bm\theta_i}, \mathbf V_{i}, \mathbf D_{ti}\}_{i=1,2}$, $\alpha_t^2 \leq 1$ and
$$
\phi(\mathbf r^{\prime} ; \alpha_t \mathbf r, h_t \mathbf I) \leq (2 \pi h_t)^{-\frac{d}{2}} \exp \left(-\frac{1}{2 h_t}\left(\frac{1}{2}\left\|\mathbf r^{\prime}\right\|_2^2-\|\mathbf r\|_2^2\right)\right).
$$
Then, substituting the upper bound for the tail estimation in Lemma 16 of \citet{chen2023score} into \eqref{equ: upper bound of score tail estimation in Theorem 2}, we deduce that
\begin{align}
\eqref{equ: upper bound of score tail estimation in Theorem 2} & = \order \bigg( \frac{(K^2 + K \|\mathbf r\|_2) (2 h_t)^{-2-\frac{d}{2}} (3\rho + \sqrt{d \log d})^{d-2}}{\Gamma(\frac{d}{2} + 1)} \exp \left( - \frac{(3\rho + \sqrt{d \log d})^2}{4 h_t} + \frac{\| \mathbf r \|_2^2}{2 h_t} \right) \bigg) \nonumber \\
&\qquad + \frac{(2K + \|\mathbf r\|_2)(2 h_t)^{-2-\frac{d}{2}} (3\rho + \sqrt{d \log d})^{d-1}}{\Gamma(\frac{d}{2} + 1)} \exp \left( - \frac{(3\rho + \sqrt{d \log d})^2}{4 h_t} + \frac{\| \mathbf r \|_2^2}{2 h_t} \right) \nonumber \\
&\qquad \qquad + \frac{(2 h_t)^{-2-\frac{d}{2}} (3\rho + \sqrt{d \log d})^{d}}{\Gamma(\frac{d}{2} + 1)} \exp \left( - \frac{(3\rho + \sqrt{d \log d})^2}{4 h_t} + \frac{\| \mathbf r \|_2^2}{2 h_t} \right) \nonumber \\
& = \order \left( K^2 \|\mathbf r\|_2 h_t^{-2-\frac{d}{2}} \left(\frac{\rho}{d}\right)^{d} \exp \left(-\frac{9 \rho^2 - 2\| \mathbf r \|_2^2}{4 h_t} \right) \right). \label{equ: upper bound 1 of score tail estimation in Theorem 2}
\end{align}
Here, the last inequality holds since $\Gamma(\frac{d}{2} + 1) = \order (\prod_{j=1}^{\frac{d}{2}} j)$ and
$$
\frac{2^{-\frac{d}{2}}(3 \rho + \sqrt{d \log d})^{d}\exp\left(-\frac{6\rho\sqrt{d \log d} + d \log d}{4 h_t}\right)}{\Gamma(\frac{d}{2} + 1)} = \order \bigg( \left(\frac{\rho}{d}\right)^{d} \bigg)
$$
for a sufficiently large $\rho > \max\{ B, d \}$.

Immediately, substituting $\|\mathbf r\|_2 \leq \rho$ into \eqref{equ: upper bound 1 of score tail estimation in Theorem 2}, we obtain the desired result.

\hfill\Halmos
\end{proof}


\begin{lemma}
\label{lem: SNN covering number}
For any given $\epsilon > 0$, $\delta > 0$, and $\rho = \order \left( \sqrt{\sigma_{\max}^2 \left(d + \log K + \log (n/\delta) \right) }\right)$ defined in \eqref{equ: choice of rho and tau}, the $\nu$-covering number of $\calS_{\rm NN}$ in \eqref{equ: score network} is
\begin{equation}
\begin{aligned}
\label{equ: covering number of SNN}
    \log \mathfrak{N}(\nu, \calS_{\textrm{NN}},\|\cdot\|_2) &= \bigg( \bigg( dk + T \tau(1+L_s)^k (1+\sigma_{\max}^k) \epsilon^{-(k+1)} \bigg(\log \frac{1}{\epsilon}+ k \bigg)^{\frac{k+4}{2}} \bigg) \log \frac{T \tau d k}{t_0 \nu \epsilon} \bigg).
\end{aligned}
\end{equation}
\end{lemma}

\begin{proof}{Proof of Lemma~\ref{lem: SNN covering number}.}
$\calS_{\textrm{NN}}$ consists of three components:
\begin{enumerate}
    \item A vector $\mathbf c = (c_1, c_2, \dots, c_d) \in [0, \sigma_{\max}]^d$ and its induced matrix 
    $$\mathbf D_t = \operatorname{diag}\{ 1/(h_t + \alpha_t^2 c_1), 1/(h_t + \alpha_t^2 c_2), \dots, 1/(h_t + \alpha_t^2 c_d) \}.$$
    \item A matrix $\mathbf V$ with orthonormal columns.
    \item A ReLU network $\mathbf g_{\bm\zeta}$.
\end{enumerate}
Denote $\mathbf D_{ti} = \operatorname{diag}\{ 1/(h_t + \alpha_t^2 c_{i1}), 1/(h_t + \alpha_t^2 c_{i2}), \dots, 1/(h_t + \alpha_t^2 c_{id}) \}$ for $i=1,2$. Directly incorporating the sub-additive property of $L^2$ norm and $\alpha_t^2 \leq 1$, we have
\begin{align}
& \quad \|\mathbf s_{\bm\theta_1}(\mathbf r, t) - \mathbf s_{\bm\theta_2}(\mathbf r, t)\|_2 \nonumber \\
& \leq \|(\mathbf D_{t1} \mathbf V_1 - \mathbf D_{t2} \mathbf V_1) \mathbf g_{\bm\zeta_1}(\mathbf V_1^\top \mathbf D_{t1} \mathbf r, t) \|_2 + \|(\mathbf D_{t2} \mathbf V_1 - \mathbf D_{t2} \mathbf V_2) \mathbf g_{\bm\zeta_1}(\mathbf V_1^\top \mathbf D_{t1} \mathbf r, t) \|_2 \nonumber \\
&\quad + \|\mathbf D_{t2} \mathbf V_2 (\mathbf g_{\bm\zeta_1}(\mathbf V_1^\top \mathbf D_{t1} \mathbf r, t) - \mathbf g_{\bm\zeta_2}(\mathbf V_1^\top \mathbf D_{t1} \mathbf r, t))\|_2 + \|\mathbf D_{t2} \mathbf V_2 (\mathbf g_{\bm\zeta_2}(\mathbf V_1^\top \mathbf D_{t1} \mathbf r, t) - \mathbf g_{\bm\zeta_2}(\mathbf V_2^\top \mathbf D_{t1} \mathbf r, t))\|_2 \nonumber \\
&\quad \quad + \|\mathbf D_{t2} \mathbf V_2 (\mathbf g_{\bm\zeta_2}(\mathbf V_2^\top \mathbf D_{t1} \mathbf r, t) - \mathbf g_{\bm\zeta_2}(\mathbf V_2^\top \mathbf D_{t2} \mathbf r, t))\|_2 + \| (\mathbf D_{t1} - \mathbf D_{t2}) \mathbf r \|_2 \nonumber \\
& \leq \|\mathbf D_{t1} - \mathbf D_{t2} \|_{\textrm{op}} \| \mathbf g_{\bm\zeta_1}(\mathbf V_1^\top \mathbf D_{t1} \mathbf r, t) \|_2 + \|\mathbf D_{t2}\|_{\textrm{op}} \| \mathbf V_1 - \mathbf V_2\|_{\textrm{op}} \| \mathbf g_{\bm\zeta_1}(\mathbf V_1^\top \mathbf D_{t1} \mathbf r, t) \|_2 \nonumber \\
&\quad + \|\mathbf D_{t2} \|_{\textrm{op}} \| \mathbf g_{\bm\zeta_1}(\mathbf V_1^\top \mathbf D_{t1} \mathbf r, t) - \mathbf g_{\bm\zeta_2}(\mathbf V_1^\top \mathbf D_{t1} \mathbf r, t) \|_2 + \gamma\|\mathbf D_{t2} \|_{\textrm{op}} \| \mathbf V_1 - \mathbf V_2^\top \|_{\textrm{op}} \|\mathbf D_{t1} \|_{\textrm{op}} \| \| \mathbf r \|_2 \nonumber \\
&\quad \quad + \gamma\|\mathbf D_{t2} \|_{\textrm{op}} \| \mathbf D_{t1} - \mathbf D_{t2} \|_{\textrm{op}} \| \mathbf r \|_2 + \| \mathbf D_{t1} - \mathbf D_{t2} \|_{\textrm{op}} \| \mathbf r \|_2, \label{equ: diff bound of score}
\end{align}
where the last inequality follows from the fact that $\{\mathbf V_i\}_{i=1,2}$ are orthogonal and $\{\mathbf g_{\bm\zeta_i}\}_{i=1,2}$ is $\gamma$-Lipschitz.

To analyze the covering number of $\calS_{\textrm{NN}}$, we consider 
\begin{equation}
\label{equ: diff bound of c, V, f}
\| \mathbf c_1 - \mathbf c_2 \|_{\infty} \leq \delta_c, \|\mathbf V_1 - \mathbf V_2\|_{\textrm{op}} \leq \delta_V, \textrm{ and }
\sup_{\| \mathbf r \|_2 \leq 3\rho+ \sqrt{d \log d}, t \in [t_0, T]} \| \mathbf g_{\bm\zeta_1}(\mathbf r, t) - \mathbf g_{\bm\zeta_2}(\mathbf r, t)\|_2 \leq \delta_f.
\end{equation}
Immediately, we can deduce that
\begin{equation}
\label{equ: diff bound of D}
\sup_{t \in [t_0, T]} \| \mathbf D_{t1} - \mathbf D_{t2} \|_{\textrm{op}} \leq \frac{\delta_c}{t_0^2}.
\end{equation}


Then, on the domain with radius $\| \mathbf r \|_2 \leq 3\rho + \sqrt{d \log d}$ and $t \in [t_0, T]$, by substituting the upper bounds \eqref{equ: diff bound of c, V, f} and \eqref{equ: diff bound of D} into \eqref{equ: diff bound of score}, we obtain
\begin{align*}
& \quad \sup_{\|\mathbf r\|_2 \leq 3\rho + \sqrt{d \log d}, t \in [t_0, T]} \|\mathbf s_{\bm\theta_1}(\mathbf r, t) - \mathbf s_{\bm\theta_2}(\mathbf r, t)\|_2 \\
&\leq \frac{\delta_c K}{t_0^2} + \frac{\delta_V K}{t_0} + \frac{\delta_f}{t_0} + \frac{\gamma \delta_V (3\rho + \sqrt{d \log d})}{t_0^2} + \frac{\gamma \delta_c (3\rho + \sqrt{d \log d})}{t_0^3} + \frac{\delta_c (3\rho + \sqrt{d \log d})}{t_0^2} \\
&\stackrel{(i)}{=} \frac{\delta_c (\gamma (3\rho + \sqrt{d \log d}) + t_0 K + t_0 (3\rho + \sqrt{d \log d}))}{t_0^3} + \frac{\delta_V (\gamma (3\rho + \sqrt{d \log d}) + t_0 K)}{t_0^2} + \frac{\delta_f}{t_0} \\
&\stackrel{(ii)}{=} \order\left( \frac{\delta_c \gamma(3\rho + \sqrt{d \log d}) + t_0 \delta_V \gamma (3\rho + \sqrt{d \log d}) + t_0^2 \delta_f}{t_0^3} \right),
\end{align*}
where $(i)$ follows from rearranging terms, and $(ii)$ holds by omitting higher-order terms on $\delta_c$, $\delta_V$, and $\delta_f$. For a hypercube $[0, \sigma_{\max}]^d$, the $\delta_c$-covering number is bounded by $\left(\frac{\sigma_{\max}}{\delta_c}\right)^{d}$. For a set of matrices $\{\mathbf V \in \bb R^{d \times k}: \|\mathbf V\|_{\textrm{op}} \leq 1\}$, its $\delta_V$-covering number is bounded by $\left(1 + \frac{2\sqrt{k}}{\delta_V}\right)^{dk}$ (see Lemma 8 in \citet{chen2019generalization}). Following Lemma 5.3 in \citet{chen2022nonparametric}, we take the upper bound $\left(\frac{2L^2 M (3\rho + \sqrt{d \log d})) \kappa^L M^{L+1}}{\delta_f}\right)^J$ for the $\delta_f$-covering number of the function class \eqref{equ: ReLU network}. Therefore, with $\rho = \order \left( \sqrt{\sigma_{\max}^2 \left(d + \log K + \log (n/\delta) \right) }\right)$, we have
\begin{align*}
    \log \mathfrak{N}(\nu, \calS_{\textrm{NN}},\|\cdot\|_2) & \leq \order\left(d\log \left( \frac{\sigma_{\max} \gamma(3\rho+\sqrt{d \log d})}{t_0^3 \nu}\right) + dk\log\left(1+\frac{2\sqrt{k}\gamma(3\rho+\sqrt{d \log d})}{t_0^2 \nu}\right) \right. \\
    &\quad \quad \left. + J\log \left( \frac{2 L^2 M(3\rho+\sqrt{d \log d})\kappa^LM^{L+1}}{t_0 \nu} \right)\right) \\
    &\stackrel{(i)}{=} \order \bigg( \bigg( dk + T \tau(1+L_s)^k (1+\sigma_{\max}^k) \epsilon^{-(k+1)} \bigg(\log \frac{1}{\epsilon}+ k \bigg)^{\frac{k+4}{2}} \bigg) \log \frac{T \tau d k}{t_0 \nu \epsilon} \bigg),
\end{align*}
where $(i)$ follows from invoking the order of network parameters in \eqref{equ: order of parameters in Theorem 1} in Theorem \ref{theorem: score approximation} and omitting higher orders terms such as $\log \log d$ and $\log \log k$. \hfill\Halmos

\end{proof}


\section{Omitted Proofs in Section \ref{sec: distribution estimation}}
\label{sec: proof of theorem -- distribution estimation}
In this section, we provide the proof of Theorem \ref{theorem: distribution estimation} and the lemmas used in the proof.

\subsection{Proof of Theorem~\ref{theorem: distribution estimation}}
\label{subsec: proof of theorem -- distribution estimation}
\iftrue
\begin{proof}{Proof.}
The proof contains two parts: the distribution estimation and the latent subspace recovery. For notational simplicity, let us denote
\begin{equation}
\label{equ: definition of simplified notation epsilon}
\epsilon := \frac{1}{t_0}(1+\sigma_{\max}^{2k}) d^{\frac{5}{2}} k^{\frac{k+10}{2}} n^{-\frac{2-2 \delta(n)}{k+5}} \log^4 n.
\end{equation}

\noindent \underline{\bf Part 1: Return Distribution Estimation.} 
First, we can decompose $\operatorname{TV}(P_{\textrm{data}}, \widehat{P}_{t_0})$ into
\begin{equation*}
\operatorname{TV}(P_{\textrm{data}}, \widehat{P}_{t_0}) \leq \operatorname{TV}(P_{\textrm{data}}, P_{t_0}) + \operatorname{TV}(P_{t_0}, \widetilde{P}_{t_0}) + \operatorname{TV}(\widetilde{P}_{t_0}, \widehat{P}_{t_0}),
\end{equation*}
where $P_{\textrm{data}}$ is the initial distribution of $\mathbf R$ in \eqref{equ: factor model}, $\widehat{P}_{t_0}$ and $\widetilde{P}_{t_0}$ are the marginal distribution of the estimated backward process $\widehat{\mathbf R}_{T-t_0}^{\leftarrow}$ in \eqref{equ: learned backward SDE} initialized with $\widehat{\mathbf R}_{0}^{\leftarrow} \sim \calN(\mathbf 0, \mathbf I_d)$ and $\widehat{\mathbf R}_{0}^{\leftarrow} \sim P_T$, respectively. Here, $\operatorname{TV}(P_{\textrm{data}}, P_{t_0})$ is the early-stopping error, $\operatorname{TV}(P_{t_0}, \widetilde{P}_{t_0})$ captures the approximation error of the score estimation, and $\operatorname{TV}(\widetilde{P}_{t_0}, \widehat{P}_{t_0})$ reflects the mixing error. We bound each term in Lemma \ref{lem: total variation distance error} and the error bound~\eqref{equ: upper bound of TV distance} is given by
\begin{equation*}
\begin{aligned}
    \operatorname{TV}\left(P_{\textrm{data}}, \widehat{P}_{t_0}\right) &= \order \bigg( d t_0 L_s (1 + \sigma_{\max}^2) + \sqrt{\epsilon (T-t_0)}+\sqrt{\operatorname{KL}\left(P_{\textrm{data}} \| \mathcal{N}\left(\mathbf 0, \mathbf I_d\right)\right)} \exp (-T) \bigg) \\
    &= \Tilde{\order} \left((1+\sigma_{\max}^k) d^{\frac{5}{4}} k^{\frac{k+10}{4}} n^{-\frac{1-\delta(n)}{2(k+5)}} \log^{\frac{5}{2}} n \right)
\end{aligned}
\end{equation*}
where the last equality follows from invoking the order of $\epsilon$ in \eqref{equ: definition of simplified notation epsilon}, $t_0 = n^{-\frac{1-\delta(n)}{k+5}}$, and $T = \order(\log n)$ and omitting the lower-order terms in $d t_0 $. Hence the distribution estimation result in Theorem~\ref{theorem: distribution estimation} is completed.

\noindent \underline{\bf Part 2: Latent Subspace Recovery.} First, we generate $m = \order\left( \lambda_{\max}^{-2}(\bm\Sigma_{0}) d n^{\frac{2(1-\delta(n))}{k+5}}\log n \right)$ new samples via Algorithm~\ref{algo: sampling}. By the error bound~\eqref{equ: upper bound of opnerator norm error} in Lemma \ref{lem: eigenvalue estimation error}, we obtain that, with probability $1 - 1/n$, it holds
\begin{align*}
    \left\| \widehat{\bm\Sigma}_{0} - \bm\Sigma_0 \right\|_{\textrm{op}} =
    \Tilde{\order}\Bigg(\lambda_{\max}(\bm\Sigma_0) (1+\sigma_{\max}^k) d^{\frac{5}{4}} k^{\frac{k+10}{4}} n^{-\frac{1-\delta(n)}{k+5}} \log^{\frac{5}{2}} n\Bigg). 
\end{align*}
Therefore, applying Weyl's theorem to $\widehat{\bm\Sigma}_{0}$ and $\bm\Sigma_0$, we deduce that for any $i = 1, 2, \dots, d$, it holds that
\begin{align*}
    \left| \lambda_i (\widehat{\bm\Sigma}_{0}) - \lambda_i ( \bm\Sigma_0 )\right| = \Tilde{\order}\Bigg(\lambda_{\max}(\bm\Sigma_0) (1+\sigma_{\max}^k) d^{\frac{5}{4}} k^{\frac{k+10}{4}} n^{-\frac{1-\delta(n)}{k+5}} \log^{\frac{5}{2}} n\Bigg).
\end{align*}
In addition, for any $i = 1, 2, \dots, k$, it holds that
\begin{align*}
    \left| \frac{\lambda_i (\widehat{\bm\Sigma}_{0})}{\lambda_i ( \bm\Sigma_0 )} - 1\right| = \Tilde{\order}\Bigg(\frac{\lambda_{\max}(\bm\Sigma_0) (1+\sigma_{\max}^k) d^{\frac{5}{4}} k^{\frac{k+10}{4}} }{\lambda_i(\bm\Sigma_0)} n^{-\frac{1-\delta(n)}{k+5}} \log^{\frac{5}{2}} n\Bigg).
\end{align*}
Next, we analyze the SVD of $\widehat{\bm\Sigma}_{0}$. Recall that the top $k$-dimensional eigenspace of $\bm\Sigma_0$ and $\widehat{\bm\Sigma}_{0}$ are denoted as $\mathbf U$ and $\widehat{\mathbf U}$, respectively. For any $j = 1, 2, \dots, k$, define
\begin{equation*}
\begin{aligned}
\label{equ: definition of cosine between matrices}
&\cos \angle_j(\widehat{\mathbf U}, \mathbf U) := \max_{\widehat{\mathbf u} \in \operatorname{Col}(\widehat{\mathbf U}), \mathbf u \in \operatorname{Col}(\mathbf U)} \frac{| \widehat{\mathbf u}^\top \mathbf u |}{\|\widehat{\mathbf u}\|_2 \|\mathbf u\|_2} := |\widehat{\mathbf u}_j^\top \mathbf u_j|, \\
&\textrm{ subject to } \widehat{\mathbf u}_j^\top \widehat{\mathbf u}_{\ell} = 0 \textrm{ and } \mathbf u_j^\top \mathbf u_{\ell} = 0, \textrm{ for any } \ell = 1, 2, \dots, j-1,
\end{aligned}
\end{equation*}
where $\operatorname{Col}(\cdot)$ represents the column space, $\widehat{\mathbf u}_0 := \mathbf 0$, and $\mathbf u_0 := \mathbf 0$. Applying Davis-Kahan-sin$(\theta)$ Theorem of \citet{davis1970rotation} to $\widehat{\mathbf U}$ and $\mathbf U$, we have
\begin{equation}
\label{equ: upper bound of sine error}
    \| \sin \angle (\widehat{\mathbf U}, \mathbf U) \|_{\rm{F}} \leq \frac{\| \widehat{\bm\Sigma}_{0} - \bm\Sigma_0 \|_{\rm{F}}}{\lambda_{k}(\bm\Sigma_0) - \lambda_{k+1}(\bm\Sigma_0)} = \order \bigg( \frac{\lambda_{\max}(\bm\Sigma_0) (1+\sigma_{\max}^k) d^{\frac{5}{4}} k^{\frac{k+10}{4}}}{{\textrm{\tt Eigen-gap}(k)}} \cdot n^{-\frac{1-\delta(n)}{k+5}} \log^{\frac{5}{2}} n \bigg),
\end{equation}
where
\begin{equation}
\label{equ: definition of sine between matrices}
\sin \angle (\widehat{\mathbf U}, \mathbf U ) := \Big(1 - \cos^2 \angle_1(\widehat{\mathbf U}, \mathbf U), 1 - \cos^2 \angle_2 (\widehat{\mathbf U}, \mathbf U), \dots, 1 - \cos^2 \angle_k (\widehat{\mathbf U}, \mathbf U) \Big).
\end{equation}
The inequality in \eqref{equ: upper bound of sine error} follows from the fact that $\|\mathbf A\|_{\textrm{F}} \leq \sqrt{k} \|\mathbf A\|_{\textrm{op}}$ for any $\mathbf A \in \mathbb{R}^{d \times k}$. By the property of SVD, we can find two orthogonal matrices $\mathbf O_1, \mathbf O_2 \in \bb R^{k \times k}$ such that 
$$
\widehat{\mathbf U}^\top \mathbf U = \mathbf O_1^\top \operatorname{diag}\left\{\cos \angle_1 (\widehat{\mathbf U}, \mathbf U), \cos \angle_2 (\widehat{\mathbf U}, \mathbf U), \dots, \cos \angle_k (\widehat{\mathbf U}, \mathbf U)\right\} \mathbf O_2.
$$
Immediately, it holds that
\begin{equation}
\label{equ: QR decomposition of cosine}
\widehat{\mathbf U}^\top \mathbf U \mathbf U^\top \widehat{\mathbf U} = \mathbf O_1^\top \operatorname{diag}\left\{\cos^2(\angle_1), \dots, \cos^2(\angle_k)\right\} \mathbf O_1.
\end{equation}
Therefore, we deduce that
\begin{align}
    \|\widehat{\mathbf U} \widehat{\mathbf U}^\top - \mathbf U \mathbf U^\top\|_{\rm{F}}^2 &= \operatorname{tr}(\widehat{\mathbf U} \widehat{\mathbf U}^\top + \mathbf U \mathbf U^\top - 2\widehat{\mathbf U} \widehat{\mathbf U}^\top \mathbf U \mathbf U^\top) \nonumber \\
    &\stackrel{(i)}{=} \operatorname{tr}(\widehat{\mathbf U}^\top \widehat{\mathbf U}) + \operatorname{tr}(\mathbf U^\top \mathbf U) - 2 \operatorname{tr}(\mathbf O_1^\top \operatorname{diag}\left\{\cos^2(\angle_1), \dots, \cos^2(\angle_k)\right\} \mathbf O_1) \nonumber \\
    &\stackrel{(ii)}{=} 2k - \sum_{i=1}^k \cos^2(\angle_i) = 2\| \sin \angle (\widehat{\mathbf U}, \mathbf U) \|_{\rm{F}}^2,
    \label{equ: relationship between subspace and sin}
\end{align}
where $(i)$ invokes \eqref{equ: QR decomposition of cosine} and $(ii)$ holds due to the fact that $\widehat{\mathbf U}$, $\mathbf U$, and $\mathbf O_1$ have orthogonal columns, and the last equality holds by the definition of $\sin \angle$ defined in \eqref{equ: definition of sine between matrices}.
Therefore, substituting the error bound of $\| \sin \angle (\widehat{\mathbf U}, \mathbf U) \|_{\rm{F}}^2$ in \eqref{equ: upper bound of sine error} into \eqref{equ: relationship between subspace and sin}, we obtain
\begin{align*}
    \|\widehat{\mathbf U} \widehat{\mathbf U}^\top - \mathbf U \mathbf U^\top\|_{\rm{F}} = \Tilde{\order}\Bigg(\frac{\lambda_{\max}(\bm\Sigma_0) (1+\sigma_{\max}^k) d^{\frac{5}{4}} k^{\frac{k+12}{4}} }{{\textrm{\tt Eigen-gap}(k)}} n^{-\frac{1-\delta(n)}{k+5}} \log^{\frac{5}{2}} n\Bigg). \tag*{\Halmos}
\end{align*}

\end{proof}
\fi


\subsection{Supporting Lemmas for Theorem \ref{theorem: distribution estimation}}
\label{subsec: proof of lemmas -- distribution estimation}
Recall that Lemma~\ref{lem: eigenvalue estimation error} and Lemma Lemma~\ref{lem: backward SDEs L2 error} are key results of our development. We provide their proofs in Appendices \ref{pf: eigenvalue estimation error} and \ref{pf: backward SDEs L2 error} respectively. Some additional lemmas that support the proof of Theorem \ref{theorem: distribution estimation} are stated and proved in Appendix \ref{ap:thm3_others}.
 \subsubsection{Proof of Lemma~\ref{lem: eigenvalue estimation error}}\label{pf: eigenvalue estimation error}
\iftrue
\begin{proof}{Proof.}

For notational simplicity, let us define 
\begin{equation}
\begin{aligned}
\label{equ: definition of three covariance matrices}
    &\bm\Sigma_{t_0} := \E_{\mathbf R_{t_0} \sim P_{t_0}}\left[\mathbf R_{t_0} \mathbf R_{t_0}^\top \right] - \E_{\mathbf R_{t_0} \sim P_{t_0}}[\mathbf R_{t_0}]\E_{\mathbf R_{t_0} \sim P_{t_0}}[\mathbf R_{t_0}]^\top, \\
    &\widetilde{\bm\Sigma}_{t_0} := \E_{\mathbf R_{t_0} \sim \widetilde{P}_{t_0}}\left[\mathbf R_{t_0} \mathbf R_{t_0}^\top \right] - \E_{\mathbf R_{t_0} \sim \widetilde{P}_{t_0}}[\mathbf R_{t_0}]\E_{\mathbf R_{t_0} \sim \widetilde{P}_{t_0}}[\mathbf R_{t_0}]^\top, \textrm{ and } \\
    &\widecheck{\bm\Sigma}_{t_0} = \E_{\mathbf R_{t_0} \sim \widehat{P}_{t_0}}\left[\mathbf R_{t_0} \mathbf R_{t_0}^\top \right] - \E_{\mathbf R_{t_0} \sim \widehat{P}_{t_0}}[\mathbf R_{t_0}]\E_{\mathbf R_{t_0} \sim \widehat{P}_{t_0}}[\mathbf R_{t_0}]^\top.
\end{aligned}
\end{equation}
The proof is based on the following error decomposition.
\paragraph{Error Decomposition.}
We decompose the target operator norm as
\begin{equation}
\label{equ: oracle inequality in Theorem 3}
    \big\| \widehat{\bm\Sigma}_{0} - \bm\Sigma_0 \big\|_{\textrm{op}} \leq \underbrace{\big\| \bm\Sigma_0 - \bm\Sigma_{t_0} \big\|_{\textrm{op}}}_{(A)} + \underbrace{\big\| \bm\Sigma_{t_0} - \widetilde{\bm\Sigma}_{t_0} \big\|_{\textrm{op}}}_{(B)} + \underbrace{\big\|\widetilde{\bm\Sigma}_{t_0} - \widecheck{\bm\Sigma}_{t_0} \big\|_{\textrm{op}}}_{(C)} + \underbrace{\big\| \widehat{\bm\Sigma}_{0} - \widecheck{\bm\Sigma}_{t_0} \big\|_{\textrm{op}}}_{(D)},
\end{equation}
where term $(A)$ is the early-stopping error, term $(B)$ is the approximation error of $\calS_{\textrm{NN}}$ term $(C)$ is the mixing error of forward process \eqref{equ: diffusion forward SDE}, term $(D)$ is the finite-sample error.

\paragraph{Bounding Term $(A)$.}
Using the fact that $\mathbf R_{t_0} = e^{-t_0 / 2} \mathbf R_0 + \mathbf B_{1-e^{-t_0}}$, we have 
\begin{align*}
    \bm\Sigma_0 - \bm\Sigma_{t_0} = \bm\Sigma_0 - e^{-t_0} \bm\Sigma_0 - (1-e^{-t_0}) \mathbf I_d =  (1-e^{-t_0})(\bm\Sigma_0 - \mathbf I_d).
\end{align*}
Therefore, by the definition of $(A)$ in \eqref{equ: oracle inequality in Theorem 3} and $t_0 = n^{-\frac{1-\delta(n)}{k+5}}$, we obtain
\begin{align}
    (A) = \order \Big( \lambda_{\max}(\bm\Sigma_0) \cdot n^{-\frac{1-\delta(n)}{k+5}} \Big). \label{equ: bound term (A) in Theorem 3}
\end{align}


\paragraph{Bounding Term $(B)$.}
Under the coupled SDE system \eqref{equ: coupling SDEs system}, we have
\begin{align}
    (B) &\leq \bigg\|\E_{\mathbf R_{t_0} \sim P_{t_0}}\left[\mathbf R_{t_0} \mathbf R_{t_0}^\top \right] - \E_{\mathbf R_{t_0} \sim \widehat{P}_{t_0}}\left[\mathbf R_{t_0} \mathbf R_{t_0}^\top \right]\bigg\|_{\textrm{op}} \nonumber \\
    &\qquad + \bigg\| \E_{\mathbf R_{t_0} \sim P_{t_0}}[\mathbf R_{t_0}]\E_{\mathbf R_{t_0} \sim P_{t_0}}[\mathbf R_{t_0}]^\top - \E_{\mathbf R_{t_0} \sim \widehat{P}_{t_0}}[\mathbf R_{t_0}]\E_{\mathbf R_{t_0} \sim \widehat{P}_{t_0}}[\mathbf R_{t_0}]^\top \bigg\|_{\textrm{op}} \nonumber \\
    &= \bigg\| \E\left[ (\mathbf R_{T-t_0}^{\leftarrow}) (\mathbf R_{T-t_0}^{\leftarrow})^\top \right] - \E\left[ (\widehat{\mathbf R}_{T-t_0}^{\leftarrow}) (\widehat{\mathbf R}_{T-t_0}^{\leftarrow})^\top \right] \bigg\|_{\textrm{op}} \label{equ: temp1 of bounding term B in latent subspace in Theorem 3} \\
    &\qquad + \bigg\| \E\left[\mathbf R_{T-t_0}^{\leftarrow}\right]\E\left[\mathbf R_{T-t_0}^{\leftarrow}\right]^\top - \E\left[\widehat{\mathbf R}_{T-t_0}^{\leftarrow}\right]\E\left[\widehat{\mathbf R}_{T-t_0}^{\leftarrow}\right]^\top \bigg\|_{\textrm{op}}, \label{equ: temp2 of bounding term B in latent subspace in Theorem 3}
\end{align}
where the last equality invokes $\bRb$ and $\hatbRb$ defined in \eqref{equ: coupling SDEs system}. For term \eqref{equ: temp1 of bounding term B in latent subspace in Theorem 3}, we have
\begin{align}
    \eqref{equ: temp1 of bounding term B in latent subspace in Theorem 3} &\leq \left\| \E\left[ (\mathbf R_{T-t_0}^{\leftarrow} - \widehat{\mathbf R}_{T-t_0}^{\leftarrow}) (\mathbf R_{T-t_0}^{\leftarrow})^\top \right] \right\|_{\text{op}} + \left\| \E\left[ (\widehat{\mathbf R}_{T-t_0}^{\leftarrow}) (\mathbf R_{T-t_0}^{\leftarrow} - \widehat{\mathbf R}_{T-t_0}^{\leftarrow})^\top \right] \right\|_{\text{op}} \nonumber \\
    &\leq \sqrt{ \E \big\| \mathbf R_{T-t_0}^{\leftarrow} - \widehat{\mathbf R}_{T-t_0}^{\leftarrow} \big\|_2^2 } \cdot \left( \sqrt{ \E \big\| \mathbf R_{T-t_0}^{\leftarrow} \big\|_2^2 } + \sqrt{ \E \big\| \widehat{\mathbf R}_{T-t_0}^{\leftarrow} \big\|_2^2 } \right), \label{equ: bounding term1 in B}
\end{align}
where \eqref{equ: bounding term1 in B} follows from the Cauchy-Schwarz inequality and rearranging terms. Similarly, for term \eqref{equ: temp2 of bounding term B in latent subspace in Theorem 3}, using the Cauchy-Schwarz inequality, we have
\begin{align}
    \eqref{equ: temp2 of bounding term B in latent subspace in Theorem 3} &\leq \left\|(\E\left[\mathbf R_{T-t_0}^{\leftarrow}\right] - \E[\widehat{\mathbf R}_{T-t_0}^{\leftarrow}]) \E\left[\mathbf R_{T-t_0}^{\leftarrow}\right]^\top \right\|_{\textrm{op}} + \left\| \E[\widehat{\mathbf R}_{T-t_0}^{\leftarrow}] (\E\left[\mathbf R_{T-t_0}^{\leftarrow}\right]^\top - \E[\widehat{\mathbf R}_{T-t_0}^{\leftarrow}]^\top) \right\|_{\textrm{op}} \nonumber \\
    &\leq \sqrt{ \E \big\| \mathbf R_{T-t_0}^{\leftarrow} - \widehat{\mathbf R}_{T-t_0}^{\leftarrow} \big\|_2^2 } \cdot \left( \sqrt{ \E \big\| \mathbf R_{T-t_0}^{\leftarrow} \big\|_2^2 } + \sqrt{ \E \big\| \widehat{\mathbf R}_{T-t_0}^{\leftarrow} \big\|_2^2 } \right), \label{equ: bounding term2 in B}
\end{align}
Then, substituting \eqref{equ: bounding term1 in B} and \eqref{equ: bounding term2 in B} into \eqref{equ: temp1 of bounding term B in latent subspace in Theorem 3} and \eqref{equ: temp2 of bounding term B in latent subspace in Theorem 3}, we deduce that
\begin{align}
    (B) &\leq 2\sqrt{ \E \big\| \mathbf R_{T-t_0}^{\leftarrow} - \widehat{\mathbf R}_{T-t_0}^{\leftarrow} \big\|_2^2 } \cdot \left( \sqrt{ \E \big\| \mathbf R_{T-t_0}^{\leftarrow} \big\|_2^2 } + \sqrt{ \E \big\| \widehat{\mathbf R}_{T-t_0}^{\leftarrow} \big\|_2^2 } \right) \nonumber \\
    &= \order \bigg( (1+\sigma_{\max}^k) d^{\frac{5}{4}} k^{\frac{k+10}{4}} n^{-\frac{1-\delta(n)}{k+5}} \log^{\frac{5}{2}} n \bigg), \label{equ: bound term (B) in Theorem 3}
\end{align}
where the last equality follows from applying the upper bound \eqref{equ: score estimation bound in Lemma 2 of Theorem 3} in Lemma \ref{lem: backward SDEs L2 error} and using the fact that
\begin{align*}
    &\E \big\| \mathbf R_{T-t_0}^{\leftarrow} \big\|_2^2 = \E \big\| e^{-t_0 / 2} \mathbf R_0 + \mathbf B_{1-e^{-t_0}} \big\|_2^2 \leq e^{-t_0} \E \big\| \mathbf R_0 \big\|_2^2 + 1 - e^{-t_0} = \order(1) \ \textrm{ and } \\
    &\E \big\| \widehat{\mathbf R}_{T-t_0}^{\leftarrow} \big\|_2^2 \leq 2\E \big\| \mathbf R_{T-t_0}^{\leftarrow} - \widehat{\mathbf R}_{T-t_0}^{\leftarrow} \big\|_2^2 + 2\E \big\| \mathbf R_{T-t_0}^{\leftarrow} \big\|_2^2 = \order(1).
\end{align*}

\paragraph{Bounding Term $(C)$.}
Applying Lemma~\ref{lem: backward SDEs L2 error} to the estimated backward process starting from $P_T$ and $\calN(\mathbf 0, \mathbf I_d)$, respectively, we obtain
\begin{equation}
\label{equ: bound term (C) in Theorem 3}
    \big\| \widetilde{\bm\Sigma}_{t_0} - \widecheck{\bm\Sigma}_{t_0} \big \|_{\textrm{op}} = \order \big( 2\E\| \widehat{\mathbf R}_{T-t_0}^{\leftarrow} - \mathbf R_{T-t_0}^{\leftarrow} \|_2^2 \big) = \order \bigg( (1+\sigma_{\max}^k) d^{\frac{5}{4}} k^{\frac{k+10}{4}} n^{-\frac{1-\delta(n)}{k+5}} \log^{\frac{5}{2}} n \bigg).
\end{equation}

\paragraph{Bounding Term $(D)$.}
By introducing the estimation error between $\bar{\mathbf R}_{0}$ and $\E[\mathbf R_i]$, we have
\begin{align*}
    (D) &\leq \bigg\| \frac{1}{m-1} 
    \sum_{i=1}^m \left( (\mathbf R_i - \E[\mathbf R_i]) (\mathbf R_i - \E[\mathbf R_i])^\top \right) - \widecheck{\bm\Sigma}_{t_0} \bigg\|_{\textrm{op}} \\
    &\qquad + \bigg\| \bar{\mathbf R}_0 (\bar{\mathbf R}_0 - \E[\mathbf R_i])^\top \bigg\|_{\textrm{op}} + \bigg\| (\bar{\mathbf R}_0 - \E[\mathbf R_i])\E[\mathbf R_i]^\top \bigg\|_{\textrm{op}} \\
    &\stackrel{(i)}{\leq} \bigg\| \frac{1}{m-1} 
    \sum_{i=1}^m \left( (\mathbf R_i - \E[\mathbf R_i]) (\mathbf R_i - \E[\mathbf R_i])^\top \right) - \widecheck{\bm\Sigma}_{t_0} \bigg\|_{\textrm{op}} \\
    &\qquad + \| \bar{\mathbf R}_0 \|_2 \| \bar{\mathbf R}_0 - \E[\mathbf R_i] \|_2 + \| \bar{\mathbf R}_0 - \E[\mathbf R_i] \|_2 \| \E[\mathbf R_i] \|_2 \\
    &\stackrel{(ii)}{\leq} \bigg\| \frac{1}{m-1} 
    \sum_{i=1}^m \left( (\widecheck{\bm\Sigma}_{t_0})^{-1/2}(\mathbf R_i - \E[\mathbf R_i]) (\mathbf R_i - \E[\mathbf R_i])^\top (\widecheck{\bm\Sigma}_{t_0})^{-1/2} - \mathbf I_d \right) \bigg\|_{\textrm{op}} \bigg\| \widecheck{\bm\Sigma}_{t_0} \bigg\|_{\textrm{op}} \\
    &\qquad + \| (\widecheck{\bm\Sigma}_{t_0})^{-\frac{1}{2}} \bar{\mathbf R}_0 \|_2 \| (\widecheck{\bm\Sigma}_{t_0})^{-\frac{1}{2}} (\bar{\mathbf R}_0 - \E[\mathbf R_i]) \|_2 \| \widecheck{\bm\Sigma}_{t_0} \|_{\textrm{op}} \\
    &\qquad \qquad + \| (\widecheck{\bm\Sigma}_{t_0})^{-\frac{1}{2}} (\bar{\mathbf R}_0 - \E[\mathbf R_i]) \|_2 \| (\widecheck{\bm\Sigma}_{t_0})^{-\frac{1}{2}} \E[\mathbf R_i] \|_2 \| \widecheck{\bm\Sigma}_{t_0} \|_{\textrm{op}},
\end{align*}
where $(i)$ follows from the H$\ddot{\text{o}}$lder inequality and $(ii)$ holds due to the covariance normalization using~$(\widecheck{\bm\Sigma}_{t_0})^{-\frac{1}{2}}$. Applying Theorem 3.1.1 and Theorem 4.6.1 of \citet{vershynin2018high} to
$$
(\widecheck{\bm\Sigma}_{t_0})^{-1/2}(\bar{\mathbf R}_0 - \E[\mathbf R_i]) \ \textrm{  and  } \
\frac{1}{m-1} \sum_{i=1}^m (\widecheck{\bm\Sigma}_{t_0})^{-1/2}(\mathbf R_i - \E[\mathbf R_i]) (\mathbf R_i - \E[\mathbf R_i])^\top (\widecheck{\bm\Sigma}_{t_0})^{-1/2},
$$
respectively, we obtain that with probability $1 - \delta$, it holds
\begin{align}
    (D) &= \order \bigg( \max\bigg\{\frac{\sqrt{d} + \sqrt{\log (2/\delta)}}{\sqrt{m}}, \bigg( \frac{\sqrt{d} + \sqrt{\log (2/\delta)}}{\sqrt{m}} \bigg)^2 \bigg\} \cdot \big\|\widecheck{\bm\Sigma}_{t_0}\big\|_{\textrm{op}} \bigg) \nonumber \\
    &= \order \bigg( \lambda_{\max}(\bm\Sigma_0) (1+\sigma_{\max}^k) d^{\frac{5}{4}} k^{\frac{k+10}{4}} n^{-\frac{1-\delta(n)}{k+5}} \log^{\frac{5}{2}} n \bigg), \label{equ: bound term (D) in Theorem 3}
\end{align}
where the last inequality the last inequality invokes the order of $m$ in \eqref{equ: order of m in Lemma 3} and the fact that
$$
\big\|\widecheck{\bm\Sigma}_{t_0}\big\|_{\textrm{op}} \leq \big\|\widecheck{\bm\Sigma}_{t_0} - \widetilde{\bm\Sigma}_{t_0}\big \|_{\textrm{op}} + \big\| \widetilde{\bm\Sigma}_{t_0} - \bm\Sigma_{t_0} \big \|_{\textrm{op}} + \big\| \bm\Sigma_{t_0} - \bm\Sigma_{0} \big \|_{\textrm{op}} + \big\| \bm\Sigma_{0}\big\|_{\textrm{op}}.
$$

Summing up the upper bound of $(A)$--$(D)$ in \eqref{equ: bound term (A) in Theorem 3} and \eqref{equ: bound term (B) in Theorem 3}--\eqref{equ: bound term (D) in Theorem 3}, we obtain the desired result. \hfill\Halmos
\end{proof}
\fi


\iftrue
\subsubsection{Proof of Lemma~\ref{lem: backward SDEs L2 error}}\label{pf: backward SDEs L2 error}

\begin{proof}{Proof.}
    For notational simplicity, we denote $\widehat{\mathbf s}_{T-t}(\cdot) := \widehat{\mathbf s}_{\bm\theta}\left( \cdot, T-t \right)$ and let $\widehat{\sigma}_{\min}^2$ and $\widehat{\sigma}_{\max}^2$ be the minimal and maximal elements of $\mathbf c$ in $\widehat{\mathbf s}_{\bm\theta}$, respectively. First, by direct calculation, we obtain
    \begin{align*}
        \frac{\dd \E\| \bRb - \hatbRb \|_2^2}{\dd t} &= 2\E\left[\Big(\bRb - \hatbRb\Big)^\top \Big( \frac{1}{2}\bRb - \frac{1}{2} \hatbRb + \nabla \log p_{T-t}\left(\bRb\right) - \widehat{\mathbf s}_{T-t}(\hatbRb) \Big)\right] \\
        &= \E\| \bRb - \hatbRb \|_2^2 + 2 \underbrace{\E\left[(\bRb - \hatbRb)^\top (\nabla \log p_{T-t}\left(\bRb\right) - \widehat{\mathbf s}_{T-t}(\hatbRb))\right]}_{(*)}.
    \end{align*}
  Consider $\Tilde{\mathbf g}_{\bm\zeta} : \bb R^k \times [0, T] \rightarrow \bb R^k$, equivalent to $\mathbf g_{\bm\zeta}$ defined via transformation, defined as
    \begin{equation}
    \label{equ: anothor formula for f relu network}
        \Tilde{\mathbf g}_{\bm\zeta}(\mathbf z, t) := \mathbf g_{\bm\zeta}(\mathbf V^\top \mathbf D_t \mathbf V \mathbf z, t),
    \end{equation}
    where $\mathbf V$, $\mathbf D_t$, and $\mathbf g_{\bm\zeta}$ are components of $\widehat{\mathbf s}_{\bm\theta}$ defined in \eqref{equ: score network}. Note that the Lipschitz constant of the ReLU network $\Tilde{\mathbf g}_{\bm\zeta}$ with respect to $\mathbf z$ is also on the order of $\gamma$ defined in \eqref{equ: order of parameters in Theorem 1}.
    Then, for term $(*)$, we have
    \begin{align*}
        (*) &= \E\left[(\bRb - \hatbRb)^\top (\nabla \log p_{T-t}\left(\bRb\right) - \widehat{\mathbf s}_{T-t}(\bRb))\right] \\
        &\qquad + \E\left[(\bRb - \hatbRb)^\top (\widehat{\mathbf s}_{T-t}(\bRb) - \widehat{\mathbf s}_{T-t}(\hatbRb))\right] \\
        &\stackrel{(i)}{\leq} \frac{\E\| \bRb - \hatbRb \|_2^2}{4} + \E\left\|\widehat{\mathbf s}_{T-t}\left(\bRb\right) - \nabla \log p_{T-t}\left(\bRb\right)\right\|_2^2 \\
        &\quad + \E\left[ (\bRb - \hatbRb)^\top \mathbf D_{T-t}^{1/2}(\alpha_{T-t} \gamma_1 \mathbf D_{T-t}^{1/2} \mathbf V (\mathbf V^{\top} \mathbf D_{T-t} \mathbf V)^{-1} \mathbf V^\top \mathbf D_{T-t}^{1/2} - \mathbf I) \mathbf D_{T-t}^{1/2} (\bRb - \hatbRb) \right] \\
        &\stackrel{(ii)}{\leq} \bigg(\frac{1}{4} + \frac{(\alpha_{T-t} \gamma_1 - 1)\indicator\{\alpha_{T-t} \gamma_1 > 1\}}{h_{T-t} + \widehat{\sigma}_{\min}^2\alpha_{T-t}^2} + \frac{(\alpha_{T-t} \gamma_1 - 1)\indicator\{\alpha_{T-t} \gamma_1 \leq 1\}}{h_{T-t} + \widehat{\sigma}_{\max}^2\alpha_{T-t}^2} \bigg)\E\| \bRb - \hatbRb \|_2^2 \\
        &\quad + \E\left\|\widehat{\mathbf s}_{T-t}\left(\bRb\right) - \nabla \log p_{T-t}\left(\bRb\right)\right\|_2^2,
    \end{align*}
    where $(i)$ holds due to the Cauchy-Schwarz inequality and the fact that $\widehat{\mathbf s}_{T-t}(\cdot)$ is $\gamma_1$-Lipschitz; $(ii)$ follows from
    \begin{equation*}
    \begin{aligned}
        & \lambda_{\max}(\alpha_{T-t} \gamma_1 \mathbf V (\mathbf V^\top \mathbf D_{T-t} \mathbf V)^{-1} \mathbf V^\top \mathbf D_{T-t} - \mathbf I) = \alpha_{T-t} \gamma_1 - 1,
    \end{aligned}
    \end{equation*}
    and
    $$
        \frac{1}{h_{T-t} + \widehat{\sigma}_{\max}^2\alpha_{T-t}^2} \leq \|\widehat{\mathbf D}_{T-t}\|_{\textrm{op}} \leq \frac{1}{h_{T-t} + \widehat{\sigma}_{\min}^2\alpha_{T-t}^2}.
    $$

 Notice that $\alpha_{T-t} \gamma_1 \leq 1$ is equivalent to $t \leq T - 2 \log \gamma_1$. By Gr$\ddot{\text{o}}$nwall's inequality, we obtain
    \begin{align}
        \quad &\E\| \mathbf R_{T-t_0}^{\leftarrow} - \widehat{\mathbf R}_{T-t_0}^{\leftarrow} \|_2^2 \nonumber \\
        &\leq \left( \E\| \mathbf R_0^{\leftarrow} - \widehat{\mathbf R}_0^{\leftarrow} \|_2^2 + \int_{0}^{T-t_0} 2\E\left\|\widehat{\mathbf s}_{T-t}\left(\bRb\right) - \nabla \log p_{T-t}\left(\bRb\right)\right\|_2^2 \dd t \right) \nonumber \\
        &\qquad \cdot \exp\left(\int_{0}^{T - 2 \log \gamma_1} \left(\frac{3}{2} + \frac{2(\alpha_{T-t} \gamma_1 - 1)}{h_{T-t} + \widehat{\sigma}_{\max}^2\alpha_{T-t}^2} \right) \dd t + \int_{T - 2 \log \gamma_1}^{T-t_0} \left(\frac{3}{2} + \frac{2(\alpha_{T-t} \gamma_1 - 1)}{h_{T-t} + \widehat{\sigma}_{\min}^2\alpha_{T-t}^2} \right) \dd t \right) \nonumber \\
        &= \left( \E\| \mathbf R_0^{\leftarrow} - \widehat{\mathbf R}_0^{\leftarrow} \|_2^2 + \int_{0}^{T-t_0} 2\E\left\|\widehat{\mathbf s}_{T-t}\left(\bRb\right) - \nabla \log p_{T-t}\left(\bRb\right)\right\|_2^2 \dd t \right) \label{equ: dynamic bound of backward process line 1} \\
        &\qquad \cdot \exp\left(\frac{3}{2}(T-t_0) + \int_{t_0}^{2 \log \gamma_1} \frac{2(\alpha_{w} \gamma_1 - 1)}{h_{w} + \widehat{\sigma}_{\min}^2\alpha_{w}^2} \dd w + \int_{2 \log \gamma_1}^{T} \frac{2(\alpha_{w} \gamma_1 - 1)}{h_{w} + \widehat{\sigma}_{\max}^2\alpha_{w}^2} \dd w \right), \label{equ: dynamic bound of backward process line 2}
    \end{align}
    where the last equality follows from rearranging the terms and a change of variable $T - t = w$.


   Now we claim that  
    \begin{equation}
    \label{equ: integral bound in Theorem 3}
        \int_{t_0}^{2 \log \gamma_1} \frac{2(\alpha_{w} \gamma_1 - 1)}{h_{w} + \widehat{\sigma}_{\min}^2\alpha_{w}^2} \dd w + \int_{2 \log \gamma_1}^{T} \frac{2(\alpha_{w} \gamma_1 - 1)}{h_{w} + \widehat{\sigma}_{\max}^2\alpha_{w}^2} \dd w \leq 4\gamma_1 \left(1 - \log (\widehat{\sigma}_{\min}^2 + t_0)\right) - 2(T - t_0).
    \end{equation}
    To verify this, consider the integral
    \begin{numcases}{\int \frac{\alpha_w \gamma_1 - 1}{h_w + c\alpha_w^2} \dd w =}
    C - \dfrac{2 \gamma_1 \arctan(\sqrt{c - 1}e^{-w/2})}{\sqrt{c - 1}} - \log (e^w + c - 1), & $\forall \ c > 1$ \label{equ: integral case1} \\
    C - 2\gamma_1 e^{-w/2} - w, & $c = 1$ \label{equ: integral case2} \\
    C - \dfrac{\gamma_1 \log \left(\frac{1 + e^{-w/2}\sqrt{1 - c}}{1 - e^{-w/2}\sqrt{1 - c}}\right) }{\sqrt{1 - c}} - \log (e^w + c - 1), & $\forall \ 0 < c < 1$ \label{equ: integral case3}
    \end{numcases}

\begin{enumerate}
        \item For the case $ c > 1 $, note that
        \begin{equation}
        \begin{aligned}
        \label{equ: temp of inregral bound 1 in Theorem 3}
            & -\log\bigg(\frac{e^T + c - 1}{e^{t_0} + c - 1}\bigg) \leq -(T-t_0) + \log (1+(c-1)e^{-t_0})
            \leq \log(c-(c-1)t_0)-(T - t_0), \\
            & -\frac{\arctan(\sqrt{c - 1} e^{-T/2}) - \arctan(\sqrt{c - 1} e^{-t_0/2})}{\sqrt{c - 1}} \leq e^{-t_0/2} - e^{-T/2} \leq 1.
        \end{aligned}
        \end{equation}
        Then, by substituting \eqref{equ: temp of inregral bound 1 in Theorem 3} into the integral \eqref{equ: integral case1}, we obtain
        \begin{equation}
        \label{equ: integral bound 1 in Theorem 3}
            \displaystyle\int_{t_0}^{T} \frac{\alpha_w \gamma_1 - 1}{h_w + c\alpha_w^2} \dd w \leq 2\gamma_1 + \log(c-(c-1)t_0) - (T-t_0).
        \end{equation}
        \item For the case $ c = 1 $, applying $e^{-w/2} \leq 1$, we obtain that the integral in \eqref{equ: integral case2} satisfies
        \begin{equation}
        \label{equ: integral bound 2 in Theorem 3}
            \displaystyle\int_{t_0}^{T} \frac{\alpha_w \gamma_1 - 1}{h_w + c\alpha_w^2} \dd w \leq -2\gamma_1(e^{-T} - e^{-t_0})-(T-t_0) \leq 2\gamma_1 - (T-t_0).
        \end{equation}
        \item For the case $0 < c < 1$, due to the continuity of the integral \eqref{equ: integral case3} with respect to $c$ and the bound in \eqref{equ: integral bound 2 in Theorem 3}, we only need to focus on the case $c \ll 1$. Without loss of generality, we consider $c < 1/2$. By direct calculation, we have 
   \begin{align}
            &\quad -\frac{1}{\sqrt{1 - c}} \left(\log \bigg(\frac{1 + e^{-T/2}\sqrt{1 - c}}{1 - e^{-T/2}\sqrt{1 - c}}\bigg) - \log \bigg(\frac{1 + e^{-t_0/2}\sqrt{1 - c}}{1 - e^{-t_0/2}\sqrt{1 - c}}\bigg)\right) \nonumber \\
            &\leq \frac{1}{\sqrt{1 - c}} \log \bigg(\frac{1 + e^{-t_0/2}\sqrt{1 - c}}{1 - e^{-t_0/2}\sqrt{1 - c}}\bigg) \nonumber \\
            &\leq \sqrt{2}(\log 4 - \log (c + t_0)), \label{equ: temp2 of integral bound 3}
        \end{align}
        where the last inequality follows from the fact that $e^{-x} \leq 1/(1+x)$, $\sqrt{1-c} \leq 1-c/2$, and $\log((1+x) / (1-x))$ is increasing in $x$; and rearranging terms. Then, by substituting \eqref{equ: temp of inregral bound 1 in Theorem 3} and \eqref{equ: temp2 of integral bound 3} into \eqref{equ: integral case3}, we obtain
        \begin{equation}
        \label{equ: integral bound 3 in Theorem 3}
        \displaystyle\int_{t_0}^{T} \frac{\alpha_w \gamma_1 - 1}{h_w + c\alpha_w^2} \dd w \leq 2\gamma_1(1 - \log (c + t_0))- (T-t_0).
        \end{equation}
    \end{enumerate}
    Combining the results in \eqref{equ: integral bound 1 in Theorem 3}, \eqref{equ: integral bound 2 in Theorem 3}, and \eqref{equ: integral bound 3 in Theorem 3}, we verified the claim in \eqref{equ: integral bound in Theorem 3}. 
    Finally, applying the upper bound of score estimation in \eqref{equ: score estimation bound in Lemma 2 of Theorem 3} and substituting \eqref{equ: integral bound in Theorem 3} into \eqref{equ: dynamic bound of backward process line 1} and \eqref{equ: dynamic bound of backward process line 2}, we deduce that
    \begin{align*} 
        &\quad \E \| \mathbf R_{T-t_0}^{\leftarrow} - \widehat{\mathbf R}_{T-t_0}^{\leftarrow} \|_2^2 \\ &\leq \left( \E\| \mathbf R_0^{\leftarrow} - \widehat{\mathbf R}_0^{\leftarrow} \|_2^2 + 2\epsilon (T-t_0) \right) \cdot \exp\left( \frac{3}{2}(T-t_0) + 4\gamma_1 (1 - \log (\widehat{\sigma}_{\min}^2 + t_0)) - 2(T-t_0) \right) \\
        &= \order \bigg( (1+\sigma_{\max}^k) d^{\frac{5}{4}} k^{\frac{k+10}{4}} n^{-\frac{1-\delta(n)}{k+5}} \log^{\frac{5}{2}} n \bigg),
    \end{align*}
    where the last equality follows from invoking $\E\| \mathbf R_0^{\leftarrow} - \widehat{\mathbf R}_0^{\leftarrow} \|_2^2 = \order (e^{-T})$ and rearranging terms. \hfill\Halmos
\end{proof}
\fi

\subsubsection{Other Supporting Lemmas for Theorem \ref{theorem: distribution estimation}}
\label{ap:thm3_others}
\begin{lemma}
\label{lem: total variation distance error}
Suppose that $P_{\mathrm{data}}$ is sub-Gaussian, and both $\widehat{\mathbf s}_{\bm\theta}(\mathbf r, t)$ and $\nabla \log p_t(\mathbf r)$ are Lipschitz with respect to both $\mathbf r$ and $t$. Consider the score estimation error satisfying
$$
\int_{t_0}^{T} \E_{\mathbf R_t \sim P_t}\left\|\widehat{\mathbf s}_{\bm\theta}(\mathbf R_t, t) - \nabla \log p_t \left(\mathbf R_t\right)\right\|_{2}^{2} \dd t = \order (\epsilon (T - t_0)).
$$
Then, the total variation distance is bounded by
\begin{equation}
\label{equ: upper bound of TV distance}
\operatorname{TV}(P_{\mathrm{data}}, \widehat{P}_{t_0}) = \order \bigg( d t_0 L_s (1 + \sigma_{\max}^2) + \sqrt{\epsilon (T-t_0)}+\sqrt{\operatorname{KL}\left(P_{\mathrm{data}} \| \mathcal{N}\left(\mathbf 0, \mathbf I_d\right)\right)} \exp (-T) \bigg),
\end{equation}
where $P_{\mathrm{data}}$ is the initial distribution of $\mathbf R$ in \eqref{equ: factor model} and $\widehat{P}_{t_0}$ is the marginal distribution of the backward process $\widehat{\mathbf R}_{T-t_0}^{\leftarrow}$ in \eqref{equ: learned backward SDE} starting from $\mathcal{N}(\mathbf 0, \mathbf I_d)$.
\end{lemma}

\begin{proof}{Proof of Lemma~\ref{lem: total variation distance error}.}
To estimate $\operatorname{TV}(P_{\textrm{data}}, \widehat{P}_{t_0})$, we leverage the error decomposition in \eqref{equ: TV distance decomposition in Theorem 3}.
Recall that $\widetilde{P}_{t_0}$ is the marginal distribution of $\widehat{\mathbf R}_{T - t_0}^{\leftarrow}$ in \eqref{equ: learned backward SDE} initialized with $\widehat{\mathbf R}_{0}^{\leftarrow} \sim P_T$. In the decomposition \eqref{equ: TV distance decomposition in Theorem 3}, $\operatorname{TV}(P_{\textrm{data}}, P_{t_0})$ is the early stopping error, $\operatorname{TV}(P_{t_0}, \widetilde{P}_{t_0})$ is the statistical error arising from the score estimation, and $\operatorname{TV}(\widetilde{P}_{t_0}, \widehat{P}_{t_0})$ is the mixing error of the forward process \eqref{equ: diffusion forward SDE}. 
\begin{enumerate}
    \item For term $\operatorname{TV}(P_{\textrm{data}}, P_{t_0})$, applying the upper bound \eqref{equ: TV between 0 and t0} with $t = t_0$ in Lemma \ref{lem: TV between 0 and t0}, we obtain
    \begin{equation}
    \label{equ: bounding term1 in TV distance}
    \operatorname{TV}\left(P_{\textrm{data}}, P_{t_0} \right) = \order (d t_0).
    \end{equation}
    \item For term $\operatorname{TV}(P_{t_0}, \widetilde{P}_{t_0})$, by Pinsker's inequality \cite[Lemma 2.5]{tsy2009nonparametric} and the upper bound of KL-divergence  \eqref{equ: KL divergence between backward processes} in Lemma \ref{lem: KL divergence between backward processes}, we have
    \begin{equation}
    \label{equ: bounding term2 in TV distance}
    \operatorname{TV}(P_{t_0}, \widetilde{P}_{t_0}) \leq \operatorname{KL}(P_{t_0} || \widetilde{P}_{t_0}) = \order \big( \sqrt{\epsilon\left(T-t_0\right)} \big).
    \end{equation}
    \item For term $\operatorname{TV}(\widetilde{P}_{t_0}, \widehat{P}_{t_0})$, by Pinsker's inequality \cite[Lemma 2.5]{tsy2009nonparametric} and Data processing inequality \cite[Theorem 2.8.1]{thomas2006elements} , we deduce that
    \begin{equation}
    \label{equ: bounding term3 in TV distance}
    {\operatorname{TV}}(\widetilde{P}_{t_0}, \widehat{P}_{t_0}) \leq \sqrt{\operatorname{KL}(\widetilde{P}_{t_0} \| \widehat{P}_{t_0})} \leq \sqrt{\operatorname{KL}\left(P_T \| \mathcal{N}\left(0, \mathbf I_d\right)\right)} = \order\big( \sqrt{\operatorname{KL}\left(P_{\textrm{data}} \| \mathcal{N}\left(0, \mathbf I_d\right)\right)} \exp (-T)\big),
    \end{equation}
where in the last inequality, we use the exponential mixing property of the O-U process.
\end{enumerate}
Substituting the upper bounds \eqref{equ: bounding term1 in TV distance}, \eqref{equ: bounding term2 in TV distance}, and \eqref{equ: bounding term3 in TV distance} into \eqref{equ: TV distance decomposition in Theorem 3}, we obtain the desired result. \hfill\Halmos
\end{proof}


\begin{lemma}[Novikov's condition]
\label{lem: Novikov's condition}
Under the assumptions in Lemma \ref{lem: total variation distance error}, it holds
\begin{equation}
\label{equ: Novikov's condition}
\E_{(\bRb)_{t \in [0, T-t_0]}} \bigg[\exp \left(\frac{1}{2} \int_0^{T-t_0}\left\|\widehat{\mathbf s}_{\bm\theta}(\bRb, t) - \nabla \log p_{T-t}\left(\bRb\right)\right\|_2^2 \dd t\right) \bigg] < \infty,
\end{equation}
where the expectation is taken over the backward diffusion process $(\bRb)_{t \in [0, T-t_0]}$ in \eqref{equ: diffusion backward SDE}.
\end{lemma}

\begin{proof}{Proof of Lemma~\ref{lem: Novikov's condition}.}
The result follows from a straightforward calculation using the same techniques as in \cite[Lemma 11]{chen2023score}. \hfill\Halmos
\end{proof}


\begin{lemma}
\label{lem: KL divergence between backward processes}
Suppose that the assumptions in Lemma \ref{lem: total variation distance error} hold. When both the ground-truth and learned backward processes start with $\mathbf R_0^{\leftarrow} \stackrel{\textrm{d}}{=} \widehat{\mathbf R}_{0}^{\leftarrow} \sim P_T$, the KL-divergence between the laws of the paths of the processes $(\bRb)_{0 \leq t \leq T-t_0}$ and $(\hatbRb)_{0 \leq t \leq T-t_0}$ can be bounded by
\begin{equation}
\label{equ: KL divergence between backward processes}
\operatorname{KL}(P_{t_0} || \widetilde{P}_{t_0})=\E\left(\frac{1}{2} \int_0^{T-t_0}\left\|\widehat{\mathbf s}_{\bm\theta}\left(\bRb, T-t\right) - \nabla \log p_{T-t}\left(\bRb\right)\right\|_2^2 \dd t\right) = \order \Big( \epsilon(T-t_0) \Big).
\end{equation}
\end{lemma}

\begin{proof}{Proof of Lemma~\ref{lem: KL divergence between backward processes}.}
By Lemma \ref{lem: Novikov's condition}, the Novikov's condition holds. Immediately, we obtain the results by directly invoking Girsanov's Theorem \cite[Theorem 6]{chen2022sampling}. \hfill\Halmos
\end{proof}

\begin{lemma}
\label{lem: TV between 0 and t0}
Suppose that the assumptions in Lemma \ref{lem: total variation distance error} hold. Then, for any $t < 1/d$, we have
\begin{equation}
\label{equ: TV between 0 and t0}
    \operatorname{TV}(P_{\textrm{data}}, P_t) = \order (d t).
\end{equation}
\end{lemma}

\begin{proof}{Proof of Lemma~\ref{lem: TV between 0 and t0}.}
Given $\mathbf R_0$, $\mathbf R_t$ can be represented as
\begin{equation*}
\mathbf R_t = e^{-t/2} \mathbf R_0 + \int_0^{t} e^{-(t-s)/2} \dd \mathbf W_s,
\end{equation*}
where $\mathbf R_0$ and $\int_0^t e^{-(t-s)/2} \dd \mathbf W_s$ are independent. Then, the density of $\mathbf R_t$ is given by
    $$
        p_t(\mathbf r) = \int p_{\textrm{data}}(\mathbf y) \phi(\mathbf r; \alpha_t \mathbf y, h_t) \dd \mathbf y.
    $$
    Define
    \begin{equation}
    \label{equ: choice of S(d, t)}
    S(d, t) := \order(\sqrt{d + \log (1/t)})
    \end{equation}
    as a truncation radius and we have
    \begin{align}
        \operatorname{TV}\left( P_{\textrm{data}}, P_t \right) &= \frac{1}{2} \int \left| p_t(\mathbf r) - p_{\textrm{data}}(\mathbf r) \right| \dd \mathbf r \nonumber \\
        &\leq \frac{1}{2} \int_{\| \mathbf r \|_2 > S(d, t)} \Big(p_t(\mathbf r) + p_{\textrm{data}}(\mathbf r)\Big) \dd \mathbf r \label{equ: term1 in TV between 0 and t0} \\
        &\qquad + \frac{1}{2} \int_{\| \mathbf r \|_2 \leq S(d, t)} \bigg| \int ( p_{\textrm{data}}(\mathbf y) \phi(\mathbf r; \alpha_t \mathbf y, h_t) - p_{\textrm{data}}(\mathbf r) ) \dd \mathbf y \bigg| \dd \mathbf r. \label{equ: term2 in TV between 0 and t0}
    \end{align}
     By the density upper bound in \eqref{equ: R0 sub-Gaussian tail -- heterogeneous} and Theorem 3.1 of \citet{chazottes2019evolution}, it holds that $p_{\textrm{data}}$ and $p_t(\mathbf r)$ are sub-Gaussian and there exists a constant $A_1 > 0$ such that $(p_t(\mathbf r) + p_{\textrm{data}}(\mathbf r)) \leq \exp(-A_1 \|\mathbf r\|_2^2/2)$. 


    For term \eqref{equ: term1 in TV between 0 and t0}, using the sub-Gaussian tail in Lemma 16 of \citet{chen2023score} and invoking the order of $S(d, t)$ in \eqref{equ: choice of S(d, t)}, we obtain that
    \begin{equation}
    \label{equ: bound of term1 in TV between 0 and t0}
    \eqref{equ: term1 in TV between 0 and t0} = \order \bigg( \frac{2^{-\frac{d}{2}} d S(d, t)^{d-2}}{A_1 \Gamma\left( \frac{d}{2} + 1 \right)} \exp\left(- \frac{A_1 S(d, t)^2}{2} \right) \bigg) = \order \big( t\exp\left( -A_1 d \right) \big).
    \end{equation}
    For term \eqref{equ: term2 in TV between 0 and t0}, by taking a change of variable $\mathbf z := (\mathbf r - \alpha_t \mathbf y)/\sqrt{h_t}$, we deduce that
    \begin{align}
        \eqref{equ: term2 in TV between 0 and t0} &= \int_{\| \mathbf r \|_2 \leq S(d, t)} \left| \int \left( p_{\textrm{data}}(\alpha_t^{-1} ( \mathbf r - \sqrt{h_t} \mathbf z )) \phi( \mathbf z; \mathbf 0, \mathbf I) - p_{\textrm{data}}(\mathbf r) \right) \dd \mathbf z \right| \dd \mathbf r \nonumber \\
        &\stackrel{(i)}{=} \order \bigg( \int_{\| \mathbf r \|_2 \leq S(d, t)} \bigg| \int \bigg(\nabla p_{\textrm{data}}(\mathbf r) \bigg( \frac{t \mathbf r}{2} - \sqrt{t} \mathbf z \bigg) \phi(\mathbf z; \mathbf 0, \mathbf I) \dd \mathbf z \bigg| \dd \mathbf r \label{equ: upper bound of TV in domain S(d, t) line1} \\
        &\qquad \qquad + \int_{\| \mathbf r \|_2 \leq S(d, t)} \bigg| \frac{1}{2} \bigg( \frac{t \mathbf r}{2} - \sqrt{t} \mathbf z \bigg)^\top \nabla^2 p_{\textrm{data}}(\mathbf r) \bigg( \frac{t \mathbf r}{2} - \sqrt{t} \mathbf z \bigg) \bigg) \phi(\mathbf z; \mathbf 0, \mathbf I) \dd \mathbf z \bigg| \dd \mathbf r \bigg), \label{equ: upper bound of TV in domain S(d, t) line2}
    \end{align}
    where $(i)$ involves the Taylor expansion $\alpha_t^{-1} = 1 + t/2 + \order(t^2)$, $h_t = t + \order(t^2)$ and the fact that $$
    p_{\textrm{data}}(e^{t/2} (\mathbf r - \sqrt{h_t} \mathbf z)) = p_{\textrm{data}}(\mathbf r) + \nabla p_{\textrm{data}}(\mathbf r) \bigg( \frac{t \mathbf r}{2} - \sqrt{t} \mathbf z \bigg) + \frac{1}{2} \bigg( \frac{t \mathbf r}{2} - \sqrt{t} \mathbf z \bigg)^\top \nabla^2 p_{\textrm{data}}(\mathbf r) \bigg( \frac{t \mathbf r}{2} - \sqrt{t} \mathbf z \bigg).
    $$
    The integrals associated with the kernel function $\phi(\mathbf z; \mathbf 0, \mathbf I)$ satisfy
    \begin{equation}
    \label{equ: integral about kernel function -- 0 moment}
        \int p_{\textrm{data}}(\mathbf r) \phi(\mathbf z; \mathbf 0, \mathbf I) \dd \mathbf z = p_{\textrm{data}}(\mathbf r)
    \end{equation}
    and
    \begin{align}
        \int \nabla p_{\textrm{data}}(\mathbf r) \bigg( \frac{t \mathbf r}{2} - \sqrt{t} \mathbf z \bigg) \phi(\mathbf z; \mathbf 0, \mathbf I) \dd \mathbf z = \frac{t}{2} \nabla \log p_{\textrm{data}}(\mathbf r) \mathbf r p_{\textrm{data}}(\mathbf r) = \order ( t \|\mathbf r\|_2 \| \nabla \log p_{\textrm{data}}(\mathbf r) \|_2 \cdot p_{\textrm{data}}(\mathbf r)). \label{equ: integral about kernel function -- 1 moment}
    \end{align}
    Moreover, since the Hessian matrix satisfies the following property
    \begin{equation}
    \begin{aligned}
    \label{equ: Hessian matrix representation}
        \nabla^2 p_{\textrm{data}}(\mathbf r) = (\nabla^2 \log p_{\textrm{data}}(\mathbf r) + \nabla \log p_{\textrm{data}}(\mathbf r) \nabla \log p_{\textrm{data}}(\mathbf r)^\top ) \cdot p_{\textrm{data}}(\mathbf r),
    \end{aligned}
    \end{equation}
    we deduce
    \begin{align}
    \label{equ: integral about kernel function -- 2 moment}
        &\quad \int \bigg(\frac{1}{2} \bigg( \frac{t \mathbf r}{2} - \sqrt{t} \mathbf z \bigg)^\top \nabla^2 p_{\textrm{data}}(\mathbf r) \bigg( \frac{t \mathbf r}{2} - \sqrt{t} \mathbf z \bigg) \bigg) \phi(\mathbf z; \mathbf 0, \mathbf I) \dd \mathbf z \nonumber \\
        &\stackrel{(i)}{=} \operatorname{tr}\bigg( \frac{1}{8} t^2 \nabla^2 p_{\textrm{data}}(\mathbf r) \mathbf r \mathbf r^\top + \frac{1}{2} t \nabla^2 p_{\textrm{data}}(\mathbf r) \bigg) \nonumber \\
        &\stackrel{(ii)}{=} \operatorname{tr}\bigg( \bigg( \frac{1}{8} t^2 \mathbf r \mathbf r^\top + \frac{1}{2} t \bigg) (\nabla^2 \log p_{\textrm{data}}(\mathbf r) + \nabla \log p_{\textrm{data}}(\mathbf r) \nabla \log p_{\textrm{data}}(\mathbf r)^\top ) \cdot p_{\textrm{data}}(\mathbf r) \bigg) \nonumber \\
        &= \order \bigg( (t^2 \|\mathbf r\|_2^2 + t) \operatorname{tr}\big( (\nabla^2 \log p_{\textrm{data}}(\mathbf r) + \nabla \log p_{\textrm{data}}(\mathbf r) \nabla \log p_{\textrm{data}}(\mathbf r)^\top ) \cdot p_{\textrm{data}}(\mathbf r) \big) \bigg).
    \end{align}
    where $(i)$ is follows from $\int \mathbf z \mathbf z^\top \phi(\mathbf z; \mathbf 0, \mathbf I) \dd \mathbf z = \mathbf I_d$ and rearranging terms, and $(ii)$ follows \eqref{equ: Hessian matrix representation}.

Therefore, by substituting \eqref{equ: integral about kernel function -- 0 moment}, \eqref{equ: integral about kernel function -- 1 moment} and \eqref{equ: integral about kernel function -- 2 moment} into \eqref{equ: upper bound of TV in domain S(d, t) line1} and \eqref{equ: upper bound of TV in domain S(d, t) line2}, we obtain that
    \begin{align}
        \eqref{equ: term2 in TV between 0 and t0}
        &= \order \bigg( \int_{\| \mathbf r \|_2 \leq S(d, t)} \bigg( t \|\mathbf r\|_2 \| \nabla \log p_{\textrm{data}}(\mathbf r) \|_2 \nonumber \\
        &\qquad + \operatorname{tr} \big( (t^2 \|\mathbf r\|_2^2 + t) (\nabla^2 \log p_{\textrm{data}}(\mathbf r) + \nabla \log p_{\textrm{data}}(\mathbf r) \nabla \log p_{\textrm{data}}(\mathbf r)^\top ) \big) \bigg) p_{\textrm{data}}(\mathbf r) \dd \mathbf r \bigg) \nonumber \\
        &\stackrel{(i)}{=} \order \bigg( t S(d, t) \sqrt{\E_{\mathbf R_0 \sim P_{\textrm{data}}}[\| \nabla \log p_{\textrm{data}}(\mathbf R_0) \|_2^2]} \nonumber \\
        &\qquad + (t^2 S^2(d, t)  + t) \operatorname{tr}\bigg(\int (\nabla^2 \log p_{\textrm{data}}(\mathbf r) + \nabla \log p_{\textrm{data}}(\mathbf r) \nabla \log p_{\textrm{data}}(\mathbf r)^\top) p_{\textrm{data}}(\mathbf r) \dd \mathbf r) \bigg) \bigg) \nonumber \\
        &\stackrel{(ii)}{=} \order \big( t \sqrt{d} S(d, t) + t^2 d S^2(d, t) \cdot L_s (\sigma_{\max}^2 + 1) \big) = \order \big( d t L_s (\sigma_{\max}^2 + 1) \big). \label{equ: bound of term2 in TV between 0 and t0}
    \end{align}
    where $(i)$ is due to the Cauchy-Schwarz inequality and $\| \mathbf r \|_2 \leq S(d, t)$, and $(ii)$ invokes the upper bound \eqref{equ: upper bound of log p_data L2 norm} in Lemma \ref{lem: bound for score function L2 norm}.


    Combining the upper bound of \eqref{equ: term1 in TV between 0 and t0} and \eqref{equ: term2 in TV between 0 and t0} in \eqref{equ: bound of term1 in TV between 0 and t0} and \eqref{equ: bound of term2 in TV between 0 and t0}, we obtain the desired result. \hfill\Halmos
\end{proof}

\begin{lemma}
\label{lem: bound for score function L2 norm}
Suppose Assumptions \ref{assumption: factor}-\ref{assumption: Lipschitz} holds. Then, it holds
\begin{align}
    \E_{\mathbf R_0 \sim P_{\mathrm{data}}}\left\|\nabla \log p_{\mathrm{data}}(\mathbf R_0)\right\|_2^2 = \order (d L_s (\sigma_{\max}^2 + 1)). \label{equ: upper bound of log p_data L2 norm}
\end{align}
\end{lemma}

\begin{proof}{Proof of Lemma~\ref{lem: bound for score function L2 norm}.}

Taking $t = 0$ in the formula of $\nabla \log p_t$ in \eqref{equ: score decomposition -- heterogeneous} of Lemma \ref{lem: score decomposition -- heterogeneous}, we have
\begin{align*}
    \nabla \log p_{\textrm{data}}(\mathbf r) &= \mathbf s_{\textrm{sub}}(\bm\Gamma_0\bm\beta^\top \bm\Lambda_0^{-1} \mathbf r, 0) - \bm \Lambda_0^{-\frac{1}{2}} (\mathbf I - \bm\Lambda_0^{-\frac{1}{2}} \bm\beta \bm\Gamma_0 \bm\beta^\top \bm\Lambda_0^{-\frac{1}{2}}) \bm \Lambda_0^{-\frac{1}{2}} \mathbf r.
\end{align*}
Under Assumption \ref{assumption: Lipschitz}, for any $\mathbf r_1, \mathbf r_2 \in \bb R^d$, it holds that
\begin{align}
    \|\nabla \log p_{\textrm{data}}(\mathbf r_1) - \nabla \log p_{\textrm{data}}(\mathbf r_2)\|_2 &\leq L_s \| \bm\Gamma_0\bm\beta^\top \bm\Lambda_0^{-1} \|_{\textrm{op}} \|\mathbf r_1 - \mathbf r_2\|_2 + \|\bm\Lambda_0^{-1} \|_{\textrm{op}} \|\mathbf r_1 - \mathbf r_2\|_2 \nonumber \\
    &\leq \frac{L_s (\sigma_{\max}^2 + 1)}{\sigma_d^2} \cdot \|\mathbf r_1 - \mathbf r_2\|_2, \label{equ: Lipschitz constant of log p_data}
\end{align}
where the last equality follows from $\| \bm\Gamma_0\|_{\textrm{op}} \leq \sigma_{\max}^2$ and $\| \bm\Lambda_0^{-1} \|_{\textrm{op}} \leq 1/\sigma_d^2$. This indicates that the Lipschitz constant of $\nabla \log p_{\textrm{data}}$ is bounded by $L_s (1+\sigma_{\max}^2)/\sigma_d^2$. 

Furthermore, we have
\begin{align*}
\E_{\mathbf R_0 \sim P_{\textrm{data}}}\bigg[ \| \nabla \log p_{\textrm{data}}(\mathbf R_0) \|_2^2 \bigg]
&= \operatorname{tr}\bigg( \int \nabla \log p_{\textrm{data}}(\mathbf r) \nabla \log p_{\textrm{data}}(\mathbf r)^{\top} p_{\textrm{data}}(\mathbf r) \dd \mathbf r \bigg) \\
&\stackrel{(i)}{=} \operatorname{tr}\bigg( -\int \nabla^2 \log p_{\textrm{data}}(\mathbf r)^{\top} p_{\textrm{data}}(\mathbf r) \dd \mathbf r\bigg) \\
&= \order (d L_s (\sigma_{\max}^2 + 1)),
\end{align*}
where $(i)$ is due to the integration by parts and the last inequality follows from invoking \eqref{equ: Lipschitz constant of log p_data}. \hfill\Halmos

\end{proof}



\section{Additional Details of the Numerical Study with Synthetic Data} \label{app:exp_setup}
Here we explain additional details of the numerical experiment setup for Section \ref{sec:synthetic}. Following \citet{bai2002determining, bai2023approximate}, we construct the ground-truth environment of high-dimensional asset returns using a latent factor model. Specifically, the universe consists of $ d = 2048 $ assets, whose returns are driven by $ k = 16 $ latent factors. Here, the choice of $ d $ as a power of 2 enhances the computational efficiency. 

Denote $\bm{\mu}_F = (\mu_{F1}, \mu_{F2}, \dots, \mu_{Fk})$ as the expected return and $\bm{\Sigma}_F = \operatorname{diag}\{\sigma_{F1}^2, \sigma_{F2}^2, \dots, \sigma_{Fk}^2\}$ the covariance matrix of the latent factor. In addition, denote
$\bm{\Sigma}_{\varepsilon} = \operatorname{diag}\{\sigma_{\varepsilon 1}^2, \sigma_{\varepsilon 2}^2, \dots, \sigma_{\varepsilon d}^2\}$ as the covariance of the idiosyncratic noise of the asset. We then construct samples from the ground-truth environment as follows:
\begin{enumerate}
    \item \textbf{Latent Factor.}  
    The components of $\bm{\mu}_F$ are drawn i.i.d. from $\operatorname{Uniform}(0, 0.1)$ and we set $ \sigma_{Fi} = 1.5 \mu_{Fi} $ for $ i = 1, 2, \dots, k $ to ensure that the volatility scales proportionally to the corresponding mean.

    \item \textbf{Factor Loadings.}  
    We generate the factor loading matrix $\bm \beta \in \mathbb{R}^{d \times k}$, where each element is drawn i.i.d. from $\mathcal{N}(0, 1)$, ensuring that the loadings are symmetrically distributed with comparable magnitudes across assets and factors.

    \item \textbf{Idiosyncratic Risk.}  
    $\{\sigma_{\varepsilon i}\}_{i=1}^{d}$ are drawn i.i.d. from $ \operatorname{Uniform}(0, 0.4)$, ensuring uncorrelated idiosyncratic returns across assets.

    \item \textbf{Asset Return.} We generate a total of $ 2^{13}=8192 $ simulated samples. Asset returns are sampled i.i.d. according to the following procedure. First, the factor is drawn from a multivariate normal distribution $\mathbf F \sim \mathcal{N}(\bm{\mu}_F, \bm{\Sigma}_F)$. Then the asset-specific noise terms are drawn i.i.d. from $\bm{\varepsilon} \sim \mathcal{N}(\mathbf 0, \bm{\Sigma}_{\varepsilon})$. Finally, the asset return is constructed by $\mathbf R = \bm\beta \mathbf F + \bm{\varepsilon}$. We denote by $ \mu_{Ri} $ and $ \sigma_{Ri} $ the mean and standard deviation of the ground-truth return for asset $ i $, where $ i = 1, 2, \dots, d $.

\end{enumerate}


\paragraph{Summary Statistics of the Synthetic Data.} To show that our simulation setting is close to the realistic market scenario, we benchmark our simulation set-up against the S\&P 500 index. Specifically, denote by $ \mu_{\text{S\&P 500}, i} $ and $ \sigma_{\text{S\&P500}, i} $ the mean and standard deviation of historical returns for stock $ i $ in the S\&P 500 index over the period 2000–2020. Table \ref{tab:summary_statistics_for_simulation} reports the summary statistics of $ \{\mu_{Ri}\}_{i=1}^{d} $ and compares them with $ \{\mu_{\text{S\&P500}, i}\}_{i=1}^{500} $. The range of both the simulated mean and standard deviation of returns closely matches that of the empirical quantities of stocks in the S\&P 500 index.

In addition, the variance of the factors accounts for 50.42\% of the total variance in our synthetic data, which corresponds to the population $R$-squared.

