\includegraphics[width=1.1\textwidth]{logistic_regression_manifold_new.png}
\caption{Regression manifold for bivariate logistic. }\label{1:f1}
\end{figure}

\begin{exm}[Non-stationary Husler-Reiss model]
An instance of the non-stationary Husler-Reiss regression manifold is shown in Fig. \ref{1:f2}. It arises from the non-stationary Husler-Reiss bivariate extreme value distribution function, which has the following form
\begin{equation}\label{eq23}
G(x_t,y_t)=\exp\left\{-x_t^{-1}\Phi\left(\lambda+\frac{1}{2\lambda}\log\frac{y_t}{x_t}\right)-y_t^{-1}\Phi\left(\lambda+\frac{1}{2\lambda}\log\frac{x_t}{y_t}\right)       \right\}, \; \;\; \; \;\; x_t,y_t>0,
\end{equation}
where $\Phi$ denotes the standard normal distribution function and $\lambda \in (0,\infty]$ is a parameter that modulates the dependency between extremes: as $\lambda\rightarrow 0$, the dependence becomes perfect, while in the limit as $\lambda\rightarrow\infty$, the dependency reaches complete independence. The collection of regression lines  $\mathbf{L}_{q}$ for this model lacks explicit forms and is derived using (\ref{eq19}) with
\begin{equation}\label{eq24}
\small
G_{Y_t|X_t}(y_t|x_t)=\left[\Phi\left(\lambda+\frac{1}{2\lambda}\log\frac{y_t}{x_t}\right)+\frac{1}{2\lambda}\phi\left(\lambda+\frac{1}{2\lambda}\log\frac{y_t}{x_t}\right)-\frac{x_t y_t^{-1}}{2\lambda}\phi\left(\lambda+\frac{1}{2\lambda}\log\frac{x_t}{y_t}\right)\right]\times G(x_t,y_t)\exp(1/x_t),
\end{equation}
for $x_t,y_t>0$ where $\phi$ is the standard Normal density function.
\end{exm}
