\centering
\includegraphics[width=7.5in,height=2.5in]{husler_reiss_regression_manifold.png}
\caption{Regression manifold for bivariate Husler-Reiss. }\label{1:f2}
\end{figure}
\begin{exm}[Non-stationary Coles-Tawn model]
An instance of the non-stationary Coles-Tawn regression manifold is shown in Fig. \ref{1:f3}. This idea is derived from the non-stationary Coles-Tawn bivariate extreme value distribution function, which is defined as follows
\begin{equation}\label{eq5}
G(x_t,y_t)=\exp[-x_t^{-1}\{1-Be(q;\alpha+1,\beta)\}-y_t^{-1}Be(q;\alpha,\beta+1)], \; \;\;  \; \;\; x_t,y_t>0,
\end{equation}
where $Be(q; a,b)$ represents the cumulative distribution function of a $Beta$ distribution with parameters $a,b>0$. In this context,
$q$ is defined as $q=\alpha y_t^{-1}/(\alpha y_t^{-1}+\beta x_t^{-1})$ with $\alpha, \beta>0$ serving as parameters that control the dependence between extremes. The scenario where $\alpha=\beta=0$  indicates complete independence, while the case of $\alpha=\beta\rightarrow\infty$ signifies perfect dependence. For fixed values of $\alpha(\beta)$, an increase in $\beta(\alpha)$  leads to a stronger dependence. The family of regression lines $\mathbf{L}_{q}$ for this model does not have a straightforward representation and is determined through calculations using (\ref{eq19}) for $x_t, y_t > 0$, with

\small
$$G_{Y_t|X_t}(y_t | x_t)= \left[ 1-Be(q;\alpha+1,\beta) +\frac{(\alpha+1)\beta}{\gamma}be(q;\alpha+2,\beta+1)-
\frac{x_t}{y_t}\frac{\alpha(\beta+1)}{\gamma}be(q;\alpha+1,\beta+2)\right]$$
\begin{equation}\label{eq27}
G(x_t,y_t)\exp(1/x_t).
\end{equation}

\end{exm}
